//! The MIR builder: typed HIR (the AST plus the checker's node tables) to
//! `Built` MIR, one body per monomorphic instance reachable from `main`
//! (redesign M1; `docs/spikes/mir-types.md` §4).
//!
//! What `Built` promises is in the spike's §3: every scope end, early exit,
//! assignment and temporary already carries its `Drop`, in the order core
//! semantics D1 to D5 require, and a `Drop` may name a place that was moved
//! on some path. Drop elaboration removes those.
//!
//! The builder never guesses. A construct it does not lower yet is reported
//! in [`Lowered::errors`] with its span, and the program is not run.

use rustc_hash::{FxHashMap, FxHashSet};

use crate::ast::{
    self, BinOp as AstBinOp, Block, CallArg, CompoundOp, EnsuresClause, Expr, ExprKind, Function,
    ImplItem, Item, LiteralPattern, ParLoop, ParsedInterpolationPart, Pattern, PatternKind,
    SelfParam, Stmt, StmtKind, UnaryOp,
};
use crate::def_path::DefPath;
use crate::def_table::ProgramDefs;
use crate::ids::{DefId, DefKind, NodeId};
use crate::node_res::Res;
use crate::ownership::OwnershipMode;
use crate::resolver::{ResolveResult, SpanKey, SymbolId};
use crate::token::Span;
use crate::ty::{AdtDef, IntrinsicKind, TyKind as HK, TypeName, VariantDef};
use crate::typechecker::types::{FloatSize, IntSize, Type, UIntSize, VariantTypeInfo};
use crate::typechecker::{ProjTraits, TypeCheckResult};
use crate::typed_hir::{Callee, ResolvedCall, TypedHir};

use super::build::BodyBuilder;
use super::interp;
use super::syntax::*;
use super::ty::{AdtId, FloatTy, Ty, TyInterner};

mod dyn_trait;

/// The value of an operator tree made only of unsuffixed integer literals,
/// when every step is in range. A lone literal is not a tree. A shift amount
/// must be below `bits`, the width of the type the tree takes: 64, or 128
/// for an `i128` or `u128` tree (B-2026-10-15-54).
fn fold_int(e: &Expr, bits: i128) -> Option<i128> {
    fold_int_in(e, bits, i128::MIN, i128::MAX)
}

/// [`fold_int`], where every step must also lie in `lo..=hi`, the range of
/// the type the tree takes: a step the unfolded code would trap on is not
/// folded, so it traps at run time (core semantics §10, B-2026-10-22-35).
/// A left shift does not trap; its bits past the type's width are dropped,
/// as at run time.
fn fold_int_in(e: &Expr, bits: i128, lo: i128, hi: i128) -> Option<i128> {
    let wrap = |v: i128| match hi.checked_sub(lo).and_then(|w| w.checked_add(1)) {
        Some(m) => v.wrapping_sub(lo).rem_euclid(m) + lo,
        None => v,
    };
    fn go(e: &Expr, bits: i128, lo: i128, hi: i128, wrap: &dyn Fn(i128) -> i128) -> Option<i128> {
        let v = match &e.kind {
            ExprKind::Integer(v, None) => Some(*v),
            ExprKind::Unary {
                op: UnaryOp::Neg,
                operand,
            } => go(operand, bits, lo, hi, wrap)?.checked_neg(),
            ExprKind::Binary { op, left, right } => {
                let (a, b) = (
                    go(left, bits, lo, hi, wrap)?,
                    go(right, bits, lo, hi, wrap)?,
                );
                match op {
                    AstBinOp::Add => a.checked_add(b),
                    AstBinOp::Sub => a.checked_sub(b),
                    AstBinOp::Mul => a.checked_mul(b),
                    AstBinOp::BitAnd => Some(a & b),
                    AstBinOp::BitOr => Some(a | b),
                    AstBinOp::BitXor => Some(a ^ b),
                    AstBinOp::Shl if (0..bits).contains(&b) => a.checked_shl(b as u32).map(wrap),
                    AstBinOp::Shr if (0..bits).contains(&b) => Some(a >> b),
                    _ => None,
                }
            }
            _ => None,
        }?;
        (lo..=hi).contains(&v).then_some(v)
    }
    match &e.kind {
        ExprKind::Binary { .. } => go(e, bits, lo, hi, &wrap),
        ExprKind::Unary { operand, .. } if !matches!(operand.kind, ExprKind::Integer(..)) => {
            go(e, bits, lo, hi, &wrap)
        }
        _ => None,
    }
}

/// The statement of `b` at the reduction span `r`, inside the arms of an
/// `if` or `match` of it too (`if c { s += x; }`), not in a nested loop or
/// closure, whose own lowering would see it again.
fn reduction_stmt(b: &Block, r: Span) -> Option<&Stmt> {
    let within = |s: Span| s.offset <= r.offset && r.offset + r.length <= s.offset + s.length;
    fn in_expr(e: &Expr, r: Span) -> Option<&Stmt> {
        match &e.kind {
            ExprKind::Block(b) | ExprKind::LabeledBlock { body: b, .. } => reduction_stmt(b, r),
            ExprKind::If {
                then_block,
                else_branch,
                ..
            }
            | ExprKind::IfLet {
                then_block,
                else_branch,
                ..
            } => reduction_stmt(then_block, r)
                .or_else(|| else_branch.as_deref().and_then(|e| in_expr(e, r))),
            ExprKind::Match { arms, .. } => arms.iter().find_map(|a| in_expr(&a.body, r)),
            // A reduction in an inner loop (kata 332's `sink`, summed over
            // each path's characters) is the outer loop's too.
            ExprKind::While { body, .. }
            | ExprKind::WhileLet { body, .. }
            | ExprKind::Loop { body, .. }
            | ExprKind::For { body, .. } => reduction_stmt(body, r),
            _ => None,
        }
    }
    if let Some(st) = b.stmts.iter().find(|s| within(s.span)) {
        return match &st.kind {
            // A push (`v.push(e);`) is the statement itself.
            StmtKind::Expr(e) => in_expr(e, r).or(Some(st)),
            _ => Some(st),
        };
    }
    b.final_expr.as_deref().and_then(|e| in_expr(e, r))
}

/// The operation of an auto-par reduction written as `op`.
fn reduction_op(op: &AstBinOp) -> Option<BinOp> {
    Some(match op {
        AstBinOp::Add => BinOp::Add,
        AstBinOp::Mul => BinOp::Mul,
        AstBinOp::BitAnd => BinOp::BitAnd,
        AstBinOp::BitOr => BinOp::BitOr,
        AstBinOp::BitXor => BinOp::BitXor,
        _ => return None,
    })
}

/// The binary operator an operator trait's method stands for: `add` of
/// `Add` is `+` (design.md § Operator traits).
fn operator_method(method: &str) -> Option<AstBinOp> {
    Some(match method {
        "add" => AstBinOp::Add,
        "sub" => AstBinOp::Sub,
        "mul" => AstBinOp::Mul,
        "div" => AstBinOp::Div,
        "rem" => AstBinOp::Mod,
        "eq" => AstBinOp::Eq,
        "ne" => AstBinOp::NotEq,
        "lt" => AstBinOp::Lt,
        "le" => AstBinOp::LtEq,
        "gt" => AstBinOp::Gt,
        "ge" => AstBinOp::GtEq,
        "bitand" => AstBinOp::BitAnd,
        "bitor" => AstBinOp::BitOr,
        "bitxor" => AstBinOp::BitXor,
        "shl" => AstBinOp::Shl,
        "shr" => AstBinOp::Shr,
        _ => return None,
    })
}

/// The values an integer type holds; the whole `i128` range for anything
/// else, and for `u128`, whose values past `i128::MAX` the fold carries as
/// their `i128` bit pattern, so it cannot check them.
fn int_range(k: HK) -> (i128, i128) {
    let signed = |bits: u32| (-(1i128 << (bits - 1)), (1i128 << (bits - 1)) - 1);
    match k {
        HK::Int(IntSize::I8) => signed(8),
        HK::Int(IntSize::I16) => signed(16),
        HK::Int(IntSize::I32) => signed(32),
        HK::Int(IntSize::I128) => (i128::MIN, i128::MAX),
        HK::Int(_) => signed(64),
        HK::UInt(UIntSize::U8) => (0, 255),
        HK::UInt(UIntSize::U16) => (0, 65_535),
        HK::UInt(UIntSize::U32) => (0, u32::MAX as i128),
        HK::UInt(UIntSize::U128) => (i128::MIN, i128::MAX),
        HK::UInt(_) => (0, u64::MAX as i128),
        _ => (i128::MIN, i128::MAX),
    }
}

/// An `if`/`if let` with an `else`, or a `match`: a value one of several
/// arms computes.
fn is_branching(e: &Expr) -> bool {
    matches!(
        e.kind,
        ExprKind::If {
            else_branch: Some(_),
            ..
        } | ExprKind::IfLet {
            else_branch: Some(_),
            ..
        } | ExprKind::Match { .. }
    )
}

/// The lowered program, or why it could not be lowered.
pub struct Lowered {
    pub program: interp::Program,
    pub tys: TyInterner,
    /// One line per construct the builder does not lower yet, with its
    /// position. Empty when every reachable body was built.
    pub errors: Vec<String>,
    /// The instances that take `ref self` or `mut ref self`.
    pub receivers: FxHashSet<String>,
    /// The receivers whose result borrows what the receiver's value
    /// borrows, not its place (§5.4; [`view_result`]).
    pub views: FxHashSet<String>,
    /// The views whose result borrows through their receiver's references
    /// ([`through_ref_fields`]).
    pub pointee_views: FxHashSet<String>,
    /// The closure bodies that return a closure. A returned closure owns
    /// its captures (core semantics §9.3), so a call's result borrows what
    /// the environment holds, never the closure value that lent it
    /// (B-2026-10-24-9).
    pub closure_results: FxHashSet<String>,
    /// For a program that binds a resource (core semantics §14), the
    /// effects of the program as built, before provider specialisation
    /// replaced its calls on resources: what `par_check` reports from.
    pub effects: Option<crate::mir::effects::EffectReport>,
    /// The loops this build ran as tasks under auto-par (M4 item 14), as
    /// `instance@line` of each `for`.
    pub auto_par_tasks: Vec<String>,
    /// The runs of statements this build ran as tasks under auto-par, as
    /// `instance@line` of each run's first statement.
    pub auto_par_groups: Vec<String>,
    /// The reductions of the loops in [`Self::auto_par_tasks`], as
    /// `instance@line (acc at line, ..)`, one line per site.
    pub auto_par_reductions: Vec<String>,
    /// Whether this is auto-par's recording build, whose bodies only the
    /// verdicts read.
    pub auto_par_record: bool,
    /// Each body's locals the ownership check proved frozen (design.md §
    /// Frozen handles), which `frozen::uncount` makes count nothing.
    pub frozen_locals: FxHashMap<String, crate::mir::frozen::FrozenLocals>,
    /// For a build that runs loops or statements as tasks, the program as
    /// `KARAC_AUTO_PAR=0` builds it. A run on one worker runs this one
    /// instead ([`Lowered::for_this_pool`]), and a native build carries
    /// both and picks at startup: on one worker the tasks only cost
    /// (B-2026-10-26-17), and an in-order copy of the program's functions
    /// beside the tasks does not run the in-order build's instructions,
    /// since LLVM optimises them in the other program's company
    /// (B-2026-10-28-1).
    pub in_order: Option<Box<Lowered>>,
}

impl Lowered {
    /// The program this process runs: the in-order one when the pool has
    /// one worker ([`Self::in_order`]).
    pub fn for_this_pool(self) -> Lowered {
        match self.in_order {
            Some(seq) if !interp::pool_has_workers() => *seq,
            _ => self,
        }
    }
}

/// The `let`s the ownership check's frozen walk admitted, by their
/// initializer's span: non-counting aliases of a frozen place
/// (`let k = n.kids[i];`, `let g = freeze root;`), and `Vec` locals whose
/// every element is one (`let mut q: Vec[Node] = Vec.new();`).
#[derive(Default, Clone)]
pub struct FrozenHints {
    pub aliases: FxHashSet<SpanKey>,
    pub containers: FxHashSet<SpanKey>,
}

/// What an `extern "C"` signature with a type no backend passes to C yet
/// reads as, in a "... is not lowered yet" error: only integers, `bool` and
/// raw pointers cross so far.
fn crossing(name: &str) -> String {
    format!(
        "a parameter or return type of the `extern \"C\"` function `{name}` other than an \
         integer, `bool` or raw pointer"
    )
}

/// Lower every instance reachable from `main`.
#[allow(clippy::too_many_arguments)]
pub fn lower_program<'a>(
    program: &'a ast::Program,
    source: &'a str,
    tc: &'a TypeCheckResult,
    defs: &ProgramDefs,
    res: &FxHashMap<NodeId, Res>,
    rr: &ResolveResult,
    hir: TypedHir,
    capture_modes: &FxHashMap<SpanKey, Vec<(String, OwnershipMode)>>,
) -> Lowered {
    lower_program_with_library(program, source, None, tc, defs, res, rr, hir, capture_modes)
}

/// [`lower_program`] of a program whose first `user_len` bytes of `source`
/// are the user's and the rest the appended library ([`library_source`]):
/// a type the user declares is the user's whatever its name.
#[allow(clippy::too_many_arguments)]
pub fn lower_program_with_library<'a>(
    program: &'a ast::Program,
    source: &'a str,
    user_len: Option<usize>,
    tc: &'a TypeCheckResult,
    defs: &ProgramDefs,
    res: &FxHashMap<NodeId, Res>,
    rr: &ResolveResult,
    hir: TypedHir,
    capture_modes: &FxHashMap<SpanKey, Vec<(String, OwnershipMode)>>,
) -> Lowered {
    lower_program_inner(
        program,
        source,
        user_len,
        tc,
        defs,
        res,
        rr,
        hir,
        capture_modes,
        &FrozenHints::default(),
        None,
        None,
        AutoPar::Off,
        None,
    )
}

/// [`lower_program_with_library`], with the bodies of the functions from
/// `signatures_only_from` on (the library's) left unlowered: each gets its
/// parameters and nothing else. `karac check`'s MIR checks look only at the
/// program's own bodies, and a call needs only its callee's signature
/// (B-2026-10-19-21).
#[allow(clippy::too_many_arguments)]
fn lower_program_inner<'a>(
    program: &'a ast::Program,
    source: &'a str,
    user_len: Option<usize>,
    tc: &'a TypeCheckResult,
    defs: &ProgramDefs,
    res: &FxHashMap<NodeId, Res>,
    rr: &ResolveResult,
    hir: TypedHir,
    capture_modes: &FxHashMap<SpanKey, Vec<(String, OwnershipMode)>>,
    frozen: &FrozenHints,
    signatures_only_from: Option<usize>,
    roots: Option<&[String]>,
    auto_par: AutoPar,
    cancel_at: Option<FxHashSet<String>>,
) -> Lowered {
    let user_types: FxHashSet<String> = match user_len {
        Some(n) => program
            .items
            .iter()
            .filter_map(|i| match i {
                Item::StructDef(s) if s.span.offset < n => Some(s.name.clone()),
                Item::EnumDef(e) if e.span.offset < n => Some(e.name.clone()),
                _ => None,
            })
            .collect(),
        None => FxHashSet::default(),
    };
    let TypedHir {
        tcx,
        node_types,
        calls,
        errors: hir_errors,
    } = hir;
    let defaults = trait_defaults(program, tc);
    let mut lcx = Lcx {
        tc,
        source,
        user_len,
        fn_field_effects: program
            .items
            .iter()
            .filter_map(|i| match i {
                Item::StructDef(s) => Some(s),
                _ => None,
            })
            .flat_map(|s| {
                s.fields.iter().filter_map(|f| {
                    Some(((s.name.clone(), f.name.clone()), declared_effects(&f.ty)?))
                })
            })
            .collect(),
        let_fn_effects: FxHashMap::default(),
        user_types,
        refined: program
            .items
            .iter()
            .filter_map(|i| match i {
                Item::DistinctType(d)
                    if d.generic_params
                        .as_ref()
                        .is_none_or(|g| g.params.is_empty()) =>
                {
                    Some((d.name.clone(), d.refinement.as_ref()?))
                }
                Item::TypeAlias(t)
                    if t.generic_params
                        .as_ref()
                        .is_none_or(|g| g.params.is_empty()) =>
                {
                    Some((t.name.clone(), t.refinement.as_ref()?))
                }
                _ => None,
            })
            .collect(),
        ref_bindings: &program.ref_binding_spans,
        mut_ref_bindings: &program.mut_ref_binding_spans,
        escaping_fns: &program.escaping_fn_types,
        defs,
        res,
        node_types,
        hir_errors: hir_errors.into_iter().collect(),
        calls,
        tys: TyInterner::from_tcx(tcx),
        binding_syms: rr
            .binding_nodes
            .iter()
            .map(|(&s, &n)| ((n, rr.symbol_table.get_symbol(s).name.clone()), s))
            .collect(),
        par_joins: par_joins(rr),
        unbound_vars: rr
            .symbol_table
            .all_symbols()
            .iter()
            .filter(|s| {
                matches!(s.kind, crate::resolver::SymbolKind::Variable { .. })
                    && !rr.binding_nodes.contains_key(&s.id)
            })
            .map(|s| ((s.name.clone(), s.span.offset, s.span.length), s.id))
            .collect(),
        fns: FxHashMap::default(),
        builtin_owns: FxHashMap::default(),
        builtin_mut_self: FxHashSet::default(),
        builtin_own_self: FxHashSet::default(),
        consts: FxHashMap::default(),
        resource_defaults: FxHashMap::default(),
        user_defaults: FxHashSet::default(),
        default_queue: Vec::new(),
        resource_bounds: FxHashMap::default(),
        trait_defs: FxHashMap::default(),
        trait_impl_fns: FxHashMap::default(),
        bound_resources: FxHashSet::default(),
        bindings: FxHashMap::default(),
        statics: FxHashMap::default(),
        static_queue: Vec::new(),
        signatures_only_from,
        comptime_eval: roots.is_some(),
        literal_statics: FxHashMap::default(),
        literal_queue: Vec::new(),
        eq_queue: Vec::new(),
        eq_queued: FxHashSet::default(),
        hash_scanned: FxHashSet::default(),
        hash_noted: FxHashSet::default(),
        key_eq_noted: FxHashSet::default(),
        self_tys: FxHashMap::default(),
        queue: Vec::new(),
        queued: FxHashSet::default(),
        program: interp::Program::default(),
        errors: Vec::new(),
        variants: FxHashMap::default(),
        generic_drops: FxHashMap::default(),
        registered: FxHashSet::default(),
        proj_adts: FxHashSet::default(),
        proj_instances: FxHashSet::default(),
        keep_param_projs: false,
        capture_modes,
        frozen: frozen.clone(),
        frozen_locals: FxHashMap::default(),
        next_closure: defs.table.len() as u32,
        closures: FxHashMap::default(),
        closure_exprs: FxHashMap::default(),
        par_task_exprs: FxHashMap::default(),
        isolating_task_exprs: FxHashMap::default(),
        par_for_task_exprs: FxHashMap::default(),
        stmt_chunk_exprs: FxHashMap::default(),
        counted_whiles: FxHashMap::default(),
        auto_par_wides: FxHashMap::default(),
        const_lets: FxHashMap::default(),
        next_synthetic_node: u32::MAX - 1,
        auto_par,
        next_synthetic_sym: usize::MAX - 1,
        auto_par_done: Vec::new(),
        auto_par_groups: Vec::new(),
        auto_par_reduced: Vec::new(),
        closure_queue: Vec::new(),
        fn_param_tys: FxHashMap::default(),
        own_self_trait_methods: FxHashSet::default(),
        extern_fns: FxHashMap::default(),
        cancel_at,
    };
    lcx.index_functions(program, &defaults);
    // Statics are initialized in declaration order, so they are numbered
    // in it.
    for item in &program.items {
        if let Item::ModuleBinding(b) = item {
            if let Some(d) = defs.lookup(0, &b.name) {
                lcx.static_of(d);
            }
        }
    }
    // Contracts are checked at run time; until the builder emits those
    // checks, a program with one is refused rather than run without them.
    for item in &program.items {
        if let Item::StructDef(sd) = item {
            if !sd.invariants.is_empty() || !sd.impl_invariants.is_empty() {
                lcx.errors.push(format!(
                    "{}: a type invariant is not lowered yet",
                    at(sd.span)
                ));
            }
        }
    }
    match roots {
        // A comptime evaluation's roots (B-2026-10-22-20): its wrapper
        // functions, and no `main`.
        Some(roots) => {
            for r in roots {
                match defs.lookup(0, r) {
                    Some(d) => {
                        lcx.instance(d, Vec::new());
                    }
                    None => lcx.errors.push(format!("no `{r}` function")),
                }
            }
        }
        None => match defs.lookup(0, "main") {
            Some(main) => {
                lcx.instance(main, Vec::new());
            }
            None => lcx.errors.push("no `main` function".into()),
        },
    }
    // The `#[panic_handler]` thunk is a root too: nothing calls it but the
    // backends, when a panic ends the process.
    if let Some(thunk) = defs.lookup(0, PANIC_THUNK) {
        lcx.instance(thunk, Vec::new());
    }
    let mut receivers = FxHashSet::default();
    let mut views = FxHashSet::default();
    let mut closure_results = FxHashSet::default();
    loop {
        if let Some((def, args, name)) = lcx.queue.pop() {
            let has_self = lcx.fns.get(&def).is_some_and(|i| i.f.self_param.is_some());
            let view = lcx.fns.get(&def).is_some_and(|i| {
                // The impl's parameters only: a method's own can be filled
                // from another argument (`pick[U](ref self, f: Fn(ref Self)
                // -> U)`), so its value may borrow the receiver's place.
                let params: Vec<&str> = i
                    .impl_generics
                    .iter()
                    .flat_map(|g| g.params.iter().map(|p| p.name.as_str()))
                    .collect();
                i.f.return_type
                    .as_ref()
                    .is_some_and(|t| view_result(t, &params))
            });
            lcx.lower_instance(def, &args, &name);
            // A receiver the body borrows, written or (D5) a bare `self`.
            let borrows = lcx.program.bodies.get(&name).is_some_and(|b| {
                b.arg_count > 0
                    && matches!(
                        lcx.tys.tcx().kind(b.locals[1].ty),
                        HK::Ref(_) | HK::MutRef(_)
                    )
            });
            if has_self && borrows {
                if view {
                    views.insert(name.clone());
                }
                receivers.insert(name.clone());
            }
        } else if let Some(job) = lcx.closure_queue.pop() {
            let name = job.name.clone();
            lcx.lower_closure(job);
            let returns_closure = lcx.program.bodies.get(&name).is_some_and(|b| {
                matches!(
                    lcx.tys.tcx().kind(b.locals[0].ty),
                    HK::Closure { .. } | HK::Fn { .. } | HK::FnDef { .. }
                )
            });
            if returns_closure {
                closure_results.insert(name);
            }
        } else if let Some((def, name)) = lcx.static_queue.pop() {
            lcx.lower_static(def, &name);
        } else if let Some((e, t, name)) = lcx.literal_queue.pop() {
            lcx.lower_literal_static(e, t, &name);
        } else if let Some((e, t, name)) = lcx.default_queue.pop() {
            lcx.lower_default_static(e, t, &name);
        } else if let Some((t, name)) = lcx.eq_queue.pop() {
            lcx.lower_derived_eq(t, &name);
        } else if !lcx.note_table_hashes() {
            break;
        }
    }
    let pointee_views: FxHashSet<String> = views
        .iter()
        .filter(|n| through_ref_fields(&lcx.program, &lcx.tys, &views, n))
        .cloned()
        .collect();
    lcx.program.transparent = observability_fns(program);
    Lowered {
        program: lcx.program,
        tys: lcx.tys,
        errors: lcx.errors,
        receivers,
        views,
        pointee_views,
        closure_results,
        effects: None,
        auto_par_tasks: lcx.auto_par_done,
        auto_par_groups: lcx.auto_par_groups,
        auto_par_reductions: lcx.auto_par_reduced,
        auto_par_record: matches!(lcx.auto_par, AutoPar::Record),
        frozen_locals: lcx.frozen_locals,
        in_order: None,
    }
}

/// The `Hasher` methods a table's hash glue calls on a user hasher's
/// state: `write`, `finish`, and the `write_<width>` the built-in types
/// feed through (collections.md § "What the built-in types feed").
const HASHER_METHODS: [&str; 12] = [
    "write",
    "finish",
    "write_u8",
    "write_u16",
    "write_u32",
    "write_u64",
    "write_usize",
    "write_i8",
    "write_i16",
    "write_i32",
    "write_i64",
    "write_isize",
];

/// Whether a method's result, of declared type `t`, can hold a reference
/// only through a type parameter of its impl (`params`) or an associated type
/// (`Self.Item`, `I.Item`): built from those, scalars, `String`, `Option`,
/// `Result`, tuples and arrays. Such a reference came from outside the
/// receiver, since a value cannot borrow itself, so the result borrows
/// what the receiver's value borrows (§5.4). A `ref` written in the type,
/// or a named type that may hold one, keeps the receiver's place.
fn view_result(t: &ast::TypeExpr, params: &[&str]) -> bool {
    match &t.kind {
        ast::TypeKind::Path(p) => {
            let args_ok = || {
                p.generic_args.as_ref().is_none_or(|g| {
                    g.iter().all(|a| match a {
                        ast::GenericArg::Type(t) => view_result(t, params),
                        _ => false,
                    })
                })
            };
            match p.segments.as_slice() {
                [base, _] => {
                    (base == "Self" || params.contains(&base.as_str())) && p.generic_args.is_none()
                }
                [n] if params.contains(&n.as_str()) => p.generic_args.is_none(),
                [n] if matches!(n.as_str(), "Option" | "Result") => args_ok(),
                [n] => {
                    p.generic_args.is_none()
                        && matches!(
                            n.as_str(),
                            "i8" | "i16"
                                | "i32"
                                | "i64"
                                | "i128"
                                | "isize"
                                | "u8"
                                | "u16"
                                | "u32"
                                | "u64"
                                | "u128"
                                | "usize"
                                | "f32"
                                | "f64"
                                | "bool"
                                | "char"
                                | "String"
                        )
                }
                _ => false,
            }
        }
        ast::TypeKind::Tuple(ts) => ts.iter().all(|t| view_result(t, params)),
        ast::TypeKind::Array { element, .. } => view_result(element, params),
        _ => false,
    }
}

/// Whether the view `name`'s result borrows only what the values its
/// receiver refers to hold (`ResultBorrows::ReceiverPointeeValue`): its
/// receiver's fields are each a reference or a scalar, every call it makes
/// is itself a view, and it copies no reference field out, so nothing it
/// returns can carry the receiver's references themselves.
/// `IterByRef.next` over a view iterator is one (B-2026-10-21-59); a
/// lending iterator, whose `next` is not a view, keeps its loan.
fn through_ref_fields(
    program: &interp::Program,
    tys: &TyInterner,
    views: &FxHashSet<String>,
    name: &str,
) -> bool {
    use crate::mir::syntax::{StatementKind, TerminatorKind};
    let Some(body) = program.bodies.get(name) else {
        return false;
    };
    let tcx = tys.tcx();
    let Some(recv) = body.locals.get(1).map(|l| l.ty) else {
        return false;
    };
    let (HK::Ref(st) | HK::MutRef(st)) = tcx.kind(recv) else {
        return false;
    };
    let Some((adt, _)) = tcx.adt_of(st) else {
        return false;
    };
    let Some(v) = adt.variants.first().filter(|_| !adt.is_enum) else {
        return false;
    };
    let fields_ok = (0..v.fields.len() as u32).all(|i| {
        tcx.field_ty(st, None, i).is_some_and(|t| {
            matches!(
                tcx.kind(t),
                HK::Ref(_)
                    | HK::MutRef(_)
                    | HK::Int(_)
                    | HK::UInt(_)
                    | HK::Float(_)
                    | HK::Bool
                    | HK::Char
            )
        })
    });
    if !fields_ok {
        return false;
    }
    let self_ref_field = |p: &Place| {
        p.local.index() == 1
            && p.projection.len() == 2
            && matches!(p.projection[0], ProjElem::Deref)
            && crate::mir::place_ty::place_ty(body, tys, p)
                .is_ok_and(|pt| matches!(tcx.kind(pt.ty), HK::Ref(_) | HK::MutRef(_)))
    };
    // A body with no `return` (a stub left where lowering failed) is no
    // evidence of what the method returns.
    let returns = body
        .blocks
        .iter()
        .any(|b| matches!(b.terminator.kind, TerminatorKind::Return));
    returns && body.blocks.iter().all(|b| {
        let copies = b.statements.iter().any(|s| match &s.kind {
            StatementKind::Assign(_, Rvalue::Use(Operand::Copy(p) | Operand::Move(p))) => {
                self_ref_field(p)
            }
            _ => false,
        });
        let calls_ok = match &b.terminator.kind {
            TerminatorKind::Call { func, .. } => matches!(
                func,
                Operand::Const(Const { kind: ConstKind::FnDef(c), .. }) if views.contains(&c.name)
            ),
            _ => true,
        };
        !copies && calls_ok
    })
}

/// Whether `t` is a reference to a struct whose fields are all references
/// (`IterByRef`): a library method on one keeps its body under `karac
/// check`, for `through_ref_fields` to read (B-2026-10-21-59).
fn refs_only_receiver(tys: &TyInterner, t: Ty) -> bool {
    let tcx = tys.tcx();
    let (HK::Ref(st) | HK::MutRef(st)) = tcx.kind(t) else {
        return false;
    };
    let Some((adt, _)) = tcx.adt_of(st) else {
        return false;
    };
    let Some(v) = adt.variants.first().filter(|_| !adt.is_enum) else {
        return false;
    };
    !v.fields.is_empty()
        && (0..v.fields.len() as u32).all(|i| {
            tcx.field_ty(st, None, i)
                .is_some_and(|t| matches!(tcx.kind(t), HK::Ref(_) | HK::MutRef(_)))
        })
}

/// The natives the builder calls by bare name rather than through a
/// definition.
const BUILDER_NATIVES: [&str; 11] = [
    "format",
    "format_spec",
    "panic_message",
    "contract_enter",
    "contract_exit",
    "error_trace_push",
    "error_trace_clear",
    "table_unkeyed",
    "dbg",
    "debug_string",
    // `std.time.sleep`'s (B-2026-10-27-29).
    "sleep_ms",
];

struct FnItem<'a> {
    f: &'a Function,
    /// The impl's target type and how many generic parameters the impl
    /// declares (they come first in the method's positional generics).
    impl_target: Option<DefId>,
    impl_params: usize,
    /// The primitive an impl is for (`impl Step for i64`), which has no
    /// definition to be `impl_target`.
    impl_prim: Option<Ty>,
    /// The library's `impl[T] Slice[T]`: its one parameter is the element,
    /// and `self` is the slice of it.
    impl_slice: bool,
    /// The impl's generic parameters, which come before the method's.
    impl_generics: Option<&'a ast::GenericParams>,
    /// The trait's arguments as the impl writes them (`Handler[i64]`).
    impl_trait_args: Option<&'a [ast::GenericArg]>,
    /// Where each impl parameter sits among the target's arguments, when
    /// that is not simply the leading ones in order: `impl[I, B] ... for
    /// MapIter[I, I.Item, B]` gives `[0, 2]`.
    impl_arg_pos: Option<Vec<usize>>,
    /// The impl block's span: with the method's own span, the key of the
    /// checker's per-function tables (a trait default method copied into
    /// several impls has the same span in each).
    impl_span: Option<SpanKey>,
    /// The checker's name for an impl for one instantiation of a generic
    /// type (`impl Bx[String]`) that shares a method name with a sibling
    /// impl, as `TypeCheckResult.method_impl_dispatch` names the winner.
    impl_dispatch: Option<String>,
    /// `#k` for the `k`th (k > 0) impl of a generic trait on one type
    /// (`impl From[S] for E` beside `impl From[T] for E`), which keeps
    /// its methods' bodies apart from the first impl's.
    impl_suffix: Option<String>,
    /// A trait's default method (`TraitDefault`): the trait. Its first
    /// argument is `Self`, a `dyn` type.
    impl_dyn: Option<DefId>,
}

impl FnItem<'_> {
    /// The impl's target's arguments, from the impl's own `args` in its
    /// declared order: `impl[T, I] .. for Tagged[I, T]` writes them
    /// swapped (B-2026-10-18-48). The arguments as given when they are not
    /// a reordering of all of the target's.
    fn target_args(&self, args: &[Ty]) -> Vec<Ty> {
        let Some(pos) = &self.impl_arg_pos else {
            return args.to_vec();
        };
        let mut out = vec![None; args.len()];
        for (&a, &k) in args.iter().zip(pos) {
            if let Some(slot) = out.get_mut(k) {
                *slot = Some(a);
            }
        }
        out.into_iter()
            .collect::<Option<Vec<_>>>()
            .unwrap_or_else(|| args.to_vec())
    }

    /// The impl's generic arguments, read off its target's arguments.
    fn impl_args(&self, targs: &[Ty]) -> Option<Vec<Ty>> {
        match &self.impl_arg_pos {
            Some(pos) => pos.iter().map(|&k| targs.get(k).copied()).collect(),
            None => targs.get(..self.impl_params).map(<[Ty]>::to_vec),
        }
    }
}

/// A trait's default method as a function of its own, called on a `dyn`
/// value (design.md § `dyn Trait`): a default that is in no slot (`map`,
/// `collect`) runs this body, instanced with `Self` the `dyn` type. Its
/// generics are `Self` and the trait's, then the method's, as the checker
/// placed the body's types.
struct TraitDefault {
    trait_name: String,
    generics: ast::GenericParams,
    f: Function,
}

/// The default methods with a receiver of each trait a `dyn` type the
/// program makes names, and of their supertraits.
fn trait_defaults(program: &ast::Program, tc: &TypeCheckResult) -> Vec<TraitDefault> {
    let traits: FxHashMap<&str, &ast::TraitDef> = program
        .items
        .iter()
        .filter_map(|i| match i {
            Item::TraitDef(t) => Some((t.name.as_str(), t)),
            _ => None,
        })
        .collect();
    let mut work: Vec<&str> = tc
        .node_dyn_coercions
        .values()
        .filter_map(|(_, target)| {
            let mut t = target;
            while let Type::Ref(inner) | Type::MutRef(inner) = t {
                t = inner;
            }
            match t {
                Type::Dyn { trait_name, .. } => Some(trait_name.as_str()),
                _ => None,
            }
        })
        .collect();
    let mut seen = FxHashSet::default();
    let mut out = Vec::new();
    while let Some(name) = work.pop() {
        if !seen.insert(name) {
            continue;
        }
        let Some(&t) = traits.get(name) else { continue };
        work.extend(
            t.supertraits
                .iter()
                .filter_map(|b| b.path.last().map(String::as_str)),
        );
        let own = t.generic_params.as_ref();
        let mut params = vec![ast::GenericParam {
            name: "Self".to_string(),
            bounds: Vec::new(),
            is_const: false,
            const_type: None,
            variance: ast::Variance::Invariant,
            variance_span: None,
            is_variadic_shape: false,
            default: None,
            span: t.span,
        }];
        params.extend(own.iter().flat_map(|g| g.params.iter().cloned()));
        let generics = ast::GenericParams {
            params,
            effect_params: Vec::new(),
            span: t.span,
        };
        for it in &t.items {
            let ast::TraitItem::Method(m) = it else {
                continue;
            };
            if m.body.is_none() || m.self_param.is_none() || m.is_dyn_dispatchable() {
                continue;
            }
            out.push(TraitDefault {
                trait_name: t.name.clone(),
                generics: generics.clone(),
                f: crate::desugar::trait_method_to_function(m, t.stdlib_origin),
            });
        }
    }
    out
}

/// Whether `b` is `impl[T] Slice[T]`, the library's slice methods.
fn is_slice_impl(b: &ast::ImplBlock) -> bool {
    let Some(g) = &b.generic_params else {
        return false;
    };
    let ast::TypeKind::Path(p) = &b.target_type.kind else {
        return false;
    };
    let one = |a: &ast::GenericArg| match a {
        ast::GenericArg::Type(t) => matches!(&t.kind, ast::TypeKind::Path(q)
            if q.generic_args.is_none() && q.segments == [g.params[0].name.clone()]),
        _ => false,
    };
    g.params.len() == 1
        && p.segments.last().is_some_and(|n| n == "Slice")
        && p.generic_args
            .as_deref()
            .is_some_and(|a| a.len() == 1 && one(&a[0]))
}

/// Where each of `b`'s generic parameters is written among its target's
/// arguments, or `None` when they are those arguments' first ones in
/// order (or are not each written bare, which nothing maps yet).
fn impl_arg_positions(b: &ast::ImplBlock) -> Option<Vec<usize>> {
    let params = &b.generic_params.as_ref()?.params;
    let ast::TypeKind::Path(p) = &b.target_type.kind else {
        return None;
    };
    let targs = p.generic_args.as_ref()?;
    let bare = |a: &ast::GenericArg| match a {
        ast::GenericArg::Type(t) => match &t.kind {
            ast::TypeKind::Path(q) if q.generic_args.is_none() && q.segments.len() == 1 => {
                Some(q.segments[0].clone())
            }
            _ => None,
        },
        _ => None,
    };
    let pos = params
        .iter()
        .map(|g| {
            targs
                .iter()
                .position(|a| bare(a).as_deref() == Some(g.name.as_str()))
        })
        .collect::<Option<Vec<_>>>()?;
    (!pos.iter().copied().eq(0..params.len())).then_some(pos)
}

struct Lcx<'a> {
    tc: &'a TypeCheckResult,
    /// Where the functions start whose bodies are not lowered, only their
    /// parameters ([`lower_program_inner`]).
    signatures_only_from: Option<usize>,
    /// A comptime evaluation (B-2026-10-22-20): a `comptime { .. }` block
    /// reached here runs as the block it is.
    comptime_eval: bool,
    /// The checked source text, for `dbg(e)`'s rendering of `e`.
    source: &'a str,
    /// How many leading bytes of `source` are the program's own, the rest
    /// being the appended library's; `None` when it is all the program's.
    user_len: Option<usize>,
    /// The struct fields whose function type declares an effect clause, as
    /// (struct, field): a call through one has those effects (core
    /// semantics §12, B-2026-10-27-2).
    fn_field_effects: FxHashMap<(String, String), Vec<DeclaredEffect>>,
    /// The `let` bindings whose written function type declares an effect
    /// clause, by symbol, so a closure that captures one finds it too
    /// (B-2026-10-27-8).
    let_fn_effects: FxHashMap<SymbolId, Vec<DeclaredEffect>>,
    /// The structs and enums the user's program declares, as opposed to
    /// the appended library's (`lower_program_with_library`).
    user_types: FxHashSet<String>,
    /// The `where` predicate of each refinement and distinct type that has
    /// one, which making a value of it checks.
    refined: FxHashMap<String, &'a Expr>,
    /// `ref name` pattern bindings, by the binding's span.
    ref_bindings: &'a FxHashSet<SpanKey>,
    /// `mut ref name` pattern bindings, by the binding's span.
    mut_ref_bindings: &'a FxHashSet<SpanKey>,
    /// The types of `escaping Fn(..)` parameters, by span.
    escaping_fns: &'a FxHashSet<SpanKey>,
    /// Which arguments of each `#[compiler_builtin]` method (by its type's
    /// name and its own) are declared `own`: the native keeps them.
    builtin_owns: FxHashMap<(String, String), Vec<bool>>,
    /// The library's `#[compiler_builtin]` methods declared `mut ref self`
    /// that return a borrow (`BufReader.fill_buf`'s view of the reader's
    /// buffer, B-2026-10-14-72), whose receiver is lent mutably so the
    /// result holds the reader. The others (`TaskGroup.spawn`) write
    /// through a shared borrow, as the library cells do.
    builtin_mut_self: FxHashSet<(String, String)>,
    /// The library's `#[compiler_builtin]` methods declared `own self`
    /// (`Pool.with_health_check`, B-2026-10-21-43): the receiver moves in.
    builtin_own_self: FxHashSet<(String, String)>,
    defs: &'a ProgramDefs,
    res: &'a FxHashMap<NodeId, Res>,
    node_types: FxHashMap<NodeId, Ty>,
    /// Why a node has no type or call entry, for the refusal that names it.
    hir_errors: FxHashMap<NodeId, crate::typed_hir::HirError>,
    calls: FxHashMap<NodeId, ResolvedCall>,
    tys: TyInterner,
    /// The symbol a pattern node binds under a name (a struct pattern's
    /// shorthand fields all bind through that pattern's node).
    binding_syms: FxHashMap<(NodeId, String), SymbolId>,
    /// A `par {}` branch's binding and the symbols its join re-defines
    /// it under in the enclosing scope (the tail and the code after the
    /// block read those).
    par_joins: FxHashMap<SymbolId, Vec<SymbolId>>,
    /// Variables the resolver defined with no binding pattern (an
    /// `ensures(result)` binding), by name and span.
    unbound_vars: FxHashMap<(String, usize, usize), SymbolId>,
    fns: FxHashMap<DefId, FnItem<'a>>,
    /// Module-level constants and immutable `let` bindings, by
    /// definition, with their initializers.
    consts: FxHashMap<DefId, &'a Expr>,
    /// The default provider of each program-rooted resource the program
    /// declares (`effect resource Env: EnvProvider = OsEnv {};`,
    /// core-semantics §14.7), by the resource's name.
    resource_defaults: FxHashMap<String, &'a Expr>,
    /// The resources whose default the program declares rather than the
    /// library (core semantics §14.14): their calls go through
    /// `providers::specialise` even where nothing overrides them.
    user_defaults: FxHashSet<String>,
    /// The initializers still to be built of the statics holding such
    /// defaults: the expression, its type and the body's name.
    default_queue: Vec<(&'a Expr, Ty, String)>,
    /// The provider trait bounds of each resource the program declares
    /// (`effect resource Db: Store;`, core semantics §14.1), by name.
    resource_bounds: FxHashMap<String, Vec<String>>,
    /// Every trait the program declares, by name.
    trait_defs: FxHashMap<String, &'a ast::TraitDef>,
    /// The methods of the first impl of each trait, which stand for the
    /// trait's own when its declaration is not in the program (the
    /// library's `EnvProvider` is the checker's, not the MIR library's).
    trait_impl_fns: FxHashMap<String, Vec<&'a ast::Function>>,
    /// The resources some `with_provider` or `providers` block binds: a
    /// call on one of them goes through its provider (core semantics
    /// §14.3), where a program-rooted resource no one binds keeps calling
    /// its default directly (§14.7).
    bound_resources: FxHashSet<String>,
    /// Every module `let` binding, by definition.
    bindings: FxHashMap<DefId, &'a ast::ModuleBinding>,
    /// The module bindings that live in a static: each one's index in
    /// `program.statics`, its type, and whether it is `let mut`.
    statics: FxHashMap<DefId, (u32, Ty, bool)>,
    /// Statics whose initializer body is still to be built.
    static_queue: Vec<(DefId, String)>,
    /// The statics holding a literal lent to a `ref T` slot (core
    /// semantics §5.3), by type and spelling.
    literal_statics: FxHashMap<(Ty, String), u32>,
    /// Literal statics whose initializer is still to be built.
    literal_queue: Vec<(&'a Expr, Ty, String)>,
    /// Derived `==` bodies to build, for types whose comparison reaches
    /// itself (`shared struct Node { next: Option[Node] }`).
    eq_queue: Vec<(Ty, String)>,
    eq_queued: FxHashSet<Ty>,
    /// The bodies [`Lcx::note_table_hashes`] has looked at.
    hash_scanned: FxHashSet<String>,
    /// The tables, by key type and hasher, [`Lcx::note_table_hash`] has
    /// looked at.
    hash_noted: FxHashSet<(Ty, Option<Ty>)>,
    /// The key types [`Lcx::note_key_eq`] has looked at.
    key_eq_noted: FxHashSet<Ty>,
    /// The receiver type a method of a non-generic impl was called with:
    /// its `self` type when the impl names a concrete instance of a
    /// generic type (`impl Joiner for Vec[String]`).
    self_tys: FxHashMap<DefId, Ty>,
    queue: Vec<(DefId, Vec<Ty>, String)>,
    queued: FxHashSet<String>,
    program: interp::Program,
    errors: Vec<String>,
    /// A variant's enum and its index there.
    variants: FxHashMap<DefId, (DefId, u32)>,
    /// ADTs whose definition (and `Drop` body) has been registered.
    registered: FxHashSet<DefId>,
    /// Generic ADTs with a field typed by a projection of a parameter
    /// (`prev: Option[I.Item]`), whose instances normalize it, and the
    /// instances done (B-2026-10-18-23).
    proj_adts: FxHashSet<DefId>,
    proj_instances: FxHashSet<Ty>,
    /// Registering an ADT's fields: a projection of a parameter stays
    /// one, to be normalized at each instance.
    keep_param_projs: bool,
    /// The `drop` method of each generic ADT with a `Drop` body, which is
    /// instantiated for each instance of the type.
    generic_drops: FxHashMap<DefId, DefId>,
    /// The ownership checker's capture modes, by the closure's span.
    capture_modes: &'a FxHashMap<SpanKey, Vec<(String, OwnershipMode)>>,
    /// The ownership checker's frozen `let`s.
    frozen: FrozenHints,
    /// The locals of each body lowered so far that those `let`s bind.
    frozen_locals: FxHashMap<String, crate::mir::frozen::FrozenLocals>,
    /// Closures get DefIds past the definition table's.
    next_closure: u32,
    /// Each closure's body name and how it takes its environment.
    closures: FxHashMap<DefId, (String, EnvMode)>,
    closure_exprs: FxHashMap<DefId, &'a Expr>,
    /// The closure each `par` branch runs as, by the branch's node.
    par_task_exprs: FxHashMap<NodeId, &'a Expr>,
    /// The closure an isolating `spawn` of a function value runs as, by
    /// the value's node.
    isolating_task_exprs: FxHashMap<NodeId, &'a Expr>,
    /// The closure `|| { body }` a `par for` iteration runs as, by body.
    par_for_task_exprs: FxHashMap<*const Block, &'a Expr>,
    /// The tuples a statement-run task evaluates ([`Builder::stmt_chunk`]),
    /// by the run's first statement and its length.
    stmt_chunk_exprs: FxHashMap<(*const Stmt, usize), &'a Expr>,
    /// Each `while`'s counting shape, by the loop's node, or `None` when
    /// it has none (see [`CountedWhile`]).
    counted_whiles: FxHashMap<NodeId, Option<CountedWhile<'a>>>,
    /// Each auto-par loop body's signed-sum sites, by the body (see
    /// [`AutoRed::wide`]).
    auto_par_wides: FxHashMap<*const Block, &'a [WideSum<'a>]>,
    /// A `let` without `mut` whose value is a literal, by its symbol: an
    /// auto-par task binds it to the constant rather than reading it
    /// through its environment, so the task's code folds it as the
    /// sequential loop's does.
    const_lets: FxHashMap<SymbolId, Const>,
    /// The next id for a node the builder makes up (counting down from
    /// the top, clear of the checker's ids).
    next_synthetic_node: u32,
    /// What this build does about automatic parallelism (M4 item 14).
    auto_par: AutoPar,
    /// The next symbol the builder makes up (counting down from the top,
    /// clear of the resolver's).
    next_synthetic_sym: usize,
    /// See [`Lowered::auto_par_tasks`].
    auto_par_done: Vec<String>,
    /// See [`Lowered::auto_par_groups`].
    auto_par_groups: Vec<String>,
    /// See [`Lowered::auto_par_reductions`].
    auto_par_reduced: Vec<String>,
    closure_queue: Vec<ClosureJob<'a>>,
    /// Instances whose function-typed parameters take a concrete closure
    /// or function type: by instance name, one entry per parameter.
    fn_param_tys: FxHashMap<String, Vec<Option<Ty>>>,
    /// The trait methods declared `own self`, by trait and method name: a
    /// generic call through one moves its receiver even into an impl that
    /// borrows it (core semantics §4.7).
    own_self_trait_methods: FxHashSet<(String, String)>,
    /// The functions declared in an `extern "C"` block (or as a lone
    /// `extern "C" fn`): their calls go to the native library.
    extern_fns: FxHashMap<DefId, &'a ast::ExternFunction>,
    /// In a program that cancels tasks (core-semantics §11.9), the
    /// functions that suspend: a call to one, or to a suspending native,
    /// gets a cancel exit ([`Bx::cancel_exit`]).
    cancel_at: Option<FxHashSet<String>>,
}

/// An element position in a sequence a slice pattern matches.
#[derive(Debug, Clone, Copy)]
enum SeqPos {
    /// The `i`th from the start.
    Start(u64),
    /// The `m`th from the end, counting the last as 1.
    End(u64),
}

/// How a closure's body takes its environment (core semantics §9).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EnvMode {
    Ref,
    Mut,
    /// A closure whose body moves a capture out: called once, by value.
    Value,
}

/// How one capture is held in the environment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CapMode {
    /// Moved or copied in.
    Value,
    Ref,
    Mut,
}

struct ClosureJob<'a> {
    def: DefId,
    name: String,
    expr: &'a Expr,
    /// The enclosing instance's type arguments.
    args: Vec<Ty>,
    /// Captured symbol, how, and the environment field's type.
    caps: Vec<(SymbolId, CapMode, Ty)>,
    /// For each capture, the field of the symbol's struct it borrows when
    /// the closure captures fields apart (core semantics §9.1).
    fields: Vec<Option<String>>,
    /// For each capture, whether the binding is itself a reference: the
    /// field holds that reference (a borrow of a borrow is the borrow), so
    /// the body names the field rather than what it points to.
    lent: Vec<bool>,
    env: EnvMode,
    ty: Ty,
    /// Its parameters borrow what the caller passes: a closure handed to
    /// a library call, which lends it elements in place.
    ref_params: bool,
    /// It returns its body's place by reference: a sort key that names a
    /// part of the element (`|p| p.name`), which the sort only compares.
    ref_key: bool,
    /// A `par` branch run as a task: the task's return type, and the
    /// variant its body's value is wrapped in, when the enclosing function
    /// returns a `Result` or `Option` (see `par_tasks`).
    ret: Option<(Ty, Option<u32>)>,
    /// A `par` branch's task that may leave early: the enclosing
    /// function's return type, and the variant of the task's result its
    /// `return` and `?` carry that function's value in (see `par_tasks`).
    exit: Option<(Ty, u32)>,
    /// It returns this capture's value after its body runs (see
    /// `Bx::closure_ret_capture`).
    ret_capture: Option<SymbolId>,
    /// It is an auto-par task: in place of its body it runs these of a
    /// loop's iterations (M4 item 14).
    chunk: Option<ChunkJob<'a>>,
    /// The function the closure is written in, whose type parameters its
    /// body names (`|| T.zero()`).
    outer: DefId,
}

/// A method of a resource's bound (core semantics §14.2).
struct BoundMethod<'a> {
    name: &'a str,
    /// The trait it comes from.
    bound: String,
    self_param: Option<ast::SelfParam>,
    params: &'a [ast::Param],
    /// It has a default body in the trait.
    has_default: bool,
}

/// A variant as the checker records it: its name and named field types.
type CheckedVariant = (String, Vec<(String, Type)>);

/// An integer constant re-typed to `t` (the checker records an unsuffixed
/// literal as `i64` whatever the other operand is); any other operand as
/// it is.
fn retype_const(o: Operand, t: Ty) -> Operand {
    match o {
        Operand::Const(Const {
            kind: ConstKind::Scalar(v),
            ..
        }) => Operand::Const(Const {
            ty: t,
            kind: ConstKind::Scalar(v),
        }),
        o => o,
    }
}

/// The resources a `with_provider[R](..)` or a `providers { R => .. }`
/// block anywhere in `program` binds (core semantics §14.4, §14.8).
fn bound_resources(program: &ast::Program) -> FxHashSet<String> {
    let mut out = FxHashSet::default();
    let mut scan = |b: &Block| {
        crate::span_visitor::for_each_expr_in_block(b, &mut |e: &Expr| match &e.kind {
            ExprKind::Call { callee, .. } => {
                if let Some(r) = with_provider_resource(callee) {
                    out.insert(r.to_string());
                }
            }
            ExprKind::Providers { bindings, .. } => {
                out.extend(bindings.iter().map(|b| b.resource.clone()));
            }
            _ => {}
        });
    };
    for item in &program.items {
        match item {
            Item::Function(f) => scan(&f.body),
            Item::ImplBlock(b) => {
                for it in &b.items {
                    if let ImplItem::Method(f) = it {
                        scan(&f.body);
                    }
                }
            }
            _ => {}
        }
    }
    out
}

/// `R` when `callee` is `with_provider[R]`.
fn with_provider_resource(callee: &Expr) -> Option<&str> {
    let ExprKind::Index { object, index } = &callee.kind else {
        return None;
    };
    let named = match &object.kind {
        ExprKind::Identifier(n) => n == "with_provider",
        ExprKind::Path { segments, .. } => segments.as_slice() == ["with_provider"],
        _ => false,
    };
    if !named {
        return None;
    }
    match &index.kind {
        ExprKind::Identifier(n) => Some(n),
        ExprKind::Path { segments, .. } => segments.last().map(String::as_str),
        _ => None,
    }
}

/// D5's bare-parameter borrow (core semantics §8): on, with `KARAC_D5=0`
/// to take bare parameters by value as before the migration to `own T`.
fn d5_params() -> bool {
    #[cfg(test)]
    if let Some(on) = tests::D5.with(|c| c.get()) {
        return on;
    }
    crate::d5_params::on()
}

/// A span's line and column, after the library module it lies in when it
/// lies in a gated one (`std.path:13:20`, B-2026-10-15-107).
fn at(span: Span) -> String {
    match crate::prelude::gated_module_at(span.offset) {
        Some((path, _)) => format!("{}:{}:{}", path.join("."), span.line, span.column),
        None => format!("{}:{}", span.line, span.column),
    }
}

/// A type error stopping the pipeline, at its line and column as the build
/// stage's errors are (B-2026-10-14-46).
fn typecheck_error(e: &crate::typechecker::TypeError) -> String {
    if e.span.line == 0 {
        return format!("typecheck: {}", e.message);
    }
    format!("typecheck: {}: {}", at(e.span), e.message)
}

impl<'a> Lcx<'a> {
    /// A symbol no binding has, for a value the builder captures itself
    /// (an auto-par task's bounds).
    fn synthetic_sym(&mut self) -> SymbolId {
        self.next_synthetic_sym -= 1;
        SymbolId(self.next_synthetic_sym + 1)
    }

    // ── items ───────────────────────────────────────────────────────

    /// Map each function and method in the AST to its DefId. An impl's
    /// DefId comes from the definition table, which numbered the program's
    /// impl blocks in item order after the stdlib's: a program's
    /// `impl Option[T]` is `impl#1` when the stdlib already has one.
    fn index_functions(&mut self, program: &'a ast::Program, defaults: &'a [TraitDefault]) {
        for d in defaults {
            let Some(tr) = self.defs.lookup(0, &d.trait_name) else {
                continue;
            };
            let mut path = self.defs.table.get(tr).path.segments.clone();
            path.push(d.f.name.clone());
            let Some(m) = self.defs.table.lookup(&DefPath::new(path)) else {
                continue;
            };
            self.fns.insert(
                m,
                FnItem {
                    f: &d.f,
                    impl_target: None,
                    impl_params: d.generics.params.len(),
                    impl_prim: None,
                    impl_slice: false,
                    impl_generics: Some(&d.generics),
                    impl_trait_args: None,
                    impl_arg_pos: None,
                    impl_span: None,
                    impl_dispatch: None,
                    impl_suffix: None,
                    impl_dyn: Some(tr),
                },
            );
        }
        let baked = crate::prelude::STDLIB_PROGRAMS
            .iter()
            .map(|(_, p)| p)
            .chain(crate::prelude::GATED_STDLIB_PROGRAMS.iter().map(|(_, p)| p));
        for p in baked {
            self.note_builtin_owns(p);
        }
        self.note_builtin_owns(program);
        let mut impl_ids = self.defs.module_impls.first().into_iter().flatten();
        let dispatch_names = crate::impl_dispatch::collect_impl_dispatch_names(program);
        self.bound_resources = bound_resources(program);
        // Each inherent method by its type and name, and each trait impl's
        // method with its trait: a trait's method named like an inherent
        // one of the same type is named apart (B-2026-10-27-10).
        let mut inherent = FxHashSet::default();
        let mut trait_methods = Vec::new();
        for item in &program.items {
            let externs: Vec<&ast::ExternFunction> = match item {
                // A `host fn` is called the same way: its host provides the
                // body (design.md § Host Functions).
                Item::ExternFunction(e) if e.abi == "C" || e.abi == "host" => vec![e],
                Item::ExternBlock(b) if b.abi == "C" => b
                    .items
                    .iter()
                    .filter_map(|i| match i {
                        ast::ExternItem::Function(f) => Some(&**f),
                        ast::ExternItem::OpaqueType(_) => None,
                    })
                    .collect(),
                _ => Vec::new(),
            };
            for e in externs {
                if let Some(d) = self.defs.lookup(0, &e.name) {
                    self.extern_fns.insert(d, e);
                }
            }
            match item {
                Item::Function(f) => {
                    // An appended library's `#[compiler_builtin]` function
                    // (`mark_library_builtins`) is the interpreter's.
                    if f.stdlib_origin && f.attributes.iter().any(|a| a.is_bare("compiler_builtin"))
                    {
                        continue;
                    }
                    if let Some(d) = self.defs.lookup(0, &f.name) {
                        self.fns.insert(
                            d,
                            FnItem {
                                f,
                                impl_target: None,
                                impl_params: 0,
                                impl_prim: None,
                                impl_slice: false,
                                impl_generics: None,
                                impl_trait_args: None,
                                impl_arg_pos: None,
                                impl_span: None,
                                impl_dispatch: None,
                                impl_suffix: None,
                                impl_dyn: None,
                            },
                        );
                    }
                }
                Item::ConstDecl(c) => {
                    if let Some(d) = self.defs.lookup(0, &c.name) {
                        self.consts.insert(d, &c.value);
                    }
                }
                Item::EffectResource(r) => {
                    if let Some(d) = &r.default {
                        self.resource_defaults.insert(r.name.clone(), d);
                        if r.span.offset < program.library_start.unwrap_or(usize::MAX) {
                            self.user_defaults.insert(r.name.clone());
                        }
                    }
                    self.resource_bounds.insert(
                        r.name.clone(),
                        r.provider_bounds.iter().map(|b| b.name.clone()).collect(),
                    );
                }
                Item::TraitDef(t) => {
                    self.trait_defs.insert(t.name.clone(), t);
                    for it in &t.items {
                        if let ast::TraitItem::Method(m) = it {
                            if m.self_is_own {
                                self.own_self_trait_methods
                                    .insert((t.name.clone(), m.name.clone()));
                            }
                        }
                    }
                }
                // An immutable module `let` is evaluated where it is used,
                // like a constant, unless it lives in a static
                // (`static_of`).
                Item::ModuleBinding(b) => {
                    if let Some(d) = self.defs.lookup(0, &b.name) {
                        self.bindings.insert(d, b);
                        if !b.is_mut {
                            self.consts.insert(d, &b.value);
                        }
                    }
                }
                Item::ImplBlock(b) => {
                    if let Some(t) = b.trait_name.as_ref().and_then(|t| t.segments.last()) {
                        self.trait_impl_fns.entry(t.clone()).or_insert_with(|| {
                            b.items
                                .iter()
                                .filter_map(|it| match it {
                                    ImplItem::Method(f) => Some(&**f),
                                    _ => None,
                                })
                                .collect()
                        });
                    }
                    let Some(&impl_id) = impl_ids.next() else {
                        continue;
                    };
                    let target = self.defs.impls.get(&impl_id).and_then(|i| i.target);
                    let prim = match (&b.target_type.kind, target) {
                        (ast::TypeKind::Path(p), None) if b.generic_params.is_none() => {
                            p.segments.last().and_then(|n| self.primitive(n))
                        }
                        _ => None,
                    };
                    // A target with no definition of its own (`impl Reads
                    // for Array[i64, 3]`) is the type its methods' `self`
                    // was checked at.
                    let prim = prim.or_else(|| {
                        if target.is_some() || b.generic_params.is_some() {
                            return None;
                        }
                        let impl_span = SpanKey::from_span(&b.span);
                        b.items.iter().find_map(|it| {
                            let ImplItem::Method(f) = it else { return None };
                            let key = (Some(impl_span), SpanKey::from_span(&f.span));
                            let (ty, _) = self.tc.fn_self_types.get(&key)?;
                            let hir = self.lower_legacy(ty, &[], None).ok()?;
                            self.mir_ty(hir, &[]).ok()
                        })
                    });
                    let slice = target.is_none() && prim.is_none() && is_slice_impl(b);
                    // A blanket trait impl over its own parameter (`impl[I:
                    // Iterator] IntoIterator for I`): its methods are
                    // instanced at a receiver (`blanket_method`).
                    let blanket = target.is_none()
                        && b.trait_name.is_some()
                        && matches!(
                            (&b.target_type.kind, &b.generic_params),
                            (ast::TypeKind::Path(p), Some(g))
                                if p.segments.len() == 1
                                    && g.params.iter().any(|q| q.name == p.segments[0])
                        );
                    if target.is_none() && prim.is_none() && !slice && !blanket {
                        continue;
                    }
                    let impl_dispatch = dispatch_names
                        .get(&SpanKey::from_span(&b.target_type.span))
                        .cloned();
                    let impl_path = self.defs.table.get(impl_id).path.segments.clone();
                    let impl_suffix = b
                        .trait_name
                        .as_ref()
                        .filter(|t| t.generic_args.is_some())
                        .and(impl_path.last())
                        .and_then(|l| l.rsplit_once('#'))
                        .filter(|(_, k)| *k != "0")
                        .map(|(_, k)| format!("#{k}"));
                    let impl_params = b.generic_params.as_ref().map_or(0, |g| g.params.len());
                    let impl_arg_pos = impl_arg_positions(b);
                    for it in &b.items {
                        let ImplItem::Method(f) = it else { continue };
                        // A `#[compiler_builtin]` method's body is a
                        // placeholder: a call is the interpreter's.
                        if f.attributes.iter().any(|a| a.is_bare("compiler_builtin")) {
                            continue;
                        }
                        let mut p = impl_path.clone();
                        p.push(f.name.clone());
                        if let Some(d) = self.defs.table.lookup(&DefPath::new(p)) {
                            if let Some(t) = prim {
                                self.self_tys.insert(d, t);
                            }
                            self.fns.insert(
                                d,
                                FnItem {
                                    f,
                                    impl_target: target,
                                    impl_params,
                                    impl_prim: prim,
                                    impl_slice: slice,
                                    impl_generics: b.generic_params.as_ref(),
                                    impl_trait_args: b
                                        .trait_name
                                        .as_ref()
                                        .and_then(|t| t.generic_args.as_deref()),
                                    impl_arg_pos: impl_arg_pos.clone(),
                                    impl_span: Some(SpanKey::from_span(&b.span)),
                                    impl_dispatch: impl_dispatch.clone(),
                                    impl_suffix: impl_suffix.clone(),
                                    impl_dyn: None,
                                },
                            );
                            let key = (target, prim, slice, impl_dispatch.clone(), &f.name);
                            match b.trait_name.as_ref().and_then(|t| t.segments.last()) {
                                Some(tr) => trait_methods.push((d, key, tr)),
                                None => {
                                    inherent.insert(key);
                                }
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        for (d, key, tr) in trait_methods {
            if inherent.contains(&key) {
                if let Some(item) = self.fns.get_mut(&d) {
                    let k = item.impl_suffix.get_or_insert_with(String::new);
                    k.push('#');
                    k.push_str(tr);
                }
            }
        }
    }

    /// The scalar a primitive type name spells, for an impl on it.
    fn primitive(&self, name: &str) -> Option<Ty> {
        let kind = match name {
            "i8" => HK::Int(IntSize::I8),
            "i16" => HK::Int(IntSize::I16),
            "i32" => HK::Int(IntSize::I32),
            "i64" => HK::Int(IntSize::I64),
            "i128" => HK::Int(IntSize::I128),
            "isize" => HK::Int(IntSize::Isize),
            "u8" => HK::UInt(UIntSize::U8),
            "u16" => HK::UInt(UIntSize::U16),
            "u32" => HK::UInt(UIntSize::U32),
            "u64" => HK::UInt(UIntSize::U64),
            "u128" => HK::UInt(UIntSize::U128),
            "usize" => HK::UInt(UIntSize::Usize),
            "f32" => HK::Float(FloatSize::F32),
            "f64" => HK::Float(FloatSize::F64),
            "bool" => HK::Bool,
            "char" => HK::Char,
            "Never" => HK::Never,
            "String" => HK::Str,
            _ => return None,
        };
        Some(self.tys.tcx().intern(kind))
    }

    /// The type an `extern "C"` signature spells: an integer, `bool`, `()`,
    /// or a raw pointer, whose pointee is `()` when it is anything else (a
    /// foreign type). `None` for anything else, a float or an aggregate,
    /// which no backend passes to C yet.
    fn extern_ty(&self, t: &ast::TypeExpr) -> Option<Ty> {
        match &t.kind {
            ast::TypeKind::Path(p) if p.generic_args.is_none() => {
                let [name] = p.segments.as_slice() else {
                    return None;
                };
                self.primitive(name).filter(|&t| {
                    matches!(self.tys.tcx().kind(t), HK::Int(_) | HK::UInt(_) | HK::Bool)
                })
            }
            ast::TypeKind::Tuple(ts) if ts.is_empty() => Some(self.tys.tcx().intern(HK::Unit)),
            ast::TypeKind::Pointer { is_mut, inner } => {
                let unit = self.tys.tcx().intern(HK::Unit);
                let pointee = self.extern_ty(inner).unwrap_or(unit);
                Some(self.tys.tcx().intern(HK::RawPtr {
                    mutable: *is_mut,
                    pointee,
                }))
            }
            _ => None,
        }
    }

    /// Record which arguments the library's `#[compiler_builtin]` methods
    /// declare `own`.
    fn note_builtin_owns(&mut self, program: &ast::Program) {
        for item in &program.items {
            let Item::ImplBlock(b) = item else { continue };
            let ast::TypeKind::Path(tp) = &b.target_type.kind else {
                continue;
            };
            let Some(head) = tp.segments.last() else {
                continue;
            };
            for it in &b.items {
                let ImplItem::Method(f) = it else { continue };
                let builtin = f.attributes.iter().any(|a| a.is_bare("compiler_builtin"));
                if builtin
                    && f.self_param == Some(ast::SelfParam::MutRef)
                    && f.return_type.as_ref().is_some_and(type_expr_borrows)
                {
                    self.builtin_mut_self.insert((head.clone(), f.name.clone()));
                }
                if builtin && f.self_is_own {
                    self.builtin_own_self.insert((head.clone(), f.name.clone()));
                }
                if builtin && f.params.iter().any(|p| p.is_own) {
                    self.builtin_owns.insert(
                        (head.clone(), f.name.clone()),
                        f.params.iter().map(|p| p.is_own).collect(),
                    );
                }
            }
        }
    }

    /// The method `d` resolves to, or the same method of another impl of
    /// the same trait on the same type that has a body here. The baked
    /// stdlib's impls are not lowered; a library source re-states one in
    /// Kāra (`impl Display for AllocError` is the baked `impl Display#0`
    /// and the appended source's `impl Display#1`), and calls resolved to
    /// the baked one run the source one.
    fn lowered_def(&self, d: DefId) -> Option<DefId> {
        if self.fns.contains_key(&d) {
            return Some(d);
        }
        let segs = &self.defs.table.get(d).path.segments;
        let n = segs.len();
        if n < 2 {
            return None;
        }
        let (label, _) = segs[n - 2].rsplit_once('#')?;
        if !label.starts_with("impl") {
            return None;
        }
        let mut path = segs.clone();
        for k in 0..8 {
            path[n - 2] = format!("{label}#{k}");
            if let Some(t) = self.defs.table.lookup(&DefPath::new(path.clone())) {
                if self.fns.contains_key(&t) {
                    return Some(t);
                }
            }
        }
        None
    }

    /// The type whose impl defines `d` (`Command` for `Command.new`).
    fn def_owner(&self, d: DefId) -> Option<String> {
        let segs = &self.defs.table.get(d).path.segments;
        let n = segs.len();
        (n >= 3 && segs[n - 2].starts_with("impl")).then(|| segs[n - 3].clone())
    }

    /// The library's `f64_wrapper_from` for `F64.from` (and `F32`'s): the
    /// constructor has no body of its own to name as a value.
    fn wrapper_from(&self, d: DefId) -> Option<DefId> {
        if self.def_name(d) != "from" {
            return None;
        }
        let wrapper = match self.def_owner(d)?.as_str() {
            "F64" => "f64_wrapper_from",
            "F32" => "f32_wrapper_from",
            _ => return None,
        };
        self.defs.lookup(0, wrapper)
    }

    /// Whether `d` is a method of a blanket trait impl over its own
    /// parameter (`impl[I: Iterator] IntoIterator for I`), whose path is
    /// `["<builtin>", "I", "impl IntoIterator#0", method]`.
    fn is_blanket_fn(&self, d: DefId) -> bool {
        let Some(i) = self.fns.get(&d) else {
            return false;
        };
        let Some([p]) = i.impl_generics.map(|g| g.params.as_slice()) else {
            return false;
        };
        let path = &self.defs.table.get(d).path.segments;
        let n = path.len();
        i.impl_target.is_none()
            && i.impl_prim.is_none()
            && n == 4
            && path[0] == "<builtin>"
            && path[1] == p.name
            && path[2].starts_with("impl ")
    }

    fn def_name(&self, d: DefId) -> String {
        self.defs
            .table
            .get(d)
            .path
            .segments
            .last()
            .cloned()
            .unwrap_or_default()
    }

    /// Queue an instance of `def[args]` whose function-typed parameters take
    /// the given closure or function types, and return its name.
    fn instance_with_fns(&mut self, def: DefId, args: Vec<Ty>, fns: Vec<Option<Ty>>) -> String {
        let shown: Vec<String> = fns.iter().flatten().map(|&t| self.tys.display(t)).collect();
        let name = format!("{}{{{}}}", self.instance_name(def, &args), shown.join(", "));
        if self.queued.insert(name.clone()) {
            self.fn_param_tys.insert(name.clone(), fns);
            self.queue.push((def, args, name.clone()));
        }
        name
    }

    /// Method `method` of the first `impl <tr> for t`, with its instance
    /// arguments (the impl's, read off `t`'s).
    fn trait_method_of(&self, t: Ty, tr: &str, method: &str) -> Option<(DefId, Vec<Ty>)> {
        let (adt, args) = self.tys.tcx().adt_of(t)?;
        let mut path = self.defs.table.get(adt.def).path.segments.clone();
        path.push(format!("impl {tr}#0"));
        path.push(method.to_string());
        let d = self.defs.table.lookup(&DefPath::new(path))?;
        let d = self.lowered_def(d)?;
        let item = self.fns.get(&d)?;
        Some((d, item.impl_args(&args)?))
    }

    /// Record and queue what each hashed table the bodies lowered so far
    /// use needs to hash its keys by Kāra code ([`interp::TableHash`]) and
    /// to compare them ([`interp::Program::key_eqs`]). Whether anything new
    /// was queued.
    fn note_table_hashes(&mut self) -> bool {
        let fresh: Vec<String> = self
            .program
            .bodies
            .keys()
            .filter(|n| !self.hash_scanned.contains(*n))
            .cloned()
            .collect();
        let before = self.queue.len();
        for name in fresh {
            self.hash_scanned.insert(name.clone());
            let tys: Vec<Ty> = self.program.bodies[&name]
                .locals
                .iter()
                .map(|l| l.ty)
                .collect();
            for t in tys {
                self.note_table_hash(t);
            }
        }
        self.queue.len() > before || !self.eq_queue.is_empty()
    }

    /// Record how a table of type `t` hashes its keys when that runs Kāra
    /// code: through a user `BuildHasher` it names, or, for a native
    /// hasher, through the key's own `Hash` impls feeding a `TableKeyBytes`
    /// (collections.md § Hashing).
    fn note_table_hash(&mut self, mut t: Ty) {
        while let HK::Ref(i) | HK::MutRef(i) = self.tys.tcx().kind(t) {
            t = i;
        }
        let HK::Intrinsic { kind, args } = self.tys.tcx().kind(t) else {
            return;
        };
        if !matches!(kind, IntrinsicKind::Map | IntrinsicKind::Set) {
            return;
        }
        let Some(&key) = self.tys.tcx().list(args).first() else {
            return;
        };
        self.note_key_eq(key);
        let h = self.tys.hasher(t);
        if !self.hash_noted.insert((key, h)) {
            return;
        }
        let native = match h {
            None => Some("karac_hash_bytes"),
            Some(h) if self.tys.display(h) == "FxBuildHasher" => Some("karac_hash_bytes_fx"),
            Some(_) => None,
        };
        let (build_def, bargs) = match h {
            Some(h) if native.is_none() => match self.trait_method_of(h, "BuildHasher", "build") {
                Some(b) => b,
                None => return,
            },
            _ => match self
                .defs
                .lookup(0, "table_key_bytes")
                .and_then(|d| self.lowered_def(d))
            {
                Some(d) => (d, Vec::new()),
                None => return,
            },
        };
        let Ok(state) = self.fn_return(build_def, &bargs) else {
            return;
        };
        // The key's parts with their own `Hash`, which feed themselves.
        let mut own = std::collections::BTreeMap::new();
        let mut seen = FxHashSet::default();
        let mut work = vec![key];
        while let Some(t) = work.pop() {
            if !seen.insert(t) {
                continue;
            }
            let tcx = self.tys.tcx();
            match tcx.kind(t) {
                HK::Ref(x) | HK::MutRef(x) => work.push(x),
                HK::Tuple(l) => work.extend(tcx.list(l)),
                HK::Array { elem, .. } | HK::Slice { elem, .. } => work.push(elem),
                HK::Intrinsic { args, .. } => work.extend(tcx.list(args)),
                HK::Adt { args, .. } | HK::Shared { args, .. } => {
                    if let Some((d, mut a)) = self.trait_method_of(t, "Hash", "hash") {
                        a.push(state);
                        own.insert(t, self.instance(d, a));
                        continue;
                    }
                    let tcx = self.tys.tcx();
                    work.extend(tcx.list(args));
                    if let Some((adt, _)) = tcx.adt_of(t) {
                        for (k, v) in adt.variants.iter().enumerate() {
                            let variant = adt.is_enum.then_some(k as u32);
                            for i in 0..v.fields.len() {
                                work.extend(tcx.field_ty(t, variant, i as u32));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        // A native hasher over a key with no `Hash` of its own runs no
        // Kāra code: its glue hashes the key's parts itself.
        if native.is_some() && own.is_empty() {
            return;
        }
        let build = self.instance(build_def, bargs);
        let mut methods = std::collections::BTreeMap::new();
        for m in HASHER_METHODS {
            if let Some((d, a)) = self.trait_method_of(state, "Hasher", m) {
                methods.insert(m.to_string(), self.instance(d, a));
            }
        }
        self.program.table_hashes.insert(
            (key, h),
            interp::TableHash {
                build,
                state,
                methods,
                own,
                native,
            },
        );
    }

    /// Record, for a hashed table's key type `key`, the `==` body it is
    /// compared by when a part of it, not the key itself, has a
    /// hand-written `PartialEq`, as collections.md § Hashing says keys are
    /// compared (B-2026-10-27-26). A key with its own `eq` is found by that
    /// body already, and one with no hand-written part structurally.
    fn note_key_eq(&mut self, key: Ty) {
        let mut key = key;
        while let HK::Ref(i) | HK::MutRef(i) = self.tys.tcx().kind(key) {
            key = i;
        }
        if self.program.key_eqs.contains_key(&key) || !self.key_eq_noted.insert(key) {
            return;
        }
        if self.trait_method_of(key, "PartialEq", "eq").is_some() {
            return;
        }
        let mut seen = FxHashSet::default();
        let mut work = vec![key];
        let mut found = false;
        while let Some(t) = work.pop() {
            if !seen.insert(t) {
                continue;
            }
            let tcx = self.tys.tcx();
            match tcx.kind(t) {
                HK::Ref(x) | HK::MutRef(x) => work.push(x),
                HK::Tuple(l) => work.extend(tcx.list(l)),
                HK::Array { elem, .. } | HK::Slice { elem, .. } => work.push(elem),
                HK::Intrinsic { args, .. } => work.extend(tcx.list(args)),
                HK::Adt { args, .. } | HK::Shared { args, .. } => {
                    if self.trait_method_of(t, "PartialEq", "eq").is_some() {
                        found = true;
                        break;
                    }
                    let tcx = self.tys.tcx();
                    work.extend(tcx.list(args));
                    if let Some((adt, _)) = tcx.adt_of(t) {
                        for (k, v) in adt.variants.iter().enumerate() {
                            let variant = adt.is_enum.then_some(k as u32);
                            for i in 0..v.fields.len() {
                                work.extend(tcx.field_ty(t, variant, i as u32));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
        if !found {
            return;
        }
        let name = format!("{}.eq#key", self.tys.display(key));
        self.lower_key_eq(key, &name);
        self.program.key_eqs.insert(key, name);
    }

    /// `T.eq#key(a: ref T, b: ref T) -> bool`: `*a == *b`, as `==` on a
    /// `T` lowers, built as its own body for a table's key search.
    fn lower_key_eq(&mut self, t: Ty, name: &str) {
        let bool_t = self.tys.bool();
        let rt = self.tys.tcx().reference(t, false);
        let instance = InstanceId {
            def: DefId(u32::MAX),
            args: Vec::new(),
            name: name.to_string(),
        };
        let mut bx = Bx::new(self, instance, bool_t, Vec::new());
        let a = bx.b.arg("a", rt);
        let b = bx.b.arg("b", rt);
        let r = bx.eq_places(
            Span::default(),
            Place::local(a).project(ProjElem::Deref),
            Place::local(b).project(ProjElem::Deref),
            t,
            Place::local(Local::RETURN_PLACE),
        );
        if r.is_ok() {
            let cur = bx.cur;
            bx.b.terminate(cur, TerminatorKind::Return);
        }
        let (body, errors) = bx.finish();
        self.errors.extend(errors);
        if let Some(body) = body {
            self.program.add(body);
        }
    }

    /// Queue the instance `def[args]` if it is new, and return its name.
    fn instance(&mut self, def: DefId, args: Vec<Ty>) -> String {
        let name = self.instance_name(def, &args);
        if self.queued.insert(name.clone()) {
            self.queue.push((def, args, name.clone()));
        }
        name
    }

    /// `f`, `f[i64]`, `R.drop`, `Pair[i64].put[bool]`.
    fn instance_name(&self, def: DefId, args: &[Ty]) -> String {
        let show = |ts: &[Ty]| {
            ts.iter()
                .map(|&t| self.tys.display(t))
                .collect::<Vec<_>>()
                .join(", ")
        };
        let name = self.def_name(def);
        match self.fns.get(&def) {
            Some(FnItem {
                impl_target: Some(t),
                impl_params,
                impl_dispatch,
                impl_suffix,
                ..
            }) => {
                let (impl_args, own) = args.split_at((*impl_params).min(args.len()));
                // A method of one of several single-instantiation impls is
                // named for its instantiation (`Bx[String].tag`), apart from
                // its siblings'.
                let mut s = impl_dispatch.clone().unwrap_or_else(|| self.def_name(*t));
                if !impl_args.is_empty() {
                    s = format!("{s}[{}]", show(impl_args));
                }
                s.push('.');
                s.push_str(&name);
                if let Some(k) = impl_suffix {
                    s.push_str(k);
                }
                if !own.is_empty() {
                    s = format!("{s}[{}]", show(own));
                }
                s
            }
            Some(FnItem {
                impl_dyn: Some(tr),
                impl_params,
                ..
            }) if !args.is_empty() => {
                let (impl_args, own) = args.split_at((*impl_params).min(args.len()));
                let mut s = self.tys.display(impl_args[0]);
                if impl_args.len() > 1 {
                    s = format!("{s} as {}[{}]", self.def_name(*tr), show(&impl_args[1..]));
                }
                s = format!("{s}.{name}");
                if !own.is_empty() {
                    s = format!("{s}[{}]", show(own));
                }
                s
            }
            Some(FnItem {
                impl_slice: true, ..
            }) if !args.is_empty() => {
                let s = format!("Slice[{}].{name}", show(&args[..1]));
                if args.len() == 1 {
                    s
                } else {
                    format!("{s}[{}]", show(&args[1..]))
                }
            }
            Some(FnItem {
                impl_prim: Some(t), ..
            }) => {
                let s = format!("{}.{name}", self.tys.display(*t));
                if args.is_empty() {
                    s
                } else {
                    format!("{s}[{}]", show(args))
                }
            }
            // The builder calls these natives by bare name (an f-string is
            // `format`), and a body of the same name would take the call:
            // a user function so named is renamed apart (B-2026-10-15-34).
            _ if BUILDER_NATIVES.contains(&name.as_str()) => {
                let s = format!("{name}#fn");
                if args.is_empty() {
                    s
                } else {
                    format!("{s}[{}]", show(args))
                }
            }
            _ if args.is_empty() => name,
            _ => format!("{name}[{}]", show(args)),
        }
    }

    fn lower_instance(&mut self, def: DefId, args: &[Ty], name: &str) {
        let Some(item) = self.fns.get(&def) else {
            self.errors.push(format!("no body for `{name}`"));
            return;
        };
        let f = item.f;
        let impl_target = item.impl_target.map(|t| (t, item.impl_params));
        let instance = InstanceId {
            def,
            args: args.to_vec(),
            name: name.to_string(),
        };
        let ret = match self.fn_return(def, args) {
            Ok(t) => t,
            Err(e) => {
                self.errors.push(format!("{} `{name}`: {e}", at(f.span)));
                return;
            }
        };
        let fn_params = self.fn_param_tys.get(name).cloned().unwrap_or_default();
        let mut bx = Bx::new(self, instance, ret, args.to_vec());
        if name == "main" {
            // `main`'s `Err(e)` exit writes `e` through its `Display`
            // (core-semantics §10.3), which the backends call like a
            // nested one (B-2026-10-23-18).
            bx.queue_nested_displays(ret);
        }
        bx.lower_fn(f, impl_target, &fn_params);
        let (body, errors) = bx.finish();
        self.errors.extend(errors);
        if let Some(body) = body {
            self.program.add(body);
        }
    }

    /// The static a module binding lives in, as its index, type and
    /// mutability, allocated (and its initializer queued) on first ask.
    /// A `let mut` binding needs one global place; so does an immutable
    /// one holding a cell (`Atomic`, `Mutex`, ...), whose writes through
    /// a shared borrow every use must see. Any other binding is a value
    /// computed where it is used.
    fn static_of(&mut self, d: DefId) -> Option<(u32, Ty, bool)> {
        if let Some(&s) = self.statics.get(&d) {
            return Some(s);
        }
        let b = *self.bindings.get(&d)?;
        let t = *self.node_types.get(&b.value.id)?;
        let t = self.mir_ty(t, &[]).ok()?;
        if !b.is_mut {
            let shown = self.tys.display(t);
            let cell = [
                "Atomic", "Mutex", "RwLock", "Arena", "OnceLock", "OnceCell", "LazyLock",
            ]
            .iter()
            .any(|c| shown == *c || shown.starts_with(&format!("{c}[")));
            if !cell {
                return None;
            }
        }
        let idx = self.program.statics.len() as u32;
        let init = format!("static.{}", b.name);
        self.program.statics.push(StaticDef {
            name: b.name.clone(),
            ty: t,
            mutable: b.is_mut,
            init: init.clone(),
        });
        self.statics.insert(d, (idx, t, b.is_mut));
        self.static_queue.push((d, init));
        Some((idx, t, b.is_mut))
    }

    /// The static holding the literal `e` of type `t`: one per type and
    /// spelling, its value computed before `main` like a module binding's.
    fn literal_static(&mut self, e: &'a Expr, t: Ty) -> u32 {
        let key = (t, format!("{:?}", e.kind));
        if let Some(&i) = self.literal_statics.get(&key) {
            return i;
        }
        let i = self.program.statics.len() as u32;
        let name = format!("lit{}", self.literal_statics.len());
        let init = format!("static.{name}");
        self.program.statics.push(StaticDef {
            name,
            ty: t,
            mutable: false,
            init: init.clone(),
        });
        self.literal_statics.insert(key, i);
        self.literal_queue.push((e, t, init));
        i
    }

    fn lower_literal_static(&mut self, e: &'a Expr, t: Ty, name: &str) {
        let instance = InstanceId {
            def: DefId(u32::MAX),
            args: Vec::new(),
            name: name.to_string(),
        };
        let mut bx = Bx::new(self, instance, t, Vec::new());
        let _ = bx.lower_literal_init(e, t);
        let (body, errors) = bx.finish();
        self.errors.extend(errors);
        if let Some(body) = body {
            self.program.add(body);
        }
    }

    /// The initializer of the static holding a program's default provider
    /// (core semantics §14.14): its declaration's expression, evaluated
    /// once before `main`.
    fn lower_default_static(&mut self, e: &'a Expr, t: Ty, name: &str) {
        let instance = InstanceId {
            def: DefId(u32::MAX),
            args: Vec::new(),
            name: name.to_string(),
        };
        let mut bx = Bx::new(self, instance, t, Vec::new());
        let _ = bx.lower_static_init(e);
        let (body, errors) = bx.finish();
        self.errors.extend(errors);
        if let Some(body) = body {
            self.program.add(body);
        }
    }

    /// A static's initializer: a body of no parameters returning its value.
    fn lower_static(&mut self, def: DefId, name: &str) {
        let Some(b) = self.bindings.get(&def).copied() else {
            return;
        };
        let Some(&(_, t, _)) = self.statics.get(&def) else {
            return;
        };
        let instance = InstanceId {
            def,
            args: Vec::new(),
            name: name.to_string(),
        };
        let mut bx = Bx::new(self, instance, t, Vec::new());
        let _ = bx.lower_static_init(&b.value);
        let (body, errors) = bx.finish();
        self.errors.extend(errors);
        if let Some(body) = body {
            self.program.add(body);
        }
    }

    /// `T.eq#derived(a: ref T, b: ref T) -> bool`: a derived `==` built as
    /// its own body, which a comparison calls where it would otherwise
    /// inline itself forever.
    fn lower_derived_eq(&mut self, t: Ty, name: &str) {
        let bool_t = self.tys.bool();
        let rt = self.tys.tcx().reference(t, false);
        let instance = InstanceId {
            def: DefId(u32::MAX),
            args: Vec::new(),
            name: name.to_string(),
        };
        let mut bx = Bx::new(self, instance, bool_t, Vec::new());
        let a = bx.b.arg("a", rt);
        let b = bx.b.arg("b", rt);
        bx.eq_stack.push(t);
        let r = bx.derived_eq(
            Span::default(),
            Place::local(a).project(ProjElem::Deref),
            Place::local(b).project(ProjElem::Deref),
            t,
            Place::local(Local::RETURN_PLACE),
        );
        if r.is_ok() {
            let cur = bx.cur;
            bx.b.terminate(cur, TerminatorKind::Return);
        }
        let (body, errors) = bx.finish();
        self.errors.extend(errors);
        if let Some(body) = body {
            self.program.add(body);
        }
    }

    /// Build a closure's body: the environment first, then its parameters.
    fn lower_closure(&mut self, job: ClosureJob<'a>) {
        let ExprKind::Closure { params, body, .. } = &job.expr.kind else {
            return;
        };
        let ret = match (job.ret, self.node_types.get(&job.expr.id)) {
            (Some((t, _)), _) => Ok(t),
            (None, Some(&fn_ty)) => match self.tys.tcx().kind(fn_ty) {
                HK::Fn { ret, .. } => self.mir_ty(ret, &job.args),
                _ => Err("a closure whose type is not a function".to_string()),
            },
            (None, None) => {
                self.errors.push(format!(
                    "{} closure with no recorded type",
                    at(job.expr.span)
                ));
                return;
            }
        };
        let ret = match ret {
            Ok(t) if job.ref_key => self.tys.tcx().reference(t, false),
            Ok(t) => t,
            Err(e) => {
                self.errors
                    .push(format!("{} `{}`: {e}", at(job.expr.span), job.name));
                return;
            }
        };
        let instance = InstanceId {
            def: job.def,
            args: job.args.clone(),
            name: job.name.clone(),
        };
        let mut bx = Bx::new(self, instance, ret, job.args.clone());
        bx.outer_fn = Some(job.outer);
        let _ = bx.lower_closure_body(&job, params, body);
        let (body, errors) = bx.finish();
        self.errors.extend(errors);
        if let Some(body) = body {
            self.program.add(body);
        }
    }

    /// The key of `def` in the checker's per-function tables.
    fn fn_key(&self, def: DefId) -> (Option<SpanKey>, SpanKey) {
        let item = &self.fns[&def];
        (item.impl_span, SpanKey::from_span(&item.f.span))
    }

    /// The declared return type of `f`, instantiated.
    fn fn_return(&mut self, def: DefId, args: &[Ty]) -> Result<Ty, String> {
        let key = self.fn_key(def);
        let Some((ty, frame)) = self.tc.fn_return_types.get(&key) else {
            return Err("its return type was not recorded".into());
        };
        let params = self
            .tc
            .node_generic_frames
            .get(*frame as usize)
            .cloned()
            .unwrap_or_default();
        let projs = self.tc.node_generic_frame_proj_traits.get(*frame as usize);
        let hir = self.lower_legacy(ty, &params, projs)?;
        let hir = self.fill_erased_target(def, hir, args);
        self.mir_ty(hir, args)
    }

    /// `t` with the instance arguments `args` of `def` written into its
    /// impl target where the checker recorded the target erased (`Tk` for
    /// `impl[I] It for Tk[I]`, which is how `self`, a local bound to it, and
    /// `Self` in a signature are typed).
    fn fill_erased_target(&self, def: DefId, t: Ty, args: &[Ty]) -> Ty {
        let Some(item) = self.fns.get(&def) else {
            return t;
        };
        let (Some(target), n) = (item.impl_target, item.impl_params) else {
            return t;
        };
        if n == 0 {
            // A concrete impl over an applied generic (`impl Bx[String]`):
            // its target's args are the receiver's, as a call recorded them.
            let tcx = self.tys.tcx();
            let applied = match self.self_tys.get(&def).map(|&st| tcx.kind(st)) {
                Some(HK::Adt { args, .. } | HK::Shared { args, .. }) => tcx.list(args),
                _ => Vec::new(),
            };
            if applied.is_empty() {
                return t;
            }
            return tcx.fill_erased_args(t, target, &applied);
        }
        if n > args.len() {
            return t;
        }
        self.tys
            .tcx()
            .fill_erased_args(t, target, &item.target_args(&args[..n]))
    }

    /// `self`'s type in `f`, instantiated, when the checker recorded the
    /// impl target with its args written out: `Option[Option[i64]]` for
    /// `impl[T] Option[Option[T]]` at `T = i64`, where building the target
    /// from the impl's params by position gives `Option[i64]`. `None` when
    /// the recorded target has its args erased, as most generic impls'
    /// targets are.
    fn fn_self_written(&mut self, def: DefId, args: &[Ty]) -> Option<Result<Ty, String>> {
        let key = self.fn_key(def);
        let (ty, frame) = self.tc.fn_self_types.get(&key)?;
        if !matches!(ty, Type::Named { args, .. } if !args.is_empty()) {
            return None;
        }
        let params = self
            .tc
            .node_generic_frames
            .get(*frame as usize)
            .cloned()
            .unwrap_or_default();
        let projs = self.tc.node_generic_frame_proj_traits.get(*frame as usize);
        Some(
            self.lower_legacy(ty, &params, projs)
                .and_then(|hir| self.mir_ty(hir, args)),
        )
    }

    /// `projs` names the bound trait behind each `T.Assoc` in `ty`, from
    /// the frame or impl `ty` was written in (B-2026-10-18-1).
    fn lower_legacy(
        &self,
        ty: &Type,
        params: &[String],
        projs: Option<&ProjTraits>,
    ) -> Result<Ty, String> {
        let defs = self.defs;
        let lookup = |name: &str| {
            let d = defs.lookup(0, name)?;
            if defs.is_builtin_unit(d) {
                // `Unit` spelled by name is `()`.
                return None;
            }
            match defs.table.get(d).kind {
                DefKind::Trait => Some(TypeName::Trait(d)),
                _ => Some(TypeName::Adt(d)),
            }
        };
        let param = |name: &str| params.iter().position(|p| p == name).map(|i| i as u32);
        let proj_trait = |p: &str, a: &str| projs?.get(&(p.to_string(), a.to_string())).cloned();
        self.tys
            .tcx()
            .lower_legacy_full(ty, &lookup, &param, false, &proj_trait)
            .map_err(|e| format!("type {e:?}"))
    }

    // ── types ───────────────────────────────────────────────────────

    /// The MIR type of a typed-HIR type, with the instance's arguments
    /// substituted. The library collections become intrinsics and a
    /// `shared` ADT a counted handle; every ADT reached is registered.
    fn mir_ty(&mut self, ty: Ty, args: &[Ty]) -> Result<Ty, String> {
        let tcx = self.tys.tcx();
        let ty = tcx.subst(ty, args, &[]);
        self.convert(ty)
    }

    fn convert(&mut self, ty: Ty) -> Result<Ty, String> {
        let kind = self.tys.tcx().kind(ty);
        let list = |s: &mut Self, l| -> Result<Vec<Ty>, String> {
            let tys = s.tys.tcx().list(l);
            tys.into_iter().map(|t| s.convert(t)).collect()
        };
        let new = match kind {
            HK::Adt { def, args } => {
                let args = list(self, args)?;
                let name = self.def_name(def);
                let std = self
                    .defs
                    .table
                    .get(def)
                    .path
                    .segments
                    .first()
                    .map(String::as_str)
                    == Some("std");
                let intrinsic = match name.as_str() {
                    "Vec" if std => Some(IntrinsicKind::Vec),
                    "Map" if std => Some(IntrinsicKind::Map),
                    "Set" if std => Some(IntrinsicKind::Set),
                    "VecDeque" if std => Some(IntrinsicKind::VecDeque),
                    "SortedMap" if std => Some(IntrinsicKind::SortedMap),
                    "SortedSet" if std => Some(IntrinsicKind::SortedSet),
                    _ => None,
                };
                if let Some(kind) = intrinsic {
                    let args = self.tys.tcx().intern_list(&args);
                    HK::Intrinsic { kind, args }
                } else if name == "StringSlice" && std {
                    // A view of text (core semantics §5.2): `str`, copied
                    // like a reference and never dropped.
                    HK::StaticStr
                } else {
                    let shared = self.register_adt(def)?;
                    let targs = args.clone();
                    let args = self.tys.tcx().intern_list(&args);
                    let new = if shared {
                        HK::Shared { def, args }
                    } else {
                        HK::Adt { def, args }
                    };
                    // Its fields typed by a projection, normalized for
                    // this instance (B-2026-10-18-23).
                    if self.proj_adts.contains(&def)
                        && !targs.iter().any(|&t| has_param(&self.tys, t))
                    {
                        let ty = self.tys.tcx().intern(new);
                        if self.proj_instances.insert(ty) {
                            self.normalize_field_projs(def, &targs)?;
                        }
                    }
                    // A generic type's `Drop` body, for this instance.
                    if let Some(&d) = self.generic_drops.get(&def) {
                        let concrete = !targs.iter().any(|&t| has_param(&self.tys, t));
                        if concrete {
                            let ty = self.tys.tcx().intern(new);
                            if !self.program.drop_by_ty.contains_key(&ty) {
                                let inst = if self.fns.contains_key(&d) {
                                    self.instance(d, targs)
                                } else {
                                    // A `#[compiler_builtin]` drop: the
                                    // interpreter's, by the type's name.
                                    format!("{}.drop", self.tys.display(ty))
                                };
                                self.program.drop_by_ty.insert(ty, inst);
                            }
                        }
                    }
                    new
                }
            }
            HK::Tuple(l) => {
                let tys = list(self, l)?;
                HK::Tuple(self.tys.tcx().intern_list(&tys))
            }
            HK::Array { elem, len } => HK::Array {
                elem: self.convert(elem)?,
                len,
            },
            HK::Slice { elem, mutable } => HK::Slice {
                elem: self.convert(elem)?,
                mutable,
            },
            HK::Vector { elem, lanes } => HK::Vector {
                elem: self.convert(elem)?,
                lanes,
            },
            HK::Ref(t) => HK::Ref(self.convert(t)?),
            HK::MutRef(t) => HK::MutRef(self.convert(t)?),
            HK::Opaque { .. } => return Err("an iterator value".into()),
            HK::Proj { base, .. } if self.keep_param_projs && has_param(&self.tys, base) => {
                return Ok(ty)
            }
            HK::Proj {
                base,
                assoc,
                trait_,
            } => {
                let to = self.normalize_proj(base, assoc, trait_)?;
                if !has_param(&self.tys, base) {
                    self.tys.tcx().record_proj(ty, to);
                }
                return Ok(to);
            }
            HK::Error => return Err("a type that failed to check".into()),
            HK::Weak(t) => HK::Weak(self.convert(t)?),
            HK::Fn {
                params,
                ret,
                once,
                mutable,
            } => HK::Fn {
                params: {
                    let tys = list(self, params)?;
                    self.tys.tcx().intern_list(&tys)
                },
                ret: self.convert(ret)?,
                once,
                mutable,
            },
            HK::RawPtr { mutable, pointee } => HK::RawPtr {
                mutable,
                pointee: self.convert(pointee)?,
            },
            other => other,
        };
        Ok(self.tys.tcx().intern(new))
    }

    /// Normalize each projection in `def`'s field types at `args`, so
    /// `field_ty` answers with its binding (B-2026-10-18-23).
    fn normalize_field_projs(&mut self, def: DefId, args: &[Ty]) -> Result<(), String> {
        let Some(adt) = self.tys.tcx().adt_def(def) else {
            return Ok(());
        };
        let mut projs = Vec::new();
        for v in &adt.variants {
            for &(_, t) in &v.fields {
                collect_param_projs(&self.tys, t, &mut projs);
            }
        }
        for p in projs {
            let p = self.tys.tcx().subst(p, args, &[]);
            if matches!(self.tys.tcx().kind(p), HK::Proj { .. }) {
                self.convert(p)?;
            }
        }
        Ok(())
    }

    /// Where `assoc` sits in the arguments of a `dyn tr`: after the trait's
    /// own generics, the associated types of the trait and its supertraits,
    /// breadth-first and each once (the checker's `dyn_assoc_names`).
    pub(super) fn dyn_assoc_index(&self, tr: &str, assoc: &str) -> Option<usize> {
        let own = self.trait_defs.get(tr)?;
        let generics = own.generic_params.as_ref().map_or(0, |g| g.params.len());
        let mut names: Vec<&str> = Vec::new();
        let mut seen: FxHashSet<&str> = FxHashSet::default();
        let mut frontier = std::collections::VecDeque::from([tr]);
        seen.insert(tr);
        while let Some(t) = frontier.pop_front() {
            let Some(def) = self.trait_defs.get(t) else {
                continue;
            };
            for item in &def.items {
                if let ast::TraitItem::AssocType(a) = item {
                    if !names.contains(&a.name.as_str()) {
                        names.push(&a.name);
                    }
                }
            }
            for st in &def.supertraits {
                if let Some(n) = st.path.last() {
                    if seen.insert(n) {
                        frontier.push_back(n);
                    }
                }
            }
        }
        names.iter().position(|n| *n == assoc).map(|i| generics + i)
    }

    /// `base.assoc` at an instance: the binding of `assoc` in the impl for
    /// `base`'s type, instantiated with `base`'s arguments. With `trait_`
    /// (`T.Output` under `T: Add`), the binding of that trait's impl, so a
    /// type with `impl Add` and `impl Mul` answers with the right one
    /// (B-2026-10-18-1).
    fn normalize_proj(
        &mut self,
        base: Ty,
        assoc: crate::intern::Symbol,
        trait_: Option<crate::intern::Symbol>,
    ) -> Result<Ty, String> {
        let base = self.convert(base)?;
        let tcx = self.tys.tcx();
        let (name, args) = match tcx.kind(base) {
            HK::Adt { def, args } | HK::Shared { def, args } => (self.def_name(def), args),
            HK::Intrinsic { kind, args } => (kind.name().to_string(), args),
            // B-2026-10-15-76 — every operator impl of a number or `bool` has
            // `Output = Self` (design.md § Operator traits), the typechecker's
            // `resolve_assoc_projections` twin.
            HK::Int(_) | HK::UInt(_) | HK::Float(_) | HK::Bool
                if &*tcx.resolve_name(assoc) == "Output" =>
            {
                return Ok(base);
            }
            // A `dyn` type carries its bindings in its arguments.
            HK::Dyn { trait_, args, .. } => {
                let tr = self.def_name(trait_);
                if let Some(i) = self.dyn_assoc_index(&tr, &tcx.resolve_name(assoc)) {
                    if let Some(&t) = tcx.list(args).get(i) {
                        return Ok(t);
                    }
                }
                return Err(format!(
                    "an associated type of `{}`",
                    tcx.display(base, &|d| self.def_name(d))
                ));
            }
            _ => {
                return Err(format!(
                    "an associated type of `{}`",
                    tcx.display(base, &|d| self.def_name(d))
                ))
            }
        };
        let assoc = tcx.resolve_name(assoc).to_string();
        let tc = self.tc;
        // Without a bound trait (`Self.Output`, `W[V].Output`), the one
        // trait impl that binds `assoc` still brings its own bounds for a
        // projection in the binding (`W[T.Output]` under `impl[T: Add]`).
        let by_trait = match trait_ {
            Some(t) => {
                let key = (name.clone(), tcx.resolve_name(t).to_string(), assoc.clone());
                tc.impl_trait_assoc_types.get(&key)
            }
            None => {
                let mut it = tc
                    .impl_trait_assoc_types
                    .iter()
                    .filter(|((ty, _, a), _)| *ty == name && *a == assoc)
                    .map(|(_, v)| v);
                match (it.next(), it.next()) {
                    (Some(v), None) => Some(v),
                    _ => None,
                }
            }
        };
        // A blanket impl (`impl[I: Iterator] IntoIterator for I`) answers
        // for a receiver with no impl of the trait of its own, with its
        // parameter standing for the whole receiver.
        if by_trait.is_none() {
            if let Some(t) = trait_ {
                let t = tcx.resolve_name(t).to_string();
                let blanket = tc.blanket_impls.iter().find_map(|(bt, p)| {
                    let key = (p.clone(), t.clone(), assoc.clone());
                    (*bt == t).then(|| tc.impl_trait_assoc_types.get(&key).map(|e| (p, e)))?
                });
                if let Some((p, (bound, projs))) = blanket {
                    let hir = self.lower_legacy(bound, std::slice::from_ref(p), Some(projs))?;
                    return self.mir_ty(hir, &[base]);
                }
            }
        }
        let (bound, projs) = match by_trait {
            Some((bound, projs)) => (bound, Some(projs)),
            None => match tc.impl_assoc_types.get(&(name.clone(), assoc.clone())) {
                Some(bound) => (bound, None),
                None => return Err(format!("`{name}.{assoc}`, which no impl binds")),
            },
        };
        let params = tc
            .struct_info
            .get(&name)
            .map(|s| s.generic_params.clone())
            .or_else(|| tc.enum_info.get(&name).map(|e| e.generic_params.clone()))
            .unwrap_or_default();
        let hir = self.lower_legacy(bound, &params, projs)?;
        let args = tcx.list(args);
        self.mir_ty(hir, &args)
    }

    /// Whether `def` is the builtin `CStr` (a borrowed view, `Copy`) or
    /// `CString` (owned), as `Some(is_copy)`.
    fn c_string_def(&self, def: DefId, name: &str) -> Option<bool> {
        let std = self
            .defs
            .table
            .get(def)
            .path
            .segments
            .first()
            .map(String::as_str)
            == Some("std");
        match name {
            "CStr" if std => Some(true),
            "CString" if std => Some(false),
            _ => None,
        }
    }

    /// Register the definition of the ADT `def` (and its `Drop` body),
    /// once. Returns whether it is `shared`.
    fn register_adt(&mut self, def: DefId) -> Result<bool, String> {
        let name = self.def_name(def);
        let tc = self.tc;
        let (generics, variants, shared, copy): (_, Vec<CheckedVariant>, _, _) =
            if let Some(s) = tc.struct_info.get(&name) {
                (
                    s.generic_params.clone(),
                    vec![(
                        name.clone(),
                        s.fields
                            .iter()
                            .map(|(n, t, _)| (n.clone(), t.clone()))
                            .collect(),
                    )],
                    s.is_shared || s.is_par,
                    s.derived_traits.contains("Copy"),
                )
            } else if let Some(e) = tc.enum_info.get(&name) {
                let vs = e
                    .variants
                    .iter()
                    .map(|(n, v)| {
                        let fields = match v {
                            VariantTypeInfo::Unit => Vec::new(),
                            VariantTypeInfo::Tuple(ts) => ts
                                .iter()
                                .enumerate()
                                .map(|(i, t)| (i.to_string(), t.clone()))
                                .collect(),
                            VariantTypeInfo::Struct(fs) => fs.clone(),
                        };
                        (n.clone(), fields)
                    })
                    .collect();
                (
                    e.generic_params.clone(),
                    vs,
                    e.is_shared || e.is_par,
                    e.derived_traits.contains("Copy"),
                )
            } else if let Some(base) = tc.distinct_bases.get(&name) {
                // `distinct type UserId = i64`: a struct of one field, the
                // base value (`UserId(7)` builds it, `.raw()` reads it).
                (
                    Vec::new(),
                    vec![(name.clone(), vec![("0".to_string(), base.clone())])],
                    false,
                    tc.distinct_type_traits
                        .get(&name)
                        .is_some_and(|d| d.contains("Copy")),
                )
            } else if let Some(copy) = self.c_string_def(def, &name) {
                // `CStr` / `CString`: opaque, their bytes held by the
                // interpreter's natives.
                (Vec::new(), vec![(name.clone(), Vec::new())], false, copy)
            } else {
                return Err(format!("no definition for type `{name}`"));
            };
        if !self.registered.insert(def) {
            return Ok(shared);
        }
        let is_enum = tc.enum_info.contains_key(&name);
        let mut vdefs = Vec::new();
        for (i, (vname, fields)) in variants.iter().enumerate() {
            let mut fs = Vec::new();
            for (fname, fty) in fields {
                let hir = self.lower_legacy(fty, &generics, None)?;
                let keep = std::mem::replace(&mut self.keep_param_projs, true);
                let t = self.convert(hir);
                self.keep_param_projs = keep;
                let t = t?;
                if has_param_proj(&self.tys, t) {
                    self.proj_adts.insert(def);
                }
                fs.push((fname.clone(), t));
            }
            if is_enum {
                if let Some(v) = self.defs.variant(def, vname) {
                    self.variants.insert(v, (def, i as u32));
                }
            }
            vdefs.push(VariantDef {
                name: vname.clone(),
                fields: fs,
            });
        }
        let has_drop_impl = tc.drop_method_keys.contains_key(&name);
        // Declared in the program rather than the library, whatever its
        // name.
        let user = self.user_types.contains(&name);
        if is_enum && tc.display_snake_case_enums.contains(&name) {
            self.program
                .display_styles
                .insert(AdtId(def.0), interp::DisplayStyle::SnakeCase);
        }
        if tc.distinct_bases.contains_key(&name) && !tc.struct_info.contains_key(&name) {
            self.program
                .display_styles
                .insert(AdtId(def.0), interp::DisplayStyle::Transparent);
        }
        if name == "Secret"
            && tc
                .struct_info
                .get(&name)
                .is_some_and(|si| si.defining_stdlib_origin)
        {
            self.program
                .display_styles
                .insert(AdtId(def.0), interp::DisplayStyle::Redacted);
        }
        let sync = tc.struct_info.get(&name).is_some_and(|s| s.is_par)
            || tc.enum_info.get(&name).is_some_and(|e| e.is_par);
        self.tys.tcx().add_adt_def(AdtDef {
            def,
            name: name.clone(),
            is_enum,
            variants: vdefs,
            has_drop_impl,
            is_copy: copy || (is_enum && matches!(name.as_str(), "Option" | "Result")),
            user,
            sync,
        });
        if has_drop_impl {
            let drop_fn = self
                .defs
                .methods
                .get(&def)
                .and_then(|ms| ms.get("drop"))
                .and_then(|c| c.first().copied());
            match drop_fn {
                Some(d) if generics.is_empty() => {
                    // A `#[compiler_builtin]` drop (`TaskGroup`'s) has no
                    // Kāra body: it is the interpreter's `TaskGroup.drop`.
                    let inst = if self.fns.contains_key(&d) {
                        self.instance(d, Vec::new())
                    } else {
                        format!("{name}.drop")
                    };
                    self.program.drop_impls.insert(AdtId(def.0), inst);
                }
                Some(d) => {
                    self.generic_drops.insert(def, d);
                }
                None => return Err(format!("no `drop` method found for `{name}`")),
            }
        }
        Ok(shared)
    }

    fn variant(&mut self, v: DefId) -> Option<(DefId, u32)> {
        if let Some(&x) = self.variants.get(&v) {
            return Some(x);
        }
        let enum_def = *self.defs.parent.get(&v)?;
        self.register_adt(enum_def).ok()?;
        self.variants.get(&v).copied()
    }
}

/// Whether `t` holds a projection of a generic parameter (`I.Item`).
fn has_param_proj(tys: &TyInterner, t: Ty) -> bool {
    let mut v = Vec::new();
    collect_param_projs(tys, t, &mut v);
    !v.is_empty()
}

/// The projections of a generic parameter in `t`, innermost last.
fn collect_param_projs(tys: &TyInterner, t: Ty, out: &mut Vec<Ty>) {
    let tcx = tys.tcx();
    match tcx.kind(t) {
        HK::Proj { base, .. } => {
            if has_param(tys, base) {
                out.push(t);
            }
        }
        HK::Adt { args, .. } | HK::Shared { args, .. } | HK::Intrinsic { args, .. } => {
            for a in tcx.list(args) {
                collect_param_projs(tys, a, out);
            }
        }
        HK::Tuple(l) => {
            for a in tcx.list(l) {
                collect_param_projs(tys, a, out);
            }
        }
        HK::Ref(i) | HK::MutRef(i) | HK::Weak(i) => collect_param_projs(tys, i, out),
        HK::Array { elem, .. } | HK::Slice { elem, .. } | HK::Vector { elem, .. } => {
            collect_param_projs(tys, elem, out)
        }
        // B-2026-10-18-49: `f: Fn(own I.Item) -> I.Item`.
        HK::Fn { params, ret, .. } => {
            for a in tcx.list(params) {
                collect_param_projs(tys, a, out);
            }
            collect_param_projs(tys, ret, out);
        }
        _ => {}
    }
}

/// Whether `t` still names a generic parameter.
fn has_param(tys: &TyInterner, t: Ty) -> bool {
    let tcx = tys.tcx();
    match tcx.kind(t) {
        HK::Param(_) => true,
        HK::Adt { args, .. } | HK::Shared { args, .. } | HK::Intrinsic { args, .. } => {
            tcx.list(args).into_iter().any(|a| has_param(tys, a))
        }
        HK::Tuple(l) => tcx.list(l).into_iter().any(|a| has_param(tys, a)),
        HK::Ref(i) | HK::MutRef(i) | HK::Weak(i) => has_param(tys, i),
        HK::Array { elem, .. } | HK::Slice { elem, .. } | HK::Vector { elem, .. } => {
            has_param(tys, elem)
        }
        HK::Proj { base, .. } => has_param(tys, base),
        HK::Fn { params, ret, .. } => {
            tcx.list(params).into_iter().any(|a| has_param(tys, a)) || has_param(tys, ret)
        }
        _ => false,
    }
}

/// Each `par {}` branch binding's join symbols: a variable the resolver
/// defined at a binding's name and span with no binding node of its own.
fn par_joins(rr: &ResolveResult) -> FxHashMap<SymbolId, Vec<SymbolId>> {
    let table = &rr.symbol_table;
    let bound: FxHashMap<(&str, usize, usize), SymbolId> = rr
        .binding_nodes
        .keys()
        .map(|&s| {
            let sym = table.get_symbol(s);
            ((sym.name.as_str(), sym.span.offset, sym.span.length), s)
        })
        .collect();
    let mut out: FxHashMap<SymbolId, Vec<SymbolId>> = FxHashMap::default();
    for sym in table.all_symbols() {
        if !matches!(sym.kind, crate::resolver::SymbolKind::Variable { .. })
            || rr.binding_nodes.contains_key(&sym.id)
        {
            continue;
        }
        if let Some(&b) = bound.get(&(sym.name.as_str(), sym.span.offset, sym.span.length)) {
            out.entry(b).or_default().push(sym.id);
        }
    }
    out
}

// ── bodies ──────────────────────────────────────────────────────────

enum ScopeEntry<'a> {
    Drop(Place),
    Defer(&'a Block),
    /// An `errdefer` body, with `errdefer(e)`'s name and statement node.
    ErrDefer(&'a Block, Option<(&'a str, NodeId)>),
    /// A local whose storage ends with the scope.
    Storage(Local),
    /// A `Vec` that `for x in v.into_iter()` takes from the back, reversed
    /// on entry: reversed again on any exit, so what a `break` leaves
    /// drops front to back. The `reverse` native, and the `mut ref` type
    /// it takes.
    Unreverse(Local, Ty, String),
    /// The extent id a `providers { FileSystem => p }` block's
    /// `FileSystem.enter` returned, and the resource (`Network` too):
    /// `R.exit` ends it on every exit from the block (core semantics
    /// §14.11, §14.12).
    FsExit(Local, &'static str),
}

/// An iterator type's `next`, instantiated for a `for` loop: its definition,
/// instance args and name, and the `Option[Item]` it returns.
type NextFn = (DefId, Vec<Ty>, String, Ty);

struct LoopCx {
    label: Option<String>,
    break_bb: BasicBlock,
    continue_bb: BasicBlock,
    depth: usize,
    dest: Option<Place>,
}

/// A `par for` whose iterations run as tasks of one group (M4 item 12).
struct ParForTasks {
    group: Local,
    group_ty: Ty,
    /// The `Vec[TaskHandle[T]]` of the iterations' handles, in order.
    handles: Local,
    handles_ty: Ty,
    /// The symbols bound before the loop: any other the body captures is
    /// one of the loop's own, taken by value.
    outer: FxHashSet<SymbolId>,
}

/// The most tasks an auto-par loop's iterations are cut into (M4 item 14).
const AUTO_PAR_TASKS: u128 = 16;

/// An auto-par loop's task (M4 item 14): a run of the loop's iterations,
/// from the capture `lo` to the capture `hi`, with the loop's own pattern
/// and body.
struct ChunkJob<'a> {
    pattern: &'a Pattern,
    body: &'a Block,
    lo: SymbolId,
    hi: SymbolId,
    ty: Ty,
    /// The loop's reduction is a signed sum, which the task keeps wide
    /// (see [`AutoRed::wide`]).
    wide: Option<&'a [WideSum<'a>]>,
}

/// `while k < n { ..; k += 1 }` (or `k = k + 1`), with `k` an integer
/// local and `n` a literal, a name or `v.len()`: auto-par records and runs
/// it as `for k in k..n { .. }`, the step left out (M4 item 14). Each task
/// binds its own `k`; the loop then leaves `k` at `n` when it ran at all.
#[derive(Clone, Copy)]
struct CountedWhile<'a> {
    /// `k`, binding the counter's symbol.
    pattern: &'a Pattern,
    /// `k..n`.
    range: &'a Expr,
    /// The body without its last statement, the step.
    inner: &'a Block,
    step: &'a Stmt,
    counter: &'a Expr,
    bound: &'a Expr,
}

/// `acc = acc op e` in an auto-par loop's body: each task starts its own
/// `acc` at `op`'s identity and returns it, and the join folds the results
/// into `acc` in iteration order.
#[derive(Clone, Copy)]
struct AutoRed<'a> {
    sym: SymbolId,
    acc: Local,
    op: BinOp,
    ty: Ty,
    /// Where the sequential loop's operation is, which the fold's overflow
    /// check names.
    span: Span,
    /// A checked `+` on a signed integer: a run's own sum can overflow
    /// where the sequential sum never does (`i64.max + 1 - 1`), so each
    /// task sums in `i128` and returns that sum with its run's least and
    /// greatest prefix, and the join checks the prefixes against `acc`'s
    /// range in order: the sequential loop overflows exactly where one of
    /// them leaves it. One per site the body writes `acc` at.
    wide: Option<&'a [WideSum<'a>]>,
    /// `acc.push(e)`: each task pushes onto a `Vec` of its own, which the
    /// join appends to `acc` in iteration order (`op` is unused).
    push: bool,
    /// A checked `+` written at several sites: the join knows a run's sum
    /// would overflow but not at which site, so it runs that run again in
    /// order, where the overflow names its site as the sequential loop's
    /// does. The body can then do nothing others see (the verdict keeps a
    /// loop that can panic and writes in order), so running it twice is
    /// not observable.
    replay: bool,
}

/// A signed sum's statement in an auto-par loop's body, and what it adds:
/// the term of `acc += e`, or the chain `acc = a + acc + b` that holds
/// `acc` as one of its operands.
#[derive(Clone, Copy)]
struct WideSum<'a> {
    stmt: &'a Stmt,
    term: &'a Expr,
    chain: bool,
    acc: SymbolId,
    /// `acc`'s type.
    ty: Ty,
}

/// An auto-par task's wide sum while its run is lowered, the locals the
/// reduction's statement adds its term to in place of `acc`. The run's
/// sum is `base + run`: `run` and its least and greatest prefix are in
/// `acc`'s type, so a term costs a checked add and two compares, and only
/// when `run` would overflow does it fold into the `i128` `base`, `least`
/// and `most` and start again at 0 (B-2026-10-28-35).
#[derive(Clone, Copy)]
struct WideAcc<'a> {
    sums: &'a [WideSum<'a>],
    base: Local,
    least: Local,
    most: Local,
    run: Local,
    run_least: Local,
    run_most: Local,
}

/// How to run one run of an auto-par loop's iterations again, in order:
/// the loop's binding and body, and the runs' bounds, as the spawn cut
/// them (the first `rem` runs one longer than `q`, from `lo`).
#[derive(Clone, Copy)]
struct Replay<'a> {
    pattern: &'a Pattern,
    body: &'a Block,
    lo: Local,
    q: Local,
    rem: Local,
    ty: Ty,
}

/// One site of an auto-par loop's reduction (see [`Bx::reduction_site`]).
#[derive(Clone, Copy)]
struct RedSite<'a> {
    stmt: &'a Stmt,
    sym: SymbolId,
    op: BinOp,
    /// Where its checked operation is.
    span: Span,
    /// The term it adds, or the chain holding `acc`.
    term: &'a Expr,
    chain: bool,
    /// Every step of the chain on the way to `acc` starts at the chain's
    /// start, where the sequential loop's overflow is named.
    chain_starts: bool,
    push: bool,
}

/// What a join of a loop's tasks does with each task's value.
enum JoinSink<'a> {
    /// Push it onto this `Vec` (a `par for`'s value).
    Push(Local, Ty),
    /// Fold it into the reduction's accumulator, or for a reduction that
    /// replays (see [`AutoRed::replay`]), how to run a run again.
    Fold(AutoRed<'a>, Option<Replay<'a>>),
    /// Nothing: the iterations return no value.
    Discard,
}

/// Where a `?` in a `par` branch goes: [`Bx::par_try`].
#[derive(Clone, Copy)]
struct ParTry {
    /// The scope depth the branch starts at.
    depth: usize,
    /// Where the block continues once this branch has failed: the copy of
    /// the next branch that runs after a failure.
    skip: BasicBlock,
    /// The function's return value the block fails with.
    pending: Local,
    /// An earlier branch already failed, so this error is dropped: the
    /// source-earliest error is the block's.
    discard: bool,
}

struct Bx<'l, 'a> {
    lcx: &'l mut Lcx<'a>,
    b: BodyBuilder,
    args: Vec<Ty>,
    cur: BasicBlock,
    locals: FxHashMap<SymbolId, Local>,
    self_local: Option<Local>,
    scopes: Vec<Vec<ScopeEntry<'a>>>,
    loops: Vec<LoopCx>,
    errors: Vec<String>,
    name: String,
    /// In a closure body: where each captured symbol lives.
    captured: FxHashMap<SymbolId, Place>,
    /// A closure body's captures of single fields of an outer struct
    /// binding, by symbol and field (core semantics §9.1).
    captured_fields: FxHashMap<(SymbolId, String), Place>,
    /// Closures created in this body so far, for their names.
    closure_count: u32,
    /// The next closure literal lowered goes to a library call, so its
    /// parameters borrow.
    closure_ref_params: bool,
    /// `Copy` bindings read through a shared reference, with the place
    /// they copied: a `ref` to the binding views that place instead, so it
    /// outlives the binding's arm.
    copy_views: FxHashMap<Local, Place>,
    /// Scrutinees reborrowed mutably because they are reached only through
    /// `mut ref`s, with no `mut ref` binding asking for it: their `Copy`
    /// parts bind by copy (B-2026-10-18-41).
    writable_reborrows: FxHashSet<Local>,
    /// The scope of the block a `let` binding being lowered belongs to: a
    /// value its initializer borrows lives to that block's end
    /// (B-2026-10-18-53).
    let_scope: Option<usize>,
    /// The closure being lowered is a library sort's key function.
    closure_key: bool,
    /// The closure being lowered is a task handed to `TaskGroup.spawn`,
    /// which copies its `Copy` captures in (see `closure_value`).
    closure_task: bool,
    /// The next closure lowered is a `par` branch's task, with this return
    /// type and wrapping (see `ClosureJob::ret`).
    closure_ret: Option<(Ty, Option<u32>)>,
    /// The next closure lowered is a `par` branch's task that may leave
    /// early (see `ClosureJob::exit`).
    closure_exit: Option<(Ty, u32)>,
    /// This body is a `par` branch's task that may leave early: a
    /// `return` or `?` in it ends the task with the function's value in
    /// this variant of the task's result (see `ClosureJob::exit`).
    par_exit: Option<(Ty, u32)>,
    /// The next closure literal lowered escapes (it is stored as a
    /// function value), so it captures by move.
    closure_escapes: bool,
    /// Expressions already evaluated, and the places that hold their
    /// values: an assertion's operands, which its failure message reads
    /// again without running them twice.
    pinned: FxHashMap<NodeId, Place>,
    /// The captures a closure body assigns to, found with its moves.
    assigned_caps: std::cell::RefCell<FxHashSet<SymbolId>>,
    /// Whether `moved_captures` is finding a task's: a library builtin's
    /// argument then moves in (`String.from_utf8(bytes)`), where a closure
    /// the program writes keeps the checker's capture modes.
    task_moves: bool,
    /// In a closure's body, the function the closure is written in.
    outer_fn: Option<DefId>,
    /// `let f = |..| ..` bindings whose closure is later stored where it
    /// escapes, by the binding pattern's id (see `let_closure_escapes`).
    escaping_lets: FxHashSet<NodeId>,
    /// Closure literals inside the value this body returns (see
    /// `note_returned_closures`).
    returned_closures: FxHashSet<NodeId>,
    /// Types for expressions the checker left untyped, taken from where
    /// they are used (`v.push(None)` gives `None` the element type).
    ty_hints: FxHashMap<NodeId, Ty>,
    /// The `par for` whose body is lowered next: its body, the `Vec` local
    /// that collects the bodies' values, and that `Vec`'s type.
    par_acc: Option<(*const Block, Local, Ty, usize)>,
    /// When that `par for`'s iterations run as tasks: their group and the
    /// `Vec` of their handles.
    par_for_tasks: Option<ParForTasks>,
    /// Captures a closure takes by value whatever its body needs: a `par
    /// for` iteration's loop bindings, which end before its task does.
    closure_by_value: FxHashSet<SymbolId>,
    /// The sequential `for` whose body is lowered next, recorded as an
    /// auto-par candidate with the loop's span (M4 item 14).
    auto_par_candidate: Option<(*const Block, Span)>,
    /// The next closure lowered is an auto-par loop's task running a run
    /// of its iterations (see `ClosureJob::chunk`).
    closure_chunk: Option<ChunkJob<'a>>,
    /// An auto-par task's signed sum, while its run is lowered.
    wide_acc: Option<WideAcc<'a>>,
    /// The source lines of the reduction sites [`Self::auto_par_plan`] last
    /// planned, for the auto-par report.
    red_lines: Vec<usize>,
    /// Symbols the next closure lowered captures besides those its body
    /// names (an auto-par task's bounds), and ones it does not (the loop's
    /// own binding, which the task binds).
    closure_extra_caps: Vec<SymbolId>,
    closure_skip_caps: FxHashSet<SymbolId>,
    /// The next closure lowered returns this capture's value once its body
    /// has run: an auto-par iteration's part of a reduction.
    closure_ret_capture: Option<SymbolId>,
    /// The next closure lowered is an auto-par loop's task.
    closure_auto_par: bool,
    /// Auto-par tasks created in this body so far, for their names.
    auto_par_count: u32,
    /// The `seq { .. }` blocks being lowered: nothing in one is a
    /// candidate for auto-par.
    seq_depth: u32,
    /// The `par` branches being lowered, innermost last: a `?` in one
    /// records its error and leaves the branch, not the function, so the
    /// other branches still run (core semantics §11.7). `None` while a
    /// `par for` body is lowered, where `?` still returns.
    par_try: Vec<Option<ParTry>>,
    /// Each `old(e)` of this function's `ensures` clauses: `e`'s value,
    /// taken on entry.
    old_vals: FxHashMap<NodeId, Local>,
    /// This function's `ensures` clauses, checked at every return.
    ensures: &'a [EnsuresClause],
    /// The impl this function belongs to and its generic parameter count.
    impl_target: Option<(DefId, usize)>,
    /// Subscripts of an assignment's target, evaluated before its value.
    pre_indices: FxHashMap<NodeId, Operand>,
    /// The types whose derived `==` is being inlined, outermost first.
    eq_stack: Vec<Ty>,
    /// Building a cancel exit, whose calls get none of their own.
    in_cancel_exit: bool,
}

type R<T> = Result<T, ()>;

impl<'l, 'a> Bx<'l, 'a> {
    fn new(lcx: &'l mut Lcx<'a>, instance: InstanceId, ret: Ty, args: Vec<Ty>) -> Self {
        let name = instance.name.clone();
        let mut b = BodyBuilder::new(instance, ret);
        let cur = b.new_block();
        Bx {
            lcx,
            b,
            args,
            cur,
            locals: FxHashMap::default(),
            self_local: None,
            scopes: Vec::new(),
            loops: Vec::new(),
            errors: Vec::new(),
            name,
            captured: FxHashMap::default(),
            captured_fields: FxHashMap::default(),
            closure_count: 0,
            closure_ref_params: false,
            copy_views: FxHashMap::default(),
            writable_reborrows: FxHashSet::default(),
            let_scope: None,
            closure_key: false,
            closure_task: false,
            closure_ret: None,
            closure_exit: None,
            par_exit: None,
            closure_escapes: false,
            pinned: FxHashMap::default(),
            escaping_lets: FxHashSet::default(),
            returned_closures: FxHashSet::default(),
            assigned_caps: Default::default(),
            task_moves: false,
            outer_fn: None,
            ty_hints: FxHashMap::default(),
            par_acc: None,
            par_for_tasks: None,
            closure_by_value: FxHashSet::default(),
            auto_par_candidate: None,
            closure_chunk: None,
            wide_acc: None,
            red_lines: Vec::new(),
            closure_extra_caps: Vec::new(),
            closure_skip_caps: FxHashSet::default(),
            closure_ret_capture: None,
            closure_auto_par: false,
            auto_par_count: 0,
            seq_depth: 0,
            par_try: Vec::new(),
            old_vals: FxHashMap::default(),
            ensures: &[],
            impl_target: None,
            pre_indices: FxHashMap::default(),
            eq_stack: Vec::new(),
            in_cancel_exit: false,
        }
    }

    fn finish(mut self) -> (Option<Body>, Vec<String>) {
        if !self.errors.is_empty() {
            return (None, self.errors);
        }
        self.b.terminate_open_blocks(TerminatorKind::Unreachable);
        match self.b.finish() {
            Ok(mut body) => {
                clear_unreachable_blocks(&mut body);
                (Some(body), Vec::new())
            }
            Err(e) => (None, vec![format!("`{}`: {e}", self.name)]),
        }
    }

    fn unsupported<T>(&mut self, span: Span, what: &str) -> R<T> {
        self.errors.push(format!(
            "{} in `{}`: {what} is not lowered yet",
            at(span),
            self.name
        ));
        Err(())
    }

    fn tys(&self) -> &TyInterner {
        &self.lcx.tys
    }

    /// The MIR type of the node `id` in this instance.
    fn node_ty(&mut self, id: NodeId, span: Span) -> R<Ty> {
        if let Some(&l) = self.old_vals.get(&id) {
            return Ok(self.b.local_ty(l));
        }
        let Some(&t) = self.lcx.node_types.get(&id) else {
            if let Some(&t) = self.ty_hints.get(&id) {
                return Ok(t);
            }
            let why = match self.lcx.hir_errors.get(&id) {
                Some(err) => format!("an expression whose type does not lower ({err:?})"),
                None => "an expression with no recorded type".to_string(),
            };
            return self.unsupported(span, &why);
        };
        let args = self.args.clone();
        let t = self.fill_erased_target(t);
        match self.lcx.mir_ty(t, &args) {
            Ok(t) => Ok(t),
            Err(e) => self.unsupported(span, &e),
        }
    }

    /// `t` with this instance's impl arguments written into its impl
    /// target where the checker recorded the target erased (a local bound
    /// to `self` in `impl[I] It for Tk[I]` is typed `Tk`).
    fn fill_erased_target(&self, t: Ty) -> Ty {
        self.lcx
            .fill_erased_target(self.b.instance().def, t, &self.args)
    }

    /// The MIR type of `e`'s value. A local reads as the type of its MIR
    /// local, which differs from the checker's when it binds by reference
    /// (`ref name` patterns, `self` under `ref self`).
    fn expr_ty(&mut self, e: &Expr) -> R<Ty> {
        if self.assert_builtin(e).is_some() {
            return Ok(self.unit());
        }
        if is_process_exit(e) {
            return Ok(self.tys().tcx().intern(HK::Never));
        }
        match &e.kind {
            ExprKind::Identifier(_) => {
                if let Some(Res::Local(sym)) = self.lcx.res.get(&e.id) {
                    let t = match (self.locals.get(sym), self.captured.get(sym).cloned()) {
                        (Some(&l), _) => Some(self.b.local_ty(l)),
                        (None, Some(p)) => Some(self.place_type(&p)),
                        (None, None) => None,
                    };
                    if let Some(t) = t {
                        // A `weak` local read as a value (the checker typed
                        // it an `Option`) is the `Option` of its referent,
                        // which `expr_place` upgrades it to
                        // (B-2026-10-25-45).
                        // A borrowed `weak` parameter reads the same way.
                        let slot = match self.tys().tcx().kind(t) {
                            HK::Ref(i) => i,
                            _ => t,
                        };
                        if let (HK::Weak(inner), Some(&read)) =
                            (self.tys().tcx().kind(slot), self.lcx.node_types.get(&e.id))
                        {
                            if !matches!(self.tys().tcx().kind(read), HK::Weak(_)) {
                                if let Some(o) = self.option_of(inner) {
                                    return Ok(o);
                                }
                            }
                        }
                        return Ok(t);
                    }
                }
            }
            ExprKind::SelfValue => {
                if let Some(l) = self.self_local {
                    return Ok(self.b.local_ty(l));
                }
                if let Some(Res::Local(sym)) = self.lcx.res.get(&e.id) {
                    if let Some(p) = self.captured.get(sym).cloned() {
                        return Ok(self.place_type(&p));
                    }
                }
            }
            ExprKind::FieldAccess { .. } => {
                if let Some((t, _)) = self.int_limit_of(e) {
                    return Ok(t);
                }
            }
            ExprKind::Providers { body, .. } if !self.lcx.node_types.contains_key(&e.id) => {
                return match &body.final_expr {
                    Some(x) => self.expr_ty(x),
                    None => Ok(self.unit()),
                };
            }
            // `with_provider[R](p, || body)` has the closure's value (core
            // semantics §14.4), which the checker records only when it is
            // fully known.
            ExprKind::Call { callee, args } if with_provider_resource(callee).is_some() => {
                if let Some(f) = args.get(1).filter(|_| args.len() == 2) {
                    let ft = self.lcx.node_types.get(&f.value.id).copied();
                    if let Some(HK::Fn { ret, .. }) = ft.map(|t| self.tys().tcx().kind(t)) {
                        let a = self.args.clone();
                        return match self.lcx.mir_ty(ret, &a) {
                            Ok(t) => Ok(t),
                            Err(err) => self.unsupported(e.span, &err),
                        };
                    }
                }
            }
            _ if is_branching(e) => {
                let t = self.node_ty(e.id, e.span)?;
                return Ok(self.arm_width(e, t));
            }
            _ => {}
        }
        self.node_ty(e.id, e.span)
    }

    fn unit(&self) -> Ty {
        self.tys().unit()
    }

    fn is_copy(&self, t: Ty) -> bool {
        self.tys().is_copy(t)
    }

    /// A number, `bool` or `char`: a type whose library methods take their
    /// receiver by value.
    fn is_number(&self, t: Ty) -> bool {
        matches!(
            self.tys().tcx().kind(t),
            HK::Int(_) | HK::UInt(_) | HK::Float(_) | HK::Bool | HK::Char
        )
    }

    fn needs_drop(&self, t: Ty) -> bool {
        self.tys().needs_drop(t)
    }

    fn assign(&mut self, place: impl Into<Place>, rv: Rvalue) {
        let place = place.into();
        let pt = self.place_type(&place);
        // A view of a `dyn` value is the pair itself, never reborrowed
        // through: there is no place behind it to borrow.
        let rv = match rv {
            Rvalue::Ref(_, p) if self.is_dyn_view(self.place_type(&p)) => {
                Rvalue::Use(Operand::Copy(p))
            }
            rv => rv,
        };
        // A borrow of a place that holds a reference is that reference
        // (a borrow of a borrow is the borrow): a reborrow through it.
        let rv = match rv {
            Rvalue::Ref(kind, p) if self.is_reference(self.place_type(&p)) => {
                let kind = match self.tys().tcx().kind(self.place_type(&p)) {
                    HK::Ref(_) => BorrowKind::Shared,
                    _ => kind,
                };
                Rvalue::Ref(kind, p.project(ProjElem::Deref))
            }
            rv => rv,
        };
        // A borrow of a concrete value into a `dyn` view is the borrow, then
        // the view of it (design.md § `dyn Trait`).
        let rv = match rv {
            Rvalue::Ref(kind, p)
                if self.dyn_under(pt).is_some_and(|d| d != pt)
                    && self.dyn_under(self.place_type(&p)).is_none() =>
            {
                let mutable = matches!(kind, BorrowKind::Mut);
                let ct = self.place_type(&p);
                let rt = self.tys().tcx().reference(ct, mutable);
                let r = self.temp(rt);
                let bb = self.cur;
                self.b.assign(bb, Place::local(r), Rvalue::Ref(kind, p));
                Rvalue::Use(Operand::Move(Place::local(r)))
            }
            rv => rv,
        };
        let rv = match rv {
            Rvalue::Use(op) if self.dyn_cast(&op, pt).is_some() => {
                let (concrete, dyn_ty) = self.dyn_cast(&op, pt).expect("checked");
                match self.vtable_for(concrete, dyn_ty) {
                    Ok(vt) => Rvalue::Cast(CastKind::ToDyn(vt), op, pt),
                    Err(()) => Rvalue::Use(op),
                }
            }
            rv => rv,
        };
        let rv = match rv {
            // A closure or function item stored in a function-typed slot
            // is erased to that type.
            Rvalue::Use(op) if self.erases(&op, pt) => {
                Rvalue::Cast(CastKind::Erase, self.erase_source(op), pt)
            }
            Rvalue::Use(op) if self.downgrades(&op, pt) => Rvalue::Use(self.downgrade(op, pt)),
            Rvalue::Use(op) if self.reads_through(&op, pt) => {
                Rvalue::Use(self.read_through(op, pt))
            }
            Rvalue::Use(op @ (Operand::Copy(_) | Operand::Move(_)))
                if self.widening(self.operand_ty(&op), pt).is_some() =>
            {
                let kind = self.widening(self.operand_ty(&op), pt).unwrap();
                Rvalue::Cast(kind, op, pt)
            }
            // Arithmetic computed at the operands' width and widened into
            // the slot (`fn f(x: f32) -> f64 { x + 1.0 }`): the operation,
            // then the widening. Integer operations already reach here as
            // a `Use` of the checked result's value.
            Rvalue::BinaryOp(op, a, b) if self.widening(self.operand_ty(&a), pt).is_some() => {
                let at = self.operand_ty(&a);
                let kind = self.widening(at, pt).unwrap();
                let t = self.temp(at);
                let bb = self.cur;
                self.b
                    .assign(bb, Place::local(t), Rvalue::BinaryOp(op, a, b));
                Rvalue::Cast(kind, Operand::Move(Place::local(t)), pt)
            }
            Rvalue::UnaryOp(op, a) if self.widening(self.operand_ty(&a), pt).is_some() => {
                let at = self.operand_ty(&a);
                let kind = self.widening(at, pt).unwrap();
                let t = self.temp(at);
                let bb = self.cur;
                self.b.assign(bb, Place::local(t), Rvalue::UnaryOp(op, a));
                Rvalue::Cast(kind, Operand::Move(Place::local(t)), pt)
            }
            Rvalue::Aggregate(kind, ops) => {
                // A variant of a generic type named bare in its own impl
                // (`self = Cnt.Done`) is recorded without its arguments:
                // it builds the type of the place it goes to.
                let kind = match kind {
                    AggregateKind::Adt { ty, variant } if self.bare_of(ty, pt) => {
                        AggregateKind::Adt { ty: pt, variant }
                    }
                    AggregateKind::Shared { ty, variant } if self.bare_of(ty, pt) => {
                        AggregateKind::Shared { ty: pt, variant }
                    }
                    k => k,
                };
                let ops = self.erase_parts(&place, &kind, ops);
                Rvalue::Aggregate(kind, ops)
            }
            rv => rv,
        };
        let rv = match rv {
            Rvalue::Use(o @ Operand::Const(_)) => {
                Rvalue::Use(self.fit_const(o, self.place_type(&place)))
            }
            Rvalue::Aggregate(kind, ops) => {
                let ops = self.fit_parts(&place, &kind, ops);
                Rvalue::Aggregate(kind, ops)
            }
            rv => rv,
        };
        let bb = self.cur;
        self.b.assign(bb, place, rv);
    }

    /// Whether `t` is a `ref` or `mut ref`.
    fn is_reference(&self, t: Ty) -> bool {
        matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_))
    }

    /// Whether `t` is the generic type `full` names, written with no
    /// arguments.
    fn bare_of(&self, t: Ty, full: Ty) -> bool {
        let tcx = self.tys().tcx();
        match (tcx.kind(t), tcx.kind(full)) {
            (HK::Adt { def, args }, HK::Adt { def: d2, args: a2 })
            | (HK::Shared { def, args }, HK::Shared { def: d2, args: a2 }) => {
                def == d2 && tcx.list(args).is_empty() && !tcx.list(a2).is_empty()
            }
            _ => false,
        }
    }

    /// The type of an operand's value.
    fn operand_ty(&self, op: &Operand) -> Ty {
        match op {
            Operand::Copy(p) | Operand::Move(p) => self.place_type(p),
            Operand::Const(c) => c.ty,
        }
    }

    /// The cast that widens a value of numeric type `from` into the
    /// numeric slot `to`, when they differ (design.md §5, lossless widening
    /// is implicit at a binding, an argument, a field or a return).
    fn widening(&self, from: Ty, to: Ty) -> Option<CastKind> {
        if from == to {
            return None;
        }
        let tcx = self.tys().tcx();
        let int = |k| matches!(k, HK::Int(_) | HK::UInt(_));
        let float = |k| matches!(k, HK::Float(_));
        let (f, t) = (tcx.kind(from), tcx.kind(to));
        if int(f) && int(t) {
            Some(CastKind::IntToInt)
        } else if int(f) && float(t) {
            Some(CastKind::IntToFloat)
        } else if float(f) && float(t) {
            Some(CastKind::FloatToFloat)
        } else {
            None
        }
    }

    /// Whether every value of numeric type `from` is exactly a value of `to`.
    fn lossless(&self, from: Ty, to: Ty) -> bool {
        // (signed, unsigned or float; value bits)
        let class = |t: Ty| match self.tys().tcx().kind(t) {
            HK::Int(s) => Some((
                's',
                match s {
                    IntSize::I8 => 8,
                    IntSize::I16 => 16,
                    IntSize::I32 => 32,
                    IntSize::I64 | IntSize::Isize => 64,
                    IntSize::I128 => 128,
                },
            )),
            HK::UInt(s) => Some((
                'u',
                match s {
                    UIntSize::U8 => 8,
                    UIntSize::U16 => 16,
                    UIntSize::U32 => 32,
                    UIntSize::U64 | UIntSize::Usize => 64,
                    UIntSize::U128 => 128,
                },
            )),
            // The significand's bits, the implicit one included.
            HK::Float(s) => Some((
                'f',
                match s {
                    FloatSize::BF16 => 8,
                    FloatSize::F16 => 11,
                    FloatSize::F32 => 24,
                    FloatSize::F64 => 53,
                },
            )),
            _ => None,
        };
        let (Some((fc, fb)), Some((tc, tb))) = (class(from), class(to)) else {
            return false;
        };
        match (fc, tc) {
            ('s', 's') | ('u', 'u') | ('u', 's') => fb < tb,
            ('s', 'f') => fb - 1 <= tb,
            ('u', 'f') => fb <= tb,
            ('f', 'f') => fb < tb,
            _ => false,
        }
    }

    /// The type of a branching value recorded at numeric type `t`: its
    /// widest arm. The checker's branch join keeps the first arm's type when
    /// the other only widens to it, so `if c { 0 } else { big }` is recorded
    /// at the literal's `i64` though `big` is an `i128`. An unsuffixed
    /// literal arm takes whatever type the value has.
    fn arm_width(&mut self, e: &Expr, t: Ty) -> Ty {
        match &e.kind {
            ExprKind::If {
                then_block,
                else_branch: Some(els),
                ..
            }
            | ExprKind::IfLet {
                then_block,
                else_branch: Some(els),
                ..
            } => {
                let t = match &then_block.final_expr {
                    Some(x) => self.arm_width(x, t),
                    None => t,
                };
                self.arm_width(els, t)
            }
            ExprKind::Match { arms, .. } => {
                let mut t = t;
                for a in arms {
                    t = self.arm_width(&a.body, t);
                }
                t
            }
            ExprKind::Block(b) => match &b.final_expr {
                Some(x) => self.arm_width(x, t),
                None => t,
            },
            ExprKind::Integer(_, None) | ExprKind::Float(_, None) => t,
            _ if fold_int(e, 64).is_some() => t,
            _ => match self.expr_ty(e) {
                Ok(at) if self.lossless(t, at) => at,
                _ => t,
            },
        }
    }

    /// Whether `at` is `pt` with some parts `()`: the type the checker gave
    /// a value whose type parameter it never solved.
    fn fills_unit_holes(&self, at: Ty, pt: Ty) -> bool {
        if at == pt {
            return true;
        }
        let tcx = self.tys().tcx();
        let all = |a: crate::ty::TyList, b: crate::ty::TyList| {
            let (a, b) = (tcx.list(a), tcx.list(b));
            a.len() == b.len() && a.iter().zip(&b).all(|(&x, &y)| self.fills_unit_holes(x, y))
        };
        match (tcx.kind(at), tcx.kind(pt)) {
            _ if at == self.unit() => true,
            (HK::Adt { def: d, args: x }, HK::Adt { def: e, args: y }) => d == e && all(x, y),
            (HK::Intrinsic { kind: k, args: x }, HK::Intrinsic { kind: l, args: y }) => {
                k == l && all(x, y)
            }
            (HK::Tuple(x), HK::Tuple(y)) => all(x, y),
            _ => false,
        }
    }

    /// `a` as an operand of type `want`. A value whose type the checker
    /// left with an unsolved part, lowered as `()` (the `None` of
    /// `Vec.filled(3, None)` pushed into a `Vec[Vec[Option[i64]]]`), is
    /// built at the type its slot knows, so it has the slot's size
    /// (B-2026-10-29-25).
    fn operand_filling_holes(&mut self, a: &'a Expr, want: Ty) -> R<Operand> {
        let at = self.expr_ty(a)?;
        if at == want || !self.fills_unit_holes(at, want) {
            return self.expr_operand(a);
        }
        let l = self.temp(want);
        self.expr_into(a, Place::local(l))?;
        Ok(Operand::Move(Place::local(l)))
    }

    /// `op` widened into the numeric slot `t`, if it needs it.
    fn widen(&mut self, op: Operand, t: Ty) -> Operand {
        if self.dyn_cast(&op, t).is_some() {
            return self.coerce_to_dyn(op, t);
        }
        if let Operand::Const(_) = op {
            return self.fit_const(op, t);
        }
        let Some(kind) = self.widening(self.operand_ty(&op), t) else {
            return op;
        };
        let l = self.temp(t);
        let bb = self.cur;
        self.b
            .assign(bb, Place::local(l), Rvalue::Cast(kind, op, t));
        Operand::Copy(Place::local(l))
    }

    /// Whether `p` is reached through a `shared` value, a reference or an
    /// index, so its contents cannot be moved out.
    fn borrowed_place(&self, p: &Place) -> bool {
        let mut q = Place::local(p.local);
        for el in &p.projection {
            let t = self.place_type(&q);
            if matches!(
                self.tys().tcx().kind(t),
                HK::Shared { .. } | HK::Ref(_) | HK::MutRef(_)
            ) || matches!(el, ProjElem::Index(_) | ProjElem::ConstIndex(_))
            {
                return true;
            }
            q = q.project(*el);
        }
        false
    }

    /// `let y = x` where `x` is a reference to a value that is neither
    /// `Copy` nor counted: `y` copies the reference (core semantics §4.6,
    /// §5.1), so it reads through it rather than moving the target out.
    fn ref_rebind(&mut self, value: &'a Expr, t: Ty) -> R<Option<Ty>> {
        if self.is_copy(t) || self.is_handle(t) || self.is_handle_aggregate(t) {
            return Ok(None);
        }
        if !matches!(value.kind, ExprKind::Identifier(_)) {
            return Ok(None);
        }
        let vt = self.expr_ty(value)?;
        Ok(match self.tys().tcx().kind(vt) {
            HK::Ref(i) | HK::MutRef(i) if i == t => Some(vt),
            _ => None,
        })
    }

    /// Whether `op` is a reference whose target goes into the slot `t` by
    /// value: a borrowed parameter (D5) stored into a field or a local.
    fn reads_through(&self, op: &Operand, t: Ty) -> bool {
        let tcx = self.tys().tcx();
        !matches!(op, Operand::Const(_))
            && matches!(tcx.kind(self.operand_ty(op)), HK::Ref(i) | HK::MutRef(i) if i == t)
    }

    /// The value `op` refers to, for the slot `t`: a `Copy` value copies, a
    /// handle or handle aggregate counts (§6.1), and anything else moves
    /// out of the borrow, which the borrow check refuses.
    fn read_through(&mut self, op: Operand, t: Ty) -> Operand {
        let (Operand::Copy(p) | Operand::Move(p)) = op else {
            return op;
        };
        let target = p.project(ProjElem::Deref);
        if self.is_handle(t) || self.is_handle_aggregate(t) {
            let l = self.temp(t);
            self.count_copy(target, t, Place::local(l));
            return Operand::Move(Place::local(l));
        }
        self.use_place(target, t)
    }

    /// Whether `op` is a strong handle going into the `weak` slot `t`.
    fn downgrades(&self, op: &Operand, t: Ty) -> bool {
        let tcx = self.tys().tcx();
        matches!(tcx.kind(t), HK::Weak(_)) && !matches!(tcx.kind(self.operand_ty(op)), HK::Weak(_))
    }

    /// A strong handle stored into the `weak` slot `t` is downgraded:
    /// moved into a temporary, read through a borrow into a new weak
    /// reference, and the strong handle released (design.md, "strong to
    /// weak is implicit").
    fn downgrade(&mut self, op: Operand, t: Ty) -> Operand {
        let st = self.operand_ty(&op);
        let (strong, rt) = {
            let tcx = self.tys().tcx();
            let st = match tcx.kind(st) {
                HK::Ref(i) | HK::MutRef(i) => i,
                _ => st,
            };
            (st, tcx.reference(st, false))
        };
        let src = match op {
            Operand::Copy(p) | Operand::Move(p)
                if self.operand_ty(&Operand::Copy(p.clone())) != strong =>
            {
                // A reference to the handle: borrow through it.
                p.project(ProjElem::Deref)
            }
            op => {
                let h = self.temp(strong);
                let bb = self.cur;
                self.b.assign(bb, Place::local(h), Rvalue::Use(op));
                Place::local(h)
            }
        };
        let owned = src.projection.is_empty();
        let r = self.temp(rt);
        let w = self.temp(t);
        let bb = self.cur;
        self.b.assign(
            bb,
            Place::local(r),
            Rvalue::Ref(BorrowKind::Shared, src.clone()),
        );
        self.b.assign(
            bb,
            Place::local(w),
            Rvalue::Cast(CastKind::Downgrade, Operand::Move(Place::local(r)), t),
        );
        if owned {
            let next = self.b.new_block();
            self.goto_with(
                TerminatorKind::Drop {
                    place: src,
                    target: next,
                    unwind: UnwindAction::Abort,
                },
                next,
            );
        }
        Operand::Move(Place::local(w))
    }

    /// Whether `op` is a closure, function item or function value of
    /// another kind going into the function-typed slot `t`.
    fn erases(&self, op: &Operand, t: Ty) -> bool {
        let tcx = self.tys().tcx();
        if !matches!(tcx.kind(t), HK::Fn { .. }) {
            return false;
        }
        let mut ot = self.operand_ty(op);
        if let HK::Ref(inner) | HK::MutRef(inner) = tcx.kind(ot) {
            ot = inner;
        }
        ot != t
            && matches!(
                tcx.kind(ot),
                HK::Closure { .. } | HK::FnDef { .. } | HK::Fn { .. }
            )
    }

    /// The operand an `Erase` takes: the value itself, moved out from
    /// behind a reference when it is one (which the borrow check refuses:
    /// a borrowed closure, such as a non-escaping parameter, cannot be
    /// stored).
    fn erase_source(&self, op: Operand) -> Operand {
        let ot = self.operand_ty(&op);
        match (&op, self.tys().tcx().kind(ot)) {
            (Operand::Copy(p) | Operand::Move(p), HK::Ref(_) | HK::MutRef(_)) => {
                Operand::Move(p.clone().project(ProjElem::Deref))
            }
            _ => op,
        }
    }

    /// An aggregate's parts, each closure or function item going into a
    /// function-typed field erased first.
    fn erase_parts(
        &mut self,
        place: &Place,
        kind: &AggregateKind,
        ops: Vec<Operand>,
    ) -> Vec<Operand> {
        let mut out = Vec::with_capacity(ops.len());
        for (i, o) in ops.into_iter().enumerate() {
            let tcx = self.tys().tcx();
            let slot = match kind {
                AggregateKind::Array(elem) => Some(*elem),
                AggregateKind::Tuple => tcx.field_ty(self.place_type(place), None, i as u32),
                AggregateKind::Adt { ty, variant } | AggregateKind::Shared { ty, variant } => {
                    let is_enum = tcx.adt_of(*ty).is_some_and(|(a, _)| a.is_enum);
                    tcx.field_ty(*ty, is_enum.then_some(variant.0), i as u32)
                }
                AggregateKind::Closure { .. } => None,
            };
            match slot {
                Some(t) if self.erases(&o, t) => {
                    let l = self.temp(t);
                    let bb = self.cur;
                    let o = self.erase_source(o);
                    self.b.assign(bb, l, Rvalue::Cast(CastKind::Erase, o, t));
                    out.push(Operand::Move(Place::local(l)));
                }
                Some(t) if self.downgrades(&o, t) => out.push(self.downgrade(o, t)),
                Some(t) if self.reads_through(&o, t) => out.push(self.read_through(o, t)),
                Some(t) if !matches!(o, Operand::Const(_)) => out.push(self.widen(o, t)),
                _ => out.push(o),
            }
        }
        out
    }

    /// A numeric literal in a slot of another numeric type takes the
    /// slot's (the checker records an unsuffixed literal as `i64` or `f64`
    /// wherever it sits; `let x: f64 = 2` reads the integer as a float).
    fn fit_const(&self, o: Operand, t: Ty) -> Operand {
        let Operand::Const(c) = o else {
            return o;
        };
        let tcx = self.tys().tcx();
        let int = |t| matches!(tcx.kind(t), HK::Int(_) | HK::UInt(_));
        let float = |t| matches!(tcx.kind(t), HK::Float(_));
        let kind = match c.kind {
            ConstKind::Scalar(v) if int(c.ty) && float(t) => {
                ConstKind::Float(((v as i128) as f64).to_bits())
            }
            k @ ConstKind::Scalar(_) if int(c.ty) && int(t) => k,
            k @ ConstKind::Float(_) if float(c.ty) && float(t) => k,
            kind => return Operand::Const(Const { ty: c.ty, kind }),
        };
        Operand::Const(Const { ty: t, kind })
    }

    /// An aggregate's literal parts, fitted to their slots' types.
    fn fit_parts(&self, place: &Place, kind: &AggregateKind, ops: Vec<Operand>) -> Vec<Operand> {
        let tcx = self.tys().tcx();
        let slot = |i: usize| -> Option<Ty> {
            match kind {
                AggregateKind::Array(elem) => Some(*elem),
                AggregateKind::Tuple => tcx.field_ty(self.place_type(place), None, i as u32),
                AggregateKind::Adt { ty, variant } | AggregateKind::Shared { ty, variant } => {
                    let is_enum = tcx.adt_of(*ty).is_some_and(|(a, _)| a.is_enum);
                    tcx.field_ty(*ty, is_enum.then_some(variant.0), i as u32)
                }
                AggregateKind::Closure { .. } => None,
            }
        };
        ops.into_iter()
            .enumerate()
            .map(|(i, o)| match (&o, slot(i)) {
                (Operand::Const(_), Some(t)) => self.fit_const(o, t),
                _ => o,
            })
            .collect()
    }

    /// End the current block with `kind`; continue in `next`.
    fn goto_with(&mut self, mut kind: TerminatorKind, next: BasicBlock) {
        let cancel = self.cancel_point(&mut kind);
        let bb = self.cur;
        self.b.terminate(bb, kind);
        self.cur = next;
        if let Some((check, cont, back)) = cancel {
            self.cancel_exit(check, cont, back);
        }
    }

    /// When `kind` is a call that suspends in a program that cancels tasks
    /// (`Lcx::cancel_at`): points it at a fresh block, where the check for
    /// a cancelled callee goes, and answers that block, the call's own
    /// target and, for a result that needs dropping, the place it belongs
    /// in and the temporary the call now returns into.
    #[allow(clippy::type_complexity)]
    fn cancel_point(
        &mut self,
        kind: &mut TerminatorKind,
    ) -> Option<(BasicBlock, BasicBlock, Option<(Place, Local)>)> {
        if self.in_cancel_exit || self.lcx.cancel_at.is_none() {
            return None;
        }
        let TerminatorKind::Call {
            func,
            destination,
            target: Some(target),
            ..
        } = kind
        else {
            return None;
        };
        let suspends = match func {
            Operand::Const(Const {
                kind: ConstKind::FnDef(callee),
                ..
            }) => {
                let n = callee.name.as_str();
                n == "TaskGroup.spawn"
                    || crate::mir::coroutine::suspends_native(n)
                    || self.lcx.cancel_at.as_ref().is_some_and(|a| a.contains(n))
            }
            // A call through a `dyn` slot a table fills with a coroutine.
            Operand::Const(Const {
                kind: ConstKind::DynSlot { dyn_ty, slot },
                ..
            }) => {
                let key = match self.tys().tcx().kind(*dyn_ty) {
                    HK::Dyn { trait_, .. } => {
                        Some(crate::mir::coroutine::dyn_slot_key(trait_, *slot))
                    }
                    _ => None,
                };
                self.lcx.cancel_at.as_ref().is_some_and(|a| {
                    key.is_some_and(|k| a.contains(&k)) || a.contains(crate::mir::coroutine::PANIC)
                })
            }
            // A call through a function value a coroutine is erased into,
            // or any call through a value in a program whose isolating
            // tasks leave at a panic (§11.12): the value may panic.
            f => {
                let key = crate::mir::coroutine::fn_value_key(self.tys(), self.operand_ty(f));
                self.lcx.cancel_at.as_ref().is_some_and(|a| {
                    key.is_some_and(|k| a.contains(&k)) || a.contains(crate::mir::coroutine::PANIC)
                })
            }
        };
        if !suspends {
            return None;
        }
        let cont = *target;
        let check = self.b.new_block();
        *target = check;
        let dt = self.place_type(destination);
        let back = self.needs_drop(dt).then(|| {
            let t = self.temp(dt);
            (std::mem::replace(destination, Place::local(t)), t)
        });
        Some((check, cont, back))
    }

    /// A call's cancel exit (core-semantics §11.9): in `check`, the call
    /// returned, and `__unwinding` says whether that is because its task is
    /// being torn down at a wait the callee suspended in. If not, the
    /// result moves to where it belongs (`back`) and the body goes on to
    /// `cont`. If so, the result is no value and is left alone, and the
    /// function leaves as by an error exit from here: every scope's drops,
    /// `defer`s and `errdefer`s, innermost first. The exit's own calls are
    /// not cancelled, so `__unwind(false)` stops its callees from reading
    /// the callee's teardown as theirs, and `__unwind(true)` passes the
    /// teardown on to the caller.
    ///
    /// The coroutine transform makes the waits themselves cancellable: a
    /// suspending native whose call continues to a check like this one
    /// leaves its readiness loop for the cancel exit when its task is
    /// cancelled.
    fn cancel_exit(&mut self, check: BasicBlock, cont: BasicBlock, back: Option<(Place, Local)>) {
        let resume = self.cur;
        let bool_t = self.tys().bool();
        let unwinding = self.temp(bool_t);
        let (sw, go, exit) = (self.b.new_block(), self.b.new_block(), self.b.new_block());
        let func = self.fn_operand(
            crate::mir::coroutine::UNWINDING,
            DefId(u32::MAX),
            Vec::new(),
        );
        self.b.terminate(
            check,
            TerminatorKind::Call {
                func,
                args: Vec::new(),
                destination: Place::local(unwinding),
                target: Some(sw),
                unwind: UnwindAction::Abort,
            },
        );
        self.b.terminate(
            sw,
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(unwinding)),
                targets: SwitchTargets::if_else(exit, go),
            },
        );
        self.cur = go;
        if let Some((place, t)) = back {
            self.assign(place, Rvalue::Use(Operand::Move(Place::local(t))));
        }
        self.goto(cont);
        self.cur = exit;
        self.in_cancel_exit = true;
        let unit = self.unit();
        let u = self.temp(unit);
        let unwind = crate::mir::coroutine::UNWIND;
        self.call_native(unwind, vec![bool_const(bool_t, false)], Place::local(u));
        // An error is recorded where it happens.
        let _ = self.exit_to(0, true);
        self.call_native(unwind, vec![bool_const(bool_t, true)], Place::local(u));
        self.diverge(TerminatorKind::Return);
        self.in_cancel_exit = false;
        self.cur = resume;
    }

    fn goto(&mut self, target: BasicBlock) {
        let bb = self.cur;
        self.b.terminate(bb, TerminatorKind::Goto { target });
    }

    /// End the current block with a terminator that does not fall through,
    /// and continue in a fresh (unreachable) block.
    /// `lock m x { body }`: the body, with `x` naming the value the
    /// `Mutex` `m` holds (`m` itself when there is no alias). It is
    /// `m.lock()`'s guard in a scope of its own: `acquire` waits until no
    /// other task holds `m`, `x` is the guard's `value`, and the guard's
    /// drop releases `m` on every exit from the body (B-2026-10-19-23).
    fn lock_block(
        &mut self,
        e: &'a Expr,
        mutex: &'a Expr,
        alias: &Option<String>,
        body: &'a Block,
        dest: Place,
    ) -> R<()> {
        let name = match (alias, &mutex.kind) {
            (Some(a), _) => a.clone(),
            (None, ExprKind::Identifier(n)) => n.clone(),
            _ => return self.unsupported(e.span, "a `lock` with no name for its value"),
        };
        let Some(&sym) = self.lcx.binding_syms.get(&(e.id, name)) else {
            return self.unsupported(e.span, "a `lock` with no name for its value");
        };
        let (mp, mt) = self.deref_place(mutex, false)?;
        let inner = match self.tys().tcx().kind(mt) {
            HK::Adt { args, .. } if self.tys().display(mt).starts_with("Mutex[") => {
                self.tys().tcx().list(args)[0]
            }
            _ => return self.unsupported(e.span, "a `lock` of other than a `Mutex`"),
        };
        let rt = self.tys().tcx().reference(mt, false);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, mp));
        let gt = self.tys().tcx().reference(inner, true);
        let g = self.temp(gt);
        let Some(guard_t) = self.library_struct("MutexGuard", &[inner]) else {
            return self.unsupported(e.span, "a `lock` without the library's `MutexGuard`");
        };
        let acquire = format!("{}.acquire", self.tys().display(mt));
        self.call_native(
            &acquire,
            vec![Operand::Copy(Place::local(r))],
            Place::local(g),
        );
        self.push_scope();
        let guard = self.temp(guard_t);
        let kind = self.adt_aggregate(guard_t, 0);
        self.assign(
            guard,
            Rvalue::Aggregate(
                kind,
                vec![
                    Operand::Move(Place::local(g)),
                    Operand::Copy(Place::local(r)),
                ],
            ),
        );
        self.schedule(ScopeEntry::Drop(Place::local(guard)));
        self.captured.insert(
            sym,
            Place::local(guard).field(0, gt).project(ProjElem::Deref),
        );
        let res = self.block_into(body, dest);
        self.captured.remove(&sym);
        res?;
        self.pop_scope()
    }

    /// `o?.f`: `f` of the value `o` holds, or `None` when it holds none.
    /// A field that is itself an `Option` is the result, not wrapped again
    /// (`u.address?.city` is an `Option[City]`).
    fn optional_chain(&mut self, e: &'a Expr, object: &'a Expr, field: &str, dest: Place) -> R<()> {
        let rt = self.expr_ty(e)?;
        let (base, bt) = self.deref_place(object, false)?;
        let tcx = self.tys().tcx();
        let idx = |t: Ty, want: &str| {
            tcx.adt_of(t)
                .and_then(|(adt, _)| adt.variants.iter().position(|v| v.name == want))
                .map(|i| i as u32)
        };
        let (Some(some), Some(r_some), Some(r_none)) =
            (idx(bt, "Some"), idx(rt, "Some"), idx(rt, "None"))
        else {
            return self.unsupported(e.span, "`?.` of other than an `Option`");
        };
        let Some(st) = tcx.field_ty(bt, Some(some), 0) else {
            return self.unsupported(e.span, "`?.` of other than an `Option`");
        };
        let Some((fidx, ft)) = self.field_of(st, None, field) else {
            return self.unsupported(e.span, &format!("the field `{field}`"));
        };
        let through_ref = base.projection.iter().any(|p| matches!(p, ProjElem::Deref));
        if through_ref && !self.is_copy(ft) {
            return self.unsupported(e.span, "`?.` moving out of a borrow");
        }
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let tag = self.temp(isize_t);
        self.assign(tag, Rvalue::Discriminant(base.clone()));
        let is_some = self.temp(self.tys().bool());
        self.assign(
            is_some,
            Rvalue::BinaryOp(
                BinOp::Eq,
                Operand::Copy(Place::local(tag)),
                Operand::Const(Const {
                    ty: isize_t,
                    kind: ConstKind::Scalar(some as u128),
                }),
            ),
        );
        let (yes, no, join) = (self.b.new_block(), self.b.new_block(), self.b.new_block());
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(is_some)),
                targets: SwitchTargets::if_else(yes, no),
            },
            no,
        );
        self.build_variant(rt, r_none, Vec::new(), dest.clone());
        self.goto(join);
        self.cur = yes;
        let q = base
            .project(ProjElem::Downcast(VariantIdx(some)))
            .field(0, st)
            .field(fidx, ft);
        let op = self.use_place(q, ft);
        if ft == rt {
            self.assign(dest, Rvalue::Use(op));
        } else {
            self.build_variant(rt, r_some, vec![op], dest);
        }
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    /// `inner as T` into `dest`, `T` being `e`'s type.
    fn cast_into(&mut self, e: &'a Expr, inner: &'a Expr, dest: Place) -> R<()> {
        let mut from = self.expr_ty(inner)?;
        let to = self.expr_ty(e)?;
        // A borrowed scalar (`ref self` in `impl Serialize for i8`) casts
        // its value: `self as i64` reads through the reference.
        let pointee = match self.tys().tcx().kind(from) {
            HK::Ref(t) | HK::MutRef(t)
                if !matches!(self.tys().tcx().kind(t), HK::RawPtr { .. }) =>
            {
                Some(t)
            }
            _ => None,
        };
        let o = match pointee {
            Some(t) => {
                from = t;
                self.owned_operand(inner, t)?
            }
            None => self.expr_operand(inner)?,
        };
        let kind = {
            let tcx = self.tys().tcx();
            let int = |t| matches!(tcx.kind(t), HK::Int(_) | HK::UInt(_));
            let float = |t| matches!(tcx.kind(t), HK::Float(_));
            let (char_k, bool_k) = (|t| tcx.kind(t) == HK::Char, |t| tcx.kind(t) == HK::Bool);
            match (int(from) || from == to, float(from), int(to), float(to)) {
                _ if from == to => None,
                _ if char_k(to) && matches!(tcx.kind(from), HK::UInt(UIntSize::U8)) => {
                    Some(CastKind::IntToChar)
                }
                _ if char_k(from) && int(to) => Some(CastKind::CharToInt),
                _ if bool_k(from) && int(to) => Some(CastKind::BoolToInt),
                _ if matches!(
                    (tcx.kind(from), tcx.kind(to)),
                    (HK::RawPtr { .. }, HK::RawPtr { .. })
                ) =>
                {
                    Some(CastKind::PtrToPtr)
                }
                (true, _, true, _) => Some(CastKind::IntToInt),
                (true, _, _, true) => Some(CastKind::IntToFloat),
                (_, true, true, _) => Some(CastKind::FloatToInt),
                (_, true, _, true) => Some(CastKind::FloatToFloat),
                _ => return self.unsupported(e.span, "this cast"),
            }
        };
        match kind {
            None => self.assign(dest, Rvalue::Use(o)),
            // A cast into a wider place (`let y: i64 = c as i32`) is the
            // cast, then the implicit widening `assign` gives a value
            // (B-2026-10-13-21).
            Some(k) if self.widening(to, self.place_type(&dest)).is_some() => {
                let t = self.temp(to);
                self.assign(t, Rvalue::Cast(k, o, to));
                self.assign(dest, Rvalue::Use(Operand::Move(Place::local(t))));
            }
            Some(k) => self.assign(dest, Rvalue::Cast(k, o, to)),
        }
        Ok(())
    }

    /// Panics unless the value in `v` satisfies the `where` predicate of
    /// the refinement or distinct type `name`, when it has one: the
    /// predicate, with `self` the value.
    fn require_refinement(&mut self, name: &str, v: Local) -> R<()> {
        let Some(ok) = self.refinement_holds(name, v)? else {
            return Ok(());
        };
        let pass = self.b.new_block();
        let fail = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(ok)),
                targets: SwitchTargets::if_else(pass, fail),
            },
            fail,
        );
        self.diverge(TerminatorKind::Abort {
            reason: AbortReason::Panic,
        });
        self.cur = pass;
        Ok(())
    }

    /// Whether the value in `v` satisfies the `where` predicate of `name`,
    /// as a `bool` local; `None` when `name` has no predicate.
    fn refinement_holds(&mut self, name: &str, v: Local) -> R<Option<Local>> {
        let Some(&pred) = self.lcx.refined.get(name) else {
            return Ok(None);
        };
        let bool_t = self.tys().bool();
        let ok = self.temp(bool_t);
        let saved = self.self_local.replace(v);
        let c = self.operand_at(pred, bool_t);
        self.self_local = saved;
        let c = c?;
        self.assign(Place::local(ok), Rvalue::Use(c));
        Ok(Some(ok))
    }

    /// `T.try_from(x)` of a refinement `T`: `Ok(x)` when `x` satisfies
    /// `T`'s predicate, else `Err` of the message saying it does not.
    fn refinement_try_from(
        &mut self,
        e: &'a Expr,
        name: &str,
        arg: &'a Expr,
        dest: Place,
    ) -> R<()> {
        let rt = self.expr_ty(e)?;
        let tcx = self.tys().tcx();
        let idx = |want: &str| {
            tcx.adt_of(rt)
                .and_then(|(adt, _)| adt.variants.iter().position(|v| v.name == want))
                .map(|i| i as u32)
        };
        let (Some(ok_idx), Some(err_idx)) = (idx("Ok"), idx("Err")) else {
            return self.unsupported(e.span, &format!("`{name}.try_from` of no `Result`"));
        };
        let (Some(pt), Some(et)) = (
            tcx.field_ty(rt, Some(ok_idx), 0),
            tcx.field_ty(rt, Some(err_idx), 0),
        ) else {
            return self.unsupported(e.span, &format!("`{name}.try_from` of no `Result`"));
        };
        // A distinct type's value wraps its base's; a refinement's is it.
        let distinct = self.distinct_base(pt);
        let v = self.temp_of(arg, distinct.unwrap_or(pt))?;
        let payload = |s: &mut Self| {
            if distinct.is_none() {
                return Operand::Move(Place::local(v));
            }
            let w = s.temp(pt);
            s.wrap_distinct(pt, v, Place::local(w));
            Operand::Move(Place::local(w))
        };
        let Some(ok) = self.refinement_holds(name, v)? else {
            let op = payload(self);
            self.build_variant(rt, ok_idx, vec![op], dest);
            return Ok(());
        };
        let (pass, fail, join) = (self.b.new_block(), self.b.new_block(), self.b.new_block());
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(ok)),
                targets: SwitchTargets::if_else(pass, fail),
            },
            pass,
        );
        let op = payload(self);
        self.build_variant(rt, ok_idx, vec![op], dest.clone());
        self.goto(join);
        self.cur = fail;
        let msg = self.temp(et);
        let text = self.static_str(&format!("value does not satisfy refinement `{name}`"));
        self.call_native("String.from", vec![text], Place::local(msg));
        self.build_variant(rt, err_idx, vec![Operand::Move(Place::local(msg))], dest);
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    fn diverge(&mut self, kind: TerminatorKind) {
        // In a program with an isolating group, a panic is a call that a
        // task of one leaves by its cancel exit (core-semantics §11.12).
        if let TerminatorKind::Abort { reason } = &kind {
            let panics = crate::mir::coroutine::PANIC;
            if !self.in_cancel_exit
                && self
                    .lcx
                    .cancel_at
                    .as_ref()
                    .is_some_and(|a| a.contains(panics))
            {
                let it = self.tys().tcx().intern(HK::Int(IntSize::I64));
                let code = Operand::Const(Const {
                    ty: it,
                    kind: ConstKind::Scalar(u128::from(reason.code())),
                });
                let unit = self.unit();
                let u = self.temp(unit);
                self.call_native(panics, vec![code], Place::local(u));
                self.diverge(TerminatorKind::Unreachable);
                return;
            }
        }
        let next = self.b.new_block();
        self.goto_with(kind, next);
    }

    fn temp(&mut self, t: Ty) -> Local {
        self.b.temp(t)
    }

    /// A temporary that is dropped at the end of the innermost scope (the
    /// statement's, for a statement's temporaries).
    /// A temporary holding `e`'s value, dropped at the end of the scope.
    /// Its drop is scheduled once the value exists, so it drops before
    /// the temporaries made while computing it (core semantics §7.4).
    fn temp_of(&mut self, e: &'a Expr, t: Ty) -> R<Local> {
        let l = self.temp(t);
        self.expr_into(e, Place::local(l))?;
        if self.needs_drop(t) {
            self.schedule(ScopeEntry::Drop(Place::local(l)));
        }
        Ok(l)
    }

    /// The place `e` names when it is an owned local's (or a part of one
    /// reached without a reference), and holds no `shared` handle.
    fn owned_place(&mut self, e: &'a Expr) -> R<Option<Place>> {
        if !is_place_expr(e) {
            return Ok(None);
        }
        if let ExprKind::Identifier(_) = &e.kind {
            let local = matches!(self.lcx.res.get(&e.id), Some(Res::Local(s)) if self.locals.contains_key(s));
            if !local {
                return Ok(None);
            }
        }
        let p = self.expr_place(e, false)?;
        let t = self.place_type(&p);
        let through_handle = (0..p.projection.len()).any(|i| {
            let prefix = Place {
                local: p.local,
                projection: p.projection[..i].to_vec(),
            };
            let pt = self.place_type(&prefix);
            self.is_handle(pt)
                || self
                    .tys()
                    .tcx()
                    .adt_of(pt)
                    .is_some_and(|(a, _)| a.has_drop_impl)
        });
        let owned = !through_handle
            && !p.projection.contains(&ProjElem::Deref)
            && match self.tys().tcx().kind(t) {
                HK::Adt { .. } => !self
                    .tys()
                    .tcx()
                    .adt_of(t)
                    .is_some_and(|(a, _)| a.has_drop_impl),
                HK::Tuple(_) | HK::Array { .. } => true,
                _ => false,
            };
        Ok(owned.then_some(p))
    }

    fn scoped_temp(&mut self, t: Ty) -> Local {
        let l = self.temp(t);
        if self.needs_drop(t) {
            self.schedule(ScopeEntry::Drop(Place::local(l)));
        }
        l
    }

    fn schedule(&mut self, e: ScopeEntry<'a>) {
        self.scopes
            .last_mut()
            .expect("a body always has a scope")
            .push(e);
    }

    fn push_scope(&mut self) {
        self.scopes.push(Vec::new());
    }

    /// Leave the innermost scope normally: its drops and `defer` bodies in
    /// reverse order of introduction.
    fn pop_scope(&mut self) -> R<()> {
        let entries = self.scopes.pop().expect("scope underflow");
        self.exit_entries(&entries, false)
    }

    fn exit_entries(&mut self, entries: &[ScopeEntry<'a>], error: bool) -> R<()> {
        for e in entries.iter().rev() {
            match e {
                ScopeEntry::Drop(p) => {
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Drop {
                            place: p.clone(),
                            target: next,
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                }
                ScopeEntry::Defer(body) => self.defer_body(body)?,
                ScopeEntry::ErrDefer(body, None) if error => self.defer_body(body)?,
                // A cancelled task returns no error for the binding to name.
                ScopeEntry::ErrDefer(body, Some((name, node))) if error && !self.in_cancel_exit => {
                    self.errdefer_bound(body, name, *node)?
                }
                ScopeEntry::ErrDefer(..) => {}
                ScopeEntry::Storage(l) => {
                    let bb = self.cur;
                    self.b.push(bb, StatementKind::StorageDead(*l));
                }
                ScopeEntry::Unreverse(v, mt, native) => self.reverse_vec(*v, *mt, native),
                ScopeEntry::FsExit(id, r) => {
                    let t = self.unit();
                    let u = self.temp(t);
                    self.call_native(
                        &format!("{r}.exit"),
                        vec![Operand::Copy(Place::local(*id))],
                        Place::local(u),
                    );
                }
            }
        }
        Ok(())
    }

    /// `v.reverse()` of the `Vec` in `v`, through `native`.
    fn reverse_vec(&mut self, v: Local, mt: Ty, native: &str) {
        let r = self.temp(mt);
        self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(v)));
        let t = self.unit();
        let u = self.temp(t);
        self.call_native(
            native,
            vec![Operand::Move(Place::local(r))],
            Place::local(u),
        );
    }

    fn defer_body(&mut self, body: &'a Block) -> R<()> {
        let t = self.unit();
        let tmp = self.temp(t);
        self.block_into(body, Place::local(tmp))
    }

    /// `errdefer(e) { .. }` on the error exit: `e` borrows the `Err`
    /// payload of the value being returned, for the body only.
    fn errdefer_bound(&mut self, body: &'a Block, name: &str, node: NodeId) -> R<()> {
        let (value, ret) = self.fn_value_place();
        let err = self.error_variant(ret);
        let et = err.and_then(|vi| self.tys().tcx().field_ty(ret, Some(vi), 0));
        let (Some(vi), Some(et)) = (err, et) else {
            return self.unsupported(body.span, "an `errdefer` binding outside a `Result`");
        };
        let payload = value
            .project(ProjElem::Downcast(VariantIdx(vi)))
            .field(0, et);
        self.push_scope();
        let mut binds = Vec::new();
        self.bind_one(name, node, payload, et, true, &mut binds);
        for (l, t) in binds {
            self.declare(l, t);
        }
        self.defer_body(body)?;
        self.pop_scope()
    }

    /// Run the exit sequence of every scope above `depth`, innermost first,
    /// without popping them (an early exit).
    fn exit_to(&mut self, depth: usize, error: bool) -> R<()> {
        let mut i = self.scopes.len();
        while i > depth {
            i -= 1;
            let entries = std::mem::take(&mut self.scopes[i]);
            let r = self.exit_entries(&entries, error);
            self.scopes[i] = entries;
            r?;
        }
        Ok(())
    }

    // ── functions ───────────────────────────────────────────────────

    /// A literal static's initializer: the literal at `t`, which is the
    /// type of the `ref` slot it was lent to with the reference removed.
    fn lower_literal_init(&mut self, e: &'a Expr, t: Ty) -> R<()> {
        let ret = Place::local(Local::RETURN_PLACE);
        let op = match &e.kind {
            ExprKind::StringLit(s) if matches!(self.tys().tcx().kind(t), HK::Str) => {
                let op = self.static_str(s);
                self.call_native("String.from", vec![op], ret.clone());
                None
            }
            ExprKind::StringLit(s) => Some(self.static_str(s)),
            _ => match self.constant(e)? {
                // The checker may type the literal as the slot (`ref i64`).
                Some(c) => Some(Operand::Const(Const {
                    ty: t,
                    kind: c.kind,
                })),
                None => return self.unsupported(e.span, "this literal in a `ref` slot"),
            },
        };
        if let Some(op) = op {
            self.assign(ret, Rvalue::Use(op));
        }
        self.return_exit()?;
        self.scopes.clear();
        Ok(())
    }

    fn lower_static_init(&mut self, value: &'a Expr) -> R<()> {
        let ret = Place::local(Local::RETURN_PLACE);
        self.push_scope();
        self.expr_into(value, ret)?;
        self.pop_scope()?;
        self.return_exit()?;
        self.scopes.clear();
        Ok(())
    }

    fn lower_fn(
        &mut self,
        f: &'a Function,
        impl_target: Option<(DefId, usize)>,
        fn_params: &[Option<Ty>],
    ) {
        let _ = self.lower_fn_inner(f, impl_target, fn_params);
    }

    fn lower_fn_inner(
        &mut self,
        f: &'a Function,
        impl_target: Option<(DefId, usize)>,
        fn_params: &[Option<Ty>],
    ) -> R<()> {
        self.impl_target = impl_target;
        self.push_scope();
        if let Some(mode) = &f.self_param {
            let seen = impl_target
                .is_none_or(|(_, n)| n == 0)
                .then(|| self.lcx.self_tys.get(&self.b.instance().def).copied())
                .flatten();
            let t = match seen {
                Some(t) => t,
                // A blanket impl's `self` is its parameter, the receiver.
                None if self.lcx.is_blanket_fn(self.b.instance().def) => self.args[0],
                // A trait's default body run on a `dyn` value: `Self`.
                None if self.lcx.fns[&self.b.instance().def].impl_dyn.is_some() => self.args[0],
                None if self.lcx.fns[&self.b.instance().def].impl_slice => {
                    let elem = self.args[0];
                    self.tys().tcx().intern(HK::Slice {
                        elem,
                        mutable: false,
                    })
                }
                None => {
                    let Some((target, n)) = impl_target else {
                        return self.unsupported(f.span, "a `self` parameter outside an impl");
                    };
                    let args = self.args.clone();
                    let def = self.b.instance().def;
                    match self.lcx.fn_self_written(def, &args).filter(|_| n > 0) {
                        Some(Ok(t)) => t,
                        Some(Err(e)) => return self.unsupported(f.span, &e),
                        None => {
                            let tcx = self.tys().tcx();
                            let params = self.lcx.fns[&def]
                                .target_args(&self.args[..n.min(self.args.len())]);
                            let target_ty = tcx.adt(target, &params);
                            match self.lcx.convert(target_ty) {
                                Ok(t) => t,
                                Err(e) => return self.unsupported(f.span, &e),
                            }
                        }
                    }
                }
            };
            let t = match self.self_mode(f, mode.clone(), t) {
                SelfParam::Owned => t,
                SelfParam::Ref => self.tys().tcx().reference(t, false),
                SelfParam::MutRef => self.tys().tcx().reference(t, true),
            };
            let l = self.b.arg("self", t);
            self.self_local = Some(l);
            if self.needs_drop(t) {
                self.schedule(ScopeEntry::Drop(Place::local(l)));
            }
        }
        // A destructuring parameter is an argument of its own; its names
        // bind once every argument is declared, as a `let` would.
        let mut destructured = Vec::new();
        for (i, p) in f.params.iter().enumerate() {
            let t = match fn_params.get(i).copied().flatten() {
                Some(t) => t,
                None => {
                    let t = self.node_ty(p.pattern.id, p.span)?;
                    self.param_mode_ty(p, t)
                }
            };
            let PatternKind::Binding(name) = &p.pattern.kind else {
                let l = self.b.arg("arg", t);
                if self.needs_drop(t) {
                    self.schedule(ScopeEntry::Drop(Place::local(l)));
                }
                destructured.push((&p.pattern, l, t));
                continue;
            };
            let l = self.b.arg(name, t);
            if let Some(&sym) = self.lcx.binding_syms.get(&(p.pattern.id, name.clone())) {
                self.locals.insert(sym, l);
            }
            if self.needs_drop(t) {
                self.schedule(ScopeEntry::Drop(Place::local(l)));
            }
        }
        self.bind_destructured(destructured)?;
        // See [`Body::clause_names_var`].
        self.b.clause_names_var = f.effects.as_ref().is_some_and(|c| {
            c.items
                .iter()
                .any(|i| matches!(i, ast::EffectItem::Variable(_)))
        });
        if self
            .lcx
            .signatures_only_from
            .is_some_and(|from| f.span.offset >= from)
            && !self
                .self_local
                .is_some_and(|l| refs_only_receiver(self.tys(), self.b.local_ty(l)))
        {
            // Parameters only: the body ends unreachable (`finish`).
            self.scopes.clear();
            return Ok(());
        }
        self.contracts_on_entry(f)?;
        // The body's own scope sits inside the parameters' (D6). Falling
        // off the end is a return like any other, so a tail `Err(..)` runs
        // the `errdefer` bodies too.
        let ret = Place::local(Local::RETURN_PLACE);
        self.push_scope();
        self.note_escaping_lets(&f.body);
        if let Some(e) = &f.body.final_expr {
            self.note_returned_closures(e);
        }
        self.block_stmts(&f.body)?;
        match &f.body.final_expr {
            Some(e) => {
                self.push_scope();
                self.expr_into(e, ret)?;
                self.pop_scope()?;
            }
            None => self.assign(ret, Rvalue::Use(unit_const(self.unit()))),
        }
        self.return_exit()?;
        self.scopes.clear();
        Ok(())
    }

    /// Bind the names of each destructuring parameter from its argument.
    fn bind_destructured(&mut self, params: Vec<(&'a Pattern, Local, Ty)>) -> R<()> {
        for (pat, l, t) in params {
            let mut binds = Vec::new();
            self.bind_irrefutable(pat, Place::local(l), t, &mut binds)?;
            for (l, t) in binds {
                self.declare(l, t);
            }
        }
        Ok(())
    }

    /// A function's contracts on entry (design.md § Contracts): each
    /// `requires` must hold, and each `old(e)` its `ensures` clauses read
    /// is evaluated now. An `ensures(result)` clause reads the return place.
    fn contracts_on_entry(&mut self, f: &'a Function) -> R<()> {
        self.b.suspends = f.effects.as_ref().is_some_and(|e| {
            e.items.iter().any(|i| {
                matches!(i, ast::EffectItem::Verb(v) if matches!(v.kind, ast::EffectVerbKind::Suspends))
            })
        });
        // A release build strips the contracts (design.md § Contracts).
        if release_strips("KARAC_STRIP_CONTRACTS") {
            return Ok(());
        }
        for r in &f.requires {
            self.contract_check(r, "requires")?;
        }
        let mut olds = Vec::new();
        for clause in &f.ensures {
            old_calls(&clause.body, &mut olds);
            if let Some(name) = &clause.param {
                let key = (name.clone(), clause.span.offset, clause.span.length);
                if let Some(&sym) = self.lcx.unbound_vars.get(&key) {
                    self.locals.insert(sym, Local::RETURN_PLACE);
                }
            }
        }
        for o in olds {
            let ExprKind::Call { args, .. } = &o.kind else {
                continue;
            };
            let [arg] = args.as_slice() else {
                return self.unsupported(o.span, "this `old`");
            };
            let t = self.expr_ty(&arg.value)?;
            let l = self.temp(t);
            let bb = self.cur;
            self.b.push(bb, StatementKind::StorageLive(l));
            if self.is_copy(t) || !is_place_expr(&arg.value) {
                self.expr_into(&arg.value, Place::local(l))?;
            } else {
                let p = self.expr_place(&arg.value, false)?;
                self.clone_into(p, t, Place::local(l));
            }
            self.declare(l, t);
            self.old_vals.insert(o.id, l);
        }
        self.ensures = &f.ensures;
        Ok(())
    }

    /// Aborts unless the contract condition `c` holds (a panic: exit 101),
    /// with the `contract violated: <what> clause` message at `c`
    /// (B-2026-10-23-18).
    fn contract_check(&mut self, c: &'a Expr, what: &str) -> R<()> {
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo {
            span: c.span,
            ..outer
        });
        let r = self.contract_check_here(c, what);
        self.b.set_source_info(outer);
        r
    }

    fn contract_check_here(&mut self, c: &'a Expr, what: &str) -> R<()> {
        let bool_t = self.tys().bool();
        let v = self.temp(bool_t);
        // An abort while the predicate runs, in it or in a function it
        // calls, is the predicate's panic rather than a violation (design.md
        // § Contracts rule 2).
        let unit = self.tys().unit();
        let l = self.temp(unit);
        self.call_native("contract_enter", Vec::new(), Place::local(l));
        self.push_scope();
        self.expr_into(c, Place::local(v))?;
        self.pop_scope()?;
        let l = self.temp(unit);
        self.call_native("contract_exit", Vec::new(), Place::local(l));
        let bad = self.b.new_block();
        let ok = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(v)),
                targets: SwitchTargets::if_else(ok, bad),
            },
            bad,
        );
        let msg = self.static_str(&format!("contract violated: {what} clause"));
        let l = self.temp(unit);
        self.call_native("panic_message", vec![msg], Place::local(l));
        self.diverge(TerminatorKind::Abort {
            reason: AbortReason::Panic,
        });
        self.cur = ok;
        Ok(())
    }

    // ── blocks and statements ───────────────────────────────────────

    fn block_into(&mut self, block: &'a Block, dest: Place) -> R<()> {
        self.push_scope();
        self.note_escaping_lets(block);
        self.block_stmts(block)?;
        match &block.final_expr {
            // A value in a `()` slot (the arm of an `if` with no `else`)
            // is discarded, as a statement's is: built, then dropped.
            Some(e) if self.discards(e, &dest)? => {
                self.push_scope();
                let t = self.expr_ty(e)?;
                self.temp_of(e, t)?;
                self.pop_scope()?;
                self.assign(dest, Rvalue::Use(unit_const(self.unit())));
            }
            Some(e) => {
                self.push_scope();
                self.expr_into(e, dest)?;
                self.pop_scope()?;
            }
            None => self.assign(dest, Rvalue::Use(unit_const(self.unit()))),
        }
        self.pop_scope()
    }

    /// A block's statements, in order: recorded as an auto-par candidate
    /// when the build records them, and with the runs its verdict named
    /// lowered as tasks when it said yes (M4 item 14). Nothing in a
    /// `seq { .. }` is either.
    fn block_stmts(&mut self, block: &'a Block) -> R<()> {
        if self.seq_depth == 0 && block.stmts.len() > 1 {
            let groups = match &self.lcx.auto_par {
                AutoPar::Off => None,
                AutoPar::Record => return self.auto_par_record_stmts(block),
                AutoPar::Apply(hints) => {
                    let key = (self.name.clone(), block.span.offset, block.span.length);
                    hints.stmts.get(&key).cloned()
                }
            };
            if let Some(groups) = groups {
                let mut k = 0;
                while k < block.stmts.len() {
                    let run = groups.iter().find(|g| g.stmts.first() == Some(&k));
                    if let Some(g) = run {
                        let end = k + g.stmts.len();
                        let consecutive = g.stmts.iter().copied().eq(k..end);
                        let starts: Option<Vec<usize>> = g
                            .starts
                            .iter()
                            .map(|&s| s.checked_sub(k).filter(|&s| s < end - k))
                            .collect();
                        let tasks = match starts {
                            Some(starts) if consecutive && end <= block.stmts.len() => {
                                self.stmt_tasks(&block.stmts[k..end], &starts)?
                            }
                            _ => false,
                        };
                        if tasks {
                            k = end;
                            continue;
                        }
                    }
                    self.stmt(&block.stmts[k])?;
                    k += 1;
                }
                return Ok(());
            }
        }
        for s in &block.stmts {
            self.stmt(s)?;
        }
        Ok(())
    }

    /// A block's statements, each recorded as one branch of an auto-par
    /// candidate, its blocks.
    fn auto_par_record_stmts(&mut self, block: &'a Block) -> R<()> {
        // Outer before inner, as `par_regions` are.
        let k = self.b.auto_par_candidates.len();
        self.b.auto_par_candidates.push(ParRegion {
            kind: ParKind::Block,
            span: block.span,
            branches: Vec::new(),
        });
        for s in &block.stmts {
            let entry = self.branch_begin();
            self.stmt(s)?;
            self.candidate_branch_end(k, entry);
        }
        Ok(())
    }

    /// Ends a branch of auto-par candidate `k` begun at `entry`, recording
    /// its blocks, and continues in a fresh block.
    fn candidate_branch_end(&mut self, k: usize, entry: BasicBlock) {
        let after = self.b.new_block();
        let end = self.b.block_count() as u32;
        let blocks = (entry.0..end)
            .filter(|&i| i != after.0)
            .map(BasicBlock)
            .collect();
        self.b.auto_par_candidates[k].branches.push(blocks);
        self.goto(after);
        self.cur = after;
    }

    /// A run of statements an auto-par verdict said may run together, as
    /// tasks, as a statement `par {}` runs its branches: one for each of
    /// `starts` (indices into `run`), which runs the statements from it to
    /// the next in order. The `let`s bind their results once all are
    /// joined. `false`, with nothing lowered, for a run with a statement
    /// that is not a `let` of one name or an expression, or whose value is
    /// a reference, a function or never returns: the run then stays in
    /// order.
    fn stmt_tasks(&mut self, run: &'a [Stmt], starts: &[usize]) -> R<bool> {
        let mut es: Vec<&'a Expr> = Vec::new();
        let mut slots = Vec::new();
        for s in run {
            let (e, slot) = match &s.kind {
                StmtKind::Let {
                    pattern, value, ty, ..
                } => {
                    let PatternKind::Binding(name) = &pattern.kind else {
                        return Ok(false);
                    };
                    if self.is_fn_typed(pattern.id) {
                        return Ok(false);
                    }
                    let t = self.node_ty(pattern.id, pattern.span)?;
                    if ty.is_none()
                        && (self.ref_rebind(value, t)?.is_some()
                            || (is_branching(value) && self.arm_width(value, t) != t))
                    {
                        return Ok(false);
                    }
                    if self.expr_ty(value)? != t {
                        return Ok(false);
                    }
                    (value, Some((name.as_str(), pattern.id)))
                }
                StmtKind::Expr(e) if self.discarded_dbg(e).is_none() => (e, None),
                _ => return Ok(false),
            };
            // A task's value outlives the task, so it holds no borrow of
            // what the task owns (`ps.iter().min_by_key(..)`, an
            // `Option[ref P]`).
            let t = self.expr_ty(e)?;
            if crate::mir::borrowck::holds_borrow(self.tys(), t)
                || matches!(self.tys().tcx().kind(t), HK::Never | HK::Fn { .. })
            {
                return Ok(false);
            }
            es.push(e);
            slots.push((slot, t));
        }
        // A task takes what its statement moves, so a binding one statement
        // moves (on any path, a `return` included) and another names keeps
        // the run in order.
        let caps: Vec<Vec<SymbolId>> = es.iter().map(|e| self.closure_captures(e)).collect();
        for (k, e) in es.iter().enumerate() {
            self.task_moves = true;
            let moved = self.moved_captures(e, &caps[k]);
            self.task_moves = false;
            let shared = |s: &SymbolId| {
                caps.iter()
                    .enumerate()
                    .any(|(j, c)| j != k && c.contains(s))
            };
            if moved.iter().any(shared) {
                return Ok(false);
            }
        }
        // The tasks: a statement of its own, or a chunk of consecutive
        // ones evaluated in order as a tuple, where each statement is a
        // field (B-2026-10-28-10).
        let mut bounds: Vec<usize> = starts.iter().copied().filter(|&k| k < es.len()).collect();
        bounds.push(0);
        bounds.sort_unstable();
        bounds.dedup();
        bounds.push(es.len());
        let mut tasks: Vec<&'a Expr> = Vec::new();
        let mut task_tys: Vec<Ty> = Vec::new();
        // Where each statement's value is: its task, and its field there.
        let mut at: Vec<(usize, Option<u32>)> = Vec::new();
        for w in bounds.windows(2) {
            let (a, b) = (w[0], w[1]);
            let tys: Vec<Ty> = slots[a..b].iter().map(|&(_, t)| t).collect();
            let chunk = match b - a {
                1 => None,
                _ => self.stmt_chunk(&run[a], &es[a..b], &tys),
            };
            match chunk {
                Some(x) => {
                    for j in 0..b - a {
                        at.push((tasks.len(), Some(j as u32)));
                    }
                    tasks.push(x);
                    task_tys.push(self.tys().tcx().tuple(&tys));
                }
                None => {
                    for k in a..b {
                        at.push((tasks.len(), None));
                        tasks.push(es[k]);
                        task_tys.push(slots[k].1);
                    }
                }
            }
        }
        let region = self.open_par_region(ParKind::Block, run[0].span);
        let tt = self.tys().tcx().tuple(&task_tys);
        let tup = self.temp(tt);
        self.push_scope();
        self.par_tasks(region, &tasks, Place::local(tup), true)?;
        let mut binds = Vec::new();
        for (k, (slot, t)) in slots.into_iter().enumerate() {
            let (task, part) = at[k];
            let of_task = Place::local(tup).field(task as u32, task_tys[task]);
            let field = Operand::Move(match part {
                Some(j) => of_task.field(j, t),
                None => of_task,
            });
            match slot {
                Some((name, id)) => {
                    let l = self.user_local(name, t, id);
                    self.assign(l, Rvalue::Use(field));
                    binds.push((l, t));
                }
                // An expression statement's value drops with the run.
                None => {
                    let d = self.scoped_temp(t);
                    self.assign(d, Rvalue::Use(field));
                }
            }
        }
        self.pop_scope()?;
        for (l, t) in binds {
            self.declare(l, t);
        }
        let at = format!("{}@{}", self.name, run[0].span.line);
        self.lcx.auto_par_groups.push(at);
        Ok(true)
    }

    /// The tuple `(e1, e2, ..)` of statement values `es`, the run from
    /// `first` on, that one task evaluates in order, typed as the tuple
    /// of `tys`; made once per run, kept for every instance lowered.
    /// `None` when a value's recorded type is not the one `tys` gives it
    /// here: the statements then run as tasks of their own.
    fn stmt_chunk(&mut self, first: &'a Stmt, es: &[&'a Expr], tys: &[Ty]) -> Option<&'a Expr> {
        let mut hir = Vec::new();
        for (e, &t) in es.iter().zip(tys) {
            let &h = self.lcx.node_types.get(&e.id)?;
            let h2 = self.fill_erased_target(h);
            if self.lcx.mir_ty(h2, &self.args).ok()? != t {
                return None;
            }
            hir.push(h);
        }
        let key = (first as *const Stmt, es.len());
        if let Some(&x) = self.lcx.stmt_chunk_exprs.get(&key) {
            return Some(x);
        }
        let id = NodeId(self.lcx.next_synthetic_node);
        self.lcx.next_synthetic_node -= 1;
        let tt = self.tys().tcx().tuple(&hir);
        self.lcx.node_types.insert(id, tt);
        let x: &'a Expr = Box::leak(Box::new(Expr {
            kind: ExprKind::Tuple(es.iter().map(|e| (*e).clone()).collect()),
            span: es[0].span,
            id,
        }));
        self.lcx.stmt_chunk_exprs.insert(key, x);
        Some(x)
    }

    /// Record the closure literals inside the value the body whose tail is
    /// `e` returns: `(i + 1..n).map(|j| i * 10 + j)` as a closure's result
    /// holds its closure, which then escapes (core semantics §9.3: "it, or
    /// a value containing it, is returned") and captures by move, so the
    /// capture outlives the body's `i` (B-2026-10-20-34). The walk follows
    /// the value through block, `if` and `match` tails, `return`, literals,
    /// and calls whose result can hold a function; a call whose result
    /// cannot (`.sum()`) consumes its closures.
    fn note_returned_closures(&mut self, e: &Expr) {
        let out: Vec<NodeId> = self.returned_closures_of(e).iter().map(|c| c.id).collect();
        self.returned_closures.extend(out);
    }

    /// The closure literals inside the value the body whose tail is `e`
    /// returns ([`Self::note_returned_closures`]).
    fn returned_closures_of<'e>(&self, e: &'e Expr) -> Vec<&'e Expr> {
        let tcx = self.tys().tcx();
        let holds_fn = |t: Ty| {
            let mut seen = FxHashSet::default();
            let mut work = vec![t];
            while let Some(t) = work.pop() {
                if !seen.insert(t) {
                    continue;
                }
                match tcx.kind(t) {
                    HK::Fn { .. } => return true,
                    HK::Ref(x) | HK::MutRef(x) => work.push(x),
                    HK::Tuple(l) => work.extend(tcx.list(l)),
                    HK::Array { elem, .. } | HK::Slice { elem, .. } => work.push(elem),
                    HK::Intrinsic { args, .. } | HK::Adt { args, .. } | HK::Shared { args, .. } => {
                        work.extend(tcx.list(args))
                    }
                    _ => {}
                }
            }
            false
        };
        let mut out = Vec::new();
        let mut work = vec![e];
        while let Some(e) = work.pop() {
            match &e.kind {
                ExprKind::Closure { .. } => out.push(e),
                ExprKind::Block(b) => work.extend(b.final_expr.as_deref()),
                ExprKind::If {
                    then_block,
                    else_branch,
                    ..
                }
                | ExprKind::IfLet {
                    then_block,
                    else_branch,
                    ..
                } => {
                    work.extend(then_block.final_expr.as_deref());
                    work.extend(else_branch.as_deref());
                }
                ExprKind::Match { arms, .. } => work.extend(arms.iter().map(|a| &a.body)),
                ExprKind::Return(Some(x)) => work.push(x),
                ExprKind::Tuple(es) | ExprKind::ArrayLiteral(es) => work.extend(es),
                ExprKind::StructLiteral { fields, .. } => {
                    work.extend(fields.iter().map(|f| &f.value))
                }
                ExprKind::Call { args, .. } | ExprKind::MethodCall { args, .. }
                    if self.lcx.node_types.get(&e.id).is_some_and(|&t| holds_fn(t)) =>
                {
                    if let ExprKind::MethodCall { object, .. } = &e.kind {
                        work.push(object);
                    }
                    work.extend(args.iter().map(|a| &a.value));
                }
                _ => {}
            }
        }
        out
    }

    /// Record the `let f = |..| ..` bindings of `block` whose closure escapes.
    fn note_escaping_lets(&mut self, block: &Block) {
        for s in &block.stmts {
            let StmtKind::Let { pattern, value, .. } = &s.kind else {
                continue;
            };
            let (PatternKind::Binding(name), ExprKind::Closure { .. }) =
                (&pattern.kind, &value.kind)
            else {
                continue;
            };
            let sym = self
                .lcx
                .binding_syms
                .get(&(pattern.id, name.clone()))
                .copied();
            if sym.is_some_and(|sym| self.let_closure_escapes(block, sym)) {
                self.escaping_lets.insert(pattern.id);
            }
        }
    }

    /// Whether the closure a `let` in `block` binds to `sym` is later stored
    /// where it escapes: a struct field, a collection, a tuple or array, a
    /// `return`, or the block's value. Core semantics §9.3 makes such a
    /// closure capture by move (B-2026-10-15-27).
    fn let_closure_escapes(&self, block: &Block, sym: SymbolId) -> bool {
        let is_sym = |e: &Expr| {
            matches!(e.kind, ExprKind::Identifier(_))
                && matches!(self.lcx.res.get(&e.id), Some(Res::Local(s)) if *s == sym)
        };
        if block.final_expr.as_deref().is_some_and(is_sym) {
            return true;
        }
        let mut found = false;
        crate::span_visitor::for_each_expr_in_block(block, &mut |e| {
            found |= match &e.kind {
                ExprKind::StructLiteral { fields, .. } => fields.iter().any(|f| is_sym(&f.value)),
                ExprKind::MethodCall { method, args, .. } if stores_argument(method) => {
                    args.iter().any(|a| is_sym(&a.value))
                }
                ExprKind::Return(Some(v)) => is_sym(v),
                ExprKind::Tuple(es) | ExprKind::ArrayLiteral(es) => es.iter().any(is_sym),
                _ => false,
            };
        });
        found
    }

    /// Whether `e`, a block's final expression, has a value that `dest`, a
    /// `()` place, cannot hold.
    fn discards(&mut self, e: &'a Expr, dest: &Place) -> R<bool> {
        let unit = |k: HK| matches!(k, HK::Unit | HK::Never);
        let (dt, et) = (self.place_type(dest), self.expr_ty(e)?);
        let tcx = self.tys().tcx();
        Ok(unit(tcx.kind(dt)) && !unit(tcx.kind(et)))
    }

    /// Lower `s`. What it pushes outside any expression of its own carries
    /// `s`'s span, so a borrow error in an assignment's write or a compound
    /// assignment's read names that statement (B-2026-10-19-15).
    fn stmt(&mut self, s: &'a Stmt) -> R<()> {
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo {
            span: s.span,
            ..outer
        });
        let site = self
            .wide_acc
            .and_then(|w| Some((w, *w.sums.iter().find(|x| std::ptr::eq(x.stmt, s))?)));
        let r = match site {
            Some((w, sum)) => self.wide_add(w, sum),
            None => self.stmt_here(s),
        };
        self.b.set_source_info(outer);
        r
    }

    /// An auto-par task's signed sum statement: its term added to the
    /// task's `i128` total, the least and greatest prefix kept.
    fn wide_add(&mut self, w: WideAcc<'a>, sum: WideSum<'a>) -> R<()> {
        if sum.chain {
            return self.wide_chain(w, sum, sum.term);
        }
        self.wide_term(w, sum.term)
    }

    /// The chain `e` of a wide sum, evaluated as the sequential statement
    /// evaluates it: at each step the operand holding `acc` first when it
    /// is the left one, its other operand added after it.
    fn wide_chain(&mut self, w: WideAcc<'a>, sum: WideSum<'a>, e: &'a Expr) -> R<()> {
        let ExprKind::Binary { left, right, .. } = &e.kind else {
            // `acc` itself, which the task's total stands in for.
            return Ok(());
        };
        if self.acc_chain(left, BinOp::Add, sum.acc) == Ok(None) {
            self.wide_term(w, left)?;
            self.wide_chain(w, sum, right)
        } else {
            self.wide_chain(w, sum, left)?;
            self.wide_term(w, right)
        }
    }

    /// `e`, one term of a wide sum, added to the task's run, the least
    /// and greatest prefix kept; a run that would overflow `acc`'s type
    /// folds into the `i128` base first.
    fn wide_term(&mut self, w: WideAcc<'a>, e: &'a Expr) -> R<()> {
        let t = self.expr_ty(e)?;
        let x = self.temp(t);
        self.expr_into(e, Place::local(x))?;
        // A term read through a reference (`hits + v` with `v: ref i64`)
        // adds what it points at.
        let mut p = Place::local(x);
        let mut pt = t;
        while let HK::Ref(inner) = self.tys().tcx().kind(pt) {
            p = p.project(ProjElem::Deref);
            pt = inner;
        }
        let nt = self.b.local_ty(w.run);
        let xn = self.temp(nt);
        self.assign(xn, Rvalue::Cast(CastKind::IntToInt, Operand::Copy(p), nt));
        let bool_t = self.tys().bool();
        let pair_t = self.tys().tcx().tuple(&[nt, bool_t]);
        let pair = self.temp(pair_t);
        self.assign(
            pair,
            Rvalue::CheckedBinaryOp(
                BinOp::Add,
                Operand::Copy(Place::local(w.run)),
                Operand::Copy(Place::local(xn)),
            ),
        );
        let next = self.temp(nt);
        self.assign(
            next,
            Rvalue::Use(Operand::Copy(Place::local(pair).field(0, nt))),
        );
        let over = self.temp(bool_t);
        self.assign(
            over,
            Rvalue::Use(Operand::Copy(Place::local(pair).field(1, bool_t))),
        );
        // The run starts again at 0 on the base it folded into, where the
        // term cannot overflow it.
        self.when(over, |b| {
            b.wide_rebase(w);
            b.assign(next, Rvalue::Use(Operand::Copy(Place::local(xn))));
        });
        self.assign(w.run, Rvalue::Use(Operand::Copy(Place::local(next))));
        for (bound, op) in [(w.run_least, BinOp::Lt), (w.run_most, BinOp::Gt)] {
            let past = self.temp(bool_t);
            self.assign(
                past,
                Rvalue::BinaryOp(
                    op,
                    Operand::Copy(Place::local(w.run)),
                    Operand::Copy(Place::local(bound)),
                ),
            );
            self.when(past, |b| {
                b.assign(bound, Rvalue::Use(Operand::Copy(Place::local(w.run))));
            });
        }
        Ok(())
    }

    /// Folds a wide sum's run into its `i128` base, least and greatest
    /// prefix, and starts the run again at 0.
    fn wide_rebase(&mut self, w: WideAcc<'a>) {
        let wt = self.b.local_ty(w.base);
        let nt = self.b.local_ty(w.run);
        let bool_t = self.tys().bool();
        for (acc, bound, op) in [
            (w.least, w.run_least, BinOp::Lt),
            (w.most, w.run_most, BinOp::Gt),
        ] {
            let bw = self.temp(wt);
            self.assign(
                bw,
                Rvalue::Cast(CastKind::IntToInt, Operand::Copy(Place::local(bound)), wt),
            );
            let at = self.temp(wt);
            self.assign(
                at,
                Rvalue::BinaryOp(
                    BinOp::Add,
                    Operand::Copy(Place::local(w.base)),
                    Operand::Move(Place::local(bw)),
                ),
            );
            let past = self.temp(bool_t);
            self.assign(
                past,
                Rvalue::BinaryOp(
                    op,
                    Operand::Copy(Place::local(at)),
                    Operand::Copy(Place::local(acc)),
                ),
            );
            self.when(past, |b| {
                b.assign(acc, Rvalue::Use(Operand::Copy(Place::local(at))));
            });
        }
        let rw = self.temp(wt);
        self.assign(
            rw,
            Rvalue::Cast(CastKind::IntToInt, Operand::Copy(Place::local(w.run)), wt),
        );
        // No run is long enough to overflow an `i128` base of 64-bit terms.
        self.assign(
            w.base,
            Rvalue::BinaryOp(
                BinOp::Add,
                Operand::Copy(Place::local(w.base)),
                Operand::Move(Place::local(rw)),
            ),
        );
        for x in [w.run, w.run_least, w.run_most] {
            self.assign(
                x,
                Rvalue::Use(Operand::Const(Const {
                    ty: nt,
                    kind: ConstKind::Scalar(0),
                })),
            );
        }
    }

    /// Records `l`, bound by a `let` of `value`, when the ownership check
    /// proved that `let` frozen ([`FrozenHints`]).
    fn note_frozen(&mut self, value: &Expr, l: Local) {
        let key = SpanKey::from_span(&value.span);
        let (alias, container) = (
            self.lcx.frozen.aliases.contains(&key),
            self.lcx.frozen.containers.contains(&key),
        );
        if !alias && !container {
            return;
        }
        let at = self.lcx.frozen_locals.entry(self.name.clone()).or_default();
        if alias {
            at.aliases.push(l);
        }
        if container {
            at.containers.push(l);
        }
    }

    fn stmt_here(&mut self, s: &'a Stmt) -> R<()> {
        match &s.kind {
            StmtKind::Let {
                is_mut,
                pattern,
                value,
                ty,
            } => {
                // The value's temporaries are the statement's; the bindings
                // belong to the enclosing block.
                if let PatternKind::Binding(name) = &pattern.kind {
                    // A closure or function item keeps its own type; any
                    // other function-typed value (a call's result, a
                    // field) is an erased `Fn` value.
                    let item = matches!(
                        value.kind,
                        ExprKind::Closure { .. } | ExprKind::Identifier(_) | ExprKind::Path { .. }
                    );
                    if item && self.is_fn_typed(pattern.id) {
                        self.push_scope();
                        if self.escaping_lets.contains(&pattern.id) {
                            self.closure_escapes = true;
                        }
                        let (op, t) = self.fn_value(value)?;
                        let l = self.user_local(name, t, pattern.id);
                        self.note_declared_effects(l, (pattern.id, name), ty.as_ref());
                        self.assign(l, Rvalue::Use(op));
                        self.pop_scope()?;
                        self.declare(l, t);
                        return Ok(());
                    }
                    let mut t = self.node_ty(pattern.id, pattern.span)?;
                    if ty.is_none() {
                        if let Some(rt) = self.ref_rebind(value, t)? {
                            t = rt;
                        } else if (is_branching(value) || matches!(value.kind, ExprKind::Block(_)))
                            && !(self.is_copy(t)
                                || self.is_handle(t)
                                || self.is_handle_aggregate(t))
                            && !matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_))
                            && self.lcx.tc.core_ref_copy_nodes.contains(&value.id)
                        {
                            // A `match`, `if` or block whose every result is a
                            // view (`Some(ref r) => r`) is a reference, and the
                            // local binds it (core semantics §4.6,
                            // B-2026-10-28-25): nothing moves out of the place
                            // the results borrow.
                            t = self.tys().tcx().reference(t, false);
                        }
                        if is_branching(value) {
                            t = self.arm_width(value, t);
                        }
                    }
                    let l = self.user_local(name, t, pattern.id);
                    self.note_declared_effects(l, (pattern.id, name), ty.as_ref());
                    self.note_frozen(value, l);
                    let outer = self.let_scope.replace(self.scopes.len() - 1);
                    self.push_scope();
                    // `let idx: i64 = m.get(k).unwrap()` reads the `ref i64`
                    // (core semantics §5.10), as does `let mut t = since` of a
                    // `ref i64`, which the checker types `i64`.
                    let vt = self.expr_ty(value)?;
                    if !matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_))
                        && matches!(self.tys().tcx().kind(vt), HK::Ref(i) | HK::MutRef(i) if i == t)
                    {
                        let op = self.owned_operand(value, t)?;
                        self.assign(l, Rvalue::Use(op));
                    } else {
                        self.expr_into(value, Place::local(l))?;
                    }
                    self.pop_scope()?;
                    self.let_scope = outer;
                    self.declare(l, t);
                    if !is_mut && !matches!(self.lcx.auto_par, AutoPar::Off) {
                        if let (Some(c), Some(&sym)) = (
                            self.constant(value)?,
                            self.lcx.binding_syms.get(&(pattern.id, name.clone())),
                        ) {
                            if c.ty == t {
                                self.lcx.const_lets.insert(sym, c);
                            }
                        }
                    }
                    return Ok(());
                }
                // `let _ = place;` binds nothing, so it moves nothing. A
                // bare unit variant or a const is a value, not a place: it is
                // built and dropped at the `;` (B-2026-10-22-42).
                if matches!(pattern.kind, PatternKind::Wildcard)
                    && is_place_expr(value)
                    && self.names_storage(value)
                {
                    return Ok(());
                }
                self.push_scope();
                // An owned place is destructured where it is (§4.6): the
                // parts it keeps live on in it. Anything else is evaluated
                // into a temporary that dies with the statement.
                let (src, t) = match self.owned_place(value)? {
                    Some(p) => {
                        let t = self.place_type(&p);
                        (p, t)
                    }
                    // A pattern that only borrows or copies (`let W { r: ref
                    // r, n: _ } = w`) reads a local where it is, even one
                    // whose type runs a `Drop` body: nothing moves out of it.
                    None if matches!(value.kind, ExprKind::Identifier(_))
                        && matches!(self.lcx.res.get(&value.id), Some(Res::Local(s)) if self.locals.contains_key(s))
                        && {
                            let vt = self.expr_ty(value)?;
                            self.moves_nothing(pattern, vt)
                        } =>
                    {
                        let p = self.expr_place(value, false)?;
                        let t = self.place_type(&p);
                        (p, t)
                    }
                    // A place reached through a reference (`h.pe` with `h` a
                    // bare parameter) is a `ref` scrutinee, as in a `match`
                    // (core semantics §4.6): its non-`Copy` parts bind `ref`s.
                    None if self.destructures(pattern)
                        && self.is_place(value)
                        && self.is_local_rooted(value)
                        && self
                            .expr_place(value, false)?
                            .projection
                            .contains(&ProjElem::Deref) =>
                    {
                        let mutable = self.binds_mut_ref([pattern]);
                        let (p, st, by_ref) = self.scrutinee(value, mutable)?;
                        let mut binds = Vec::new();
                        self.bind_pattern(pattern, &p, st, by_ref, &mut binds)?;
                        self.pop_scope()?;
                        for (l, t) in binds {
                            self.declare(l, t);
                        }
                        return Ok(());
                    }
                    None => {
                        let t = self.expr_ty(value)?;
                        (Place::local(self.temp_of(value, t)?), t)
                    }
                };
                let mut binds = Vec::new();
                self.bind_irrefutable(pattern, src, t, &mut binds)?;
                self.pop_scope()?;
                for (l, t) in binds {
                    self.declare(l, t);
                }
                Ok(())
            }
            StmtKind::Expr(e) => {
                self.push_scope();
                if let Some(a) = self.discarded_dbg(e) {
                    // `dbg(place);` with its value unused reads the place
                    // and leaves it: removing the `dbg` (as a release build
                    // does) must not change what the program may do next.
                    let p = self.expr_place(a, false)?;
                    let t = self.place_type(&p);
                    let value = self.ref_to(p, t);
                    self.dbg_print(e, a, value);
                } else {
                    let t = self.expr_ty(e)?;
                    self.temp_of(e, t)?;
                }
                self.pop_scope()
            }
            StmtKind::Assign { target, value } => {
                self.push_scope();
                let r = self.assign_stmt(target, value);
                r?;
                self.pop_scope()
            }
            StmtKind::CompoundAssign { target, op, value } => {
                self.push_scope();
                self.compound_assign(target, op.clone(), value)?;
                self.pop_scope()
            }
            StmtKind::LetElse {
                pattern,
                value,
                else_block,
                ..
            } => {
                // `let P = v else { diverge };`: the bindings belong to the
                // enclosing block; the scrutinee's temporaries are the
                // statement's, dropped on either path.
                self.push_scope();
                let (place, st, by_ref) = self.scrutinee(value, self.binds_mut_ref([pattern]))?;
                let fail = self.b.new_block();
                self.test_pattern(pattern, &place, st, fail)?;
                let matched = self.cur;
                self.cur = fail;
                // The initializer's temporaries drop before the else block
                // runs (core semantics §7.4), so it leaves through none.
                let temps = std::mem::take(self.scopes.last_mut().expect("the statement's scope"));
                self.exit_entries(&temps, false)?;
                self.push_scope();
                let t = self.unit();
                let tmp = self.temp(t);
                self.block_into(else_block, Place::local(tmp))?;
                self.pop_scope()?;
                *self.scopes.last_mut().expect("the statement's scope") = temps;
                // The else block diverges (the type checker requires it).
                self.diverge(TerminatorKind::Unreachable);
                self.cur = matched;
                let mut binds = Vec::new();
                self.bind_pattern(pattern, &place, st, by_ref, &mut binds)?;
                self.pop_scope()?;
                for (l, t) in binds {
                    self.declare(l, t);
                }
                Ok(())
            }
            StmtKind::Defer { body } => {
                self.schedule(ScopeEntry::Defer(body));
                Ok(())
            }
            StmtKind::ErrDefer { binding, body } => {
                let bound = binding.as_deref().map(|n| (n, s.id));
                self.schedule(ScopeEntry::ErrDefer(body, bound));
                Ok(())
            }
            // `let x: T;`: storage now, a value at its first assignment
            // (definite assignment is the move check's).
            StmtKind::LetUninit {
                name, name_span, ..
            } => {
                let key = SpanKey::from_span(name_span);
                let Some(ty) = self.lcx.tc.expr_types.get(&key) else {
                    return self.unsupported(s.span, "this statement");
                };
                let args = self.args.clone();
                let t = match self
                    .lcx
                    .lower_legacy(ty, &[], None)
                    .and_then(|h| self.lcx.mir_ty(h, &args))
                {
                    Ok(t) => t,
                    Err(e) => return self.unsupported(s.span, &e),
                };
                let l = self.b.push_local(
                    t,
                    Mutability::Mut,
                    LocalKind::User {
                        name: name.clone(),
                        node: s.id,
                    },
                );
                let key = (name.clone(), name_span.offset, name_span.length);
                if let Some(&sym) = self.lcx.unbound_vars.get(&key) {
                    self.locals.insert(sym, l);
                }
                let bb = self.cur;
                self.b.push(bb, StatementKind::StorageLive(l));
                self.declare(l, t);
                Ok(())
            }
            _ => self.unsupported(s.span, "this statement"),
        }
    }

    fn user_local(&mut self, name: &str, t: Ty, node: NodeId) -> Local {
        let l = self.b.push_local(
            t,
            Mutability::Mut,
            LocalKind::User {
                name: name.to_string(),
                node,
            },
        );
        if let Some(&sym) = self.lcx.binding_syms.get(&(node, name.to_string())) {
            self.locals.insert(sym, l);
            for &j in self.lcx.par_joins.get(&sym).into_iter().flatten() {
                self.locals.insert(j, l);
            }
        }
        let bb = self.cur;
        self.b.push(bb, StatementKind::StorageLive(l));
        l
    }

    /// A binding's local now holds a value: it is dropped at the end of the
    /// enclosing scope.
    fn declare(&mut self, l: Local, t: Ty) {
        self.schedule(ScopeEntry::Storage(l));
        if self.needs_drop(t) {
            self.schedule(ScopeEntry::Drop(Place::local(l)));
        }
    }

    /// Bind the names of an irrefutable pattern by moving (or copying) the
    /// matching parts of `place` into fresh locals.
    fn bind_irrefutable(
        &mut self,
        pat: &'a Pattern,
        place: Place,
        t: Ty,
        out: &mut Vec<(Local, Ty)>,
    ) -> R<()> {
        // Destructuring through a reference binds references into the
        // referent, as a match through one does.
        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            if !matches!(pat.kind, PatternKind::Wildcard | PatternKind::Binding(_)) {
                return self.bind_pattern(pat, &place.project(ProjElem::Deref), inner, true, out);
            }
        }
        match &pat.kind {
            PatternKind::Wildcard => Ok(()),
            PatternKind::Binding(name)
                if self
                    .lcx
                    .mut_ref_bindings
                    .contains(&SpanKey::from_span(&pat.span)) =>
            {
                self.bind_mut_ref(name, pat.id, place, t, out);
                Ok(())
            }
            PatternKind::Binding(name)
                if self
                    .lcx
                    .ref_bindings
                    .contains(&SpanKey::from_span(&pat.span)) =>
            {
                self.bind_one(name, pat.id, place, t, true, out);
                Ok(())
            }
            PatternKind::Binding(name) => {
                let l = self.user_local(name, t, pat.id);
                if self.is_handle(t) || self.is_handle_aggregate(t) {
                    self.count_copy(place, t, Place::local(l));
                } else {
                    let op = self.use_place(place, t);
                    self.assign(l, Rvalue::Use(op));
                }
                out.push((l, t));
                Ok(())
            }
            PatternKind::Tuple(ps) => {
                for (i, p) in ps.iter().enumerate() {
                    let Some(ft) = self.tys().field_ty(t, None, i as u32) else {
                        return self.unsupported(p.span, "this tuple pattern");
                    };
                    self.bind_irrefutable(p, place.field(i as u32, ft), ft, out)?;
                }
                Ok(())
            }
            PatternKind::Struct { fields, .. } => {
                for fp in fields {
                    let Some((idx, ft)) = self.field_of(t, None, &fp.name) else {
                        return self.unsupported(fp.span, "this field pattern");
                    };
                    let fplace = place.field(idx, ft);
                    match &fp.pattern {
                        Some(p) => self.bind_irrefutable(p, fplace, ft, out)?,
                        None => {
                            let l = self.user_local(&fp.name, ft, pat.id);
                            let op = self.use_place(fplace, ft);
                            self.assign(l, Rvalue::Use(op));
                            out.push((l, ft));
                        }
                    }
                }
                Ok(())
            }
            PatternKind::Slice { .. } | PatternKind::AtBinding { .. } => {
                self.bind_pattern(pat, &place, t, false, out)
            }
            _ => self.unsupported(pat.span, "this pattern in a `let`"),
        }
    }

    /// The index and type of the field `name` of `t` (variant `variant` of
    /// an enum).
    fn field_of(&self, t: Ty, variant: Option<u32>, name: &str) -> Option<(u32, Ty)> {
        let (adt, _) = self.tys().tcx().adt_of(t)?;
        let v = adt.variants.get(variant.unwrap_or(0) as usize)?;
        let idx = v.fields.iter().position(|(n, _)| n == name)? as u32;
        let ft = self.tys().tcx().field_ty(t, variant, idx)?;
        Some((idx, ft))
    }

    fn assign_stmt(&mut self, target: &'a Expr, value: &'a Expr) -> R<()> {
        // `m[k] = v` on a map inserts (`IndexSet`, design.md §9): the
        // entry is created when the key is missing, and an old value is
        // handed back and dropped.
        if let ExprKind::Index { object, index } = &target.kind {
            if let ExprKind::Range {
                start,
                end,
                inclusive,
            } = &index.kind
            {
                let range = (start.as_deref(), end.as_deref(), *inclusive);
                return self.range_assign(target, object, range, value);
            }
            if self.slices(object, index) {
                return self.unsupported(target.span, "an assignment through a range value");
            }
            let ot = self.expr_ty(object)?;
            let (k, base) = self.strip_ty_full(ot);
            if let HK::Intrinsic {
                kind: IntrinsicKind::Map | IntrinsicKind::SortedMap,
                args,
            } = k
            {
                let targs = self.tys().tcx().list(args);
                return self.index_set(target, object, index, value, base, &targs);
            }
            // A user type's `impl IndexSet` (B-2026-10-14-47).
            if let Some((d, inst_args)) =
                self.user_operator_method(base, "IndexSet", "index_set", index)?
            {
                return self.user_index_set(target, object, index, value, base, d, inst_args);
            }
        }
        // Left to right: the target's own subexpressions, then the value,
        // then the old value is dropped and the new one stored (D4).
        let pending = self.prepare_place(target)?;
        // A tuple literal is built at the target's element types, as a
        // `let`'s is at its annotation's (`b[1] = (7, 8)` into `(i32, i32)`).
        let op = if matches!(value.kind, ExprKind::Tuple(_)) {
            let tt = self.expr_ty(target)?;
            let (_, tt) = self.strip_ty_full(tt);
            self.operand_at(value, tt)?
        } else {
            self.expr_operand(value)?
        };
        let op = self.settle(op);
        let place = self.finish_place(pending, true)?;
        let (place, t) = self.write_through(place, value)?;
        if self.needs_drop(t) {
            let next = self.b.new_block();
            self.goto_with(
                TerminatorKind::Drop {
                    place: place.clone(),
                    target: next,
                    unwind: UnwindAction::Abort,
                },
                next,
            );
        }
        self.assign(place.clone(), Rvalue::Use(op));
        Ok(())
    }

    /// `m[k] = v` on a map: `insert(&mut m, k, v)`, with the key, then
    /// the value, evaluated before the map's borrow starts (§5.6).
    fn index_set(
        &mut self,
        target: &'a Expr,
        object: &'a Expr,
        index: &'a Expr,
        value: &'a Expr,
        base: Ty,
        targs: &[Ty],
    ) -> R<()> {
        let (Some(&kt), Some(&vt)) = (targs.first(), targs.get(1)) else {
            return self.unsupported(target.span, "an index assignment to this map");
        };
        let Some(ret) = self.option_of(vt) else {
            return self.unsupported(target.span, "an index assignment without `Option`");
        };
        let recv = self.recv_place(object, true)?;
        let key = self.owned_operand(index, kt)?;
        let mut val = self.owned_operand(value, vt)?;
        val = if self.downgrades(&val, vt) {
            self.downgrade(val, vt)
        } else {
            self.widen(val, vt)
        };
        let mut rest = vec![key, val];
        let mut ops = vec![self.recv_borrow_after(recv, &mut rest)?];
        ops.extend(rest);
        let old = self.temp(ret);
        let name = format!("{}.insert", self.tys().display(base));
        self.call_native(&name, ops, Place::local(old));
        if self.needs_drop(ret) {
            let next = self.b.new_block();
            self.goto_with(
                TerminatorKind::Drop {
                    place: Place::local(old),
                    target: next,
                    unwind: UnwindAction::Abort,
                },
                next,
            );
        }
        Ok(())
    }

    /// `Option[t]`.
    fn option_of(&mut self, t: Ty) -> Option<Ty> {
        self.enum_of("Option", &[t])
    }

    /// The enum named `name`, applied to `args`.
    fn enum_of(&mut self, name: &str, args: &[Ty]) -> Option<Ty> {
        self.adt_named(DefKind::Enum, name, args)
    }

    /// The library's struct `name` at `args` (`MutexGuard[T]`), with its
    /// `Drop` body registered for this instance.
    fn library_struct(&mut self, name: &str, args: &[Ty]) -> Option<Ty> {
        let t = self.adt_named(DefKind::Struct, name, args)?;
        self.lcx.convert(t).ok()
    }

    fn adt_named(&mut self, kind: DefKind, name: &str, args: &[Ty]) -> Option<Ty> {
        let table = &self.lcx.defs.table;
        let d = (0..table.len() as u32).map(DefId).find(|&d| {
            let e = table.get(d);
            e.kind == kind && e.path.segments.last().is_some_and(|s| s == name)
        })?;
        self.lcx.register_adt(d).ok()?;
        Some(self.tys().tcx().adt(d, args))
    }

    /// An operand that reads through a projection (`copy (*_r)`, where `_r`
    /// borrows an element) read into a temporary now, so the borrow it
    /// reads through ends before the target's own borrow starts
    /// (`v[k] = v[j]`).
    fn settle(&mut self, op: Operand) -> Operand {
        match op {
            Operand::Copy(p) | Operand::Move(p) if !p.projection.is_empty() => {
                let t = self.place_type(&p);
                let l = self.temp(t);
                let read = self.use_place(p, t);
                self.assign(l, Rvalue::Use(read));
                self.use_place(Place::local(l), t)
            }
            other => other,
        }
    }

    /// The place an assignment writes: a `mut ref` binding assigned a value
    /// of its pointee type writes through the reference (`x = x + 1` for
    /// `x: mut ref i64`), and the type stored there.
    fn write_through(&mut self, place: Place, value: &'a Expr) -> R<(Place, Ty)> {
        let t = self.place_type(&place);
        if let HK::MutRef(inner) = self.tys().tcx().kind(t) {
            let vt = self.expr_ty(value)?;
            if !matches!(self.tys().tcx().kind(vt), HK::Ref(_) | HK::MutRef(_)) {
                return Ok((place.project(ProjElem::Deref), inner));
            }
        }
        Ok((place, t))
    }

    fn compound_assign(&mut self, target: &'a Expr, op: CompoundOp, value: &'a Expr) -> R<()> {
        // `s += x` on a `String` appends, as `s.push_str(x)` (or `push` of
        // a `char`) does.
        if op == CompoundOp::Add {
            let tt = self.expr_ty(target)?;
            if matches!(self.strip_ty(tt), HK::Str) {
                let vt = self.expr_ty(value)?;
                let method = if matches!(self.strip_ty(vt), HK::Char) {
                    "push"
                } else {
                    "push_str"
                };
                let arg = self.lib_arg(value, !self.is_copy(vt))?;
                let mut place = self.expr_place(target, true)?;
                while let HK::Ref(_) | HK::MutRef(_) =
                    self.tys().tcx().kind(self.place_type(&place))
                {
                    place = place.project(ProjElem::Deref);
                }
                let st = self.place_type(&place);
                let rt = self.tys().tcx().reference(st, true);
                let r = self.temp(rt);
                self.assign(r, Rvalue::Ref(BorrowKind::Mut, place));
                let u = self.temp(self.unit());
                self.call_native(
                    &format!("String.{method}"),
                    vec![Operand::Move(Place::local(r)), arg],
                    Place::local(u),
                );
                return Ok(());
            }
        }
        // B-2026-10-14-30 — `a += b` on a user type is `a = a + b`, through
        // the impl's operator method.
        if let Some((tr, m)) = user_operator_trait(compound_binop(&op)) {
            let tt = self.expr_ty(target)?;
            let (_, tb) = self.strip_ty_full(tt);
            if let Some((d, args)) = self.user_operator_method(tb, tr, m, value)? {
                let tmp = self.temp(tb);
                self.user_operator_call(target, Some(value), d, args, Place::local(tmp))?;
                let place = self.expr_place(target, true)?;
                let (place, t) = self.write_through(place, value)?;
                if self.needs_drop(t) {
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Drop {
                            place: place.clone(),
                            target: next,
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                }
                self.assign(place, Rvalue::Use(Operand::Move(Place::local(tmp))));
                return Ok(());
            }
        }
        let pending = self.prepare_place(target)?;
        let (rhs, _) = self.scalar_operand(value)?;
        let rhs = self.settle(rhs);
        let place = self.finish_place(pending, true)?;
        let (place, t) = self.write_through(place, value)?;
        let bin = compound_binop(&op);
        if !self.is_copy(t) {
            return self.unsupported(target.span, "a compound assignment to a non-scalar");
        }
        let lhs = Operand::Copy(place.clone());
        let rhs = if matches!(bin, BinOp::Shl | BinOp::Shr) {
            rhs
        } else {
            self.fit_const(rhs, t)
        };
        self.arith(bin, lhs, rhs, t, place);
        Ok(())
    }

    /// An operator on `String`s: the library's `String.eq` (borrowing both
    /// sides) and `String.add` (taking the left, borrowing the right).
    fn string_op(&mut self, left: &'a Expr, bin: BinOp, right: &'a Expr, dest: Place) -> R<()> {
        match bin {
            BinOp::Eq | BinOp::Ne => {
                let l = self.lib_arg(left, true)?;
                let r = self.lib_arg(right, true)?;
                if bin == BinOp::Eq {
                    self.call_native("String.eq", vec![l, r], dest);
                } else {
                    let bool_t = self.tys().bool();
                    let t = self.temp(bool_t);
                    self.call_native("String.eq", vec![l, r], Place::local(t));
                    self.assign(
                        dest,
                        Rvalue::UnaryOp(UnOp::Not, Operand::Move(Place::local(t))),
                    );
                }
                Ok(())
            }
            BinOp::Add => {
                // `fn add(ref self, other: ref String) -> String` (core
                // semantics §3.1): `a + b` moves neither operand.
                let l = self.lib_arg(left, true)?;
                let r = self.lib_arg(right, true)?;
                self.call_native("String.add", vec![l, r], dest);
                Ok(())
            }
            // `a < b` and the rest through the library's `String.lt` (byte
            // order): `a > b` is `b < a`, `a <= b` is `!(b < a)`.
            BinOp::Lt | BinOp::Gt | BinOp::Le | BinOp::Ge => {
                let l = self.lib_arg(left, true)?;
                let r = self.lib_arg(right, true)?;
                let (args, negate) = match bin {
                    BinOp::Lt => (vec![l, r], false),
                    BinOp::Gt => (vec![r, l], false),
                    BinOp::Le => (vec![r, l], true),
                    _ => (vec![l, r], true),
                };
                if !negate {
                    self.call_native("String.lt", args, dest);
                } else {
                    let bool_t = self.tys().bool();
                    let t = self.temp(bool_t);
                    self.call_native("String.lt", args, Place::local(t));
                    self.assign(
                        dest,
                        Rvalue::UnaryOp(UnOp::Not, Operand::Move(Place::local(t))),
                    );
                }
                Ok(())
            }
            _ => self.unsupported(left.span, "this operator on strings"),
        }
    }

    /// An operator's operand and its type, read through a reference
    /// (`*r + 1` and `r + 1` alike, for `r: ref i64`).
    fn scalar_operand(&mut self, e: &'a Expr) -> R<(Operand, Ty)> {
        let t = self.expr_ty(e)?;
        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            if self.is_copy(inner) {
                let p = self.expr_place(e, false)?.project(ProjElem::Deref);
                return Ok((Operand::Copy(p), inner));
            }
        }
        Ok((self.expr_operand(e)?, t))
    }

    /// `dest = l <op> r` on values of type `t`. Integer arithmetic is
    /// checked (core semantics C8): division by zero and overflow abort.
    fn arith(&mut self, bin: BinOp, l: Operand, r: Operand, t: Ty, dest: Place) {
        let int = matches!(self.tys().tcx().kind(t), HK::Int(_) | HK::UInt(_));
        // An unsuffixed literal takes the other operand's integer type (the
        // checker records `c += 27` with `c: i8` as an `i64` literal). A
        // shift's amount keeps its own type.
        let retype = |o: Operand| match o {
            Operand::Const(Const {
                kind: ConstKind::Scalar(v),
                ..
            }) if int => Operand::Const(Const {
                ty: t,
                kind: ConstKind::Scalar(v),
            }),
            o => o,
        };
        let l = retype(l);
        let r = if matches!(bin, BinOp::Shl | BinOp::Shr) {
            r
        } else {
            retype(r)
        };
        let checked = matches!(
            bin,
            BinOp::Add
                | BinOp::Sub
                | BinOp::Mul
                | BinOp::Div
                | BinOp::Rem
                | BinOp::Shl
                | BinOp::Shr
        );
        if !int || !checked {
            self.assign(dest, Rvalue::BinaryOp(bin, l, r));
            return;
        }
        if matches!(bin, BinOp::Div | BinOp::Rem) {
            let bool_t = self.tys().bool();
            let z = self.temp(bool_t);
            self.assign(
                z,
                Rvalue::BinaryOp(
                    BinOp::Eq,
                    r.clone(),
                    Operand::Const(Const {
                        ty: t,
                        kind: ConstKind::Scalar(0),
                    }),
                ),
            );
            let ok = self.b.new_block();
            let bad = self.b.new_block();
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(z)),
                    targets: SwitchTargets::if_else(bad, ok),
                },
                bad,
            );
            self.diverge(TerminatorKind::Abort {
                reason: AbortReason::DivByZero,
            });
            self.cur = ok;
        }
        let pair_t = {
            let tcx = self.tys().tcx();
            let b = tcx.intern(HK::Bool);
            tcx.tuple(&[t, b])
        };
        let pair = self.temp(pair_t);
        self.assign(pair, Rvalue::CheckedBinaryOp(bin, l, r));
        let bool_t = self.tys().bool();
        let ok = self.b.new_block();
        let bad = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(pair).field(1, bool_t)),
                targets: SwitchTargets::if_else(bad, ok),
            },
            bad,
        );
        self.diverge(TerminatorKind::Abort {
            reason: AbortReason::Overflow,
        });
        self.cur = ok;
        self.assign(
            dest,
            Rvalue::Use(Operand::Copy(Place::local(pair).field(0, t))),
        );
    }

    // ── places ──────────────────────────────────────────────────────

    /// Whether `object[index]` slices (`v[a..b]`, or a sequence indexed by
    /// a range value: `let r = 1..3; v[r]`) rather than naming one element
    /// (a map keyed by ranges looks its key up). The checker's types are
    /// read here, where a `Vec` is still the library's type.
    fn slices(&self, object: &Expr, index: &Expr) -> bool {
        if matches!(index.kind, ExprKind::Range { .. }) {
            return true;
        }
        let tcx = self.tys().tcx();
        let named = |t: Ty, names: &[&str]| match tcx.kind(t) {
            HK::Adt { def, .. } => names.contains(&self.lcx.def_name(def).as_str()),
            _ => false,
        };
        let range = self
            .lcx
            .node_types
            .get(&index.id)
            .is_some_and(|&t| named(t, &["Range", "RangeInclusive", "RangeFrom"]));
        range
            && self.lcx.node_types.get(&object.id).is_some_and(|&t| {
                let mut t = t;
                while let HK::Ref(inner) | HK::MutRef(inner) = tcx.kind(t) {
                    t = inner;
                }
                self.seq_of(t).is_some() || named(t, &["Vec"])
            })
    }

    /// Is `e` a place expression (it names memory rather than computing a
    /// value)?
    fn is_place(&self, e: &Expr) -> bool {
        if self.pinned.contains_key(&e.id) {
            return true;
        }
        match &e.kind {
            ExprKind::Identifier(_) => match self.lcx.res.get(&e.id) {
                Some(Res::Local(_)) => true,
                Some(Res::Def(d)) => self.lcx.statics.contains_key(d),
                _ => false,
            },
            ExprKind::SelfValue => true,
            // `F.value` with an uppercase local `F`.
            ExprKind::Path { .. } => matches!(self.lcx.res.get(&e.id), Some(Res::LocalPath(_))),
            // A field of a temporary is a place too: the temporary's.
            ExprKind::FieldAccess { .. } => {
                self.int_limit_of(e).is_none() && self.builtin_fn_def(e).is_none()
            }
            // `v[a..b]` makes a slice value; `v[i]` names an element.
            ExprKind::Index { object, index } => !self.slices(object, index),
            ExprKind::TupleIndex { .. } => true,
            ExprKind::Unary {
                op: UnaryOp::Deref, ..
            } => true,
            _ => false,
        }
    }

    /// A place expression whose root identifier names storage, a local or
    /// a static, rather than a unit variant or a const.
    fn names_storage(&self, e: &Expr) -> bool {
        match &e.kind {
            ExprKind::Identifier(_) => match self.lcx.res.get(&e.id) {
                Some(Res::Local(_)) => true,
                Some(Res::Def(d)) => self.lcx.statics.contains_key(d),
                _ => false,
            },
            ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
                self.names_storage(object)
            }
            _ => true,
        }
    }

    /// `i64.MAX`, `u8.MIN`, `f64.NAN`: a primitive type's constant, as its
    /// type and value.
    fn int_limit_of(&self, e: &Expr) -> Option<(Ty, ConstKind)> {
        let ExprKind::FieldAccess { object, field } = &e.kind else {
            return None;
        };
        let ExprKind::Identifier(name) = &object.kind else {
            return None;
        };
        if matches!(self.lcx.res.get(&object.id), Some(Res::Local(_))) {
            return None;
        }
        let tcx = self.tys().tcx();
        let kind = match name.as_str() {
            "i8" => HK::Int(IntSize::I8),
            "i16" => HK::Int(IntSize::I16),
            "i32" => HK::Int(IntSize::I32),
            "i64" => HK::Int(IntSize::I64),
            "i128" => HK::Int(IntSize::I128),
            "isize" => HK::Int(IntSize::Isize),
            "u8" => HK::UInt(UIntSize::U8),
            "u16" => HK::UInt(UIntSize::U16),
            "u32" => HK::UInt(UIntSize::U32),
            "u64" => HK::UInt(UIntSize::U64),
            "u128" => HK::UInt(UIntSize::U128),
            "usize" => HK::UInt(UIntSize::Usize),
            "f32" | "f64" => {
                let (kind, v) = match crate::prelude::lookup_primitive_const(name, field)? {
                    crate::prelude::ConstValue::F32(v) => (HK::Float(FloatSize::F32), *v as f64),
                    crate::prelude::ConstValue::F64(v) => (HK::Float(FloatSize::F64), *v),
                    _ => return None,
                };
                return Some((tcx.intern(kind), ConstKind::Float(v.to_bits())));
            }
            _ => return None,
        };
        let v = int_limit(kind, field)?;
        Some((tcx.intern(kind), ConstKind::Scalar(v)))
    }

    /// Evaluate the parts of a place expression that compute values (an
    /// index), leaving the place itself to `finish_place`.
    /// Every subscript along the place is evaluated now, outermost
    /// object first (`hs[idx(1)].t.1[idx(0)]` calls `idx(1)` then
    /// `idx(0)`), before the value it is assigned (core semantics §8).
    fn prepare_place(&mut self, e: &'a Expr) -> R<PendingPlace<'a>> {
        self.pre_index(e)?;
        Ok(PendingPlace::Plain(e))
    }

    fn pre_index(&mut self, e: &'a Expr) -> R<()> {
        match &e.kind {
            ExprKind::Index { object, index } => {
                self.pre_index(object)?;
                // An index already read (a place prepared before it is
                // named) is not read again.
                if !self.slices(object, index) && !self.pre_indices.contains_key(&index.id) {
                    let idx = match self.index_operand(object, index)? {
                        // Read now: the value may assign the variable.
                        Operand::Copy(p) => {
                            let t = self.place_type(&p);
                            let l = self.temp(t);
                            self.assign(l, Rvalue::Use(Operand::Copy(p)));
                            Operand::Copy(Place::local(l))
                        }
                        op => op,
                    };
                    self.pre_indices.insert(index.id, idx);
                }
                Ok(())
            }
            ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
                self.pre_index(object)
            }
            _ => Ok(()),
        }
    }

    fn finish_place(&mut self, p: PendingPlace<'a>, mutable: bool) -> R<Place> {
        match p {
            PendingPlace::Plain(e) => self.expr_place(e, mutable),
        }
    }

    /// The place `e` names. Field access through a reference derefs it.
    fn expr_place(&mut self, e: &'a Expr, mutable: bool) -> R<Place> {
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo {
            span: e.span,
            ..outer
        });
        let r = self.expr_place_here(e, mutable);
        self.b.set_source_info(outer);
        r
    }

    fn expr_place_here(&mut self, e: &'a Expr, mutable: bool) -> R<Place> {
        let p = self.expr_place_of(e, mutable)?;
        if mutable {
            return Ok(p);
        }
        // Reading a `weak` slot upgrades it: `Some` of a counted handle
        // while the object lives, else `None` (design.md, Cycles and
        // `weak`).
        let pt = self.place_type(&p);
        // A borrowed `weak` parameter is upgraded through its reference
        // (B-2026-10-25-45).
        let by_ref = match self.tys().tcx().kind(pt) {
            HK::Ref(i) if matches!(self.tys().tcx().kind(i), HK::Weak(_)) => true,
            HK::Weak(_) => false,
            _ => return Ok(p),
        };
        let ot = self.expr_ty(e)?;
        if matches!(self.tys().tcx().kind(ot), HK::Weak(_) | HK::Ref(_)) {
            return Ok(p);
        }
        let r = if by_ref {
            Operand::Copy(p)
        } else {
            let rt = self.tys().tcx().reference(pt, false);
            let r = self.temp(rt);
            self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
            Operand::Move(Place::local(r))
        };
        let l = self.temp(ot);
        self.assign(l, Rvalue::Cast(CastKind::Upgrade, r, ot));
        if self.needs_drop(ot) {
            self.schedule(ScopeEntry::Drop(Place::local(l)));
        }
        Ok(Place::local(l))
    }

    /// The place `segments` names from the uppercase local `sym` (its first
    /// segment): the local, then each field in turn.
    fn local_path_place(&mut self, span: Span, sym: SymbolId, segments: &[String]) -> R<Place> {
        let mut p = match (self.locals.get(&sym), self.captured.get(&sym)) {
            (Some(&l), _) => Place::local(l),
            (None, Some(p)) => p.clone(),
            (None, None) => {
                let name = &segments[0];
                return self.unsupported(span, &format!("the capture of `{name}`"));
            }
        };
        for field in &segments[1..] {
            let (base, bt) = self.strip_refs(p);
            let Some((idx, ft)) = self.field_of(bt, None, field) else {
                return self.unsupported(span, &format!("the field `{field}`"));
            };
            p = base.field(idx, ft);
        }
        Ok(p)
    }

    fn expr_place_of(&mut self, e: &'a Expr, mutable: bool) -> R<Place> {
        if let Some(p) = self.pinned.get(&e.id) {
            return Ok(p.clone());
        }
        match &e.kind {
            ExprKind::Identifier(name) => match self.lcx.res.get(&e.id) {
                Some(Res::Local(sym)) => match self.locals.get(sym) {
                    Some(&l) => Ok(Place::local(l)),
                    None => match self.captured.get(sym) {
                        Some(p) => Ok(p.clone()),
                        None => self.unsupported(e.span, &format!("the capture of `{name}`")),
                    },
                },
                Some(&Res::Def(d)) if self.lcx.statics.contains_key(&d) => Ok(self.static_place(d)),
                _ => self.temp_place(e),
            },
            // `F.value.x` with an uppercase local `F`, which the parser
            // reads as a path: the local, then each field in turn.
            ExprKind::Path { segments, .. } => {
                let Some(&Res::LocalPath(sym)) = self.lcx.res.get(&e.id) else {
                    return self.temp_place(e);
                };
                self.local_path_place(e.span, sym, segments)
            }
            // Inside a closure `self` is one of its captures.
            ExprKind::SelfValue => match self.self_local {
                Some(l) => Ok(Place::local(l)),
                None => match self.lcx.res.get(&e.id) {
                    Some(Res::Local(sym)) if self.captured.contains_key(sym) => {
                        Ok(self.captured[sym].clone())
                    }
                    _ => self.unsupported(e.span, "`self` here"),
                },
            },
            ExprKind::FieldAccess { object, field }
                if self.captured_field(object, field).is_some() =>
            {
                Ok(self.captured_field(object, field).expect("checked"))
            }
            ExprKind::FieldAccess { object, field } => {
                // A field of a `shared` value is written through any
                // handle to it (core-semantics §5.9), so the handle is
                // only read: `nodes[i].val = v` with `nodes` a `ref Vec`
                // takes `index`, not `index_mut` (B-2026-10-13-33).
                let through_shared = mutable
                    && self.expr_ty(object).is_ok_and(|mut ot| {
                        while let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(ot) {
                            ot = inner;
                        }
                        matches!(self.tys().tcx().kind(ot), HK::Shared { .. })
                    });
                let (base, bt) = self.deref_place(object, mutable && !through_shared)?;
                match self.field_of(bt, None, field) {
                    Some((idx, ft)) => Ok(base.field(idx, ft)),
                    None => self.unsupported(e.span, &format!("the field `{field}`")),
                }
            }
            ExprKind::TupleIndex { object, index } => {
                let (base, bt) = self.deref_place(object, mutable)?;
                match self.tys().field_ty(bt, None, *index as u32) {
                    Some(ft) => Ok(base.field(*index as u32, ft)),
                    None => self.unsupported(e.span, "this tuple index"),
                }
            }
            // `v[a..b]` is a value (a slice, or a new `String`).
            ExprKind::Index { object, index } if self.slices(object, index) => self.temp_place(e),
            ExprKind::Index { object, index } => {
                // The base's own indices are read before this one: `v[p(1)][p(0)]`
                // reads `p(1)` first (core semantics §8.1; B-2026-10-19-53).
                self.pre_index(object)?;
                let idx = self.index_operand(object, index)?;
                self.index_place(object, idx, e, mutable)
            }
            ExprKind::Unary {
                op: UnaryOp::Deref,
                operand,
            } => {
                let p = self.expr_place(operand, mutable)?;
                // A `Copy` part bound through a `ref` is bound by value
                // (`bind_one`), so `*min` of it is the binding itself; so is
                // a handle part of a `shared` value (B-2026-10-18-30).
                let pt = self.place_type(&p);
                if !matches!(
                    self.tys().tcx().kind(pt),
                    HK::Ref(_) | HK::MutRef(_) | HK::RawPtr { .. }
                ) && (self.is_copy(pt) || self.is_handle(pt) || self.is_handle_aggregate(pt))
                {
                    return Ok(p);
                }
                // `*x` of an `x: ref T` whose `T` is itself a reference: the
                // borrow of a borrow is the borrow, so `x` is that `T`.
                if matches!(self.tys().tcx().kind(pt), HK::Ref(_) | HK::MutRef(_))
                    && self.expr_ty(e)? == pt
                {
                    return Ok(p);
                }
                Ok(p.project(ProjElem::Deref))
            }
            _ => self.temp_place(e),
        }
    }

    /// The place of a module binding that lives in a static: `*_t`, with
    /// `_t` the static's borrow.
    fn static_place(&mut self, d: DefId) -> Place {
        let (i, t, mutable) = self.lcx.statics[&d];
        let rt = self.tys().tcx().reference(t, mutable);
        let l = self.temp(rt);
        self.assign(
            l,
            Rvalue::Use(Operand::Const(Const {
                ty: rt,
                kind: ConstKind::Static(i),
            })),
        );
        Place::local(l).project(ProjElem::Deref)
    }

    /// The MIR type `p` ends at: its local's type through each projection.
    fn place_type(&self, p: &Place) -> Ty {
        let mut t = self.b.local_ty(p.local);
        for elem in &p.projection {
            let tcx = self.tys().tcx();
            t = match (elem, tcx.kind(t)) {
                (ProjElem::Field(_, ft), _) => *ft,
                (ProjElem::Downcast(_), _) => t,
                (
                    ProjElem::Deref,
                    HK::Ref(inner) | HK::MutRef(inner) | HK::RawPtr { pointee: inner, .. },
                ) => inner,
                (
                    ProjElem::Index(_) | ProjElem::ConstIndex(_),
                    HK::Array { elem, .. } | HK::Vector { elem, .. },
                ) => elem,
                _ => t,
            };
        }
        t
    }

    /// The place of `object`, through any references, and its type there.
    fn deref_place(&mut self, object: &'a Expr, mutable: bool) -> R<(Place, Ty)> {
        let mut p = self.expr_place(object, mutable)?;
        let mut t = self.place_type(&p);
        loop {
            match self.tys().tcx().kind(t) {
                HK::Ref(inner) | HK::MutRef(inner) => {
                    p = p.project(ProjElem::Deref);
                    t = inner;
                }
                _ => return Ok((p, t)),
            }
        }
    }

    /// The index of `object[index]`: a `Map` key that is not `Copy` is
    /// borrowed, anything else is a value.
    fn index_operand(&mut self, object: &'a Expr, index: &'a Expr) -> R<Operand> {
        if let Some(op) = self.pre_indices.remove(&index.id) {
            return Ok(op);
        }
        let mut t = self.expr_ty(object)?;
        while let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            t = inner;
        }
        if let HK::Intrinsic {
            kind: IntrinsicKind::Map | IntrinsicKind::SortedMap,
            ..
        } = self.tys().tcx().kind(t)
        {
            let kt = self.expr_ty(index)?;
            if !self.is_copy(kt) {
                return self.lib_arg(index, true);
            }
        }
        // A user type's `index` that borrows its key (a bare `name: String`
        // under D5) is lent a place key, which stays the caller's
        // (B-2026-10-28-21).
        if matches!(self.tys().tcx().kind(t), HK::Adt { .. } | HK::Shared { .. })
            && self.is_place(index)
        {
            let kt = self.expr_ty(index)?;
            if !self.is_copy(kt) && !self.is_reference(kt) {
                let picked = match self.user_operator_method(t, "Index", "index", index)? {
                    Some(m) => Some(m),
                    None => self.user_operator_method(t, "IndexMut", "index_mut", index)?,
                };
                if let Some((d, args)) = picked {
                    if let [p] = self.lcx.fns[&d].f.params.as_slice() {
                        let pt = self.callee_param_ty(p, &args)?;
                        if matches!(self.tys().tcx().kind(pt), HK::Ref(_)) {
                            return self.lib_arg(index, true);
                        }
                    }
                }
            }
        }
        // A position held through a `mut ref` reads through it.
        Ok(self.scalar_operand(index)?.0)
    }

    /// `object[idx]`: a library call yielding a reference, then its target.
    fn index_place(
        &mut self,
        object: &'a Expr,
        idx: Operand,
        e: &'a Expr,
        mutable: bool,
    ) -> R<Place> {
        let (base, bt) = self.deref_place(object, mutable)?;
        // A `Vec`, `VecDeque` or slice takes a `usize` position; a `Map`
        // its key.
        let (elem, positional) = match self.tys().tcx().kind(bt) {
            HK::Intrinsic {
                kind: IntrinsicKind::Vec | IntrinsicKind::VecDeque,
                args,
            } => (self.tys().tcx().list(args)[0], true),
            HK::Intrinsic {
                kind: IntrinsicKind::Map | IntrinsicKind::SortedMap,
                args,
            } => (self.tys().tcx().list(args)[1], false),
            HK::Slice { elem, .. } => (elem, true),
            HK::Array { .. } | HK::Vector { .. } => return Ok(self.array_index(base, idx)),
            _ => {
                // A user type's `impl Index` / `impl IndexMut`
                // (B-2026-10-14-37).
                let (tr, method) = if mutable {
                    ("IndexMut", "index_mut")
                } else {
                    ("Index", "index")
                };
                // Of several impls (`Index[String]` and `Index[i64]`), the
                // key's type picks one (B-2026-10-28-21).
                let picked = match &e.kind {
                    ExprKind::Index { index, .. } => {
                        self.user_operator_method(bt, tr, method, index)?
                    }
                    _ => self.user_impl_method(bt, tr, method),
                };
                return match picked {
                    Some((d, inst_args)) => self.user_index_place(base, bt, idx, d, inst_args, e),
                    None => self.unsupported(e.span, "indexing this type"),
                };
            }
        };
        let (usize_t, rt, et) = {
            let tcx = self.tys().tcx();
            (
                tcx.intern(HK::UInt(UIntSize::Usize)),
                tcx.reference(bt, mutable),
                tcx.reference(elem, mutable),
            )
        };
        let idx = if positional {
            self.cast_index(idx, usize_t)
        } else {
            idx
        };
        let borrow = if mutable {
            BorrowKind::Mut
        } else {
            BorrowKind::Shared
        };
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(borrow, base));
        let out = self.temp(et);
        let ty_name = self.tys().display(bt);
        let method = if mutable { "index_mut" } else { "index" };
        self.call_native(
            &format!("{ty_name}.{method}"),
            vec![Operand::Move(Place::local(r)), idx],
            Place::local(out),
        );
        // An element that is a reference is what the native gives (a
        // borrow of a borrow is the borrow): the place is `out` itself.
        // Through a shared one nothing can be written, so a mutable place
        // of it could only replace the element, which needs the slot.
        if self.is_reference(elem) {
            if mutable && matches!(self.tys().tcx().kind(elem), HK::Ref(_)) {
                return self.unsupported(
                    e.span,
                    "replacing a reference element of a collection in place",
                );
            }
            return Ok(Place::local(out));
        }
        Ok(Place::local(out).project(ProjElem::Deref))
    }

    /// `base[idx]` on a user type: the place `*base.index(idx)`, or
    /// `*base.index_mut(idx)` for a write (design.md § `Index` and
    /// `IndexMut`, B-2026-10-14-37). The receiver is borrowed as the method's
    /// `self` asks; an index the method borrows is lent from a temporary.
    fn user_index_place(
        &mut self,
        base: Place,
        bt: Ty,
        idx: Operand,
        d: DefId,
        inst_args: Vec<Ty>,
        e: &'a Expr,
    ) -> R<Place> {
        let f = self.lcx.fns[&d].f;
        let (Some(m), [p]) = (f.self_param.clone(), f.params.as_slice()) else {
            return self.unsupported(
                e.span,
                "an index method that does not take `self` and an index",
            );
        };
        if self.lcx.fns[&d].impl_params == 0 {
            self.lcx.self_tys.entry(d).or_insert(bt);
        }
        let borrow = match self.self_mode(f, m, bt) {
            SelfParam::Ref => BorrowKind::Shared,
            SelfParam::MutRef => BorrowKind::Mut,
            SelfParam::Owned => {
                return self.unsupported(e.span, "an index method that takes `self` by value")
            }
        };
        let pt = self.callee_param_ty(p, &inst_args)?;
        let et = self.expr_ty(e)?;
        let (rt, out_t) = {
            let tcx = self.tys().tcx();
            let mutable = borrow == BorrowKind::Mut;
            (tcx.reference(bt, mutable), tcx.reference(et, mutable))
        };
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(borrow, base));
        let idx = self.lend_to(idx, pt);
        let out = self.temp(out_t);
        let name = self.lcx.instance(d, inst_args.clone());
        let func = self.fn_operand(&name, d, inst_args);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: vec![Operand::Move(Place::local(r)), idx],
                destination: Place::local(out),
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(Place::local(out).project(ProjElem::Deref))
    }

    /// `op` as an argument of type `pt`: lent from a temporary when `pt`
    /// is a reference and `op` is not. The temporary is the statement's, so
    /// a key that owns a value (`c["a".to_string()]`) is dropped with it.
    fn lend_to(&mut self, op: Operand, pt: Ty) -> Operand {
        match self.tys().tcx().kind(pt) {
            HK::Ref(it) | HK::MutRef(it) if !self.is_reference(self.operand_ty(&op)) => {
                let v = self.scoped_temp(it);
                self.assign(v, Rvalue::Use(op));
                let lent = self.temp(pt);
                let kind = if matches!(self.tys().tcx().kind(pt), HK::MutRef(_)) {
                    BorrowKind::Mut
                } else {
                    BorrowKind::Shared
                };
                self.assign(lent, Rvalue::Ref(kind, Place::local(v)));
                Operand::Move(Place::local(lent))
            }
            _ => op,
        }
    }

    /// `c[k] = v` on a user type with an `impl IndexSet`: the call
    /// `c.index_set(k, v)`, with the key, then the value, evaluated before
    /// the receiver's borrow starts, as for a map (design.md § `Index` and
    /// `IndexMut`, B-2026-10-14-47).
    #[allow(clippy::too_many_arguments)]
    fn user_index_set(
        &mut self,
        target: &'a Expr,
        object: &'a Expr,
        index: &'a Expr,
        value: &'a Expr,
        base: Ty,
        d: DefId,
        inst_args: Vec<Ty>,
    ) -> R<()> {
        let f = self.lcx.fns[&d].f;
        let (Some(m), [kp, vp]) = (f.self_param.clone(), f.params.as_slice()) else {
            return self.unsupported(
                target.span,
                "an `index_set` that does not take `self`, a key and a value",
            );
        };
        if self.lcx.fns[&d].impl_params == 0 {
            self.lcx.self_tys.entry(d).or_insert(base);
        }
        if self.self_mode(f, m, base) != SelfParam::MutRef {
            return self.unsupported(target.span, "an `index_set` without `mut ref self`");
        }
        let kt = self.callee_param_ty(kp, &inst_args)?;
        let vt = self.callee_param_ty(vp, &inst_args)?;
        let recv = self.recv_place(object, true)?;
        let key = match self.tys().tcx().kind(kt) {
            HK::Ref(_) | HK::MutRef(_) => {
                let k = self.expr_operand(index)?;
                self.lend_to(k, kt)
            }
            _ => self.owned_operand(index, kt)?,
        };
        let val = match self.tys().tcx().kind(vt) {
            HK::Ref(_) | HK::MutRef(_) => {
                let v = self.expr_operand(value)?;
                self.lend_to(v, vt)
            }
            _ => {
                let v = self.owned_operand(value, vt)?;
                if self.downgrades(&v, vt) {
                    self.downgrade(v, vt)
                } else {
                    self.widen(v, vt)
                }
            }
        };
        let mut rest = vec![key, val];
        let mut args = vec![self.recv_borrow_after(recv, &mut rest)?];
        args.extend(rest);
        let unit = self.unit();
        let out = self.temp(unit);
        let name = self.lcx.instance(d, inst_args.clone());
        let func = self.fn_operand(&name, d, inst_args);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args,
                destination: Place::local(out),
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(())
    }

    /// `base[idx]` on a fixed-size array: a bounds check that aborts, then
    /// the element place.
    fn array_index(&mut self, base: Place, idx: Operand) -> Place {
        let (usize_t, bool_t) = {
            let tcx = self.tys().tcx();
            (tcx.intern(HK::UInt(UIntSize::Usize)), tcx.intern(HK::Bool))
        };
        let idx = self.cast_index(idx, usize_t);
        let i = self.temp(usize_t);
        self.assign(i, Rvalue::Use(idx));
        let n = self.temp(usize_t);
        self.assign(n, Rvalue::Len(base.clone()));
        let c = self.temp(bool_t);
        self.assign(
            c,
            Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(Place::local(i)),
                Operand::Copy(Place::local(n)),
            ),
        );
        let ok = self.b.new_block();
        let bad = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(ok, bad),
            },
            bad,
        );
        self.diverge(TerminatorKind::Abort {
            reason: AbortReason::BoundsCheck,
        });
        self.cur = ok;
        base.project(ProjElem::Index(i))
    }

    /// `s[a..b]` on a `String`: a new `String` holding those bytes, from
    /// the library's `String.index_range(ref s, a, b)`, which panics off a
    /// char boundary or out of range. An open start is 0, an open end the
    /// length, and `a..=b` ends at `b + 1`.
    fn string_range(
        &mut self,
        object: &'a Expr,
        start: Option<&'a Expr>,
        end: Option<&'a Expr>,
        inclusive: bool,
        dest: Place,
    ) -> R<()> {
        let i64_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let p = self.expr_place(object, false)?;
        let (p, ct) = self.strip_refs(p);
        let rt = self.tys().tcx().reference(ct, false);
        let bound = |this: &mut Self, x: &'a Expr| -> R<Operand> {
            let (o, t) = this.scalar_operand(x)?;
            Ok(if t == i64_t {
                o
            } else {
                this.cast_index(o, i64_t)
            })
        };
        let lo = match start {
            Some(x) => bound(self, x)?,
            None => Operand::Const(Const {
                ty: i64_t,
                kind: ConstKind::Scalar(0),
            }),
        };
        let hi = match end {
            Some(x) => {
                let o = bound(self, x)?;
                if inclusive {
                    let one = Operand::Const(Const {
                        ty: i64_t,
                        kind: ConstKind::Scalar(1),
                    });
                    let h = self.temp(i64_t);
                    self.arith(BinOp::Add, o, one, i64_t, Place::local(h));
                    Operand::Copy(Place::local(h))
                } else {
                    o
                }
            }
            None => {
                let r = self.temp(rt);
                self.assign(r, Rvalue::Ref(BorrowKind::Shared, p.clone()));
                let n = self.temp(i64_t);
                self.call_native(
                    "String.len",
                    vec![Operand::Move(Place::local(r))],
                    Place::local(n),
                );
                Operand::Copy(Place::local(n))
            }
        };
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
        self.call_native(
            "String.index_range",
            vec![Operand::Move(Place::local(r)), lo, hi],
            dest,
        );
        Ok(())
    }

    fn cast_index(&mut self, idx: Operand, usize_t: Ty) -> Operand {
        match idx {
            Operand::Const(Const {
                kind: ConstKind::Scalar(v),
                ..
            }) => Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(v),
            }),
            other => {
                let t = self.temp(usize_t);
                self.assign(t, Rvalue::Cast(CastKind::IntToInt, other, usize_t));
                Operand::Copy(Place::local(t))
            }
        }
    }

    /// A value expression evaluated into a fresh temporary, as a place.
    fn temp_place(&mut self, e: &'a Expr) -> R<Place> {
        let t = self.expr_ty(e)?;
        let l = self.temp_of(e, t)?;
        Ok(Place::local(l))
    }

    /// Whether `t` is a `shared` handle, which a read copies with a count.
    fn is_handle(&self, t: Ty) -> bool {
        matches!(self.tys().tcx().kind(t), HK::Shared { .. })
    }

    /// An `Option`, `Result` or tuple made only of `shared` handles and `Copy` parts,
    /// with at least one handle: a read copies it by counting each handle,
    /// as for a bare handle (core semantics §6.1).
    fn is_handle_aggregate(&self, t: Ty) -> bool {
        let parts = match self.tys().tcx().kind(t) {
            HK::Tuple(l) => self.tys().tcx().list(l),
            HK::Adt { def, args }
                if matches!(self.lcx.def_name(def).as_str(), "Option" | "Result") =>
            {
                self.tys().tcx().list(args)
            }
            _ => return false,
        };
        let counted = |p: Ty| self.is_handle(p) || self.is_handle_aggregate(p);
        parts.iter().all(|&p| counted(p) || self.is_copy(p)) && parts.iter().any(|&p| counted(p))
    }

    /// `dest = <a counted copy of place>`, for a handle or handle aggregate.
    fn count_copy(&mut self, place: Place, t: Ty, dest: Place) {
        // A strong handle copied into a `weak` local is a new weak reference
        // to its object, made through a borrow: no strong count is taken
        // (B-2026-10-25-45).
        let dt = self.place_type(&dest);
        if matches!(self.tys().tcx().kind(dt), HK::Weak(_))
            && !matches!(self.tys().tcx().kind(t), HK::Weak(_))
        {
            let rt = self.tys().tcx().reference(t, false);
            let r = self.temp(rt);
            self.assign(r, Rvalue::Ref(BorrowKind::Shared, place));
            self.assign(
                dest,
                Rvalue::Cast(CastKind::Downgrade, Operand::Move(Place::local(r)), dt),
            );
            return;
        }
        if self.is_handle(t) {
            self.assign(dest, Rvalue::Retain(place));
        } else {
            let recv = self.ref_to(place, t);
            let name = format!("{}.clone", self.tys().display(t));
            self.call_native(&name, vec![recv], dest);
        }
    }

    /// A `weak` value behind a reference or an index cannot move out:
    /// reading it is a new weak handle to the same object (§6.5), a
    /// downgrade through a borrow of it, in a new temporary.
    fn weak_read(&mut self, p: &Place, t: Ty) -> Option<Local> {
        // A field of a `shared` value cannot move out either
        // (`c.parent = b.parent`, B-2026-10-13-23).
        let behind = p
            .projection
            .iter()
            .any(|e| matches!(e, ProjElem::Deref | ProjElem::Index(_)))
            || (0..p.projection.len()).any(|i| {
                let prefix = Place {
                    local: p.local,
                    projection: p.projection[..i].to_vec(),
                };
                matches!(
                    self.tys().tcx().kind(self.place_type(&prefix)),
                    HK::Shared { .. }
                )
            });
        if !behind || !matches!(self.tys().tcx().kind(t), HK::Weak(_)) {
            return None;
        }
        let rt = self.tys().tcx().reference(t, false);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, p.clone()));
        let w = self.temp(t);
        self.assign(
            w,
            Rvalue::Cast(CastKind::Downgrade, Operand::Move(Place::local(r)), t),
        );
        Some(w)
    }

    /// Read a place as an operand: a copy for a `Copy` type, else a move.
    fn use_place(&self, p: Place, t: Ty) -> Operand {
        if self.is_copy(t) {
            Operand::Copy(p)
        } else {
            Operand::Move(p)
        }
    }

    // ── expressions ─────────────────────────────────────────────────

    /// `e` taken as an owned value of type `want`. A borrowed place (a
    /// `ref` or `mut ref` parameter, which every bare parameter is under
    /// D5) is read through its reference: a `Copy` value copies, a handle
    /// counts, and anything else moves out of the borrow, which the borrow
    /// check refuses (core semantics §3.7).
    fn owned_operand(&mut self, e: &'a Expr, want: Ty) -> R<Operand> {
        let at = self.expr_ty(e)?;
        let inner = match self.tys().tcx().kind(at) {
            HK::Ref(t) | HK::MutRef(t) => t,
            _ => return self.expr_operand(e),
        };
        if inner != want {
            return self.expr_operand(e);
        }
        // A reference a call returns is read through its temporary.
        let p = if self.is_place(e) {
            self.expr_place(e, false)?
        } else {
            Place::local(self.temp_of(e, at)?)
        }
        .project(ProjElem::Deref);
        if self.is_handle(inner) || self.is_handle_aggregate(inner) {
            let l = self.temp(inner);
            self.count_copy(p, inner, Place::local(l));
            return Ok(Operand::Move(Place::local(l)));
        }
        Ok(self.use_place(p, inner))
    }

    /// `e` as an operand for a slot of type `want`. A tuple literal is
    /// built at the slot's element types, each element widened into its
    /// position: `(b, d)` with `b: u8` fills a `(i64, i64)` slot as
    /// `(b as i64, d as i64)`, not as the `(u8, u32)` the checker records.
    fn operand_at(&mut self, e: &'a Expr, want: Ty) -> R<Operand> {
        if let ExprKind::Tuple(es) = &e.kind {
            if let HK::Tuple(l) = self.tys().tcx().kind(want) {
                let wts = self.tys().tcx().list(l);
                if !es.is_empty() && wts.len() == es.len() && self.expr_ty(e)? != want {
                    let mut ops = Vec::with_capacity(es.len());
                    for (x, &wt) in es.iter().zip(&wts) {
                        ops.push(self.operand_at(x, wt)?);
                    }
                    let l = self.temp(want);
                    self.assign(l, Rvalue::Aggregate(AggregateKind::Tuple, ops));
                    return Ok(Operand::Move(Place::local(l)));
                }
            }
        }
        // A `ref` to a `Copy` value or handle in a value slot is read
        // (core semantics §5.10, §6.1).
        let et = self.expr_ty(e)?;
        // An owned place stored where a `ref` (or a `Str` view) is wanted
        // is lent, as it would be to a parameter.
        if matches!(
            self.tys().tcx().kind(want),
            HK::Ref(_) | HK::MutRef(_) | HK::StaticStr
        ) && !matches!(self.tys().tcx().kind(et), HK::Ref(_) | HK::MutRef(_))
            && et != want
        {
            return self.arg_operand(e, want);
        }
        if !matches!(self.tys().tcx().kind(want), HK::Ref(_) | HK::MutRef(_))
            && matches!(self.tys().tcx().kind(et), HK::Ref(_) | HK::MutRef(_))
        {
            return self.owned_operand(e, want);
        }
        // A value the checker typed with a free parameter left at `()`
        // (`None` beside `Some(s)` in `[Some(s), None]`) is built at the
        // slot's type.
        if et != want && !self.is_place(e) {
            let tcx = self.tys().tcx();
            if let (HK::Adt { def: a, .. }, HK::Adt { def: b, .. }) = (tcx.kind(et), tcx.kind(want))
            {
                if a == b {
                    let l = self.temp(want);
                    self.expr_into(e, Place::local(l))?;
                    return Ok(Operand::Move(Place::local(l)));
                }
            }
            // A function item or closure the checker typed as one function
            // type, going to a slot of another (a generic `Fn(V)` field at a
            // `Copy` `V` lends its argument), is erased once, straight to the
            // slot's type: an erase from one `Fn` to another is a copy
            // (B-2026-10-20-19).
            if matches!(tcx.kind(et), HK::Fn { .. }) && matches!(tcx.kind(want), HK::Fn { .. }) {
                let l = self.temp(want);
                self.expr_into(e, Place::local(l))?;
                return Ok(Operand::Move(Place::local(l)));
            }
        }
        let op = self.expr_operand(e)?;
        Ok(self.widen(op, want))
    }

    fn expr_operand(&mut self, e: &'a Expr) -> R<Operand> {
        if let Some(op) = self.literal_ref(e, None)? {
            return Ok(op);
        }
        if let Some(c) = self.constant(e)? {
            return Ok(Operand::Const(c));
        }
        if self.is_place(e) {
            let p = self.expr_place(e, false)?;
            let mut t = self.expr_ty(e)?;
            if let HK::Weak(_) = self.tys().tcx().kind(t) {
                // A strong handle the checker typed as the `weak` slot it
                // goes to: read it as the handle it is.
                t = self.place_type(&p);
            }
            if self.is_handle(t) || self.is_handle_aggregate(t) {
                let l = self.temp(t);
                self.count_copy(p, t, Place::local(l));
                return Ok(Operand::Move(Place::local(l)));
            }
            if let HK::MutRef(_) = self.tys().tcx().kind(t) {
                // A `mut ref` used as a value is reborrowed.
                let l = self.temp(t);
                self.assign(l, Rvalue::Ref(BorrowKind::Mut, p.project(ProjElem::Deref)));
                return Ok(Operand::Move(Place::local(l)));
            }
            if let Some(w) = self.weak_read(&p, t) {
                return Ok(Operand::Move(Place::local(w)));
            }
            return Ok(self.use_place(p, t));
        }
        let t = self.expr_ty(e)?;
        let l = self.temp_of(e, t)?;
        Ok(self.use_place(Place::local(l), t))
    }

    /// A literal lent to a `ref T` slot (the checker typed it `ref T`, or
    /// `slot` is one): a reference to a constant in static data, with no
    /// origins, which no statement end ends (core semantics §5.3). A
    /// `mut ref` slot keeps its temporary.
    fn literal_ref(&mut self, e: &'a Expr, slot: Option<Ty>) -> R<Option<Operand>> {
        if !matches!(
            e.kind,
            ExprKind::StringLit(_)
                | ExprKind::Integer(..)
                | ExprKind::Float(..)
                | ExprKind::Bool(_)
                | ExprKind::CharLit(_)
        ) {
            return Ok(None);
        }
        let et = self.expr_ty(e)?;
        let t = match (
            self.tys().tcx().kind(et),
            slot.map(|s| self.tys().tcx().kind(s)),
        ) {
            (HK::Ref(t), _) | (_, Some(HK::Ref(t))) => t,
            _ => return Ok(None),
        };
        if matches!(e.kind, ExprKind::StringLit(_))
            != matches!(self.tys().tcx().kind(t), HK::Str | HK::StaticStr)
        {
            return Ok(None);
        }
        // A `Str` is already a view of static text: borrow a local copy of
        // it rather than a static holding the view (B-2026-10-14-68).
        if let (ExprKind::StringLit(s), HK::StaticStr) = (&e.kind, self.tys().tcx().kind(t)) {
            let op = self.static_str(s);
            let v = self.temp(t);
            self.assign(v, Rvalue::Use(op));
            let r = self.temp(self.tys().tcx().reference(t, false));
            self.assign(r, Rvalue::Ref(BorrowKind::Shared, Place::local(v)));
            return Ok(Some(Operand::Move(Place::local(r))));
        }
        let i = self.lcx.literal_static(e, t);
        Ok(Some(Operand::Const(Const {
            ty: self.tys().tcx().reference(t, false),
            kind: ConstKind::Static(i),
        })))
    }

    fn is_local(&self, e: &Expr) -> bool {
        matches!(self.lcx.res.get(&e.id), Some(Res::Local(_)))
    }

    /// A literal as a constant, if `e` is one.
    fn constant(&mut self, e: &'a Expr) -> R<Option<Const>> {
        let scalar = |s: &mut Self, v: u128| -> R<Option<Const>> {
            let ty = s.expr_ty(e)?;
            Ok(Some(Const {
                ty,
                kind: ConstKind::Scalar(v),
            }))
        };
        match &e.kind {
            ExprKind::Integer(v, _) => scalar(self, *v as u128),
            ExprKind::Bool(b) => scalar(self, *b as u128),
            ExprKind::CharLit(c) => scalar(self, *c as u128),
            ExprKind::ByteLit(b) => scalar(self, *b as u128),
            ExprKind::Float(f, suffix) => {
                // A suffixed literal is a value of its suffix's type even
                // where it widens (`let w: f64 = 0.1f32`).
                use crate::token::FloatSuffix;
                let f = match suffix {
                    Some(FloatSuffix::F32) => FloatTy::F32.round(*f),
                    Some(FloatSuffix::BF16) => FloatTy::BF16.round(*f),
                    Some(FloatSuffix::F16) => FloatTy::F16.round(*f),
                    _ => *f,
                };
                let ty = self.expr_ty(e)?;
                Ok(Some(Const {
                    ty,
                    kind: ConstKind::Float(f.to_bits()),
                }))
            }
            ExprKind::Tuple(es) if es.is_empty() => Ok(Some(match unit_const(self.unit()) {
                Operand::Const(c) => c,
                _ => unreachable!(),
            })),
            ExprKind::Binary { .. } | ExprKind::Unary { .. } if fold_int(e, 128).is_some() => {
                // An operator tree of unsuffixed integer literals is one
                // constant, so it takes its destination's type as a single
                // literal does (`let n: i32 = -(2 * 3)`).
                let t = self.expr_ty(e)?;
                let kind = self.tys().tcx().kind(t);
                let bits = match kind {
                    HK::Int(IntSize::I128) | HK::UInt(UIntSize::U128) => 128,
                    _ => 64,
                };
                let (lo, hi) = int_range(kind);
                match fold_int_in(e, bits, lo, hi) {
                    Some(v) => scalar(self, v as u128),
                    None => Ok(None),
                }
            }
            ExprKind::Unary {
                op: UnaryOp::Neg,
                operand,
            } => match &operand.kind {
                ExprKind::Integer(v, _) => scalar(self, (-*v) as u128),
                ExprKind::Float(f, _) => {
                    let ty = self.expr_ty(e)?;
                    Ok(Some(Const {
                        ty,
                        kind: ConstKind::Float((-*f).to_bits()),
                    }))
                }
                _ => Ok(None),
            },
            _ => Ok(None),
        }
    }

    fn static_str(&self, s: &str) -> Operand {
        let t = self.tys().tcx().intern(HK::StaticStr);
        Operand::Const(Const {
            ty: t,
            kind: ConstKind::Str(s.to_string()),
        })
    }

    /// Evaluate `e` and store its value in `dest`. What it pushes carries
    /// `e`'s span, so a run that aborts in it names the place.
    fn expr_into(&mut self, e: &'a Expr, dest: Place) -> R<()> {
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo {
            span: e.span,
            ..outer
        });
        let r = self.expr_into_here(e, dest);
        self.b.set_source_info(outer);
        r
    }

    fn expr_into_here(&mut self, e: &'a Expr, dest: Place) -> R<()> {
        // `process.exit(code)`: the process ends here, with no drops.
        if let Some([code]) = process_exit_args(e) {
            let i32_t = self.tys().tcx().intern(HK::Int(IntSize::I32));
            let op = self.operand_at(&code.value, i32_t)?;
            let u = self.temp(self.unit());
            self.call_native("process.exit", vec![op], Place::local(u));
            self.diverge(TerminatorKind::Unreachable);
            return Ok(());
        }
        // A concrete value into a `dyn` slot (design.md § `dyn Trait`):
        // made at its own type, then coerced by `assign`.
        let dt = self.place_type(&dest);
        if self.dyn_under(dt).is_some() {
            let et = self.expr_ty(e)?;
            if self.dyn_under(et).is_none() && !matches!(self.tys().tcx().kind(et), HK::Never) {
                let l = self.temp(et);
                self.expr_into(e, Place::local(l))?;
                self.assign(dest, Rvalue::Use(Operand::Move(Place::local(l))));
                return Ok(());
            }
        }
        // B-2026-10-18-4 — a call that returns a `ref T` of a `Copy` (or
        // handle) `T`, stored into a `T` slot (`-> i64` returning
        // `m.get(k).unwrap_or(0)`): the slot takes the value read through
        // the reference (core semantics §5.10), not the reference itself,
        // which a compiled backend stored as an address.
        if matches!(e.kind, ExprKind::Call { .. } | ExprKind::MethodCall { .. }) {
            let dt = self.place_type(&dest);
            let et = self.expr_ty(e)?;
            if matches!(self.tys().tcx().kind(et), HK::Ref(i) | HK::MutRef(i) if i == dt)
                && (self.is_copy(dt) || self.is_handle(dt))
            {
                let op = self.owned_operand(e, dt)?;
                self.assign(dest, Rvalue::Use(op));
                return Ok(());
            }
            // A number the slot widens (`let x: f64 = f()` with `f() ->
            // f32`, design.md §5): the call writes a temporary of its own
            // type, which is widened into the slot (B-2026-10-29-22).
            if self.widening(et, dt).is_some() && self.lossless(et, dt) {
                let l = self.temp(et);
                self.expr_into(e, Place::local(l))?;
                let op = self.widen(Operand::Move(Place::local(l)), dt);
                self.assign(dest, Rvalue::Use(op));
                return Ok(());
            }
        }
        // A strong handle or an `Option` of one, made by a call, a
        // constructor or a branch, stored into a `weak` slot: made in a
        // temporary of its own type, then downgraded by `assign` as a
        // local's handle is (B-2026-10-13-23). A struct literal into a
        // `weak` local is one too (B-2026-10-25-45).
        if let HK::Weak(_) = self.tys().tcx().kind(self.place_type(&dest)) {
            if matches!(
                e.kind,
                ExprKind::Call { .. }
                    | ExprKind::StructLiteral { .. }
                    | ExprKind::MethodCall { .. }
                    | ExprKind::If { .. }
                    | ExprKind::Match { .. }
                    | ExprKind::Block(..)
            ) {
                let et = self.expr_ty(e)?;
                if !matches!(self.tys().tcx().kind(et), HK::Weak(_)) {
                    let t = self.temp(et);
                    self.expr_into(e, Place::local(t))?;
                    self.assign(dest, Rvalue::Use(Operand::Move(Place::local(t))));
                    return Ok(());
                }
            }
        }
        if let Some(op) = self.literal_ref(e, None)? {
            self.assign(dest, Rvalue::Use(op));
            return Ok(());
        }
        if let Some(mut c) = self.constant(e)? {
            // An unsuffixed literal takes its destination's numeric type
            // (`let c: i8 = 100` records the literal as `i64`).
            let dt = self.place_type(&dest);
            let tcx = self.tys().tcx();
            let int = |t| matches!(tcx.kind(t), HK::Int(_) | HK::UInt(_));
            let float = |t| matches!(tcx.kind(t), HK::Float(_));
            if (int(c.ty) && int(dt)) || (float(c.ty) && float(dt)) {
                c.ty = dt;
            }
            self.assign(dest, Rvalue::Use(Operand::Const(c)));
            return Ok(());
        }
        match &e.kind {
            // A literal the checker typed `Str` (a `Str` was expected) is the
            // view of its static data (design.md § String literals).
            ExprKind::StringLit(s)
                if matches!(self.tys().tcx().kind(self.place_type(&dest)), HK::StaticStr) =>
            {
                let op = self.static_str(s);
                self.assign(dest, Rvalue::Use(op));
                Ok(())
            }
            ExprKind::StringLit(s) => {
                let op = self.static_str(s);
                self.call_native("String.from", vec![op], dest);
                Ok(())
            }
            ExprKind::Identifier(_) if !self.is_local(e) => self.path_value(e, dest),
            ExprKind::Closure { .. } => {
                // A closure stored as a function value escapes, so it
                // captures by move (core semantics §9.3).
                let dt = self.place_type(&dest);
                self.closure_escapes = matches!(self.tys().tcx().kind(dt), HK::Fn { .. });
                let (op, _) = self.closure_value(e)?;
                self.assign(dest, Rvalue::Use(op));
                Ok(())
            }
            ExprKind::Path { .. } if !self.is_place(e) => self.path_value(e, dest),
            ExprKind::Index { object, index } if !self.is_place(e) => {
                let ExprKind::Range {
                    start,
                    end,
                    inclusive,
                } = &index.kind
                else {
                    // `let r = 1..3; v[r]`: the bounds are the value's.
                    let t = self.expr_ty(e)?;
                    let s = self.slice_view_by(object, index, t)?;
                    self.assign(dest, Rvalue::Use(Operand::Move(Place::local(s))));
                    return Ok(());
                };
                let ot = self.expr_ty(object)?;
                if matches!(self.strip_ty(ot), HK::Str | HK::StaticStr) {
                    let (start, end) = (start.as_deref(), end.as_deref());
                    return self.string_range(object, start, end, *inclusive, dest);
                }
                let t = self.expr_ty(e)?;
                let range = (start.as_deref(), end.as_deref(), *inclusive);
                let s = self.slice_view(object, Some(range), t, false)?;
                self.assign(dest, Rvalue::Use(Operand::Move(Place::local(s))));
                Ok(())
            }
            ExprKind::FieldAccess { .. } if self.int_limit_of(e).is_some() => {
                let (t, kind) = self.int_limit_of(e).expect("checked above");
                self.assign(dest, Rvalue::Use(Operand::Const(Const { ty: t, kind })));
                Ok(())
            }
            ExprKind::FieldAccess { .. } if self.builtin_fn_def(e).is_some() => {
                let d = self.builtin_fn_def(e).expect("checked");
                let want = self.place_type(&dest);
                let (op, _) = self.fn_item_value(e, d, Some(want))?;
                self.assign(dest, Rvalue::Use(op));
                Ok(())
            }
            _ if self.is_place(e) => {
                let dt = self.place_type(&dest);
                let mutable = matches!(self.tys().tcx().kind(dt), HK::MutRef(_));
                let mut p = self.expr_place(e, mutable)?;
                let mut t = self.place_type(&p);
                // A `ref T` flowing into a `T` slot is read through: a copy
                // for a Copy `T` (`fn f(x: ref i64) -> i64 { return x; }`),
                // else a move the borrow check refuses.
                while let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
                    if t == dt || self.ref_depth(t) <= self.ref_depth(dt) {
                        break;
                    }
                    p = p.project(ProjElem::Deref);
                    t = inner;
                }
                // A `mut ref` used as a value is reborrowed, `&mut (*r)`, so
                // its source keeps it (as when it is passed on).
                if let (HK::MutRef(inner), HK::Ref(di) | HK::MutRef(di)) =
                    (self.tys().tcx().kind(t), self.tys().tcx().kind(dt))
                {
                    if di == inner {
                        let kind = if mutable {
                            BorrowKind::Mut
                        } else {
                            BorrowKind::Shared
                        };
                        self.assign(dest, Rvalue::Ref(kind, p.project(ProjElem::Deref)));
                        return Ok(());
                    }
                }
                // A place of `T` flowing into a `ref T` slot is borrowed.
                if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(dt) {
                    if inner == t {
                        let kind = if mutable {
                            BorrowKind::Mut
                        } else {
                            BorrowKind::Shared
                        };
                        self.assign(dest, Rvalue::Ref(kind, p));
                        return Ok(());
                    }
                }
                if self.is_handle(t) || self.is_handle_aggregate(t) {
                    // Copying a `shared` handle counts; the source keeps
                    // its own (core semantics §6.1).
                    self.count_copy(p, t, dest);
                    return Ok(());
                }
                if let Some(w) = self.weak_read(&p, t) {
                    self.assign(dest, Rvalue::Use(Operand::Move(Place::local(w))));
                    return Ok(());
                }
                let op = self.use_place(p, t);
                self.assign(dest, Rvalue::Use(op));
                Ok(())
            }
            ExprKind::Binary {
                op: op @ (AstBinOp::Range | AstBinOp::RangeInclusive),
                left,
                right,
            } => self.range_value(e, left, Some(right), *op == AstBinOp::RangeInclusive, dest),
            ExprKind::Range {
                start: Some(left),
                end: Some(right),
                inclusive,
            } => self.range_value(e, left, Some(right), *inclusive, dest),
            // B-2026-10-21-46 — `a..` as a value is the library's `RangeFrom`.
            ExprKind::Range {
                start: Some(left),
                end: None,
                inclusive: false,
            } => self.range_value(e, left, None, false, dest),
            ExprKind::Binary { op, left, right } => self.binary(op.clone(), left, right, dest),
            ExprKind::Unary { op, operand } => {
                // B-2026-10-14-33 — `-a` / `~a` on a user type with an
                // `impl Neg` / `impl Not` calls its `neg` / `not`.
                let user = match op {
                    UnaryOp::Neg => Some(("Neg", "neg")),
                    UnaryOp::BitNot => Some(("Not", "not")),
                    _ => None,
                };
                if let Some((tr, m)) = user {
                    let ot = self.expr_ty(operand)?;
                    let (_, base) = self.strip_ty_full(ot);
                    if let Some((d, args)) = self.user_impl_method(base, tr, m) {
                        return self.user_operator_call(operand, None, d, args, dest);
                    }
                }
                let mop = match op {
                    UnaryOp::Neg => UnOp::Neg,
                    // `!` on a bool, `~` on an integer: both are `Not`.
                    UnaryOp::Not | UnaryOp::BitNot => UnOp::Not,
                    // `ref v[i]`: a shared borrow of a place.
                    UnaryOp::Ref if self.is_place(operand) => {
                        let p = self.expr_place(operand, false)?;
                        self.assign(dest, Rvalue::Ref(BorrowKind::Shared, p));
                        return Ok(());
                    }
                    // `mut ref v[i]`: a unique borrow of a place
                    // (B-2026-10-15-14).
                    UnaryOp::MutRef if self.is_place(operand) => {
                        let p = self.expr_place(operand, true)?;
                        self.assign(dest, Rvalue::Ref(BorrowKind::Mut, p));
                        return Ok(());
                    }
                    _ => return self.unsupported(e.span, "this unary operator"),
                };
                let t = self.expr_ty(operand)?;
                if let Some(bt) = self.distinct_base(t).filter(|&bt| self.is_copy(bt)) {
                    // `-d` on an `Arithmetic` distinct type.
                    let p = self.expr_place(operand, false)?;
                    let v = self.temp(bt);
                    self.assign(
                        Place::local(v),
                        Rvalue::UnaryOp(mop, Operand::Copy(p.field(0, bt))),
                    );
                    self.wrap_distinct(t, v, dest);
                    return Ok(());
                }
                let (o, _) = self.scalar_operand(operand)?;
                self.assign(dest, Rvalue::UnaryOp(mop, o));
                Ok(())
            }
            ExprKind::Tuple(es) => {
                // Each element is built at its position's type in the
                // destination, which may be wider than the element's own.
                let dt = self.place_type(&dest);
                let wts = match self.tys().tcx().kind(dt) {
                    HK::Tuple(l) => self.tys().tcx().list(l),
                    _ => Vec::new(),
                };
                let mut ops = Vec::new();
                for (i, x) in es.iter().enumerate() {
                    ops.push(match wts.get(i) {
                        Some(&wt) if wts.len() == es.len() => self.operand_at(x, wt)?,
                        _ => self.expr_operand(x)?,
                    });
                }
                self.assign(dest, Rvalue::Aggregate(AggregateKind::Tuple, ops));
                Ok(())
            }
            ExprKind::ArrayLiteral(es) => self.array_literal(e, es, dest),
            // `c"..."` is a `ref CStr` to its bytes, which live in a place
            // of the body's own that nothing drops (design.md § C-String
            // Literals gives them the program's lifetime).
            ExprKind::CStringLit { bytes, .. } => {
                let rt = self.expr_ty(e)?;
                let ct = match self.tys().tcx().kind(rt) {
                    HK::Ref(t) => t,
                    _ => rt,
                };
                let u8_t = self.tys().tcx().intern(HK::UInt(UIntSize::U8));
                let ops = bytes
                    .iter()
                    .map(|&b| {
                        Operand::Const(Const {
                            ty: u8_t,
                            kind: ConstKind::Scalar(b as u128),
                        })
                    })
                    .collect();
                let l = self.temp(ct);
                self.call_native("CStr.from_bytes", ops, Place::local(l));
                self.assign(dest, Rvalue::Ref(BorrowKind::Shared, Place::local(l)));
                Ok(())
            }
            // `b"..."` is an `Array[u8, N]` of its bytes (design.md § Byte
            // and byte-string literals).
            ExprKind::ByteStringLit(bytes) => {
                let u8_t = self.tys().tcx().intern(HK::UInt(UIntSize::U8));
                let ops = bytes
                    .iter()
                    .map(|&b| {
                        Operand::Const(Const {
                            ty: u8_t,
                            kind: ConstKind::Scalar(b as u128),
                        })
                    })
                    .collect();
                self.assign(dest, Rvalue::Aggregate(AggregateKind::Array(u8_t), ops));
                Ok(())
            }
            ExprKind::MapLiteral { entries, .. } => self.map_literal(e, entries, dest),
            ExprKind::PrefixCollectionLiteral { items, .. } => self.prefix_literal(e, items, dest),
            ExprKind::StructLiteral {
                fields,
                spread: None,
                ..
            } => {
                let t = self.expr_ty(e)?;
                // `E.A { v: .. }` builds a variant with named fields.
                let variant = match self.lcx.res.get(&e.id) {
                    Some(Res::Def(d)) => self.lcx.variant(*d).map(|(_, i)| i),
                    _ => None,
                };
                // Fields are evaluated in source order and stored in
                // declaration order.
                let mut vals: Vec<(u32, Operand)> = Vec::new();
                for fi in fields {
                    let Some((idx, ft)) = self.field_of(t, variant, &fi.name) else {
                        return self.unsupported(fi.span, "this field");
                    };
                    let op = self.operand_at(&fi.value, ft)?;
                    vals.push((idx, op));
                }
                vals.sort_by_key(|(i, _)| *i);
                let ops = vals.into_iter().map(|(_, o)| o).collect();
                let kind = self.adt_aggregate(t, variant.unwrap_or(0));
                self.assign(dest.clone(), Rvalue::Aggregate(kind, ops));
                Ok(())
            }
            ExprKind::Block(b) => self.block_into(b, dest),
            ExprKind::Providers { bindings, body } => self.providers_into(bindings, body, dest),
            ExprKind::If {
                condition,
                then_block,
                else_branch,
            } => {
                // The condition's temporaries drop once it is evaluated,
                // before either branch runs (core semantics §7.4).
                self.push_scope();
                // A borrowed `bool` (`for w in v.iter() { if w {..} }`) is read.
                let bool_t = self.tys().bool();
                let c = self.owned_operand(condition, bool_t)?;
                let c = self.read_before_drops(c, bool_t);
                self.pop_scope()?;
                let then_bb = self.b.new_block();
                let else_bb = self.b.new_block();
                let join = self.b.new_block();
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: c,
                        targets: SwitchTargets::if_else(then_bb, else_bb),
                    },
                    then_bb,
                );
                self.block_into(then_block, dest.clone())?;
                self.goto(join);
                self.cur = else_bb;
                match else_branch {
                    Some(els) => {
                        self.push_scope();
                        self.expr_into(els, dest)?;
                        self.pop_scope()?;
                    }
                    None => self.assign(dest, Rvalue::Use(unit_const(self.unit()))),
                }
                self.goto(join);
                self.cur = join;
                Ok(())
            }
            ExprKind::Match { scrutinee, arms } => self.lower_match(e, scrutinee, arms, dest),
            ExprKind::IfLet {
                pattern,
                value,
                then_block,
                else_branch,
            } => self.if_let(pattern, value, then_block, else_branch.as_deref(), dest),
            ExprKind::WhileLet {
                label,
                pattern,
                value,
                body,
                ..
            } => {
                let head = self.b.new_block();
                let exit = self.b.new_block();
                self.goto(head);
                self.cur = head;
                self.loops.push(LoopCx {
                    label: label.clone(),
                    break_bb: exit,
                    continue_bb: head,
                    depth: self.scopes.len(),
                    dest: None,
                });
                let r = self.while_let_round(pattern, value, body, head, exit);
                self.loops.pop();
                r?;
                self.cur = exit;
                self.assign(dest, Rvalue::Use(unit_const(self.unit())));
                Ok(())
            }
            ExprKind::LabeledBlock { label, body, .. } => {
                let exit = self.b.new_block();
                self.loops.push(LoopCx {
                    label: Some(label.clone()),
                    break_bb: exit,
                    continue_bb: exit,
                    depth: self.scopes.len(),
                    dest: Some(dest.clone()),
                });
                let r = self.block_into(body, dest);
                self.loops.pop();
                r?;
                self.goto(exit);
                self.cur = exit;
                Ok(())
            }
            ExprKind::Unsafe(b) => self.block_into(b, dest),
            ExprKind::Comptime(b) if self.lcx.comptime_eval => self.block_into(b, dest),
            // The branches of a `par` block run one after another, in source
            // order: one of the schedules the block allows (the sequential
            // scheduler's).
            ExprKind::Par(b) => self.par_block(e, b, dest),
            // `seq { .. }` only suppresses auto-parallelism: nothing in it
            // is a candidate (M4 item 14).
            ExprKind::Seq(b) => {
                self.seq_depth += 1;
                let r = self.block_into(b, dest);
                self.seq_depth -= 1;
                r
            }
            ExprKind::RepeatLiteral { value, count, .. } => {
                self.repeat_literal(e, value, count, dest)
            }
            ExprKind::OptionalChain {
                object,
                field_or_method,
                args: None,
            } => self.optional_chain(e, object, field_or_method, dest),
            ExprKind::Lock { mutex, alias, body } => self.lock_block(e, mutex, alias, body, dest),
            ExprKind::Cast { expr: inner, ty } => {
                // `x as T` of a refinement `T`: the cast to its base, and a
                // panic unless the value satisfies `T`'s predicate.
                let refined = match &ty.kind {
                    ast::TypeKind::Path(p) => p
                        .segments
                        .last()
                        .filter(|n| self.lcx.refined.contains_key(*n)),
                    _ => None,
                };
                let Some(name) = refined else {
                    return self.cast_into(e, inner, dest);
                };
                let to = self.expr_ty(e)?;
                let v = self.temp(to);
                self.cast_into(e, inner, Place::local(v))?;
                self.require_refinement(name, v)?;
                self.assign(dest, Rvalue::Use(Operand::Move(Place::local(v))));
                Ok(())
            }
            ExprKind::While {
                label,
                condition,
                body,
                ..
            } => {
                let counted = match self.lcx.auto_par {
                    AutoPar::Off => None,
                    _ if self.seq_depth > 0 => None,
                    _ => self.counted_while(e, condition, body)?,
                };
                if let (Some(cw), AutoPar::Apply(hints)) = (counted, &self.lcx.auto_par) {
                    let key = (self.name.clone(), e.span.offset, e.span.length);
                    if let Some(reds) = hints.loops.get(&key).cloned() {
                        if !leaves_loop(cw.inner) {
                            if let Some(red) = self.auto_par_plan(cw.inner, &reds)? {
                                return self.auto_par_while(e, label, cw, red, dest);
                            }
                        }
                    }
                }
                let head = self.b.new_block();
                let body_bb = self.b.new_block();
                let exit = self.b.new_block();
                self.goto(head);
                self.cur = head;
                self.push_scope();
                // A borrowed `bool` (`for w in v.iter() { if w {..} }`) is read.
                let bool_t = self.tys().bool();
                let c = self.owned_operand(condition, bool_t)?;
                let c = self.read_before_drops(c, bool_t);
                self.pop_scope()?;
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: c,
                        targets: SwitchTargets::if_else(body_bb, exit),
                    },
                    body_bb,
                );
                match counted {
                    // The body's step outside the candidate, so the
                    // iterations' uses of the counter are reads.
                    Some(cw) if matches!(self.lcx.auto_par, AutoPar::Record) => {
                        self.loops.push(LoopCx {
                            label: label.clone(),
                            break_bb: exit,
                            continue_bb: head,
                            depth: self.scopes.len(),
                            dest: None,
                        });
                        let r = self
                            .auto_par_record(cw.inner, e.span)
                            .and_then(|()| self.stmt(cw.step));
                        self.loops.pop();
                        r?;
                        self.goto(head);
                    }
                    _ => self.loop_body(label, body, head, exit, None)?,
                }
                self.cur = exit;
                self.assign(dest, Rvalue::Use(unit_const(self.unit())));
                Ok(())
            }
            ExprKind::Loop { label, body, .. } => {
                let head = self.b.new_block();
                let exit = self.b.new_block();
                self.goto(head);
                self.cur = head;
                self.loop_body(label, body, head, exit, Some(dest))?;
                self.cur = exit;
                Ok(())
            }
            ExprKind::For {
                label,
                pattern,
                iterable,
                body,
                par: Some(par),
                ..
            } => self.par_for(e, label, pattern, iterable, body, par, dest),
            ExprKind::For {
                label,
                pattern,
                iterable,
                body,
                ..
            } => self.seq_for(e, label, pattern, iterable, body, dest),
            ExprKind::Return(value) => {
                let ret = Place::local(Local::RETURN_PLACE);
                // In a `par` branch's task the function's value ends the
                // task, in its exit variant (core semantics §11.7).
                if let Some((t, _)) = self.par_exit {
                    let l = self.temp(t);
                    match value {
                        Some(v) => self.expr_into(v, Place::local(l))?,
                        None => self.assign(l, Rvalue::Use(unit_const(self.unit()))),
                    }
                    let v = self.exit_value(Rvalue::Use(Operand::Move(Place::local(l))));
                    self.assign(ret, v);
                    return self.return_exit();
                }
                // A closure whose every exit is a `return` was typed as
                // returning `!`; its returns say what it gives back.
                if let Some(v) = value {
                    let never = self.tys().tcx().intern(HK::Never);
                    if self.b.local_ty(Local::RETURN_PLACE) == never {
                        let vt = self.expr_ty(v)?;
                        if vt != never {
                            self.b.set_local_ty(Local::RETURN_PLACE, vt);
                        }
                    }
                }
                match value {
                    Some(v) => self.expr_into(v, ret)?,
                    None => self.assign(ret, Rvalue::Use(unit_const(self.unit()))),
                }
                self.return_exit()
            }
            ExprKind::Break { label, value } => {
                let Some(i) = self.find_loop(label) else {
                    return self.unsupported(e.span, "this `break`");
                };
                if let Some(v) = value {
                    match self.loops[i].dest.clone() {
                        Some(d) => self.expr_into(v, d)?,
                        // `break 'outer ()` out of a `while`: the unit is
                        // evaluated and the loop left.
                        None if self.expr_ty(v)? == self.unit() => {
                            let u = self.temp(self.unit());
                            self.expr_into(v, Place::local(u))?;
                        }
                        None => return self.unsupported(e.span, "`break` with a value here"),
                    }
                } else if let Some(d) = self.loops[i].dest.clone() {
                    self.assign(d, Rvalue::Use(unit_const(self.unit())));
                }
                let depth = self.loops[i].depth;
                self.exit_to(depth, false)?;
                let target = self.loops[i].break_bb;
                self.diverge(TerminatorKind::Goto { target });
                Ok(())
            }
            ExprKind::Continue { label, .. } => {
                let Some(i) = self.find_loop(label) else {
                    return self.unsupported(e.span, "this `continue`");
                };
                let depth = self.loops[i].depth;
                self.exit_to(depth, false)?;
                let target = self.loops[i].continue_bb;
                self.diverge(TerminatorKind::Goto { target });
                Ok(())
            }
            ExprKind::Call { callee, args } => self.call(e, callee, args, dest),
            ExprKind::MethodCall {
                object,
                method,
                args,
                ..
            } => self.method_call(e, object, method, args, dest),
            ExprKind::Question(inner) => self.question(e, inner, dest),
            ExprKind::NilCoalesce { left, right } => self.nil_coalesce(left, right, dest),
            ExprKind::InterpolatedStringLit(_) => {
                // An f-string as a value: the library's `format`, which takes
                // the parts the way `print` does.
                let mut ops = Vec::new();
                self.print_operands(e, &mut ops)?;
                self.call_native("format", ops, dest);
                Ok(())
            }
            other => {
                let dbg = format!("{other:?}");
                let kind = dbg.split(['(', ' ', '{']).next().unwrap_or("").to_string();
                self.unsupported(e.span, &format!("the expression kind `{kind}`"))
            }
        }
    }

    /// `a..b`, `a..=b` or `a..` as a value: the library's `Range`,
    /// `RangeInclusive` or `RangeFrom`, which a held or adapted range
    /// iterates through.
    fn range_value(
        &mut self,
        e: &'a Expr,
        left: &'a Expr,
        right: Option<&'a Expr>,
        inclusive: bool,
        dest: Place,
    ) -> R<()> {
        let t = self.expr_ty(e)?;
        let Some((_, st)) = self.field_of(t, None, "start") else {
            return self.unsupported(e.span, "a range value");
        };
        let mut ops = vec![self.operand_at(left, st)?];
        if let Some(right) = right {
            let Some((_, et)) = self.field_of(t, None, "end") else {
                return self.unsupported(e.span, "a range value");
            };
            ops.push(self.operand_at(right, et)?);
        }
        if inclusive {
            ops.push(bool_const(self.tys().bool(), false));
        }
        let kind = self.adt_aggregate(t, 0);
        self.assign(dest, Rvalue::Aggregate(kind, ops));
        Ok(())
    }

    /// A path naming a value: a unit variant (`None`, `E.A`) or a constant.
    fn path_value(&mut self, e: &'a Expr, dest: Place) -> R<()> {
        // `ExitCode.SUCCESS`, `ExitCode.FAILURE`: the library's codes.
        if let ExprKind::Path { segments, .. } = &e.kind {
            if let [ty, c] = segments.as_slice() {
                if let Some(code) = crate::prelude::lookup_exitcode_const(ty, c) {
                    let t = self.expr_ty(e)?;
                    if let Some(bt) = self.distinct_base(t) {
                        let v = self.temp(bt);
                        let op = Operand::Const(Const {
                            ty: bt,
                            kind: ConstKind::Scalar(code as u32 as u128),
                        });
                        self.assign(Place::local(v), Rvalue::Use(op));
                        self.wrap_distinct(t, v, dest);
                        return Ok(());
                    }
                }
            }
        }
        // `None` stored into a `weak` slot is an empty weak reference: the
        // `None` downgraded, the same shape as an `Option` value stored there.
        let t = self.expr_ty(e)?;
        if let HK::Weak(inner) = self.tys().tcx().kind(t) {
            let Some(ot) = self.option_of(inner) else {
                return self.unsupported(e.span, "this path");
            };
            let none = self
                .tys()
                .tcx()
                .adt_of(ot)
                .and_then(|(a, _)| a.variants.iter().position(|v| v.name == "None"));
            let Some(idx) = none else {
                return self.unsupported(e.span, "this path");
            };
            let l = self.temp(ot);
            let kind = self.adt_aggregate(ot, idx as u32);
            self.assign(l, Rvalue::Aggregate(kind, Vec::new()));
            let w = self.downgrade(Operand::Move(Place::local(l)), t);
            self.assign(dest, Rvalue::Use(w));
            return Ok(());
        }
        // A type named in value position is a comptime `Type`, carried as
        // its name (B-2026-10-22-20).
        if let Some(Res::Def(d)) = self.lcx.res.get(&e.id) {
            let kind = self.lcx.defs.table.get(*d).kind;
            if matches!(
                kind,
                DefKind::Struct | DefKind::Enum | DefKind::Union | DefKind::TypeAlias
            ) && matches!(self.tys().tcx().kind(t), HK::Str)
            {
                let name = self.lcx.def_name(*d);
                let op = self.static_str(&name);
                self.call_native("String.from", vec![op], dest);
                return Ok(());
            }
        }
        // `F64.from` as a value is the library's `f64_wrapper_from`.
        if let ExprKind::Path { segments, .. } = &e.kind {
            let wrapper = match segments.as_slice() {
                [w, m] if m == "from" && w == "F64" => Some("f64_wrapper_from"),
                [w, m] if m == "from" && w == "F32" => Some("f32_wrapper_from"),
                _ => None,
            };
            if let Some(d) = wrapper.and_then(|w| self.lcx.defs.lookup(0, w)) {
                let want = self.place_type(&dest);
                let (op, _) = self.fn_item_value(e, d, Some(want))?;
                self.assign(dest, Rvalue::Use(op));
                return Ok(());
            }
        }
        match self.lcx.res.get(&e.id) {
            Some(Res::Def(d)) => {
                let d = *d;
                // A variant of an enum not registered yet is placed by
                // name below.
                let variant = self.lcx.variant(d).or_else(|| {
                    (self.lcx.defs.table.get(d).kind == DefKind::Variant).then_some((d, 0))
                });
                match variant {
                    Some((_, idx)) => {
                        // A fieldless variant takes its destination's type
                        // when the checker left a parameter free (`None`).
                        let mut t = self.expr_ty(e)?;
                        let dt = self.place_type(&dest);
                        let tcx = self.tys().tcx();
                        if let (HK::Adt { def: a, .. }, HK::Adt { def: b, .. }) =
                            (tcx.kind(t), tcx.kind(dt))
                        {
                            if a == b {
                                t = dt;
                            }
                        }
                        // A `None` handed to a `ref Option[T]` parameter is
                        // typed by the reference; the enum it names decides
                        // its variant (B-2026-10-19-31).
                        let et = match self.tys().tcx().kind(t) {
                            HK::Ref(inner) | HK::MutRef(inner) => inner,
                            _ => t,
                        };
                        let idx = self.variant_at(d, et).unwrap_or(idx);
                        self.build_variant(t, idx, Vec::new(), dest);
                        Ok(())
                    }
                    None if self.lcx.lowered_def(d).is_some() => {
                        let want = self.place_type(&dest);
                        let (op, _) = self.fn_item_value(e, d, Some(want))?;
                        self.assign(dest, Rvalue::Use(op));
                        Ok(())
                    }
                    None if self.lcx.statics.contains_key(&d) => {
                        let p = self.static_place(d);
                        let t = self.place_type(&p);
                        if !self.is_copy(t) {
                            return self.unsupported(e.span, "a move out of a module binding");
                        }
                        self.assign(dest, Rvalue::Use(Operand::Copy(p)));
                        Ok(())
                    }
                    None => match self.lcx.consts.get(&d) {
                        // A constant's value is computed where it is used.
                        Some(value) => self.const_value(e, value, dest),
                        None => self.unsupported(e.span, "this path"),
                    },
                }
            }
            Some(Res::Builtin(_)) if self.builtin_fn_def(e).is_some() => {
                let d = self.builtin_fn_def(e).expect("checked");
                let want = self.place_type(&dest);
                let (op, _) = self.fn_item_value(e, d, Some(want))?;
                self.assign(dest, Rvalue::Use(op));
                Ok(())
            }
            Some(Res::Builtin(path)) => {
                let path = path.clone();
                let t = self.expr_ty(e)?;
                let Some(v) = int_limit(self.tys().tcx().kind(t), &path) else {
                    return self.unsupported(e.span, "this path");
                };
                self.assign(
                    dest,
                    Rvalue::Use(Operand::Const(Const {
                        ty: t,
                        kind: ConstKind::Scalar(v),
                    })),
                );
                Ok(())
            }
            _ => self.unsupported(e.span, "this name"),
        }
    }

    /// A use `e` of a constant whose value is `value`, at the type the use
    /// was checked at (an unsuffixed literal takes the declared type).
    fn const_value(&mut self, e: &'a Expr, value: &'a Expr, dest: Place) -> R<()> {
        let t = self.expr_ty(e)?;
        let vt = self.expr_ty(value)?;
        if t == vt {
            return self.expr_into(value, dest);
        }
        let op = self.expr_operand(value)?;
        let op = match op {
            Operand::Const(Const {
                kind: ConstKind::Scalar(v),
                ..
            }) => Operand::Const(Const {
                ty: t,
                kind: ConstKind::Scalar(v),
            }),
            Operand::Const(Const {
                kind: ConstKind::Float(v),
                ..
            }) => Operand::Const(Const {
                ty: t,
                kind: ConstKind::Float(v),
            }),
            _ => return self.unsupported(e.span, "a constant used at another type"),
        };
        self.assign(dest, Rvalue::Use(op));
        Ok(())
    }

    /// `dest = ` variant `idx` of `t` with payload `ops`. A constructor
    /// handed to a borrowed parameter (`t` is `ref Option[R]` for
    /// `show(None)`) builds the value it lends in a temporary of the scope.
    fn build_variant(&mut self, t: Ty, idx: u32, ops: Vec<Operand>, dest: Place) {
        let lend = match self.tys().tcx().kind(t) {
            HK::Ref(inner) => Some((inner, BorrowKind::Shared)),
            HK::MutRef(inner) => Some((inner, BorrowKind::Mut)),
            _ => None,
        };
        // A constructor the checker typed at the parameter it is lent to
        // (`g(if c { None } else { .. })` for `v: Option[String]`) builds
        // the value itself when its destination holds one (B-2026-10-20-31).
        let dt = self.place_type(&dest);
        let lend = lend.filter(|_| matches!(self.tys().tcx().kind(dt), HK::Ref(_) | HK::MutRef(_)));
        let t = match (lend, self.tys().tcx().kind(t)) {
            (None, HK::Ref(inner) | HK::MutRef(inner)) => inner,
            _ => t,
        };
        let Some((inner, bk)) = lend else {
            let kind = self.adt_aggregate(t, idx);
            self.assign(dest, Rvalue::Aggregate(kind, ops));
            return;
        };
        let v = Place::local(self.temp(inner));
        let kind = self.adt_aggregate(inner, idx);
        self.assign(v.clone(), Rvalue::Aggregate(kind, ops));
        if self.needs_drop(inner) {
            self.schedule(ScopeEntry::Drop(v.clone()));
        }
        self.assign(dest, Rvalue::Ref(bk, v));
    }

    fn adt_aggregate(&self, t: Ty, variant: u32) -> AggregateKind {
        match self.tys().tcx().kind(t) {
            HK::Shared { .. } => AggregateKind::Shared {
                ty: t,
                variant: VariantIdx(variant),
            },
            _ => AggregateKind::Adt {
                ty: t,
                variant: VariantIdx(variant),
            },
        }
    }

    fn array_literal(&mut self, e: &'a Expr, es: &'a [Expr], dest: Place) -> R<()> {
        let t = self.expr_ty(e)?;
        let (elem, vec) = match self.tys().tcx().kind(t) {
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            } => (self.tys().tcx().list(args)[0], true),
            HK::Array { elem, .. } => (elem, false),
            // `let q: VecDeque[i64] = [1, 2]`: the prefix literal's
            // collection, each item added in order.
            HK::Intrinsic { .. } => return self.prefix_literal(e, es, dest),
            _ => return self.unsupported(e.span, "this collection literal"),
        };
        let mut ops = Vec::new();
        for x in es {
            ops.push(self.operand_at(x, elem)?);
        }
        let agg = Rvalue::Aggregate(AggregateKind::Array(elem), ops);
        if !vec {
            self.assign(dest, agg);
            return Ok(());
        }
        let at = self.tys().tcx().intern(HK::Array {
            elem,
            len: crate::ty::ArrayLen::Known(es.len() as u64),
        });
        let arr = self.temp(at);
        self.assign(arr, agg);
        let name = format!("{}.from_array", self.tys().display(t));
        self.call_native(&name, vec![Operand::Move(Place::local(arr))], dest);
        Ok(())
    }

    /// `Set[1, 2]`, `VecDeque[4, 5]`, `SortedMap[]`: a new collection and
    /// each item added in order (a `Vec` or an array is its literal).
    fn prefix_literal(&mut self, e: &'a Expr, items: &'a [Expr], dest: Place) -> R<()> {
        let t = self.expr_ty(e)?;
        let (kind, targs) = match self.tys().tcx().kind(t) {
            HK::Intrinsic { kind, args } => (kind, self.tys().tcx().list(args)),
            HK::Array { .. } => return self.array_literal(e, items, dest),
            _ => return self.unsupported(e.span, "this collection literal"),
        };
        if kind == IntrinsicKind::Vec {
            return self.array_literal(e, items, dest);
        }
        let name = self.tys().display(t);
        self.call_native(&format!("{name}.new"), Vec::new(), dest.clone());
        let (add, ret) = match kind {
            _ if items.is_empty() => return Ok(()),
            IntrinsicKind::Set | IntrinsicKind::SortedSet => ("insert", self.tys().bool()),
            IntrinsicKind::VecDeque => ("push_back", self.unit()),
            _ => return self.unsupported(e.span, "this collection literal"),
        };
        let elem = targs[0];
        for x in items {
            let v = self.owned_operand(x, elem)?;
            let v = self.widen(v, elem);
            let rt = self.tys().tcx().reference(t, true);
            let r = self.temp(rt);
            self.assign(r, Rvalue::Ref(BorrowKind::Mut, dest.clone()));
            let out = self.temp(ret);
            self.call_native(
                &format!("{name}.{add}"),
                vec![Operand::Move(Place::local(r)), v],
                Place::local(out),
            );
        }
        Ok(())
    }

    /// `{k: v, ..}`: a new map, and each entry inserted in order, a later
    /// duplicate key replacing the earlier value.
    fn map_literal(&mut self, e: &'a Expr, entries: &'a [(Expr, Expr)], dest: Place) -> R<()> {
        let t = self.expr_ty(e)?;
        let targs = match self.tys().tcx().kind(t) {
            HK::Intrinsic {
                kind: IntrinsicKind::Map | IntrinsicKind::SortedMap,
                args,
            } => self.tys().tcx().list(args),
            _ => return self.unsupported(e.span, "this map literal"),
        };
        let (kt, vt) = (targs[0], targs[1]);
        let Some(ret) = self.option_of(vt) else {
            return self.unsupported(e.span, "a map literal without `Option`");
        };
        let name = self.tys().display(t);
        self.call_native(&format!("{name}.new"), Vec::new(), dest.clone());
        for (k, v) in entries {
            let key = self.owned_operand(k, kt)?;
            let key = self.widen(key, kt);
            let val = self.owned_operand(v, vt)?;
            let val = if self.downgrades(&val, vt) {
                self.downgrade(val, vt)
            } else {
                self.widen(val, vt)
            };
            let rt = self.tys().tcx().reference(t, true);
            let r = self.temp(rt);
            self.assign(r, Rvalue::Ref(BorrowKind::Mut, dest.clone()));
            let old = self.temp(ret);
            self.call_native(
                &format!("{name}.insert"),
                vec![Operand::Move(Place::local(r)), key, val],
                Place::local(old),
            );
            if self.needs_drop(ret) {
                let next = self.b.new_block();
                self.goto_with(
                    TerminatorKind::Drop {
                        place: Place::local(old),
                        target: next,
                        unwind: UnwindAction::Abort,
                    },
                    next,
                );
            }
        }
        Ok(())
    }

    /// `[v; n]`: an array of `n` copies of a `Copy` value, or a `Vec`
    /// built by the library's `Vec.filled(n, v)`.
    fn repeat_literal(
        &mut self,
        e: &'a Expr,
        value: &'a Expr,
        count: &'a Expr,
        dest: Place,
    ) -> R<()> {
        let t = self.expr_ty(e)?;
        match self.tys().tcx().kind(t) {
            HK::Array {
                elem,
                len: crate::ty::ArrayLen::Known(n),
            } if self.is_copy(elem) => {
                let v = match self.operand_filling_holes(value, elem)? {
                    // An unsuffixed literal takes the element type.
                    Operand::Const(Const {
                        kind: ConstKind::Scalar(x),
                        ..
                    }) => Operand::Const(Const {
                        ty: elem,
                        kind: ConstKind::Scalar(x),
                    }),
                    v => v,
                };
                let tmp = self.temp(elem);
                self.assign(tmp, Rvalue::Use(v));
                let ops = (0..n).map(|_| Operand::Copy(Place::local(tmp))).collect();
                self.assign(dest, Rvalue::Aggregate(AggregateKind::Array(elem), ops));
                Ok(())
            }
            // `[vec![1]; 3]`: a clone of the value in each slot but the
            // last, which takes it.
            HK::Array {
                elem,
                len: crate::ty::ArrayLen::Known(n),
            } if n > 0 => {
                let tmp = self.temp(elem);
                self.expr_into(value, Place::local(tmp))?;
                let mut ops = Vec::new();
                for _ in 1..n {
                    let c = self.temp(elem);
                    self.clone_into(Place::local(tmp), elem, Place::local(c));
                    ops.push(Operand::Move(Place::local(c)));
                }
                ops.push(Operand::Move(Place::local(tmp)));
                self.assign(dest, Rvalue::Aggregate(AggregateKind::Array(elem), ops));
                Ok(())
            }
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                ..
            } => {
                let i64_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
                let n = self.expr_operand(count)?;
                let ct = self.expr_ty(count)?;
                let n = if ct == i64_t {
                    n
                } else {
                    let c = self.temp(i64_t);
                    self.assign(c, Rvalue::Cast(CastKind::IntToInt, n, i64_t));
                    Operand::Copy(Place::local(c))
                };
                let elem = match self.tys().tcx().kind(t) {
                    HK::Intrinsic { args, .. } => self.tys().tcx().list(args)[0],
                    _ => unreachable!(),
                };
                let v = self.operand_filling_holes(value, elem)?;
                let name = format!("{}.filled", self.tys().display(t));
                self.call_native(&name, vec![n, v], dest);
                Ok(())
            }
            _ => self.unsupported(e.span, "this repeat literal"),
        }
    }

    fn binary(&mut self, op: AstBinOp, left: &'a Expr, right: &'a Expr, dest: Place) -> R<()> {
        let bin = match op {
            AstBinOp::Add => BinOp::Add,
            AstBinOp::Sub => BinOp::Sub,
            AstBinOp::Mul => BinOp::Mul,
            AstBinOp::Div => BinOp::Div,
            AstBinOp::Mod => BinOp::Rem,
            AstBinOp::Eq => BinOp::Eq,
            AstBinOp::NotEq => BinOp::Ne,
            AstBinOp::Lt => BinOp::Lt,
            AstBinOp::LtEq => BinOp::Le,
            AstBinOp::Gt => BinOp::Gt,
            AstBinOp::GtEq => BinOp::Ge,
            AstBinOp::BitAnd => BinOp::BitAnd,
            AstBinOp::BitOr => BinOp::BitOr,
            AstBinOp::BitXor => BinOp::BitXor,
            AstBinOp::Shl => BinOp::Shl,
            AstBinOp::Shr => BinOp::Shr,
            AstBinOp::And | AstBinOp::Or => {
                // Short circuit: the right side runs only when it decides.
                // Either side may be a borrowed `bool`, which is read.
                let bool_t = self.tys().bool();
                let l = self.owned_operand(left, bool_t)?;
                let rhs_bb = self.b.new_block();
                let short_bb = self.b.new_block();
                let join = self.b.new_block();
                let (t, f) = if op == AstBinOp::And {
                    (rhs_bb, short_bb)
                } else {
                    (short_bb, rhs_bb)
                };
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: l,
                        targets: SwitchTargets::if_else(t, f),
                    },
                    rhs_bb,
                );
                self.push_scope();
                let r = self.owned_operand(right, bool_t)?;
                self.assign(dest.clone(), Rvalue::Use(r));
                self.pop_scope()?;
                self.goto(join);
                self.cur = short_bb;
                self.assign(
                    dest,
                    Rvalue::Use(Operand::Const(Const {
                        ty: bool_t,
                        kind: ConstKind::Scalar((op == AstBinOp::Or) as u128),
                    })),
                );
                self.goto(join);
                self.cur = join;
                return Ok(());
            }
            AstBinOp::Range | AstBinOp::RangeInclusive => {
                return self.unsupported(left.span, "a range value");
            }
        };
        let lt0 = self.expr_ty(left)?;
        // B-2026-10-14-30 — `a + b` on a user type with an `impl Add` calls
        // its `add` (design.md § Operator traits).
        if let Some((tr, m)) = user_operator_trait(bin) {
            let (_, lbase) = self.strip_ty_full(lt0);
            if let Some((d, args)) = self.user_operator_method(lbase, tr, m, right)? {
                return self.user_operator_call(left, Some(right), d, args, dest);
            }
        }
        let lbase = match self.tys().tcx().kind(lt0) {
            HK::Ref(t) | HK::MutRef(t) => t,
            _ => lt0,
        };
        if matches!(self.tys().tcx().kind(lbase), HK::Str | HK::StaticStr) {
            return self.string_op(left, bin, right, dest);
        }
        // `a + b` on a `distinct type` that derives `Arithmetic`: the
        // operator on the base values, wrapped back.
        if let Some(bt) = self.distinct_base(lbase).filter(|&bt| self.is_copy(bt)) {
            if matches!(
                bin,
                BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem
            ) {
                let lp = self.expr_place(left, false)?;
                let (lp, _) = self.strip_refs(lp);
                let rp = self.expr_place(right, false)?;
                let (rp, _) = self.strip_refs(rp);
                let v = self.temp(bt);
                let (l, r) = (
                    Operand::Copy(lp.field(0, bt)),
                    Operand::Copy(rp.field(0, bt)),
                );
                self.arith(bin, l, r, bt, Place::local(v));
                self.wrap_distinct(lbase, v, dest);
                return Ok(());
            }
        }
        // `a + b`, `a < b` on lane vectors: one operator over every lane
        // (a comparison gives a `Vector[bool, N]` mask).
        if lt0 == lbase && matches!(self.tys().tcx().kind(lbase), HK::Vector { .. }) {
            let l = self.expr_operand(left)?;
            let r = self.operand_at(right, lbase)?;
            self.assign(dest, Rvalue::BinaryOp(bin, l, r));
            return Ok(());
        }
        let scalar = |k: HK| {
            matches!(
                k,
                HK::Int(_) | HK::UInt(_) | HK::Float(_) | HK::Bool | HK::Char
            )
        };
        if !scalar(self.tys().tcx().kind(lbase)) && matches!(bin, BinOp::Eq | BinOp::Ne) {
            return self.eq_exprs(left, right, bin == BinOp::Ne, dest);
        }
        if !scalar(self.tys().tcx().kind(lbase))
            && matches!(bin, BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge)
        {
            return self.ordered_exprs(left, bin, right, dest);
        }
        let (l, lt) = self.scalar_operand(left)?;
        if !self.is_copy(lt) {
            return self.unsupported(left.span, "an operator on a non-scalar");
        }
        let (r, rt) = self.scalar_operand(right)?;
        // An unsuffixed literal takes the other operand's type (the
        // checker records `x * 2` with `x: f64` as an `i64` literal). A
        // shift's amount keeps its own.
        let shift = matches!(bin, BinOp::Shl | BinOp::Shr);
        let lit = |o: &Operand| matches!(o, Operand::Const(_));
        let t = if lit(&l) && !lit(&r) && !shift {
            rt
        } else {
            lt
        };
        let l = self.fit_const(l, t);
        let r = if shift { r } else { self.fit_const(r, t) };
        // Operands of different widths meet at the wider one when the
        // widening is lossless (design.md, implicit widening).
        let (l, r, t) = match (self.operand_ty(&l), self.operand_ty(&r)) {
            (a, b) if a != b && !shift && self.lossless(a, b) => (self.widen(l, b), r, b),
            (a, b) if a != b && !shift && self.lossless(b, a) => (l, self.widen(r, a), a),
            _ => (l, r, t),
        };
        self.arith(bin, l, r, t, dest);
        Ok(())
    }

    // ── equality ────────────────────────────────────────────────────

    /// `left == right` (or `!=`) on values that are not scalars: the type's
    /// own `eq` when it has one, field by field when it derives it.
    fn eq_exprs(&mut self, left: &'a Expr, right: &'a Expr, negate: bool, dest: Place) -> R<()> {
        let lp = self.expr_place(left, false)?;
        let rp = self.expr_place(right, false)?;
        let (lp, lt) = self.strip_refs(lp);
        let (rp, _) = self.strip_refs(rp);
        if !negate {
            return self.eq_places(left.span, lp, rp, lt, dest);
        }
        let bool_t = self.tys().bool();
        let t = self.temp(bool_t);
        self.eq_places(left.span, lp, rp, lt, Place::local(t))?;
        self.assign(
            dest,
            Rvalue::UnaryOp(UnOp::Not, Operand::Move(Place::local(t))),
        );
        Ok(())
    }

    /// `a < b` on a type ordered by `Ord`: `a.cmp(b)`, and a test of the
    /// `Ordering` it returns. `<` and `>` require `Less` and `Greater`; `<=`
    /// and `>=` rule out `Greater` and `Less`.
    fn ordered_exprs(&mut self, left: &'a Expr, bin: BinOp, right: &'a Expr, dest: Place) -> R<()> {
        let lp = self.expr_place(left, false)?;
        let rp = self.expr_place(right, false)?;
        let (lp, lt) = self.strip_refs(lp);
        let (rp, _) = self.strip_refs(rp);
        let (ot, [less, _, greater]) = self.ordering_ty(left.span)?;
        let (want, eq) = match bin {
            BinOp::Lt => (less, true),
            BinOp::Gt => (greater, true),
            BinOp::Le => (greater, false),
            _ => (less, false),
        };
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let op = if eq { BinOp::Eq } else { BinOp::Ne };
        // A type that implements `PartialOrd` and not `Ord`: its own
        // `partial_cmp`, where `None` (unordered) makes every operator false.
        let partial = match self.user_impl_method(lt, "Ord", "cmp") {
            Some(_) => None,
            None => self.user_impl_method(lt, "PartialOrd", "partial_cmp"),
        };
        if let Some((d, args)) = partial {
            let Some(opt_t) = self.option_of(ot) else {
                return self.unsupported(left.span, "a `partial_cmp` with no `Option`");
            };
            let some = self
                .tys()
                .tcx()
                .adt_of(opt_t)
                .and_then(|(a, _)| a.variants.iter().position(|v| v.name == "Some"));
            let Some(some) = some else {
                return self.unsupported(left.span, "a `partial_cmp` with no `Option`");
            };
            let lo = self.ref_to(lp, lt);
            let ro = self.ref_to(rp, lt);
            let name = self.lcx.instance(d, args.clone());
            let func = self.fn_operand(&name, d, args);
            let opt = self.temp(opt_t);
            let next = self.b.new_block();
            self.goto_with(
                TerminatorKind::Call {
                    func,
                    args: vec![lo, ro],
                    destination: Place::local(opt),
                    target: Some(next),
                    unwind: UnwindAction::Abort,
                },
                next,
            );
            let tag = self.temp(isize_t);
            self.assign(tag, Rvalue::Discriminant(Place::local(opt)));
            let is_some = self.temp(self.tys().bool());
            self.assign(
                is_some,
                Rvalue::BinaryOp(
                    BinOp::Eq,
                    Operand::Copy(Place::local(tag)),
                    Operand::Const(Const {
                        ty: isize_t,
                        kind: ConstKind::Scalar(some as u128),
                    }),
                ),
            );
            let (yes, no, join) = (self.b.new_block(), self.b.new_block(), self.b.new_block());
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(is_some)),
                    targets: SwitchTargets::if_else(yes, no),
                },
                no,
            );
            let f = Operand::Const(Const {
                ty: self.tys().bool(),
                kind: ConstKind::Scalar(0),
            });
            self.assign(dest.clone(), Rvalue::Use(f));
            self.goto(join);
            self.cur = yes;
            let payload = Place::local(opt)
                .project(ProjElem::Downcast(VariantIdx(some as u32)))
                .field(0, ot);
            let disc = self.temp(isize_t);
            self.assign(disc, Rvalue::Discriminant(payload));
            let want = Operand::Const(Const {
                ty: isize_t,
                kind: ConstKind::Scalar(want as u128),
            });
            self.assign(
                dest,
                Rvalue::BinaryOp(op, Operand::Copy(Place::local(disc)), want),
            );
            self.goto(join);
            self.cur = join;
            return Ok(());
        }
        let o = self.temp(ot);
        self.cmp_places(left.span, lp, rp, lt, Place::local(o))?;
        let disc = self.temp(isize_t);
        self.assign(disc, Rvalue::Discriminant(Place::local(o)));
        let want = Operand::Const(Const {
            ty: isize_t,
            kind: ConstKind::Scalar(want as u128),
        });
        self.assign(
            dest,
            Rvalue::BinaryOp(op, Operand::Copy(Place::local(disc)), want),
        );
        Ok(())
    }

    /// The `Ordering` type, with the indices of `Less`, `Equal` and
    /// `Greater`.
    fn ordering_ty(&mut self, span: Span) -> R<(Ty, [u32; 3])> {
        let Some(ord) = self.lcx.defs.lookup(0, "Ordering") else {
            return self.unsupported(span, "an ordering with no `Ordering`");
        };
        let ot = self.tys().tcx().adt(ord, &[]);
        let ot = match self.lcx.mir_ty(ot, &[]) {
            Ok(t) => t,
            Err(err) => return self.unsupported(span, &err),
        };
        let Some((adt, _)) = self.tys().tcx().adt_of(ot) else {
            return self.unsupported(span, "an ordering with no `Ordering`");
        };
        let variant = |name: &str| {
            adt.variants
                .iter()
                .position(|v| v.name == name)
                .map(|i| i as u32)
        };
        match (variant("Less"), variant("Equal"), variant("Greater")) {
            (Some(l), Some(e), Some(g)) => Ok((ot, [l, e, g])),
            _ => self.unsupported(span, "an ordering with no `Ordering`"),
        }
    }

    /// `dest = l.cmp(r)` for two places of type `t`: the user's `Ord` body
    /// when the type has one; otherwise the order a derive gives, scalars
    /// by value, `String`s by the library, and aggregates field by field.
    fn cmp_places(&mut self, span: Span, l: Place, r: Place, t: Ty, dest: Place) -> R<()> {
        let (ot, [less, equal, greater]) = self.ordering_ty(span)?;
        match self.tys().tcx().kind(t) {
            HK::Int(_) | HK::UInt(_) | HK::Float(_) | HK::Bool | HK::Char => {
                let bool_t = self.tys().bool();
                let join = self.b.new_block();
                for (op, variant) in [(BinOp::Lt, less), (BinOp::Gt, greater)] {
                    let c = self.temp(bool_t);
                    self.assign(
                        c,
                        Rvalue::BinaryOp(op, Operand::Copy(l.clone()), Operand::Copy(r.clone())),
                    );
                    let yes = self.b.new_block();
                    let no = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::SwitchInt {
                            discr: Operand::Copy(Place::local(c)),
                            targets: SwitchTargets::if_else(yes, no),
                        },
                        yes,
                    );
                    let kind = self.adt_aggregate(ot, variant);
                    self.assign(dest.clone(), Rvalue::Aggregate(kind, Vec::new()));
                    self.goto(join);
                    self.cur = no;
                }
                let kind = self.adt_aggregate(ot, equal);
                self.assign(dest, Rvalue::Aggregate(kind, Vec::new()));
                self.goto(join);
                self.cur = join;
                Ok(())
            }
            HK::Ref(inner) | HK::MutRef(inner) => self.cmp_places(
                span,
                l.project(ProjElem::Deref),
                r.project(ProjElem::Deref),
                inner,
                dest,
            ),
            HK::Str | HK::StaticStr => {
                let lo = self.ref_to(l, t);
                let ro = self.ref_to(r, t);
                self.call_native("String.cmp", vec![lo, ro], dest);
                Ok(())
            }
            // B-2026-10-06-92: a `Vec` orders lexicographically, as its
            // `Slice` does and as `==` already compares it. A `VecDeque`
            // too, front to back (B-2026-10-21-30).
            HK::Intrinsic {
                kind: IntrinsicKind::Vec | IntrinsicKind::VecDeque,
                args,
            } => {
                let elem = self.tys().tcx().list(args)[0];
                self.seq_cmp(span, l, r, t, elem, dest)
            }
            HK::Slice { elem, .. } => self.seq_cmp(span, l, r, t, elem, dest),
            HK::Tuple(list) => {
                let tys = self.tys().tcx().list(list);
                let parts = tys
                    .iter()
                    .enumerate()
                    .map(|(i, &ft)| (l.field(i as u32, ft), r.field(i as u32, ft), ft))
                    .collect();
                self.lex_cmp(span, parts, dest)
            }
            HK::Array {
                elem,
                len: crate::ty::ArrayLen::Known(n),
            } => {
                let parts = (0..n)
                    .map(|i| {
                        (
                            l.project(ProjElem::ConstIndex(i)),
                            r.project(ProjElem::ConstIndex(i)),
                            elem,
                        )
                    })
                    .collect();
                self.lex_cmp(span, parts, dest)
            }
            HK::Adt { .. } | HK::Shared { .. } if self.total_float_wrapper(t).is_some() => {
                // `F64` / `F32` order their field totally: `-0.0 < 0.0`, and
                // a NaN equals itself.
                let (float, ft) = self.total_float_wrapper(t).expect("checked");
                let lo = self.ref_to(l.field(0, ft), ft);
                let ro = self.ref_to(r.field(0, ft), ft);
                self.call_native(&format!("{float}.total_cmp"), vec![lo, ro], dest);
                Ok(())
            }
            HK::Adt { .. } | HK::Shared { .. } => {
                if let Some((d, args)) = self.user_impl_method(t, "Ord", "cmp") {
                    let lo = self.ref_to(l, t);
                    let ro = self.ref_to(r, t);
                    let name = self.lcx.instance(d, args.clone());
                    let func = self.fn_operand(&name, d, args);
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Call {
                            func,
                            args: vec![lo, ro],
                            destination: dest,
                            target: Some(next),
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                    return Ok(());
                }
                let (adt, _) = self.tys().tcx().adt_of(t).expect("an ADT");
                if !adt.is_enum {
                    let n = adt.variants.first().map_or(0, |v| v.fields.len());
                    let mut parts = Vec::new();
                    for i in 0..n as u32 {
                        let Some(ft) = self.tys().tcx().field_ty(t, None, i) else {
                            return self.unsupported(span, "ordering this type");
                        };
                        parts.push((l.clone().field(i, ft), r.clone().field(i, ft), ft));
                    }
                    return self.lex_cmp(span, parts, dest);
                }
                self.enum_cmp(span, l, r, t, &adt, dest)
            }
            _ => self.unsupported(span, "ordering this type"),
        }
    }

    /// The library's total-order float wrapper `t` is (`F64`, `F32`): the
    /// float type its one field holds, and that field's type.
    fn total_float_wrapper(&self, t: Ty) -> Option<(&'static str, Ty)> {
        let (adt, _) = self.tys().tcx().adt_of(t)?;
        let float = match adt.name.as_str() {
            "F64" => "f64",
            "F32" => "f32",
            _ => return None,
        };
        let ft = self.tys().tcx().field_ty(t, None, 0)?;
        matches!(self.tys().tcx().kind(ft), HK::Float(_)).then_some((float, ft))
    }

    /// `dest` is the first pair's ordering that is not `Equal`, else `Equal`.
    /// Two slices in lexicographic order: the first pair of
    /// elements that differ decides, each by its own ordering, and a
    /// prefix orders before what extends it.
    fn seq_cmp(&mut self, span: Span, l: Place, r: Place, t: Ty, elem: Ty, dest: Place) -> R<()> {
        let (ot, [_, equal, _]) = self.ordering_ty(span)?;
        let (usize_t, isize_t, bool_t, rt, et) = {
            let tcx = self.tys().tcx();
            (
                tcx.intern(HK::UInt(UIntSize::Usize)),
                tcx.intern(HK::Int(IntSize::I64)),
                tcx.intern(HK::Bool),
                tcx.reference(t, false),
                tcx.reference(elem, false),
            )
        };
        let ty_name = self.tys().display(t);
        let mut lens = Vec::new();
        let mut refs = Vec::new();
        for p in [l, r] {
            let rf = self.temp(rt);
            self.assign(rf, Rvalue::Ref(BorrowKind::Shared, p));
            let n = self.temp(usize_t);
            self.call_native(
                &format!("{ty_name}.len"),
                vec![Operand::Copy(Place::local(rf))],
                Place::local(n),
            );
            lens.push(n);
            refs.push(rf);
        }
        let i = self.temp(usize_t);
        let zero = Operand::Const(Const {
            ty: usize_t,
            kind: ConstKind::Scalar(0),
        });
        self.assign(i, Rvalue::Use(zero));
        let (head, body, tail, join) = (
            self.b.new_block(),
            self.b.new_block(),
            self.b.new_block(),
            self.b.new_block(),
        );
        self.goto(head);
        self.cur = head;
        let mut checks = Vec::new();
        for &n in &lens {
            let c = self.temp(bool_t);
            self.assign(
                c,
                Rvalue::BinaryOp(
                    BinOp::Lt,
                    Operand::Copy(Place::local(i)),
                    Operand::Copy(Place::local(n)),
                ),
            );
            checks.push(c);
        }
        let first = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(checks[0])),
                targets: SwitchTargets::if_else(first, tail),
            },
            first,
        );
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(checks[1])),
                targets: SwitchTargets::if_else(body, tail),
            },
            body,
        );
        let mut elems = Vec::new();
        for &rf in &refs {
            let e = self.temp(et);
            self.call_native(
                &format!("{ty_name}.index"),
                vec![
                    Operand::Copy(Place::local(rf)),
                    Operand::Copy(Place::local(i)),
                ],
                Place::local(e),
            );
            elems.push(Place::local(e).project(ProjElem::Deref));
        }
        let o = self.temp(ot);
        let (el, er) = (elems[0].clone(), elems[1].clone());
        self.cmp_places(span, el, er, elem, Place::local(o))?;
        let disc = self.temp(isize_t);
        self.assign(disc, Rvalue::Discriminant(Place::local(o)));
        let same = self.temp(bool_t);
        self.assign(
            same,
            Rvalue::BinaryOp(
                BinOp::Eq,
                Operand::Copy(Place::local(disc)),
                Operand::Const(Const {
                    ty: isize_t,
                    kind: ConstKind::Scalar(equal as u128),
                }),
            ),
        );
        let (next, differ) = (self.b.new_block(), self.b.new_block());
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(same)),
                targets: SwitchTargets::if_else(next, differ),
            },
            differ,
        );
        self.assign(dest.clone(), Rvalue::Use(Operand::Copy(Place::local(o))));
        self.goto(join);
        self.cur = next;
        let one = Operand::Const(Const {
            ty: usize_t,
            kind: ConstKind::Scalar(1),
        });
        self.assign(
            i,
            Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(i)), one),
        );
        self.goto(head);
        self.cur = tail;
        let (nl, nr) = (Place::local(lens[0]), Place::local(lens[1]));
        self.cmp_places(span, nl, nr, usize_t, dest)?;
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    fn lex_cmp(&mut self, span: Span, parts: Vec<(Place, Place, Ty)>, dest: Place) -> R<()> {
        let (ot, [_, equal, _]) = self.ordering_ty(span)?;
        let (isize_t, bool_t) = {
            let tcx = self.tys().tcx();
            (tcx.intern(HK::Int(IntSize::I64)), tcx.intern(HK::Bool))
        };
        let join = self.b.new_block();
        for (lp, rp, ft) in parts {
            let o = self.temp(ot);
            self.cmp_places(span, lp, rp, ft, Place::local(o))?;
            let disc = self.temp(isize_t);
            self.assign(disc, Rvalue::Discriminant(Place::local(o)));
            let same = self.temp(bool_t);
            self.assign(
                same,
                Rvalue::BinaryOp(
                    BinOp::Eq,
                    Operand::Copy(Place::local(disc)),
                    Operand::Const(Const {
                        ty: isize_t,
                        kind: ConstKind::Scalar(equal as u128),
                    }),
                ),
            );
            let next = self.b.new_block();
            let differ = self.b.new_block();
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(same)),
                    targets: SwitchTargets::if_else(next, differ),
                },
                differ,
            );
            self.assign(dest.clone(), Rvalue::Use(Operand::Copy(Place::local(o))));
            self.goto(join);
            self.cur = next;
        }
        let kind = self.adt_aggregate(ot, equal);
        self.assign(dest, Rvalue::Aggregate(kind, Vec::new()));
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    /// Enum values order by variant, in declaration order, and then by
    /// their payloads.
    fn enum_cmp(
        &mut self,
        span: Span,
        l: Place,
        r: Place,
        t: Ty,
        adt: &crate::ty::AdtDef,
        dest: Place,
    ) -> R<()> {
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let dl = self.temp(isize_t);
        self.assign(dl, Rvalue::Discriminant(l.clone()));
        let dr = self.temp(isize_t);
        self.assign(dr, Rvalue::Discriminant(r.clone()));
        let join = self.b.new_block();
        let switch = self.b.new_block();
        // The variants' order is their indices' order.
        self.cmp_places(
            span,
            Place::local(dl),
            Place::local(dr),
            isize_t,
            dest.clone(),
        )?;
        let (_, [_, equal, _]) = self.ordering_ty(span)?;
        let bool_t = self.tys().bool();
        let disc = self.temp(isize_t);
        self.assign(disc, Rvalue::Discriminant(dest.clone()));
        let same = self.temp(bool_t);
        self.assign(
            same,
            Rvalue::BinaryOp(
                BinOp::Eq,
                Operand::Copy(Place::local(disc)),
                Operand::Const(Const {
                    ty: isize_t,
                    kind: ConstKind::Scalar(equal as u128),
                }),
            ),
        );
        let differ = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(same)),
                targets: SwitchTargets::if_else(switch, differ),
            },
            differ,
        );
        self.goto(join);
        self.cur = switch;
        let arms: Vec<BasicBlock> = adt.variants.iter().map(|_| self.b.new_block()).collect();
        let unreachable = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(dl)),
                targets: SwitchTargets {
                    values: arms
                        .iter()
                        .enumerate()
                        .map(|(i, &b)| (i as u128, b))
                        .collect(),
                    otherwise: unreachable,
                },
            },
            unreachable,
        );
        self.diverge(TerminatorKind::Unreachable);
        for (vi, v) in adt.variants.iter().enumerate() {
            self.cur = arms[vi];
            let vi = vi as u32;
            let mut parts = Vec::new();
            for fi in 0..v.fields.len() as u32 {
                let Some(ft) = self.tys().tcx().field_ty(t, Some(vi), fi) else {
                    return self.unsupported(span, "ordering this type");
                };
                let down = |p: &Place| p.project(ProjElem::Downcast(VariantIdx(vi))).field(fi, ft);
                parts.push((down(&l), down(&r), ft));
            }
            self.lex_cmp(span, parts, dest.clone())?;
            self.goto(join);
        }
        self.cur = join;
        Ok(())
    }

    fn strip_refs(&self, mut p: Place) -> (Place, Ty) {
        let mut t = self.place_type(&p);
        while let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            p = p.project(ProjElem::Deref);
            t = inner;
        }
        (p, t)
    }

    fn ref_to(&mut self, p: Place, t: Ty) -> Operand {
        let rt = self.tys().tcx().reference(t, false);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
        Operand::Move(Place::local(r))
    }

    /// `dest = p.clone()` for a place of type `t`: a copy, a counted copy
    /// of a handle, a tuple part by part, else the library's `clone`.
    fn clone_into(&mut self, p: Place, t: Ty, dest: Place) {
        if self.is_copy(t) {
            self.assign(dest, Rvalue::Use(Operand::Copy(p)));
            return;
        }
        if self.is_handle(t) || self.is_handle_aggregate(t) {
            self.count_copy(p, t, dest);
            return;
        }
        if let HK::Tuple(parts) = self.tys().tcx().kind(t) {
            let parts = self.tys().tcx().list(parts).to_vec();
            let mut ops = Vec::new();
            for (i, pt) in parts.into_iter().enumerate() {
                let l = self.temp(pt);
                self.clone_into(p.field(i as u32, pt), pt, Place::local(l));
                ops.push(Operand::Move(Place::local(l)));
            }
            self.assign(dest, Rvalue::Aggregate(AggregateKind::Tuple, ops));
            return;
        }
        if let HK::Array {
            elem,
            len: crate::ty::ArrayLen::Known(n),
        } = self.tys().tcx().kind(t)
        {
            let mut ops = Vec::new();
            for i in 0..n {
                let l = self.temp(elem);
                self.clone_into(
                    p.clone().project(ProjElem::ConstIndex(i)),
                    elem,
                    Place::local(l),
                );
                ops.push(Operand::Move(Place::local(l)));
            }
            self.assign(dest, Rvalue::Aggregate(AggregateKind::Array(elem), ops));
            return;
        }
        self.queue_nested_clones(t);
        let r = self.ref_to(p, t);
        let name = format!("{}.clone", self.tys().display(t));
        self.call_native(&name, vec![r], dest);
    }

    /// `dest = l == r` for two places of type `t`.
    fn eq_places(&mut self, span: Span, l: Place, r: Place, t: Ty, dest: Place) -> R<()> {
        let kind = self.tys().tcx().kind(t);
        match kind {
            HK::Int(_) | HK::UInt(_) | HK::Float(_) | HK::Bool | HK::Char => {
                self.assign(
                    dest,
                    Rvalue::BinaryOp(BinOp::Eq, Operand::Copy(l), Operand::Copy(r)),
                );
                Ok(())
            }
            HK::Ref(inner) | HK::MutRef(inner) => self.eq_places(
                span,
                l.project(ProjElem::Deref),
                r.project(ProjElem::Deref),
                inner,
                dest,
            ),
            HK::Str | HK::StaticStr => {
                let lo = self.ref_to(l, t);
                let ro = self.ref_to(r, t);
                self.call_native("String.eq", vec![lo, ro], dest);
                Ok(())
            }
            HK::Tuple(list) => {
                let tys = self.tys().tcx().list(list);
                let parts = tys
                    .iter()
                    .enumerate()
                    .map(|(i, &ft)| (l.field(i as u32, ft), r.field(i as u32, ft), ft))
                    .collect();
                self.all_eq(span, parts, dest)
            }
            HK::Array {
                elem,
                len: crate::ty::ArrayLen::Known(n),
            } => {
                let parts = (0..n)
                    .map(|i| {
                        (
                            l.project(ProjElem::ConstIndex(i)),
                            r.project(ProjElem::ConstIndex(i)),
                            elem,
                        )
                    })
                    .collect();
                self.all_eq(span, parts, dest)
            }
            HK::Intrinsic {
                kind: IntrinsicKind::Vec | IntrinsicKind::VecDeque,
                args,
            } => {
                let elem = self.tys().tcx().list(args)[0];
                self.seq_eq(span, l, r, t, elem, dest)
            }
            HK::Slice { elem, .. } => self.seq_eq(span, l, r, t, elem, dest),
            HK::Adt { .. } | HK::Shared { .. } if self.total_float_wrapper(t).is_some() => {
                let (ot, [_, equal, _]) = self.ordering_ty(span)?;
                let o = self.temp(ot);
                self.cmp_places(span, l, r, t, Place::local(o))?;
                let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
                let disc = self.temp(isize_t);
                self.assign(disc, Rvalue::Discriminant(Place::local(o)));
                let want = Operand::Const(Const {
                    ty: isize_t,
                    kind: ConstKind::Scalar(equal as u128),
                });
                self.assign(
                    dest,
                    Rvalue::BinaryOp(BinOp::Eq, Operand::Copy(Place::local(disc)), want),
                );
                Ok(())
            }
            HK::Adt { .. } | HK::Shared { .. } => {
                if let Some((d, args)) = self.user_eq(t) {
                    let lo = self.ref_to(l, t);
                    let ro = self.ref_to(r, t);
                    let name = self.lcx.instance(d, args.clone());
                    let func = self.fn_operand(&name, d, args);
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Call {
                            func,
                            args: vec![lo, ro],
                            destination: dest,
                            target: Some(next),
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                    return Ok(());
                }
                if self.eq_stack.contains(&t) {
                    // The comparison reaches its own type: call the derived
                    // body, built once, rather than inline it again.
                    let name = format!("{}.eq#derived", self.tys().display(t));
                    if self.lcx.eq_queued.insert(t) {
                        self.lcx.eq_queue.push((t, name.clone()));
                    }
                    let lo = self.ref_to(l, t);
                    let ro = self.ref_to(r, t);
                    let func = self.fn_operand(&name, DefId(u32::MAX), Vec::new());
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Call {
                            func,
                            args: vec![lo, ro],
                            destination: dest,
                            target: Some(next),
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                    return Ok(());
                }
                self.eq_stack.push(t);
                let res = self.derived_eq(span, l, r, t, dest);
                self.eq_stack.pop();
                res
            }
            _ => self.unsupported(span, "comparing this type"),
        }
    }

    /// `l == r` by a derived `PartialEq`: field by field, or variant and
    /// then payload.
    fn derived_eq(&mut self, span: Span, l: Place, r: Place, t: Ty, dest: Place) -> R<()> {
        let Some((adt, _)) = self.tys().tcx().adt_of(t) else {
            return self.unsupported(span, "comparing this type");
        };
        if !adt.is_enum {
            let n = adt.variants.first().map_or(0, |v| v.fields.len());
            let mut parts = Vec::new();
            for i in 0..n as u32 {
                let Some(ft) = self.tys().tcx().field_ty(t, None, i) else {
                    return self.unsupported(span, "comparing this type");
                };
                parts.push((l.clone().field(i, ft), r.clone().field(i, ft), ft));
            }
            return self.all_eq(span, parts, dest);
        }
        self.enum_eq(span, l, r, t, &adt, dest)
    }

    /// Two enum values are equal when their variants are, and then their
    /// payloads.
    fn enum_eq(
        &mut self,
        span: Span,
        l: Place,
        r: Place,
        t: Ty,
        adt: &crate::ty::AdtDef,
        dest: Place,
    ) -> R<()> {
        let (isize_t, bool_t) = {
            let tcx = self.tys().tcx();
            (tcx.intern(HK::Int(IntSize::I64)), tcx.intern(HK::Bool))
        };
        let dl = self.temp(isize_t);
        self.assign(dl, Rvalue::Discriminant(l.clone()));
        let dr = self.temp(isize_t);
        self.assign(dr, Rvalue::Discriminant(r.clone()));
        let same = self.temp(bool_t);
        self.assign(
            same,
            Rvalue::BinaryOp(
                BinOp::Eq,
                Operand::Copy(Place::local(dl)),
                Operand::Copy(Place::local(dr)),
            ),
        );
        let differ = self.b.new_block();
        let switch = self.b.new_block();
        let join = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(same)),
                targets: SwitchTargets::if_else(switch, differ),
            },
            differ,
        );
        self.assign(dest.clone(), Rvalue::Use(bool_const(bool_t, false)));
        self.goto(join);
        self.cur = switch;
        let arms: Vec<BasicBlock> = adt.variants.iter().map(|_| self.b.new_block()).collect();
        let unreachable = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(dl)),
                targets: SwitchTargets {
                    values: arms
                        .iter()
                        .enumerate()
                        .map(|(i, &b)| (i as u128, b))
                        .collect(),
                    otherwise: unreachable,
                },
            },
            unreachable,
        );
        self.diverge(TerminatorKind::Unreachable);
        for (vi, v) in adt.variants.iter().enumerate() {
            self.cur = arms[vi];
            let vi = vi as u32;
            let mut parts = Vec::new();
            for fi in 0..v.fields.len() as u32 {
                let Some(ft) = self.tys().tcx().field_ty(t, Some(vi), fi) else {
                    return self.unsupported(span, "comparing this type");
                };
                let down = |p: &Place| p.project(ProjElem::Downcast(VariantIdx(vi))).field(fi, ft);
                parts.push((down(&l), down(&r), ft));
            }
            self.all_eq(span, parts, dest.clone())?;
            self.goto(join);
        }
        self.cur = join;
        Ok(())
    }

    /// `dest = true` when every pair is equal, stopping at the first that
    /// is not.
    /// `dest = l == r` for two `Vec`s or slices of `elem`: the same length
    /// and equal elements, compared in order until one differs.
    fn seq_eq(&mut self, span: Span, l: Place, r: Place, t: Ty, elem: Ty, dest: Place) -> R<()> {
        let (bool_t, usize_t, rt, et) = {
            let tcx = self.tys().tcx();
            (
                tcx.intern(HK::Bool),
                tcx.intern(HK::UInt(UIntSize::Usize)),
                tcx.reference(t, false),
                tcx.reference(elem, false),
            )
        };
        let ty_name = self.tys().display(t);
        let (lr, rr) = (self.temp(rt), self.temp(rt));
        self.assign(lr, Rvalue::Ref(BorrowKind::Shared, l));
        self.assign(rr, Rvalue::Ref(BorrowKind::Shared, r));
        let (nl, nr) = (self.temp(usize_t), self.temp(usize_t));
        let len = format!("{ty_name}.len");
        self.call_native(
            &len,
            vec![Operand::Copy(Place::local(lr))],
            Place::local(nl),
        );
        self.call_native(
            &len,
            vec![Operand::Copy(Place::local(rr))],
            Place::local(nr),
        );
        let c = self.temp(bool_t);
        self.assign(
            c,
            Rvalue::BinaryOp(
                BinOp::Eq,
                Operand::Copy(Place::local(nl)),
                Operand::Copy(Place::local(nr)),
            ),
        );
        let (differ, join, head, body, step, same) = (
            self.b.new_block(),
            self.b.new_block(),
            self.b.new_block(),
            self.b.new_block(),
            self.b.new_block(),
            self.b.new_block(),
        );
        let i = self.temp(usize_t);
        self.assign(
            i,
            Rvalue::Use(Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(0),
            })),
        );
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(head, differ),
            },
            head,
        );
        let more = self.temp(bool_t);
        self.assign(
            more,
            Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(Place::local(i)),
                Operand::Copy(Place::local(nl)),
            ),
        );
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(more)),
                targets: SwitchTargets::if_else(body, same),
            },
            body,
        );
        let index = format!("{ty_name}.index");
        let (el, er) = (self.temp(et), self.temp(et));
        self.call_native(
            &index,
            vec![
                Operand::Copy(Place::local(lr)),
                Operand::Copy(Place::local(i)),
            ],
            Place::local(el),
        );
        self.call_native(
            &index,
            vec![
                Operand::Copy(Place::local(rr)),
                Operand::Copy(Place::local(i)),
            ],
            Place::local(er),
        );
        let e = self.temp(bool_t);
        self.eq_places(
            span,
            Place::local(el).project(ProjElem::Deref),
            Place::local(er).project(ProjElem::Deref),
            elem,
            Place::local(e),
        )?;
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(e)),
                targets: SwitchTargets::if_else(step, differ),
            },
            step,
        );
        let one = Operand::Const(Const {
            ty: usize_t,
            kind: ConstKind::Scalar(1),
        });
        self.assign(
            i,
            Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(i)), one),
        );
        self.goto(head);
        self.cur = same;
        self.assign(dest.clone(), Rvalue::Use(bool_const(bool_t, true)));
        self.goto(join);
        self.cur = differ;
        self.assign(dest, Rvalue::Use(bool_const(bool_t, false)));
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    fn all_eq(&mut self, span: Span, parts: Vec<(Place, Place, Ty)>, dest: Place) -> R<()> {
        let bool_t = self.tys().bool();
        let differ = self.b.new_block();
        let join = self.b.new_block();
        for (lp, rp, ft) in parts {
            let c = self.temp(bool_t);
            self.eq_places(span, lp, rp, ft, Place::local(c))?;
            let next = self.b.new_block();
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(c)),
                    targets: SwitchTargets::if_else(next, differ),
                },
                next,
            );
        }
        self.assign(dest.clone(), Rvalue::Use(bool_const(bool_t, true)));
        self.goto(join);
        self.cur = differ;
        self.assign(dest, Rvalue::Use(bool_const(bool_t, false)));
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    /// A user `impl PartialEq` method `eq` for `t`, with its instance
    /// arguments.
    fn user_eq(&self, t: Ty) -> Option<(DefId, Vec<Ty>)> {
        self.user_impl_method(t, "PartialEq", "eq")
    }

    /// Method `method` of the user's `impl <tr> for t`, with the impl's
    /// generic arguments when it has any.
    /// Queue the user `Display` body of every type a printed `t` contains,
    /// for the interpreter to show it by at any depth (a `Vec[P]`, an
    /// `Option[P]`, a field of type `P`). A type with its own `Display`
    /// is shown by that body alone, so its parts are not visited.
    fn queue_nested_displays(&mut self, t: Ty) {
        let mut seen = FxHashSet::default();
        let mut work = vec![t];
        while let Some(t) = work.pop() {
            if !seen.insert(t) {
                continue;
            }
            let tcx = self.tys().tcx();
            match tcx.kind(t) {
                HK::Ref(x) | HK::MutRef(x) => work.push(x),
                HK::Tuple(l) => work.extend(tcx.list(l)),
                HK::Array { elem, .. } | HK::Slice { elem, .. } => work.push(elem),
                HK::Intrinsic { args, .. } => work.extend(tcx.list(args)),
                HK::Adt { args, .. } | HK::Shared { args, .. } => {
                    if let Some((d, args)) = self.user_impl_method(t, "Display", "to_string") {
                        self.lcx.instance(d, args);
                        continue;
                    }
                    let tcx = self.tys().tcx();
                    work.extend(tcx.list(args));
                    if let Some((adt, _)) = tcx.adt_of(t) {
                        for (k, v) in adt.variants.iter().enumerate() {
                            let variant = adt.is_enum.then_some(k as u32);
                            for i in 0..v.fields.len() {
                                work.extend(tcx.field_ty(t, variant, i as u32));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }

    /// Queue the user `Clone` body of every type a cloned `t` contains (a
    /// `Vec[P]`, an `Option[P]`, a field of type `P`), which the clone glue
    /// and the interpreter call for it (B-2026-10-06-112). A type with its
    /// own `Clone` is cloned by that body alone, so its parts are not
    /// visited.
    fn queue_nested_clones(&mut self, t: Ty) {
        let mut seen = FxHashSet::default();
        let mut work = vec![t];
        while let Some(t) = work.pop() {
            if !seen.insert(t) {
                continue;
            }
            let tcx = self.tys().tcx();
            match tcx.kind(t) {
                HK::Ref(x) | HK::MutRef(x) => work.push(x),
                HK::Tuple(l) => work.extend(tcx.list(l)),
                HK::Array { elem, .. } | HK::Slice { elem, .. } => work.push(elem),
                HK::Intrinsic { args, .. } => work.extend(tcx.list(args)),
                HK::Adt { args, .. } => {
                    if let Some((d, args)) = self.user_impl_method(t, "Clone", "clone") {
                        self.lcx.instance(d, args);
                        continue;
                    }
                    let tcx = self.tys().tcx();
                    work.extend(tcx.list(args));
                    if let Some((adt, _)) = tcx.adt_of(t) {
                        for (k, v) in adt.variants.iter().enumerate() {
                            let variant = adt.is_enum.then_some(k as u32);
                            for i in 0..v.fields.len() {
                                work.extend(tcx.field_ty(t, variant, i as u32));
                            }
                        }
                    }
                }
                _ => {}
            }
        }
    }

    /// Queue the user `PartialEq.eq` of a collection's element or key
    /// type, which the interpreter compares keys and searches by.
    fn queue_key_eq(&mut self, collection: Ty) {
        let (_, base) = self.strip_ty_full(collection);
        let elem = match self.tys().tcx().kind(base) {
            HK::Intrinsic { args, .. } => self.tys().tcx().list(args).first().copied(),
            _ => None,
        };
        if let Some(e) = elem {
            let (_, e) = self.strip_ty_full(e);
            if let Some((d, args)) = self.user_impl_method(e, "PartialEq", "eq") {
                self.lcx.instance(d, args);
            }
        }
    }

    /// Queue `t`'s user `Ord.cmp`, which the interpreter sorts by.
    fn queue_user_cmp(&mut self, t: Ty) {
        let (_, t) = self.strip_ty_full(t);
        if let Some((d, args)) = self.user_impl_method(t, "Ord", "cmp") {
            self.lcx.instance(d, args);
        }
    }

    fn user_impl_method(&self, t: Ty, tr: &str, method: &str) -> Option<(DefId, Vec<Ty>)> {
        self.nth_impl_method(t, tr, method, 0)
    }

    /// `method` of the `n`th impl of `tr` for `t`'s type, in source order.
    fn nth_impl_method(&self, t: Ty, tr: &str, method: &str, n: usize) -> Option<(DefId, Vec<Ty>)> {
        if let HK::Dyn { .. } = self.tys().tcx().kind(t) {
            return (n == 0)
                .then(|| self.dyn_impl_method(t, tr, method))
                .flatten();
        }
        let (d, targs) = self.nth_impl_def(t, tr, method, n)?;
        match targs {
            Some(args) => Some((d, self.lcx.fns.get(&d)?.impl_args(&args)?)),
            None => Some((d, Vec::new())),
        }
    }

    /// `method` of the impl of `tr[trait_args]` for `t`: of `impl
    /// Handler[i64] for Both` and `impl Handler[String] for Both`, the one
    /// the arguments name, and an impl parameter only the trait's
    /// arguments name (`T` of `impl[T] Handler[T] for Echo`) read off them.
    pub(super) fn trait_impl_method(
        &self,
        t: Ty,
        tr: &str,
        method: &str,
        trait_args: &[Ty],
    ) -> Option<(DefId, Vec<Ty>)> {
        if trait_args.is_empty() || matches!(self.tys().tcx().kind(t), HK::Dyn { .. }) {
            return self.user_impl_method(t, tr, method);
        }
        let mut n = 0;
        while let Some((d, targs)) = self.nth_impl_def(t, tr, method, n) {
            n += 1;
            let item = self.lcx.fns.get(&d)?;
            let Some(written) = item.impl_trait_args else {
                continue;
            };
            let written: Vec<&ast::TypeExpr> = written
                .iter()
                .filter_map(|a| match a {
                    ast::GenericArg::Type(te) => Some(te),
                    _ => None,
                })
                .collect();
            if written.len() != trait_args.len() {
                continue;
            }
            let names: Vec<&str> = item
                .impl_generics
                .map(|g| g.params.iter().map(|p| p.name.as_str()).collect())
                .unwrap_or_default();
            let mut out: Vec<Option<Ty>> = vec![None; item.impl_params];
            if let Some(from_target) = targs.as_deref().and_then(|a| item.impl_args(a)) {
                for (slot, a) in out.iter_mut().zip(from_target) {
                    *slot = Some(a);
                }
            }
            let fits = written
                .iter()
                .zip(trait_args)
                .all(|(w, &a)| self.written_fits(w, a, &names, &mut out));
            if let (true, Some(inst)) = (fits, out.into_iter().collect::<Option<Vec<_>>>()) {
                return Some((d, inst));
            }
        }
        None
    }

    /// Whether `te`, a type an impl writes, can be `t`, binding each of the
    /// impl's parameters (`names`) it writes to its part of `t`.
    fn written_fits(
        &self,
        te: &ast::TypeExpr,
        t: Ty,
        names: &[&str],
        out: &mut [Option<Ty>],
    ) -> bool {
        let tcx = self.tys().tcx();
        match &te.kind {
            ast::TypeKind::Path(q) => {
                let Some(last) = q.segments.last() else {
                    return false;
                };
                if q.generic_args.is_none() && q.segments.len() == 1 {
                    if let Some(i) = names.iter().position(|n| n == last) {
                        return match out.get_mut(i) {
                            Some(Some(b)) => *b == t,
                            Some(slot) => {
                                *slot = Some(t);
                                true
                            }
                            None => false,
                        };
                    }
                    if let Some(p) = self.lcx.primitive(last) {
                        return p == t;
                    }
                }
                let (name, args) = match tcx.kind(t) {
                    HK::Adt { def, args } | HK::Shared { def, args } => {
                        (self.lcx.def_name(def), tcx.list(args))
                    }
                    HK::Intrinsic { kind, args } => (kind.name().to_string(), tcx.list(args)),
                    _ => return false,
                };
                let written = q.generic_args.as_deref().unwrap_or(&[]);
                &name == last
                    && written.len() == args.len()
                    && written.iter().zip(args).all(|(w, a)| match w {
                        ast::GenericArg::Type(w) => self.written_fits(w, a, names, out),
                        _ => true,
                    })
            }
            ast::TypeKind::Tuple(ws) => match tcx.kind(t) {
                HK::Tuple(l) => {
                    let l = tcx.list(l);
                    ws.len() == l.len()
                        && ws
                            .iter()
                            .zip(l)
                            .all(|(w, a)| self.written_fits(w, a, names, out))
                }
                HK::Unit => ws.is_empty(),
                _ => false,
            },
            ast::TypeKind::Ref(w) => {
                matches!(tcx.kind(t), HK::Ref(i) if self.written_fits(w, i, names, out))
            }
            ast::TypeKind::MutRef(w) => {
                matches!(tcx.kind(t), HK::MutRef(i) if self.written_fits(w, i, names, out))
            }
            _ => false,
        }
    }

    /// The `n`th impl of `tr` for `t`'s type that has `method`, with
    /// `t`'s arguments (`None` for a primitive, whose impl has no target).
    fn nth_impl_def(
        &self,
        t: Ty,
        tr: &str,
        method: &str,
        n: usize,
    ) -> Option<(DefId, Option<Vec<Ty>>)> {
        let label = format!("impl {tr}#{n}");
        let (def, args) = match self.tys().tcx().adt_of(t) {
            Some((adt, args)) => (adt.def, args),
            None => match self.tys().tcx().kind(t) {
                HK::Intrinsic { kind, args } => (
                    self.lcx.defs.lookup(0, kind.name())?,
                    crate::mir::ty::table_args(kind, self.tys().tcx().list(args)),
                ),
                // A primitive's impl (`impl Shape for i64`) has no target
                // definition: the method whose `self` was checked at `t`.
                _ => {
                    return self.lcx.fns.iter().find_map(|(&d, i)| {
                        let path = &self.lcx.defs.table.get(d).path.segments;
                        (i.impl_prim == Some(t)
                            && i.f.name == method
                            && path.len() >= 2
                            && path[path.len() - 2] == label)
                            .then_some((d, None))
                    });
                }
            },
        };
        let mut path = self.lcx.defs.table.get(def).path.segments.clone();
        path.push(label);
        path.push(method.to_string());
        let d = self.lcx.defs.table.lookup(&DefPath::new(path))?;
        let d = self.lcx.lowered_def(d)?;
        self.lcx.fns.contains_key(&d).then_some((d, Some(args)))
    }

    /// B-2026-10-15-76 — the operator method `a <op> right` calls on `t`:
    /// of the impls of `tr` for `t`'s type (`impl Mul for Duration`, `impl
    /// Mul[i64] for Duration`), the one whose `rhs` is `right`'s type, as the
    /// typechecker chose it; the first when only one exists or none fits.
    fn user_operator_method(
        &mut self,
        t: Ty,
        tr: &str,
        method: &str,
        right: &'a Expr,
    ) -> R<Option<(DefId, Vec<Ty>)>> {
        let Some(first) = self.user_impl_method(t, tr, method) else {
            return Ok(None);
        };
        // B-2026-10-28-16 — on a primitive left operand (`2.0 * col` with
        // `impl Mul[Col] for f64`) only an impl whose `rhs` is the right
        // operand's type applies; `2.0 * 3.0` stays the built-in operator.
        let scalar = matches!(
            self.tys().tcx().kind(t),
            HK::Int(_) | HK::UInt(_) | HK::Float(_) | HK::Bool | HK::Char
        );
        if !scalar && self.nth_impl_method(t, tr, method, 1).is_none() {
            return Ok(Some(first));
        }
        let rt = self.expr_ty(right)?;
        let (_, rt) = self.strip_ty_full(rt);
        let mut n = 0;
        while let Some((d, args)) = self.nth_impl_method(t, tr, method, n) {
            let f = self.lcx.fns[&d].f;
            if let Some(p) = f.params.first() {
                let pt = self.callee_param_ty(p, &args)?;
                let (_, pt) = self.strip_ty_full(pt);
                if pt == rt {
                    return Ok(Some((d, args)));
                }
            }
            n += 1;
        }
        Ok((!scalar).then_some(first))
    }

    /// `dbg(x)` where `x` names a place: the argument.
    fn discarded_dbg(&self, e: &'a Expr) -> Option<&'a Expr> {
        let ExprKind::Call { callee, args, .. } = &e.kind else {
            return None;
        };
        let [a] = args.as_slice() else {
            return None;
        };
        let builtin = matches!(&callee.kind, ExprKind::Identifier(n) if n == "dbg")
            && matches!(
                self.lcx.calls.get(&e.id).map(|rc| &rc.callee),
                Some(Callee::Builtin(n)) if n == "dbg"
            );
        (builtin && is_place_expr(&a.value) && self.is_place(&a.value)).then_some(&a.value)
    }

    /// The library's `dbg` writing `[file:line] text = <value>` to stderr,
    /// for `value`, a reference to what `a` evaluated to. A release build
    /// evaluates the argument and prints nothing (design.md § `dbg()`).
    /// Evaluate an assertion's operand `x` once, now: a pure one (a
    /// literal, a constant, a path) is read again where it is used, any
    /// other's place is kept for the comparison and the failure message.
    fn pin_operand(&mut self, x: &'a Expr) -> R<()> {
        let pure = matches!(
            x.kind,
            ExprKind::StringLit(_)
                | ExprKind::Identifier(_)
                | ExprKind::Path { .. }
                | ExprKind::SelfValue
        ) || self.constant(x)?.is_some();
        if pure {
            return Ok(());
        }
        let p = if self.is_place(x) {
            self.expr_place(x, false)?
        } else {
            let t = self.expr_ty(x)?;
            let l = self.scoped_temp(t);
            self.expr_into(x, Place::local(l))?;
            Place::local(l)
        };
        self.pinned.insert(x.id, p);
        Ok(())
    }

    /// An assertion operand's `Debug` text, for its failure message.
    fn assert_side_debug(&mut self, side: &AssertSide<'a>) -> R<Operand> {
        // A borrow of the value, as `dbg` takes it.
        let (p, t) = match side {
            AssertSide::Place(p, t) => (p.clone(), *t),
            AssertSide::Expr(x) => {
                let t = self.expr_ty(x)?;
                let p = match self.is_place(x) {
                    true => self.expr_place(x, false)?,
                    false => Place::local(self.temp_of(x, t)?),
                };
                (p, t)
            }
        };
        let value = self.ref_to(p, t);
        let st = self.tys().tcx().intern(HK::Str);
        let s = self.temp(st);
        self.call_native("debug_string", vec![value], Place::local(s));
        Ok(self.ref_to(Place::local(s), st))
    }

    fn dbg_print(&mut self, e: &Expr, a: &Expr, value: Operand) {
        if release_strips("KARAC_STRIP_DBG") {
            return;
        }
        let (off, len) = (a.span.offset, a.span.length);
        let text = self
            .lcx
            .source
            .get(off..off + len)
            .filter(|t| !t.is_empty())
            .unwrap_or("<expr>");
        let text = self.static_str(text);
        let line = Operand::Const(Const {
            ty: self.tys().tcx().intern(HK::Int(IntSize::I64)),
            kind: ConstKind::Scalar(e.span.line as u128),
        });
        let unit = self.unit();
        let out = self.temp(unit);
        self.call_native("dbg", vec![line, text, value], Place::local(out));
    }

    /// The library's `impl From for IoError` of a `VarError` (`env.var(k)?`
    /// in a function returning `IoError`), written as its mapping of
    /// variants: `NotPresent` is `NotFound`, `NotUnicode` is `InvalidUtf8`
    /// (runtime/stdlib/io.kara). Replaces the one operand in `ops`.
    fn variant_from(&mut self, want: Ty, have: Ty, ops: &mut Vec<Operand>) -> bool {
        let map: &[(&str, &str)] = match (
            self.tys().display(have).as_str(),
            self.tys().display(want).as_str(),
        ) {
            ("VarError", "IoError") => &[("NotPresent", "NotFound"), ("NotUnicode", "InvalidUtf8")],
            _ => return false,
        };
        let tcx = self.tys().tcx();
        let (Some((from, _)), Some((to, _))) = (tcx.adt_of(have), tcx.adt_of(want)) else {
            return false;
        };
        let pos = |a: &crate::ty::AdtDef, n: &str| {
            a.variants
                .iter()
                .position(|v| v.name == n && v.fields.is_empty())
        };
        let Some(arms) = map
            .iter()
            .map(|(a, b)| Some((pos(&from, a)?, pos(&to, b)?)))
            .collect::<Option<Vec<_>>>()
        else {
            return false;
        };
        if arms.len() != from.variants.len() {
            return false;
        }
        let Some(op) = ops.pop() else {
            return false;
        };
        let h = self.temp(have);
        self.assign(h, Rvalue::Use(op));
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let tag = self.temp(isize_t);
        self.assign(tag, Rvalue::Discriminant(Place::local(h)));
        let out = self.temp(want);
        let join = self.b.new_block();
        let blocks: Vec<BasicBlock> = arms.iter().map(|_| self.b.new_block()).collect();
        let targets = SwitchTargets {
            values: arms
                .iter()
                .zip(&blocks)
                .map(|(&(i, _), &bb)| (i as u128, bb))
                .collect(),
            otherwise: blocks[blocks.len() - 1],
        };
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(tag)),
                targets,
            },
            join,
        );
        for (&(_, j), &bb) in arms.iter().zip(&blocks) {
            self.cur = bb;
            self.build_variant(want, j as u32, Vec::new(), Place::local(out));
            self.goto(join);
        }
        self.cur = join;
        ops.push(Operand::Move(Place::local(out)));
        true
    }

    /// The `from` of the user's non-generic `impl From[source] for
    /// target`, as `?` converts an error.
    fn user_from(&mut self, target: Ty, source: Ty) -> Option<(DefId, Vec<Ty>)> {
        let (adt, _) = self.tys().tcx().adt_of(target)?;
        let base = self.lcx.defs.table.get(adt.def).path.segments.clone();
        // A concrete impl first; then a blanket one over its own parameter
        // (`impl[E: Error] From[E] for AnyError`, design.md §10), instanced
        // at the source. The checker has already held its bounds.
        let mut blanket = None;
        for k in 0.. {
            let mut path = base.clone();
            path.push(format!("impl From#{k}"));
            path.push("from".to_string());
            let Some(d) = self.lcx.defs.table.lookup(&DefPath::new(path)) else {
                break;
            };
            let item = self.lcx.fns.get(&d)?;
            let args = match item.impl_params {
                0 => Vec::new(),
                1 if blanket.is_none() => vec![source],
                _ => continue,
            };
            let p = item.f.params.first()?;
            let t = *self.lcx.node_types.get(&p.pattern.id)?;
            // A `from` that borrows its source (`i: ref Inches`, or a bare
            // `i: Inches`, which D5 reads as that borrow) converts an
            // `Inches` too: an impl may be weaker than its trait (core
            // semantics §4.7, B-2026-10-14-34). The callers lend it.
            let Ok(pt) = self.lcx.mir_ty(t, &args) else {
                continue;
            };
            let pt = match self.tys().tcx().kind(pt) {
                HK::Ref(inner) => inner,
                _ => pt,
            };
            if pt == source {
                if args.is_empty() {
                    return Some((d, args));
                }
                blanket = Some((d, args));
            }
        }
        blanket
    }

    // ── loops ───────────────────────────────────────────────────────

    fn find_loop(&self, label: &Option<String>) -> Option<usize> {
        match label {
            None => self.loops.len().checked_sub(1),
            Some(l) => self
                .loops
                .iter()
                .rposition(|c| c.label.as_deref() == Some(l.as_str())),
        }
    }

    fn loop_body(
        &mut self,
        label: &Option<String>,
        body: &'a Block,
        continue_bb: BasicBlock,
        exit: BasicBlock,
        dest: Option<Place>,
    ) -> R<()> {
        self.loops.push(LoopCx {
            label: label.clone(),
            break_bb: exit,
            continue_bb,
            depth: self.scopes.len(),
            dest,
        });
        let r = self.for_body(body);
        self.loops.pop();
        r?;
        self.goto(continue_bb);
        Ok(())
    }

    /// A loop body, whose value is dropped, or for the body of a `par for`,
    /// pushed onto the `Vec` the loop builds.
    fn for_body(&mut self, body: &'a Block) -> R<()> {
        if let Some((_, span)) = self.auto_par_candidate.take_if(|c| std::ptr::eq(c.0, body)) {
            return self.auto_par_record(body, span);
        }
        let acc = match self.par_acc {
            Some((b, acc, vt, region)) if std::ptr::eq(b, body) => {
                self.par_acc = None;
                Some((acc, vt, region))
            }
            _ => None,
        };
        let Some((acc, vt, region)) = acc else {
            let t = self.unit();
            let tmp = self.temp(t);
            return self.block_into(body, Place::local(tmp));
        };
        let et = match self.tys().tcx().kind(vt) {
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            } => self.tys().tcx().list(args)[0],
            _ => return self.unsupported(body.span, "this `par for`"),
        };
        if let Some(tasks) = self.par_for_tasks.take() {
            return self.par_for_spawn(body, region, et, tasks);
        }
        let v = self.temp(et);
        let entry = self.branch_begin();
        self.block_into(body, Place::local(v))?;
        self.branch_end(region, entry);
        let rt = self.tys().tcx().reference(vt, true);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(acc)));
        let u = self.unit();
        let u = self.temp(u);
        let name = format!("{}.push", self.tys().display(vt));
        self.call_native(
            &name,
            vec![
                Operand::Move(Place::local(r)),
                Operand::Move(Place::local(v)),
            ],
            Place::local(u),
        );
        Ok(())
    }

    /// Opens a `par` region whose branches are filled in as they lower.
    fn open_par_region(&mut self, kind: ParKind, span: Span) -> usize {
        self.b.par_regions.push(ParRegion {
            kind,
            span,
            branches: Vec::new(),
        });
        self.b.par_regions.len() - 1
    }

    /// Starts a branch in a block of its own, so the branch's blocks are
    /// exactly those opened from here to [`Self::branch_end`].
    fn branch_begin(&mut self) -> BasicBlock {
        let entry = self.b.new_block();
        self.goto(entry);
        self.cur = entry;
        entry
    }

    /// Ends the branch begun at `entry`, recording its blocks in `region`,
    /// and continues in a fresh block.
    fn branch_end(&mut self, region: usize, entry: BasicBlock) {
        let after = self.b.new_block();
        self.branch_end_at(region, entry, after);
    }

    /// [`Self::branch_end`], continuing at `after`, a block opened before
    /// the branch so it is not one of the branch's.
    fn branch_end_at(&mut self, region: usize, entry: BasicBlock, after: BasicBlock) {
        let end = self.b.block_count() as u32;
        let blocks = (entry.0..end)
            .filter(|&i| i != after.0)
            .map(BasicBlock)
            .collect();
        self.b.par_regions[region].branches.push(blocks);
        self.goto(after);
        self.cur = after;
    }

    /// Leaves with the error `value` for `ret`: from the function, or, in a
    /// `par` branch, from the branch into its error slot.
    fn error_exit(&mut self, ret: Place, value: Rvalue) -> R<()> {
        match self.par_try.last().copied().flatten() {
            Some(slot) if slot.discard => {
                let t = self.b.local_ty(slot.pending);
                let l = self.temp(t);
                self.assign(l, value);
                let next = self.b.new_block();
                self.goto_with(
                    TerminatorKind::Drop {
                        place: Place::local(l),
                        target: next,
                        unwind: UnwindAction::Abort,
                    },
                    next,
                );
                self.exit_to(slot.depth, true)?;
                self.diverge(TerminatorKind::Goto { target: slot.skip });
                Ok(())
            }
            Some(slot) => {
                self.assign(Place::local(slot.pending), value);
                self.exit_to(slot.depth, true)?;
                self.diverge(TerminatorKind::Goto { target: slot.skip });
                Ok(())
            }
            None => {
                let value = self.exit_value(value);
                self.assign(ret, value);
                self.return_exit()
            }
        }
    }

    /// The type a `return` or `?` here gives back: the function's, also
    /// in a `par` branch's task.
    fn fn_ret_ty(&self) -> Ty {
        match self.par_exit {
            Some((t, _)) => t,
            None => self.b.local_ty(Local::RETURN_PLACE),
        }
    }

    /// `value`, of the function's return type, as this body returns it:
    /// in a `par` branch's task, in the task's exit variant.
    fn exit_value(&mut self, value: Rvalue) -> Rvalue {
        let Some((t, xv)) = self.par_exit else {
            return value;
        };
        let l = self.temp(t);
        self.assign(l, value);
        let rt = self.b.local_ty(Local::RETURN_PLACE);
        let kind = self.adt_aggregate(rt, xv);
        Rvalue::Aggregate(kind, vec![Operand::Move(Place::local(l))])
    }

    /// `par { a, b }`: each expression is a branch and the value is the
    /// tuple of theirs. Each branch runs as a task (`par_tasks`), since
    /// branches may wait on each other, also one that `return`s from the
    /// function. The older `par { s1; s2; }` has one branch per statement,
    /// whose bindings outlive the block; those run in source order.
    fn par_block(&mut self, e: &'a Expr, b: &'a Block, dest: Place) -> R<()> {
        let region = self.open_par_region(ParKind::Block, e.span);
        if b.stmts.is_empty() {
            if let Some(ExprKind::Tuple(es)) = b.final_expr.as_deref().map(|x| &x.kind) {
                if es.len() > 1 {
                    let es: Vec<&'a Expr> = es.iter().collect();
                    return self.par_tasks(region, &es, dest, false);
                }
            }
        }
        // Only a function that returns a `Result` or `Option` has a `?`.
        let ret_ty = self.fn_ret_ty();
        if self.error_variant(ret_ty).is_some() {
            return self.par_block_fallible(region, b, dest);
        }
        if b.stmts.is_empty() {
            if let Some(ExprKind::Tuple(es)) = b.final_expr.as_deref().map(|x| &x.kind) {
                if !es.is_empty() {
                    let mut ops = Vec::new();
                    for x in es {
                        let entry = self.branch_begin();
                        ops.push(self.expr_operand(x)?);
                        self.branch_end(region, entry);
                    }
                    self.assign(dest, Rvalue::Aggregate(AggregateKind::Tuple, ops));
                    return Ok(());
                }
            }
        }
        // The branches' bindings join the enclosing scope, so they live on
        // past the block.
        self.note_escaping_lets(b);
        for s in &b.stmts {
            let entry = self.branch_begin();
            self.stmt(s)?;
            self.branch_end(region, entry);
        }
        match &b.final_expr {
            Some(x) => {
                let entry = self.branch_begin();
                self.push_scope();
                self.expr_into(x, dest)?;
                self.pop_scope()?;
                self.branch_end(region, entry);
            }
            None => self.assign(dest, Rvalue::Use(unit_const(self.unit()))),
        }
        Ok(())
    }

    /// `par { a, b }` with each branch run as a task of a fresh group, the
    /// way `TaskGroup.spawn` runs a closure, and then joined in source
    /// order: a branch may wait on another, as a consumer waits on its
    /// producer through a channel, so no fixed order of the branches is
    /// safe (core semantics §11.1; B-2026-10-21-68). The branches stay a
    /// `par` region, so their conflicts are still checked.
    ///
    /// In a function that returns a `Result` or `Option`, each task returns
    /// its branch's value wrapped in that type, so a `?` in it ends that
    /// branch alone. Once every task is joined, the source-earliest error is
    /// returned and the other results drop (§11.7).
    ///
    /// When a branch `return`s, each task instead returns a `Result` whose
    /// error variant carries the function's whole value, which a `return`
    /// or `?` in the task builds; the source-earliest one is returned.
    /// `hidden`: auto-par made the tasks, which are not tasks to the
    /// program's logging (docs/library/log.md; B-2026-10-27-22).
    fn par_tasks(&mut self, region: usize, es: &[&'a Expr], dest: Place, hidden: bool) -> R<()> {
        let span = es[0].span;
        let ret_ty = self.fn_ret_ty();
        // A branch that `return`s leaves its task with the function's
        // value, so every task returns a `Result` whose error variant
        // carries it, and `?` is the `return` of an error (B-2026-10-22-9).
        let exits = es.iter().any(|x| returns_from_fn(x));
        let err = if exits {
            None
        } else {
            self.error_variant(ret_ty)
        };
        let Some(group_ty) = self.library_struct("TaskGroup", &[]) else {
            return self.unsupported(span, "`par` without the library's `TaskGroup`");
        };
        let g = self.temp(group_ty);
        self.call_native("TaskGroup.new", Vec::new(), Place::local(g));
        if hidden {
            self.hide_group(g, group_ty);
        }
        let mut handles = Vec::new();
        for &x in es {
            let vt = self.expr_ty(x)?;
            let mut exit = None;
            let tt = match err {
                None if exits => {
                    let t = self.enum_of("Result", &[vt, ret_ty]);
                    let Some((t, xv)) = t.and_then(|t| Some((t, self.error_variant(t)?))) else {
                        return self.unsupported(x.span, "this `par` branch's result type");
                    };
                    exit = Some((ret_ty, xv));
                    t
                }
                None => vt,
                Some(ev) => {
                    let wrapped = match self.tys().tcx().adt_of(ret_ty) {
                        Some((adt, _)) if adt.name == "Result" => {
                            let et = self.tys().tcx().field_ty(ret_ty, Some(ev), 0);
                            et.and_then(|et| self.enum_of("Result", &[vt, et]))
                        }
                        _ => self.enum_of("Option", &[vt]),
                    };
                    let Some(t) = wrapped else {
                        return self.unsupported(x.span, "this `par` branch's result type");
                    };
                    t
                }
            };
            let Some(ht) = self.library_struct("TaskHandle", &[tt]) else {
                return self.unsupported(x.span, "`par` without the library's `TaskHandle`");
            };
            let entry = self.branch_begin();
            let task = self.par_task_expr(x);
            self.closure_task = true;
            self.closure_ret = Some((tt, err.or(exit.map(|e| e.1)).map(|ev| 1 - ev)));
            self.closure_exit = exit;
            let made = self.closure_value(task);
            self.closure_task = false;
            self.closure_ret = None;
            self.closure_exit = None;
            let (c, _) = made?;
            let gr = self.ref_to(Place::local(g), group_ty);
            let h = self.temp(ht);
            self.call_native("TaskGroup.spawn", vec![gr, c], Place::local(h));
            self.branch_end(region, entry);
            handles.push((h, ht, tt));
        }
        let mut outs = Vec::new();
        for &(h, ht, tt) in &handles {
            let o = match err {
                Some(_) => self.scoped_temp(tt),
                None if exits => self.scoped_temp(tt),
                None => self.temp(tt),
            };
            let name = format!("{}.join", self.tys().display(ht));
            self.call_native(&name, vec![Operand::Move(Place::local(h))], Place::local(o));
            outs.push((o, tt));
        }
        // The group ends here, so what its tasks borrow is free again.
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Drop {
                place: Place::local(g),
                target: next,
                unwind: UnwindAction::Abort,
            },
            next,
        );
        let Some(ev) = err.or_else(|| {
            let (_, tt) = *outs.first()?;
            exits.then(|| self.error_variant(tt)).flatten()
        }) else {
            let ops = outs
                .into_iter()
                .map(|(o, _)| Operand::Move(Place::local(o)))
                .collect();
            self.assign(dest, Rvalue::Aggregate(AggregateKind::Tuple, ops));
            return Ok(());
        };
        let ok = 1 - ev;
        let ret = Place::local(Local::RETURN_PLACE);
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        for &(o, tt) in &outs {
            let p = Place::local(o);
            let d = self.temp(isize_t);
            self.assign(d, Rvalue::Discriminant(p.clone()));
            let err_bb = self.b.new_block();
            let ok_bb = self.b.new_block();
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(d)),
                    targets: SwitchTargets {
                        values: vec![(ev as u128, err_bb)],
                        otherwise: ok_bb,
                    },
                },
                err_bb,
            );
            // The task's error has the function's error type already; a
            // task that left early carries the function's whole value.
            let mut ops = Vec::new();
            if let Some(et) = self.tys().tcx().field_ty(tt, Some(ev), 0) {
                let fp = p
                    .clone()
                    .project(ProjElem::Downcast(VariantIdx(ev)))
                    .field(0, et);
                ops.push(self.use_place(fp, et));
            }
            let value = match ops.pop() {
                Some(v) if exits => Rvalue::Use(v),
                v => Rvalue::Aggregate(self.adt_aggregate(ret_ty, ev), v.into_iter().collect()),
            };
            self.error_exit(ret.clone(), value)?;
            self.cur = ok_bb;
        }
        let mut ops = Vec::new();
        for (o, tt) in outs {
            let Some(vt) = self.tys().tcx().field_ty(tt, Some(ok), 0) else {
                return self.unsupported(span, "this `par` branch's result type");
            };
            let fp = Place::local(o)
                .project(ProjElem::Downcast(VariantIdx(ok)))
                .field(0, vt);
            ops.push(self.use_place(fp, vt));
        }
        self.assign(dest, Rvalue::Aggregate(AggregateKind::Tuple, ops));
        Ok(())
    }

    /// The closure `|| x` a `par` branch `x` runs as: one per branch, kept
    /// for every instance lowered.
    fn par_task_expr(&mut self, x: &'a Expr) -> &'a Expr {
        if let Some(&t) = self.lcx.par_task_exprs.get(&x.id) {
            return t;
        }
        let t: &'a Expr = Box::leak(Box::new(Expr {
            kind: ExprKind::Closure {
                params: Vec::new(),
                capture_mode: None,
                prefix_span: None,
                body: Box::new(x.clone()),
            },
            span: x.span,
            id: x.id,
        }));
        self.lcx.par_task_exprs.insert(x.id, t);
        t
    }

    /// A `par` block whose branches may use `?`. A failing branch does not
    /// cancel the others: every branch runs, and the block then fails with
    /// the source-earliest error (core semantics §11.7; B-2026-10-19-54).
    ///
    /// Each branch is lowered twice: once on the path where no branch has
    /// failed yet, whose values the block's result reads, and once on the
    /// path after a failure, whose values are dropped and whose errors are
    /// dropped too. So the result is never read where a branch failed.
    fn par_block_fallible(&mut self, region: usize, b: &'a Block, dest: Place) -> R<()> {
        enum Branch<'e> {
            Stmt(&'e Stmt),
            Expr(&'e Expr),
        }
        let tuple = match b.final_expr.as_deref().map(|x| &x.kind) {
            Some(ExprKind::Tuple(es)) if b.stmts.is_empty() && !es.is_empty() => Some(es),
            _ => None,
        };
        let branches: Vec<Branch<'a>> = match tuple {
            Some(es) => es.iter().map(Branch::Expr).collect(),
            None => {
                self.note_escaping_lets(b);
                b.stmts
                    .iter()
                    .map(Branch::Stmt)
                    .chain(b.final_expr.as_deref().map(Branch::Expr))
                    .collect()
            }
        };
        let ret_ty = self.fn_ret_ty();
        let pending = self.temp(ret_ty);
        self.schedule(ScopeEntry::Drop(Place::local(pending)));
        // `after[j]`: the copy of branch `j` that runs after a failure;
        // `after[n]` fails the block.
        let after: Vec<BasicBlock> = (0..=branches.len()).map(|_| self.b.new_block()).collect();
        let depth = self.scopes.len();
        let mut ops = Vec::new();
        for (j, br) in branches.iter().enumerate() {
            // The branch's error goes to a slot of its own, which only it
            // writes, and moves to `pending` outside the branch.
            let own = self.temp(ret_ty);
            self.schedule(ScopeEntry::Drop(Place::local(own)));
            let failed = self.b.new_block();
            let here = self.cur;
            self.cur = failed;
            self.assign(pending, Rvalue::Use(Operand::Move(Place::local(own))));
            self.goto(after[j + 1]);
            self.cur = here;
            let entry = self.branch_begin();
            self.par_try.push(Some(ParTry {
                depth,
                skip: failed,
                pending: own,
                discard: false,
            }));
            let r = match br {
                Branch::Stmt(s) => self.stmt(s),
                Branch::Expr(x) if tuple.is_some() => self.expr_operand(x).map(|op| ops.push(op)),
                Branch::Expr(x) => {
                    self.push_scope();
                    let r = self.expr_into(x, dest.clone());
                    r.and_then(|()| self.pop_scope())
                }
            };
            self.par_try.pop();
            r?;
            let next = self.b.new_block();
            self.branch_end_at(region, entry, next);
        }
        match tuple {
            Some(_) => self.assign(dest, Rvalue::Aggregate(AggregateKind::Tuple, ops)),
            None if b.final_expr.is_none() => {
                self.assign(dest, Rvalue::Use(unit_const(self.unit())))
            }
            None => {}
        }
        let done = self.b.new_block();
        self.goto(done);
        // The path after a failure: the later branches run for their
        // effects, and their values and errors are dropped. Their bindings
        // are not the ones the code after the block names.
        let saved = self.locals.clone();
        for (j, br) in branches.iter().enumerate().skip(1) {
            self.cur = after[j];
            self.par_try.push(Some(ParTry {
                depth,
                skip: after[j + 1],
                pending,
                discard: true,
            }));
            let r = match br {
                Branch::Stmt(s) => self.stmt(s),
                Branch::Expr(x) => {
                    self.push_scope();
                    let t = self.expr_ty(x)?;
                    let l = self.temp(t);
                    let r = self.expr_into(x, Place::local(l));
                    self.schedule(ScopeEntry::Drop(Place::local(l)));
                    r.and_then(|()| self.pop_scope())
                }
            };
            self.par_try.pop();
            r?;
            self.goto(after[j + 1]);
        }
        self.locals = saved;
        // No branch fails before the first one runs.
        self.cur = after[0];
        self.diverge(TerminatorKind::Unreachable);
        self.cur = after[branches.len()];
        let ret = Place::local(Local::RETURN_PLACE);
        self.error_exit(ret, Rvalue::Use(Operand::Move(Place::local(pending))))?;
        self.cur = done;
        Ok(())
    }

    /// `par for x in it { body }`: one branch per element, and the value is
    /// the `Vec` of the bodies' values in iteration order (design.md
    /// § `par for`). Branches that do not conflict may run in any order, so
    /// running them one after another in iteration order is one of the
    /// allowed schedules. A limit is evaluated first, and `n <= 0` panics.
    #[allow(clippy::too_many_arguments)]
    fn par_for(
        &mut self,
        e: &'a Expr,
        label: &Option<String>,
        pattern: &'a Pattern,
        iterable: &'a Expr,
        body: &'a Block,
        par: &'a ParLoop,
        dest: Place,
    ) -> R<()> {
        let mut limit = None;
        if let Some(n) = &par.limit {
            let nt = self.expr_ty(n)?;
            let nv = self.expr_operand(n)?;
            let held = self.temp(nt);
            self.assign(held, Rvalue::Use(nv));
            let nv = Operand::Copy(Place::local(held));
            limit = Some(nv.clone());
            let bool_t = self.tys().bool();
            let c = self.temp(bool_t);
            let zero = Operand::Const(Const {
                ty: nt,
                kind: ConstKind::Scalar(0),
            });
            self.assign(c, Rvalue::BinaryOp(BinOp::Le, nv, zero));
            let bad = self.b.new_block();
            let ok = self.b.new_block();
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(c)),
                    targets: SwitchTargets::if_else(bad, ok),
                },
                bad,
            );
            self.diverge(TerminatorKind::Abort {
                reason: AbortReason::Panic,
            });
            self.cur = ok;
        }
        let vt = self.expr_ty(e)?;
        self.push_scope();
        let acc = self.temp(vt);
        let bb = self.cur;
        self.b.push(bb, StatementKind::StorageLive(acc));
        let name = format!("{}.new", self.tys().display(vt));
        self.call_native(&name, Vec::new(), Place::local(acc));
        self.declare(acc, vt);
        let region = self.open_par_region(
            ParKind::For {
                limit: limit.clone(),
            },
            e.span,
        );
        let tasks = self.par_for_tasks_begin(e, body, vt, limit)?;
        let joins = tasks
            .as_ref()
            .map(|t| (t.group, t.group_ty, t.handles, t.handles_ty));
        let saved = self
            .par_acc
            .replace((body as *const Block, acc, vt, region));
        let saved_tasks = std::mem::replace(&mut self.par_for_tasks, tasks);
        let t = self.unit();
        let unit = self.temp(t);
        self.par_try.push(None);
        let r = self.for_range(e, label, pattern, iterable, body, Place::local(unit));
        self.par_try.pop();
        self.par_acc = saved;
        self.par_for_tasks = saved_tasks;
        r?;
        if let Some((g, gt, hs, hvt)) = joins {
            let et = match self.tys().tcx().kind(vt) {
                HK::Intrinsic { args, .. } => self.tys().tcx().list(args)[0],
                _ => unreachable!("a `par for`'s value is a `Vec`"),
            };
            self.par_for_join(g, gt, hs, hvt, et, JoinSink::Push(acc, vt))?;
        }
        self.assign(dest, Rvalue::Use(Operand::Move(Place::local(acc))));
        self.pop_scope()
    }

    /// Whether a `par for`'s iterations run as tasks, and if so its group
    /// and handle `Vec`, made here before the loop. They do unless the body
    /// leaves the loop or the function (`?`, `return`, `break`,
    /// `continue`), whose meaning in a task is still the sequential one, or
    /// its value can hold a borrow, which a join through the handle `Vec`
    /// would tie to that `Vec`. `KARAC_PAR_FOR_TASKS=0` keeps every one
    /// sequential.
    fn par_for_tasks_begin(
        &mut self,
        e: &'a Expr,
        body: &'a Block,
        vt: Ty,
        limit: Option<Operand>,
    ) -> R<Option<ParForTasks>> {
        if std::env::var("KARAC_PAR_FOR_TASKS").as_deref() == Ok("0") {
            return Ok(None);
        }
        let et = match self.tys().tcx().kind(vt) {
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            } => self.tys().tcx().list(args)[0],
            _ => return Ok(None),
        };
        self.loop_tasks(e, body, et, limit, false)
    }

    /// Marks auto-par's group `g` (B-2026-10-27-22): its tasks log as their
    /// spawner, and their records reach the backend in spawn order at its
    /// drop, as the sequential program emits them.
    fn hide_group(&mut self, g: Local, group_ty: Ty) {
        let gr = self.ref_to(Place::local(g), group_ty);
        let unit = self.unit();
        let u = self.temp(unit);
        self.call_native("TaskGroup.__hidden", vec![gr], Place::local(u));
    }

    /// [`Self::par_for_tasks_begin`] for a loop whose iterations return
    /// `et`: its group and handle `Vec`, or `None` when its body leaves the
    /// loop or `et` can hold a borrow.
    fn loop_tasks(
        &mut self,
        e: &'a Expr,
        body: &'a Block,
        et: Ty,
        limit: Option<Operand>,
        hidden: bool,
    ) -> R<Option<ParForTasks>> {
        let Some(task) = self.par_for_task_expr(e, body) else {
            return Ok(None);
        };
        let mut leaves = false;
        crate::span_visitor::for_each_expr(task, &mut |x| {
            leaves |= matches!(
                x.kind,
                ExprKind::Return(_)
                    | ExprKind::Question(_)
                    | ExprKind::Break { .. }
                    | ExprKind::Continue { .. }
            );
        });
        if leaves || crate::mir::borrowck::holds_borrow(self.tys(), et) {
            return Ok(None);
        }
        let (Some(group_ty), Some(ht)) = (
            self.library_struct("TaskGroup", &[]),
            self.library_struct("TaskHandle", &[et]),
        ) else {
            return Ok(None);
        };
        let handles_ty = {
            let tcx = self.tys().tcx();
            let args = tcx.intern_list(&[ht]);
            tcx.intern(HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            })
        };
        let group = self.temp(group_ty);
        self.call_native(
            "TaskGroup.new",
            limit.into_iter().collect(),
            Place::local(group),
        );
        if hidden {
            self.hide_group(group, group_ty);
        }
        let handles = self.temp(handles_ty);
        let name = format!("{}.new", self.tys().display(handles_ty));
        self.call_native(&name, Vec::new(), Place::local(handles));
        Ok(Some(ParForTasks {
            group,
            group_ty,
            handles,
            handles_ty,
            outer: self.locals.keys().copied().collect(),
        }))
    }

    /// The closure `|| { body }` a `par for` iteration runs as: one per
    /// loop, kept for every instance lowered. Its id is a fresh one typed
    /// as the body's value.
    fn par_for_task_expr(&mut self, e: &'a Expr, body: &'a Block) -> Option<&'a Expr> {
        let key = body as *const Block;
        if let Some(&t) = self.lcx.par_for_task_exprs.get(&key) {
            return Some(t);
        }
        let id = NodeId(self.lcx.next_synthetic_node);
        self.lcx.next_synthetic_node -= 1;
        // The checker's type of the loop, when it records one, gives the
        // body's.
        let et = self
            .lcx
            .node_types
            .get(&e.id)
            .and_then(|&vt| match self.tys().tcx().kind(vt) {
                HK::Intrinsic {
                    kind: IntrinsicKind::Vec,
                    args,
                } => Some(self.tys().tcx().list(args)[0]),
                _ => None,
            });
        if let Some(et) = et {
            self.lcx.node_types.insert(id, et);
        }
        let block = Expr {
            kind: ExprKind::Block(body.clone()),
            span: body.span,
            id,
        };
        let t: &'a Expr = Box::leak(Box::new(Expr {
            kind: ExprKind::Closure {
                params: Vec::new(),
                capture_mode: None,
                prefix_span: None,
                body: Box::new(block),
            },
            span: body.span,
            id,
        }));
        self.lcx.par_for_task_exprs.insert(key, t);
        Some(t)
    }

    /// After a loop whose iterations ran as tasks: joins each in iteration
    /// order, handing its value (of type `et`) to `sink`, then drops the
    /// handles and the group, so what the tasks borrow is free again.
    fn par_for_join(
        &mut self,
        g: Local,
        gt: Ty,
        hs: Local,
        hvt: Ty,
        et: Ty,
        sink: JoinSink<'a>,
    ) -> R<()> {
        let tcx = self.tys().tcx();
        let usize_t = tcx.intern(HK::UInt(UIntSize::Usize));
        let ht = match tcx.kind(hvt) {
            HK::Intrinsic { args, .. } => tcx.list(args)[0],
            _ => unreachable!("a loop's handles are a `Vec`"),
        };
        let n = self.seq_len(&Place::local(hs), hvt);
        let i = self.temp(usize_t);
        self.assign(
            i,
            Rvalue::Use(Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(0),
            })),
        );
        // A replaying reduction's runs, as the spawn cut them: run `j`
        // from `from` to `to`.
        let runs = match &sink {
            JoinSink::Fold(_, Some(rp)) => {
                let (from, j, to) = (self.temp(rp.ty), self.temp(rp.ty), self.temp(rp.ty));
                self.assign(from, Rvalue::Use(Operand::Copy(Place::local(rp.lo))));
                self.assign(
                    j,
                    Rvalue::Use(Operand::Const(Const {
                        ty: rp.ty,
                        kind: ConstKind::Scalar(0),
                    })),
                );
                Some((*rp, from, j, to))
            }
            _ => None,
        };
        let head = self.b.new_block();
        let body_bb = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        let bool_t = self.tys().bool();
        let c = self.temp(bool_t);
        self.assign(
            c,
            Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(Place::local(i)),
                Operand::Copy(Place::local(n)),
            ),
        );
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(body_bb, exit),
            },
            body_bb,
        );
        let r = self.ref_to(Place::local(hs), hvt);
        let hr = self.tys().tcx().reference(ht, false);
        let h = self.temp(hr);
        let name = format!("{}.index", self.tys().display(hvt));
        self.call_native(
            &name,
            vec![r, Operand::Copy(Place::local(i))],
            Place::local(h),
        );
        // The handle gives its result up; the `Vec` then drops it empty.
        let v = self.temp(et);
        let name = format!("{}.join", self.tys().display(ht));
        self.call_native(&name, vec![Operand::Copy(Place::local(h))], Place::local(v));
        match sink {
            JoinSink::Push(acc, vt) => {
                let rt = self.tys().tcx().reference(vt, true);
                let ar = self.temp(rt);
                self.assign(ar, Rvalue::Ref(BorrowKind::Mut, Place::local(acc)));
                let u = self.unit();
                let u = self.temp(u);
                let name = format!("{}.push", self.tys().display(vt));
                self.call_native(
                    &name,
                    vec![
                        Operand::Move(Place::local(ar)),
                        Operand::Move(Place::local(v)),
                    ],
                    Place::local(u),
                );
            }
            JoinSink::Fold(r, _) if r.push => {
                let rt = self.tys().tcx().reference(r.ty, true);
                let ar = self.temp(rt);
                self.assign(ar, Rvalue::Ref(BorrowKind::Mut, Place::local(r.acc)));
                let u = self.unit();
                let u = self.temp(u);
                let name = format!("{}.extend", self.tys().display(r.ty));
                self.call_native(
                    &name,
                    vec![
                        Operand::Move(Place::local(ar)),
                        Operand::Move(Place::local(v)),
                    ],
                    Place::local(u),
                );
            }
            JoinSink::Fold(r, _) => {
                if let Some((rp, from, j, to)) = runs {
                    let copy = |l: Local| Operand::Copy(Place::local(l));
                    let one = Operand::Const(Const {
                        ty: rp.ty,
                        kind: ConstKind::Scalar(1),
                    });
                    self.assign(to, Rvalue::BinaryOp(BinOp::Add, copy(from), copy(rp.q)));
                    let longer = self.temp(bool_t);
                    self.assign(longer, Rvalue::BinaryOp(BinOp::Lt, copy(j), copy(rp.rem)));
                    self.when(longer, |b| {
                        b.assign(to, Rvalue::BinaryOp(BinOp::Add, copy(to), one.clone()));
                    });
                    self.fold_or_replay(r, v, (rp, from, to))?;
                    self.assign(from, Rvalue::Use(copy(to)));
                    self.assign(j, Rvalue::BinaryOp(BinOp::Add, copy(j), one));
                } else if r.wide.is_some() {
                    self.wide_fold(r, v);
                } else {
                    self.fold(r, v);
                }
            }
            JoinSink::Discard => {}
        }
        self.assign(
            i,
            Rvalue::BinaryOp(
                BinOp::Add,
                Operand::Copy(Place::local(i)),
                Operand::Const(Const {
                    ty: usize_t,
                    kind: ConstKind::Scalar(1),
                }),
            ),
        );
        self.goto(head);
        self.cur = exit;
        for (p, _) in [(hs, hvt), (g, gt)] {
            let next = self.b.new_block();
            self.goto_with(
                TerminatorKind::Drop {
                    place: Place::local(p),
                    target: next,
                    unwind: UnwindAction::Abort,
                },
                next,
            );
        }
        Ok(())
    }

    /// A task's value `v` folded into the reduction `r` by its operation,
    /// an overflow named at the loop's operation.
    fn fold(&mut self, r: AutoRed<'a>, v: Local) {
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo {
            span: r.span,
            ..outer
        });
        self.arith(
            r.op,
            Operand::Copy(Place::local(r.acc)),
            Operand::Move(Place::local(v)),
            r.ty,
            Place::local(r.acc),
        );
        self.b.set_source_info(outer);
    }

    /// A replaying reduction's fold of the task value `v` of the run from
    /// `from` to `to` (see [`AutoRed::replay`]): when it would overflow,
    /// the run again in order, which overflows at its site.
    fn fold_or_replay(
        &mut self,
        r: AutoRed<'a>,
        v: Local,
        run: (Replay<'a>, Local, Local),
    ) -> R<()> {
        let bool_t = self.tys().bool();
        let (sum, over) = if r.wide.is_some() {
            let (bad, sum) = self.wide_check(r, v);
            (
                Rvalue::Cast(CastKind::IntToInt, Operand::Move(Place::local(sum)), r.ty),
                bad,
            )
        } else {
            let pt = self.tys().tcx().tuple(&[r.ty, bool_t]);
            let pair = self.temp(pt);
            self.assign(
                pair,
                Rvalue::CheckedBinaryOp(
                    r.op,
                    Operand::Copy(Place::local(r.acc)),
                    Operand::Move(Place::local(v)),
                ),
            );
            let bad = self.temp(bool_t);
            self.assign(
                bad,
                Rvalue::Use(Operand::Copy(Place::local(pair).field(1, bool_t))),
            );
            (
                Rvalue::Use(Operand::Copy(Place::local(pair).field(0, r.ty))),
                bad,
            )
        };
        let again = self.b.new_block();
        let ok = self.b.new_block();
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(over)),
                targets: SwitchTargets::if_else(again, ok),
            },
            ok,
        );
        self.assign(r.acc, sum);
        self.goto(next);
        self.cur = again;
        let (rp, from, to) = run;
        let bound = match &rp.pattern.kind {
            PatternKind::Binding(n) => self
                .lcx
                .binding_syms
                .get(&(rp.pattern.id, n.clone()))
                .copied(),
            _ => None,
        };
        let saved = bound.and_then(|s| self.locals.get(&s).copied());
        self.seq_depth += 1;
        let ran = self.range_loop(
            &None,
            rp.pattern,
            rp.body,
            Operand::Copy(Place::local(from)),
            Some(Operand::Copy(Place::local(to))),
            false,
            rp.ty,
        );
        self.seq_depth -= 1;
        match (bound, saved) {
            (Some(s), Some(l)) => {
                self.locals.insert(s, l);
            }
            (Some(s), None) => {
                self.locals.remove(&s);
            }
            _ => {}
        }
        ran?;
        self.goto(next);
        self.cur = next;
        Ok(())
    }

    /// A task's wide sum `v` (its total, least and greatest prefix) folded
    /// into the signed sum `r`: an overflow, named at the loop's operation,
    /// when `acc` plus either prefix leaves `acc`'s range, which is where
    /// the sequential loop overflows; `acc` plus the total otherwise.
    fn wide_fold(&mut self, r: AutoRed<'a>, v: Local) {
        let (bad, sum) = self.wide_check(r, v);
        let ok = self.b.new_block();
        let over = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(bad)),
                targets: SwitchTargets::if_else(over, ok),
            },
            over,
        );
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo {
            span: r.span,
            ..outer
        });
        self.diverge(TerminatorKind::Abort {
            reason: AbortReason::Overflow,
        });
        self.b.set_source_info(outer);
        self.cur = ok;
        self.assign(
            r.acc,
            Rvalue::Cast(CastKind::IntToInt, Operand::Move(Place::local(sum)), r.ty),
        );
    }

    /// Whether `acc` plus a task's wide sum `v` overflows where the
    /// sequential loop would (either prefix leaves `acc`'s range), and the
    /// sum in `i128`.
    fn wide_check(&mut self, r: AutoRed<'a>, v: Local) -> (Local, Local) {
        let tcx = self.tys().tcx();
        let wt = tcx.intern(HK::Int(IntSize::I128));
        let bool_t = self.tys().bool();
        let (min, max) = int_range(tcx.kind(r.ty));
        let wide = |n: i128| {
            Operand::Const(Const {
                ty: wt,
                kind: ConstKind::Scalar(n as u128),
            })
        };
        let field = |i: u32| Operand::Copy(Place::local(v).field(i, wt));
        let aw = self.temp(wt);
        self.assign(
            aw,
            Rvalue::Cast(CastKind::IntToInt, Operand::Copy(Place::local(r.acc)), wt),
        );
        let mut out = Vec::new();
        for (i, op, bound) in [(1, BinOp::Lt, min), (2, BinOp::Gt, max)] {
            let at = self.temp(wt);
            self.assign(
                at,
                Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(aw)), field(i)),
            );
            let o = self.temp(bool_t);
            self.assign(
                o,
                Rvalue::BinaryOp(op, Operand::Copy(Place::local(at)), wide(bound)),
            );
            out.push(o);
        }
        let bad = self.temp(bool_t);
        self.assign(
            bad,
            Rvalue::BinaryOp(
                BinOp::BitOr,
                Operand::Copy(Place::local(out[0])),
                Operand::Copy(Place::local(out[1])),
            ),
        );
        let sum = self.temp(wt);
        self.assign(
            sum,
            Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(aw)), field(0)),
        );
        (bad, sum)
    }

    /// A `par for` iteration as a task of the loop's group: its handle is
    /// pushed onto the loop's handle `Vec`, and the loop's bindings move
    /// into the task (`ParForTasks::outer`).
    fn par_for_spawn(
        &mut self,
        body: &'a Block,
        region: usize,
        et: Ty,
        tasks: ParForTasks,
    ) -> R<()> {
        let Some(task) = self
            .lcx
            .par_for_task_exprs
            .get(&(body as *const Block))
            .copied()
        else {
            return self.unsupported(body.span, "this `par for`");
        };
        let ParForTasks {
            group,
            group_ty,
            handles,
            handles_ty,
            outer,
        } = tasks;
        let ht = match self.tys().tcx().kind(handles_ty) {
            HK::Intrinsic { args, .. } => self.tys().tcx().list(args)[0],
            _ => return self.unsupported(body.span, "this `par for`"),
        };
        let entry = self.branch_begin();
        self.closure_task = true;
        self.closure_ret = Some((et, None));
        self.closure_by_value = self
            .locals
            .keys()
            .filter(|s| !outer.contains(s))
            .copied()
            .collect();
        let made = self.closure_value(task);
        self.closure_task = false;
        self.closure_ret = None;
        self.closure_by_value.clear();
        let (c, _) = made?;
        let gr = self.ref_to(Place::local(group), group_ty);
        let h = self.temp(ht);
        self.call_native("TaskGroup.spawn", vec![gr, c], Place::local(h));
        self.branch_end(region, entry);
        let rt = self.tys().tcx().reference(handles_ty, true);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(handles)));
        let u = self.unit();
        let u = self.temp(u);
        let name = format!("{}.push", self.tys().display(handles_ty));
        self.call_native(
            &name,
            vec![
                Operand::Move(Place::local(r)),
                Operand::Move(Place::local(h)),
            ],
            Place::local(u),
        );
        Ok(())
    }

    /// A sequential `for`: an auto-par candidate when the build records
    /// them, and its iterations run as tasks when its verdict said yes
    /// (M4 item 14). Nothing in a `seq { .. }` is either.
    #[allow(clippy::too_many_arguments)]
    fn seq_for(
        &mut self,
        e: &'a Expr,
        label: &Option<String>,
        pattern: &'a Pattern,
        iterable: &'a Expr,
        body: &'a Block,
        dest: Place,
    ) -> R<()> {
        if self.seq_depth == 0 {
            match &self.lcx.auto_par {
                AutoPar::Off => {}
                AutoPar::Record => {
                    self.auto_par_candidate = Some((body as *const Block, e.span));
                }
                AutoPar::Apply(hints) => {
                    let key = (self.name.clone(), e.span.offset, e.span.length);
                    if let Some(reds) = hints.loops.get(&key).cloned() {
                        if let Some(red) = self.auto_par_plan(body, &reds)? {
                            return self.auto_par_for(e, label, pattern, iterable, body, red, dest);
                        }
                    }
                }
            }
        }
        self.for_range(e, label, pattern, iterable, body, dest)
    }

    /// `e`'s counting shape, when it has one (see [`CountedWhile`]).
    fn counted_while(
        &mut self,
        e: &'a Expr,
        condition: &'a Expr,
        body: &'a Block,
    ) -> R<Option<CountedWhile<'a>>> {
        if let Some(&c) = self.lcx.counted_whiles.get(&e.id) {
            return Ok(c);
        }
        let found = self.find_counted_while(condition, body)?;
        self.lcx.counted_whiles.insert(e.id, found);
        Ok(found)
    }

    fn find_counted_while(
        &mut self,
        condition: &'a Expr,
        body: &'a Block,
    ) -> R<Option<CountedWhile<'a>>> {
        let ExprKind::Binary {
            op: AstBinOp::Lt,
            left: counter,
            right: bound,
        } = &condition.kind
        else {
            return Ok(None);
        };
        let ExprKind::Identifier(name) = &counter.kind else {
            return Ok(None);
        };
        let t = self.expr_ty(counter)?;
        // An unsuffixed literal bound reads as the counter's type, as the
        // comparison reads it.
        let literal = matches!(bound.kind, ExprKind::Integer(_, None));
        if !matches!(self.tys().tcx().kind(t), HK::Int(_) | HK::UInt(_))
            || (!literal && self.expr_ty(bound)? != t)
        {
            return Ok(None);
        }
        let local = |x: &Expr| match (&x.kind, self.lcx.res.get(&x.id)) {
            (ExprKind::Identifier(_), Some(Res::Local(sym))) if self.locals.contains_key(sym) => {
                Some(*sym)
            }
            _ => None,
        };
        let Some(k) = local(counter) else {
            return Ok(None);
        };
        let is_k = |x: &Expr| local(x) == Some(k);
        let bound_ok = match &bound.kind {
            ExprKind::Integer(..) | ExprKind::Path { .. } => true,
            ExprKind::Identifier(_) => !is_k(bound),
            ExprKind::MethodCall {
                object,
                method,
                args,
                ..
            } => method == "len" && args.is_empty() && local(object).is_some() && !is_k(object),
            _ => false,
        };
        let one = |x: &Expr| matches!(x.kind, ExprKind::Integer(1, _));
        let (Some((step, rest)), None) = (body.stmts.split_last(), &body.final_expr) else {
            return Ok(None);
        };
        let steps = match &step.kind {
            StmtKind::CompoundAssign {
                target,
                op: CompoundOp::Add,
                value,
            } => is_k(target) && one(value),
            StmtKind::Assign { target, value } => {
                is_k(target)
                    && matches!(&value.kind, ExprKind::Binary { op: AstBinOp::Add, left, right }
                        if is_k(left) && one(right))
            }
            _ => false,
        };
        if !bound_ok || !steps || rest.is_empty() {
            return Ok(None);
        }
        let pid = NodeId(self.lcx.next_synthetic_node);
        self.lcx.next_synthetic_node -= 1;
        self.lcx.binding_syms.insert((pid, name.clone()), k);
        self.lcx.node_types.insert(pid, t);
        let pattern: &'a Pattern = Box::leak(Box::new(Pattern {
            kind: PatternKind::Binding(name.clone()),
            span: counter.span,
            id: pid,
        }));
        let bound: &'a Expr = if literal {
            let bid = NodeId(self.lcx.next_synthetic_node);
            self.lcx.next_synthetic_node -= 1;
            self.lcx.node_types.insert(bid, t);
            Box::leak(Box::new(Expr {
                kind: bound.kind.clone(),
                span: bound.span,
                id: bid,
            }))
        } else {
            bound
        };
        let rid = NodeId(self.lcx.next_synthetic_node);
        self.lcx.next_synthetic_node -= 1;
        let range: &'a Expr = Box::leak(Box::new(Expr {
            kind: ExprKind::Binary {
                op: AstBinOp::Range,
                left: counter.clone(),
                right: Box::new(bound.clone()),
            },
            span: condition.span,
            id: rid,
        }));
        let inner: &'a Block = Box::leak(Box::new(Block {
            stmts: rest.to_vec(),
            final_expr: None,
            span: body.span,
        }));
        Ok(Some(CountedWhile {
            pattern,
            range,
            inner,
            step,
            counter,
            bound,
        }))
    }

    /// A counting `while` its verdict said yes to: its iterations run as
    /// tasks, as a `for` over `k..n`'s do, and the counter then holds `n`
    /// when it started below it, as the sequential loop leaves it.
    fn auto_par_while(
        &mut self,
        e: &'a Expr,
        label: &Option<String>,
        cw: CountedWhile<'a>,
        red: Option<AutoRed<'a>>,
        dest: Place,
    ) -> R<()> {
        let t = self.expr_ty(cw.counter)?;
        let k = self.expr_place(cw.counter, false)?;
        self.auto_par_for(e, label, cw.pattern, cw.range, cw.inner, red, dest)?;
        self.push_scope();
        let n = self.temp(t);
        self.expr_into(cw.bound, Place::local(n))?;
        let bool_t = self.tys().bool();
        let below = self.temp(bool_t);
        self.assign(
            below,
            Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(k.clone()),
                Operand::Copy(Place::local(n)),
            ),
        );
        self.when(below, |b| {
            b.assign(k, Rvalue::Use(Operand::Copy(Place::local(n))));
        });
        self.pop_scope()
    }

    /// A sequential `for`'s body, recorded as an auto-par candidate of one
    /// branch, its blocks (M4 item 14).
    fn auto_par_record(&mut self, body: &'a Block, span: Span) -> R<()> {
        // Outer before inner, as `par_regions` are.
        let k = self.b.auto_par_candidates.len();
        self.b.auto_par_candidates.push(ParRegion {
            kind: ParKind::For { limit: None },
            span,
            branches: Vec::new(),
        });
        let t = self.unit();
        let tmp = self.temp(t);
        let entry = self.branch_begin();
        self.block_into(body, Place::local(tmp))?;
        self.candidate_branch_end(k, entry);
        Ok(())
    }

    /// How an auto-par loop's iterations combine, given the spans of the
    /// reductions its verdict names: `Some(None)` when they return
    /// nothing, `Some(Some(r))` when they fold into one reduction, which
    /// may be written at several sites. `None` keeps the loop sequential:
    /// a body with a value, reductions on more than one local, or one that
    /// is not a statement of the body (or of its `if` and `match` arms) on
    /// an integer or `bool` local, or a push onto a `Vec` local.
    fn auto_par_plan(&mut self, body: &'a Block, reds: &[Span]) -> R<Option<Option<AutoRed<'a>>>> {
        if let Some(f) = &body.final_expr {
            let t = self.expr_ty(f)?;
            if t != self.unit() {
                return Ok(None);
            }
        }
        if reds.is_empty() {
            return Ok(Some(None));
        }
        let mut sites = Vec::new();
        for &r in reds {
            match self.reduction_site(body, r)? {
                Some(site) => sites.push(site),
                None => return Ok(None),
            }
        }
        let first = sites[0];
        if sites
            .iter()
            .any(|x| x.sym != first.sym || x.op != first.op || x.push != first.push)
        {
            return Ok(None);
        }
        let (sym, op) = (first.sym, first.op);
        let Some(&acc) = self.locals.get(&sym) else {
            return Ok(None);
        };
        self.red_lines = reds.iter().map(|r| r.line).collect();
        self.red_lines.sort_unstable();
        let ty = self.b.local_ty(acc);
        if first.push {
            let vec = matches!(
                self.tys().tcx().kind(ty),
                HK::Intrinsic {
                    kind: IntrinsicKind::Vec,
                    ..
                }
            );
            let capacity = matches!(&self.lcx.auto_par, AutoPar::Apply(h) if h.observes_capacity);
            if !vec || sites.len() > 1 || capacity {
                return Ok(None);
            }
            return Ok(Some(Some(AutoRed {
                sym,
                acc,
                op,
                ty,
                span: first.span,
                wide: None,
                push: true,
                replay: false,
            })));
        }
        let starts = sites.iter().all(|x| x.chain_starts);
        // A checked `*` stays sequential: a run's product can overflow
        // where the sequential one never does (an earlier 0 keeps it 0),
        // and so can a signed sum, which the tasks keep wide; an `i128`
        // has no wider type to keep it in.
        let (wide, checked) = match (self.tys().tcx().kind(ty), op) {
            (HK::Int(_) | HK::UInt(_), BinOp::Mul) => return Ok(None),
            (HK::Int(_) | HK::UInt(_), BinOp::Add) if !starts => return Ok(None),
            (HK::Int(IntSize::I128), BinOp::Add) => return Ok(None),
            (HK::Int(_), BinOp::Add) => (true, true),
            (HK::UInt(_), BinOp::Add) => (false, true),
            (HK::Int(_) | HK::UInt(_) | HK::Bool, _) => (false, false),
            _ => return Ok(None),
        };
        let wide = if wide {
            let key = body as *const Block;
            let sums = match self.lcx.auto_par_wides.get(&key) {
                Some(&sums) => sums,
                None => {
                    let sums: &'a [WideSum<'a>] = Box::leak(
                        sites
                            .iter()
                            .map(|x| WideSum {
                                stmt: x.stmt,
                                term: x.term,
                                chain: x.chain,
                                acc: sym,
                                ty,
                            })
                            .collect::<Vec<_>>()
                            .into_boxed_slice(),
                    );
                    self.lcx.auto_par_wides.insert(key, sums);
                    sums
                }
            };
            Some(sums)
        } else {
            None
        };
        Ok(Some(Some(AutoRed {
            sym,
            acc,
            op,
            ty,
            span: first.span,
            wide,
            push: false,
            replay: checked && sites.len() > 1,
        })))
    }

    /// The reduction at span `r` of an auto-par loop's `body`: `acc op= e`,
    /// `acc = .. acc ..` (a chain of one operator), or `acc.push(e)`.
    fn reduction_site(&mut self, body: &'a Block, r: Span) -> R<Option<RedSite<'a>>> {
        let Some(st) = reduction_stmt(body, r) else {
            return Ok(None);
        };
        let local = |x: &Expr| match (&x.kind, self.lcx.res.get(&x.id)) {
            (ExprKind::Identifier(_), Some(Res::Local(sym))) => Some(*sym),
            _ => None,
        };
        let site = |sym, op, span, term| RedSite {
            stmt: st,
            sym,
            op,
            span,
            term,
            chain: false,
            chain_starts: true,
            push: false,
        };
        Ok(match &st.kind {
            StmtKind::CompoundAssign {
                target, op, value, ..
            } => {
                let op = match op {
                    CompoundOp::Add => BinOp::Add,
                    CompoundOp::Mul => BinOp::Mul,
                    CompoundOp::BitAnd => BinOp::BitAnd,
                    CompoundOp::BitOr => BinOp::BitOr,
                    CompoundOp::BitXor => BinOp::BitXor,
                    _ => return Ok(None),
                };
                local(target).map(|sym| site(sym, op, st.span, value))
            }
            StmtKind::Assign { target, value } => {
                let ExprKind::Binary { op, .. } = &value.kind else {
                    return Ok(None);
                };
                let (Some(op), Some(t)) = (reduction_op(op), local(target)) else {
                    return Ok(None);
                };
                // `acc` one operand of a chain of `op` (`acc = a + acc + b`).
                let Ok(Some(steps)) = self.acc_chain(value, op, t) else {
                    return Ok(None);
                };
                // A checked operation overflows at the step it is, which the
                // join names by the statement's start: every step on the way
                // to `acc` starts there (`acc + a + b`, `a + acc + b`, not
                // `a + (acc + b)`).
                Some(RedSite {
                    chain: true,
                    chain_starts: steps.iter().all(|&o| o == value.span.offset),
                    ..site(t, op, value.span, value)
                })
            }
            StmtKind::Expr(e) => {
                let ExprKind::MethodCall {
                    object,
                    method,
                    args,
                    ..
                } = &e.kind
                else {
                    return Ok(None);
                };
                match (method.as_str(), args.as_slice(), local(object)) {
                    ("push", [a], Some(sym)) => Some(RedSite {
                        push: true,
                        ..site(sym, BinOp::Add, st.span, &a.value)
                    }),
                    _ => None,
                }
            }
            _ => None,
        })
    }

    /// Where `e`, a chain of `op`, holds the local `sym` as one operand: the
    /// starts of the steps on the way down to it, `Ok(None)` when it holds
    /// none, `Err` when it holds more than one.
    fn acc_chain(&self, e: &Expr, op: BinOp, sym: SymbolId) -> Result<Option<Vec<usize>>, ()> {
        if let (ExprKind::Identifier(_), Some(Res::Local(s))) = (&e.kind, self.lcx.res.get(&e.id)) {
            return Ok((*s == sym).then(Vec::new));
        }
        let ExprKind::Binary { op: o, left, right } = &e.kind else {
            return Ok(None);
        };
        if reduction_op(o) != Some(op) {
            return Ok(None);
        }
        let mut steps = match (
            self.acc_chain(left, op, sym)?,
            self.acc_chain(right, op, sym)?,
        ) {
            (Some(_), Some(_)) => return Err(()),
            (Some(p), None) | (None, Some(p)) => p,
            (None, None) => return Ok(None),
        };
        steps.push(e.span.offset);
        Ok(Some(steps))
    }

    /// `op`'s identity on the integer or `bool` type `t`: `x op it` is `x`.
    fn identity(&self, op: BinOp, t: Ty) -> Operand {
        let ones = match self.tys().tcx().kind(t) {
            HK::Bool => 1,
            HK::UInt(s) => match s {
                UIntSize::U8 => u8::MAX as u128,
                UIntSize::U16 => u16::MAX as u128,
                UIntSize::U32 => u32::MAX as u128,
                UIntSize::U128 => u128::MAX,
                _ => u64::MAX as u128,
            },
            // A signed integer's -1, sign-extended as its constants are.
            _ => u128::MAX,
        };
        let v = match op {
            BinOp::Mul => 1,
            BinOp::BitAnd => ones,
            _ => 0,
        };
        Operand::Const(Const {
            ty: t,
            kind: ConstKind::Scalar(v),
        })
    }

    /// An auto-par loop (M4 item 14): `for x in a..b`, its iterations cut
    /// into at most [`AUTO_PAR_TASKS`] runs of consecutive ones, each a task
    /// of one group, joined in order after the loop, folding `red` when the
    /// iterations carry one. Any other loop, or a body the tasks cannot
    /// take, stays sequential.
    #[allow(clippy::too_many_arguments)]
    fn auto_par_for(
        &mut self,
        e: &'a Expr,
        label: &Option<String>,
        pattern: &'a Pattern,
        iterable: &'a Expr,
        body: &'a Block,
        red: Option<AutoRed<'a>>,
        dest: Place,
    ) -> R<()> {
        let (left, right) = match &iterable.kind {
            ExprKind::Binary {
                op: AstBinOp::Range,
                left,
                right,
            } => (&**left, &**right),
            ExprKind::Range {
                start: Some(left),
                end: Some(right),
                inclusive: false,
            } => (&**left, &**right),
            _ => return self.for_range(e, label, pattern, iterable, body, dest),
        };
        let skip: FxHashSet<SymbolId> = match &pattern.kind {
            PatternKind::Binding(n) => self
                .lcx
                .binding_syms
                .get(&(pattern.id, n.clone()))
                .into_iter()
                .copied()
                .collect(),
            PatternKind::Wildcard => FxHashSet::default(),
            _ => return self.for_range(e, label, pattern, iterable, body, dest),
        };
        let et = match red {
            Some(AutoRed { wide: Some(_), .. }) => {
                let tcx = self.tys().tcx();
                let wt = tcx.intern(HK::Int(IntSize::I128));
                tcx.tuple(&[wt, wt, wt])
            }
            Some(r) => r.ty,
            None => self.unit(),
        };
        let Some(tasks) = self.loop_tasks(e, body, et, None, true)? else {
            return self.for_range(e, label, pattern, iterable, body, dest);
        };
        let ParForTasks {
            group,
            group_ty,
            handles,
            handles_ty,
            ..
        } = tasks;
        let ht = match self.tys().tcx().kind(handles_ty) {
            HK::Intrinsic { args, .. } => self.tys().tcx().list(args)[0],
            _ => return self.unsupported(body.span, "this loop's tasks"),
        };
        let Some(task) = self
            .lcx
            .par_for_task_exprs
            .get(&(body as *const Block))
            .copied()
        else {
            return self.unsupported(body.span, "this loop's tasks");
        };
        self.push_scope();
        let (start, end, t) = self.range_bounds(left, Some(right))?;
        let Some(end) = end else {
            return self.unsupported(iterable.span, "this loop's range");
        };
        let int = |v: u128| {
            Operand::Const(Const {
                ty: t,
                kind: ConstKind::Scalar(v),
            })
        };
        let copy = |l: Local| Operand::Copy(Place::local(l));
        let bool_t = self.tys().bool();
        let lo = self.temp(t);
        self.assign(lo, Rvalue::Use(start));
        let hi = self.temp(t);
        self.assign(hi, Rvalue::Use(end));
        // `n` iterations, cut into `k` runs: the first `n % k` one longer.
        // `n` is counted in an `i128` (a range of a narrower type), since
        // `-100i8..100` has more iterations than an `i8` holds; `q`, `k`
        // and `rem` are at most `n / k` and `k`, so they fit in `t`.
        let c = match self.tys().tcx().kind(t) {
            HK::Int(IntSize::I128) | HK::UInt(UIntSize::U128) => t,
            _ => self.tys().tcx().intern(HK::Int(IntSize::I128)),
        };
        let wide = |v: u128| {
            Operand::Const(Const {
                ty: c,
                kind: ConstKind::Scalar(v),
            })
        };
        let widen = |me: &mut Self, l: Local| {
            let w = me.temp(c);
            me.assign(w, Rvalue::Cast(CastKind::IntToInt, copy(l), c));
            w
        };
        let narrow = |me: &mut Self, w: Local| {
            let l = me.temp(t);
            me.assign(l, Rvalue::Cast(CastKind::IntToInt, copy(w), t));
            l
        };
        let n = self.temp(c);
        self.assign(n, Rvalue::Use(wide(0)));
        let some = self.temp(bool_t);
        self.assign(some, Rvalue::BinaryOp(BinOp::Lt, copy(lo), copy(hi)));
        let (lo_c, hi_c) = (widen(self, lo), widen(self, hi));
        self.when(some, |b| {
            b.assign(n, Rvalue::BinaryOp(BinOp::Sub, copy(hi_c), copy(lo_c)));
        });
        let kc = self.temp(c);
        self.assign(kc, Rvalue::Use(wide(AUTO_PAR_TASKS)));
        let few = self.temp(bool_t);
        self.assign(
            few,
            Rvalue::BinaryOp(BinOp::Lt, copy(n), wide(AUTO_PAR_TASKS)),
        );
        self.when(few, |b| b.assign(kc, Rvalue::Use(copy(n))));
        let none = self.temp(bool_t);
        self.assign(none, Rvalue::BinaryOp(BinOp::Eq, copy(kc), wide(0)));
        let d = self.temp(c);
        self.assign(d, Rvalue::Use(copy(kc)));
        self.when(none, |b| b.assign(d, Rvalue::Use(wide(1))));
        let qc = self.temp(c);
        self.assign(qc, Rvalue::BinaryOp(BinOp::Div, copy(n), copy(d)));
        let remc = self.temp(c);
        self.assign(remc, Rvalue::BinaryOp(BinOp::Rem, copy(n), copy(d)));
        let (k, q, rem) = (narrow(self, kc), narrow(self, qc), narrow(self, remc));
        let j = self.temp(t);
        self.assign(j, Rvalue::Use(int(0)));
        let from = self.temp(t);
        self.assign(from, Rvalue::Use(copy(lo)));
        let to = self.temp(t);
        let head = self.b.new_block();
        let spawn = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        let more = self.temp(bool_t);
        self.assign(more, Rvalue::BinaryOp(BinOp::Lt, copy(j), copy(k)));
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(more)),
                targets: SwitchTargets::if_else(spawn, exit),
            },
            spawn,
        );
        self.assign(to, Rvalue::BinaryOp(BinOp::Add, copy(from), copy(q)));
        let longer = self.temp(bool_t);
        self.assign(longer, Rvalue::BinaryOp(BinOp::Lt, copy(j), copy(rem)));
        self.when(longer, |b| {
            b.assign(to, Rvalue::BinaryOp(BinOp::Add, copy(to), int(1)));
        });
        // The task takes its run's bounds, and the reduction's accumulator
        // at the identity, by value.
        let (lo_sym, hi_sym) = (self.lcx.synthetic_sym(), self.lcx.synthetic_sym());
        let run_lo = self.temp(t);
        self.assign(run_lo, Rvalue::Use(copy(from)));
        let run_hi = self.temp(t);
        self.assign(run_hi, Rvalue::Use(copy(to)));
        self.locals.insert(lo_sym, run_lo);
        self.locals.insert(hi_sym, run_hi);
        self.closure_extra_caps = vec![lo_sym, hi_sym];
        self.closure_by_value = [lo_sym, hi_sym].into_iter().collect();
        let mut held = None;
        if let Some(r) = red {
            let start = self.temp(r.ty);
            if r.push {
                let name = format!("{}.new", self.tys().display(r.ty));
                self.call_native(&name, Vec::new(), Place::local(start));
            } else {
                let identity = self.identity(r.op, r.ty);
                self.assign(start, Rvalue::Use(identity));
            }
            held = self.locals.insert(r.sym, start);
            self.closure_by_value.insert(r.sym);
            if r.wide.is_none() {
                self.closure_ret_capture = Some(r.sym);
            }
        }
        self.closure_skip_caps = skip;
        self.closure_chunk = Some(ChunkJob {
            pattern,
            body,
            lo: lo_sym,
            hi: hi_sym,
            ty: t,
            wide: red.and_then(|r| r.wide),
        });
        self.closure_task = true;
        self.closure_ret = Some((et, None));
        self.closure_auto_par = true;
        let made = self.closure_value(task);
        if let (Some(r), Some(acc)) = (red, held) {
            self.locals.insert(r.sym, acc);
        }
        self.locals.remove(&lo_sym);
        self.locals.remove(&hi_sym);
        self.closure_task = false;
        self.closure_ret = None;
        self.closure_ret_capture = None;
        self.closure_chunk = None;
        self.closure_extra_caps.clear();
        self.closure_skip_caps.clear();
        self.closure_by_value.clear();
        let (c, _) = made?;
        let gr = self.ref_to(Place::local(group), group_ty);
        let h = self.temp(ht);
        self.call_native("TaskGroup.spawn", vec![gr, c], Place::local(h));
        let rt = self.tys().tcx().reference(handles_ty, true);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(handles)));
        let u = self.unit();
        let u = self.temp(u);
        let name = format!("{}.push", self.tys().display(handles_ty));
        self.call_native(
            &name,
            vec![
                Operand::Move(Place::local(r)),
                Operand::Move(Place::local(h)),
            ],
            Place::local(u),
        );
        self.assign(from, Rvalue::Use(copy(to)));
        self.assign(j, Rvalue::BinaryOp(BinOp::Add, copy(j), int(1)));
        self.goto(head);
        self.cur = exit;
        let at = format!("{}@{}", self.name, e.span.line);
        if let Some(r) = red {
            let name = self
                .lcx
                .binding_syms
                .iter()
                .find(|(_, s)| **s == r.sym)
                .map(|((_, n), _)| n.clone())
                .unwrap_or_default();
            let lines: Vec<String> = self.red_lines.iter().map(|l| l.to_string()).collect();
            let note = format!("{at} ({name} at {})", lines.join(", "));
            self.lcx.auto_par_reduced.push(note);
        }
        self.lcx.auto_par_done.push(at);
        let sink = match red {
            Some(r) => {
                let replay = r.replay.then_some(Replay {
                    pattern,
                    body,
                    lo,
                    q,
                    rem,
                    ty: t,
                });
                JoinSink::Fold(r, replay)
            }
            None => JoinSink::Discard,
        };
        self.par_for_join(group, group_ty, handles, handles_ty, et, sink)?;
        self.pop_scope()?;
        self.assign(dest, Rvalue::Use(unit_const(self.unit())));
        Ok(())
    }

    /// Runs `then` in a block of its own when the `bool` local `c` holds,
    /// and continues after it either way.
    fn when(&mut self, c: Local, then: impl FnOnce(&mut Self)) {
        let yes = self.b.new_block();
        let after = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(yes, after),
            },
            yes,
        );
        then(self);
        self.goto(after);
        self.cur = after;
    }

    /// `for i in a..b { body }` over integers; `a..` runs until a `break`
    /// (B-2026-10-21-48).
    fn for_range(
        &mut self,
        e: &'a Expr,
        label: &Option<String>,
        pattern: &'a Pattern,
        iterable: &'a Expr,
        body: &'a Block,
        dest: Place,
    ) -> R<()> {
        let (left, right, inclusive): (&'a Expr, Option<&'a Expr>, bool) = match &iterable.kind {
            ExprKind::Binary {
                op: op @ (AstBinOp::Range | AstBinOp::RangeInclusive),
                left,
                right,
            } => (left, Some(right), *op == AstBinOp::RangeInclusive),
            ExprKind::Range {
                start: Some(left),
                end,
                inclusive,
            } if end.is_some() || !*inclusive => (left, end.as_deref(), *inclusive),
            _ => return self.for_collection(e, label, pattern, iterable, body, dest),
        };
        if !matches!(
            pattern.kind,
            PatternKind::Binding(_) | PatternKind::Wildcard
        ) {
            return self.unsupported(pattern.span, "this loop pattern");
        }
        self.push_scope();
        let (start, end, t) = self.range_bounds(left, right)?;
        self.range_loop(label, pattern, body, start, end, inclusive, t)?;
        self.pop_scope()?;
        self.assign(dest, Rvalue::Use(unit_const(self.unit())));
        Ok(())
    }

    /// A range loop's bounds, evaluated, and the type the counter takes.
    fn range_bounds(
        &mut self,
        left: &'a Expr,
        right: Option<&'a Expr>,
    ) -> R<(Operand, Option<Operand>, Ty)> {
        let lt = self.expr_ty(left)?;
        let rt = match right {
            Some(r) => self.expr_ty(r)?,
            None => lt,
        };
        let start = self.expr_operand(left)?;
        let end = match right {
            Some(r) => Some(self.expr_operand(r)?),
            None => None,
        };
        // An unsuffixed literal bound takes the other bound's type (the
        // checker records `-1000i32..1000001`'s end as an `i64`).
        let scalar = |o: &Operand| match o {
            Operand::Const(Const {
                kind: ConstKind::Scalar(v),
                ..
            }) => Some(*v),
            _ => None,
        };
        let t = if scalar(&start).is_some() && end.as_ref().is_some_and(|e| scalar(e).is_none()) {
            rt
        } else {
            lt
        };
        let retype = |o: Operand| match scalar(&o) {
            Some(v) => Operand::Const(Const {
                ty: t,
                kind: ConstKind::Scalar(v),
            }),
            None => o,
        };
        Ok((retype(start), end.map(retype), t))
    }

    /// `for pattern in start..end { body }` (`..=` when `inclusive`, no end
    /// for `start..`) over the integer type `t`, with the bounds evaluated.
    #[allow(clippy::too_many_arguments)]
    fn range_loop(
        &mut self,
        label: &Option<String>,
        pattern: &'a Pattern,
        body: &'a Block,
        start: Operand,
        end: Option<Operand>,
        inclusive: bool,
        t: Ty,
    ) -> R<()> {
        let name = match &pattern.kind {
            PatternKind::Binding(name) => Some(name),
            PatternKind::Wildcard => None,
            _ => return self.unsupported(pattern.span, "this loop pattern"),
        };
        let end_t = end.map(|end| {
            let l = self.temp(t);
            self.assign(l, Rvalue::Use(end));
            l
        });
        let i = self.temp(t);
        self.assign(i, Rvalue::Use(start));
        let var = name.map(|n| self.user_local(n, t, pattern.id));
        let head = self.b.new_block();
        let body_bb = self.b.new_block();
        let step = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        let bool_t = self.tys().bool();
        match end_t {
            Some(end_t) => {
                let c = self.temp(bool_t);
                let cmp = if inclusive { BinOp::Le } else { BinOp::Lt };
                self.assign(
                    c,
                    Rvalue::BinaryOp(
                        cmp,
                        Operand::Copy(Place::local(i)),
                        Operand::Copy(Place::local(end_t)),
                    ),
                );
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: Operand::Copy(Place::local(c)),
                        targets: SwitchTargets::if_else(body_bb, exit),
                    },
                    body_bb,
                );
            }
            None => {
                self.goto(body_bb);
                self.cur = body_bb;
            }
        }
        // The body sees a copy of the counter, so assigning to the loop
        // variable inside it cannot change the iteration.
        if let Some(v) = var {
            self.assign(v, Rvalue::Use(Operand::Copy(Place::local(i))));
        }
        self.loop_body(label, body, step, exit, None)?;
        self.cur = step;
        // `a..=b` stops at `b` before stepping, since `b` may be the type's
        // largest value (`250u8..=255u8`).
        if let (true, Some(end_t)) = (inclusive, end_t) {
            let last = self.temp(bool_t);
            self.assign(
                last,
                Rvalue::BinaryOp(
                    BinOp::Eq,
                    Operand::Copy(Place::local(i)),
                    Operand::Copy(Place::local(end_t)),
                ),
            );
            let bump = self.b.new_block();
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(last)),
                    targets: SwitchTargets::if_else(exit, bump),
                },
                bump,
            );
        }
        let one = Operand::Const(Const {
            ty: t,
            kind: ConstKind::Scalar(1),
        });
        self.assign(
            i,
            Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(i)), one),
        );
        self.goto(head);
        self.cur = exit;
        Ok(())
    }

    /// `for x in v` over a `Vec`. A borrowed collection (`v`, `v.iter()`,
    /// `v.iter_mut()`, or a `ref Vec`) yields references to its elements by
    /// index. `v.into_iter()` moves the collection into the loop, which
    /// gives up its elements front to front; what a `break` leaves behind
    /// drops with it at the loop's end.
    fn for_collection(
        &mut self,
        e: &'a Expr,
        label: &Option<String>,
        pattern: &'a Pattern,
        iterable: &'a Expr,
        body: &'a Block,
        dest: Place,
    ) -> R<()> {
        // `c.into_iter()` over a library collection loops below, by
        // position, so a borrowed `c` lends its elements (the library's
        // `VecIntoIter` is for an iterator value).
        // (Looked for under an `enumerate()`, which the loop below peels.)
        let under = match (&iterable.kind, &pattern.kind) {
            (
                ExprKind::MethodCall {
                    object,
                    method,
                    args,
                    ..
                },
                PatternKind::Tuple(ps),
            ) if method == "enumerate" && args.is_empty() && ps.len() == 2 => &**object,
            _ => iterable,
        };
        let into_iter = match &under.kind {
            ExprKind::MethodCall {
                object,
                method,
                args,
                ..
            } if method == "into_iter" && args.is_empty() => {
                let ot = self.expr_ty(object)?;
                let (kind, t) = self.strip_ty_full(ot);
                match kind {
                    // An owned set, map or deque of non-`Copy` elements
                    // moves them out through the library's `into_iter`
                    // (B-2026-10-13-14); one of `Copy` elements is read in
                    // place below.
                    HK::Intrinsic { kind, args }
                        if kind != IntrinsicKind::Vec
                            && t == ot
                            && !crate::mir::ty::table_args(kind, self.tys().tcx().list(args))
                                .into_iter()
                                .all(|a| self.is_copy(a)) =>
                    {
                        false
                    }
                    HK::Intrinsic { .. } => true,
                    _ => false,
                }
            }
            _ => false,
        };
        // `v.iter()` and `v.iter_mut()` over a `Vec` are library `VecIter`s
        // whose `next` reads by position; the loop below reads `v` by
        // position itself, in the same order, without a call per element.
        let vec_walk = match &under.kind {
            ExprKind::MethodCall {
                object,
                method,
                args,
                ..
            } if args.is_empty() && matches!(method.as_str(), "iter" | "iter_mut") => {
                let ot = self.expr_ty(object)?;
                matches!(
                    self.strip_ty_full(ot).0,
                    HK::Intrinsic {
                        kind: IntrinsicKind::Vec,
                        ..
                    }
                )
            }
            _ => false,
        };
        // An `Iterator` implementation in source, the library's adaptors
        // included (`it.skip(2).enumerate()`), loops through its own `next`.
        if !into_iter && !vec_walk {
            if let Some(next) = self.dyn_iterator_next(iterable)? {
                return self.for_iterator(label, pattern, iterable, next, body, dest);
            }
            if let Some(next) = self.iterator_next(iterable)? {
                return self.for_iterator(label, pattern, iterable, next, body, dest);
            }
            if let Some(next) = self.native_next(iterable)? {
                return self.for_iterator(label, pattern, iterable, next, body, dest);
            }
        }
        // `for (i, x) in c.iter().enumerate()`: the loop over `c`, with `i`
        // bound to the position.
        let (iterable, idx, pattern) = match (&iterable.kind, &pattern.kind) {
            (
                ExprKind::MethodCall {
                    object,
                    method,
                    args,
                    ..
                },
                PatternKind::Tuple(ps),
            ) if method == "enumerate" && args.is_empty() && ps.len() == 2 => {
                (&**object, Some(&ps[0]), &ps[1])
            }
            _ => (iterable, None, pattern),
        };
        if let Some(text) = self.chars_of(iterable)? {
            if idx.is_some() {
                return self.unsupported(e.span, "`enumerate` over chars");
            }
            return self.for_chars(label, pattern, body, text, dest);
        }
        #[derive(PartialEq, Clone, Copy)]
        enum Mode {
            Ref,
            Mut,
            Owned,
        }
        let (src, mut mode) = match &iterable.kind {
            ExprKind::MethodCall {
                object,
                method,
                args,
                ..
            } if args.is_empty()
                && matches!(method.as_str(), "iter" | "iter_mut" | "into_iter") =>
            {
                let m = match method.as_str() {
                    "iter" => Mode::Ref,
                    "iter_mut" => Mode::Mut,
                    _ => Mode::Owned,
                };
                (&**object, m)
            }
            // A bare `for x in c` borrows `c` (core semantics §5,
            // "`for x in c` borrows `c` through `Iterable`"); only
            // `c.into_iter()` moves it.
            _ => (iterable, Mode::Ref),
        };
        let st = self.expr_ty(src)?;
        let (coll, src_is_ref) = match self.tys().tcx().kind(st) {
            HK::Ref(t) => {
                if mode == Mode::Owned {
                    mode = Mode::Ref;
                }
                (t, true)
            }
            HK::MutRef(t) => {
                if mode == Mode::Owned {
                    mode = Mode::Mut;
                }
                (t, true)
            }
            _ => (st, false),
        };
        let elem = match self.tys().tcx().kind(coll) {
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            } => self.tys().tcx().list(args)[0],
            // The other library collections are read by position, through
            // the same `len` and `index`, in the collection's own order. A
            // map's element is its `(key, value)` entry.
            HK::Intrinsic {
                kind:
                    kind @ (IntrinsicKind::Set
                    | IntrinsicKind::SortedSet
                    | IntrinsicKind::VecDeque
                    | IntrinsicKind::Map
                    | IntrinsicKind::SortedMap),
                args,
            } if mode == Mode::Ref
                // `iter_mut` lends each element (a map's value) in place
                // (B-2026-10-21-25); a set's elements are its keys.
                || (mode == Mode::Mut
                    && !matches!(kind, IntrinsicKind::Set | IntrinsicKind::SortedSet))
                || (mode == Mode::Owned
                    && crate::mir::ty::table_args(kind, self.tys().tcx().list(args))
                        .into_iter()
                        .all(|t| self.is_copy(t))) =>
            {
                // `c.into_iter()` over `Copy` elements reads them as a lent
                // loop does; the collection goes when its scope ends.
                if mode == Mode::Owned {
                    mode = Mode::Ref;
                }
                let tcx = self.tys().tcx();
                let args = crate::mir::ty::table_args(kind, tcx.list(args));
                match kind {
                    IntrinsicKind::Map | IntrinsicKind::SortedMap => {
                        tcx.intern(HK::Tuple(tcx.intern_list(&args)))
                    }
                    _ => args[0],
                }
            }
            // A slice is a view: its loop reads the elements in place.
            HK::Slice { elem, mutable } => {
                if mode == Mode::Owned {
                    mode = if mutable { Mode::Mut } else { Mode::Ref };
                }
                elem
            }
            HK::Array {
                elem,
                len: crate::ty::ArrayLen::Known(n),
            } => {
                let how = match mode {
                    Mode::Owned | Mode::Ref if self.is_copy(elem) => None,
                    Mode::Owned => {
                        return self.unsupported(e.span, "a `for` loop that moves out of an array")
                    }
                    Mode::Ref => Some(false),
                    Mode::Mut => Some(true),
                };
                return self.for_array(
                    label,
                    (idx, pattern),
                    body,
                    src,
                    src_is_ref,
                    how,
                    (elem, n),
                    dest,
                );
            }
            // A type with an `Iterable` impl is borrowed through its
            // `iter` (design.md § `Iterator` and `Iterable`).
            HK::Adt { .. } if mode == Mode::Ref && idx.is_none() => {
                if let Some(iter) = self.iterable_iter(coll, e.span)? {
                    return self.for_iterable(label, pattern, src, src_is_ref, iter, body, dest);
                }
                return self.unsupported(e.span, "a `for` loop over a collection");
            }
            _ => return self.unsupported(e.span, "a `for` loop over a collection"),
        };
        if src_is_ref && mode == Mode::Owned {
            return self.unsupported(e.span, "a `for` loop that moves out of a borrow");
        }
        let coll_name = self.tys().display(coll);
        // A `Vec` is read by `index` with a `usize`; the other collections
        // by `entry_at` with an `i64` (`Map.index` is the key lookup).
        let by_entry = self.by_entry(coll);
        let (usize_t, bool_t, ref_coll, mut_coll, elem_ref) = {
            let tcx = self.tys().tcx();
            (
                if by_entry {
                    tcx.intern(HK::Int(IntSize::I64))
                } else {
                    tcx.intern(HK::UInt(UIntSize::Usize))
                },
                tcx.intern(HK::Bool),
                tcx.reference(coll, false),
                tcx.reference(coll, true),
                tcx.reference(elem, mode == Mode::Mut),
            )
        };
        let usize_const = |v: u128| {
            Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(v),
            })
        };
        // The loop's scope holds the collection (or the borrow of it).
        self.push_scope();
        let handle = match mode {
            // Taken from the back, which moves nothing up: reversed first,
            // so the elements still come front to back.
            Mode::Owned => {
                let v = self.temp_of(src, coll)?;
                let native = format!("{coll_name}.reverse");
                self.reverse_vec(v, mut_coll, &native);
                if self.needs_drop(elem) {
                    self.schedule(ScopeEntry::Unreverse(v, mut_coll, native));
                }
                v
            }
            Mode::Ref | Mode::Mut => {
                let mutable = mode == Mode::Mut;
                let ht = if mutable { mut_coll } else { ref_coll };
                let l = self.temp(ht);
                if src_is_ref {
                    let p = self.expr_place(src, mutable)?.project(ProjElem::Deref);
                    let kind = if mutable {
                        BorrowKind::Mut
                    } else {
                        BorrowKind::Shared
                    };
                    self.assign(l, Rvalue::Ref(kind, p));
                } else {
                    let p = self.expr_place(src, mutable)?;
                    let kind = if mutable {
                        BorrowKind::Mut
                    } else {
                        BorrowKind::Shared
                    };
                    self.assign(l, Rvalue::Ref(kind, p));
                }
                l
            }
        };
        let i = self.temp(usize_t);
        let n = self.temp(usize_t);
        self.assign(i, Rvalue::Use(usize_const(0)));
        if mode != Mode::Owned {
            let r = self.temp(ref_coll);
            let target = Place::local(handle).project(ProjElem::Deref);
            self.assign(r, Rvalue::Ref(BorrowKind::Shared, target));
            self.call_native(
                &format!("{coll_name}.len"),
                vec![Operand::Move(Place::local(r))],
                Place::local(n),
            );
        }
        let head = self.b.new_block();
        let body_bb = self.b.new_block();
        let step = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        if mode == Mode::Owned {
            // Owned: run while anything is left.
            let r = self.temp(ref_coll);
            self.assign(r, Rvalue::Ref(BorrowKind::Shared, Place::local(handle)));
            self.call_native(
                &format!("{coll_name}.len"),
                vec![Operand::Move(Place::local(r))],
                Place::local(n),
            );
        }
        let c = self.temp(bool_t);
        let (lhs, rhs) = if mode == Mode::Owned {
            (usize_const(0), Operand::Copy(Place::local(n)))
        } else {
            (
                Operand::Copy(Place::local(i)),
                Operand::Copy(Place::local(n)),
            )
        };
        self.assign(c, Rvalue::BinaryOp(BinOp::Lt, lhs, rhs));
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(body_bb, exit),
            },
            body_bb,
        );
        // A moved collection is taken from its (reversed) back, so its
        // count only numbers the rounds for `enumerate`.
        let continue_bb = step;
        self.loops.push(LoopCx {
            label: label.clone(),
            break_bb: exit,
            continue_bb,
            depth: self.scopes.len(),
            dest: None,
        });
        let r = self.for_collection_round(
            pattern,
            idx,
            body,
            (mode == Mode::Owned).then_some(n),
            mode == Mode::Mut,
            handle,
            i,
            (&coll_name, coll, elem, elem_ref),
        );
        self.loops.pop();
        r?;
        self.goto(continue_bb);
        self.cur = step;
        self.assign(
            i,
            Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(i)), usize_const(1)),
        );
        self.goto(head);
        self.cur = exit;
        self.pop_scope()?;
        self.assign(dest, Rvalue::Use(unit_const(self.unit())));
        Ok(())
    }

    /// `s` when `e` is `s.chars()` on a `String`. Until the library's
    /// iterators are written in Kāra, a `for` over it and its `.collect()`
    /// into a `Vec[char]` are lowered in place.
    fn chars_of(&mut self, e: &'a Expr) -> R<Option<&'a Expr>> {
        let ExprKind::MethodCall {
            object,
            method,
            args,
            ..
        } = &e.kind
        else {
            // `for c in s` of a `String` walks its chars.
            let t = self.expr_ty(e)?;
            return Ok(matches!(self.strip_ty(t), HK::Str | HK::StaticStr).then_some(e));
        };
        if method != "chars" || !args.is_empty() {
            return Ok(None);
        }
        let t = self.expr_ty(object)?;
        Ok(matches!(self.strip_ty(t), HK::Str | HK::StaticStr).then_some(&**object))
    }

    /// Walk the chars of the `String` `text`: `each` runs once per char,
    /// in a scope of its own, with the char in a local. The loop borrows
    /// the string for its whole run and steps by each char's UTF-8 width,
    /// through the library's `String.char_at_byte(ref s, i)` and
    /// `char.len_utf8(c)`. `continue` goes to the loop head (`i` has
    /// already stepped).
    fn walk_chars(
        &mut self,
        label: &Option<String>,
        text: &'a Expr,
        each: &mut dyn FnMut(&mut Self, Local) -> R<()>,
    ) -> R<()> {
        let (i64_t, bool_t, char_t) = {
            let tcx = self.tys().tcx();
            (
                tcx.intern(HK::Int(IntSize::I64)),
                tcx.intern(HK::Bool),
                tcx.intern(HK::Char),
            )
        };
        let p = if self.is_place(text) {
            self.expr_place(text, false)?
        } else {
            self.temp_place(text)?
        };
        let (p, st) = self.strip_refs(p);
        let rt = self.tys().tcx().reference(st, false);
        let h = self.temp(rt);
        self.assign(h, Rvalue::Ref(BorrowKind::Shared, p));
        let reborrow = |this: &mut Self| {
            let r = this.temp(rt);
            let target = Place::local(h).project(ProjElem::Deref);
            this.assign(r, Rvalue::Ref(BorrowKind::Shared, target));
            Operand::Move(Place::local(r))
        };
        let n = self.temp(i64_t);
        let r = reborrow(self);
        self.call_native("String.len", vec![r], Place::local(n));
        let i = self.temp(i64_t);
        self.assign(
            i,
            Rvalue::Use(Operand::Const(Const {
                ty: i64_t,
                kind: ConstKind::Scalar(0),
            })),
        );
        let head = self.b.new_block();
        let body_bb = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        let c = self.temp(bool_t);
        self.assign(
            c,
            Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(Place::local(i)),
                Operand::Copy(Place::local(n)),
            ),
        );
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(body_bb, exit),
            },
            body_bb,
        );
        let ch = self.temp(char_t);
        let r = reborrow(self);
        self.call_native(
            "String.char_at_byte",
            vec![r, Operand::Copy(Place::local(i))],
            Place::local(ch),
        );
        let w = self.temp(i64_t);
        self.call_native(
            "char.len_utf8",
            vec![Operand::Copy(Place::local(ch))],
            Place::local(w),
        );
        self.assign(
            i,
            Rvalue::BinaryOp(
                BinOp::Add,
                Operand::Copy(Place::local(i)),
                Operand::Move(Place::local(w)),
            ),
        );
        self.loops.push(LoopCx {
            label: label.clone(),
            break_bb: exit,
            continue_bb: head,
            depth: self.scopes.len(),
            dest: None,
        });
        let r = (|| {
            self.push_scope();
            each(self, ch)?;
            self.pop_scope()
        })();
        self.loops.pop();
        r?;
        self.goto(head);
        self.cur = exit;
        Ok(())
    }

    /// `for c in s.chars() { body }`.
    fn for_chars(
        &mut self,
        label: &Option<String>,
        pattern: &'a Pattern,
        body: &'a Block,
        text: &'a Expr,
        dest: Place,
    ) -> R<()> {
        let char_t = self.tys().tcx().intern(HK::Char);
        self.push_scope();
        let r = self.walk_chars(label, text, &mut |this, ch| {
            let mut binds = Vec::new();
            this.bind_pattern(pattern, &Place::local(ch), char_t, false, &mut binds)?;
            for &(l, t) in &binds {
                this.declare(l, t);
            }
            this.for_body(body)
        });
        r?;
        self.pop_scope()?;
        self.assign(dest, Rvalue::Use(unit_const(self.unit())));
        Ok(())
    }

    /// `s.chars().collect()` into a `Vec[char]`: push each char.
    /// Whether the `collect()` call `e` builds a `Vec[char]`.
    fn collects_char_vec(&mut self, e: &'a Expr) -> R<bool> {
        let vt = self.expr_ty(e)?;
        let char_t = self.tys().tcx().intern(HK::Char);
        Ok(matches!(self.tys().tcx().kind(vt), HK::Intrinsic {
            kind: IntrinsicKind::Vec,
            args,
        } if self.tys().tcx().list(args)[0] == char_t))
    }

    fn collect_chars(&mut self, e: &'a Expr, text: &'a Expr, dest: Place) -> R<()> {
        let vt = self.expr_ty(e)?;
        let name = self.tys().display(vt);
        self.push_scope();
        let v = self.scoped_temp(vt);
        self.call_native(&format!("{name}.new"), vec![], Place::local(v));
        let mt = self.tys().tcx().reference(vt, true);
        let unit_t = self.unit();
        self.walk_chars(&None, text, &mut |this, ch| {
            let r = this.temp(mt);
            this.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(v)));
            let u = this.temp(unit_t);
            this.call_native(
                &format!("{name}.push"),
                vec![
                    Operand::Move(Place::local(r)),
                    Operand::Copy(Place::local(ch)),
                ],
                Place::local(u),
            );
            Ok(())
        })?;
        self.assign(dest, Rvalue::Use(Operand::Move(Place::local(v))));
        self.pop_scope()
    }

    /// `for x in a` over a fixed-size array, by position: `x` is a copy of
    /// each element (`how` is `None`, the elements are `Copy`) or a
    /// reference to it (`Some(mutable)`).
    #[allow(clippy::too_many_arguments)]
    fn for_array(
        &mut self,
        label: &Option<String>,
        (idx, pattern): (Option<&'a Pattern>, &'a Pattern),
        body: &'a Block,
        src: &'a Expr,
        src_is_ref: bool,
        how: Option<bool>,
        (elem, n): (Ty, u64),
        dest: Place,
    ) -> R<()> {
        let mutable = how == Some(true);
        let (usize_t, bool_t) = {
            let tcx = self.tys().tcx();
            (tcx.intern(HK::UInt(UIntSize::Usize)), tcx.intern(HK::Bool))
        };
        let usize_const = |v: u128| {
            Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(v),
            })
        };
        self.push_scope();
        let mut base = if self.is_place(src) {
            self.expr_place(src, mutable)?
        } else {
            self.temp_place(src)?
        };
        if src_is_ref {
            base = base.project(ProjElem::Deref);
        }
        let i = self.temp(usize_t);
        self.assign(i, Rvalue::Use(usize_const(0)));
        let head = self.b.new_block();
        let body_bb = self.b.new_block();
        let step = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        let c = self.temp(bool_t);
        self.assign(
            c,
            Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(Place::local(i)),
                usize_const(n as u128),
            ),
        );
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(body_bb, exit),
            },
            body_bb,
        );
        self.loops.push(LoopCx {
            label: label.clone(),
            break_bb: exit,
            continue_bb: step,
            depth: self.scopes.len(),
            dest: None,
        });
        let r = (|| {
            self.push_scope();
            let place = base.clone().project(ProjElem::Index(i));
            let mut binds = Vec::new();
            // `enumerate`'s position, at the type its pattern has.
            if let Some(ip) = idx.filter(|p| !matches!(p.kind, PatternKind::Wildcard)) {
                let it = self.node_ty(ip.id, ip.span)?;
                let v = self.temp(it);
                let at = Operand::Copy(Place::local(i));
                let rv = if it == usize_t {
                    Rvalue::Use(at)
                } else {
                    Rvalue::Cast(CastKind::IntToInt, at, it)
                };
                self.assign(v, rv);
                self.bind_pattern(ip, &Place::local(v), it, false, &mut binds)?;
            }
            match (how, &pattern.kind) {
                (Some(m), PatternKind::Binding(name)) => {
                    let rt = self.tys().tcx().reference(elem, m);
                    let x = self.user_local(name, rt, pattern.id);
                    let kind = if m {
                        BorrowKind::Mut
                    } else {
                        BorrowKind::Shared
                    };
                    self.assign(x, Rvalue::Ref(kind, place));
                    binds.push((x, rt));
                }
                _ => self.bind_pattern(pattern, &place, elem, how.is_some(), &mut binds)?,
            }
            for &(l, t) in &binds {
                self.declare(l, t);
            }
            self.for_body(body)?;
            self.pop_scope()
        })();
        self.loops.pop();
        r?;
        self.goto(step);
        self.cur = step;
        self.assign(
            i,
            Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(i)), usize_const(1)),
        );
        self.goto(head);
        self.cur = exit;
        self.pop_scope()?;
        self.assign(dest, Rvalue::Use(unit_const(self.unit())));
        Ok(())
    }

    /// Is `coll` a library collection read by `entry_at` (every one but
    /// `Vec` and slices, which use `index`)?
    fn by_entry(&self, coll: Ty) -> bool {
        matches!(
            self.tys().tcx().kind(coll),
            HK::Intrinsic { kind, .. } if kind != IntrinsicKind::Vec
        )
    }

    /// One round of [`Self::for_collection`]: take the element, bind the
    /// pattern to it, and run the body in its own scope.
    #[allow(clippy::too_many_arguments)]
    fn for_collection_round(
        &mut self,
        pattern: &'a Pattern,
        idx: Option<&'a Pattern>,
        body: &'a Block,
        owned: Option<Local>,
        mutable: bool,
        handle: Local,
        i: Local,
        (coll_name, coll, elem, elem_ref): (&str, Ty, Ty, Ty),
    ) -> R<()> {
        self.push_scope();
        let usize_t = self.b.local_ty(i);
        let (place, by_ref) = if let Some(n) = owned {
            // The last of the `n` left: the reversed `Vec`'s front.
            let x = self.scoped_temp(elem);
            let last = self.temp(usize_t);
            self.assign(
                last,
                Rvalue::BinaryOp(
                    BinOp::Sub,
                    Operand::Copy(Place::local(n)),
                    Operand::Const(Const {
                        ty: usize_t,
                        kind: ConstKind::Scalar(1),
                    }),
                ),
            );
            let mt = self.tys().tcx().reference(coll, true);
            let r = self.temp(mt);
            self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(handle)));
            self.call_native(
                &format!("{coll_name}.remove"),
                vec![
                    Operand::Move(Place::local(r)),
                    Operand::Copy(Place::local(last)),
                ],
                Place::local(x),
            );
            (Place::local(x), false)
        } else {
            let ht = self.b.local_ty(handle);
            let h = self.temp(ht);
            let kind = if mutable {
                BorrowKind::Mut
            } else {
                BorrowKind::Shared
            };
            self.assign(
                h,
                Rvalue::Ref(kind, Place::local(handle).project(ProjElem::Deref)),
            );
            let r = self.temp(elem_ref);
            let by_entry = self.by_entry(coll);
            let method = match (by_entry, mutable) {
                (true, _) => "entry_at",
                (false, true) => "index_mut",
                (false, false) => "index",
            };
            self.call_native(
                &format!("{coll_name}.{method}"),
                vec![
                    Operand::Move(Place::local(h)),
                    Operand::Copy(Place::local(i)),
                ],
                Place::local(r),
            );
            // An element that is itself a reference (`Vec[ref Node]`) is
            // what the native gives, a borrow of a borrow being the borrow,
            // so `r` holds the element and is not read through
            // (B-2026-10-14-11).
            if matches!(self.tys().tcx().kind(elem), HK::Ref(_) | HK::MutRef(_)) {
                (Place::local(r), true)
            } else {
                (Place::local(r).project(ProjElem::Deref), true)
            }
        };
        let mut binds = Vec::new();
        if let Some(ip) = idx {
            if !matches!(ip.kind, PatternKind::Wildcard) {
                let it = self.node_ty(ip.id, ip.span)?;
                let ut = self.b.local_ty(i);
                let v = self.temp(it);
                let at = Operand::Copy(Place::local(i));
                let rv = if it == ut {
                    Rvalue::Use(at)
                } else {
                    Rvalue::Cast(CastKind::IntToInt, at, it)
                };
                self.assign(v, rv);
                self.bind_pattern(ip, &Place::local(v), it, false, &mut binds)?;
            }
        }
        match &pattern.kind {
            // A shared reference to a `Copy` element reads the same as a
            // copy of it, which is what `x` holds.
            PatternKind::Binding(name) if by_ref && !mutable && self.is_copy(elem) => {
                let x = self.user_local(name, elem, pattern.id);
                self.assign(x, Rvalue::Use(Operand::Copy(place.clone())));
                binds.push((x, elem));
            }
            // `for x in v.iter()`: `x` is the reference itself.
            PatternKind::Binding(name) if by_ref => {
                let x = self.user_local(name, elem_ref, pattern.id);
                let r = Place::local(place.local);
                let op = if mutable {
                    Operand::Move(r)
                } else {
                    Operand::Copy(r)
                };
                self.assign(x, Rvalue::Use(op));
                binds.push((x, elem_ref));
            }
            _ => self.bind_pattern(pattern, &place, elem, by_ref, &mut binds)?,
        }
        for &(l, t) in &binds {
            self.declare(l, t);
        }
        self.for_body(body)?;
        self.pop_scope()
    }

    // ── exits ───────────────────────────────────────────────────────

    /// Where the function's value is as this body returns it, and its
    /// type: the return place, or in a `par` branch's task the payload of
    /// the task's exit variant (core semantics §11.7).
    fn fn_value_place(&self) -> (Place, Ty) {
        match self.par_exit {
            Some((t, xv)) => (
                Place::local(Local::RETURN_PLACE)
                    .project(ProjElem::Downcast(VariantIdx(xv)))
                    .field(0, t),
                t,
            ),
            None => (
                Place::local(Local::RETURN_PLACE),
                self.b.local_ty(Local::RETURN_PLACE),
            ),
        }
    }

    /// The return place holds the value: run every scope's exit sequence,
    /// with the `errdefer` bodies when the value is an error, and return.
    /// In a `par` branch's task that is when the branch leaves early with
    /// the function's error; a branch that ends with its own value runs
    /// none (core semantics §11.7).
    fn return_exit(&mut self) -> R<()> {
        for clause in self.ensures {
            self.contract_check(&clause.body, "ensures")?;
        }
        let has_errdefer = self
            .scopes
            .iter()
            .flatten()
            .any(|e| matches!(e, ScopeEntry::ErrDefer(..)));
        let (value, ret_ty) = self.fn_value_place();
        let err_variant = self.error_variant(ret_ty);
        match (has_errdefer, err_variant) {
            (true, Some(err)) => {
                let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
                let err_bb = self.b.new_block();
                let ok_bb = self.b.new_block();
                if let Some((_, xv)) = self.par_exit {
                    // Only the exit variant holds the function's value.
                    let d = self.temp(isize_t);
                    self.assign(d, Rvalue::Discriminant(Place::local(Local::RETURN_PLACE)));
                    let exit_bb = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::SwitchInt {
                            discr: Operand::Copy(Place::local(d)),
                            targets: SwitchTargets {
                                values: vec![(xv as u128, exit_bb)],
                                otherwise: ok_bb,
                            },
                        },
                        exit_bb,
                    );
                }
                let d = self.temp(isize_t);
                self.assign(d, Rvalue::Discriminant(value));
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: Operand::Copy(Place::local(d)),
                        targets: SwitchTargets {
                            values: vec![(err as u128, err_bb)],
                            otherwise: ok_bb,
                        },
                    },
                    err_bb,
                );
                self.exit_to(0, true)?;
                self.diverge(TerminatorKind::Return);
                self.cur = ok_bb;
                self.exit_to(0, false)?;
                self.diverge(TerminatorKind::Return);
            }
            _ => {
                self.exit_to(0, false)?;
                self.diverge(TerminatorKind::Return);
            }
        }
        Ok(())
    }

    /// The index of the error variant of a `Result` (or `None` of an
    /// `Option`), when `t` is one.
    fn error_variant(&self, t: Ty) -> Option<u32> {
        let (adt, _) = self.tys().tcx().adt_of(t)?;
        let err = match adt.name.as_str() {
            "Result" => "Err",
            "Option" => "None",
            _ => return None,
        };
        adt.variants
            .iter()
            .position(|v| v.name == err)
            .map(|i| i as u32)
    }

    /// `inner?`: the success payload, or return the error.
    fn question(&mut self, e: &'a Expr, inner: &'a Expr, dest: Place) -> R<()> {
        let mut it = self.expr_ty(inner)?;
        // A borrowed `Option` / `Result` (a D5 parameter) whose parts are
        // `Copy` or handles is read through the borrow, a counted copy.
        let mut through_ref = false;
        if let HK::Ref(t) = self.tys().tcx().kind(it) {
            if self.is_place(inner)
                && self.error_variant(t).is_some()
                && (self.is_copy(t) || self.is_handle_aggregate(t))
            {
                it = t;
                through_ref = true;
            }
        }
        let Some(err) = self.error_variant(it) else {
            return self.unsupported(e.span, "`?` on this type");
        };
        let ok = 1 - err;
        let p = if self.is_place(inner) {
            let p = self.expr_place(inner, false)?;
            let p = if through_ref {
                p.project(ProjElem::Deref)
            } else {
                p
            };
            if self.borrowed_place(&p) && (self.is_handle_aggregate(it) || self.is_handle(it)) {
                // Read out of a shared value or a borrow: a handle
                // aggregate is copied by counting (core semantics §6.1).
                let l = self.temp(it);
                self.count_copy(p, it, Place::local(l));
                self.schedule(ScopeEntry::Drop(Place::local(l)));
                Place::local(l)
            } else {
                p
            }
        } else {
            let l = self.temp_of(inner, it)?;
            Place::local(l)
        };
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let d = self.temp(isize_t);
        self.assign(d, Rvalue::Discriminant(p.clone()));
        let err_bb = self.b.new_block();
        let ok_bb = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(d)),
                targets: SwitchTargets {
                    values: vec![(err as u128, err_bb)],
                    otherwise: ok_bb,
                },
            },
            err_bb,
        );
        let traced = self.traces_question(e.span);
        if traced {
            let context = self.trace_context(inner, &p, it, err);
            self.error_trace("error_trace_push", e.span, context);
        }
        // Error path: rebuild the error in the return type.
        let ret_ty = self.fn_ret_ty();
        let ret = Place::local(Local::RETURN_PLACE);
        let fields: Vec<Ty> = match self.tys().tcx().adt_of(it) {
            Some((adt, _)) => (0..adt.variants[err as usize].fields.len() as u32)
                .filter_map(|f| self.tys().tcx().field_ty(it, Some(err), f))
                .collect(),
            None => Vec::new(),
        };
        let mut ops = Vec::new();
        let have = fields.first().copied();
        for (i, ft) in fields.into_iter().enumerate() {
            let fp = p
                .project(ProjElem::Downcast(VariantIdx(err)))
                .field(i as u32, ft);
            ops.push(self.use_place(fp, ft));
        }
        let Some(ret_err) = self.error_variant(ret_ty) else {
            return self.unsupported(e.span, "`?` in a function that returns no `Result`");
        };
        // An error of another type converts through the target's `From`.
        let want = self.tys().tcx().field_ty(ret_ty, Some(ret_err), 0);
        if let (Some(want), Some(have), 1) = (want, have, ops.len()) {
            if want != have && self.variant_from(want, have, &mut ops) {
                // Converted in place by the library's variant mapping.
            } else if want != have {
                let Some((d, iargs)) = self.user_from(want, have) else {
                    return self.unsupported(e.span, "`?` converting this error");
                };
                let name = self.lcx.instance(d, iargs.clone());
                let func = self.fn_operand(&name, d, iargs.clone());
                // Under D5 `from` borrows its source: pass a reference to
                // the payload and drop the payload after the call.
                let item = &self.lcx.fns[&d];
                let pt = self.callee_param_ty(&item.f.params[0], &iargs)?;
                let mut held = None;
                if matches!(self.tys().tcx().kind(pt), HK::Ref(i) if i == have) {
                    let h = self.temp(have);
                    self.assign(h, Rvalue::Use(ops.pop().expect("one payload")));
                    ops.push(self.ref_to(Place::local(h), have));
                    held = Some(h);
                }
                let t = self.temp(want);
                let next = self.b.new_block();
                self.goto_with(
                    TerminatorKind::Call {
                        func,
                        args: std::mem::take(&mut ops),
                        destination: Place::local(t),
                        target: Some(next),
                        unwind: UnwindAction::Abort,
                    },
                    next,
                );
                if let Some(h) = held.filter(|_| self.needs_drop(have)) {
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Drop {
                            place: Place::local(h),
                            target: next,
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                }
                ops.push(Operand::Move(Place::local(t)));
            }
        }
        let kind = self.adt_aggregate(ret_ty, ret_err);
        self.error_exit(ret, Rvalue::Aggregate(kind, ops))?;
        // Success path: move the payload out.
        self.cur = ok_bb;
        if traced {
            self.error_trace("error_trace_clear", e.span, None);
        }
        let Some(pt) = self.tys().tcx().field_ty(it, Some(ok), 0) else {
            self.assign(dest, Rvalue::Use(unit_const(self.unit())));
            return Ok(());
        };
        let fp = p.project(ProjElem::Downcast(VariantIdx(ok))).field(0, pt);
        let op = self.use_place(fp, pt);
        self.assign(dest, Rvalue::Use(op));
        Ok(())
    }

    // ── match ───────────────────────────────────────────────────────

    fn lower_match(
        &mut self,
        e: &'a Expr,
        scrutinee: &'a Expr,
        arms: &'a [ast::MatchArm],
        dest: Place,
    ) -> R<()> {
        // The scrutinee temporary lives as long as the whole match.
        self.push_scope();
        let parts = self.scrutinee_parts(scrutinee, arms)?;
        let (place, st, by_ref) = match &parts {
            // Not read: every arm tests and binds the parts.
            Some(_) => (Place::local(Local(0)), self.unit(), false),
            None => self.scrutinee(
                scrutinee,
                self.binds_mut_ref(arms.iter().map(|a| &a.pattern)),
            )?,
        };
        let join = self.b.new_block();
        for arm in arms {
            if let PatternKind::Or(alts) = &arm.pattern.kind {
                if arm.guard.is_none() && self.pattern_binds(&arm.pattern) {
                    self.or_arm(alts, &arm.body, &place, st, by_ref, join, dest.clone())?;
                    continue;
                }
            }
            let next = self.b.new_block();
            match &parts {
                Some(parts) => self.test_parts(&arm.pattern, parts, next)?,
                None => self.test_pattern(&arm.pattern, &place, st, next)?,
            }
            self.push_scope();
            let mut binds = Vec::new();
            // A guard reads the bindings by reference; the arm moves them
            // only once it is chosen (`docs/spikes/mir-types.md` §9.5).
            let guard_by_ref = arm.guard.is_some() && !by_ref;
            match &parts {
                Some(parts) => self.bind_parts(&arm.pattern, parts, guard_by_ref, &mut binds)?,
                None => {
                    self.bind_pattern(&arm.pattern, &place, st, by_ref || guard_by_ref, &mut binds)?
                }
            }
            for &(l, t) in &binds {
                self.declare(l, t);
            }
            if let Some(g) = &arm.guard {
                let c = self.expr_operand(g)?;
                let body_bb = self.b.new_block();
                let fail = self.b.new_block();
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: c,
                        targets: SwitchTargets::if_else(body_bb, fail),
                    },
                    fail,
                );
                // A failed guard leaves the arm's scope and tries the next.
                let entries = std::mem::take(self.scopes.last_mut().unwrap());
                self.exit_entries(&entries, false)?;
                *self.scopes.last_mut().unwrap() = entries;
                self.goto(next);
                self.cur = body_bb;
                if guard_by_ref {
                    let mut moved = Vec::new();
                    match &parts {
                        Some(parts) => self.bind_parts(&arm.pattern, parts, false, &mut moved)?,
                        None => self.bind_pattern(&arm.pattern, &place, st, false, &mut moved)?,
                    }
                    for &(l, t) in &moved {
                        self.declare(l, t);
                    }
                }
            }
            self.expr_into(&arm.body, dest.clone())?;
            self.pop_scope()?;
            self.goto(join);
            self.cur = next;
        }
        let _ = e;
        self.diverge(TerminatorKind::Abort {
            reason: AbortReason::UnreachableArm,
        });
        self.cur = join;
        self.pop_scope()
    }

    /// `test_pattern` for an arm of a match on parts (`scrutinee_parts`):
    /// a tuple pattern tests each part where it lies; `_` tests nothing.
    fn test_parts(&mut self, pat: &'a Pattern, parts: &[(Place, Ty)], fail: BasicBlock) -> R<()> {
        if let PatternKind::Tuple(ps) = &pat.kind {
            for (p, (place, t)) in ps.iter().zip(parts) {
                self.test_pattern(p, place, *t, fail)?;
            }
        }
        Ok(())
    }

    /// `bind_pattern` for an arm of a match on parts.
    fn bind_parts(
        &mut self,
        pat: &'a Pattern,
        parts: &[(Place, Ty)],
        by_ref: bool,
        out: &mut Vec<(Local, Ty)>,
    ) -> R<()> {
        if let PatternKind::Tuple(ps) = &pat.kind {
            for (p, (place, t)) in ps.iter().zip(parts) {
                self.bind_pattern(p, place, *t, by_ref, out)?;
            }
        }
        Ok(())
    }

    /// A `match` arm `A(x) | B(x) => body`: each alternative is tested in
    /// turn and binds its own locals, which move into the first
    /// alternative's; the body reads those. Leaves `self.cur` at the next
    /// arm's test.
    #[allow(clippy::too_many_arguments)]
    fn or_arm(
        &mut self,
        alts: &'a [Pattern],
        body: &'a Expr,
        place: &Place,
        st: Ty,
        by_ref: bool,
        join: BasicBlock,
        dest: Place,
    ) -> R<()> {
        let body_bb = self.b.new_block();
        let next = self.b.new_block();
        self.push_scope();
        let mut canon: Vec<(String, Local, Ty)> = Vec::new();
        for (i, alt) in alts.iter().enumerate() {
            let fail = if i + 1 == alts.len() {
                next
            } else {
                self.b.new_block()
            };
            self.test_pattern(alt, place, st, fail)?;
            let mut binds = Vec::new();
            self.bind_pattern(alt, place, st, by_ref, &mut binds)?;
            for (l, t) in binds {
                let Some((name, node)) = self.b.user_name(l) else {
                    continue;
                };
                let c = match canon.iter().find(|(n, ..)| *n == name) {
                    Some(&(_, c, _)) => {
                        let op = self.use_place(Place::local(l), t);
                        self.assign(c, Rvalue::Use(op));
                        c
                    }
                    None => {
                        canon.push((name.clone(), l, t));
                        l
                    }
                };
                // The body's uses of `name` resolve to one alternative's
                // binding: every alternative's names the shared local.
                if let Some(&sym) = self.lcx.binding_syms.get(&(node, name)) {
                    self.locals.insert(sym, c);
                }
            }
            self.goto(body_bb);
            self.cur = fail;
        }
        self.cur = body_bb;
        for &(_, l, t) in &canon {
            self.declare(l, t);
        }
        self.expr_into(body, dest)?;
        self.pop_scope()?;
        self.goto(join);
        self.cur = next;
        Ok(())
    }

    /// The place a `match` or `if let` reads its scrutinee from (a temporary
    /// in the current scope unless it names a local's place), seen through
    /// any reference: the place, its type, and whether it binds by
    /// reference.
    /// Whether any of `pats` binds a `mut ref name` (core semantics §4.6).
    fn binds_mut_ref<'p>(&self, pats: impl IntoIterator<Item = &'p Pattern>) -> bool {
        pats.into_iter().any(|p| {
            p.binding_name_spans()
                .iter()
                .any(|(_, s)| self.lcx.mut_ref_bindings.contains(&SpanKey::from_span(s)))
        })
    }

    /// The place a pattern is matched against. `mutable` when a pattern
    /// binds a `mut ref` into it (`match v[i] { mut ref p => .. }`), so a
    /// place is reached for writing and reborrowed mutably
    /// (B-2026-10-15-13).
    fn scrutinee(&mut self, scrutinee: &'a Expr, mutable: bool) -> R<(Place, Ty, bool)> {
        let st = self.expr_ty(scrutinee)?;
        // An element (`v[i]`) is matched where it lies, as a local is: a
        // binding then copies, counts or borrows it out of the collection.
        fn element(e: &Expr) -> bool {
            match &e.kind {
                ExprKind::Index { .. } => true,
                ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
                    element(object)
                }
                _ => false,
            }
        }
        let element = element(scrutinee) || self.through_a_reference(scrutinee);
        let place = if self.is_place(scrutinee) && (element || self.is_local_rooted(scrutinee)) {
            self.expr_place(scrutinee, mutable)?
        } else {
            let l = self.temp_of(scrutinee, st)?;
            Place::local(l)
        };
        // Matching through a reference binds by reference.
        Ok(match self.tys().tcx().kind(st) {
            HK::Ref(inner) | HK::MutRef(inner) => (place.project(ProjElem::Deref), inner, true),
            // A place reached through a reference or handle (`self.label`
            // in a `ref self` method, `v[i]`) is a `ref` scrutinee too
            // (core semantics §4.6): matched through a shared reborrow, so
            // its bindings are `ref`s. A field reached only through
            // `mut ref`s (`it.value` with `it: mut ref Item`) is writable,
            // so it is reborrowed mutably and a non-`Copy` part binds a
            // `mut ref`, as matching on `it` itself does (B-2026-10-18-41).
            _ if place.projection.iter().any(|p| {
                matches!(
                    p,
                    ProjElem::Deref | ProjElem::Index(_) | ProjElem::ConstIndex(_)
                )
            }) =>
            {
                let writable = !mutable && self.only_through_mut_refs(&place);
                let mutable = mutable || writable;
                let rt = self.tys().tcx().reference(st, mutable);
                let r = self.temp(rt);
                if writable {
                    self.writable_reborrows.insert(r);
                }
                let kind = if mutable {
                    BorrowKind::Mut
                } else {
                    BorrowKind::Shared
                };
                self.assign(r, Rvalue::Ref(kind, place));
                (Place::local(r).project(ProjElem::Deref), st, true)
            }
            _ => (place, st, false),
        })
    }

    /// The parts of `match (a, b, ..)` over locals' places (a `ref` one seen
    /// through), when the arms only test them and copy `Copy` values out:
    /// each part is then matched where it lies, and no tuple is built, which
    /// would count every handle into it and release it after the match
    /// (B-2026-10-24-11). A part is `Copy` or a handle (which the tuple only
    /// counted, never moved), and a guard is plain operators over names, so
    /// nothing changes a part between the tests that read it.
    fn scrutinee_parts(
        &mut self,
        scrutinee: &'a Expr,
        arms: &'a [ast::MatchArm],
    ) -> R<Option<Vec<(Place, Ty)>>> {
        let ExprKind::Tuple(elems) = &scrutinee.kind else {
            return Ok(None);
        };
        let st = self.expr_ty(scrutinee)?;
        let mut tys = Vec::with_capacity(elems.len());
        for (i, el) in elems.iter().enumerate() {
            let Some(ft) = self.tys().field_ty(st, None, i as u32) else {
                return Ok(None);
            };
            let handle = matches!(self.tys().tcx().kind(ft), HK::Shared { .. });
            if !(self.is_place(el) && self.is_local_rooted(el) && (handle || self.is_copy(ft))) {
                return Ok(None);
            }
            tys.push(ft);
        }
        for arm in arms {
            let parts_ok = match &arm.pattern.kind {
                PatternKind::Wildcard => true,
                PatternKind::Tuple(ps) => {
                    ps.len() == tys.len()
                        && ps.iter().zip(&tys).all(|(p, &t)| self.copies_only(p, t))
                }
                _ => false,
            };
            if !parts_ok || !arm.guard.as_ref().is_none_or(plain_guard) {
                return Ok(None);
            }
        }
        let mut parts = Vec::with_capacity(elems.len());
        for (el, ft) in elems.iter().zip(tys) {
            let et = self.expr_ty(el)?;
            let place = self.expr_place(el, false)?;
            parts.push(match self.tys().tcx().kind(et) {
                _ if et == ft => (place, ft),
                HK::Ref(inner) | HK::MutRef(inner) if inner == ft => {
                    (place.project(ProjElem::Deref), ft)
                }
                _ => return Ok(None),
            });
        }
        return Ok(Some(parts));

        /// Names, literals, fields and operators: nothing that writes.
        fn plain_guard(e: &Expr) -> bool {
            match &e.kind {
                ExprKind::Identifier(_)
                | ExprKind::Integer(..)
                | ExprKind::Float(..)
                | ExprKind::CharLit(_)
                | ExprKind::ByteLit(_)
                | ExprKind::Bool(_) => true,
                ExprKind::Binary { left, right, .. } => plain_guard(left) && plain_guard(right),
                ExprKind::Unary { operand, .. } => plain_guard(operand),
                ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
                    plain_guard(object)
                }
                _ => false,
            }
        }
    }

    /// Whether `pat`, matched against a `t`, binds only `Copy` values by
    /// copy: no binding of a part that is not `Copy`, and no `ref` or
    /// `mut ref` binding, so no binding holds on to the scrutinee.
    fn copies_only(&mut self, pat: &Pattern, t: Ty) -> bool {
        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            if self.destructures(pat) {
                return self.copies_only(pat, inner);
            }
        }
        let by_name = |s: &Self, span| {
            let k = SpanKey::from_span(span);
            !s.lcx.ref_bindings.contains(&k) && !s.lcx.mut_ref_bindings.contains(&k)
        };
        match &pat.kind {
            PatternKind::Wildcard | PatternKind::Literal(_) | PatternKind::RangePattern { .. } => {
                true
            }
            PatternKind::Binding(_) => {
                matches!(self.lcx.res.get(&pat.id), Some(Res::Def(_)))
                    || (self.is_copy(t) && by_name(self, &pat.span))
            }
            PatternKind::AtBinding {
                pattern, by_ref, ..
            } => {
                !*by_ref
                    && self.is_copy(t)
                    && by_name(self, &pat.span)
                    && self.copies_only(pattern, t)
            }
            PatternKind::Tuple(ps) => ps.iter().enumerate().all(|(i, p)| {
                self.tys()
                    .field_ty(t, None, i as u32)
                    .is_some_and(|ft| self.copies_only(p, ft))
            }),
            PatternKind::TupleVariant { patterns, .. } => {
                let Some(&Res::Def(d)) = self.lcx.res.get(&pat.id) else {
                    return false;
                };
                let Some(idx) = self.variant_at(d, t) else {
                    return false;
                };
                patterns.iter().enumerate().all(|(i, p)| {
                    self.tys()
                        .tcx()
                        .field_ty(t, Some(idx), i as u32)
                        .is_some_and(|ft| self.copies_only(p, ft))
                })
            }
            PatternKind::Struct { fields, .. } => {
                let variant = match self.lcx.res.get(&pat.id) {
                    Some(&Res::Def(d)) => self.variant_at(d, t),
                    _ => None,
                };
                fields.iter().all(|fp| {
                    let Some((_, ft)) = self.field_of(t, variant, &fp.name) else {
                        return false;
                    };
                    match &fp.pattern {
                        Some(p) => self.copies_only(p, ft),
                        None => self.is_copy(ft),
                    }
                })
            }
            PatternKind::Or(_) => !self.pattern_binds(pat),
            _ => false,
        }
    }

    /// Whether `e` is a field (or tuple part) reached through a value that
    /// is a reference: `first(xs).v`, `m.get(k).unwrap().v`. It is matched
    /// where it lies, through that reference (B-2026-10-14-56).
    fn through_a_reference(&self, e: &'a Expr) -> bool {
        match &e.kind {
            ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
                let by_ref = self.lcx.node_types.get(&object.id).is_some_and(|&t| {
                    matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_))
                });
                by_ref || self.through_a_reference(object)
            }
            _ => false,
        }
    }

    /// `if let pattern = value { then } else { .. }`: a two-arm match.
    fn if_let(
        &mut self,
        pattern: &'a Pattern,
        value: &'a Expr,
        then_block: &'a Block,
        else_branch: Option<&'a Expr>,
        dest: Place,
    ) -> R<()> {
        self.push_scope();
        let (place, st, by_ref) = self.scrutinee(value, self.binds_mut_ref([pattern]))?;
        let else_bb = self.b.new_block();
        let join = self.b.new_block();
        self.test_pattern(pattern, &place, st, else_bb)?;
        self.push_scope();
        let mut binds = Vec::new();
        self.bind_pattern(pattern, &place, st, by_ref, &mut binds)?;
        for &(l, t) in &binds {
            self.declare(l, t);
        }
        self.block_into(then_block, dest.clone())?;
        self.pop_scope()?;
        self.goto(join);
        self.cur = else_bb;
        match else_branch {
            Some(els) => {
                self.push_scope();
                self.expr_into(els, dest)?;
                self.pop_scope()?;
            }
            None => self.assign(dest, Rvalue::Use(unit_const(self.unit()))),
        }
        self.goto(join);
        self.cur = join;
        self.pop_scope()
    }

    /// The `next` method of `iterable`'s type, instantiated, when the type
    /// is a program or library type that implements it: what a `for` loop
    /// over an `Iterator` calls. `None` for every other type, and for a
    /// library collection, whose loop reads it by position.
    fn iterator_next(&mut self, iterable: &'a Expr) -> R<Option<NextFn>> {
        // A type the builder cannot spell (the checker's opaque
        // `Iterator[T]` of `v.iter()`) is not an `Iterator` implementation;
        // the caller's own paths take it, so its refusal is not recorded.
        let before = self.errors.len();
        let Ok(t) = self.expr_ty(iterable) else {
            self.errors.truncate(before);
            return Ok(None);
        };
        self.iterator_next_of(t, iterable.span)
    }

    /// [`Self::iterator_next`] for a value of type `t`.
    fn iterator_next_of(&mut self, t: Ty, span: Span) -> R<Option<NextFn>> {
        let tcx = self.tys().tcx();
        let HK::Adt { def, args } = tcx.kind(t) else {
            return Ok(None);
        };
        let args = tcx.list(args).to_vec();
        let Some(cands) = self.lcx.defs.methods.get(&def).and_then(|m| m.get("next")) else {
            return Ok(None);
        };
        let Some(d) = cands.iter().copied().find(|d| self.lcx.fns.contains_key(d)) else {
            return Ok(None);
        };
        let info = &self.lcx.fns[&d];
        let f = info.f;
        let Some(args) = info.impl_args(&args) else {
            return Ok(None);
        };
        if !f.params.is_empty()
            || f.self_param != Some(SelfParam::MutRef)
            || f.generic_params
                .as_ref()
                .is_some_and(|g| !g.params.is_empty())
        {
            return Ok(None);
        }
        let ret = match self.lcx.fn_return(d, &args) {
            Ok(r) => r,
            Err(err) => return self.unsupported(span, &err),
        };
        let name = self.lcx.instance(d, args.clone());
        Ok(Some((d, args, name, ret)))
    }

    /// The library's line iterators, `LinesIter` (`BufReader.lines()`,
    /// docs/library/io.md § Buffered I/O) and `StdinLines`
    /// (`stdin.lines()`): `next` is the native `LinesIter.next` /
    /// `StdinLines.next`, typed by its `#[compiler_builtin]` signature.
    fn native_next(&mut self, iterable: &'a Expr) -> R<Option<NextFn>> {
        let before = self.errors.len();
        let Ok(t) = self.expr_ty(iterable) else {
            self.errors.truncate(before);
            return Ok(None);
        };
        let tcx = self.tys().tcx();
        let HK::Adt { def, .. } = tcx.kind(t) else {
            return Ok(None);
        };
        let Some(iter) = tcx
            .adt_of(t)
            .map(|(a, _)| a.name.clone())
            .filter(|n| matches!(&**n, "LinesIter" | "StdinLines"))
        else {
            return Ok(None);
        };
        if !self
            .lcx
            .defs
            .methods
            .get(&def)
            .is_some_and(|m| m.contains_key("next"))
        {
            return Ok(None);
        }
        let string = self.tys().tcx().intern(HK::Str);
        let ret = self
            .enum_of("IoError", &[])
            .and_then(|io| self.enum_of("Result", &[string, io]))
            .and_then(|r| self.option_of(r));
        let Some(ret) = ret else {
            return self.unsupported(iterable.span, "a line iterator without its library types");
        };
        Ok(Some((
            DefId(u32::MAX),
            Vec::new(),
            format!("{iter}.next"),
            ret,
        )))
    }

    /// The `iter` of `coll`'s `Iterable` impl, instanced for `coll`'s
    /// arguments, when it has one that borrows its receiver.
    fn iterable_iter(&mut self, coll: Ty, span: Span) -> R<Option<NextFn>> {
        let tcx = self.tys().tcx();
        let HK::Adt { def, args } = tcx.kind(coll) else {
            return Ok(None);
        };
        let args = tcx.list(args).to_vec();
        let Some(cands) = self.lcx.defs.methods.get(&def).and_then(|m| m.get("iter")) else {
            return Ok(None);
        };
        let Some(d) = cands.iter().copied().find(|&d| {
            let path = &self.lcx.defs.table.get(d).path.segments;
            self.lcx.fns.contains_key(&d)
                && path.len() >= 2
                && path[path.len() - 2].starts_with("impl Iterable#")
        }) else {
            return Ok(None);
        };
        let info = &self.lcx.fns[&d];
        let f = info.f;
        let Some(args) = info.impl_args(&args) else {
            return Ok(None);
        };
        if !f.params.is_empty() || f.self_param != Some(SelfParam::Ref) {
            return Ok(None);
        }
        let ret = match self.lcx.fn_return(d, &args) {
            Ok(r) => r,
            Err(err) => return self.unsupported(span, &err),
        };
        let name = self.lcx.instance(d, args.clone());
        Ok(Some((d, args, name, ret)))
    }

    /// `for pattern in c` over a type with an `Iterable` impl: the loop
    /// calls `c.iter()`, which borrows `c`, and consumes the iterator it
    /// returns as [`Self::for_iterator`] does.
    #[allow(clippy::too_many_arguments)]
    fn for_iterable(
        &mut self,
        label: &Option<String>,
        pattern: &'a Pattern,
        src: &'a Expr,
        src_is_ref: bool,
        (d, args, name, it_t): NextFn,
        body: &'a Block,
        dest: Place,
    ) -> R<()> {
        let Some(next) = self.iterator_next_of(it_t, src.span)? else {
            return self.unsupported(src.span, "an `Iterable` whose `iter` returns no `Iterator`");
        };
        let Some(some) = self
            .error_variant(next.3)
            .filter(|_| {
                self.tys()
                    .tcx()
                    .adt_of(next.3)
                    .is_some_and(|(a, _)| a.name == "Option")
            })
            .map(|none| 1 - none)
        else {
            return self.unsupported(src.span, "a `next` that returns no `Option`");
        };
        let Some(item_t) = self.tys().tcx().field_ty(next.3, Some(some), 0) else {
            return self.unsupported(src.span, "a `next` with no payload");
        };
        self.push_scope();
        let st = self.expr_ty(src)?;
        let coll = match self.tys().tcx().kind(st) {
            HK::Ref(t) | HK::MutRef(t) => t,
            _ => st,
        };
        let rt = self.tys().tcx().reference(coll, false);
        let r = self.temp(rt);
        let p = self.expr_place(src, false)?;
        let p = if src_is_ref {
            p.project(ProjElem::Deref)
        } else {
            p
        };
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
        let it = self.scoped_temp(it_t);
        let func = self.fn_operand(&name, d, args);
        let after = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: vec![Operand::Move(Place::local(r))],
                destination: Place::local(it),
                target: Some(after),
                unwind: UnwindAction::Abort,
            },
            after,
        );
        let head = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        self.loops.push(LoopCx {
            label: label.clone(),
            break_bb: exit,
            continue_bb: head,
            depth: self.scopes.len(),
            dest: None,
        });
        let r = self.for_iterator_round(pattern, it, next, some, item_t, body, head, exit);
        self.loops.pop();
        r?;
        self.cur = exit;
        self.pop_scope()?;
        self.assign(dest, Rvalue::Use(unit_const(self.unit())));
        Ok(())
    }

    /// `for pattern in it` over an `Iterator`: the loop owns `it` and calls
    /// its `next` until that returns `None`, binding each `Some` payload to
    /// `pattern`. `it` is dropped when the loop ends, however it ends.
    fn for_iterator(
        &mut self,
        label: &Option<String>,
        pattern: &'a Pattern,
        iterable: &'a Expr,
        (d, args, name, opt_t): NextFn,
        body: &'a Block,
        dest: Place,
    ) -> R<()> {
        let Some(some) = self
            .error_variant(opt_t)
            .filter(|_| {
                self.tys()
                    .tcx()
                    .adt_of(opt_t)
                    .is_some_and(|(a, _)| a.name == "Option")
            })
            .map(|none| 1 - none)
        else {
            return self.unsupported(iterable.span, "a `next` that returns no `Option`");
        };
        let Some(item_t) = self.tys().tcx().field_ty(opt_t, Some(some), 0) else {
            return self.unsupported(iterable.span, "a `next` with no payload");
        };
        let it_t = self.expr_ty(iterable)?;
        self.push_scope();
        let it = self.temp_of(iterable, it_t)?;
        let head = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        self.loops.push(LoopCx {
            label: label.clone(),
            break_bb: exit,
            continue_bb: head,
            depth: self.scopes.len(),
            dest: None,
        });
        let r = self.for_iterator_round(
            pattern,
            it,
            (d, args, name, opt_t),
            some,
            item_t,
            body,
            head,
            exit,
        );
        self.loops.pop();
        r?;
        self.cur = exit;
        self.pop_scope()?;
        self.assign(dest, Rvalue::Use(unit_const(self.unit())));
        Ok(())
    }

    /// One round of [`Self::for_iterator`], shaped like a `while let`
    /// round: `next`, then leave for `exit` on `None` or bind and run the
    /// body on `Some`.
    #[allow(clippy::too_many_arguments)]
    fn for_iterator_round(
        &mut self,
        pattern: &'a Pattern,
        it: Local,
        (d, args, name, opt_t): NextFn,
        some: u32,
        item_t: Ty,
        body: &'a Block,
        head: BasicBlock,
        exit: BasicBlock,
    ) -> R<()> {
        self.push_scope();
        let it_t = self.b.local_ty(it);
        let rt = self.tys().tcx().reference(it_t, true);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(it)));
        let opt = self.scoped_temp(opt_t);
        let func = self.dyn_next_func(&(d, args, name, opt_t));
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: vec![Operand::Move(Place::local(r))],
                destination: Place::local(opt),
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        let fail = self.b.new_block();
        self.switch_variant(&Place::local(opt), some, fail);
        let matched = self.cur;
        self.cur = fail;
        let entries = std::mem::take(self.scopes.last_mut().unwrap());
        let r = self.exit_entries(&entries, false);
        *self.scopes.last_mut().unwrap() = entries;
        r?;
        self.goto(exit);
        self.cur = matched;
        self.push_scope();
        let payload = Place::local(opt)
            .project(ProjElem::Downcast(VariantIdx(some)))
            .field(0, item_t);
        let mut binds = Vec::new();
        self.bind_pattern(pattern, &payload, item_t, false, &mut binds)?;
        for &(l, t) in &binds {
            self.declare(l, t);
        }
        self.for_body(body)?;
        self.pop_scope()?;
        self.pop_scope()?;
        self.goto(head);
        Ok(())
    }

    /// One round of `while let`: test the scrutinee, leaving for `exit` (its
    /// temporaries dropped) when the pattern fails, else run the body and
    /// go back to `head`.
    fn while_let_round(
        &mut self,
        pattern: &'a Pattern,
        value: &'a Expr,
        body: &'a Block,
        head: BasicBlock,
        exit: BasicBlock,
    ) -> R<()> {
        self.push_scope();
        let (place, st, by_ref) = self.scrutinee(value, self.binds_mut_ref([pattern]))?;
        let fail = self.b.new_block();
        self.test_pattern(pattern, &place, st, fail)?;
        let matched = self.cur;
        self.cur = fail;
        let entries = std::mem::take(self.scopes.last_mut().unwrap());
        let r = self.exit_entries(&entries, false);
        *self.scopes.last_mut().unwrap() = entries;
        r?;
        self.goto(exit);
        self.cur = matched;
        self.push_scope();
        let mut binds = Vec::new();
        self.bind_pattern(pattern, &place, st, by_ref, &mut binds)?;
        for &(l, t) in &binds {
            self.declare(l, t);
        }
        let t = self.unit();
        let tmp = self.temp(t);
        self.block_into(body, Place::local(tmp))?;
        self.pop_scope()?;
        self.pop_scope()?;
        self.goto(head);
        Ok(())
    }

    fn is_local_rooted(&self, e: &Expr) -> bool {
        match &e.kind {
            ExprKind::Identifier(_) => self.is_local(e),
            ExprKind::SelfValue => true,
            ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
                self.is_local_rooted(object)
            }
            _ => false,
        }
    }

    /// Branch to `fail` unless `place` (of type `t`) matches `pat`;
    /// continue in the current block when it does.
    fn test_pattern(&mut self, pat: &'a Pattern, place: &Place, t: Ty, fail: BasicBlock) -> R<()> {
        // A part that is a reference (`match (region, cat)` over two
        // `ref`s) is tested through it.
        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            if self.destructures(pat) {
                return self.test_pattern(pat, &place.project(ProjElem::Deref), inner, fail);
            }
        }
        match &pat.kind {
            PatternKind::Wildcard | PatternKind::Binding(_) => {
                // A bare name may be a unit variant (`None`).
                if let PatternKind::Binding(_) = &pat.kind {
                    if let Some(Res::Def(d)) = self.lcx.res.get(&pat.id) {
                        let d = *d;
                        return self.test_variant(pat, d, &[], place, t, fail);
                    }
                }
                Ok(())
            }
            PatternKind::Literal(LiteralPattern::String(text)) => {
                // `"USD" =>`: the library's `String.eq` against the constant.
                let r = match self.tys().tcx().kind(t) {
                    HK::Ref(_) | HK::MutRef(_) => Operand::Copy(place.clone()),
                    _ => self.ref_to(place.clone(), t),
                };
                let bool_t = self.tys().bool();
                let eq = self.temp(bool_t);
                self.call_native(
                    "String.eq",
                    vec![r, self.static_str(text)],
                    Place::local(eq),
                );
                let ok = self.b.new_block();
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: Operand::Move(Place::local(eq)),
                        targets: SwitchTargets::if_else(ok, fail),
                    },
                    ok,
                );
                Ok(())
            }
            // `-1.5 =>`: `==` against the constant at the scrutinee's
            // width, so `-0.0` matches `0.0` and a NaN matches nothing.
            PatternKind::Literal(LiteralPattern::Float(f, _)) => {
                let super::ty::TyKind::Float(ft) = self.tys().kind(t) else {
                    return self.unsupported(pat.span, "this literal pattern");
                };
                let bool_t = self.tys().bool();
                let eq = self.temp(bool_t);
                let c = Operand::Const(Const {
                    ty: t,
                    kind: ConstKind::Float(ft.round(*f).to_bits()),
                });
                self.assign(
                    eq,
                    Rvalue::BinaryOp(BinOp::Eq, Operand::Copy(place.clone()), c),
                );
                let ok = self.b.new_block();
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: Operand::Move(Place::local(eq)),
                        targets: SwitchTargets::if_else(ok, fail),
                    },
                    ok,
                );
                Ok(())
            }
            PatternKind::Literal(lit) => {
                let v = match lit {
                    // An arm's value is the scrutinee's bits, at its width
                    // (`u64::MAX`, not the 128-bit `-1` the literal widens
                    // to, B-2026-10-22-37).
                    LiteralPattern::Integer(v, _) => match self.tys().int_ty(t) {
                        Some(it) => {
                            let s = 128 - it.bits();
                            (*v as u128) << s >> s
                        }
                        None => *v as u128,
                    },
                    LiteralPattern::Char(c) => *c as u128,
                    LiteralPattern::Bool(b) => *b as u128,
                    _ => return self.unsupported(pat.span, "this literal pattern"),
                };
                let ok = self.b.new_block();
                let op = Operand::Copy(place.clone());
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: op,
                        targets: SwitchTargets {
                            values: vec![(v, ok)],
                            otherwise: fail,
                        },
                    },
                    ok,
                );
                Ok(())
            }
            PatternKind::Tuple(ps) => {
                for (i, p) in ps.iter().enumerate() {
                    let Some(ft) = self.tys().field_ty(t, None, i as u32) else {
                        return self.unsupported(p.span, "this tuple pattern");
                    };
                    self.test_pattern(p, &place.field(i as u32, ft), ft, fail)?;
                }
                Ok(())
            }
            PatternKind::TupleVariant { patterns, .. } => match self.lcx.res.get(&pat.id) {
                Some(Res::Def(d)) => {
                    let d = *d;
                    self.test_variant(pat, d, patterns, place, t, fail)
                }
                _ => self.unsupported(pat.span, "this variant pattern"),
            },
            PatternKind::Struct { fields, .. } => {
                let variant = match self.lcx.res.get(&pat.id) {
                    Some(&Res::Def(d)) => self.variant_at(d, t).map(|i| (d, i)),
                    _ => None,
                };
                let base = match variant {
                    Some((_, idx)) => {
                        self.switch_variant(place, idx, fail);
                        place.project(ProjElem::Downcast(VariantIdx(idx)))
                    }
                    None => place.clone(),
                };
                for fp in fields {
                    let Some((idx, ft)) = self.field_of(t, variant.map(|v| v.1), &fp.name) else {
                        return self.unsupported(fp.span, "this field pattern");
                    };
                    if let Some(p) = &fp.pattern {
                        self.test_pattern(p, &base.field(idx, ft), ft, fail)?;
                    }
                }
                Ok(())
            }
            // Each alternative in turn: the first that matches goes on.
            PatternKind::Or(alts) => {
                let ok = self.b.new_block();
                for (i, alt) in alts.iter().enumerate() {
                    let next = if i + 1 == alts.len() {
                        fail
                    } else {
                        self.b.new_block()
                    };
                    self.test_pattern(alt, place, t, next)?;
                    self.goto(ok);
                    self.cur = next;
                }
                self.cur = ok;
                Ok(())
            }
            PatternKind::AtBinding { pattern, .. } => self.test_pattern(pattern, place, t, fail),
            PatternKind::RangePattern {
                start,
                end,
                inclusive,
            } => {
                let lo = self.range_bound(start.as_ref(), t)?;
                let hi = self.range_bound(end.as_ref(), t)?;
                let (Some(lo), Some(hi)) = (lo, hi) else {
                    return self.unsupported(pat.span, "this range pattern bound");
                };
                let bool_t = self.tys().bool();
                let konst = |v: u128| {
                    Operand::Const(Const {
                        ty: t,
                        kind: ConstKind::Scalar(v),
                    })
                };
                let checks = [
                    lo.map(|v| (BinOp::Ge, v)),
                    hi.map(|v| (if *inclusive { BinOp::Le } else { BinOp::Lt }, v)),
                ];
                for (op, v) in checks.into_iter().flatten() {
                    let c = self.temp(bool_t);
                    self.assign(
                        c,
                        Rvalue::BinaryOp(op, Operand::Copy(place.clone()), konst(v)),
                    );
                    let ok = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::SwitchInt {
                            discr: Operand::Copy(Place::local(c)),
                            targets: SwitchTargets::if_else(ok, fail),
                        },
                        ok,
                    );
                }
                Ok(())
            }
            PatternKind::Slice {
                prefix,
                rest,
                suffix,
            } => {
                let Some((elem, known)) = self.seq_of(t) else {
                    return self.unsupported(pat.span, "a slice pattern on this type");
                };
                let (k, j) = (prefix.len() as u64, suffix.len() as u64);
                // An array's length is in its type, which the checker held
                // the pattern to; a view's is tested.
                if known.is_none() {
                    let n = self.seq_len(place, t);
                    let usize_t = self.tys().tcx().intern(HK::UInt(UIntSize::Usize));
                    let bool_t = self.tys().bool();
                    let op = if rest.is_some() { BinOp::Ge } else { BinOp::Eq };
                    let c = self.temp(bool_t);
                    self.assign(
                        c,
                        Rvalue::BinaryOp(
                            op,
                            Operand::Copy(Place::local(n)),
                            Operand::Const(Const {
                                ty: usize_t,
                                kind: ConstKind::Scalar((k + j) as u128),
                            }),
                        ),
                    );
                    let ok = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::SwitchInt {
                            discr: Operand::Copy(Place::local(c)),
                            targets: SwitchTargets::if_else(ok, fail),
                        },
                        ok,
                    );
                }
                for (i, p) in prefix.iter().enumerate() {
                    if self.destructures(p) {
                        let ep = self.seq_elem(place, t, SeqPos::Start(i as u64))?;
                        self.test_pattern(p, &ep, elem, fail)?;
                    }
                }
                for (i, p) in suffix.iter().enumerate() {
                    if self.destructures(p) {
                        let ep = self.seq_elem(place, t, SeqPos::End(j - i as u64))?;
                        self.test_pattern(p, &ep, elem, fail)?;
                    }
                }
                Ok(())
            }
        }
    }

    /// A range pattern's bound as the bits of a `t`: `Some(None)` when it
    /// is open, `None` when it is not a constant the builder can read. A
    /// named bound is a constant or an integer type's limit (design.md
    /// § Range patterns).
    fn range_bound(
        &mut self,
        b: Option<&'a crate::ast::RangeBound>,
        t: Ty,
    ) -> R<Option<Option<u128>>> {
        use crate::ast::RangeBound;
        let Some(b) = b else {
            return Ok(Some(None));
        };
        Ok(match b {
            RangeBound::Literal(LiteralPattern::Integer(v, _)) => Some(Some(*v as u128)),
            RangeBound::Literal(LiteralPattern::Char(c)) => Some(Some(*c as u128)),
            RangeBound::Literal(_) => None,
            RangeBound::Path { segments, .. } => match segments.as_slice() {
                [name] => {
                    let value = self
                        .lcx
                        .defs
                        .lookup(0, name)
                        .and_then(|d| self.lcx.consts.get(&d).copied());
                    match value {
                        Some(v) => match self.expr_operand(v)? {
                            Operand::Const(Const {
                                kind: ConstKind::Scalar(x),
                                ..
                            }) => Some(Some(x)),
                            _ => None,
                        },
                        None => None,
                    }
                }
                [_, _] => int_limit(self.tys().tcx().kind(t), &segments.join(".")).map(Some),
                _ => None,
            },
        })
    }

    /// The element type of a sequence a slice pattern matches, and its
    /// length when that is in the type (an array).
    fn seq_of(&self, t: Ty) -> Option<(Ty, Option<u64>)> {
        let tcx = self.tys().tcx();
        match tcx.kind(t) {
            HK::Array {
                elem,
                len: crate::ty::ArrayLen::Known(n),
            } => Some((elem, Some(n))),
            HK::Slice { elem, .. } => Some((elem, None)),
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            } => Some((tcx.list(args)[0], None)),
            _ => None,
        }
    }

    /// The length of the sequence at `place`, as a `usize` local.
    fn seq_len(&mut self, place: &Place, t: Ty) -> Local {
        let usize_t = self.tys().tcx().intern(HK::UInt(UIntSize::Usize));
        let n = self.temp(usize_t);
        if matches!(self.tys().tcx().kind(t), HK::Array { .. }) {
            self.assign(n, Rvalue::Len(place.clone()));
        } else {
            let r = self.ref_to(place.clone(), t);
            let name = self.tys().display(t);
            self.call_native(&format!("{name}.len"), vec![r], Place::local(n));
        }
        n
    }

    /// The place of one element of the sequence at `place`: an array's
    /// element itself, or a view's through the library's `index`, which
    /// lends it (design.md § Slice and array patterns: a pattern over a
    /// `Vec` or `Slice` sees a view).
    fn seq_elem(&mut self, place: &Place, t: Ty, pos: SeqPos) -> R<Place> {
        let Some((elem, known)) = self.seq_of(t) else {
            unreachable!("a sequence type")
        };
        if let Some(n) = known {
            let i = match pos {
                SeqPos::Start(i) => i,
                SeqPos::End(m) => n - m,
            };
            return Ok(place.project(ProjElem::ConstIndex(i)));
        }
        let usize_t = self.tys().tcx().intern(HK::UInt(UIntSize::Usize));
        let idx = match pos {
            SeqPos::Start(i) => Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(i as u128),
            }),
            SeqPos::End(m) => {
                let n = self.seq_len(place, t);
                let i = self.temp(usize_t);
                self.assign(
                    i,
                    Rvalue::BinaryOp(
                        BinOp::Sub,
                        Operand::Copy(Place::local(n)),
                        Operand::Const(Const {
                            ty: usize_t,
                            kind: ConstKind::Scalar(m as u128),
                        }),
                    ),
                );
                Operand::Copy(Place::local(i))
            }
        };
        let r = self.ref_to(place.clone(), t);
        let et = self.tys().tcx().reference(elem, false);
        let out = self.temp(et);
        let name = self.tys().display(t);
        self.call_native(&format!("{name}.index"), vec![r, idx], Place::local(out));
        Ok(Place::local(out).project(ProjElem::Deref))
    }

    /// The index of the variant `v` names in the enum `t`. A bare variant
    /// name that two enums share (`Str(n)`) may have resolved to the other
    /// one's; the scrutinee's enum decides, by name.
    fn variant_at(&mut self, v: DefId, t: Ty) -> Option<u32> {
        let found = self.lcx.variant(v);
        let def = match self.tys().tcx().kind(t) {
            HK::Adt { def, .. } | HK::Shared { def, .. } => def,
            _ => return found.map(|(_, idx)| idx),
        };
        match found {
            Some((e, idx)) if def == e => return Some(idx),
            Some(_) => {}
            // A struct (a struct pattern's path) has no variant, unless the
            // scrutinee is an enum with a variant by the struct's name: a
            // bare `Heading(n)` on a `Block` names the variant
            // (B-2026-10-15-35).
            None if self.lcx.defs.table.get(v).kind != DefKind::Variant && def == v => {
                return None;
            }
            None => {}
        }
        // A user variant named like a prelude one (`Err`) resolves to the
        // user's enum, which may not even be registered; the scrutinee's
        // enum decides, by name (B-2026-10-15-3).
        self.lcx.register_adt(def).ok()?;
        let name = self.lcx.def_name(v);
        let (adt, _) = self.tys().tcx().adt_of(t)?;
        adt.variants
            .iter()
            .position(|x| x.name == name.as_str())
            .map(|i| i as u32)
    }

    fn test_variant(
        &mut self,
        pat: &'a Pattern,
        v: DefId,
        subs: &'a [Pattern],
        place: &Place,
        t: Ty,
        fail: BasicBlock,
    ) -> R<()> {
        let Some(idx) = self.variant_at(v, t) else {
            return self.unsupported(pat.span, "this variant");
        };
        self.switch_variant(place, idx, fail);
        let base = place.project(ProjElem::Downcast(VariantIdx(idx)));
        for (i, p) in subs.iter().enumerate() {
            let Some(ft) = self.tys().tcx().field_ty(t, Some(idx), i as u32) else {
                return self.unsupported(p.span, "this payload pattern");
            };
            self.test_pattern(p, &base.field(i as u32, ft), ft, fail)?;
        }
        Ok(())
    }

    fn switch_variant(&mut self, place: &Place, idx: u32, fail: BasicBlock) {
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let d = self.temp(isize_t);
        self.assign(d, Rvalue::Discriminant(place.clone()));
        let ok = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(d)),
                targets: SwitchTargets {
                    values: vec![(idx as u128, ok)],
                    otherwise: fail,
                },
            },
            ok,
        );
    }

    /// Does `pat` bind a name (a unit variant written bare does not)?
    /// Whether `pat` looks inside the value it matches, rather than naming
    /// all of it (a binding or `_`) or comparing a string with it.
    fn destructures(&self, pat: &Pattern) -> bool {
        match &pat.kind {
            PatternKind::Wildcard | PatternKind::Literal(LiteralPattern::String(_)) => false,
            PatternKind::Binding(_) => matches!(self.lcx.res.get(&pat.id), Some(Res::Def(_))),
            _ => true,
        }
    }

    fn pattern_binds(&self, pat: &Pattern) -> bool {
        !pat.binding_names().is_empty()
    }

    /// Whether an irrefutable pattern binds only by `ref` or copies, so
    /// destructuring with it moves nothing out of the scrutinee.
    fn moves_nothing(&mut self, pat: &Pattern, t: Ty) -> bool {
        if let HK::Ref(_) | HK::MutRef(_) = self.tys().tcx().kind(t) {
            return true;
        }
        match &pat.kind {
            PatternKind::Wildcard | PatternKind::Literal(_) => true,
            PatternKind::Binding(_) => {
                self.is_copy(t)
                    || self
                        .lcx
                        .ref_bindings
                        .contains(&SpanKey::from_span(&pat.span))
            }
            PatternKind::Tuple(ps) => ps.iter().enumerate().all(|(i, p)| {
                self.tys()
                    .field_ty(t, None, i as u32)
                    .is_some_and(|ft| self.moves_nothing(p, ft))
            }),
            PatternKind::Struct { fields, .. } => fields.iter().all(|fp| {
                let Some((_, ft)) = self.field_of(t, None, &fp.name) else {
                    return false;
                };
                match &fp.pattern {
                    Some(p) => self.moves_nothing(p, ft),
                    None => self.is_copy(ft),
                }
            }),
            _ => false,
        }
    }

    /// Bind the names of a pattern known to match. A binding moves its
    /// part out (core semantics §3), or borrows it when matching went
    /// through a reference.
    fn bind_pattern(
        &mut self,
        pat: &'a Pattern,
        place: &Place,
        t: Ty,
        by_ref: bool,
        out: &mut Vec<(Local, Ty)>,
    ) -> R<()> {
        // A part that is a reference binds through it, by reference.
        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            if self.destructures(pat) {
                let p = place.project(ProjElem::Deref);
                return self.bind_pattern(pat, &p, inner, true, out);
            }
        }
        // The parts of a `shared` value are only reached through a handle,
        // so a plain binding of one is a `ref` (core semantics §4.6).
        let by_ref = by_ref || matches!(self.tys().tcx().kind(t), HK::Shared { .. });
        match &pat.kind {
            PatternKind::Wildcard | PatternKind::Literal(_) => Ok(()),
            PatternKind::Binding(name) => {
                if matches!(self.lcx.res.get(&pat.id), Some(Res::Def(_))) {
                    return Ok(());
                }
                if self
                    .lcx
                    .mut_ref_bindings
                    .contains(&SpanKey::from_span(&pat.span))
                {
                    self.bind_mut_ref(name, pat.id, place.clone(), t, out);
                    return Ok(());
                }
                let by_ref = by_ref
                    || self
                        .lcx
                        .ref_bindings
                        .contains(&SpanKey::from_span(&pat.span));
                self.bind_one(name, pat.id, place.clone(), t, by_ref, out);
                Ok(())
            }
            PatternKind::Tuple(ps) => {
                for (i, p) in ps.iter().enumerate() {
                    let ft = self.tys().field_ty(t, None, i as u32).unwrap();
                    self.bind_pattern(p, &place.field(i as u32, ft), ft, by_ref, out)?;
                }
                Ok(())
            }
            PatternKind::TupleVariant { patterns, .. } => {
                let Some(&Res::Def(d)) = self.lcx.res.get(&pat.id) else {
                    return Ok(());
                };
                let Some(idx) = self.variant_at(d, t) else {
                    return Ok(());
                };
                let base = place.project(ProjElem::Downcast(VariantIdx(idx)));
                for (i, p) in patterns.iter().enumerate() {
                    let ft = self.tys().tcx().field_ty(t, Some(idx), i as u32).unwrap();
                    self.bind_pattern(p, &base.field(i as u32, ft), ft, by_ref, out)?;
                }
                Ok(())
            }
            PatternKind::Struct { fields, .. } => {
                let variant = match self.lcx.res.get(&pat.id) {
                    Some(&Res::Def(d)) => self.variant_at(d, t).map(|i| (d, i)),
                    _ => None,
                };
                let base = match variant {
                    Some((_, idx)) => place.project(ProjElem::Downcast(VariantIdx(idx))),
                    None => place.clone(),
                };
                for fp in fields {
                    let (idx, ft) = self.field_of(t, variant.map(|v| v.1), &fp.name).unwrap();
                    let fplace = base.field(idx, ft);
                    match &fp.pattern {
                        Some(p) => self.bind_pattern(p, &fplace, ft, by_ref, out)?,
                        None => self.bind_one(&fp.name, pat.id, fplace, ft, by_ref, out),
                    }
                }
                Ok(())
            }
            PatternKind::RangePattern { .. } => Ok(()),
            // Which alternative matched is not known here, so only an
            // or-pattern that binds nothing is lowered.
            PatternKind::Or(_) if !self.pattern_binds(pat) => Ok(()),
            // `x @ p`: `x` names the whole, `p` binds its parts. Both can
            // hold their values only when the whole is copied or borrowed.
            PatternKind::AtBinding {
                name,
                pattern,
                by_ref: at_ref,
            } => {
                let by_ref = by_ref || *at_ref;
                // Under an owned scrutinee `name` takes the whole, so `p`
                // may bind only `Copy` parts (design.md § `@` bindings):
                // those are copied out first.
                self.bind_pattern(pattern, place, t, by_ref, out)?;
                self.bind_one(name, pat.id, place.clone(), t, by_ref, out);
                Ok(())
            }
            PatternKind::Slice {
                prefix,
                rest,
                suffix,
            } => {
                let Some((elem, known)) = self.seq_of(t) else {
                    return self.unsupported(pat.span, "a slice pattern on this type");
                };
                // Over a view every element binding borrows.
                let by_ref = by_ref || known.is_none();
                let (k, j) = (prefix.len() as u64, suffix.len() as u64);
                for (i, p) in prefix.iter().enumerate() {
                    if self.pattern_binds(p) {
                        let ep = self.seq_elem(place, t, SeqPos::Start(i as u64))?;
                        self.bind_pattern(p, &ep, elem, by_ref, out)?;
                    }
                }
                for (i, p) in suffix.iter().enumerate() {
                    if self.pattern_binds(p) {
                        let ep = self.seq_elem(place, t, SeqPos::End(j - i as u64))?;
                        self.bind_pattern(p, &ep, elem, by_ref, out)?;
                    }
                }
                if let Some(ast::RestPattern::Bound(name)) = rest {
                    // Over an array, `..rest` is the middle as an array; a
                    // middle of `Copy` elements is copied, which reads the
                    // same as the borrow the spec describes.
                    if let Some(n) = known {
                        if !self.is_copy(elem) {
                            return self
                                .unsupported(pat.span, "a named rest of non-`Copy` elements");
                        }
                        let ops = (k..n - j)
                            .map(|i| Operand::Copy(place.project(ProjElem::ConstIndex(i))))
                            .collect();
                        let at = self.tys().tcx().intern(HK::Array {
                            elem,
                            len: crate::ty::ArrayLen::Known(n - k - j),
                        });
                        let l = self.user_local(name, at, pat.id);
                        self.assign(l, Rvalue::Aggregate(AggregateKind::Array(elem), ops));
                        out.push((l, at));
                        return Ok(());
                    }
                    // `..rest` is a view of the middle, `[k, len - j)`.
                    let usize_t = self.tys().tcx().intern(HK::UInt(UIntSize::Usize));
                    let n = self.seq_len(place, t);
                    let hi = self.temp(usize_t);
                    self.assign(
                        hi,
                        Rvalue::BinaryOp(
                            BinOp::Sub,
                            Operand::Copy(Place::local(n)),
                            Operand::Const(Const {
                                ty: usize_t,
                                kind: ConstKind::Scalar(j as u128),
                            }),
                        ),
                    );
                    let st = self.tys().tcx().intern(HK::Slice {
                        elem,
                        mutable: false,
                    });
                    let r = self.ref_to(place.clone(), t);
                    let tname = self.tys().display(t);
                    let l = self.user_local(name, st, pat.id);
                    self.call_native(
                        &format!("{tname}.slice"),
                        vec![
                            r,
                            Operand::Const(Const {
                                ty: usize_t,
                                kind: ConstKind::Scalar(k as u128),
                            }),
                            Operand::Copy(Place::local(hi)),
                        ],
                        Place::local(l),
                    );
                    out.push((l, st));
                }
                Ok(())
            }
            _ => self.unsupported(pat.span, "this pattern"),
        }
    }

    /// Does `place` reach its target through a `mut ref`?
    /// Whether `place` is reached through no index and only through
    /// `mut ref` dereferences, so it may be written (B-2026-10-18-41).
    fn only_through_mut_refs(&self, place: &Place) -> bool {
        (0..place.projection.len()).all(|k| match place.projection[k] {
            ProjElem::Index(_) | ProjElem::ConstIndex(_) => false,
            ProjElem::Deref => {
                let base = Place {
                    local: place.local,
                    projection: place.projection[..k].to_vec(),
                };
                matches!(self.tys().tcx().kind(self.place_type(&base)), HK::MutRef(_))
            }
            _ => true,
        })
    }

    fn through_mut_ref(&self, place: &Place) -> bool {
        (0..place.projection.len()).any(|k| {
            matches!(place.projection[k], ProjElem::Deref) && {
                let base = Place {
                    local: place.local,
                    projection: place.projection[..k].to_vec(),
                };
                matches!(self.tys().tcx().kind(self.place_type(&base)), HK::MutRef(_))
            }
        })
    }

    fn bind_one(
        &mut self,
        name: &str,
        node: NodeId,
        place: Place,
        t: Ty,
        by_ref: bool,
        out: &mut Vec<(Local, Ty)>,
    ) {
        // Matching through a `mut ref` binds `mut ref`s into the scrutinee,
        // `Copy` parts included (`Some(n) => set_to(n, 42)` writes the
        // payload); through a `ref`, a `Copy` part is copied, which reads
        // the same.
        // A `Copy` part of a field reached through a `mut ref` (`Some(n)`
        // over `it.v`) copies, as the checker types it (B-2026-10-18-41).
        let copied = self.is_copy(t) && self.writable_reborrows.contains(&place.local);
        let mutable = by_ref && self.through_mut_ref(&place) && !copied;
        // A binding that covers a whole handle (or handle aggregate) copies
        // it even from a `ref` scrutinee (core semantics §4.6, §6.1).
        let handle = self.is_handle(t) || self.is_handle_aggregate(t);
        // A generic body's binding the checker typed as a `ref` stays one
        // when its instance is `Copy` (`Option.as_ref` at a `Copy` `T`).
        let typed_ref = by_ref
            && self.lcx.node_types.contains_key(&node)
            && self.node_ty(node, Span::default()).is_ok_and(
                |bt| matches!(self.tys().tcx().kind(bt), HK::Ref(i) | HK::MutRef(i) if i == t),
            );
        if mutable || typed_ref || (by_ref && !self.is_copy(t) && !handle) {
            let rt = self.tys().tcx().reference(t, mutable);
            let l = self.user_local(name, rt, node);
            let kind = if mutable {
                BorrowKind::Mut
            } else {
                BorrowKind::Shared
            };
            self.assign(l, Rvalue::Ref(kind, place));
            out.push((l, rt));
        } else {
            let l = self.user_local(name, t, node);
            if handle {
                // A `shared` handle binds a counted copy (§6.1).
                self.count_copy(place, t, Place::local(l));
            } else {
                // A copy out of a writable place stays a copy: the arm may
                // write that place while the binding is still read.
                if by_ref
                    && place.projection.contains(&ProjElem::Deref)
                    && !self.through_mut_ref(&place)
                {
                    self.copy_views.insert(l, place.clone());
                }
                let op = self.use_place(place, t);
                self.assign(l, Rvalue::Use(op));
            }
            out.push((l, t));
        }
    }

    /// A `mut ref name` binding: a mutable borrow of its part, `Copy` or
    /// not (core semantics §4.6, B-2026-10-15-13).
    fn bind_mut_ref(
        &mut self,
        name: &str,
        node: NodeId,
        place: Place,
        t: Ty,
        out: &mut Vec<(Local, Ty)>,
    ) {
        let rt = self.tys().tcx().reference(t, true);
        let l = self.user_local(name, rt, node);
        self.assign(l, Rvalue::Ref(BorrowKind::Mut, place));
        out.push((l, rt));
    }

    // ── calls ───────────────────────────────────────────────────────

    /// The user bodies a native calls back into: the exporter
    /// `Log.set_exporter` registers receives each later event through its
    /// `export_event`.
    fn queue_for_native(&mut self, name: &str, args: &[Operand]) {
        // A sort of elements with a user `Ord` orders them by its `cmp`, as
        // do the searches that assume that order (B-2026-10-06-109).
        if [".sort", ".sort_unstable", ".is_sorted", ".binary_search"]
            .iter()
            .any(|m| name.ends_with(m))
        {
            if let Some(op) = args.first() {
                let (_, t) = self.strip_ty_full(self.operand_ty(op));
                let elem = match self.tys().tcx().kind(t) {
                    HK::Intrinsic { args, .. } => self.tys().tcx().list(args).first().copied(),
                    HK::Slice { elem, .. } | HK::Array { elem, .. } => Some(elem),
                    _ => None,
                };
                if let Some(e) = elem {
                    self.queue_user_cmp(e);
                }
            }
        }
        // A sorted table keeps its keys in the order of their user `cmp`.
        if name.starts_with("SortedSet[") || name.starts_with("SortedMap[") {
            if let Some(op) = args.first() {
                let (_, t) = self.strip_ty_full(self.operand_ty(op));
                if let HK::Intrinsic { args, .. } = self.tys().tcx().kind(t) {
                    if let Some(&k) = self.tys().tcx().list(args).first() {
                        self.queue_user_cmp(k);
                    }
                }
            }
        }
        // `std.log`'s installed backend receives each kept record through
        // its `emit`.
        if name.starts_with("log_install$") {
            if let Some(op) = args.first() {
                let (_, t) = self.strip_ty_full(self.operand_ty(op));
                if let Some((d, inst)) = self.user_impl_method(t, "Backend", "emit") {
                    self.lcx.instance(d, inst);
                }
            }
        }
        if name.starts_with("Log[") && name.ends_with(".set_exporter") {
            if let Some(op) = args.first() {
                let (_, t) = self.strip_ty_full(self.operand_ty(op));
                if let Some((d, inst)) = self.user_impl_method(t, "Exporter", "export_event") {
                    self.lcx.instance(d, inst);
                }
            }
        }
    }

    /// Mark the table at `place` as walking under a fixed key, as a table
    /// whose type names a hasher does (`karac_mir_map_unkeyed`).
    fn unkey_table(&mut self, place: Place) {
        self.call_native("table_unkeyed", vec![Operand::Move(place.clone())], place);
    }

    /// Whether the `?` at `at` keeps the error return trace (design.md §
    /// Error return traces): one in the program's own source, outside a
    /// release build (B-2026-10-25-3).
    fn traces_question(&self, at: Span) -> bool {
        self.lcx.user_len.is_none_or(|n| at.offset < n)
            && !release_strips("KARAC_STRIP_ERROR_TRACE")
    }

    /// The message of `r.context(msg)?`, the `?`'s operand being the
    /// library's `context` on a `Result[T, AnyError]`: a `ref` to the last
    /// context message of the error at `p` (of type `it`, variant `err`),
    /// which that call has just pushed (design.md § Errors, "A site with
    /// `.context()` fills `\"context\"`", B-2026-10-25-44). `None` for any
    /// other `?`.
    fn trace_context(&mut self, inner: &Expr, p: &Place, it: Ty, err: u32) -> Option<Operand> {
        let ExprKind::MethodCall { method, .. } = &inner.kind else {
            return None;
        };
        // The library's own `context`, which pushes the message it is
        // given; a program's method of that name may not.
        let library = |d: &DefId| {
            self.lcx
                .fns
                .get(d)
                .is_some_and(|i| self.lcx.user_len.is_some_and(|n| i.f.span.offset >= n))
        };
        if method != "context"
            || !matches!(self.lcx.calls.get(&inner.id), Some(rc) if matches!(&rc.callee, Callee::Def(d) if library(d)))
        {
            return None;
        }
        let tcx = self.tys().tcx();
        let any = tcx.field_ty(it, Some(err), 0)?;
        let (adt, _) = tcx.adt_of(any)?;
        if adt.name != "AnyError" {
            return None;
        }
        let (idx, msgs) = self.field_of(any, None, "context")?;
        let (string, _) = self.seq_of(msgs)?;
        let error = p
            .project(ProjElem::Downcast(VariantIdx(err)))
            .field(0, any)
            .field(idx, msgs);
        let last = self.seq_elem(&error, msgs, SeqPos::End(1)).ok()?;
        let rt = self.tys().tcx().reference(string, false);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, last));
        Some(Operand::Move(Place::local(r)))
    }

    /// `error_trace_push(line, col, expr)` of the `?` at `at`, on its error
    /// path, with the `.context()` message of its site when it has one, or
    /// `error_trace_clear()` on its success path.
    fn error_trace(&mut self, name: &str, at: Span, context: Option<Operand>) {
        let i64_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let int = |n: usize| {
            Operand::Const(Const {
                ty: i64_t,
                kind: ConstKind::Scalar(n as u128),
            })
        };
        let args = if name == "error_trace_push" {
            // The `?` expression as written, on one line (design.md §
            // Error return traces' `expr`, B-2026-10-25-29).
            let expr = self
                .lcx
                .source
                .get(at.offset..at.offset + at.length)
                .unwrap_or("")
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ");
            let mut args = vec![int(at.line), int(at.column), self.static_str(&expr)];
            args.extend(context);
            args
        } else {
            Vec::new()
        };
        let unit = self.tys().unit();
        let l = self.temp(unit);
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo { span: at, ..outer });
        self.call_native(name, args, Place::local(l));
        self.b.set_source_info(outer);
    }

    fn call_native(&mut self, name: &str, args: Vec<Operand>, dest: Place) {
        self.queue_for_native(name, &args);
        let func = self.fn_operand(name, DefId(u32::MAX), Vec::new());
        let next = self.b.new_block();
        // A table a `Map` / `Set` native builds into a slot whose type
        // names a hasher walks under a fixed key (B-2026-10-25-31).
        let hashed = (name.starts_with("Map[") || name.starts_with("Set["))
            && self.tys().hasher(self.place_type(&dest)).is_some();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args,
                destination: dest.clone(),
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        if hashed {
            self.unkey_table(dest);
        }
    }

    fn fn_operand(&self, name: &str, def: DefId, args: Vec<Ty>) -> Operand {
        let unit = self.unit();
        Operand::Const(Const {
            ty: unit,
            kind: ConstKind::FnDef(InstanceId {
                def,
                args,
                name: name.to_string(),
            }),
        })
    }

    /// A call to an `extern "C"` function: by name, each argument at its
    /// declared parameter type, with the declaration recorded in the
    /// program's `externs` for the backends (design.md § FFI).
    fn extern_call(
        &mut self,
        e: &'a Expr,
        decl: &'a ast::ExternFunction,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        if decl.params.len() != args.len() {
            return self.unsupported(
                e.span,
                "an `extern` call with the wrong number of arguments",
            );
        }
        let mut params = Vec::with_capacity(args.len());
        for p in &decl.params {
            match self.lcx.extern_ty(&p.ty) {
                Some(t) => params.push(t),
                None => return self.unsupported(p.ty.span, &crossing(&decl.name)),
            }
        }
        let ret = match &decl.return_type {
            None => self.unit(),
            Some(t) => match self.lcx.extern_ty(t) {
                Some(t) => t,
                None => return self.unsupported(t.span, &crossing(&decl.name)),
            },
        };
        let mut ops = Vec::with_capacity(args.len());
        for (a, &t) in args.iter().zip(&params) {
            ops.push(self.operand_at(&a.value, t)?);
        }
        self.lcx.program.externs.insert(
            decl.name.clone(),
            interp::ExternSig {
                params,
                ret,
                host: decl.abi == "host",
            },
        );
        self.call_native(&decl.name, ops, dest);
        Ok(())
    }

    /// A comptime native (B-2026-10-22-20): a reflection method of a
    /// `Type` value (`t.name()`, `f.ty.is_struct()`), of a type named in
    /// call position (`Point.fields()`), `ast.item(s)` / `ast.expr(s)` or
    /// `compiler.error(msg)`. Each runs on the MIR interpreter's comptime
    /// natives (`interp::comptime`); `true` when `e` was one.
    fn comptime_native(&mut self, e: &'a Expr, dest: &Place) -> R<bool> {
        let not_local = |b: &Self, x: &Expr| !matches!(b.lcx.res.get(&x.id), Some(Res::Local(_)));
        let (name, receiver, type_name, args): (
            String,
            Option<&'a Expr>,
            Option<&'a str>,
            &'a [CallArg],
        ) = match &e.kind {
            ExprKind::MethodCall {
                object,
                method,
                args,
                ..
            } => {
                // A `comptime T: Type` parameter is a borrow under D5.
                let is_type = match self.lcx.tc.node_types.get(&object.id) {
                        Some((Type::Ref(t) | Type::MutRef(t), _)) => Some(t.as_ref()),
                        Some((t, _)) => Some(t),
                        None => None,
                    }
                    .is_some_and(|t| matches!(t, Type::Named { name, args } if name == "Type" && args.is_empty()));
                match &object.kind {
                    _ if is_type => (format!("Type.{method}"), Some(&**object), None, args),
                    ExprKind::Identifier(m)
                        if matches!(
                            (m.as_str(), method.as_str()),
                            ("ast", "item" | "expr") | ("compiler", "error")
                        ) && not_local(self, object) =>
                    {
                        (format!("{m}.{method}"), None, None, args)
                    }
                    _ => return Ok(false),
                }
            }
            ExprKind::Call { callee, args } => match &callee.kind {
                ExprKind::Path { segments, .. } => match segments.as_slice() {
                    [m, f]
                        if matches!(
                            (m.as_str(), f.as_str()),
                            ("ast", "item" | "expr") | ("compiler", "error")
                        ) =>
                    {
                        (format!("{m}.{f}"), None, None, args)
                    }
                    [t, f]
                        if interp::comptime::REFLECTION_METHODS.contains(&f.as_str())
                            && (self.lcx.tc.struct_info.contains_key(t)
                                || self.lcx.tc.enum_info.contains_key(t)
                                || self.lcx.tc.union_info.contains_key(t)) =>
                    {
                        (format!("Type.{f}"), None, Some(t.as_str()), args)
                    }
                    _ => return Ok(false),
                },
                _ => return Ok(false),
            },
            _ => return Ok(false),
        };
        let mut ops = Vec::new();
        if let Some(t) = type_name {
            ops.push(self.static_str(t));
        }
        for x in receiver.into_iter().chain(args.iter().map(|a| &a.value)) {
            let p = self.expr_place_of(x, false)?;
            let t = self.place_type(&p);
            ops.push(self.ref_to(p, t));
        }
        if name == "compiler.error" {
            let i64t = self.tys().tcx().intern(HK::Int(IntSize::I64));
            for n in [e.span.line, e.span.column, e.span.offset, e.span.length] {
                ops.push(Operand::Const(Const {
                    ty: i64t,
                    kind: ConstKind::Scalar(n as u128),
                }));
            }
        }
        self.call_native(&name, ops, dest.clone());
        Ok(true)
    }

    fn call(&mut self, e: &'a Expr, callee: &'a Expr, args: &'a [CallArg], dest: Place) -> R<()> {
        if let Some(&l) = self.old_vals.get(&e.id) {
            let t = self.b.local_ty(l);
            self.clone_into(Place::local(l), t, dest);
            return Ok(());
        }
        if self.comptime_native(e, &dest)? {
            return Ok(());
        }
        // `with_provider[R](p, f)` and `R.m(args)` (core semantics §14).
        if let Some(r) = with_provider_resource(callee) {
            if self.lcx.resource_bounds.contains_key(r) {
                return self.with_provider_call(e, r, args, dest);
            }
        }
        if let ExprKind::Path { segments, .. } = &callee.kind {
            if let [r, m] = segments.as_slice() {
                if self.resource_via_provider(r) {
                    return self.resource_call(e, r, m, args, dest);
                }
            }
        }
        // `UserId(7)`: a distinct type's constructor wraps its base, as
        // does the library's `ExitCode.from(code)`.
        let wraps = match &callee.kind {
            ExprKind::Identifier(name) => Some(name.as_str()),
            ExprKind::Path { segments, .. }
                if segments.len() == 2 && segments[0] == "ExitCode" && segments[1] == "from" =>
            {
                Some("ExitCode")
            }
            _ => None,
        };
        if let (Some(name), [a]) = (wraps, args) {
            let tc = self.lcx.tc;
            if tc.distinct_bases.contains_key(name) && !tc.struct_info.contains_key(name) {
                let t = self.expr_ty(e)?;
                if let Some(bt) = self.distinct_base(t) {
                    let v = self.temp(bt);
                    let op = self.operand_at(&a.value, bt)?;
                    self.assign(Place::local(v), Rvalue::Use(op));
                    self.require_refinement(name, v)?;
                    self.wrap_distinct(t, v, dest);
                    return Ok(());
                }
            }
        }
        // `Vec.try_from_iter(it)`: the library's `Vec.from_iter`, as an `Ok`
        // (an allocation here does not fail).
        if let ExprKind::Path { segments, .. } = &callee.kind {
            if let ([v, m], [_]) = (segments.as_slice(), args) {
                if v == "Vec" && m == "try_from_iter" && !self.lcx.calls.contains_key(&e.id) {
                    let rt = self.expr_ty(e)?;
                    let tcx = self.tys().tcx();
                    let ok = tcx
                        .adt_of(rt)
                        .and_then(|(adt, _)| adt.variants.iter().position(|v| v.name == "Ok"))
                        .map(|i| i as u32);
                    if let Some((idx, vt)) =
                        ok.and_then(|i| Some((i, tcx.field_ty(rt, Some(i), 0)?)))
                    {
                        let built = self.temp(vt);
                        self.type_param_call(e, vt, "from_iter", args, Place::local(built))?;
                        self.build_variant(rt, idx, vec![Operand::Move(Place::local(built))], dest);
                        return Ok(());
                    }
                }
            }
        }
        let rc = self.lcx.calls.get(&e.id);
        // `T.m(..)` with `T` a type parameter of this body goes to the
        // instance's type, also where the program has a type or value named
        // `T` that the checker took the path for (`struct V` against `sum`'s
        // `V.default()`).
        if let ExprKind::Path { segments, .. } = &callee.kind {
            if let [tp, m] = segments.as_slice() {
                // `T.try_from(x)` of a refinement or distinct type with a
                // `where` predicate has no definition: the checker makes it.
                if let ("try_from", [a], None) = (m.as_str(), args, rc) {
                    if self.lcx.refined.contains_key(tp) {
                        return self.refinement_try_from(e, tp, &a.value, dest);
                    }
                }
                if let ("try_from", [a]) = (m.as_str(), args) {
                    let declared = self
                        .lcx
                        .tc
                        .enum_discriminants
                        .get(tp.as_str())
                        .is_some_and(|d| d.repr_declared);
                    if declared && rc.is_none_or(|rc| matches!(rc.callee, Callee::Builtin(_))) {
                        return self.enum_try_from(e, tp, &a.value, dest);
                    }
                }
                if rc.is_none_or(|rc| matches!(rc.callee, Callee::Builtin(_))) {
                    if let Some(t) = self.type_param(tp) {
                        return self.type_param_call(e, t, m, args, dest);
                    }
                    // `i64.default()`, `String.default()`: a standard type's
                    // zero or empty value, the type the call has
                    // (B-2026-10-13-27).
                    if let ("default", []) = (m.as_str(), args) {
                        let t = self.expr_ty(e)?;
                        return self.type_param_call(e, t, m, args, dest);
                    }
                }
            }
        }
        // `default()` where the checker took the receiver from the expected
        // type (`let w: Wrapper = default()`, `T.default()` inside a generic
        // body) is that type's associated function.
        if let ExprKind::Identifier(m) = &callee.kind {
            if rc.is_none_or(|rc| matches!(rc.callee, Callee::Value)) {
                let key = SpanKey::from_span(&e.span);
                if let Some(target) = self.lcx.tc.bare_assoc_fn_targets.get(&key) {
                    let t = match self.type_param(target) {
                        Some(t) => t,
                        None => self.named_target(e, target)?,
                    };
                    return self.type_param_call(e, t, m, args, dest);
                }
            }
        }
        let Some(rc) = rc else {
            if self.variant_into(e, callee, args, dest.clone())? {
                return Ok(());
            }
            return self.unsupported(e.span, "a call with no resolved callee");
        };
        let callee_kind = rc.callee.clone();
        let substs = self.lcx.tys.tcx().list(rc.substs);
        // `C.doubled()` with an uppercase local `C`, which the parser reads
        // as a path: the local (through any fields before the method) is
        // the receiver.
        if let (ExprKind::Path { segments, .. }, Some(&Res::LocalPath(sym)), &Callee::Def(d)) =
            (&callee.kind, self.lcx.res.get(&callee.id), &callee_kind)
        {
            let f = self.lcx.fns.get(&d).map(|i| i.f);
            if let Some((f, mode)) = f.and_then(|f| Some((f, f.self_param.clone()?))) {
                let p = self.local_path_place(callee.span, sym, &segments[..segments.len() - 1])?;
                let (p, vt) = self.strip_refs(p);
                let inst_args = self.instance_args(e.span, &substs)?;
                let recv = match self.self_mode(f, mode, vt) {
                    SelfParam::Owned => self.use_place(p, vt),
                    SelfParam::Ref => self.ref_to(p, vt),
                    SelfParam::MutRef => {
                        let rt = self.tys().tcx().reference(vt, true);
                        let r = self.temp(rt);
                        self.assign(r, Rvalue::Ref(BorrowKind::Mut, p));
                        Operand::Move(Place::local(r))
                    }
                };
                return self.def_call(e, d, f, inst_args, Some(recv), args, dest);
            }
        }
        // `LOG_PATH.clone()` parses as a path: a library method of the
        // constant's value, which is computed here.
        if let ExprKind::Path { segments, .. } = &callee.kind {
            if let [c, m] = segments.as_slice() {
                // A binding in a static is the receiver itself, borrowed.
                let st = self.lcx.defs.lookup(0, c);
                if let Some(d) = st.filter(|d| self.lcx.statics.contains_key(d)) {
                    let (_, vt, mutable) = self.lcx.statics[&d];
                    let p = self.static_place(d);
                    let rt = self.tys().tcx().reference(vt, mutable);
                    let r = self.temp(rt);
                    let kind = if mutable {
                        BorrowKind::Mut
                    } else {
                        BorrowKind::Shared
                    };
                    self.assign(r, Rvalue::Ref(kind, p));
                    let mut ops = vec![Operand::Move(Place::local(r))];
                    // A stored value moves in (`LOG.push(line)`), as into
                    // any collection; other non-Copy arguments are lent.
                    let stores = stores_argument(m.as_str());
                    for a in args {
                        let t = self.expr_ty(&a.value)?;
                        let by_ref = !stores && !self.is_copy(t);
                        ops.push(self.lib_arg(&a.value, by_ref)?);
                    }
                    let name = format!("{}.{m}", self.tys().display(vt));
                    self.call_native(&name, ops, dest);
                    return Ok(());
                }
                let value = self
                    .lcx
                    .defs
                    .lookup(0, c)
                    .and_then(|d| self.lcx.consts.get(&d).copied());
                if let Some(value) = value {
                    let vt = self.expr_ty(value)?;
                    let tmp = self.temp_of(value, vt)?;
                    // A method the program (or its library) defines takes
                    // the computed value as its receiver.
                    let def = match callee_kind {
                        Callee::Def(d) => self.lcx.fns.get(&d).map(|i| (d, i.f)),
                        _ => None,
                    };
                    if let Some((d, f)) = def {
                        if let Some(mode) = f.self_param.clone() {
                            let inst_args = self.instance_args(e.span, &substs)?;
                            let mode = self.self_mode(f, mode, vt);
                            // A constant array's `Slice[T]` methods take a
                            // view of it (`AA.iter()`; B-2026-10-14-52).
                            let as_slice = self.lcx.fns[&d].impl_slice
                                && !matches!(self.tys().tcx().kind(vt), HK::Slice { .. });
                            if let (true, Some(&elem)) = (as_slice, inst_args.first()) {
                                let mutable = matches!(mode, SelfParam::MutRef);
                                let slice_t = self.tys().tcx().intern(HK::Slice { elem, mutable });
                                let s = self.slice_view_of(Place::local(tmp), vt, slice_t, mutable);
                                let recv = self.slice_receiver(s, slice_t, &mode);
                                return self.def_call(e, d, f, inst_args, Some(recv), args, dest);
                            }
                            let recv = match mode {
                                SelfParam::Owned => Operand::Move(Place::local(tmp)),
                                SelfParam::Ref => self.ref_to(Place::local(tmp), vt),
                                SelfParam::MutRef => {
                                    let rt = self.tys().tcx().reference(vt, true);
                                    let r = self.temp(rt);
                                    self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(tmp)));
                                    Operand::Move(Place::local(r))
                                }
                            };
                            return self.def_call(e, d, f, inst_args, Some(recv), args, dest);
                        }
                    }
                    // A number's library methods take it by value, as a
                    // local's do (`TOL0.sqrt()`; B-2026-10-23-3).
                    let recv = match self.is_number(vt) {
                        true => Operand::Move(Place::local(tmp)),
                        false => self.ref_to(Place::local(tmp), vt),
                    };
                    let mut ops = vec![recv];
                    for a in args {
                        let t = self.expr_ty(&a.value)?;
                        let by_ref = !self.is_copy(t);
                        ops.push(self.lib_arg(&a.value, by_ref)?);
                    }
                    let name = format!("{}.{m}", self.tys().display(vt));
                    self.call_native(&name, ops, dest);
                    return Ok(());
                }
            }
        }
        // `Stderr.println(x)` is `eprintln(x)`.
        let user_def = matches!(callee_kind, Callee::Def(d) if self.lcx.fns.contains_key(&d));
        if let Some(name) = stderr_print(callee).filter(|_| !user_def) {
            return self.builtin_call(e, name, args, dest);
        }
        if let Callee::Builtin(_) = callee_kind {
            if self.variant_builtin(e, callee, args, dest.clone())? {
                return Ok(());
            }
        }
        match callee_kind {
            Callee::Builtin(name) => self.builtin_call(e, &name, args, dest),
            Callee::Value => self.call_value(e, callee, args, dest),
            Callee::Def(d) => {
                // A bare `Err(..)` may have resolved to a user struct named
                // `Err`; a call typed as an enum names its variant
                // (B-2026-10-21-18).
                let struct_names_variant = self.lcx.defs.table.get(d).kind == DefKind::Struct
                    && !self.lcx.fns.contains_key(&d)
                    && {
                        let t = self.expr_ty(e)?;
                        let tcx = self.tys().tcx();
                        let t = match tcx.kind(t) {
                            HK::Ref(inner) | HK::MutRef(inner) => inner,
                            _ => t,
                        };
                        matches!(
                            tcx.kind(t),
                            HK::Adt { def, .. } | HK::Shared { def, .. } if def != d
                        )
                    };
                if self.lcx.variant(d).is_some()
                    || self.lcx.defs.table.get(d).kind == DefKind::Variant
                    || struct_names_variant
                {
                    let mut t = self.expr_ty(e)?;
                    // A constructor whose enum the checker left a parameter
                    // free in (`Ok(v)` closing a closure whose `?` fixes the
                    // error type) takes its destination's type.
                    let dt = self.place_type(&dest);
                    let tcx = self.tys().tcx();
                    if let (HK::Adt { def: a, .. }, HK::Adt { def: b, .. }) =
                        (tcx.kind(t), tcx.kind(dt))
                    {
                        if a == b {
                            t = dt;
                        }
                    }
                    // A constructor handed to a borrowed parameter builds
                    // the value it lends (`show(Ok(x))` for `ref Result`).
                    let ty = t;
                    let t = match self.tys().tcx().kind(t) {
                        HK::Ref(inner) | HK::MutRef(inner) => inner,
                        _ => t,
                    };
                    // A bare `Err(..)` may have resolved to a user variant of
                    // the same name; the value's enum decides
                    // (B-2026-10-15-3).
                    let Some(idx) = self.variant_at(d, t) else {
                        return self.unsupported(e.span, "this variant");
                    };
                    let mut ops = Vec::new();
                    for (i, a) in args.iter().enumerate() {
                        // Each payload at its field's type (`Some((1, 2))`
                        // as an `Option[(i32, i32)]`).
                        let ft = self.tys().tcx().field_ty(t, Some(idx), i as u32);
                        ops.push(match ft {
                            Some(ft) => self.operand_at(&a.value, ft)?,
                            None => self.expr_operand(&a.value)?,
                        });
                    }
                    self.build_variant(ty, idx, ops, dest);
                    return Ok(());
                }
                if let ("iter_read_value", None, [a]) =
                    (self.lcx.def_name(d).as_str(), self.lcx.def_owner(d), args)
                {
                    return self.read_value(e, &a.value, dest);
                }
                if let ("iter_clone_value", None, [a]) =
                    (self.lcx.def_name(d).as_str(), self.lcx.def_owner(d), args)
                {
                    let (p, t) = self.deref_place(&a.value, false)?;
                    self.clone_into(p, t, dest);
                    return Ok(());
                }
                // Labels need no lowering: the default-argument fill has
                // already put a labeled call's arguments in declaration
                // order, and the typechecker rejected any it could not.
                let inst_args = self.instance_args(e.span, &substs)?;
                let f = self.lcx.fns.get(&d).map(|i| i.f);
                let Some(f) = f else {
                    let name = self.lcx.def_name(d);
                    if let Some(&decl) = self.lcx.extern_fns.get(&d) {
                        return self.extern_call(e, decl, args, dest);
                    }
                    if self.scalar_min_max(e, &name, args, dest.clone())? {
                        return Ok(());
                    }
                    if self.lcx.def_owner(d).is_none()
                        && self.ord_min_max(e, &name, args, dest.clone())?
                    {
                        return Ok(());
                    }
                    if self.lcx.def_owner(d).is_none()
                        && self.volatile_call(&name, args, dest.clone())?
                    {
                        return Ok(());
                    }
                    if self.lcx.def_owner(d).is_none()
                        && self.mem_call(e, &name, args, dest.clone())?
                    {
                        return Ok(());
                    }
                    // `T.size_of()` / `T.align_of()`: a fact about this
                    // instance's `T`, answered from its layout.
                    let layout_op = match name.as_str() {
                        "size_of" => Some(NullOp::SizeOf),
                        "align_of" => Some(NullOp::AlignOf),
                        _ => None,
                    };
                    if let (Some(op), None, [t]) =
                        (layout_op, self.lcx.def_owner(d), inst_args.as_slice())
                    {
                        self.assign(dest, Rvalue::NullaryOp(op, *t));
                        return Ok(());
                    }
                    // The library's `any_error_kind[E]()`: the name of this
                    // instance's `E`, which an `AnyError` keeps (design.md §10).
                    if let ("any_error_kind", None, [t]) =
                        (name.as_str(), self.lcx.def_owner(d), inst_args.as_slice())
                    {
                        let kind = self.tys().display(*t);
                        let op = self.static_str(&kind);
                        self.call_native("String.from", vec![op], dest);
                        return Ok(());
                    }
                    // A library function with no Kāra body (`sleep_ms(2)`,
                    // `Command.new("ls")`, `Arena[i64].new()`): the
                    // interpreter's, by its name qualified with the owning
                    // type and that type's arguments. Copy arguments and a
                    // stored value (`Log.set_exporter(e)`) go by value, the
                    // rest by reference. `File.append(path)` opens a file and
                    // stores nothing: its path is a `Str`.
                    // `forget(value)` takes the value and drops nothing
                    // (B-2026-10-22-38).
                    // `std.log`'s backend and call move into the runtime
                    // (runtime/stdlib/std_log.kara).
                    let stores = (stores_argument(&name)
                        && self.lcx.def_owner(d).as_deref() != Some("File"))
                        || (name == "forget" && self.lcx.def_owner(d).is_none())
                        || (matches!(
                            name.as_str(),
                            "log_install$std_log" | "log_dispatch$std_log"
                        ) && self.lcx.def_owner(d).is_none());
                    // A library handle declared `own` moves in, as into a
                    // library method (`BufReader.new(file)` keeps the file).
                    let owns = self
                        .lcx
                        .def_owner(d)
                        .and_then(|o| self.lcx.builtin_owns.get(&(o.to_string(), name.clone())))
                        .cloned()
                        .unwrap_or_default();
                    let name = match (self.lcx.def_owner(d), inst_args.is_empty()) {
                        (Some(owner), true) => format!("{owner}.{name}"),
                        (Some(owner), false) => {
                            let tys = self.tys();
                            let shown: Vec<String> =
                                inst_args.iter().map(|&t| tys.display(t)).collect();
                            format!("{owner}[{}].{name}", shown.join(", "))
                        }
                        // `with_span(span, || body)`: a generic library
                        // function needs no type argument to run.
                        (None, _) => name,
                    };
                    if let ("IoError.from", [a]) = (name.as_str(), args) {
                        // `IoError.from(e)` of a `VarError`: the library's
                        // variant mapping, as `?` converts one.
                        let have = self.expr_ty(&a.value)?;
                        let want = self.place_type(&dest);
                        let mut ops = vec![self.lib_arg(&a.value, false)?];
                        if self.variant_from(want, have, &mut ops) {
                            let op = ops.pop().expect("the converted error");
                            self.assign(dest, Rvalue::Use(op));
                            return Ok(());
                        }
                    }
                    let mut ops = Vec::new();
                    for (i, a) in args.iter().enumerate() {
                        let t = self.expr_ty(&a.value)?;
                        // (A library handle only, for now: the other
                        // natives read what they are declared to own
                        // through a borrow.)
                        let declared_own = owns.get(i).copied().unwrap_or(false) && {
                            let (_, b) = self.strip_ty_full(t);
                            self.tys().tcx().adt_of(b).is_some_and(|(a, _)| {
                                a.library_name()
                                    .is_some_and(|n| crate::ty::HANDLES.contains(&n))
                            })
                        };
                        // A closure moves in, as into a library method.
                        let moves = stores
                            || declared_own
                            || self.is_fn_typed(a.value.id)
                            || matches!(a.value.kind, ExprKind::Closure { .. });
                        if a.mut_marker && self.is_place(&a.value) {
                            // `CryptoSha2.digest(256, data, mut out)`: a
                            // `mut Slice[T]` parameter lends the place
                            // mutably, even a `Copy` array, as a method
                            // native's does.
                            let p = self.expr_place(&a.value, true)?;
                            let rt = self.tys().tcx().reference(t, true);
                            let r = self.temp(rt);
                            self.assign(r, Rvalue::Ref(BorrowKind::Mut, p));
                            ops.push(Operand::Move(Place::local(r)));
                            continue;
                        }
                        let by_ref = !moves && !self.is_copy(t);
                        ops.push(self.lib_arg(&a.value, by_ref)?);
                    }
                    // `Env.var(name)` on a program-rooted resource: its
                    // provider's method, the provider first (§14.7).
                    let owner = self.lcx.def_owner(d);
                    let mut name = name;
                    if let Some(owner) = owner.filter(|_| inst_args.is_empty()) {
                        if let Some((provider, recv)) = self.provider_recv(&owner)? {
                            ops.insert(0, recv);
                            let method = self.lcx.def_name(d);
                            name = format!("{provider}.{method}");
                        }
                    }
                    self.call_native(&name, ops, dest);
                    return Ok(());
                };
                let recv = self.variant_receiver(callee, d, f, &inst_args)?;
                self.def_call(e, d, f, inst_args, recv, args, dest)
            }
        }
    }

    /// `collect` of `ref T` items into a collection of `T`: a `Copy` item
    /// is read as the value (core semantics §5.10) and a handle is a counted
    /// copy, but anything else would be moved out of the collection the
    /// items view, so it needs `.cloned()` first (iterators.md).
    /// The element a collection `c` is built from: `T` for `Vec[T]`,
    /// `(K, V)` for `Map[K, V]`.
    fn collect_elem(&self, c: Ty) -> Option<Ty> {
        let tcx = self.tys().tcx();
        match tcx.kind(c) {
            HK::Intrinsic { kind, args } => {
                let a = crate::mir::ty::table_args(kind, tcx.list(args));
                match a.len() {
                    1 => Some(a[0]),
                    2 => Some(tcx.intern(HK::Tuple(tcx.intern_list(&a)))),
                    _ => None,
                }
            }
            _ => None,
        }
    }

    /// Is `elem` the tuple `v` with some `ref` parts to `Copy` values read
    /// as those values?
    fn copies_ref_parts(&self, v: Ty, elem: Ty) -> bool {
        let tcx = self.tys().tcx();
        match (tcx.kind(v), tcx.kind(elem)) {
            (HK::Tuple(vs), HK::Tuple(es)) => {
                let (vs, es) = (tcx.list(vs), tcx.list(es));
                vs.len() == es.len()
                    && vs.iter().zip(es.iter()).all(|(a, b)| {
                        a == b
                            || matches!(tcx.kind(*a), HK::Ref(i) | HK::MutRef(i)
                                if i == *b && self.is_copy(i))
                            || self.copies_ref_parts(*a, *b)
                    })
            }
            _ => false,
        }
    }

    fn check_collect_items(&mut self, span: Span, v: Ty, c: Ty) -> R<()> {
        let elem = self.collect_elem(c);
        let Some(elem) = elem else {
            return Ok(());
        };
        if !self.reads_a_ref_as_value(v, elem) {
            return Ok(());
        }
        let (shown_v, shown_e) = (self.tys().display(v), self.tys().display(elem));
        let fix = if matches!(self.tys().tcx().kind(v), HK::Ref(_) | HK::MutRef(_)) {
            "write `.cloned()` before `collect`"
        } else {
            "clone each borrowed part in a `.map(...)` before `collect`"
        };
        self.errors.push(format!(
            "{} in `{}`: the items are `{shown_v}`, and collecting them as `{shown_e}` would \
             move each borrowed part out of the collection it views; {fix} (core semantics \
             §5.10)",
            at(span),
            self.name
        ));
        Err(())
    }

    /// Would reading an item of type `v` as `elem` copy a non-`Copy` value
    /// out from behind a `ref`, here or in a tuple part?
    fn reads_a_ref_as_value(&self, v: Ty, elem: Ty) -> bool {
        let tcx = self.tys().tcx();
        match (tcx.kind(v), tcx.kind(elem)) {
            (HK::Ref(inner) | HK::MutRef(inner), _) => {
                inner == elem
                    && !self.is_copy(inner)
                    && !self.is_handle(inner)
                    && !self.is_handle_aggregate(inner)
            }
            (HK::Tuple(vs), HK::Tuple(es)) => {
                let (vs, es) = (tcx.list(vs), tcx.list(es));
                vs.len() == es.len()
                    && vs
                        .iter()
                        .zip(es.iter())
                        .any(|(a, b)| self.reads_a_ref_as_value(*a, *b))
            }
            _ => false,
        }
    }

    /// The library's `iter_read_value(x)`: `x` read as the call's type. A
    /// `ref` to a value of that type is copied out (core semantics §5.10);
    /// any other value moves.
    fn read_value(&mut self, e: &'a Expr, x: &'a Expr, dest: Place) -> R<()> {
        let xt = self.expr_ty(x)?;
        let rt = self.expr_ty(e)?;
        let tcx = self.tys().tcx();
        if let HK::Ref(inner) | HK::MutRef(inner) = tcx.kind(xt) {
            if !matches!(tcx.kind(rt), HK::Ref(_) | HK::MutRef(_)) {
                let p = if self.is_place(x) && self.is_local_rooted(x) {
                    self.expr_place(x, false)?
                } else {
                    Place::local(self.temp_of(x, xt)?)
                };
                let p = p.project(ProjElem::Deref);
                // A handle is a counted copy (§6.1); anything else that is
                // not `Copy` would move out of the collection the item
                // views, so it needs `.cloned()` first (iterators.md).
                if self.is_handle(inner) || self.is_handle_aggregate(inner) {
                    let l = self.temp(inner);
                    self.count_copy(p, inner, Place::local(l));
                    self.assign(dest, Rvalue::Use(Operand::Move(Place::local(l))));
                    return Ok(());
                }
                if !self.is_copy(inner) {
                    let t = self.tys().display(inner);
                    self.errors.push(format!(
                        "{} in `{}`: the items are `ref {t}`, and reading one as a `{t}` would \
                         move it out of the collection it views; write `.cloned()` before \
                         `collect` (core semantics §5.10)",
                        at(e.span),
                        self.name
                    ));
                    return Err(());
                }
                let op = self.use_place(p, inner);
                self.assign(dest, Rvalue::Use(op));
                return Ok(());
            }
        }
        // A tuple with `ref` parts read as one with values there
        // (`(i64, ref i64)` as `(i64, i64)`, from `.iter().enumerate()`):
        // each such part is read as above, and the rest move.
        if let (HK::Tuple(xl), HK::Tuple(rl)) = (tcx.kind(xt), tcx.kind(rt)) {
            let (xs, rs) = (tcx.list(xl), tcx.list(rl));
            let as_ref = |t: Ty| match tcx.kind(t) {
                HK::Ref(i) | HK::MutRef(i) => Some(i),
                _ => None,
            };
            // Each part: its type, the type it views (a `ref` part), and
            // whether it is read as a `ref` too.
            let parts: Vec<(Ty, Option<Ty>, bool)> = xs
                .iter()
                .zip(rs.iter())
                .map(|(a, b)| (*a, as_ref(*a), as_ref(*b).is_some()))
                .collect();
            if xs.len() == rs.len() && parts.iter().any(|(_, i, b)| i.is_some() && !b) {
                let src = Place::local(self.temp_of(x, xt)?);
                let mut ops = Vec::new();
                for (i, (a, inner, b_ref)) in parts.into_iter().enumerate() {
                    let fp = src.field(i as u32, a);
                    let Some(inner) = inner else {
                        ops.push(Operand::Move(fp));
                        continue;
                    };
                    if b_ref {
                        ops.push(Operand::Copy(fp));
                        continue;
                    }
                    let p = fp.project(ProjElem::Deref);
                    if self.is_handle(inner) || self.is_handle_aggregate(inner) {
                        let l = self.temp(inner);
                        self.count_copy(p, inner, Place::local(l));
                        ops.push(Operand::Move(Place::local(l)));
                    } else if self.is_copy(inner) {
                        ops.push(self.use_place(p, inner));
                    } else {
                        let t = self.tys().display(inner);
                        self.errors.push(format!(
                            "{} in `{}`: the items hold a `ref {t}`, and reading it as a \
                             `{t}` would move it out of the collection it views; clone each \
                             borrowed part in a `.map(...)` before `collect` (core semantics \
                             §5.10)",
                            at(e.span),
                            self.name
                        ));
                        return Err(());
                    }
                }
                self.assign(dest, Rvalue::Aggregate(AggregateKind::Tuple, ops));
                return Ok(());
            }
        }
        let op = self.expr_operand(x)?;
        self.assign(dest, Rvalue::Use(op));
        Ok(())
    }

    /// `E.A.cmp(E.B)` and `Hid.discriminant()` spelled on a unit variant
    /// (`UsbClass.Audio.discriminant()`): a derived method of the enum,
    /// with the variant the path names as its receiver.
    fn variant_builtin(
        &mut self,
        e: &'a Expr,
        callee: &'a Expr,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        let ExprKind::Path { segments, .. } = &callee.kind else {
            return Ok(false);
        };
        let [ty, var, m] = segments.as_slice() else {
            return Ok(false);
        };
        if !matches!((m.as_str(), args), ("cmp", [_]) | ("discriminant", [])) {
            return Ok(false);
        }
        let Some(def) = self.lcx.defs.lookup(0, ty) else {
            return Ok(false);
        };
        let t = self.tys().tcx().adt(def, &[]);
        let Ok(t) = self.lcx.mir_ty(t, &[]) else {
            return Ok(false);
        };
        let Some((adt, _)) = self.tys().tcx().adt_of(t) else {
            return Ok(false);
        };
        let Some(idx) = adt
            .variants
            .iter()
            .position(|v| v.name == *var && v.fields.is_empty())
        else {
            return Ok(false);
        };
        let l = self.temp(t);
        let kind = self.adt_aggregate(t, idx as u32);
        self.assign(l, Rvalue::Aggregate(kind, Vec::new()));
        match args {
            [other] => {
                let rp = self.expr_place(&other.value, false)?;
                let (rp, _) = self.strip_refs(rp);
                self.cmp_places(e.span, Place::local(l), rp, t, dest)?;
                Ok(true)
            }
            _ => self.discriminant_into(e, Place::local(l), t, dest),
        }
    }

    /// `E.try_from(raw)` of a `#[repr(intN)]` enum: `Ok` of the variant
    /// that declares `raw`, else `Err(DiscriminantError.OutOfRange { value:
    /// raw })`.
    fn enum_try_from(&mut self, e: &'a Expr, name: &str, raw: &'a Expr, dest: Place) -> R<()> {
        let rt = self.expr_ty(e)?;
        let tcx = self.tys().tcx();
        let Some((res, _)) = tcx.adt_of(rt) else {
            return self.unsupported(e.span, "this `try_from`");
        };
        let pos = |n: &str| {
            res.variants
                .iter()
                .position(|v| v.name == n)
                .map(|i| i as u32)
        };
        let (Some(ok), Some(er)) = (pos("Ok"), pos("Err")) else {
            return self.unsupported(e.span, "this `try_from`");
        };
        let (Some(et), Some(xt)) = (tcx.field_ty(rt, Some(ok), 0), tcx.field_ty(rt, Some(er), 0))
        else {
            return self.unsupported(e.span, "this `try_from`");
        };
        let (Some((enum_adt, _)), Some((err_adt, _))) = (tcx.adt_of(et), tcx.adt_of(xt)) else {
            return self.unsupported(e.span, "this `try_from`");
        };
        let Some(table) = self.lcx.tc.enum_discriminants.get(name) else {
            return self.unsupported(e.span, "this `try_from`");
        };
        let arms: Vec<(u32, i64)> = table
            .values
            .iter()
            .filter_map(|(n, v)| {
                let i = enum_adt.variants.iter().position(|x| x.name == *n)?;
                Some((i as u32, *v))
            })
            .collect();
        let Some(range) = err_adt.variants.iter().position(|v| v.name == "OutOfRange") else {
            return self.unsupported(e.span, "this `try_from`");
        };
        let Some(dt) = tcx.field_ty(xt, Some(range as u32), 0) else {
            return self.unsupported(e.span, "this `try_from`");
        };
        let v = self.temp(dt);
        let op = self.operand_at(raw, dt)?;
        self.assign(Place::local(v), Rvalue::Use(op));
        let bool_t = self.tys().bool();
        let join = self.b.new_block();
        for (idx, value) in arms {
            let c = self.temp(bool_t);
            let k = Operand::Const(Const {
                ty: dt,
                kind: ConstKind::Scalar(value as u128),
            });
            self.assign(
                c,
                Rvalue::BinaryOp(BinOp::Eq, Operand::Copy(Place::local(v)), k),
            );
            let (yes, no) = (self.b.new_block(), self.b.new_block());
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(c)),
                    targets: SwitchTargets::if_else(yes, no),
                },
                yes,
            );
            let x = self.temp(et);
            let kind = self.adt_aggregate(et, idx);
            self.assign(x, Rvalue::Aggregate(kind, Vec::new()));
            self.build_variant(rt, ok, vec![Operand::Move(Place::local(x))], dest.clone());
            self.goto(join);
            self.cur = no;
        }
        let x = self.temp(xt);
        self.build_variant(
            xt,
            range as u32,
            vec![Operand::Copy(Place::local(v))],
            Place::local(x),
        );
        self.build_variant(rt, er, vec![Operand::Move(Place::local(x))], dest);
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    /// `x.discriminant()` of a payload-free enum: the value its variant
    /// declares (`Hid = 0x03`), or its position where none is declared.
    fn discriminant_into(&mut self, e: &'a Expr, p: Place, t: Ty, dest: Place) -> R<bool> {
        let tcx = self.tys().tcx();
        let Some((adt, _)) = tcx.adt_of(t) else {
            return Ok(false);
        };
        let Some(table) = self.lcx.tc.enum_discriminants.get(adt.name.as_str()) else {
            return Ok(false);
        };
        let values: Vec<i64> = adt
            .variants
            .iter()
            .map(|v| {
                table
                    .values
                    .iter()
                    .find(|(n, _)| *n == v.name)
                    .map(|&(_, x)| x)
            })
            .collect::<Option<_>>()
            .unwrap_or_default();
        if values.len() != adt.variants.len() {
            return Ok(false);
        }
        let rt = self.expr_ty(e)?;
        let i64_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let tag = self.temp(i64_t);
        self.assign(tag, Rvalue::Discriminant(p));
        let join = self.b.new_block();
        let blocks: Vec<BasicBlock> = values.iter().map(|_| self.b.new_block()).collect();
        let otherwise = *blocks.last().unwrap_or(&join);
        let targets = SwitchTargets {
            values: blocks
                .iter()
                .enumerate()
                .map(|(i, &bb)| (i as u128, bb))
                .collect(),
            otherwise,
        };
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(tag)),
                targets,
            },
            join,
        );
        for (&bb, &v) in blocks.iter().zip(&values) {
            self.cur = bb;
            let c = Operand::Const(Const {
                ty: rt,
                kind: ConstKind::Scalar(v as u128),
            });
            self.assign(dest.clone(), Rvalue::Use(c));
            self.goto(join);
        }
        self.cur = join;
        Ok(true)
    }

    /// `A.Y.into()` parses as a call of the path `A.Y.into`, which the
    /// checker resolves as a conversion with no callee: the unit variant
    /// the first two segments name, converted by the user's `From` impl
    /// for the call's type (B-2026-10-24-8).
    fn variant_into(
        &mut self,
        e: &'a Expr,
        callee: &'a Expr,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        let ExprKind::Path { segments, .. } = &callee.kind else {
            return Ok(false);
        };
        let ([ty, var, m], []) = (segments.as_slice(), args) else {
            return Ok(false);
        };
        if m != "into" {
            return Ok(false);
        }
        let Some(def) = self.lcx.defs.lookup(0, ty) else {
            return Ok(false);
        };
        let t = self.tys().tcx().adt(def, &[]);
        let Ok(t) = self.lcx.mir_ty(t, &[]) else {
            return Ok(false);
        };
        let Some((adt, _)) = self.tys().tcx().adt_of(t) else {
            return Ok(false);
        };
        let Some(idx) = adt
            .variants
            .iter()
            .position(|v| v.name == *var && v.fields.is_empty())
        else {
            return Ok(false);
        };
        let dt = self.expr_ty(e)?;
        let to = (dt != t).then(|| self.user_from(dt, t));
        if let Some(None) = to {
            return Ok(false);
        }
        let l = self.temp(t);
        let kind = self.adt_aggregate(t, idx as u32);
        self.assign(l, Rvalue::Aggregate(kind, Vec::new()));
        let Some(Some((d, iargs))) = to else {
            self.assign(dest, Rvalue::Use(Operand::Move(Place::local(l))));
            return Ok(true);
        };
        let f = self.lcx.fns[&d].f;
        let pt = self.callee_param_ty(&f.params[0], &iargs)?;
        let arg = match self.tys().tcx().kind(pt) {
            HK::Ref(_) => self.ref_to(Place::local(l), t),
            _ => Operand::Move(Place::local(l)),
        };
        let name = self.lcx.instance(d, iargs.clone());
        let func = self.fn_operand(&name, d, iargs);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: vec![arg],
                destination: dest,
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(true)
    }

    /// `Ordering.Less.is_lt()` parses as a call of the path
    /// `Ordering.Less.is_lt`: the unit variant its first two segments name
    /// is the receiver of the method the last one names.
    fn variant_receiver(
        &mut self,
        callee: &'a Expr,
        d: DefId,
        f: &'a Function,
        inst_args: &[Ty],
    ) -> R<Option<Operand>> {
        let Some(mode) = f.self_param.clone() else {
            return Ok(None);
        };
        let ExprKind::Path { segments, .. } = &callee.kind else {
            return Ok(None);
        };
        let [ty, var, _] = segments.as_slice() else {
            return Ok(None);
        };
        let Some(def) = self.lcx.defs.lookup(0, ty) else {
            return Ok(None);
        };
        let n = self.lcx.fns[&d].impl_params;
        let targs = self.lcx.fns[&d].target_args(inst_args.get(..n).unwrap_or(&[]));
        let t = self.tys().tcx().adt(def, &targs);
        let t = match self.lcx.mir_ty(t, &[]) {
            Ok(t) => t,
            Err(err) => return self.unsupported(callee.span, &err),
        };
        let Some((adt, _)) = self.tys().tcx().adt_of(t) else {
            return Ok(None);
        };
        let Some(idx) = adt
            .variants
            .iter()
            .position(|v| v.name == *var && v.fields.is_empty())
        else {
            return Ok(None);
        };
        let l = self.temp(t);
        let kind = self.adt_aggregate(t, idx as u32);
        self.assign(l, Rvalue::Aggregate(kind, Vec::new()));
        Ok(Some(match self.self_mode(f, mode, t) {
            SelfParam::Owned => Operand::Move(Place::local(l)),
            SelfParam::Ref => self.ref_to(Place::local(l), t),
            SelfParam::MutRef => {
                let rt = self.tys().tcx().reference(t, true);
                let r = self.temp(rt);
                self.assign(r, Rvalue::Ref(BorrowKind::Mut, Place::local(l)));
                Operand::Move(Place::local(r))
            }
        }))
    }

    /// The type a generic parameter named `name` has in this instance.
    fn type_param(&self, name: &str) -> Option<Ty> {
        let def = self.outer_fn.unwrap_or(self.b.instance().def);
        let item = self.lcx.fns.get(&def)?;
        let names = item
            .impl_generics
            .into_iter()
            .chain(item.f.generic_params.as_ref())
            .flat_map(|g| g.params.iter());
        let i = names.into_iter().position(|p| p.name == name)?;
        self.args.get(i).copied()
    }

    /// The type named `target` that a bare associated call `e` goes to: the
    /// call's own type when it names it (with its arguments), else the
    /// type by name.
    fn named_target(&mut self, e: &Expr, target: &str) -> R<Ty> {
        let t = self.expr_ty(e)?;
        let named = |d| self.lcx.def_name(d) == target;
        match self.tys().tcx().kind(t) {
            HK::Adt { def, .. } if named(def) => return Ok(t),
            _ => {}
        }
        let ty = Type::Named {
            name: target.to_string(),
            args: Vec::new(),
        };
        let args = self.args.clone();
        match self
            .lcx
            .lower_legacy(&ty, &[], None)
            .and_then(|h| self.lcx.mir_ty(h, &args))
        {
            Ok(t) => Ok(t),
            Err(err) => self.unsupported(e.span, &err),
        }
    }

    /// `T.make(args)` in a generic body: the impl's method for `T`'s type
    /// in this instance; for a primitive, its library function (`default`
    /// is zero).
    fn type_param_call(
        &mut self,
        e: &'a Expr,
        t: Ty,
        m: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        if let Some((d, inst_args)) = self.method_by_receiver(t, m) {
            let f = self.lcx.fns[&d].f;
            return self.def_call(e, d, f, inst_args, None, args, dest);
        }
        if let Some((d, inst_args)) = self.generic_fn_by_receiver(t, m, args)? {
            let f = self.lcx.fns[&d].f;
            return self.def_call(e, d, f, inst_args, None, args, dest);
        }
        let tcx = self.tys().tcx();
        let zero = match tcx.kind(t) {
            HK::Int(_) | HK::UInt(_) | HK::Bool | HK::Char => Some(ConstKind::Scalar(0)),
            HK::Float(_) => Some(ConstKind::Float(0f64.to_bits())),
            _ => None,
        };
        if let (Some(kind), "default", []) = (zero, m, args) {
            self.assign(dest, Rvalue::Use(Operand::Const(Const { ty: t, kind })));
            return Ok(());
        }
        // A library collection's or `String`'s default is its empty value.
        let empty =
            matches!(tcx.kind(t), HK::Intrinsic { .. }) || self.tys().display(t) == "String";
        if let (true, "default", []) = (empty, m, args) {
            let name = format!("{}.new", self.tys().display(t));
            self.call_native(&name, Vec::new(), dest);
            return Ok(());
        }
        let mut ops = Vec::new();
        for a in args {
            let at = self.expr_ty(&a.value)?;
            let by_ref = !self.is_copy(at);
            ops.push(self.lib_arg(&a.value, by_ref)?);
        }
        let name = format!("{}.{m}", self.tys().display(t));
        self.call_native(&name, ops, dest);
        Ok(())
    }

    /// A call of the program's function `d` (`f`) in instance `inst_args`,
    /// with `recv` before the arguments when a path names the receiver.
    #[allow(clippy::too_many_arguments)]
    fn def_call(
        &mut self,
        e: &'a Expr,
        d: DefId,
        f: &'a Function,
        inst_args: Vec<Ty>,
        recv: Option<Operand>,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        if args.len() != f.params.len() {
            return self.unsupported(e.span, "a call that leaves out default arguments");
        }
        let mut ops = Vec::new();
        let mut fn_tys: Vec<Option<Ty>> = Vec::new();
        for (a, p) in args.iter().zip(&f.params) {
            if (self.is_fn_typed(p.pattern.id) && !self.fn_param_owned(p))
                || self.ref_fn_param_takes_closure(&a.value, p)?
            {
                let want = self.generic_fn_param_want(&a.value, p, &inst_args)?;
                let (op, t) = self.fn_arg(&a.value, want, d5_params() && !p.is_own)?;
                ops.push(PendingRecv::Ready(op));
                fn_tys.push(Some(t));
                continue;
            }
            if let Some(op) = self.closure_for_param(&a.value, p, &inst_args)? {
                ops.push(PendingRecv::Ready(op));
                fn_tys.push(None);
                continue;
            }
            let pt = self.callee_param_ty(p, &inst_args)?;
            ops.push(self.arg_pending(&a.value, pt)?);
            fn_tys.push(None);
        }
        let mut ops = self.finish_args(ops)?;
        if let Some(r) = recv {
            ops.insert(0, r);
        }
        let name = if fn_tys.iter().any(Option::is_some) {
            self.lcx.instance_with_fns(d, inst_args.clone(), fn_tys)
        } else {
            self.lcx.instance(d, inst_args.clone())
        };
        if !self.lcx.fns.contains_key(&d) {
            self.queue_for_native(&name, &ops);
        }
        let func = self.fn_operand(&name, d, inst_args);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: ops,
                destination: dest,
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(())
    }

    /// A closure literal passed for a parameter whose type is a bare type
    /// parameter the checker solved to an erased `Fn(..)` (`f: own F` in
    /// `inspect`). The callee may keep it in what it returns, but that value
    /// is a local view (core semantics §9.2), so the closure does not escape
    /// (§9.3): it captures what it writes by `mut ref` (§9.1), and borrowck
    /// holds the loan for as long as the erased value lives.
    fn closure_for_param(
        &mut self,
        a: &'a Expr,
        p: &'a ast::Param,
        inst_args: &[Ty],
    ) -> R<Option<Operand>> {
        if !matches!(a.kind, ExprKind::Closure { .. }) {
            return Ok(None);
        }
        let Some(&pt) = self.lcx.node_types.get(&p.pattern.id) else {
            return Ok(None);
        };
        let HK::Param(param) = self.tys().tcx().kind(pt) else {
            return Ok(None);
        };
        let i = param.index as usize;
        let erased = inst_args
            .get(i)
            .is_some_and(|&t| matches!(self.tys().tcx().kind(t), HK::Fn { .. }));
        if !erased {
            return Ok(None);
        }
        self.closure_escapes = self.returned_closures.contains(&a.id);
        let (op, _) = self.closure_value(a)?;
        let l = self.temp(inst_args[i]);
        self.assign(l, Rvalue::Use(op));
        Ok(Some(Operand::Move(Place::local(l))))
    }

    /// The MIR types of a call's type arguments, in this instance.
    fn instance_args(&mut self, span: Span, substs: &[Ty]) -> R<Vec<Ty>> {
        let args = self.args.clone();
        let mut out = Vec::new();
        for &t in substs {
            match self.lcx.mir_ty(t, &args) {
                Ok(t) => out.push(t),
                Err(e) => return self.unsupported(span, &e),
            }
        }
        Ok(out)
    }

    fn callee_param_ty(&mut self, p: &'a ast::Param, inst_args: &[Ty]) -> R<Ty> {
        let Some(&t) = self.lcx.node_types.get(&p.pattern.id) else {
            return self.unsupported(p.span, "a parameter with no recorded type");
        };
        match self.lcx.mir_ty(t, inst_args) {
            Ok(t) => Ok(self.param_mode_ty(p, t)),
            Err(e) => self.unsupported(p.span, &e),
        }
    }

    /// A parameter's type as its body takes it. Under D5 a bare parameter
    /// of a non-`Copy` type borrows; `own T`, the written borrow forms and
    /// function values keep their type.
    fn param_mode_ty(&self, p: &ast::Param, t: Ty) -> Ty {
        if !d5_params() || p.is_own || self.is_copy(t) {
            return t;
        }
        let tcx = self.tys().tcx();
        match tcx.kind(t) {
            HK::Ref(_)
            | HK::MutRef(_)
            | HK::Slice { .. }
            | HK::Fn { .. }
            | HK::FnDef { .. }
            | HK::Closure { .. } => t,
            _ => tcx.reference(t, false),
        }
    }

    /// Whether `object.m()`, calling the impl method `d`, names a trait
    /// method declared `own self` through a generic receiver.
    fn moves_into_borrowing_impl(&self, object: &Expr, d: DefId) -> bool {
        let generic = self
            .lcx
            .node_types
            .get(&object.id)
            .is_some_and(|&t| matches!(self.tys().tcx().kind(t), HK::Param(_)));
        if !generic {
            return false;
        }
        let segs = &self.lcx.defs.table.get(d).path.segments;
        let n = segs.len();
        let Some(tr) = segs
            .get(n.wrapping_sub(2))
            .and_then(|l| l.strip_prefix("impl "))
            .and_then(|l| l.rsplit_once('#'))
            .map(|(t, _)| t)
        else {
            return false;
        };
        let tr = tr.split('[').next().unwrap_or(tr);
        self.lcx
            .own_self_trait_methods
            .contains(&(tr.to_string(), self.lcx.fns[&d].f.name.clone()))
    }

    /// The receiver mode a body takes: under D5 a bare `self` of a
    /// non-`Copy` type borrows (core semantics §8), and `own self` is owned.
    fn self_mode(&self, f: &ast::Function, mode: SelfParam, t: Ty) -> SelfParam {
        if mode == SelfParam::Owned && d5_params() && !f.self_is_own && !self.is_copy(t) {
            return SelfParam::Ref;
        }
        mode
    }

    /// Whether a function-typed parameter takes its function by value
    /// (`escaping Fn(..)`, core semantics §9.3): the callee may store it,
    /// so it is not specialised to the argument's closure.
    fn fn_param_owned(&self, p: &ast::Param) -> bool {
        self.lcx
            .escaping_fns
            .contains(&SpanKey::from_span(&p.ty.span))
    }

    /// An argument for a `mut ref` parameter whose borrow waits until every
    /// argument is evaluated (core semantics §5.6, two-phase borrows):
    /// `insert(nodes, nodes[root].left, v)` reads `nodes` before lending it.
    /// Any other argument is evaluated now.
    fn arg_pending(&mut self, a: &'a Expr, pt: Ty) -> R<PendingRecv<'a>> {
        if self.is_dyn_view(pt) && self.is_place(a) {
            if let Some(op) = self.place_into_dyn_view(a, pt)? {
                return Ok(PendingRecv::Ready(op));
            }
        }
        if let HK::MutRef(inner) = self.tys().tcx().kind(pt) {
            let slice = matches!(self.tys().tcx().kind(inner), HK::Slice { .. });
            if !slice && self.is_place(a) {
                let at = self.expr_ty(a)?;
                match self.tys().tcx().kind(at) {
                    HK::MutRef(_) => {
                        let p = self.expr_place(a, true)?.project(ProjElem::Deref);
                        let t = self.place_type(&p);
                        return Ok(PendingRecv::Borrow(p, t, true));
                    }
                    HK::Ref(_) => {}
                    _ => return self.recv_place(a, true),
                }
            }
        }
        Ok(PendingRecv::Ready(self.arg_operand(a, pt)?))
    }

    /// The arguments, with each waiting `mut ref` borrow taken last. An
    /// argument that still names a place is read into a temporary first,
    /// so the borrow does not cover the read.
    fn finish_args(&mut self, pending: Vec<PendingRecv<'a>>) -> R<Vec<Operand>> {
        let mut ops = Vec::with_capacity(pending.len());
        let mut later = Vec::new();
        for (i, p) in pending.into_iter().enumerate() {
            match p {
                PendingRecv::Ready(op) => ops.push(op),
                p => {
                    ops.push(unit_const(self.unit()));
                    later.push((i, p));
                }
            }
        }
        if later.is_empty() {
            return Ok(ops);
        }
        for (i, op) in ops.iter_mut().enumerate() {
            if later.iter().any(|(j, _)| *j == i) {
                continue;
            }
            let (Operand::Copy(p) | Operand::Move(p)) = op else {
                continue;
            };
            if p.projection.is_empty() && self.b.is_temp(p.local) {
                continue;
            }
            let t = self.place_type(p);
            let l = self.temp(t);
            let read = std::mem::replace(op, Operand::Move(Place::local(l)));
            self.assign(l, Rvalue::Use(read));
        }
        for (i, p) in later {
            ops[i] = self.recv_borrow(p)?;
        }
        Ok(ops)
    }

    /// An argument for a parameter of type `pt`: borrowed when the
    /// parameter is a reference and the argument is not. What it pushes,
    /// the borrow included, carries `a`'s span, so a borrow conflict names
    /// the argument, not the call (B-2026-10-25-7).
    fn arg_operand(&mut self, a: &'a Expr, pt: Ty) -> R<Operand> {
        let outer = self.b.source_info();
        self.b.set_source_info(SourceInfo {
            span: a.span,
            ..outer
        });
        let r = self.arg_operand_here(a, pt);
        self.b.set_source_info(outer);
        r
    }

    fn arg_operand_here(&mut self, a: &'a Expr, pt: Ty) -> R<Operand> {
        let tcx = self.tys().tcx();
        let borrow = match tcx.kind(pt) {
            HK::Ref(_) => Some(BorrowKind::Shared),
            HK::MutRef(_) => Some(BorrowKind::Mut),
            _ => None,
        };
        let at = self.expr_ty(a)?;
        if at != pt && self.fills_unit_holes(at, pt) {
            return self.operand_filling_holes(a, pt);
        }
        let slice_t = match self.tys().tcx().kind(pt) {
            HK::Ref(t) | HK::MutRef(t) => t,
            _ => pt,
        };
        if let HK::Slice { mutable, .. } = self.tys().tcx().kind(slice_t) {
            let reborrow = mutable
                && self.is_place(a)
                && matches!(self.strip_ty(at), HK::Slice { mutable: true, .. });
            if reborrow || !matches!(self.strip_ty(at), HK::Slice { .. }) {
                // A `Vec` or array passed for a slice: view it as one. A
                // `mut Slice` place is re-viewed, a reborrow, so the caller
                // keeps it.
                let s = self.slice_view(a, None, slice_t, mutable)?;
                return Ok(match borrow {
                    Some(kind) => {
                        let r = self.temp(pt);
                        self.assign(r, Rvalue::Ref(kind, Place::local(s)));
                        Operand::Move(Place::local(r))
                    }
                    None => Operand::Move(Place::local(s)),
                });
            }
        }
        // A `String` passed for a `Str` parameter is viewed, not moved
        // (core semantics §5.2).
        if matches!(self.tys().tcx().kind(pt), HK::StaticStr) {
            // A literal is a view of static text, with nothing to allocate,
            // whether check typed it `String` or, from the parameter, `Str`.
            if let ExprKind::StringLit(s) = &a.kind {
                return Ok(self.static_str(s));
            }
        }
        if matches!(self.tys().tcx().kind(pt), HK::StaticStr)
            && matches!(self.strip_ty(at), HK::Str)
        {
            let recv = self.recv_ref(a, false)?;
            let v = self.temp(pt);
            self.call_native("String.as_str", vec![recv], Place::local(v));
            return Ok(Operand::Move(Place::local(v)));
        }
        let arg_is_ref = matches!(self.tys().tcx().kind(at), HK::Ref(_) | HK::MutRef(_));
        // A `mut ref` place passed on is reborrowed, `&mut (*r)` (or `&(*r)`
        // for a `ref` parameter), so the caller keeps its reference.
        if let (Some(kind), HK::MutRef(_)) = (borrow, self.tys().tcx().kind(at)) {
            if self.is_place(a) {
                let p = self
                    .expr_place(a, kind == BorrowKind::Mut)?
                    .project(ProjElem::Deref);
                let r = self.temp(pt);
                self.assign(r, Rvalue::Ref(kind, p));
                return Ok(Operand::Move(Place::local(r)));
            }
        }
        if borrow == Some(BorrowKind::Shared) && !arg_is_ref {
            if let Some(op) = self.literal_ref(a, Some(pt))? {
                return Ok(op);
            }
        }
        match borrow {
            Some(kind) if !arg_is_ref => {
                let mut p = self.expr_place(a, kind == BorrowKind::Mut)?;
                if kind == BorrowKind::Shared && p.projection.is_empty() {
                    if let Some(v) = self.copy_views.get(&p.local) {
                        p = v.clone();
                    }
                }
                // A closure or function item held in a local, passed for a
                // borrowed function parameter (`apply(inner)`): the borrow
                // is of its erased value, made from a copy of it when it
                // can be copied, so the local stays usable.
                let fn_t = match self.tys().tcx().kind(pt) {
                    HK::Ref(t) | HK::MutRef(t) => t,
                    _ => pt,
                };
                let held = self.place_type(&p);
                // A narrower number lent to a wider one (`vc.contains(b)`,
                // `b: u8`, for a `ref f64`) widens into a temporary that is
                // lent instead (design.md §5, lossless widening).
                if kind == BorrowKind::Shared && self.lossless(held, fn_t) {
                    if let Some(cast) = self.widening(held, fn_t) {
                        let v = self.scoped_temp(fn_t);
                        self.assign(v, Rvalue::Cast(cast, Operand::Copy(p), fn_t));
                        let r = self.temp(pt);
                        self.assign(r, Rvalue::Ref(kind, Place::local(v)));
                        return Ok(Operand::Move(Place::local(r)));
                    }
                }
                if self.erases(&Operand::Copy(p.clone()), fn_t) {
                    let op = if self.is_copy(held) {
                        Operand::Copy(p)
                    } else {
                        Operand::Move(p)
                    };
                    let v = self.scoped_temp(fn_t);
                    self.assign(v, Rvalue::Use(op));
                    p = Place::local(v);
                }
                let r = self.temp(pt);
                self.assign(r, Rvalue::Ref(kind, p));
                Ok(Operand::Move(Place::local(r)))
            }
            // A tuple literal handed to a tuple of wider numbers is built
            // at the parameter's element types.
            None if matches!(a.kind, ExprKind::Tuple(_)) && at != pt => self.operand_at(a, pt),
            None => {
                let op = self.owned_operand(a, pt)?;
                if self.erases(&op, pt) {
                    // A closure or function item passed to an `escaping`
                    // function parameter, as the parameter's type.
                    let l = self.temp(pt);
                    let o = self.erase_source(op);
                    self.assign(l, Rvalue::Cast(CastKind::Erase, o, pt));
                    return Ok(Operand::Move(Place::local(l)));
                }
                Ok(self.widen(op, pt))
            }
            _ => self.expr_operand(a),
        }
    }

    /// `t` under any references, and its kind.
    fn strip_ty_full(&self, mut t: Ty) -> (HK, Ty) {
        loop {
            match self.tys().tcx().kind(t) {
                HK::Ref(inner) | HK::MutRef(inner) => t = inner,
                k => return (k, t),
            }
        }
    }

    /// The kind of `t` under any references.
    /// How many references `t` is under.
    fn ref_depth(&self, mut t: Ty) -> usize {
        let mut n = 0;
        while let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            t = inner;
            n += 1;
        }
        n
    }

    fn strip_ty(&self, mut t: Ty) -> HK {
        loop {
            match self.tys().tcx().kind(t) {
                HK::Ref(inner) | HK::MutRef(inner) => t = inner,
                k => return k,
            }
        }
    }

    /// A slice of type `slice_t` viewing the `Vec` or array `coll`, whole
    /// or (`range`) the part from `start` to `end`: the library's
    /// `as_slice` / `as_mut_slice`, or `slice` / `slice_mut` with `usize`
    /// bounds (an open end is the length).
    /// `op` read into a local of its own when it names a part of a value,
    /// so it outlives the scope that drops that value (`if mk(2).ok`;
    /// B-2026-10-14-64).
    fn read_before_drops(&mut self, op: Operand, t: Ty) -> Operand {
        match &op {
            Operand::Copy(p) | Operand::Move(p) if !p.projection.is_empty() => {
                let l = self.temp(t);
                self.assign(l, Rvalue::Use(op));
                Operand::Move(Place::local(l))
            }
            _ => op,
        }
    }

    /// A view of the whole of the collection at `p` (of type `ct`) as
    /// `slice_t`.
    fn slice_view_of(&mut self, p: Place, ct: Ty, slice_t: Ty, mutable: bool) -> Local {
        let rt = self.tys().tcx().reference(ct, mutable);
        let kind = if mutable {
            BorrowKind::Mut
        } else {
            BorrowKind::Shared
        };
        let name = self.tys().display(ct);
        let s = self.temp(slice_t);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(kind, p));
        let method = if mutable { "as_mut_slice" } else { "as_slice" };
        self.call_native(
            &format!("{name}.{method}"),
            vec![Operand::Move(Place::local(r))],
            Place::local(s),
        );
        s
    }

    /// The receiver a `Slice[T]` method of mode `mode` takes from the view
    /// `s`.
    fn slice_receiver(&mut self, s: Local, slice_t: Ty, mode: &SelfParam) -> Operand {
        match mode {
            SelfParam::Owned => Operand::Move(Place::local(s)),
            SelfParam::Ref | SelfParam::MutRef => {
                let mutable = matches!(mode, SelfParam::MutRef);
                let rt = self.tys().tcx().reference(slice_t, mutable);
                let r = self.temp(rt);
                let kind = if mutable {
                    BorrowKind::Mut
                } else {
                    BorrowKind::Shared
                };
                self.assign(r, Rvalue::Ref(kind, Place::local(s)));
                Operand::Move(Place::local(r))
            }
        }
    }

    /// `c[a..b] = other`: `other`'s elements copied into the range, which
    /// must be as long (design.md § Range indexing; B-2026-10-21-24). The
    /// range is viewed first, then the value, then each element is copied.
    fn range_assign(
        &mut self,
        target: &'a Expr,
        coll: &'a Expr,
        range: (Option<&'a Expr>, Option<&'a Expr>, bool),
        value: &'a Expr,
    ) -> R<()> {
        let ct = self.expr_ty(coll)?;
        let elem = match self.strip_ty(ct) {
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            } => self.tys().tcx().list(args)[0],
            HK::Array { elem, .. } | HK::Vector { elem, .. } | HK::Slice { elem, .. } => elem,
            _ => return self.unsupported(target.span, "assigning to this range"),
        };
        // Only a `Copy` element is copied in; `clone_from_slice` is the
        // spelling for the others.
        if !self.is_copy(elem) {
            return self.unsupported(target.span, "assigning a range of non-`Copy` elements");
        }
        let (dst_t, src_t, usize_t, bool_t) = {
            let tcx = self.tys().tcx();
            (
                tcx.intern(HK::Slice {
                    elem,
                    mutable: true,
                }),
                tcx.intern(HK::Slice {
                    elem,
                    mutable: false,
                }),
                tcx.intern(HK::UInt(UIntSize::Usize)),
                tcx.intern(HK::Bool),
            )
        };
        let dst = self.slice_view(coll, Some(range), dst_t, true)?;
        let (p, vt) = self.deref_place(value, false)?;
        let src = match self.tys().tcx().kind(vt) {
            HK::Slice { .. } => p,
            _ => Place::local(self.slice_view_of(p, vt, src_t, false)),
        };
        let src_ty = self.place_type(&src);
        let len = |bx: &mut Self, s: Place, st: Ty| {
            let rt = bx.tys().tcx().reference(st, false);
            let r = bx.temp(rt);
            bx.assign(r, Rvalue::Ref(BorrowKind::Shared, s));
            let n = bx.temp(usize_t);
            let name = bx.tys().display(st);
            bx.call_native(
                &format!("{name}.len"),
                vec![Operand::Move(Place::local(r))],
                Place::local(n),
            );
            n
        };
        let n = len(self, Place::local(dst), dst_t);
        let m = len(self, src.clone(), src_ty);
        let same = self.temp(bool_t);
        self.assign(
            same,
            Rvalue::BinaryOp(
                BinOp::Eq,
                Operand::Copy(Place::local(n)),
                Operand::Copy(Place::local(m)),
            ),
        );
        let ok = self.b.new_block();
        let bad = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(same)),
                targets: SwitchTargets::if_else(ok, bad),
            },
            bad,
        );
        let msg = self.static_str("range assignment: the value's length differs from the range's");
        let unit = self.tys().unit();
        let l = self.temp(unit);
        self.call_native("panic_message", vec![msg], Place::local(l));
        self.diverge(TerminatorKind::Abort {
            reason: AbortReason::Panic,
        });
        self.cur = ok;
        // for i in 0..n { dst[i] = src[i] }
        let i = self.temp(usize_t);
        self.assign(
            i,
            Rvalue::Use(Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(0),
            })),
        );
        let head = self.b.new_block();
        let body = self.b.new_block();
        let exit = self.b.new_block();
        self.goto(head);
        self.cur = head;
        let c = self.temp(bool_t);
        self.assign(
            c,
            Rvalue::BinaryOp(
                BinOp::Lt,
                Operand::Copy(Place::local(i)),
                Operand::Copy(Place::local(n)),
            ),
        );
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(body, exit),
            },
            body,
        );
        let (src_ref, dst_ref, er, emr) = {
            let tcx = self.tys().tcx();
            (
                tcx.reference(src_ty, false),
                tcx.reference(dst_t, true),
                tcx.reference(elem, false),
                tcx.reference(elem, true),
            )
        };
        let sname = self.tys().display(src_ty);
        let dname = self.tys().display(dst_t);
        let rs = self.temp(src_ref);
        self.assign(rs, Rvalue::Ref(BorrowKind::Shared, src.clone()));
        let from = self.temp(er);
        self.call_native(
            &format!("{sname}.index"),
            vec![
                Operand::Move(Place::local(rs)),
                Operand::Copy(Place::local(i)),
            ],
            Place::local(from),
        );
        let rd = self.temp(dst_ref);
        self.assign(rd, Rvalue::Ref(BorrowKind::Mut, Place::local(dst)));
        let to = self.temp(emr);
        self.call_native(
            &format!("{dname}.index_mut"),
            vec![
                Operand::Move(Place::local(rd)),
                Operand::Copy(Place::local(i)),
            ],
            Place::local(to),
        );
        self.assign(
            Place::local(to).project(ProjElem::Deref),
            Rvalue::Use(Operand::Copy(Place::local(from).project(ProjElem::Deref))),
        );
        let one = Operand::Const(Const {
            ty: usize_t,
            kind: ConstKind::Scalar(1),
        });
        self.assign(
            i,
            Rvalue::BinaryOp(BinOp::Add, Operand::Copy(Place::local(i)), one),
        );
        self.goto(head);
        self.cur = exit;
        Ok(())
    }

    fn slice_view(
        &mut self,
        coll: &'a Expr,
        range: Option<(Option<&'a Expr>, Option<&'a Expr>, bool)>,
        slice_t: Ty,
        mutable: bool,
    ) -> R<Local> {
        let p = self.expr_place(coll, mutable)?;
        let (p, ct) = self.strip_refs(p);
        let (rt, usize_t) = {
            let tcx = self.tys().tcx();
            (
                tcx.reference(ct, mutable),
                tcx.intern(HK::UInt(UIntSize::Usize)),
            )
        };
        let kind = if mutable {
            BorrowKind::Mut
        } else {
            BorrowKind::Shared
        };
        let name = self.tys().display(ct);
        let Some((start, end, inclusive)) = range else {
            return Ok(self.slice_view_of(p, ct, slice_t, mutable));
        };
        let s = self.temp(slice_t);
        let lo = match start {
            Some(x) => {
                let o = self.expr_operand(x)?;
                self.cast_index(o, usize_t)
            }
            None => Operand::Const(Const {
                ty: usize_t,
                kind: ConstKind::Scalar(0),
            }),
        };
        let hi = match end {
            // `a..=b` ends after `b`.
            Some(x) if inclusive => {
                let o = self.expr_operand(x)?;
                let o = self.cast_index(o, usize_t);
                let h = self.temp(usize_t);
                self.assign(
                    h,
                    Rvalue::BinaryOp(
                        BinOp::Add,
                        o,
                        Operand::Const(Const {
                            ty: usize_t,
                            kind: ConstKind::Scalar(1),
                        }),
                    ),
                );
                Operand::Copy(Place::local(h))
            }
            Some(x) => {
                let o = self.expr_operand(x)?;
                self.cast_index(o, usize_t)
            }
            None => {
                let shared = self.tys().tcx().reference(ct, false);
                let r = self.temp(shared);
                self.assign(r, Rvalue::Ref(BorrowKind::Shared, p.clone()));
                let n = self.temp(usize_t);
                self.call_native(
                    &format!("{name}.len"),
                    vec![Operand::Move(Place::local(r))],
                    Place::local(n),
                );
                Operand::Copy(Place::local(n))
            }
        };
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(kind, p));
        let method = if mutable { "slice_mut" } else { "slice" };
        self.call_native(
            &format!("{name}.{method}"),
            vec![Operand::Move(Place::local(r)), lo, hi],
            Place::local(s),
        );
        Ok(s)
    }

    /// `coll[r]` for a range value `r` (`let r = 1..3; v[r]`): the view
    /// `slice_view` makes for the range written out, its bounds read from
    /// `r`'s fields after `coll` is named.
    fn slice_view_by(&mut self, coll: &'a Expr, rng: &'a Expr, slice_t: Ty) -> R<Local> {
        let p = self.expr_place(coll, false)?;
        let (p, ct) = self.strip_refs(p);
        let rp = if self.is_place(rng) {
            self.expr_place(rng, false)?
        } else {
            let t = self.expr_ty(rng)?;
            Place::local(self.temp_of(rng, t)?)
        };
        let (rp, rt) = self.strip_refs(rp);
        let usize_t = self.tys().tcx().intern(HK::UInt(UIntSize::Usize));
        let inclusive = self
            .tys()
            .tcx()
            .adt_of(rt)
            .is_some_and(|(a, _)| a.name == "RangeInclusive");
        let bound = |bx: &mut Self, name: &str| {
            let (i, ft) = bx.field_of(rt, None, name)?;
            Some(bx.cast_index(Operand::Copy(rp.field(i, ft)), usize_t))
        };
        let lo = bound(self, "start").unwrap_or(Operand::Const(Const {
            ty: usize_t,
            kind: ConstKind::Scalar(0),
        }));
        let hi = bound(self, "end");
        let name = self.tys().display(ct);
        let hi = match hi {
            // `a..=b` ends after `b`.
            Some(o) if inclusive => {
                let h = self.temp(usize_t);
                let one = Operand::Const(Const {
                    ty: usize_t,
                    kind: ConstKind::Scalar(1),
                });
                self.assign(h, Rvalue::BinaryOp(BinOp::Add, o, one));
                Operand::Copy(Place::local(h))
            }
            Some(o) => o,
            None => {
                let shared = self.tys().tcx().reference(ct, false);
                let r = self.temp(shared);
                self.assign(r, Rvalue::Ref(BorrowKind::Shared, p.clone()));
                let n = self.temp(usize_t);
                self.call_native(
                    &format!("{name}.len"),
                    vec![Operand::Move(Place::local(r))],
                    Place::local(n),
                );
                Operand::Copy(Place::local(n))
            }
        };
        let s = self.temp(slice_t);
        let rt = self.tys().tcx().reference(ct, false);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
        self.call_native(
            &format!("{name}.slice"),
            vec![Operand::Move(Place::local(r)), lo, hi],
            Place::local(s),
        );
        Ok(s)
    }

    /// `swap(mut a, mut b)`, `replace(mut a, v)`, `take(mut a)` (`std.mem`):
    /// the library's moves through borrowed places, which MIR does not
    /// spell (a move out of `*r` is refused, core semantics §3.7). `take`
    /// is `replace` with the type's default.
    fn mem_call(&mut self, e: &'a Expr, name: &str, args: &'a [CallArg], dest: Place) -> R<bool> {
        let lend = |bx: &mut Self, a: &'a Expr| -> R<(Operand, Ty)> {
            let (p, t) = bx.deref_place(a, true)?;
            let rt = bx.tys().tcx().reference(t, true);
            let r = bx.temp(rt);
            bx.assign(r, Rvalue::Ref(BorrowKind::Mut, p));
            Ok((Operand::Move(Place::local(r)), t))
        };
        match (name, args) {
            ("swap", [a, b]) => {
                let (ra, _) = lend(self, &a.value)?;
                let (rb, _) = lend(self, &b.value)?;
                self.call_native("mem.swap", vec![ra, rb], dest);
                Ok(true)
            }
            ("replace", [a, v]) => {
                let (pa, t) = self.deref_place(&a.value, true)?;
                let op = self.operand_at(&v.value, t)?;
                let nv = self.temp(t);
                self.assign(nv, Rvalue::Use(op));
                let rt = self.tys().tcx().reference(t, true);
                let r = self.temp(rt);
                self.assign(r, Rvalue::Ref(BorrowKind::Mut, pa));
                let ops = vec![
                    Operand::Move(Place::local(r)),
                    Operand::Move(Place::local(nv)),
                ];
                self.call_native("mem.replace", ops, dest);
                Ok(true)
            }
            ("take", [a]) => {
                let (pa, t) = self.deref_place(&a.value, true)?;
                let nv = self.temp(t);
                self.type_param_call(e, t, "default", &[], Place::local(nv))?;
                let rt = self.tys().tcx().reference(t, true);
                let r = self.temp(rt);
                self.assign(r, Rvalue::Ref(BorrowKind::Mut, pa));
                let ops = vec![
                    Operand::Move(Place::local(r)),
                    Operand::Move(Place::local(nv)),
                ];
                self.call_native("mem.replace", ops, dest);
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    /// The prelude's `min(a, b)`, `max(a, b)` and `clamp(v, low, high)` on
    /// integers, chars and bools, in place until the library's Kāra bodies
    /// are lowered: `min` is `b` when `a > b`, else `a`; `max` is `b` when
    /// `a < b`, else `a`; `clamp` is `low` below it, `high` above it, else
    /// `v` (the bodies in `ordering.kara`). `false` for anything else.
    fn scalar_min_max(
        &mut self,
        e: &'a Expr,
        name: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        // Each step returns its bound when `value <op> bound` holds; the
        // value is the result when no step does. `clamp` takes `low` below
        // it, then `high` above it, so `low` wins when `low > high`.
        let (value, steps): (&CallArg, Vec<(BinOp, &CallArg)>) = match (name, args) {
            ("min", [a, b]) => (a, vec![(BinOp::Gt, b)]),
            ("max", [a, b]) => (a, vec![(BinOp::Lt, b)]),
            ("clamp", [v, lo, hi]) => (v, vec![(BinOp::Lt, lo), (BinOp::Gt, hi)]),
            _ => return Ok(false),
        };
        let t = self.expr_ty(e)?;
        if !matches!(
            self.tys().tcx().kind(t),
            HK::Int(_) | HK::UInt(_) | HK::Char | HK::Bool
        ) {
            return Ok(false);
        }
        let bool_t = self.tys().bool();
        let x = self.temp(t);
        let (o, _) = self.scalar_operand(&value.value)?;
        self.assign(x, Rvalue::Use(retype_const(o, t)));
        let mut bounds = Vec::new();
        for (op, b) in steps {
            let y = self.temp(t);
            let (o, _) = self.scalar_operand(&b.value)?;
            self.assign(y, Rvalue::Use(retype_const(o, t)));
            bounds.push((op, y));
        }
        let join = self.b.new_block();
        for (op, y) in bounds {
            let c = self.temp(bool_t);
            self.assign(
                c,
                Rvalue::BinaryOp(
                    op,
                    Operand::Copy(Place::local(x)),
                    Operand::Copy(Place::local(y)),
                ),
            );
            let take_bound = self.b.new_block();
            let next = self.b.new_block();
            self.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(c)),
                    targets: SwitchTargets::if_else(take_bound, next),
                },
                take_bound,
            );
            self.assign(dest.clone(), Rvalue::Use(Operand::Copy(Place::local(y))));
            self.goto(join);
            self.cur = next;
        }
        self.assign(dest, Rvalue::Use(Operand::Copy(Place::local(x))));
        self.goto(join);
        self.cur = join;
        Ok(true)
    }

    /// The library's `min`, `max` and `clamp` on any other `Ord` type, as
    /// their bodies in `ordering.kara` are: `min` keeps `a` unless `a > b`,
    /// `max` keeps `a` unless `a < b`, and `clamp` takes `low` below it and
    /// `high` above it. The argument not returned is dropped.
    fn ord_min_max(
        &mut self,
        e: &'a Expr,
        name: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        let t = self.expr_ty(e)?;
        if matches!(
            self.tys().tcx().kind(t),
            HK::Int(_) | HK::UInt(_) | HK::Char | HK::Float(_) | HK::Bool
        ) {
            return Ok(false);
        }
        let (_, [less, _, greater]) = match (name, args) {
            ("min" | "max", [_, _]) | ("clamp", [_, _, _]) => self.ordering_ty(e.span)?,
            _ => return Ok(false),
        };
        let join = self.b.new_block();
        match args {
            [a, b] => {
                let x = self.temp_of(&a.value, t)?;
                let y = self.temp_of(&b.value, t)?;
                let swap = if name == "min" { greater } else { less };
                let c = self.ord_is(e.span, x, y, t, swap)?;
                self.pick(c, y, x, &dest, join);
            }
            [v, lo, hi] => {
                let x = self.temp_of(&v.value, t)?;
                let l = self.temp_of(&lo.value, t)?;
                let h = self.temp_of(&hi.value, t)?;
                let below = self.ord_is(e.span, x, l, t, less)?;
                let (yes, no) = (self.b.new_block(), self.b.new_block());
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: Operand::Copy(Place::local(below)),
                        targets: SwitchTargets::if_else(yes, no),
                    },
                    yes,
                );
                self.assign(dest.clone(), Rvalue::Use(Operand::Move(Place::local(l))));
                self.goto(join);
                self.cur = no;
                let above = self.ord_is(e.span, x, h, t, greater)?;
                self.pick(above, h, x, &dest, join);
            }
            _ => unreachable!(),
        }
        self.cur = join;
        Ok(true)
    }

    /// `dest = p` as the raw pointer `e`'s type names: a borrow of the
    /// place, cast to a pointer that holds no loan.
    fn raw_ptr_to(&mut self, e: &'a Expr, p: Place, mutable: bool, dest: Place) -> R<()> {
        let pt = self.expr_ty(e)?;
        let target = self.place_type(&p);
        let rt = self.tys().tcx().reference(target, mutable);
        let r = self.temp(rt);
        let kind = if mutable {
            BorrowKind::Mut
        } else {
            BorrowKind::Shared
        };
        self.assign(r, Rvalue::Ref(kind, p));
        self.assign(
            dest,
            Rvalue::Cast(CastKind::RefToPtr, Operand::Move(Place::local(r)), pt),
        );
        Ok(())
    }

    /// The `ptr` module's address operations (design.md § Raw Pointer
    /// Construction): `ptr.null()` is address 0 and `ptr.dangling()` the
    /// pointee's alignment, `ptr.is_null(p)` compares with address 0, and
    /// `ptr.addr(p)` / `ptr.from_exposed(a)` cross between a pointer and
    /// its `usize` address.
    fn ptr_fn(&mut self, f: &str, args: &'a [CallArg], dest: Place) -> R<bool> {
        let tcx = self.tys().tcx();
        let usize_t = tcx.intern(HK::UInt(UIntSize::Usize));
        match (f, args) {
            ("null" | "null_mut" | "dangling" | "dangling_mut", []) => {
                let pt = self.place_type(&dest);
                let HK::RawPtr { pointee, .. } = tcx.kind(pt) else {
                    return Ok(false);
                };
                let a = self.temp(usize_t);
                let rv = if f.starts_with("null") {
                    Rvalue::Use(Operand::Const(Const {
                        ty: usize_t,
                        kind: ConstKind::Scalar(0),
                    }))
                } else {
                    Rvalue::NullaryOp(NullOp::AlignOf, pointee)
                };
                self.assign(a, rv);
                let op = Operand::Move(Place::local(a));
                self.assign(dest, Rvalue::Cast(CastKind::IntToPtr, op, pt));
            }
            ("is_null", [p]) => {
                let pt = self.expr_ty(&p.value)?;
                let op = self.expr_operand(&p.value)?;
                self.ptr_is_null(op, pt, dest);
            }
            ("addr" | "expose" | "expose_mut", [p]) => {
                let op = self.expr_operand(&p.value)?;
                let t = self.place_type(&dest);
                self.assign(dest, Rvalue::Cast(CastKind::PtrToInt, op, t));
            }
            ("from_exposed" | "from_exposed_mut", [a])
            | ("with_addr" | "with_addr_mut", [_, a]) => {
                let op = self.operand_at(&a.value, usize_t)?;
                let t = self.place_type(&dest);
                self.assign(dest, Rvalue::Cast(CastKind::IntToPtr, op, t));
            }
            _ => return Ok(false),
        }
        Ok(true)
    }

    /// Whether the raw pointer `p` (of type `pt`) is address 0.
    fn ptr_is_null(&mut self, p: Operand, pt: Ty, dest: Place) {
        let usize_t = self.tys().tcx().intern(HK::UInt(UIntSize::Usize));
        let zero = Operand::Const(Const {
            ty: usize_t,
            kind: ConstKind::Scalar(0),
        });
        let null = self.temp(pt);
        self.assign(null, Rvalue::Cast(CastKind::IntToPtr, zero, pt));
        self.assign(
            dest,
            Rvalue::BinaryOp(BinOp::Eq, p, Operand::Move(Place::local(null))),
        );
    }

    /// The inherent methods of a raw pointer (design.md § raw pointers):
    /// `p.read()` is `*p`, `p.write(v)` is `*p = v`, `p.offset(n)` (or
    /// `p.add(n)`) the pointer `n` pointees on, and `p.is_null()`.
    fn raw_ptr_method(
        &mut self,
        object: &'a Expr,
        method: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        let tcx = self.tys().tcx();
        let raw = |t: Option<&Ty>| t.is_some_and(|&t| matches!(tcx.kind(t), HK::RawPtr { .. }));
        if !raw(self.lcx.node_types.get(&object.id)) {
            return Ok(false);
        }
        let ot = self.expr_ty(object)?;
        match (method, args) {
            ("read" | "read_unaligned" | "read_volatile", []) => {
                let pp = self.expr_place(object, false)?.project(ProjElem::Deref);
                let t = self.place_type(&pp);
                let op = self.use_place(pp, t);
                self.assign(dest, Rvalue::Use(op));
            }
            ("write" | "write_unaligned" | "write_volatile", [v]) => {
                let pp = self.expr_place(object, false)?.project(ProjElem::Deref);
                self.expr_into(&v.value, pp)?;
                self.assign(dest, Rvalue::Use(unit_const(self.unit())));
            }
            ("offset" | "add", [n]) => {
                let p = self.expr_operand(object)?;
                let i64_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
                let n = self.operand_at(&n.value, i64_t)?;
                self.assign(dest, Rvalue::BinaryOp(BinOp::Offset, p, n));
            }
            ("is_null", []) => {
                let p = self.expr_operand(object)?;
                self.ptr_is_null(p, ot, dest);
            }
            _ => return Ok(false),
        }
        Ok(true)
    }

    /// `volatile_read(p)` is `*p`, and `volatile_write(p, v)` is `*p = v`.
    fn volatile_call(&mut self, name: &str, args: &'a [CallArg], dest: Place) -> R<bool> {
        match (name, args) {
            ("volatile_read", [p]) => {
                let pp = self.expr_place(&p.value, false)?.project(ProjElem::Deref);
                let t = self.place_type(&pp);
                let op = self.use_place(pp, t);
                self.assign(dest, Rvalue::Use(op));
                Ok(true)
            }
            ("volatile_write", [p, v]) => {
                let pp = self.expr_place(&p.value, false)?.project(ProjElem::Deref);
                self.expr_into(&v.value, pp)?;
                self.assign(dest, Rvalue::Use(unit_const(self.unit())));
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    /// Whether `x.cmp(y)` is the `Ordering` variant `variant`.
    fn ord_is(&mut self, span: Span, x: Local, y: Local, t: Ty, variant: u32) -> R<Local> {
        let (ot, _) = self.ordering_ty(span)?;
        let o = self.temp(ot);
        self.cmp_places(span, Place::local(x), Place::local(y), t, Place::local(o))?;
        let isize_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let disc = self.temp(isize_t);
        self.assign(disc, Rvalue::Discriminant(Place::local(o)));
        let c = self.temp(self.tys().bool());
        let want = Operand::Const(Const {
            ty: isize_t,
            kind: ConstKind::Scalar(variant as u128),
        });
        self.assign(
            c,
            Rvalue::BinaryOp(BinOp::Eq, Operand::Copy(Place::local(disc)), want),
        );
        Ok(c)
    }

    /// `dest = if c { yes } else { no }`, moving the one chosen; then `join`.
    fn pick(&mut self, c: Local, yes: Local, no: Local, dest: &Place, join: BasicBlock) {
        let (then_bb, else_bb) = (self.b.new_block(), self.b.new_block());
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(c)),
                targets: SwitchTargets::if_else(then_bb, else_bb),
            },
            then_bb,
        );
        self.assign(dest.clone(), Rvalue::Use(Operand::Move(Place::local(yes))));
        self.goto(join);
        self.cur = else_bb;
        self.assign(dest.clone(), Rvalue::Use(Operand::Move(Place::local(no))));
        self.goto(join);
    }

    /// `a.cmp(b)` on integers, `char` or `bool`: two comparisons choosing
    /// the `Ordering` variant.
    fn scalar_cmp(
        &mut self,
        e: &'a Expr,
        object: &'a Expr,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        let [b] = args else {
            return Ok(false);
        };
        let ot = self.expr_ty(object)?;
        let t = match self.tys().tcx().kind(ot) {
            HK::Ref(inner) | HK::MutRef(inner) => inner,
            _ => ot,
        };
        if !matches!(
            self.tys().tcx().kind(t),
            HK::Int(_) | HK::UInt(_) | HK::Char | HK::Bool
        ) {
            return Ok(false);
        }
        let ord = self.expr_ty(e)?;
        let Some((adt, _)) = self.tys().tcx().adt_of(ord) else {
            return Ok(false);
        };
        let variant = |name: &str| adt.variants.iter().position(|v| v.name == name);
        let (Some(less), Some(equal), Some(greater)) =
            (variant("Less"), variant("Equal"), variant("Greater"))
        else {
            return Ok(false);
        };
        let x = self.temp(t);
        let (o, _) = self.scalar_operand(object)?;
        self.assign(x, Rvalue::Use(o));
        let y = self.temp(t);
        let (o, _) = self.scalar_operand(&b.value)?;
        self.assign(y, Rvalue::Use(o));
        let bool_t = self.tys().bool();
        let join = self.b.new_block();
        let pick = |me: &mut Self, op: BinOp, variant: usize| {
            let c = me.temp(bool_t);
            let (xo, yo) = (
                Operand::Copy(Place::local(x)),
                Operand::Copy(Place::local(y)),
            );
            me.assign(c, Rvalue::BinaryOp(op, xo, yo));
            let yes = me.b.new_block();
            let no = me.b.new_block();
            me.goto_with(
                TerminatorKind::SwitchInt {
                    discr: Operand::Copy(Place::local(c)),
                    targets: SwitchTargets::if_else(yes, no),
                },
                yes,
            );
            let kind = me.adt_aggregate(ord, variant as u32);
            me.assign(dest.clone(), Rvalue::Aggregate(kind, Vec::new()));
            me.goto(join);
            me.cur = no;
        };
        pick(self, BinOp::Lt, less);
        pick(self, BinOp::Gt, greater);
        let kind = self.adt_aggregate(ord, equal as u32);
        self.assign(dest, Rvalue::Aggregate(kind, Vec::new()));
        self.goto(join);
        self.cur = join;
        Ok(true)
    }

    /// The base type of `t` when it is a `distinct type`.
    fn distinct_base(&self, t: Ty) -> Option<Ty> {
        let HK::Adt { def, .. } = self.tys().tcx().kind(t) else {
            return None;
        };
        let name = self.lcx.def_name(def);
        let tc = self.lcx.tc;
        if !tc.distinct_bases.contains_key(&name) || tc.struct_info.contains_key(&name) {
            return None;
        }
        self.tys().tcx().field_ty(t, None, 0)
    }

    /// `dest = T(v)` for the distinct type `t`.
    fn wrap_distinct(&mut self, t: Ty, v: Local, dest: Place) {
        self.assign(
            dest,
            Rvalue::Aggregate(
                AggregateKind::Adt {
                    ty: t,
                    variant: VariantIdx(0),
                },
                vec![Operand::Move(Place::local(v))],
            ),
        );
    }

    /// The assertion builtin `e` calls, if any. The checker records the
    /// call's type as an error; its value is `()`.
    fn assert_builtin(&self, e: &Expr) -> Option<&'static str> {
        if !matches!(e.kind, ExprKind::Call { .. }) {
            return None;
        }
        match &self.lcx.calls.get(&e.id)?.callee {
            Callee::Builtin(n) => ["assert", "assert_eq", "assert_ne"]
                .into_iter()
                .find(|a| a == n),
            _ => None,
        }
    }

    /// `i64.add(a, b)`, `f16.lt(a, b)`, `String.add(a, b)`: an operator
    /// trait's method named through a library type is the operator.
    fn operator_call(
        &mut self,
        owner: &str,
        method: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        let [l, r] = args else {
            if let [a] = args {
                if owner != "String" {
                    return self.unary_operator_call(method, &a.value, dest);
                }
            }
            return Ok(false);
        };
        let primitive = matches!(
            owner,
            "i8" | "i16"
                | "i32"
                | "i64"
                | "i128"
                | "isize"
                | "u8"
                | "u16"
                | "u32"
                | "u64"
                | "u128"
                | "usize"
                | "f16"
                | "bf16"
                | "f32"
                | "f64"
                | "bool"
                | "char"
                | "String"
        );
        let Some(op) = operator_method(method) else {
            return Ok(false);
        };
        if !primitive {
            return Ok(false);
        }
        self.binary(op, &l.value, &r.value, dest)?;
        Ok(true)
    }

    /// `a.neg()`, `a.not()` of a primitive, or `i64.neg(a)`: the unary
    /// operator, `-a` and `~a` (or `not a` of a `bool`).
    fn unary_operator_call(&mut self, method: &str, a: &'a Expr, dest: Place) -> R<bool> {
        let mop = match method {
            "neg" => UnOp::Neg,
            "not" => UnOp::Not,
            _ => return Ok(false),
        };
        let t = self.expr_ty(a)?;
        let (_, base) = self.strip_ty_full(t);
        if !matches!(
            self.tys().tcx().kind(base),
            HK::Int(_) | HK::UInt(_) | HK::Float(_) | HK::Bool
        ) {
            return Ok(false);
        }
        let (o, _) = self.scalar_operand(a)?;
        self.assign(dest, Rvalue::UnaryOp(mop, o));
        Ok(true)
    }

    fn builtin_call(&mut self, e: &'a Expr, name: &str, args: &'a [CallArg], dest: Place) -> R<()> {
        if let Some((owner, method)) = name.split_once('.') {
            if self.operator_call(owner, method, args, dest.clone())? {
                return Ok(());
            }
            if let ("try_from", [a]) = (method, args) {
                if self.lcx.refined.contains_key(owner) {
                    return self.refinement_try_from(e, owner, &a.value, dest);
                }
            }
            // `Vec.try_from_slice(src)`, `String.try_with_capacity(n)`: the
            // constructor they are the fallible companions of, as an `Ok`
            // (an allocation here does not fail).
            let base = crate::fallible_alloc::static_companion_base(method);
            if let Some(base @ ("with_capacity" | "from_slice")) = base {
                let rt = self.expr_ty(e)?;
                let tcx = self.tys().tcx();
                let ok = tcx
                    .adt_of(rt)
                    .and_then(|(adt, _)| adt.variants.iter().position(|v| v.name == "Ok"))
                    .map(|i| i as u32);
                if let Some((idx, pt)) = ok.and_then(|i| Some((i, tcx.field_ty(rt, Some(i), 0)?))) {
                    let mut ops = Vec::new();
                    for a in args {
                        ops.push(self.expr_operand(&a.value)?);
                    }
                    let ty_name = self.tys().display(pt);
                    // `with_capacity` of a `Vec`, `String` or `VecDeque` can
                    // fail, so it is its own native, which writes the
                    // `Result` (B-2026-10-21-28).
                    if base == "with_capacity"
                        && matches!(
                            self.tys().kind(pt),
                            super::ty::TyKind::Intrinsic(
                                super::ty::IntrinsicTy::Vec(_)
                                    | super::ty::IntrinsicTy::String
                                    | super::ty::IntrinsicTy::VecDeque(_)
                            )
                        )
                    {
                        self.call_native(&format!("{ty_name}.try_with_capacity"), ops, dest);
                        return Ok(());
                    }
                    let built = self.temp(pt);
                    self.call_native(&format!("{ty_name}.{base}"), ops, Place::local(built));
                    self.build_variant(rt, idx, vec![Operand::Move(Place::local(built))], dest);
                    return Ok(());
                }
            }
        }
        match name {
            "println" | "print" | "eprintln" | "eprint" => {
                let mut ops = Vec::new();
                for a in args {
                    self.print_operands(&a.value, &mut ops)?;
                }
                // A program that overrides the stream calls it through its
                // provider (§14.10), a placeholder until specialisation.
                let (r, m) = match name {
                    "println" => ("Stdout", "println"),
                    "print" => ("Stdout", "print"),
                    "eprintln" => ("Stderr", "println"),
                    _ => ("Stderr", "print"),
                };
                if self.resource_via_provider(r) {
                    self.ensure_resource(r)?;
                    self.call_native(&format!("{r}.{m}"), ops, dest);
                    return Ok(());
                }
                self.call_native(name, ops, dest);
                Ok(())
            }
            "panic" | "todo" | "unimplemented" | "unreachable" => {
                // The message is shown when the run aborts.
                let mut ops = Vec::new();
                for a in args {
                    self.print_operands(&a.value, &mut ops)?;
                }
                // Legacy's wording: `todo`, `unimplemented` and `unreachable`
                // put their own words before any message.
                let default = match name {
                    "panic" => None,
                    "todo" => Some("not yet implemented"),
                    _ => Some("entered unreachable code"),
                };
                if let Some(d) = default {
                    let head = match ops.is_empty() {
                        true => d.to_string(),
                        false => format!("{d}: "),
                    };
                    ops.insert(0, self.static_str(&head));
                }
                if !ops.is_empty() {
                    let unit = self.tys().unit();
                    let l = self.temp(unit);
                    self.call_native("panic_message", ops, Place::local(l));
                }
                self.diverge(TerminatorKind::Abort {
                    reason: AbortReason::Panic,
                });
                Ok(())
            }
            // `assert(c)`, `assert_eq(a, b)`, `assert_ne(a, b)`: a test, and a
            // panic when it fails.
            "assert" | "assert_eq" | "assert_ne" => {
                let bool_t = self.tys().bool();
                let ok = self.temp(bool_t);
                // What `assert_eq` and `assert_ne` show when they fail.
                let mut sides = Vec::new();
                match (name, args) {
                    ("assert", [c, ..]) => {
                        let c = self.operand_at(&c.value, bool_t)?;
                        self.assign(Place::local(ok), Rvalue::Use(c));
                    }
                    (_, [a, b]) => {
                        let base = |s: &mut Self, x: &Expr| -> R<Ty> {
                            let t = s.expr_ty(x)?;
                            Ok(match s.tys().tcx().kind(t) {
                                HK::Ref(t) | HK::MutRef(t) => t,
                                _ => t,
                            })
                        };
                        let (lt, rt) = (base(self, &a.value)?, base(self, &b.value)?);
                        let int = |s: &Self, t: Ty| {
                            matches!(s.tys().tcx().kind(t), HK::Int(_) | HK::UInt(_))
                        };
                        // `assert_eq(e.step(), None)`: a variant written
                        // without its arguments is the same type, with what
                        // it does not name left open, and `==` meets them as
                        // it does outside an assertion.
                        let adt = |s: &Self, t: Ty| match s.tys().tcx().kind(t) {
                            HK::Adt { def, .. } => Some(def),
                            _ => None,
                        };
                        // The open side is the one the checker left a `()`
                        // argument in; it is built at the other side's type.
                        let holes = |s: &Self, t: Ty| match s.tys().tcx().kind(t) {
                            HK::Adt { args, .. } => s
                                .tys()
                                .tcx()
                                .list(args)
                                .iter()
                                .any(|&a| matches!(s.tys().tcx().kind(a), HK::Unit)),
                            _ => false,
                        };
                        let open = match (holes(self, lt), holes(self, rt)) {
                            (false, true) => Some((&a.value, &b.value, lt, false)),
                            (true, false) => Some((&b.value, &a.value, rt, true)),
                            _ => None,
                        };
                        let same_adt = adt(self, lt).is_some() && adt(self, lt) == adt(self, rt);
                        let ne = name == "assert_ne";
                        if lt != rt && same_adt {
                            let Some((shut, open, t, open_left)) = open else {
                                return self.unsupported(e.span, &format!("`{name}` of two types"));
                            };
                            let sp = self.expr_place(shut, false)?;
                            let (sp, _) = self.strip_refs(sp);
                            let o = self.operand_at(open, t)?;
                            let op = self.temp(t);
                            self.assign(Place::local(op), Rvalue::Use(o));
                            let (lp, rp) = match open_left {
                                true => (Place::local(op), sp),
                                false => (sp, Place::local(op)),
                            };
                            sides.push(AssertSide::Place(lp.clone(), t));
                            sides.push(AssertSide::Place(rp.clone(), t));
                            let eq = self.temp(bool_t);
                            self.eq_places(e.span, lp, rp, t, Place::local(eq))?;
                            let v = Operand::Move(Place::local(eq));
                            let v = match ne {
                                true => Rvalue::UnaryOp(UnOp::Not, v),
                                false => Rvalue::Use(v),
                            };
                            self.assign(Place::local(ok), v);
                        } else if lt != rt && !(int(self, lt) && int(self, rt)) {
                            // Integers of two widths meet at the wider one;
                            // any other pair of types has no `==`.
                            return self.unsupported(e.span, &format!("`{name}` of two types"));
                        } else {
                            // Each operand is evaluated once, before the
                            // comparison, so the message reads the values
                            // it compared.
                            self.pin_operand(&a.value)?;
                            self.pin_operand(&b.value)?;
                            sides.push(AssertSide::Expr(&a.value));
                            sides.push(AssertSide::Expr(&b.value));
                            self.binary(
                                if ne { AstBinOp::NotEq } else { AstBinOp::Eq },
                                &a.value,
                                &b.value,
                                Place::local(ok),
                            )?;
                        }
                    }
                    _ => {
                        return self.unsupported(e.span, &format!("`{name}` without its operands"))
                    }
                }
                let pass = self.b.new_block();
                let fail = self.b.new_block();
                self.goto_with(
                    TerminatorKind::SwitchInt {
                        discr: Operand::Copy(Place::local(ok)),
                        targets: SwitchTargets::if_else(pass, fail),
                    },
                    fail,
                );
                // Legacy's message: `assert`'s literal one if it has one.
                // `assert_eq` adds both operands' `Debug` text and
                // `assert_ne` the one value (design.md § Assertions).
                let msg = match (name, args.get(1).map(|a| &a.value.kind)) {
                    ("assert", Some(ExprKind::StringLit(m))) => m.as_str(),
                    ("assert", _) => "assertion failed",
                    ("assert_eq", _) => "assertion failed: left != right",
                    _ => "assertion failed: left == right",
                };
                let mut ops = vec![self.static_str(msg)];
                let labels: &[&str] = match name {
                    "assert_eq" => &["\n  left:  ", "\n  right: "],
                    _ => &["\n  value: "],
                };
                for (side, label) in sides.iter().zip(labels) {
                    ops.push(self.static_str(label));
                    let op = self.assert_side_debug(side)?;
                    ops.push(op);
                }
                for a in args {
                    self.pinned.remove(&a.value.id);
                }
                let unit_t = self.tys().unit();
                let l = self.temp(unit_t);
                self.call_native("panic_message", ops, Place::local(l));
                self.diverge(TerminatorKind::Abort {
                    reason: AbortReason::Panic,
                });
                self.cur = pass;
                let unit = self.unit();
                self.assign(dest, Rvalue::Use(unit_const(unit)));
                Ok(())
            }
            // `dbg(e)`: `e`'s value, after the library's `dbg` writes
            // `[file:line] e = <value>` to stderr.
            "dbg" => {
                let [a] = args else {
                    return self.unsupported(e.span, "`dbg` of other than one value");
                };
                self.expr_into(&a.value, dest.clone())?;
                let t = self.place_type(&dest);
                let value = self.ref_to(dest, t);
                self.dbg_print(e, &a.value, value);
                Ok(())
            }
            // `Vector[f32, 4](a, b, c, d)`: the lanes, as an array's
            // elements.
            "Vector" => {
                let t = self.expr_ty(e)?;
                let HK::Vector { elem, .. } = self.tys().tcx().kind(t) else {
                    return self.unsupported(e.span, "a `Vector` of no lane type");
                };
                let mut ops = Vec::with_capacity(args.len());
                for a in args {
                    ops.push(self.operand_at(&a.value, elem)?);
                }
                self.assign(dest, Rvalue::Aggregate(AggregateKind::Array(elem), ops));
                Ok(())
            }
            // `Vec.new()`, `String.new()`, `Map.new()`, `Vec.with_capacity(n)`:
            // a library constructor, named after the type it builds.
            // `String.from(x)`: a literal is passed as the constant; a
            // `String` value is already the result.
            // `String.from('Z')`: the one-character string.
            "String.from"
                if args.len() == 1
                    && self
                        .expr_ty(&args[0].value)
                        .is_ok_and(|t| matches!(self.tys().tcx().kind(t), HK::Char)) =>
            {
                let op = self.expr_operand(&args[0].value)?;
                self.call_native("char.to_string", vec![op], dest);
                Ok(())
            }
            "String.from"
                if args.len() == 1
                    && (matches!(args[0].value.kind, ExprKind::StringLit(_))
                        || self.lcx.node_types.get(&args[0].value.id)
                            == Some(&self.place_type(&dest))) =>
            {
                match &args[0].value.kind {
                    ExprKind::StringLit(s) => {
                        let c = self.static_str(s);
                        self.call_native(name, vec![c], dest);
                        Ok(())
                    }
                    _ => self.expr_into(&args[0].value, dest),
                }
            }
            _ if name.contains('.') => {
                let (owner, m) = name.rsplit_once('.').unwrap();
                // `x.unwrap_or(Vec.new())`: a constructor whose type the
                // checker left to its context has its destination's.
                let t = if self.lcx.node_types.contains_key(&e.id)
                    || self.ty_hints.contains_key(&e.id)
                {
                    self.expr_ty(e)?
                } else {
                    self.place_type(&dest)
                };
                let mut ty_name = self.tys().display(t);
                // `Channel.new()` builds a `(Sender[T], Receiver[T])` pair:
                // named `Channel[T].new`.
                if owner == "Channel" {
                    if let HK::Tuple(parts) = self.tys().tcx().kind(t) {
                        let parts = self.tys().tcx().list(parts);
                        if let Some(&s) = parts.first() {
                            let shown = self.tys().display(s);
                            if let Some(args) = shown.strip_prefix("Sender") {
                                ty_name = format!("Channel{args}");
                            }
                        }
                    }
                }
                if ty_name.split('[').next() != Some(owner) {
                    // A library function that builds something else
                    // (`String.from_utf8` returns a `Result`): named by
                    // its owner alone.
                    if !matches!(owner, "String" | "char" | "CStr") {
                        return self.unsupported(e.span, &format!("the builtin `{name}`"));
                    }
                    ty_name = owner.to_string();
                }
                // `Vec.from_fn(n, f)` calls `f` before it returns and keeps
                // nothing of it, so its closure borrows what it captures, as
                // a method native's does (B-2026-10-22-1).
                let calls_in_place = m == "from_fn" && matches!(owner, "Vec" | "Array");
                // `Vec.filled(n, None)`: the value is built at the element
                // type the call's own type names.
                let elem = match self.tys().tcx().kind(t) {
                    HK::Intrinsic { args: ea, .. } if m == "filled" => {
                        self.tys().tcx().list(ea).first().copied()
                    }
                    _ => None,
                };
                let mut ops = Vec::new();
                for (i, a) in args.iter().enumerate() {
                    if calls_in_place && matches!(a.value.kind, ExprKind::Closure { .. }) {
                        ops.push(self.fn_value(&a.value)?.0);
                        continue;
                    }
                    ops.push(match elem {
                        Some(el) if i == 1 => self.operand_filling_holes(&a.value, el)?,
                        _ => self.expr_operand(&a.value)?,
                    });
                }
                self.call_native(&format!("{ty_name}.{m}"), ops, dest);
                Ok(())
            }
            _ => self.unsupported(e.span, &format!("the builtin `{name}`")),
        }
    }

    /// The operands `print` shows for one argument: an f-string's parts one
    /// after another, a string literal as a constant, a non-`Copy` value
    /// by reference.
    fn print_operands(&mut self, a: &'a Expr, ops: &mut Vec<Operand>) -> R<()> {
        match &a.kind {
            ExprKind::StringLit(s) => {
                ops.push(self.static_str(s));
                Ok(())
            }
            ExprKind::InterpolatedStringLit(parts) => {
                for p in parts {
                    match p {
                        ParsedInterpolationPart::Text(s) => ops.push(self.static_str(s)),
                        ParsedInterpolationPart::Expr(x, None) => self.print_operands(x, ops)?,
                        ParsedInterpolationPart::Expr(x, Some(spec)) => {
                            // `{x:.3}`: the library's `format_spec` renders
                            // the value by the spec into a String the
                            // statement drops.
                            let mut inner = Vec::new();
                            self.print_operands(x, &mut inner)?;
                            inner.push(self.static_str(spec));
                            let st = self.tys().tcx().intern(HK::Str);
                            let s = self.scoped_temp(st);
                            self.call_native("format_spec", inner, Place::local(s));
                            ops.push(self.ref_to(Place::local(s), st));
                        }
                    }
                }
                Ok(())
            }
            _ => {
                let t = self.expr_ty(a)?;
                let (_, base) = self.strip_ty_full(t);
                let dyn_display = self.dyn_under(t).filter(|&d| {
                    self.dyn_slots(d)
                        .iter()
                        .any(|(tr, m)| tr == "Display" && m.name == "to_string")
                });
                if dyn_display.is_some() {
                    // A `dyn` value of `Display` prints through its
                    // `to_string` slot, into a String the statement drops.
                    let st = self.tys().tcx().intern(HK::Str);
                    let s = self.scoped_temp(st);
                    self.dyn_method_call(a, "to_string", &[], Place::local(s))?;
                    ops.push(self.ref_to(Place::local(s), st));
                } else if let Some((d, args)) = self.user_impl_method(base, "Display", "to_string")
                {
                    // A user type prints through its `Display`: its
                    // `to_string` into a String the statement drops.
                    let p = self.expr_place(a, false)?;
                    let (p, base) = self.strip_refs(p);
                    let recv = self.ref_to(p, base);
                    let st = self.tys().tcx().intern(HK::Str);
                    let s = self.scoped_temp(st);
                    let name = self.lcx.instance(d, args.clone());
                    let func = self.fn_operand(&name, d, args);
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Call {
                            func,
                            args: vec![recv],
                            destination: Place::local(s),
                            target: Some(next),
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                    ops.push(self.ref_to(Place::local(s), st));
                } else if self.is_copy(t) {
                    self.queue_nested_displays(t);
                    ops.push(self.expr_operand(a)?);
                } else {
                    self.queue_nested_displays(t);
                    let p = self.expr_place(a, false)?;
                    let rt = self.tys().tcx().reference(t, false);
                    let r = self.temp(rt);
                    self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
                    ops.push(Operand::Move(Place::local(r)));
                }
                Ok(())
            }
        }
    }

    fn method_call(
        &mut self,
        e: &'a Expr,
        object: &'a Expr,
        method: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        if self.comptime_native(e, &dest)? {
            return Ok(());
        }
        if self.dyn_method_call(object, method, args, dest.clone())? {
            return Ok(());
        }
        // `slot.upgrade()` on a `weak` slot: the checker typed it as the
        // slot's read, an `Option`, and the read upgrades (design.md § Cycles
        // and `weak`; B-2026-10-26-4). An `Option` has no `upgrade` of its own.
        if method == "upgrade" && args.is_empty() {
            let t = self.expr_ty(object)?;
            if let HK::Adt { def, .. } = self.tys().tcx().kind(t) {
                if self.lcx.def_name(def) == "Option" {
                    return self.expr_into(object, dest);
                }
            }
        }
        // `critical_section.acquire()`: the guard whose drop ends the
        // section. Interrupts are not masked here, so it holds no token.
        if let (ExprKind::Identifier(m), "acquire", []) = (&object.kind, method, args) {
            if m == "critical_section"
                && !matches!(self.lcx.res.get(&object.id), Some(Res::Local(_)))
            {
                let t = self.expr_ty(e)?;
                let kind = self.adt_aggregate(t, 0);
                let zero = Operand::Const(Const {
                    ty: self.tys().tcx().intern(HK::Int(IntSize::I64)),
                    kind: ConstKind::Scalar(0),
                });
                self.assign(dest, Rvalue::Aggregate(kind, vec![zero]));
                return Ok(());
            }
        }
        // `ptr.mut(x)` / `ptr.const(x)`: a raw pointer to the place `x`.
        if let (ExprKind::Identifier(m), "mut" | "const", [a]) = (&object.kind, method, args) {
            if m == "ptr" && !matches!(self.lcx.res.get(&object.id), Some(Res::Local(_))) {
                let p = self.expr_place(&a.value, method == "mut")?;
                return self.raw_ptr_to(e, p, method == "mut", dest);
            }
        }
        // `ptr.null()`, `ptr.is_null(p)`, `ptr.addr(p)`, ...
        if let ExprKind::Identifier(m) = &object.kind {
            if m == "ptr"
                && !matches!(self.lcx.res.get(&object.id), Some(Res::Local(_)))
                && self.ptr_fn(method, args, dest.clone())?
            {
                return Ok(());
            }
        }
        if self.raw_ptr_method(object, method, args, dest.clone())? {
            return Ok(());
        }
        // `a.as_ptr()` / `a.as_mut_ptr()` of an array: a raw pointer to its
        // first element.
        if let ("as_ptr" | "as_mut_ptr", []) = (method, args) {
            let ot = self.expr_ty(object)?;
            let (_, base) = self.strip_ty_full(ot);
            if matches!(self.tys().tcx().kind(base), HK::Array { .. }) {
                let mutable = method == "as_mut_ptr";
                let (p, _) = self.deref_place(object, mutable)?;
                return self.raw_ptr_to(e, p.project(ProjElem::ConstIndex(0)), mutable, dest);
            }
        }
        if let ExprKind::Identifier(r) = &object.kind {
            if self.resource_via_provider(r)
                && !matches!(self.lcx.res.get(&object.id), Some(Res::Local(_)))
            {
                return self.resource_call(e, r, method, args, dest);
            }
        }
        if let Some(resource) = self
            .ambient_module(object)
            .filter(|r| self.resource_via_provider(r))
        {
            return self.resource_call(e, resource, method, args, dest);
        }
        if let Some(resource) = self.ambient_module(object) {
            // `env.args()`, `clock.now()`, …: a call of the ambient
            // resource's library method, `Env.args`, or of its provider's.
            // Copy arguments go by value, the rest by reference.
            let mut ops = Vec::new();
            for a in args {
                let t = self.expr_ty(&a.value)?;
                let by_ref = !self.is_copy(t);
                ops.push(self.lib_arg(&a.value, by_ref)?);
            }
            let name = match self.provider_recv(resource)? {
                Some((provider, recv)) => {
                    ops.insert(0, recv);
                    format!("{provider}.{method}")
                }
                None => format!("{resource}.{method}"),
            };
            self.call_native(&name, ops, dest);
            return Ok(());
        }
        if let Some(owner) = self.primitive_owner(object) {
            if self.operator_call(owner, method, args, dest.clone())? {
                return Ok(());
            }
            // `i64.zero()` of the program's `impl Zero for i64` or
            // `impl i64 { fn zero() }`: its own function.
            if let Some(rc) = self.lcx.calls.get(&e.id) {
                if let Callee::Def(d) = rc.callee {
                    if let Some(f) = self.lcx.fns.get(&d).map(|i| i.f) {
                        let substs = self.lcx.tys.tcx().list(rc.substs);
                        let inst_args = self.instance_args(e.span, &substs)?;
                        return self.def_call(e, d, f, inst_args, None, args, dest);
                    }
                }
            }
            // `i64.default()`: the type's zero (B-2026-10-13-27).
            if let ("default", []) = (method, args) {
                let t = self.expr_ty(e)?;
                return self.type_param_call(e, t, method, args, dest);
            }
            if let ("parse", [a]) = (method, args) {
                let t = self.expr_ty(e)?;
                if self.parse_result_call(owner, &a.value, t, dest.clone())? {
                    return Ok(());
                }
            }
            // `char.try_from(x)` of a borrowed integer reads the value
            // (B-2026-10-18-33).
            if let ("char", "try_from", [a]) = (owner, method, args) {
                let t = self.expr_ty(&a.value)?;
                if let HK::Ref(inner) = self.tys().tcx().kind(t) {
                    let op = self.owned_operand(&a.value, inner)?;
                    self.call_native("char.try_from", vec![op], dest);
                    return Ok(());
                }
            }
            // `i64.parse(s)`, `f64.parse(s)`: a library function of a
            // primitive type, named after it. Copy arguments go by value,
            // the rest by reference.
            let mut ops = Vec::new();
            for a in args {
                let t = self.expr_ty(&a.value)?;
                let by_ref = !self.is_copy(t);
                ops.push(self.lib_arg(&a.value, by_ref)?);
            }
            self.call_native(&format!("{owner}.{method}"), ops, dest);
            return Ok(());
        }
        if let ExprKind::Path {
            segments,
            generic_args: Some(_),
        } = &object.kind
        {
            if segments.len() == 1 && segments[0] == "Vector" {
                // `Vector[f32, 4].splat(x)`, `.from_array([..])`: a library
                // constructor of the vector type the call builds.
                let t = self.expr_ty(e)?;
                let elem = match self.tys().tcx().kind(t) {
                    HK::Vector { elem, .. } => elem,
                    _ => return self.unsupported(e.span, "a `Vector` constructor of no lane type"),
                };
                let mut ops = Vec::with_capacity(args.len());
                for a in args {
                    ops.push(match method {
                        "splat" => self.operand_at(&a.value, elem)?,
                        _ => self.expr_operand(&a.value)?,
                    });
                }
                let name = format!("{}.{method}", self.tys().display(t));
                self.call_native(&name, ops, dest);
                return Ok(());
            }
        }
        // `Ho[R].Full(x)`, `Vec[i64].new()`: a type named with its
        // arguments, then one of its associated functions, which is the call
        // `Ho.Full(x)` spelled without them.
        if let ExprKind::Path {
            segments,
            generic_args: Some(_),
        } = &object.kind
        {
            if segments.len() == 1 && self.lcx.calls.contains_key(&e.id) {
                return self.call(e, object, args, dest);
            }
        }
        if method == "into" && args.is_empty() {
            let user = matches!(
                self.lcx.calls.get(&e.id).map(|rc| &rc.callee),
                Some(Callee::Def(d)) if self.lcx.fns.contains_key(d)
            );
            if !user && self.conversion_call(e, object, dest.clone())? {
                return Ok(());
            }
        }
        // `n.try_into()` between integers: the target's `try_from`, the
        // target being the `Ok` payload of the call's `Result`.
        if method == "try_into" && args.is_empty() && !self.lcx.calls.contains_key(&e.id) {
            let (st, rt) = (self.expr_ty(object)?, self.expr_ty(e)?);
            let tcx = self.tys().tcx();
            let int = |t| matches!(tcx.kind(t), HK::Int(_) | HK::UInt(_));
            let ok = tcx
                .adt_of(rt)
                .and_then(|(adt, _)| adt.variants.iter().position(|v| v.name == "Ok"))
                .and_then(|i| tcx.field_ty(rt, Some(i as u32), 0));
            if let Some(tt) = ok.filter(|&tt| int(tt) && int(st)) {
                let name = format!("{}.try_from", self.tys().display(tt));
                let op = self.expr_operand(object)?;
                self.call_native(&name, vec![op], dest);
                return Ok(());
            }
        }
        if method == "raw" && args.is_empty() {
            // `id.raw()`: a distinct type's base value.
            let t = self.expr_ty(object)?;
            let base = match self.tys().tcx().kind(t) {
                HK::Ref(t) | HK::MutRef(t) => t,
                _ => t,
            };
            if let Some(bt) = self.distinct_base(base) {
                let p = self.expr_place(object, false)?;
                let (p, _) = self.strip_refs(p);
                let by_ref = base != t;
                let op = if self.is_copy(bt) {
                    Operand::Copy(p.field(0, bt))
                } else if by_ref {
                    return self.unsupported(e.span, "`raw` of a borrowed distinct value");
                } else {
                    Operand::Move(p.field(0, bt))
                };
                self.assign(dest, Rvalue::Use(op));
                return Ok(());
            }
        }
        if method == "cmp" && self.scalar_cmp(e, object, args, dest.clone())? {
            return Ok(());
        }
        if let ("cmp", [other]) = (method, args) {
            // A `Vec`'s `cmp`: lexicographic, as its `<` (B-2026-10-06-92).
            let ot = self.expr_ty(object)?;
            let (_, base) = self.strip_ty_full(ot);
            if matches!(
                self.tys().tcx().kind(base),
                HK::Intrinsic {
                    kind: IntrinsicKind::Vec,
                    ..
                }
            ) {
                let lp = self.expr_place(object, false)?;
                let rp = self.expr_place(&other.value, false)?;
                let (lp, lt) = self.strip_refs(lp);
                let (rp, _) = self.strip_refs(rp);
                return self.cmp_places(e.span, lp, rp, lt, dest);
            }
        }
        if let ("cmp", [other], false) = (method, args, self.lcx.calls.contains_key(&e.id)) {
            // A tuple's `cmp` (the checker records no callee for it).
            let ot = self.expr_ty(object)?;
            let (_, base) = self.strip_ty_full(ot);
            if matches!(self.tys().tcx().kind(base), HK::Tuple(_)) {
                let lp = self.expr_place(object, false)?;
                let rp = self.expr_place(&other.value, false)?;
                let (lp, lt) = self.strip_refs(lp);
                let (rp, _) = self.strip_refs(rp);
                return self.cmp_places(e.span, lp, rp, lt, dest);
            }
        }
        if method == "clone" && args.is_empty() {
            let rt = self.expr_ty(object)?;
            self.queue_nested_clones(rt);
        }
        let array_recv = method == "clone" && {
            let rt = self.expr_ty(object)?;
            matches!(self.strip_ty(rt), HK::Array { .. })
        };
        if method == "clone"
            && args.is_empty()
            && (array_recv || !self.lcx.calls.contains_key(&e.id))
        {
            // A tuple's `clone` (the checker records no callee for it), and
            // a fixed array's, element by element.
            let (p, t) = self.deref_place(object, false)?;
            self.clone_into(p, t, dest);
            return Ok(());
        }
        // Into a `Vec[char]`, walked in place; any other target collects
        // through the library's `StrChars` like any iterator.
        if method == "collect" && args.is_empty() && self.collects_char_vec(e)? {
            if let Some(text) = self.chars_of(object)? {
                return self.collect_chars(e, text, dest);
            }
        }
        // One of several impls for single instantiations of one type
        // (`impl Bx[String]`, `impl Bx[i64]`): the one the checker resolved
        // for this call site, by its dispatch name. The recorded callee names
        // the first impl of that name whatever the receiver.
        if let Some(seg) = self
            .lcx
            .tc
            .method_impl_dispatch
            .get(&(SpanKey::from_span(&e.span), method.to_string()))
        {
            let hit = self
                .lcx
                .fns
                .iter()
                .find(|(_, i)| i.f.name == method && i.impl_dispatch.as_ref() == Some(seg))
                .map(|(&d, _)| d);
            if let Some(d) = hit {
                let inst_args = match self.lcx.calls.get(&e.id) {
                    Some(rc) => {
                        let substs = self.lcx.tys.tcx().list(rc.substs);
                        self.instance_args(e.span, &substs)?
                    }
                    // A method with generics of its own (`extend[I]` of
                    // `impl Extend[char] for String`) reads them off the
                    // arguments, after the impl's off the receiver.
                    None => {
                        let rt = self.expr_ty(object)?;
                        let item = &self.lcx.fns[&d];
                        let own = item
                            .f
                            .generic_params
                            .as_ref()
                            .is_some_and(|g| !g.params.is_empty());
                        let targs = match self.strip_ty_full(rt).0 {
                            HK::Adt { args, .. }
                            | HK::Shared { args, .. }
                            | HK::Intrinsic { args, .. } => self.tys().tcx().list(args).to_vec(),
                            _ => Vec::new(),
                        };
                        let inst = if item.impl_params == 0 {
                            Vec::new()
                        } else {
                            item.impl_args(&targs).unwrap_or_default()
                        };
                        let ret = if self.lcx.node_types.contains_key(&e.id) {
                            Some(self.expr_ty(e)?)
                        } else {
                            None
                        };
                        match own {
                            true => {
                                match self.own_generics_from_args(d, inst.clone(), args, ret)? {
                                    Some((_, full)) => full,
                                    None => inst,
                                }
                            }
                            false => inst,
                        }
                    }
                };
                return self.user_method_call(e, object, d, inst_args, args, dest);
            }
        }
        let Some(rc) = self.lcx.calls.get(&e.id) else {
            if self.option_method(object, method, args, dest.clone())? {
                return Ok(());
            }
            // `a.add(b)` in a generic body (`Add.add(a, b)` with `T: Add`),
            // instantiated at a number: the operator (B-2026-10-28-17).
            let rt = self.expr_ty(object)?;
            let (_, base) = self.strip_ty_full(rt);
            let number = matches!(
                self.tys().tcx().kind(base),
                HK::Int(_) | HK::UInt(_) | HK::Float(_)
            );
            if let (true, Some(op), [other]) = (number, operator_method(method), args) {
                return self.binary(op, object, &other.value, dest);
            }
            if number
                && args.is_empty()
                && self.unary_operator_call(method, object, dest.clone())?
            {
                return Ok(());
            }
            // In a generic body a trait method is found once the receiver's
            // type is known: the one impl method of that name for it, or,
            // when an inherent method has the name too, the method of the
            // impl of the trait the bound names (B-2026-10-27-10).
            let rt = self.expr_ty(object)?;
            let bound = self
                .lcx
                .tc
                .method_typeparam_trait_key
                .get(&SpanKey::from_span(&e.span))
                .and_then(|k| k.split_once('.'))
                .and_then(|(tr, m)| {
                    let (d, inst_args) = self.user_impl_method(self.strip_ty_full(rt).1, tr, m)?;
                    let apart = self.lcx.fns.get(&d)?.impl_suffix.as_deref()?;
                    apart.ends_with(&format!("#{tr}")).then_some((d, inst_args))
                });
            if let Some((d, inst_args)) = bound {
                return self.user_method_call(e, object, d, inst_args, args, dest);
            }
            let ret = if self.lcx.node_types.contains_key(&e.id) {
                Some(self.expr_ty(e)?)
            } else {
                None
            };
            if let Some((d, inst_args)) = self.dyn_default_by_receiver(rt, method, args, ret)? {
                return self.user_method_call(e, object, d, inst_args, args, dest);
            }
            if let Some((d, inst_args)) = self.method_by_receiver(rt, method) {
                return self.user_method_call(e, object, d, inst_args, args, dest);
            }
            // A generic method (`v.serialize(s)` with `S` the serializer's
            // type): its own parameters read off the arguments.
            let ret = if self.lcx.node_types.contains_key(&e.id) {
                Some(self.expr_ty(e)?)
            } else {
                None
            };
            if let Some((d, inst_args)) = self.generic_method_by_receiver(rt, method, args, ret)? {
                return self.user_method_call(e, object, d, inst_args, args, dest);
            }
            if let Some((d, inst_args)) = self.blanket_method(e, rt, method) {
                return self.user_method_call(e, object, d, inst_args, args, dest);
            }
            // `c.try_into()` into a `Result[K, E]`: the user's `impl TryFrom
            // for K`, given the receiver.
            if method == "try_into" && args.is_empty() {
                let et = self.expr_ty(e)?;
                let tcx = self.tys().tcx();
                let ok = tcx
                    .adt_of(et)
                    .and_then(|(a, _)| a.variants.iter().position(|v| v.name == "Ok"));
                let target = ok.and_then(|i| tcx.field_ty(et, Some(i as u32), 0));
                if let Some((d, inst)) =
                    target.and_then(|k| self.user_impl_method(k, "TryFrom", "try_from"))
                {
                    // A source the `try_from` borrows (D5) is lent and
                    // stays the caller's.
                    let item = &self.lcx.fns[&d];
                    let pt = self.callee_param_ty(&item.f.params[0], &inst)?;
                    let arg = match self.tys().tcx().kind(pt) {
                        HK::Ref(_) => self.lib_arg(object, true)?,
                        _ => self.expr_operand(object)?,
                    };
                    let name = self.lcx.instance(d, inst.clone());
                    let func = self.fn_operand(&name, d, inst);
                    let next = self.b.new_block();
                    self.goto_with(
                        TerminatorKind::Call {
                            func,
                            args: vec![arg],
                            destination: dest,
                            target: Some(next),
                            unwind: UnwindAction::Abort,
                        },
                        next,
                    );
                    return Ok(());
                }
            }
            // `"42".parse()` into an `Option[i64]`: the number type's `parse`.
            if method == "parse"
                && args.is_empty()
                && matches!(self.strip_ty(rt), HK::Str | HK::StaticStr)
            {
                let et = self.expr_ty(e)?;
                // Into a `Result[i64, ParseError]`, the library's `parse`
                // (B-2026-10-12-6).
                let tcx = self.tys().tcx();
                let ok = tcx
                    .adt_of(et)
                    .and_then(|(a, _)| a.variants.iter().position(|v| v.name == "Ok"));
                if let Some(nt) = ok.and_then(|i| tcx.field_ty(et, Some(i as u32), 0)) {
                    let owner = self.tys().display(nt);
                    if self.parse_result_call(&owner, object, et, dest.clone())? {
                        return Ok(());
                    }
                }
                let tcx = self.tys().tcx();
                let some = tcx
                    .adt_of(et)
                    .and_then(|(a, _)| a.variants.iter().position(|v| v.name == "Some"));
                if let Some(nt) = some.and_then(|i| tcx.field_ty(et, Some(i as u32), 0)) {
                    let s = self.lib_arg(object, true)?;
                    let name = format!("{}.parse", self.tys().display(nt));
                    self.call_native(&name, vec![s], dest);
                    return Ok(());
                }
            }
            // `x.to_string()` under `T: Display` at a number, a `bool`, a
            // `char` or a `String`: the builtin conversion, as on the type
            // itself (B-2026-10-29-31).
            let display_bound = self
                .lcx
                .tc
                .method_typeparam_trait_key
                .get(&SpanKey::from_span(&e.span))
                .is_some_and(|k| k == "Display.to_string");
            if display_bound && method == "to_string" && args.is_empty() {
                let (_, base) = self.strip_ty_full(rt);
                if self.tys().tcx().adt_of(base).is_none() {
                    let key = format!("{}.to_string", self.tys().display(base));
                    return self.builtin_method(e, &key, object, method, args, dest);
                }
            }
            return self.unsupported(
                e.span,
                &format!("the method call `.{method}` with no resolved callee"),
            );
        };
        let callee = rc.callee.clone();
        let substs = self.lcx.tys.tcx().list(rc.substs);
        // `2.0.mul(3.0)` beside the program's `impl Mul[Col] for f64` is the
        // number's own operator, which the check picked by the argument
        // (B-2026-10-28-18).
        if let ([other], Some(op)) = (args, operator_method(method)) {
            let rt = self.expr_ty(object)?;
            let at = self.expr_ty(&other.value)?;
            let (lt, at) = (self.strip_ty_full(rt).1, self.strip_ty_full(at).1);
            let number = matches!(
                self.tys().tcx().kind(lt),
                HK::Int(_) | HK::UInt(_) | HK::Float(_)
            );
            if number && lt == at {
                return self.binary(op, object, &other.value, dest);
            }
        }
        match callee {
            Callee::Def(d) if self.lcx.fns.get(&d).is_some_and(|i| i.impl_dyn.is_none()) => {
                let inst_args = self.instance_args(e.span, &substs)?;
                let mut inst_args = inst_args;
                if method == "collect" && args.is_empty() && inst_args.len() >= 2 {
                    let n = inst_args.len();
                    let (v, c) = (inst_args[n - 2], inst_args[n - 1]);
                    self.check_collect_items(e.span, v, c)?;
                    // Tuple items with `ref` parts to `Copy` values are
                    // collected as the collection's elements, each such part
                    // copied out (`(i64, ref i64)` as `(i64, i64)`).
                    if let Some(elem) = self.collect_elem(c) {
                        if elem != v && self.copies_ref_parts(v, elem) {
                            inst_args[n - 2] = elem;
                        }
                    }
                }
                self.user_method_call(e, object, d, inst_args, args, dest)
            }
            Callee::Def(d) => {
                let own = self.instance_args(e.span, &substs)?;
                if self.dyn_default_call(e, object, d, own, args, dest.clone())? {
                    return Ok(());
                }
                if let Some(t) = self.lcx.lowered_def(d).filter(|&t| t != d) {
                    let inst_args = self.instance_args(e.span, &substs)?;
                    return self.user_method_call(e, object, t, inst_args, args, dest);
                }
                let key = format!("{}.{method}", self.lcx.def_name(d));
                self.builtin_method(e, &key, object, method, args, dest)
            }
            Callee::Builtin(key) => {
                // A user impl on a type with no definition of its own
                // (`impl Reads for Array[i64, 3]`) is recorded as a builtin.
                let rt = self.expr_ty(object)?;
                let (_, base) = self.strip_ty_full(rt);
                // `join` of a `Vec` of anything but `String`, and `concat` of
                // any `Vec`, is the library's `impl[T: Display] Slice[T]`
                // (B-2026-10-14-67); a `Vec[String]`'s `join` is the native.
                let elem = match self.tys().tcx().kind(base) {
                    HK::Slice { elem, .. } => Some(elem),
                    HK::Intrinsic { kind, args }
                        if matches!(method, "join" | "concat") && kind.name() == "Vec" =>
                    {
                        let args = self.tys().tcx().list(args);
                        match args.as_slice() {
                            [e] if method == "concat" || self.tys().display(*e) != "String" => {
                                Some(*e)
                            }
                            _ => None,
                        }
                    }
                    _ => None,
                };
                if let Some(elem) = elem {
                    let lib = self.lcx.fns.iter().find(|(_, i)| {
                        i.impl_slice
                            && i.f.name == method
                            && i.f
                                .generic_params
                                .as_ref()
                                .is_none_or(|g| g.params.is_empty())
                    });
                    if let Some((&d, _)) = lib {
                        return self.user_method_call(e, object, d, vec![elem], args, dest);
                    }
                }
                let user = self
                    .lcx
                    .fns
                    .iter()
                    .any(|(_, i)| i.impl_prim == Some(base) && i.f.name == method);
                if user {
                    if let Some((d, inst_args)) = self.method_by_receiver(rt, method) {
                        return self.user_method_call(e, object, d, inst_args, args, dest);
                    }
                }
                self.builtin_method(e, &key, object, method, args, dest)
            }
            Callee::Value => self.unsupported(e.span, "this method call"),
        }
    }

    /// `x.into()` at the type its context gives it: `x` itself, a widened
    /// number, `x` wrapped in `Some` / `Ok`, a `char` as a `String`, or the
    /// user's `impl From[x's type]` for the target.
    fn conversion_call(&mut self, e: &'a Expr, object: &'a Expr, dest: Place) -> R<bool> {
        let st = self.expr_ty(object)?;
        let dt = self.expr_ty(e)?;
        if st == dt {
            self.expr_into(object, dest)?;
            return Ok(true);
        }
        if let Some(kind) = self.widening(st, dt) {
            let op = self.expr_operand(object)?;
            self.assign(dest, Rvalue::Cast(kind, op, dt));
            return Ok(true);
        }
        let tcx = self.tys().tcx();
        if matches!(tcx.kind(st), HK::Char) && self.tys().display(dt) == "String" {
            let op = self.expr_operand(object)?;
            self.call_native("char.to_string", vec![op], dest);
            return Ok(true);
        }
        if let Some((adt, _)) = tcx.adt_of(dt) {
            let wrap = adt
                .variants
                .iter()
                .position(|v| (v.name == "Some" || v.name == "Ok") && v.fields.len() == 1);
            let named = matches!(
                self.tys().display(dt).split('[').next(),
                Some("Option" | "Result")
            );
            if let (Some(idx), true) = (wrap, named) {
                if tcx.field_ty(dt, Some(idx as u32), 0) == Some(st) {
                    let op = self.operand_at(object, st)?;
                    self.build_variant(dt, idx as u32, vec![op], dest);
                    return Ok(true);
                }
            }
        }
        // The library's `From[VarError] for IoError`, which `?` uses too
        // (B-2026-10-21-16).
        if (self.tys().display(st), self.tys().display(dt)) == ("VarError".into(), "IoError".into())
        {
            let mut ops = vec![self.expr_operand(object)?];
            if self.variant_from(dt, st, &mut ops) {
                if let Some(op) = ops.pop() {
                    self.assign(dest, Rvalue::Use(op));
                    return Ok(true);
                }
            }
        }
        let Some((d, iargs)) = self.user_from(dt, st) else {
            return Ok(false);
        };
        let f = self.lcx.fns[&d].f;
        let pt = self.callee_param_ty(&f.params[0], &iargs)?;
        let pending = vec![self.arg_pending(object, pt)?];
        let ops = self.finish_args(pending)?;
        let name = self.lcx.instance(d, iargs.clone());
        let func = self.fn_operand(&name, d, iargs);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: ops,
                destination: dest,
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(true)
    }

    /// The method `method` of the impl for `recv`'s type, when exactly one
    /// impl has it, with its instance arguments (the impl's parameters
    /// are the receiver's type arguments).
    fn method_by_receiver(&self, recv: Ty, method: &str) -> Option<(DefId, Vec<Ty>)> {
        let (kind, base) = self.strip_ty_full(recv);
        // A primitive's impl (`impl Step for i64`) has no target definition.
        let mut prim = self
            .lcx
            .fns
            .iter()
            .filter(|(_, i)| i.impl_prim == Some(base) && i.f.name == method);
        if let Some((&d, item)) = prim.next() {
            let generic = item
                .f
                .generic_params
                .as_ref()
                .is_some_and(|g| !g.params.is_empty());
            return (prim.next().is_none() && !generic).then(|| (d, Vec::new()));
        }
        let (target, targs) = match kind {
            HK::Adt { def, args } | HK::Shared { def, args } => (def, self.tys().tcx().list(args)),
            HK::Intrinsic { kind, args } => {
                let name = match kind {
                    IntrinsicKind::Vec => "Vec",
                    IntrinsicKind::Map => "Map",
                    IntrinsicKind::Set => "Set",
                    IntrinsicKind::VecDeque => "VecDeque",
                    IntrinsicKind::SortedMap => "SortedMap",
                    IntrinsicKind::SortedSet => "SortedSet",
                };
                (
                    self.lcx.defs.lookup(0, name)?,
                    crate::mir::ty::table_args(kind, self.tys().tcx().list(args)),
                )
            }
            _ => return None,
        };
        let mut found = self
            .lcx
            .fns
            .iter()
            .filter(|(_, i)| i.impl_target == Some(target) && i.f.name == method);
        let (&d, item) = found.next()?;
        if found.next().is_some()
            || item
                .f
                .generic_params
                .as_ref()
                .is_some_and(|g| !g.params.is_empty())
        {
            return None;
        }
        Some((d, item.impl_args(&targs)?))
    }

    /// A trait method called through a bound (`c.into_iter()` under `C:
    /// IntoIterator`) on a receiver with no impl of the trait of its own: the
    /// method of the trait's blanket impl over its own parameter
    /// (`impl[I: Iterator] IntoIterator for I`), instanced at the receiver.
    /// The checker has held the parameter's bounds.
    fn blanket_method(&self, e: &Expr, recv: Ty, method: &str) -> Option<(DefId, Vec<Ty>)> {
        let key = self
            .lcx
            .tc
            .method_typeparam_trait_key
            .get(&SpanKey::from_span(&e.span))?;
        let tr = key.strip_suffix(&format!(".{method}"))?;
        let label = format!("impl {tr}#");
        let recv = match self.tys().tcx().kind(recv) {
            HK::Ref(inner) | HK::MutRef(inner) => inner,
            _ => recv,
        };
        let mut found = self.lcx.fns.iter().filter(|(&d, i)| {
            let path = &self.lcx.defs.table.get(d).path.segments;
            i.f.name == method
                && self.lcx.is_blanket_fn(d)
                && path.len() >= 2
                && path[path.len() - 2].starts_with(&label)
        });
        let (&d, _) = found.next()?;
        found.next().is_none().then(|| (d, vec![recv]))
    }

    /// The one impl method `method` of `recv` when it has generic parameters
    /// of its own, each read off an argument, or off `ret`, the call's type,
    /// for one only the return type names (`OutV` of `it.map(f)`).
    fn generic_method_by_receiver(
        &mut self,
        recv: Ty,
        method: &str,
        args: &'a [CallArg],
        ret: Option<Ty>,
    ) -> R<Option<(DefId, Vec<Ty>)>> {
        let (kind, base) = self.strip_ty_full(recv);
        let generic = |i: &FnItem<'_>| {
            i.f.generic_params
                .as_ref()
                .is_some_and(|g| !g.params.is_empty())
        };
        let prim: Vec<DefId> = self
            .lcx
            .fns
            .iter()
            .filter(|(_, i)| i.impl_prim == Some(base) && i.f.name == method)
            .map(|(&d, _)| d)
            .collect();
        if let [d] = prim.as_slice() {
            if !generic(&self.lcx.fns[d]) {
                return Ok(None);
            }
            return self.own_generics_from_args(*d, Vec::new(), args, ret);
        }
        if !prim.is_empty() {
            return Ok(None);
        }
        let (target, targs) = match kind {
            HK::Adt { def, args } | HK::Shared { def, args } => (def, self.tys().tcx().list(args)),
            HK::Intrinsic { kind, args } => {
                let name = match kind {
                    IntrinsicKind::Vec => "Vec",
                    IntrinsicKind::Map => "Map",
                    IntrinsicKind::Set => "Set",
                    IntrinsicKind::VecDeque => "VecDeque",
                    IntrinsicKind::SortedMap => "SortedMap",
                    IntrinsicKind::SortedSet => "SortedSet",
                };
                let Some(d) = self.lcx.defs.lookup(0, name) else {
                    return Ok(None);
                };
                (
                    d,
                    crate::mir::ty::table_args(kind, self.tys().tcx().list(args)),
                )
            }
            _ => return Ok(None),
        };
        let found: Vec<DefId> = self
            .lcx
            .fns
            .iter()
            .filter(|(_, i)| i.impl_target == Some(target) && i.f.name == method)
            .map(|(&d, _)| d)
            .collect();
        let [d] = found.as_slice() else {
            return Ok(None);
        };
        let item = &self.lcx.fns[d];
        if !generic(item) {
            return Ok(None);
        }
        let Some(inst) = item.impl_args(&targs) else {
            return Ok(None);
        };
        self.own_generics_from_args(*d, inst, args, ret)
    }

    /// The associated function `m` of `t`'s impl when it has generic
    /// parameters of its own (`C.from_iter(it)` with `C` a `Vec`), each read
    /// off the argument its parameter is written as (`iter: own I`).
    fn generic_fn_by_receiver(
        &mut self,
        t: Ty,
        m: &str,
        args: &'a [CallArg],
    ) -> R<Option<(DefId, Vec<Ty>)>> {
        let (kind, base) = self.strip_ty_full(t);
        // A primitive's impl (`impl FromIterator[char] for String`) has no
        // target definition and no type arguments.
        let mut prim = self
            .lcx
            .fns
            .iter()
            .filter(|(_, i)| i.impl_prim == Some(base) && i.f.name == m);
        if let Some((&d, _)) = prim.next() {
            if prim.next().is_some() {
                return Ok(None);
            }
            return self.own_generics_from_args(d, Vec::new(), args, None);
        }
        let (target, targs) = match kind {
            HK::Adt { def, args } | HK::Shared { def, args } => (def, self.tys().tcx().list(args)),
            HK::Intrinsic { kind, args } => {
                let name = match kind {
                    IntrinsicKind::Vec => "Vec",
                    IntrinsicKind::Map => "Map",
                    IntrinsicKind::Set => "Set",
                    IntrinsicKind::VecDeque => "VecDeque",
                    IntrinsicKind::SortedMap => "SortedMap",
                    IntrinsicKind::SortedSet => "SortedSet",
                };
                let Some(d) = self.lcx.defs.lookup(0, name) else {
                    return Ok(None);
                };
                (
                    d,
                    crate::mir::ty::table_args(kind, self.tys().tcx().list(args)),
                )
            }
            _ => return Ok(None),
        };
        let mut found = self
            .lcx
            .fns
            .iter()
            .filter(|(_, i)| i.impl_target == Some(target) && i.f.name == m);
        let Some((&d, item)) = found.next() else {
            return Ok(None);
        };
        if found.next().is_some() {
            return Ok(None);
        }
        let Some(inst) = item.impl_args(&targs) else {
            return Ok(None);
        };
        self.own_generics_from_args(d, inst, args, None)
    }

    /// `d`'s instance arguments: `inst` (its impl's), then each of its own
    /// generic parameters read off the argument written as that bare name,
    /// or, for one no parameter is written as, off `ret`, the call's type,
    /// where `d`'s return type names it (B-2026-10-24-4).
    fn own_generics_from_args(
        &mut self,
        d: DefId,
        mut inst: Vec<Ty>,
        args: &'a [CallArg],
        ret: Option<Ty>,
    ) -> R<Option<(DefId, Vec<Ty>)>> {
        let f = self.lcx.fns[&d].f;
        let Some(own) = f.generic_params.as_ref() else {
            return Ok(None);
        };
        let names = |t: &ast::TypeExpr, name: &str| {
            matches!(&t.kind, ast::TypeKind::Path(q)
                if q.generic_args.is_none() && q.segments == [name.to_string()])
        };
        // Each parameter read off an argument written as it (`iter: own I`),
        // or as a borrow of it (`s: mut ref S`), whose pointee it is.
        let mut from: Vec<Result<(&'a Expr, bool), Ty>> = Vec::new();
        for gp in &own.params {
            let at = f
                .params
                .iter()
                .zip(args)
                .find_map(|(p, a)| match &p.ty.kind {
                    _ if names(&p.ty, &gp.name) => Some((&a.value, false)),
                    ast::TypeKind::Ref(inner) | ast::TypeKind::MutRef(inner)
                        if names(inner, &gp.name) =>
                    {
                        Some((&a.value, true))
                    }
                    _ => None,
                });
            if let Some(a) = at {
                from.push(Ok(a));
                continue;
            }
            let written = f
                .return_type
                .as_ref()
                .zip(ret)
                .and_then(|(rt, t)| self.written_at(rt, t, &gp.name));
            let Some(t) = written else {
                return Ok(None);
            };
            from.push(Err(t));
        }
        for a in from {
            let (a, borrowed) = match a {
                Ok(a) => a,
                Err(t) => {
                    inst.push(t);
                    continue;
                }
            };
            let t = self.expr_ty(a)?;
            let t = match self.tys().tcx().kind(t) {
                HK::Ref(inner) | HK::MutRef(inner) if borrowed => inner,
                _ => t,
            };
            inst.push(t);
        }
        Ok(Some((d, inst)))
    }

    /// The part of `t` that `te`, the type `t` was written as, writes as the
    /// bare name `name`: through a path's type arguments, a tuple's
    /// elements and a borrow's pointee.
    fn written_at(&self, te: &ast::TypeExpr, t: Ty, name: &str) -> Option<Ty> {
        let tcx = self.tys().tcx();
        match (&te.kind, tcx.kind(t)) {
            (ast::TypeKind::Path(q), _)
                if q.generic_args.is_none() && q.segments == [name.to_string()] =>
            {
                Some(t)
            }
            (
                ast::TypeKind::Path(q),
                HK::Adt { args, .. } | HK::Shared { args, .. } | HK::Intrinsic { args, .. },
            ) => {
                let written = q.generic_args.as_ref()?;
                let args = tcx.list(args);
                if written.len() != args.len() {
                    return None;
                }
                written.iter().zip(args.iter()).find_map(|(w, &a)| match w {
                    ast::GenericArg::Type(w) => self.written_at(w, a, name),
                    _ => None,
                })
            }
            (ast::TypeKind::Tuple(ws), HK::Tuple(l)) => {
                let l = tcx.list(l);
                ws.iter()
                    .zip(l.iter())
                    .find_map(|(w, &a)| self.written_at(w, a, name))
            }
            (ast::TypeKind::Ref(w), HK::Ref(inner))
            | (ast::TypeKind::MutRef(w), HK::MutRef(inner)) => self.written_at(w, inner, name),
            _ => None,
        }
    }

    /// `left <op> right` as a call of the user impl's operator method `d`,
    /// `left` the receiver and `right` the one argument, passed as
    /// [`Self::user_method_call`] passes them (B-2026-10-14-30); with no
    /// `right`, the unary `-left` / `~left` (B-2026-10-14-33).
    fn user_operator_call(
        &mut self,
        left: &'a Expr,
        right: Option<&'a Expr>,
        d: DefId,
        inst_args: Vec<Ty>,
        dest: Place,
    ) -> R<()> {
        let f = self.lcx.fns[&d].f;
        let Some(m) = f.self_param.clone() else {
            return self.unsupported(left.span, "an operator method without `self`");
        };
        let rhs = match (f.params.as_slice(), right) {
            ([p], Some(r)) => Some((p, r)),
            ([], None) => None,
            _ => {
                return self.unsupported(
                    left.span,
                    "an operator method whose parameters do not fit the operator",
                )
            }
        };
        let st = self.expr_ty(left)?;
        let (_, st) = self.strip_ty_full(st);
        if self.lcx.fns[&d].impl_params == 0 {
            self.lcx.self_tys.entry(d).or_insert(st);
        }
        let recv = match self.self_mode(f, m, st) {
            SelfParam::Owned => PendingRecv::Ready(self.owned_operand(left, st)?),
            SelfParam::Ref => self.recv_place(left, false)?,
            SelfParam::MutRef => self.recv_place(left, true)?,
        };
        let rest = match rhs {
            Some((p, right)) => {
                let pt = self.callee_param_ty(p, &inst_args)?;
                vec![self.arg_pending(right, pt)?]
            }
            None => Vec::new(),
        };
        let mut rest = self.finish_args(rest)?;
        let mut ops = vec![self.recv_borrow_after(recv, &mut rest)?];
        ops.extend(rest);
        let name = self.lcx.instance(d, inst_args.clone());
        let func = self.fn_operand(&name, d, inst_args);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: ops,
                destination: dest,
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(())
    }

    fn user_method_call(
        &mut self,
        e: &'a Expr,
        object: &'a Expr,
        d: DefId,
        inst_args: Vec<Ty>,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        if let ExprKind::MethodCall { method, .. } = &e.kind {
            if self.get_mut_by_key_view(object, method, args)? {
                // Named apart from the library's own `get_mut` instance,
                // which shares the native's name.
                let key = format!("{}.{method}", self.lcx.def_name(d));
                return self.builtin_method(e, &key, object, "get_mut_by_view", args, dest);
            }
        }
        // The argument list the typechecker completed: defaults filled in
        // and named arguments in declaration order (the legacy pipeline's
        // `lowering` splices the same list into the tree).
        let tc: &'a TypeCheckResult = self.lcx.tc;
        let args: &'a [CallArg] = match &e.kind {
            ExprKind::MethodCall { method, .. } => tc
                .method_default_fills
                .get(&(SpanKey::from_span(&e.span), method.clone()))
                .map_or(args, |v| v.as_slice()),
            _ => args,
        };
        {
            {
                let f = self.lcx.fns[&d].f;
                if args.len() != f.params.len() {
                    return self.unsupported(e.span, "a call that leaves out default arguments");
                }
                let mode = f.self_param.clone();
                if self.lcx.fns[&d].impl_params == 0 {
                    let rt = self.expr_ty(object)?;
                    let (_, base) = self.strip_ty_full(rt);
                    self.lcx.self_tys.entry(d).or_insert(base);
                }
                let mode = match mode {
                    Some(m) => {
                        let st = self.expr_ty(object)?;
                        let (_, st) = self.strip_ty_full(st);
                        Some(self.self_mode(f, m, st))
                    }
                    None => None,
                };
                // An array or `Vec` receiver of the library's `Slice[T]`
                // methods is viewed as a slice (`mk().iter()`;
                // B-2026-10-14-41).
                let slice_recv = match (self.lcx.fns[&d].impl_slice, &mode, inst_args.first()) {
                    (true, Some(m), Some(&elem)) => {
                        let st = self.expr_ty(object)?;
                        let (_, st) = self.strip_ty_full(st);
                        if matches!(self.tys().tcx().kind(st), HK::Slice { .. }) {
                            None
                        } else {
                            let mutable = matches!(m, SelfParam::MutRef);
                            let slice_t = self.tys().tcx().intern(HK::Slice { elem, mutable });
                            let s = self.slice_view(object, None, slice_t, mutable)?;
                            Some(self.slice_receiver(s, slice_t, m))
                        }
                    }
                    _ => None,
                };
                // No receiver: `G[i64].mk()` names an associated function
                // through its type, which is all the object is.
                let recv = match mode {
                    _ if slice_recv.is_some() => slice_recv.map(PendingRecv::Ready),
                    // Through a generic bound the trait's `own self` moves
                    // the receiver, even into an impl that borrows it: the
                    // moved value is the call's temporary, dropped at the
                    // end of the statement (core semantics §4.7, §7.4).
                    Some(SelfParam::Ref | SelfParam::MutRef)
                        if self.moves_into_borrowing_impl(object, d) =>
                    {
                        let st = self.expr_ty(object)?;
                        let mutable = mode == Some(SelfParam::MutRef);
                        let l = self.temp_of(object, st)?;
                        Some(PendingRecv::Borrow(Place::local(l), st, mutable))
                    }
                    Some(SelfParam::Owned) => {
                        let st = self.expr_ty(object)?;
                        let (_, st) = self.strip_ty_full(st);
                        Some(PendingRecv::Ready(self.owned_operand(object, st)?))
                    }
                    Some(SelfParam::Ref) => Some(self.recv_place(object, false)?),
                    Some(SelfParam::MutRef) => Some(self.recv_place(object, true)?),
                    None => None,
                };
                let mut rest = Vec::with_capacity(args.len());
                let mut fn_tys: Vec<Option<Ty>> = Vec::with_capacity(args.len());
                for (a, p) in args.iter().zip(&f.params) {
                    // A function-typed parameter takes the closure or function
                    // item itself, and the instance is specialised to it, as
                    // for a free function's call.
                    if (self.is_fn_typed(p.pattern.id) && !self.fn_param_owned(p))
                        || self.ref_fn_param_takes_closure(&a.value, p)?
                    {
                        let want = self.generic_fn_param_want(&a.value, p, &inst_args)?;
                        let (op, t) = self.fn_arg(&a.value, want, d5_params() && !p.is_own)?;
                        rest.push(PendingRecv::Ready(op));
                        fn_tys.push(Some(t));
                        continue;
                    }
                    if let Some(op) = self.closure_for_param(&a.value, p, &inst_args)? {
                        rest.push(PendingRecv::Ready(op));
                        fn_tys.push(None);
                        continue;
                    }
                    let pt = self.callee_param_ty(p, &inst_args)?;
                    rest.push(self.arg_pending(&a.value, pt)?);
                    fn_tys.push(None);
                }
                let mut rest = self.finish_args(rest)?;
                let mut ops = match recv {
                    Some(recv) => vec![self.recv_borrow_after(recv, &mut rest)?],
                    None => Vec::new(),
                };
                ops.extend(rest);
                let name = if fn_tys.iter().any(Option::is_some) {
                    self.lcx.instance_with_fns(d, inst_args.clone(), fn_tys)
                } else {
                    self.lcx.instance(d, inst_args.clone())
                };
                let func = self.fn_operand(&name, d, inst_args);
                let next = self.b.new_block();
                self.goto_with(
                    TerminatorKind::Call {
                        func,
                        args: ops,
                        destination: dest,
                        target: Some(next),
                        unwind: UnwindAction::Abort,
                    },
                    next,
                );
                Ok(())
            }
        }
    }

    /// Give the untyped arguments of a library method (`v.push(None)`)
    /// the parameter type the receiver implies.
    /// The parameter types of a library collection method, where known.
    fn lib_param_tys(&self, recv: Ty, method: &str) -> Option<Vec<Ty>> {
        let HK::Intrinsic { kind, args: targs } = self.tys().tcx().kind(recv) else {
            return None;
        };
        let targs = self.tys().tcx().list(targs);
        let usize_t = self.tys().tcx().intern(HK::UInt(UIntSize::Usize));
        // The fallible forms (`try_push`, `try_resize`) take what the
        // plain ones do.
        let method = method.strip_prefix("try_").unwrap_or(method);
        Some(match (kind, method) {
            (IntrinsicKind::Vec, "push" | "contains") => vec![targs[0]],
            (IntrinsicKind::VecDeque, "push_back" | "push_front") => vec![targs[0]],
            (IntrinsicKind::Vec, "insert") => vec![usize_t, targs[0]],
            // `fn resize(mut ref self, n: i64, val: own T)`: a negative
            // `n` counts as 0.
            (IntrinsicKind::Vec, "resize") => {
                vec![self.tys().tcx().intern(HK::Int(IntSize::I64)), targs[0]]
            }
            (IntrinsicKind::Map | IntrinsicKind::SortedMap, "insert") => vec![targs[0], targs[1]],
            (IntrinsicKind::Map, "get" | "contains_key" | "remove") => vec![targs[0]],
            (IntrinsicKind::Set, "insert" | "contains" | "remove") => vec![targs[0]],
            _ => return None,
        })
    }

    fn hint_lib_args(&mut self, recv: Ty, method: &str, args: &[CallArg]) {
        // `v.shuffle([3, 0])`: the lane indices are a literal the checker
        // reads as constants and leaves untyped.
        if method == "shuffle" && matches!(self.tys().tcx().kind(recv), HK::Vector { .. }) {
            for a in args {
                let ExprKind::ArrayLiteral(es) = &a.value.kind else {
                    continue;
                };
                let (i64_t, at) = {
                    let tcx = self.tys().tcx();
                    let i = tcx.intern(HK::Int(IntSize::I64));
                    let len = crate::ty::ArrayLen::Known(es.len() as u64);
                    (i, tcx.intern(HK::Array { elem: i, len }))
                };
                self.ty_hints.entry(a.value.id).or_insert(at);
                for x in es {
                    self.ty_hints.entry(x.id).or_insert(i64_t);
                }
            }
            return;
        }
        let Some(params) = self.lib_param_tys(recv, method) else {
            return;
        };
        for (a, p) in args.iter().zip(params) {
            if !self.lcx.node_types.contains_key(&a.value.id) {
                self.ty_hints.insert(a.value.id, p);
            }
        }
    }

    /// The ambient resource a lowercase module receiver names (`env` is
    /// `Env`), unless a local shadows it.
    /// The primitive type `object` names when it is a type rather than a
    /// value: `i64` in `i64.parse(s)`.
    fn primitive_owner(&self, object: &Expr) -> Option<&'a str> {
        let ExprKind::Identifier(name) = &object.kind else {
            return None;
        };
        if matches!(self.lcx.res.get(&object.id), Some(Res::Local(_)))
            || self.lcx.node_types.contains_key(&object.id)
        {
            return None;
        }
        const PRIMS: [&str; 18] = [
            "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize",
            "f16", "bf16", "f32", "f64", "bool", "char",
        ];
        PRIMS.iter().copied().find(|p| *p == name)
    }

    fn ambient_module(&self, object: &Expr) -> Option<&'static str> {
        let ExprKind::Identifier(name) = &object.kind else {
            return None;
        };
        if matches!(self.lcx.res.get(&object.id), Some(Res::Local(_))) {
            return None;
        }
        Some(match name.as_str() {
            "env" => "Env",
            "clock" => "Clock",
            "rand" => "RandomSource",
            "stdin" => "Stdin",
            "stdout" => "Stdout",
            "stderr" => "Stderr",
            "fs" => "FileSystem",
            "cpu" => "Cpu",
            _ => return None,
        })
    }

    /// Whether a call on `r` goes through its provider (core semantics
    /// §14.3): `r` is a resource with no default provider, one whose
    /// default the program declares (§14.14), or one with a default that
    /// some `with_provider` overrides. A call on it stays a placeholder
    /// until `providers::specialise`.
    fn resource_via_provider(&self, r: &str) -> bool {
        self.lcx.resource_bounds.contains_key(r)
            && (!self.lcx.resource_defaults.contains_key(r)
                || self.lcx.user_defaults.contains(r)
                || self.lcx.bound_resources.contains(r))
    }

    /// The declaration of `m` in one of `r`'s bounds.
    fn resource_method(&self, r: &str, m: &str) -> Option<BoundMethod<'a>> {
        self.bound_methods(r).into_iter().find(|bm| bm.name == m)
    }

    /// The methods of `r`'s bounds, each with the trait it comes from.
    fn bound_methods(&self, r: &str) -> Vec<BoundMethod<'a>> {
        let mut out = Vec::new();
        for t in self.lcx.resource_bounds.get(r).into_iter().flatten() {
            if let Some(&def) = self.lcx.trait_defs.get(t) {
                for it in &def.items {
                    if let ast::TraitItem::Method(tm) = it {
                        out.push(BoundMethod {
                            name: &tm.name,
                            bound: t.clone(),
                            self_param: tm.self_param.clone(),
                            params: &tm.params,
                            has_default: tm.body.is_some(),
                        });
                    }
                }
            } else if let Some(fs) = self.lcx.trait_impl_fns.get(t) {
                for f in fs {
                    out.push(BoundMethod {
                        name: &f.name,
                        bound: t.clone(),
                        self_param: f.self_param.clone(),
                        params: &f.params,
                        has_default: false,
                    });
                }
            }
        }
        out
    }

    /// `r` in the program's table of resources (core semantics §14): its
    /// bounds' methods, and its default provider if it has one.
    fn ensure_resource(&mut self, r: &str) -> R<()> {
        if self.lcx.program.resources.contains_key(r) {
            return Ok(());
        }
        let mut decl = crate::mir::effects::ResourceDecl::default();
        for bm in self.bound_methods(r) {
            let writes = matches!(bm.self_param, Some(ast::SelfParam::MutRef));
            decl.methods.insert(bm.name.to_string(), writes);
        }
        if let Some(&d) = self
            .lcx
            .resource_defaults
            .get(r)
            .filter(|_| self.lcx.user_defaults.contains(r))
        {
            // A program's own default (§14.14) is a provider like any
            // other, held in a static built before `main` and never
            // dropped. One with fields is read-only; a field-less one,
            // which no write can change, is lent `mut ref` too.
            let t = self.expr_ty(d)?;
            decl.impls.insert(t, self.provider_methods(d.span, r, t)?);
            decl.default = Some(t);
            let stateful = self.tys().field_ty(t, None, 0).is_some();
            let idx = self.lcx.program.statics.len() as u32;
            let init = format!("static.default.{r}");
            self.lcx.program.statics.push(StaticDef {
                name: format!("default.{r}"),
                ty: t,
                mutable: !stateful,
                init: init.clone(),
            });
            self.lcx.default_queue.push((d, t, init));
            decl.default_static = Some(idx);
            decl.default_stateful = stateful;
        } else if let Some(&d) = self.lcx.resource_defaults.get(r) {
            // The library's defaults keep their methods as natives, named
            // as `provider_recv` names them.
            let t = self.expr_ty(d)?;
            let shown = self.tys().display(t);
            let methods = decl
                .methods
                .keys()
                .map(|m| (m.clone(), format!("{shown}.{m}")))
                .collect();
            decl.impls.insert(t, methods);
            decl.default = Some(t);
        }
        // `print` and `println` on a standard stream (§14.10) take the
        // parts the fused natives take; `providers::specialise` keeps the
        // native outside an override and formats for the provider's
        // `write` inside one.
        for m in ["print", "println"] {
            if let Some(native) = crate::mir::providers::fused_print(r, m) {
                decl.methods.insert(m.to_string(), true);
                if let Some(t) = decl.default {
                    if let Some(ms) = decl.impls.get_mut(&t) {
                        ms.insert(m.to_string(), native.to_string());
                    }
                }
            }
        }
        // An open and the operations on an open `File` are calls on
        // `FileSystem` in a program that binds it (§14.11,
        // `providers::route_files`); each writes, as the provider's
        // `open`, `read_handle` and `write_handle` do.
        // The socket natives are calls on `Network` likewise (§14.12,
        // `providers::route_network`).
        let routed: Vec<String> = match r {
            "FileSystem" => std::iter::once("open_file".to_string())
                .chain(
                    crate::mir::providers::FILE_OPS
                        .iter()
                        .map(|op| format!("file_{op}")),
                )
                .collect(),
            "Network" => crate::mir::providers::NET_ROUTES
                .iter()
                .map(|(_, call)| call.to_string())
                .collect(),
            _ => Vec::new(),
        };
        for m in routed {
            decl.methods.insert(m.clone(), true);
            if let Some(t) = decl.default {
                if let (Some(ms), Some(native)) = (
                    decl.impls.get_mut(&t),
                    crate::mir::providers::file_native(r, &m),
                ) {
                    ms.insert(m, native);
                }
            }
        }
        self.lcx.program.resources.insert(r.to_string(), decl);
        Ok(())
    }

    /// A `with_provider` binds `r` to a provider of type `t`: the instance
    /// of each of `r`'s methods for `t`, which the calls on `r` reach after
    /// specialisation.
    fn bind_provider(&mut self, span: Span, r: &str, t: Ty) -> R<()> {
        self.ensure_resource(r)?;
        if self.lcx.program.resources[r].impls.contains_key(&t) {
            return Ok(());
        }
        let methods = self.provider_methods(span, r, t)?;
        if let Some(decl) = self.lcx.program.resources.get_mut(r) {
            decl.impls.insert(t, methods);
        }
        Ok(())
    }

    /// The instance of each of `r`'s methods for the provider type `t`.
    fn provider_methods(
        &mut self,
        span: Span,
        r: &str,
        t: Ty,
    ) -> R<std::collections::BTreeMap<String, String>> {
        let mut methods = std::collections::BTreeMap::new();
        for bm in self.bound_methods(r) {
            match self.user_impl_method(t, &bm.bound, bm.name) {
                Some((d, args)) => {
                    let name = self.lcx.instance(d, args);
                    methods.insert(bm.name.to_string(), name);
                }
                None if bm.has_default => {
                    let shown = self.tys().display(t);
                    return self.unsupported(
                        span,
                        &format!(
                            "`{}`'s default `{}` for the provider `{shown}`",
                            bm.bound, bm.name
                        ),
                    );
                }
                None => {}
            }
        }
        Ok(methods)
    }

    /// `providers { R1 => e1, .. } in { body }` (core semantics §14.8):
    /// each provider evaluated in order into a local that drops after the
    /// body, and the body's blocks recorded as a region in which each `R`
    /// is bound to its local, the first binding outermost.
    fn providers_into(
        &mut self,
        bindings: &'a [ast::ProviderBinding],
        body: &'a Block,
        dest: Place,
    ) -> R<()> {
        self.push_scope();
        let mut bound = Vec::new();
        for b in bindings {
            if !self.lcx.resource_bounds.contains_key(&b.resource) {
                return self.unsupported(b.resource_span, "a provider for an undeclared resource");
            }
            let t = self.expr_ty(&b.value)?;
            let l = self.scoped_temp(t);
            self.expr_into(&b.value, Place::local(l))?;
            self.bind_provider(b.resource_span, &b.resource, t)?;
            bound.push((b.resource.clone(), l));
        }
        let start = self.b.new_block();
        self.goto(start);
        self.cur = start;
        // A `FileSystem` or `Network` provider's handles reach it while
        // the block runs (core semantics §14.11, §14.12): provider
        // specialisation adds its handle methods to the `enter`, inside
        // the block's region.
        for (resource, l) in &bound {
            let r = match resource.as_str() {
                "FileSystem" => "FileSystem",
                "Network" => "Network",
                _ => continue,
            };
            let pt = self.b.local_ty(*l);
            let mt = self.tys().tcx().reference(pt, true);
            let p = self.temp(mt);
            self.assign(p, Rvalue::Ref(BorrowKind::Mut, Place::local(*l)));
            let i64t = self.tys().tcx().intern(HK::Int(IntSize::I64));
            let id = self.temp(i64t);
            self.call_native(
                &format!("{r}.enter"),
                vec![Operand::Move(Place::local(p))],
                Place::local(id),
            );
            self.schedule(ScopeEntry::FsExit(id, r));
        }
        self.block_into(body, dest)?;
        let end = self.b.new_block();
        self.goto(end);
        self.cur = end;
        let blocks: Vec<BasicBlock> = (start.0..end.0).map(BasicBlock).collect();
        // Inner before outer: the last binding is the innermost.
        for (resource, local) in bound.into_iter().rev() {
            self.b.provided.push(ProvidedRegion {
                resource,
                local,
                blocks: blocks.clone(),
            });
        }
        self.pop_scope()
    }

    /// `with_provider[R](p, f)` (core semantics §14.4), before provider
    /// specialisation: `p`, then the closure, then a call of the
    /// body-less `with_provider[R]`.
    fn with_provider_call(
        &mut self,
        e: &'a Expr,
        r: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        let [p, f] = args else {
            return self.unsupported(e.span, "a `with_provider` without a provider and a closure");
        };
        let pt = self.expr_ty(&p.value)?;
        let pv = self.temp(pt);
        self.expr_into(&p.value, Place::local(pv))?;
        self.bind_provider(e.span, r, pt)?;
        let fop = match &f.value.kind {
            ExprKind::Closure { .. } => self.closure_value(&f.value)?.0,
            _ => self.expr_operand(&f.value)?,
        };
        let ops = vec![Operand::Move(Place::local(pv)), fop];
        self.call_native(&format!("with_provider[{r}]"), ops, dest);
        Ok(())
    }

    /// `R.m(args)` on a resource reached through its provider (core
    /// semantics §14.2), before provider specialisation: a call of the
    /// body-less `R.m`, with no receiver.
    fn resource_call(
        &mut self,
        e: &'a Expr,
        r: &str,
        m: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        self.ensure_resource(r)?;
        if (r, m) == ("Stdin", "lines") {
            self.errors.push(format!(
                "{} in `{}`: `stdin.lines()` reads the process's own stdin, so it cannot run \
                 under a `Stdin` override (core-semantics §14.10); read with \
                 `stdin.read_line()` in a loop instead",
                at(e.span),
                self.name
            ));
            return Err(());
        }
        if crate::mir::providers::fused_print(r, m).is_some() {
            let mut ops = Vec::new();
            for a in args {
                self.print_operands(&a.value, &mut ops)?;
            }
            self.call_native(&format!("{r}.{m}"), ops, dest);
            return Ok(());
        }
        let Some(tm) = self.resource_method(r, m) else {
            return self.unsupported(
                e.span,
                &format!("a call of `{r}.{m}`, which no bound of `{r}` declares,"),
            );
        };
        if args.len() != tm.params.len() {
            return self.unsupported(e.span, "a call that leaves out default arguments");
        }
        let mut ops = Vec::new();
        for (a, p) in args.iter().zip(tm.params.iter()) {
            let t = match self.lcx.node_types.get(&p.pattern.id) {
                Some(&t) => match self.lcx.mir_ty(t, &[]) {
                    Ok(t) => t,
                    Err(err) => return self.unsupported(p.span, &err),
                },
                None => self.expr_ty(&a.value)?,
            };
            let pt = self.param_mode_ty(p, t);
            ops.push(self.arg_pending(&a.value, pt)?);
        }
        let ops = self.finish_args(ops)?;
        self.call_native(&format!("{r}.{m}"), ops, dest);
        Ok(())
    }

    /// The provider a call on the program-rooted resource `resource` goes
    /// to (core-semantics §14.7): the provider type's name and a borrow of
    /// the provider, the call's first argument. Outside any `with_provider`
    /// that is the resource's default, a fresh value of the declaration's
    /// constant expression. `None` for a resource the program declares no
    /// default for, whose calls keep the resource's own natives.
    fn provider_recv(&mut self, resource: &str) -> R<Option<(String, Operand)>> {
        let Some(&d) = self.lcx.resource_defaults.get(resource) else {
            return Ok(None);
        };
        let t = self.expr_ty(d)?;
        let v = self.temp(t);
        self.expr_into(d, Place::local(v))?;
        let rt = self.tys().tcx().reference(t, true);
        let r = self.temp(rt);
        self.assign(
            Place::local(r),
            Rvalue::Ref(BorrowKind::Mut, Place::local(v)),
        );
        let provider = self.tys().display(t);
        Ok(Some((provider, Operand::Move(Place::local(r)))))
    }

    /// A reference to the receiver, unless it already is one.
    fn recv_ref(&mut self, object: &'a Expr, mutable: bool) -> R<Operand> {
        let pending = self.recv_place(object, mutable)?;
        self.recv_borrow(pending)
    }

    /// The first half of a receiver borrow: evaluate the receiver's place,
    /// leaving the borrow itself to `recv_borrow`, which the caller emits
    /// after the arguments (core semantics §5.6, two-phase borrows).
    fn recv_place(&mut self, object: &'a Expr, mutable: bool) -> R<PendingRecv<'a>> {
        let t = self.expr_ty(object)?;
        if !matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_)) && through_index(object)
        {
            self.pre_index(object)?;
            return Ok(PendingRecv::Deferred(object, mutable));
        }
        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(t) {
            // A receiver that is already a reference is reborrowed, so a
            // `mut ref self` call through a `ref` reaches the borrow check
            // as the `&mut (*r)` it is (§5.9).
            if !self.is_place(object) {
                return Ok(PendingRecv::Ready(self.expr_operand(object)?));
            }
            let p = self.expr_place(object, mutable)?.project(ProjElem::Deref);
            return Ok(PendingRecv::Borrow(p, inner, mutable));
        }
        if let ExprKind::StringLit(lit) = &object.kind {
            // A literal receiver is a static `Str` with no origins (core
            // semantics §5.4): a shared borrow lends a `String` in static
            // data, so a view of it outlives any block, a branch's
            // included (B-2026-10-21-40).
            if !mutable && matches!(self.tys().tcx().kind(t), HK::Str) {
                let i = self.lcx.literal_static(object, t);
                return Ok(PendingRecv::Ready(Operand::Const(Const {
                    ty: self.tys().tcx().reference(t, false),
                    kind: ConstKind::Static(i),
                })));
            }
            // A `mut` one has a `String` of its own, to the end of the
            // enclosing block.
            let l = self.temp(t);
            let op = self.static_str(lit);
            self.call_native("String.from", vec![op], Place::local(l));
            let n = self.scopes.len();
            let at = n.saturating_sub(2);
            self.scopes[at].push(ScopeEntry::Drop(Place::local(l)));
            return Ok(PendingRecv::Borrow(Place::local(l), t, mutable));
        }
        let p = self.expr_place(object, mutable)?;
        Ok(PendingRecv::Borrow(p, t, mutable))
    }

    /// The receiver's borrow, taken after the arguments `rest` were
    /// evaluated (core semantics §5.6, two-phase borrows): an argument that
    /// still names a place (`doc.move_subtree(a, doc.root, 9)`) is read
    /// into a temporary first, so `&mut doc` does not cover the read.
    fn recv_borrow_after(&mut self, pending: PendingRecv<'a>, rest: &mut [Operand]) -> R<Operand> {
        if matches!(
            pending,
            PendingRecv::Borrow(_, _, true) | PendingRecv::Deferred(_, true)
        ) {
            for op in rest.iter_mut() {
                let (Operand::Copy(p) | Operand::Move(p)) = op else {
                    continue;
                };
                if p.projection.is_empty() && self.b.is_temp(p.local) {
                    continue;
                }
                let t = self.place_type(p);
                let l = self.temp(t);
                let read = std::mem::replace(op, Operand::Move(Place::local(l)));
                self.assign(l, Rvalue::Use(read));
            }
        }
        self.recv_borrow(pending)
    }

    fn recv_borrow(&mut self, pending: PendingRecv<'a>) -> R<Operand> {
        let (p, t, mutable) = match pending {
            PendingRecv::Ready(op) => return Ok(op),
            PendingRecv::Borrow(p, t, m) => (p, t, m),
            PendingRecv::Deferred(object, m) => {
                let p = self.expr_place(object, m)?;
                let t = self.place_type(&p);
                (p, t, m)
            }
        };
        let rt = self.tys().tcx().reference(t, mutable);
        let r = self.temp(rt);
        let kind = if mutable {
            BorrowKind::Mut
        } else {
            BorrowKind::Shared
        };
        self.assign(r, Rvalue::Ref(kind, p));
        Ok(Operand::Move(Place::local(r)))
    }

    // ── function values ─────────────────────────────────────────────

    /// Whether the checker gave node `id` a function type.
    fn is_fn_typed(&self, id: NodeId) -> bool {
        self.lcx
            .node_types
            .get(&id)
            .is_some_and(|&t| matches!(self.tys().tcx().kind(t), HK::Fn { .. }))
    }

    /// Whether the parameter `p` takes its function by reference (`f: mut
    /// ref MutFn()`) and the argument `a` is a closure, which the instance
    /// is then specialised to, taking the closure by the reference its body
    /// wants (B-2026-10-19-68). An erased `Fn` argument keeps the call
    /// through the erased value.
    fn ref_fn_param_takes_closure(&mut self, a: &'a Expr, p: &ast::Param) -> R<bool> {
        let tcx = self.tys().tcx();
        let by_ref = self.lcx.node_types.get(&p.pattern.id).is_some_and(|&t| {
            matches!(tcx.kind(t), HK::Ref(i) | HK::MutRef(i) if matches!(tcx.kind(i), HK::Fn { .. }))
        });
        if !by_ref {
            return Ok(false);
        }
        if matches!(a.kind, ExprKind::Closure { .. }) {
            return Ok(true);
        }
        let at = self.expr_ty(a)?;
        let tcx = self.tys().tcx();
        let inner = match tcx.kind(at) {
            HK::Ref(i) | HK::MutRef(i) => i,
            _ => at,
        };
        Ok(matches!(tcx.kind(inner), HK::Closure { .. }))
    }

    /// A function item as a value: a constant of its `FnDef` type.
    fn fn_item_value(&mut self, e: &Expr, d: DefId, want: Option<Ty>) -> R<(Operand, Ty)> {
        let d = if self.lcx.fns.contains_key(&d) {
            d
        } else {
            self.lcx.wrapper_from(d).unwrap_or(d)
        };
        let n_generic = self.lcx.fns.get(&d).map_or(0, |i| {
            i.f.generic_params.as_ref().map_or(0, |g| g.params.len())
        });
        let args = if n_generic == 0 {
            Vec::new()
        } else {
            match self.fn_item_value_args(e, d, n_generic, want)? {
                Some(args) => args,
                None => return self.unsupported(e.span, "a generic function as a value"),
            }
        };
        let name = self.lcx.instance(d, args.clone());
        let t = {
            let tcx = self.tys().tcx();
            let list = tcx.intern_list(&args);
            tcx.intern(HK::FnDef { def: d, args: list })
        };
        let op = Operand::Const(Const {
            ty: t,
            kind: ConstKind::FnDef(InstanceId { def: d, args, name }),
        });
        Ok((op, t))
    }

    /// The type the parameter `p` of a callee in instance `inst_args` gives
    /// the argument `a`, when `a` names a generic function item, which
    /// takes its own instance from it.
    fn generic_fn_param_want(
        &mut self,
        a: &Expr,
        p: &'a ast::Param,
        inst_args: &[Ty],
    ) -> R<Option<Ty>> {
        let generic_item = match &a.kind {
            ExprKind::Identifier(_) | ExprKind::Path { .. } => match self.lcx.res.get(&a.id) {
                Some(Res::Def(d)) => self.lcx.fns.get(d).is_some_and(|i| {
                    i.f.generic_params
                        .as_ref()
                        .is_some_and(|g| !g.params.is_empty())
                }),
                _ => false,
            },
            _ => false,
        };
        if !generic_item {
            return Ok(None);
        }
        let t = self.callee_param_ty(p, inst_args)?;
        Ok(Some(t))
    }

    /// The generic arguments of the function item `d`, used as a value at
    /// `e`, read off the `Fn` type the use site gives it: `count(v, never)`
    /// with a `keep: Fn(char) -> bool` parameter names `never[char]`
    /// (B-2026-10-18-12). `None` when a parameter is left unsolved.
    fn fn_item_value_args(
        &mut self,
        e: &Expr,
        d: DefId,
        n: usize,
        want: Option<Ty>,
    ) -> R<Option<Vec<Ty>>> {
        // The slot's type when there is one: the checker records the
        // item's own type, whose parameters are unsolved.
        let want = match want {
            Some(t) => t,
            None => self.expr_ty(e)?,
        };
        let HK::Fn { params, .. } = self.tys().tcx().kind(want) else {
            return Ok(None);
        };
        let wants = self.tys().tcx().list(params);
        let f = self.lcx.fns[&d].f;
        if wants.len() != f.params.len() {
            return Ok(None);
        }
        let mut out: Vec<Option<Ty>> = vec![None; n];
        for (p, &w) in f.params.iter().zip(&wants) {
            let Some(&g) = self.lcx.node_types.get(&p.pattern.id) else {
                return Ok(None);
            };
            // In the builder's own form (`Vec` an intrinsic), parameters kept.
            let Ok(g) = self.lcx.convert(g) else {
                return Ok(None);
            };
            self.solve_params(g, w, &mut out);
        }
        Ok(out.into_iter().collect())
    }

    /// Bind each generic parameter in `g` (a declared type) to the part of
    /// the concrete type `c` in its position. A borrowed `c` against an
    /// unborrowed `g` is matched through the borrow.
    fn solve_params(&self, g: Ty, c: Ty, out: &mut [Option<Ty>]) {
        let tcx = self.tys().tcx();
        match (tcx.kind(g), tcx.kind(c)) {
            (HK::Param(p), _) => {
                if let Some(slot) = out.get_mut(p.index as usize) {
                    slot.get_or_insert(c);
                }
            }
            (HK::Ref(a), HK::Ref(b)) | (HK::MutRef(a), HK::MutRef(b)) => {
                self.solve_params(a, b, out)
            }
            (k, HK::Ref(b) | HK::MutRef(b)) if !matches!(k, HK::Ref(_) | HK::MutRef(_)) => {
                self.solve_params(g, b, out)
            }
            (HK::Adt { def: a, args: x }, HK::Adt { def: b, args: y }) if a == b => {
                let (x, y) = (tcx.list(x), tcx.list(y));
                for (&gx, &cy) in x.iter().zip(&y) {
                    self.solve_params(gx, cy, out);
                }
            }
            (HK::Intrinsic { kind: a, args: x }, HK::Intrinsic { kind: b, args: y }) if a == b => {
                let (x, y) = (tcx.list(x), tcx.list(y));
                for (&gx, &cy) in x.iter().zip(&y) {
                    self.solve_params(gx, cy, out);
                }
            }
            (HK::Tuple(x), HK::Tuple(y)) => {
                let (x, y) = (tcx.list(x), tcx.list(y));
                for (&gx, &cy) in x.iter().zip(&y) {
                    self.solve_params(gx, cy, out);
                }
            }
            (HK::Slice { elem: a, .. }, HK::Slice { elem: b, .. })
            | (HK::Array { elem: a, .. }, HK::Array { elem: b, .. }) => {
                self.solve_params(a, b, out)
            }
            (
                HK::Fn {
                    params: x, ret: r1, ..
                },
                HK::Fn {
                    params: y, ret: r2, ..
                },
            ) => {
                let (x, y) = (tcx.list(x), tcx.list(y));
                for (&gx, &cy) in x.iter().zip(&y) {
                    self.solve_params(gx, cy, out);
                }
                self.solve_params(r1, r2, out);
            }
            _ => {}
        }
    }

    /// The library function a compiler-provided path names as a value:
    /// `Vec.new`, `String.new` and the other empty constructors are the
    /// type's `default`, as is `String.default` (B-2026-10-06-118).
    fn builtin_fn_def(&self, e: &Expr) -> Option<DefId> {
        // `f64.total_cmp` named as a value is the library's
        // `f64_total_cmp` (B-2026-10-21-30).
        if let ExprKind::FieldAccess { object, field } = &e.kind {
            let ExprKind::Identifier(name) = &object.kind else {
                return None;
            };
            if field != "total_cmp"
                || !matches!(name.as_str(), "f64" | "f32")
                || matches!(self.lcx.res.get(&object.id), Some(Res::Local(_)))
            {
                return None;
            }
            return self.lcx.defs.lookup(0, &format!("{name}_total_cmp"));
        }
        let Some(Res::Builtin(path)) = self.lcx.res.get(&e.id) else {
            return None;
        };
        let (ty, "new" | "default") = path.rsplit_once('.')? else {
            return None;
        };
        let defs = &self.lcx.defs;
        let cands = match defs.lookup(0, ty) {
            Some(t) => defs.methods.get(&t)?.get("default")?,
            None => defs.builtin_methods.get(ty)?.get("default")?,
        };
        cands.iter().copied().find(|&m| !defs.is_trait_method(m))
    }

    /// A function-typed value: a closure literal, a function item, or a
    /// local holding one (moved, or copied when it is `Copy`).
    fn fn_value(&mut self, e: &'a Expr) -> R<(Operand, Ty)> {
        match &e.kind {
            ExprKind::Closure { .. } => self.closure_value(e),
            ExprKind::Identifier(_) | ExprKind::Path { .. } => {
                if let Some(Res::Def(d)) = self.lcx.res.get(&e.id) {
                    return self.fn_item_value(e, *d, None);
                }
                if let Some(d) = self.builtin_fn_def(e) {
                    return self.fn_item_value(e, d, None);
                }
                let p = self.expr_place(e, false)?;
                let t = self.place_type(&p);
                Ok((self.use_place(p, t), t))
            }
            ExprKind::FieldAccess { .. } if self.builtin_fn_def(e).is_some() => {
                let d = self.builtin_fn_def(e).expect("checked");
                self.fn_item_value(e, d, None)
            }
            // Any other expression (a call's result, an element, a field)
            // already has an erased `Fn` type: its value is the function.
            _ => {
                let t = self.expr_ty(e)?;
                Ok((self.expr_operand(e)?, t))
            }
        }
    }

    /// The fields of `t`, a struct, that `body` reads `sym` through, when
    /// every use of `sym` there is such a field access and `body` makes no
    /// closure of its own.
    fn disjoint_fields(&self, body: &Expr, sym: SymbolId, t: Ty) -> Option<Vec<(String, u32, Ty)>> {
        let (adt, _) = self.tys().tcx().adt_of(t)?;
        if adt.is_enum || matches!(self.tys().tcx().kind(t), HK::Shared { .. }) {
            return None;
        }
        let res = &self.lcx.res;
        let is_sym = |x: &Expr| {
            matches!(x.kind, ExprKind::Identifier(_))
                && matches!(res.get(&x.id), Some(Res::Local(s)) if *s == sym)
        };
        let (mut names, mut objects, mut uses, mut nested) =
            (Vec::new(), Vec::new(), Vec::new(), false);
        crate::span_visitor::for_each_expr(body, &mut |x| match &x.kind {
            ExprKind::FieldAccess { object, field } if is_sym(object) => {
                objects.push(object.id);
                if !names.contains(field) {
                    names.push(field.clone());
                }
            }
            ExprKind::Closure { .. } => nested = true,
            _ if is_sym(x) => uses.push(x.id),
            _ => {}
        });
        if nested || uses.is_empty() || uses.iter().any(|u| !objects.contains(u)) {
            return None;
        }
        names
            .into_iter()
            .map(|n| self.field_of(t, None, &n).map(|(i, ft)| (n, i, ft)))
            .collect()
    }

    /// The capture of `object.field` when a closure captured that field of
    /// an outer binding apart (`disjoint_fields`).
    fn captured_field(&self, object: &Expr, field: &str) -> Option<Place> {
        if self.captured_fields.is_empty() || !matches!(object.kind, ExprKind::Identifier(_)) {
            return None;
        }
        let Some(Res::Local(sym)) = self.lcx.res.get(&object.id) else {
            return None;
        };
        self.captured_fields
            .get(&(*sym, field.to_string()))
            .cloned()
    }

    /// The symbols a closure body reads from its surroundings, in the order
    /// they first appear (core semantics §9.4).
    fn closure_captures(&self, body: &Expr) -> Vec<SymbolId> {
        let mut out = Vec::new();
        // The method's `self` is not a named local: its uses are found by
        // kind (B-2026-10-15-4).
        let selves = match self.self_local {
            Some(_) => crate::span_visitor::self_value_ids(body),
            None => Vec::new(),
        };
        for id in crate::span_visitor::expr_node_ids(body) {
            if let Some(Res::Local(sym)) = self.lcx.res.get(&id) {
                let outer = self.locals.contains_key(sym)
                    || self.captured.contains_key(sym)
                    || selves.contains(&id);
                if outer && !out.contains(sym) {
                    out.push(*sym);
                }
            }
        }
        out
    }

    /// The captures in `caps` that `body` moves: a non-`Copy` capture used
    /// where a value is consumed (an owned argument or receiver, a `let`,
    /// a return, a field of a new value, the closure's result).
    fn moved_captures(&self, body: &'a Expr, caps: &[SymbolId]) -> FxHashSet<SymbolId> {
        let mut out = FxHashSet::default();
        self.mv_expr(body, true, caps, &mut out);
        out
    }

    fn owned_node(&self, id: NodeId) -> bool {
        self.lcx.node_types.get(&id).is_some_and(|&t| {
            !self.is_copy(t)
                && !self.hir_handle(t)
                && !matches!(
                    self.tys().tcx().kind(t),
                    HK::Shared { .. } | HK::Ref(_) | HK::MutRef(_)
                )
        })
    }

    /// Whether the typed-HIR type `t` is a `shared` (or `par`) ADT, which
    /// typed HIR writes as its plain `Adt`: a use copies the handle, so a
    /// closure returning one moves nothing out (B-2026-10-25-13).
    fn hir_handle(&self, t: Ty) -> bool {
        let HK::Adt { def, .. } = self.tys().tcx().kind(t) else {
            return false;
        };
        let name = self.lcx.def_name(def);
        let tc = self.lcx.tc;
        match tc.struct_info.get(&name) {
            Some(s) => s.is_shared || s.is_par,
            None => tc
                .enum_info
                .get(&name)
                .is_some_and(|e| e.is_shared || e.is_par),
        }
    }

    /// Whether the user function `d`'s parameter `i` takes its argument by
    /// value (not as a reference or a slice view).
    fn owned_param(&self, d: DefId, i: usize) -> bool {
        self.lcx.fns.get(&d).is_some_and(|item| {
            item.f.params.get(i).is_some_and(|p| {
                self.lcx.node_types.get(&p.pattern.id).is_some_and(|&t| {
                    // A slice parameter views its argument, and under D5 a
                    // bare one borrows it.
                    let t = self.param_mode_ty(p, t);
                    !matches!(
                        self.tys().tcx().kind(t),
                        HK::Ref(_) | HK::MutRef(_) | HK::Slice { .. }
                    )
                })
            })
        })
    }

    /// Record the capture an assignment's target is rooted at.
    fn note_assigned(&self, target: &Expr, caps: &[SymbolId]) {
        let mut e = target;
        while let ExprKind::FieldAccess { object, .. }
        | ExprKind::TupleIndex { object, .. }
        | ExprKind::Index { object, .. } = &e.kind
        {
            e = object;
        }
        if let Some(Res::Local(sym)) = self.lcx.res.get(&e.id) {
            if caps.contains(sym) {
                self.assigned_caps.borrow_mut().insert(*sym);
            }
        }
    }

    fn mv_block(&self, b: &'a Block, ctx: bool, caps: &[SymbolId], out: &mut FxHashSet<SymbolId>) {
        for st in &b.stmts {
            match &st.kind {
                StmtKind::Let { value, .. } => self.mv_expr(value, true, caps, out),
                StmtKind::Assign { target, value } => {
                    self.note_assigned(target, caps);
                    self.mv_expr(target, false, caps, out);
                    self.mv_expr(value, true, caps, out);
                }
                StmtKind::CompoundAssign { target, value, .. } => {
                    self.note_assigned(target, caps);
                    self.mv_expr(target, false, caps, out);
                    self.mv_expr(value, false, caps, out);
                }
                StmtKind::Expr(e) => self.mv_expr(e, false, caps, out),
                StmtKind::Defer { body } | StmtKind::ErrDefer { body, .. } => {
                    self.mv_block(body, false, caps, out)
                }
                _ => {}
            }
        }
        if let Some(e) = &b.final_expr {
            self.mv_expr(e, ctx, caps, out);
        }
    }

    fn mv_expr(&self, e: &'a Expr, ctx: bool, caps: &[SymbolId], out: &mut FxHashSet<SymbolId>) {
        let ctx = ctx && self.owned_node(e.id);
        let go =
            |x: &'a Expr, c: bool, out: &mut FxHashSet<SymbolId>| self.mv_expr(x, c, caps, out);
        match &e.kind {
            ExprKind::Identifier(_) | ExprKind::SelfValue => {
                if let Some(Res::Local(sym)) = self.lcx.res.get(&e.id) {
                    if ctx && caps.contains(sym) {
                        out.insert(*sym);
                    }
                }
            }
            ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
                go(object, ctx, out)
            }
            ExprKind::Index { object, index } => {
                go(object, false, out);
                go(index, false, out);
            }
            ExprKind::Call { callee, args } => {
                let def = match self.lcx.calls.get(&e.id).map(|c| &c.callee) {
                    Some(Callee::Def(d)) => Some(*d),
                    _ => match self.lcx.res.get(&callee.id) {
                        Some(Res::Def(d)) => Some(*d),
                        _ => None,
                    },
                };
                let variant =
                    def.is_some_and(|d| self.lcx.defs.table.get(d).kind == DefKind::Variant);
                // `with_provider[R](p, f)` takes its provider by value (§14.4).
                let binds = with_provider_resource(callee).is_some();
                // A library builtin (`String.from_utf8(bytes)`) takes its
                // arguments as operands, so a non-`Copy` one moves into a
                // task.
                let builtin = self.task_moves
                    && matches!(callee.kind, ExprKind::Path { .. })
                    && def.is_none_or(|d| !self.lcx.fns.contains_key(&d));
                // A call through a function value (`f(s)`, `f: Fn(own
                // String)`) takes what its type's parameters own
                // (B-2026-10-25-36).
                let value_params = match def {
                    None => self.lcx.node_types.get(&callee.id).and_then(|&t| {
                        let (_, t) = self.strip_ty_full(t);
                        match self.tys().tcx().kind(t) {
                            HK::Fn { params, .. } => Some(self.tys().tcx().list(params)),
                            _ => None,
                        }
                    }),
                    Some(_) => None,
                };
                go(callee, false, out);
                for (i, a) in args.iter().enumerate() {
                    let owned = variant
                        || builtin
                        || (binds && i == 0)
                        || def.is_some_and(|d| self.owned_param(d, i))
                        || value_params
                            .as_ref()
                            .and_then(|ps| ps.get(i))
                            .is_some_and(|&p| {
                                !matches!(
                                    self.tys().tcx().kind(p),
                                    HK::Ref(_) | HK::MutRef(_) | HK::Slice { .. }
                                )
                            });
                    // `f(mut x)` lends the capture mutably.
                    if a.mut_marker {
                        self.note_assigned(&a.value, caps);
                    }
                    go(&a.value, owned, out);
                }
            }
            ExprKind::MethodCall {
                object,
                method,
                args,
                ..
            } => {
                let def = match self.lcx.calls.get(&e.id).map(|c| &c.callee) {
                    Some(Callee::Def(d)) if self.lcx.fns.contains_key(d) => Some(*d),
                    _ => None,
                };
                let recv_owned = match def {
                    Some(d) => {
                        let f = self.lcx.fns[&d].f;
                        let st = self.lcx.node_types.get(&object.id).copied();
                        match (&f.self_param, st) {
                            (Some(m), Some(st)) => {
                                let (_, st) = self.strip_ty_full(st);
                                self.self_mode(f, m.clone(), st) == SelfParam::Owned
                            }
                            _ => false,
                        }
                    }
                    None => false,
                };
                // A method that writes its receiver mutates the capture
                // it is rooted at.
                let writes = match def {
                    Some(d) => matches!(self.lcx.fns[&d].f.self_param, Some(SelfParam::MutRef)),
                    None => {
                        crate::ast::is_mutating_collection_method(method)
                            || matches!(
                                method.as_str(),
                                "push_str" | "set" | "entry" | "split_at_mut"
                            )
                    }
                };
                if writes {
                    self.note_assigned(object, caps);
                }
                go(object, recv_owned, out);
                let stores = stores_argument(method.as_str());
                for (i, a) in args.iter().enumerate() {
                    let owned = match def {
                        Some(d) => self.owned_param(d, i),
                        None => stores,
                    };
                    if a.mut_marker {
                        self.note_assigned(&a.value, caps);
                    }
                    go(&a.value, owned, out);
                }
            }
            ExprKind::StructLiteral { fields, spread, .. } => {
                for f in fields {
                    go(&f.value, true, out);
                }
                if let Some(s) = spread {
                    go(s, true, out);
                }
            }
            ExprKind::Tuple(es) | ExprKind::ArrayLiteral(es) => {
                for x in es {
                    go(x, true, out);
                }
            }
            ExprKind::Block(b) => self.mv_block(b, ctx, caps, out),
            ExprKind::If {
                condition,
                then_block,
                else_branch,
            } => {
                go(condition, false, out);
                self.mv_block(then_block, ctx, caps, out);
                if let Some(x) = else_branch {
                    go(x, ctx, out);
                }
            }
            ExprKind::IfLet {
                value,
                then_block,
                else_branch,
                ..
            } => {
                go(value, false, out);
                self.mv_block(then_block, ctx, caps, out);
                if let Some(x) = else_branch {
                    go(x, ctx, out);
                }
            }
            ExprKind::Match { scrutinee, arms } => {
                go(scrutinee, false, out);
                for arm in arms {
                    if let Some(g) = &arm.guard {
                        go(g, false, out);
                    }
                    go(&arm.body, ctx, out);
                }
            }
            ExprKind::While {
                condition, body, ..
            } => {
                go(condition, false, out);
                self.mv_block(body, false, caps, out);
            }
            ExprKind::WhileLet { value, body, .. } => {
                go(value, false, out);
                self.mv_block(body, false, caps, out);
            }
            ExprKind::For { iterable, body, .. } => {
                go(iterable, false, out);
                self.mv_block(body, false, caps, out);
            }
            ExprKind::Loop { body, .. } => self.mv_block(body, false, caps, out),
            ExprKind::Closure { body, .. } => go(body, true, out),
            ExprKind::Return(Some(x)) | ExprKind::Question(x) => go(x, true, out),
            ExprKind::Break { value: Some(x), .. } => go(x, true, out),
            ExprKind::Binary { left, right, .. } => {
                go(left, false, out);
                go(right, false, out);
            }
            ExprKind::Unary { operand, .. } => go(operand, false, out),
            ExprKind::Cast { expr, .. } => go(expr, false, out),
            ExprKind::InterpolatedStringLit(parts) => {
                for p in parts {
                    if let ParsedInterpolationPart::Expr(x, _) = p {
                        go(x, false, out);
                    }
                }
            }
            _ => {}
        }
    }

    /// Create a closure: its environment is an aggregate of the captures,
    /// each moved, copied or borrowed by the mode the body needs (§9.1).
    fn closure_value(&mut self, e: &'a Expr) -> R<(Operand, Ty)> {
        let ExprKind::Closure {
            body, capture_mode, ..
        } = &e.kind
        else {
            return self.unsupported(e.span, "this closure");
        };
        let ref_params = std::mem::take(&mut self.closure_ref_params);
        let key = std::mem::take(&mut self.closure_key);
        let task = std::mem::take(&mut self.closure_task);
        let escapes = std::mem::take(&mut self.closure_escapes);
        let by_value = std::mem::take(&mut self.closure_by_value);
        let ret_capture = self.closure_ret_capture.take();
        let auto_par = std::mem::take(&mut self.closure_auto_par);
        let chunk = self.closure_chunk.take();
        let extra_caps = std::mem::take(&mut self.closure_extra_caps);
        let skip_caps = std::mem::take(&mut self.closure_skip_caps);
        let ret = self.closure_ret.take();
        let exit = self.closure_exit.take();
        let once = match self
            .lcx
            .node_types
            .get(&e.id)
            .map(|&t| self.tys().tcx().kind(t))
        {
            // A `par` branch runs once.
            _ if ret.is_some() => true,
            Some(HK::Fn { once, .. }) => once,
            _ => return self.unsupported(e.span, "a closure with no function type"),
        };
        let legacy = self
            .lcx
            .capture_modes
            .get(&SpanKey::from_span(&e.span))
            .cloned()
            .unwrap_or_default();
        let mut caps = Vec::new();
        let mut fields = Vec::new();
        let mut lent = Vec::new();
        let mut ops = Vec::new();
        // Whether the body writes a capture, which then needs the
        // environment lent mutably even when the capture was moved in.
        let mut writes = false;
        let mut captured = self.closure_captures(body);
        captured.retain(|s| !skip_caps.contains(s));
        captured.extend(extra_caps);
        self.assigned_caps.borrow_mut().clear();
        self.task_moves = task;
        let mut moved = self.moved_captures(body, &captured);
        // A closure the body returns escapes and takes its captures by
        // move (core semantics §9.3), so a non-`Copy` place of this
        // closure's that it uses is moved out of this one's environment:
        // this closure captures the place by move too, and is an `OnceFn`
        // (§9.1, §9.4, B-2026-10-26-8). A handle is counted, not moved.
        for inner in self.returned_closures_of(body) {
            let ExprKind::Closure { body: inner, .. } = &inner.kind else {
                continue;
            };
            for sym in self.closure_captures(inner) {
                let Some(&l) = self.locals.get(&sym) else {
                    continue;
                };
                let t = self.place_type(&Place::local(l));
                if captured.contains(&sym)
                    && !self.is_copy(t)
                    && !self.is_handle(t)
                    && !self.is_handle_aggregate(t)
                    && !matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_))
                {
                    moved.insert(sym);
                }
            }
        }
        self.task_moves = false;
        let assigned = std::mem::take(&mut *self.assigned_caps.borrow_mut());
        // The places a task takes by move because they drop before its
        // group (core semantics §9.5), as the checker found them.
        let task_moved: Vec<String> = if task {
            self.lcx
                .tc
                .core_task_moved_captures
                .get(&SpanKey::from_span(&e.span))
                .map(|v| v.iter().map(|(n, _, _)| n.clone()).collect())
                .unwrap_or_default()
        } else {
            Vec::new()
        };
        for sym in captured {
            let place = match (self.locals.get(&sym), self.captured.get(&sym)) {
                (Some(&l), _) => Place::local(l),
                (None, Some(p)) => p.clone(),
                // Only the method's `self` is captured without a local.
                (None, None) => match self.self_local {
                    Some(l) => Place::local(l),
                    None => return self.unsupported(e.span, "this capture"),
                },
            };
            let t = self.place_type(&place);
            let name = self
                .lcx
                .binding_syms
                .iter()
                .find(|(_, s)| **s == sym)
                .map(|((_, n), _)| n.clone())
                .unwrap_or_else(|| "self".to_string());
            let declared = match capture_mode {
                Some(ast::CaptureMode::Own) => Some(OwnershipMode::Own),
                Some(ast::CaptureMode::Ref) => Some(OwnershipMode::Ref),
                Some(ast::CaptureMode::MutRef) => Some(OwnershipMode::MutRef),
                None => None,
            };
            let explicit = declared.is_some();
            // The legacy analysis reads a bare parameter as owned, so under
            // D5 its by-move answer is replaced by the moves found here.
            let mode = declared.or_else(|| {
                legacy
                    .iter()
                    .find(|(n, _)| *n == name)
                    .map(|(_, m)| m.clone())
                    .filter(|m| !(d5_params() && *m == OwnershipMode::Own))
            });
            // A read-only capture of a `Copy` place is still a `ref`
            // capture, so writing the place while the closure is live is
            // refused rather than read stale (core semantics §9.1). A
            // once-callable closure moves something out of its captures, so
            // its non-`Copy` captures move in.
            writes |= mode == Some(OwnershipMode::MutRef);
            let cm = match mode {
                _ if escapes || by_value.contains(&sym) => CapMode::Value,
                _ if !explicit && task_moved.contains(&name) => CapMode::Value,
                Some(OwnershipMode::MutRef) => CapMode::Mut,
                // A capture the body assigns to is lent by `mut ref` (§9.1).
                _ if !explicit && assigned.contains(&sym) && !moved.contains(&sym) => CapMode::Mut,
                // A `par` branch's task reads a handle through a borrow and
                // counts each copy it takes, as the branch did in place, so
                // sibling branches can each take one (§6.1).
                _ if !explicit
                    && ret.is_some()
                    && (self.is_handle(t) || self.is_handle_aggregate(t)) =>
                {
                    CapMode::Ref
                }
                // An auto-par loop's tasks are joined before the loop
                // ends, so a fixed array they only read is borrowed rather
                // than copied into each of them (kata 1's 40 KB input into
                // all 16, B-2026-10-29-42).
                _ if !explicit
                    && auto_par
                    && !assigned.contains(&sym)
                    && matches!(self.tys().tcx().kind(t), HK::Array { .. }) =>
                {
                    CapMode::Ref
                }
                // A task copies them: its group outlives a loop body's
                // locals, which is the usual place to spawn from.
                _ if !explicit && !task && self.is_copy(t) => CapMode::Ref,
                Some(OwnershipMode::Own) => CapMode::Value,
                _ if self.is_copy(t) => CapMode::Value,
                // Under D5 a capture is moved place by place, as the body
                // moves it (§9.1).
                None | Some(OwnershipMode::Ref)
                    if ((once && !d5_params()) || moved.contains(&sym)) && !explicit =>
                {
                    CapMode::Value
                }
                _ => CapMode::Ref,
            };
            // A capture moved in that the body assigns to is written in
            // the environment.
            writes |= cm == CapMode::Value && assigned.contains(&sym);
            // A struct binding the body uses only through its fields is
            // captured field by field, so the rest of it stays usable
            // outside the closure (core semantics §9.1).
            if cm != CapMode::Value && self.locals.contains_key(&sym) {
                if let Some(names) = self.disjoint_fields(body, sym, t) {
                    for (name, idx, ft) in names {
                        let mutable = cm == CapMode::Mut;
                        let rt = self.tys().tcx().reference(ft, mutable);
                        let r = self.temp(rt);
                        let kind = if mutable {
                            BorrowKind::Mut
                        } else {
                            BorrowKind::Shared
                        };
                        self.assign(r, Rvalue::Ref(kind, place.field(idx, ft)));
                        caps.push((sym, cm, rt));
                        fields.push(Some(name));
                        lent.push(false);
                        ops.push(Operand::Move(Place::local(r)));
                    }
                    continue;
                }
            }
            let (ft, op) = match cm {
                // An escaping closure outlives the frame, so it holds a
                // counted copy of a handle (§6.1, §9.3), the caller's
                // staying usable, and a `Copy` value behind a borrowed
                // parameter rather than the borrow.
                CapMode::Value if escapes => {
                    let (mut p, mut it) = (place.clone(), t);
                    while let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(it) {
                        p = p.project(ProjElem::Deref);
                        it = inner;
                    }
                    if self.is_handle(it) || self.is_handle_aggregate(it) {
                        let l = self.temp(it);
                        self.count_copy(p, it, Place::local(l));
                        (it, Operand::Move(Place::local(l)))
                    } else if it != t && self.is_copy(it) {
                        (it, Operand::Copy(p))
                    } else if let Some(names) = (it != t)
                        .then(|| self.disjoint_fields(body, sym, it))
                        .flatten()
                        .filter(|ns| {
                            ns.iter().all(|&(_, _, ft)| {
                                self.is_copy(ft)
                                    || self.is_handle(ft)
                                    || self.is_handle_aggregate(ft)
                            })
                        })
                    {
                        // A borrowed value that cannot move out: the
                        // closure takes the `Copy` and handle fields it
                        // uses, one by one (§9.1).
                        for (name, idx, ft) in names {
                            let fp = p.clone().field(idx, ft);
                            let op = if self.is_copy(ft) {
                                Operand::Copy(fp)
                            } else {
                                let l = self.temp(ft);
                                self.count_copy(fp, ft, Place::local(l));
                                Operand::Move(Place::local(l))
                            };
                            caps.push((sym, CapMode::Value, ft));
                            fields.push(Some(name));
                            lent.push(false);
                            ops.push(op);
                        }
                        continue;
                    } else {
                        (t, self.use_place(place, t))
                    }
                }
                CapMode::Value => (t, self.use_place(place, t)),
                CapMode::Ref | CapMode::Mut => {
                    let mutable = cm == CapMode::Mut;
                    let rt = self.tys().tcx().reference(t, mutable);
                    let r = self.temp(rt);
                    let kind = if mutable {
                        BorrowKind::Mut
                    } else {
                        BorrowKind::Shared
                    };
                    self.assign(r, Rvalue::Ref(kind, place));
                    (rt, Operand::Move(Place::local(r)))
                }
            };
            caps.push((sym, cm, ft));
            fields.push(None);
            lent.push(
                cm != CapMode::Value
                    && matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_)),
            );
            ops.push(op);
        }
        let env = if (once || !moved.is_empty())
            && caps
                .iter()
                .any(|&(_, m, t)| m == CapMode::Value && !self.is_copy(t))
        {
            EnvMode::Value
        } else if writes || caps.iter().any(|&(_, m, _)| m == CapMode::Mut) {
            EnvMode::Mut
        } else {
            EnvMode::Ref
        };
        let def = DefId(self.lcx.next_closure);
        self.lcx.next_closure += 1;
        let ty = {
            let tcx = self.tys().tcx();
            let list: Vec<Ty> = caps.iter().map(|&(_, _, t)| t).collect();
            let captures = tcx.intern_list(&list);
            tcx.intern(HK::Closure { def, captures })
        };
        // An auto-par loop's task is named apart, so the closures the
        // program writes keep the names the verdicts know them by.
        let name = if auto_par {
            self.auto_par_count += 1;
            format!("{}.ap{}", self.name, self.auto_par_count - 1)
        } else {
            self.closure_count += 1;
            format!("{}.c{}", self.name, self.closure_count - 1)
        };
        self.lcx.closures.insert(def, (name.clone(), env));
        self.lcx.closure_exprs.insert(def, e);
        let simple = match &e.kind {
            ExprKind::Closure { params, .. } => params
                .iter()
                .all(|p| matches!(p.pattern.kind, PatternKind::Binding(_))),
            _ => false,
        };
        let ref_key = key && simple && is_place_expr(body) && {
            let kt = self.expr_ty(body)?;
            !self.is_copy(kt)
        };
        // A key with a user `Ord` is ordered by its `cmp`.
        if key {
            let kt = self.expr_ty(body)?;
            self.queue_user_cmp(kt);
        }
        self.lcx.closure_queue.push(ClosureJob {
            def,
            name,
            expr: e,
            args: self.args.clone(),
            caps,
            fields,
            lent,
            env,
            ty,
            ref_params,
            ref_key,
            ret,
            exit,
            ret_capture,
            chunk,
            outer: self.outer_fn.unwrap_or(self.b.instance().def),
        });
        let l = self.scoped_temp(ty);
        self.assign(l, Rvalue::Aggregate(AggregateKind::Closure { ty }, ops));
        Ok((Operand::Move(Place::local(l)), ty))
    }

    /// The body of a closure: `_1` is the environment, then the parameters.
    fn lower_closure_body(
        &mut self,
        job: &ClosureJob<'a>,
        params: &'a [ast::ClosureParam],
        body: &'a Expr,
    ) -> R<()> {
        self.par_exit = job.exit;
        self.push_scope();
        let env_ty = match job.env {
            EnvMode::Ref => self.tys().tcx().reference(job.ty, false),
            EnvMode::Mut => self.tys().tcx().reference(job.ty, true),
            EnvMode::Value => job.ty,
        };
        let env = self.b.arg("env", env_ty);
        let base = match job.env {
            EnvMode::Value => {
                self.schedule(ScopeEntry::Drop(Place::local(env)));
                Place::local(env)
            }
            _ => Place::local(env).project(ProjElem::Deref),
        };
        for (k, &(sym, cm, ft)) in job.caps.iter().enumerate() {
            // An auto-par task's constant capture is the constant (see
            // `const_lets`): kata 4's bounds, read through the environment,
            // left its binary search unfolded, 0.38x on one worker.
            if job.chunk.is_some() && job.fields[k].is_none() {
                if let Some(c) = self.lcx.const_lets.get(&sym).cloned() {
                    let vt = match (cm, self.tys().tcx().kind(ft)) {
                        (CapMode::Ref, HK::Ref(i)) if !job.lent[k] => Some(i),
                        (CapMode::Value, _) => Some(ft),
                        _ => None,
                    };
                    if vt == Some(c.ty) {
                        let l = self.temp(c.ty);
                        self.assign(l, Rvalue::Use(Operand::Const(c)));
                        self.locals.insert(sym, l);
                        continue;
                    }
                }
            }
            let p = base.field(k as u32, ft);
            let p = match cm {
                CapMode::Ref | CapMode::Mut if !job.lent[k] => p.project(ProjElem::Deref),
                _ => p,
            };
            match &job.fields[k] {
                Some(name) => {
                    self.captured_fields.insert((sym, name.clone()), p);
                }
                None => {
                    self.captured.insert(sym, p);
                }
            }
        }
        // The arguments come first (`_2..`); a borrowed one binds its name
        // after all of them are declared.
        let mut through = Vec::new();
        let mut destructured = Vec::new();
        // A parameter whose function type lends a `Copy` item that the
        // checker binds as a copy (`(1..n).find(|j| ..)`, core-semantics.md
        // §5.10, B-2026-10-13-32) takes the reference and copies it out.
        let fn_params = self.closure_fn_param_tys(job);
        for (i, p) in params.iter().enumerate() {
            let t = self.node_ty(p.pattern.id, p.span)?;
            let lent_copy = !job.ref_params
                && fn_params.get(i).is_some_and(|&pt| {
                    matches!(self.tys().tcx().kind(pt), HK::Ref(inner) if inner == t)
                        && self.is_copy(t)
                });
            let by_ref = job.ref_params || lent_copy;
            let PatternKind::Binding(name) = &p.pattern.kind else {
                // Lent: the parts bind through the reference.
                if by_ref && !matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_)) {
                    let rt = self.tys().tcx().reference(t, false);
                    let arg = self.b.arg("arg", rt);
                    destructured.push((&p.pattern, arg, rt));
                    continue;
                }
                let l = self.b.arg("arg", t);
                if self.needs_drop(t) {
                    self.schedule(ScopeEntry::Drop(Place::local(l)));
                }
                destructured.push((&p.pattern, l, t));
                continue;
            };
            let sym = self
                .lcx
                .binding_syms
                .get(&(p.pattern.id, name.clone()))
                .copied();
            if by_ref && !matches!(self.tys().tcx().kind(t), HK::Ref(_) | HK::MutRef(_)) {
                let rt = self.tys().tcx().reference(t, false);
                let arg = self.b.arg("arg", rt);
                through.push((name, p.pattern.id, sym, arg, t));
                continue;
            }
            let l = self.b.arg(name, t);
            if let Some(sym) = sym {
                self.locals.insert(sym, l);
            }
            if self.needs_drop(t) {
                self.schedule(ScopeEntry::Drop(Place::local(l)));
            }
        }
        // A closure handed to a library call gets each element by
        // reference; its name binds through it as a match part does (a
        // `Copy` value is copied out).
        let mut lent = FxHashMap::default();
        for (name, node, sym, arg, t) in through {
            let mut out = Vec::new();
            let elem = Place::local(arg).project(ProjElem::Deref);
            self.bind_one(name, node, elem, t, true, &mut out);
            for (l, lt) in out {
                if lt != t {
                    lent.insert(l, arg);
                }
                if let Some(sym) = sym {
                    self.locals.insert(sym, l);
                }
                self.declare(l, lt);
            }
        }
        self.bind_destructured(destructured)?;
        let ret = Place::local(Local::RETURN_PLACE);
        self.note_returned_closures(body);
        self.push_scope();
        if job.ref_key {
            // The key borrows the element itself, through the argument
            // rather than the name's own reference to it, which dies here.
            let mut p = self.expr_place(body, false)?;
            match lent.get(&p.local) {
                Some(&arg) if p.projection.is_empty() => {
                    self.assign(
                        Local::RETURN_PLACE,
                        Rvalue::Use(Operand::Copy(Place::local(arg))),
                    );
                }
                Some(&arg) => {
                    p.local = arg;
                    self.assign(Local::RETURN_PLACE, Rvalue::Ref(BorrowKind::Shared, p));
                }
                None => self.assign(Local::RETURN_PLACE, Rvalue::Ref(BorrowKind::Shared, p)),
            }
        } else if let Some(ch) = &job.chunk {
            // An auto-par task: its run of the loop's iterations, then its
            // part of the reduction, the capture it started at the
            // identity, when the loop has one.
            let (Some(lo), Some(hi)) = (
                self.captured.get(&ch.lo).cloned(),
                self.captured.get(&ch.hi).cloned(),
            ) else {
                return self.unsupported(body.span, "this loop's task");
            };
            let u = self.unit();
            let l = self.temp(u);
            let wide = ch.wide.map(|sums| {
                let wt = self.tys().tcx().intern(HK::Int(IntSize::I128));
                let nt = sums[0].ty;
                let [base, least, most, run, run_least, run_most] =
                    [wt, wt, wt, nt, nt, nt].map(|ty| {
                        let x = self.temp(ty);
                        self.assign(
                            x,
                            Rvalue::Use(Operand::Const(Const {
                                ty,
                                kind: ConstKind::Scalar(0),
                            })),
                        );
                        x
                    });
                WideAcc {
                    sums,
                    base,
                    least,
                    most,
                    run,
                    run_least,
                    run_most,
                }
            });
            self.wide_acc = wide;
            self.push_scope();
            self.range_loop(
                &None,
                ch.pattern,
                ch.body,
                Operand::Copy(lo),
                Some(Operand::Copy(hi)),
                false,
                ch.ty,
            )?;
            self.pop_scope()?;
            self.wide_acc = None;
            if let Some(w) = wide {
                self.wide_rebase(w);
            }
            self.assign(l, Rvalue::Use(unit_const(u)));
            let value = match (
                wide,
                job.ret_capture.and_then(|s| self.captured.get(&s).cloned()),
            ) {
                (Some(w), _) => Rvalue::Aggregate(
                    AggregateKind::Tuple,
                    [w.base, w.least, w.most]
                        .map(|x| Operand::Copy(Place::local(x)))
                        .to_vec(),
                ),
                // A pushed-onto `Vec` moves out (`AutoRed::push`).
                (None, Some(p)) if !self.is_copy(self.place_type(&p)) => {
                    Rvalue::Use(Operand::Move(p))
                }
                (None, Some(p)) => Rvalue::Use(Operand::Copy(p)),
                (None, None) => Rvalue::Use(unit_const(u)),
            };
            self.assign(Local::RETURN_PLACE, value);
        } else if let Some((rt, Some(ok))) = job.ret {
            // A `par` branch of a function that can fail: its value is the
            // success, and its `?` returns the error from the task.
            let vt = self.expr_ty(body)?;
            let l = self.temp(vt);
            self.expr_into(body, Place::local(l))?;
            let kind = self.adt_aggregate(rt, ok);
            self.assign(
                Local::RETURN_PLACE,
                Rvalue::Aggregate(kind, vec![Operand::Move(Place::local(l))]),
            );
        } else {
            self.expr_into(body, ret)?;
        }
        self.pop_scope()?;
        self.return_exit()?;
        self.scopes.clear();
        Ok(())
    }

    /// `g.spawn(f)` on an `IsolatingGroup` (core-semantics §11.12): a task
    /// of the group it holds, whose closure is `f` with its value in `Ok`,
    /// as a `return` or `?` in it leaves it. A panic in the task is the
    /// `Err` its handle holds instead.
    fn isolating_spawn(&mut self, object: &'a Expr, f: &'a CallArg, dest: Place) -> R<()> {
        let Some(group_ty) = self.library_struct("TaskGroup", &[]) else {
            return self.unsupported(f.value.span, "`spawn` without the library's `TaskGroup`");
        };
        let ht = self.place_type(&dest);
        let tt = match self.tys().tcx().kind(ht) {
            HK::Adt { args, .. } => self.tys().tcx().list(args).first().copied(),
            _ => None,
        };
        let Some((tt, ev)) = tt.and_then(|t| Some((t, self.error_variant(t)?))) else {
            return self.unsupported(f.value.span, "this isolating task's result type");
        };
        let ok = 1 - ev;
        let Some(vt) = self.tys().tcx().field_ty(tt, Some(ok), 0) else {
            return self.unsupported(f.value.span, "this isolating task's result type");
        };
        let p = self.expr_place(object, false)?;
        let (p, _) = self.strip_refs(p);
        let gr = self.ref_to(p.field(0, group_ty), group_ty);
        let task = match f.value.kind {
            ExprKind::Closure { .. } => &f.value,
            _ => self.isolating_task_expr(&f.value, vt),
        };
        self.closure_task = true;
        self.closure_ret = Some((tt, Some(ok)));
        self.closure_exit = Some((vt, ok));
        let made = self.closure_value(task);
        self.closure_task = false;
        self.closure_ret = None;
        self.closure_exit = None;
        let (c, _) = made?;
        self.call_native("TaskGroup.spawn", vec![gr, c], dest);
        Ok(())
    }

    /// The closure `own || f()` an isolating group's `spawn(f)` of a
    /// function value runs as, `f`'s value of type `vt` (B-2026-10-25-22):
    /// the value moves in, as the spawn takes it. One per call, kept for
    /// every instance lowered.
    fn isolating_task_expr(&mut self, f: &'a Expr, vt: Ty) -> &'a Expr {
        if let Some(&t) = self.lcx.isolating_task_exprs.get(&f.id) {
            return t;
        }
        let call = NodeId(self.lcx.next_synthetic_node);
        let id = NodeId(self.lcx.next_synthetic_node - 1);
        self.lcx.next_synthetic_node -= 2;
        self.lcx.node_types.insert(call, vt);
        // A function by name is called directly, so a panic in it reaches
        // the task as any call's does; other values, and a generic
        // function's instance, are called through.
        let named = match self.lcx.res.get(&f.id) {
            Some(&Res::Def(d)) => self.lcx.fns.get(&d).filter(|i| {
                i.f.generic_params
                    .as_ref()
                    .is_none_or(|g| g.params.is_empty())
            }),
            _ => None,
        };
        let callee = match (named, self.lcx.res.get(&f.id)) {
            (Some(_), Some(&Res::Def(d))) => Callee::Def(d),
            _ => Callee::Value,
        };
        let substs = self.tys().tcx().empty_list();
        self.lcx.calls.insert(call, ResolvedCall { callee, substs });
        if let Some(&ft) = self.lcx.node_types.get(&f.id) {
            self.lcx.node_types.insert(id, ft);
        }
        let t: &'a Expr = Box::leak(Box::new(Expr {
            kind: ExprKind::Closure {
                params: Vec::new(),
                capture_mode: Some(ast::CaptureMode::Own),
                prefix_span: None,
                body: Box::new(Expr {
                    kind: ExprKind::Call {
                        callee: Box::new(f.clone()),
                        args: Vec::new(),
                    },
                    span: f.span,
                    id: call,
                }),
            },
            span: f.span,
            id,
        }));
        self.lcx.isolating_task_exprs.insert(f.id, t);
        t
    }

    /// The environment argument for calling the closure value `p` (of type
    /// `t`: the closure or a reference to it), as its body takes it.
    fn env_operand(&mut self, span: Span, p: Place, t: Ty) -> R<(Operand, Ty, String)> {
        let tcx = self.tys().tcx();
        let (inner, through) = match tcx.kind(t) {
            HK::Ref(i) => (i, Some(false)),
            HK::MutRef(i) => (i, Some(true)),
            _ => (t, None),
        };
        let HK::Closure { def, .. } = tcx.kind(inner) else {
            return self.unsupported(span, "a call through this value");
        };
        let Some((name, env)) = self.lcx.closures.get(&def).cloned() else {
            return self.unsupported(span, "a call to an unknown closure");
        };
        let target = match through {
            Some(_) => p.clone().project(ProjElem::Deref),
            None => p.clone(),
        };
        let op = match (env, through) {
            (EnvMode::Ref, Some(false)) => Operand::Copy(p),
            (EnvMode::Ref, _) | (EnvMode::Mut, None | Some(true)) => {
                let mutable = env == EnvMode::Mut;
                let rt = self.tys().tcx().reference(inner, mutable);
                let r = self.temp(rt);
                let kind = if mutable {
                    BorrowKind::Mut
                } else {
                    BorrowKind::Shared
                };
                self.assign(r, Rvalue::Ref(kind, target));
                Operand::Move(Place::local(r))
            }
            (EnvMode::Value, None) => self.use_place(target, inner),
            _ => return self.unsupported(span, "calling this closure through a reference"),
        };
        Ok((op, inner, name))
    }

    /// A `let` binding `l` written with a function type that declares an
    /// effect clause: a call through `l`, or through a capture of it, has
    /// those effects (B-2026-10-27-2, B-2026-10-27-8).
    fn note_declared_effects(
        &mut self,
        l: Local,
        (node, name): (NodeId, &str),
        ty: Option<&ast::TypeExpr>,
    ) {
        if let Some(declared) = ty.and_then(declared_effects) {
            if let Some(&sym) = self.lcx.binding_syms.get(&(node, name.to_string())) {
                self.lcx.let_fn_effects.insert(sym, declared.clone());
            }
            self.b.fn_value_effects.push((l, declared));
        }
    }

    /// The effect clause of the function value `callee` names, when its
    /// written type declares one: a struct field's (`(j.run)(3)`) or an
    /// annotated `let`'s (B-2026-10-27-2).
    fn callee_effects(&mut self, callee: &'a Expr) -> Option<Vec<DeclaredEffect>> {
        match &callee.kind {
            ExprKind::FieldAccess { object, field } => {
                let mut t = self.expr_ty(object).ok()?;
                if let HK::Ref(i) | HK::MutRef(i) = self.tys().tcx().kind(t) {
                    t = i;
                }
                let (adt, _) = self.tys().tcx().adt_of(t)?;
                self.lcx
                    .fn_field_effects
                    .get(&(adt.name.clone(), field.clone()))
                    .cloned()
            }
            ExprKind::Identifier(_) => match self.lcx.res.get(&callee.id) {
                Some(Res::Local(sym)) => self.lcx.let_fn_effects.get(sym).cloned(),
                _ => None,
            },
            _ => None,
        }
    }

    /// `f(args)` where `f` is a value: a closure (its body, with the
    /// environment first) or a function item (a direct call).
    fn call_value(
        &mut self,
        e: &'a Expr,
        callee: &'a Expr,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        let ct = self.expr_ty(callee)?;
        let peeled = match self.tys().tcx().kind(ct) {
            HK::Ref(i) | HK::MutRef(i) => i,
            _ => ct,
        };
        let (func, mut ops, param_tys) = match self.tys().tcx().kind(peeled) {
            HK::FnDef { def, args: fargs } => {
                // `let g = F64.from; g(x)`.
                let def = if self.lcx.fns.contains_key(&def) {
                    def
                } else {
                    self.lcx.wrapper_from(def).unwrap_or(def)
                };
                let Some(f) = self.lcx.fns.get(&def).map(|i| i.f) else {
                    return self.unsupported(e.span, "a call to this function value");
                };
                // A generic item's value carries its instance
                // (B-2026-10-18-12).
                let fargs = self.tys().tcx().list(fargs);
                let mut pts = Vec::new();
                for p in &f.params {
                    pts.push(self.callee_param_ty(p, &fargs)?);
                }
                let name = self.lcx.instance(def, fargs.clone());
                (self.fn_operand(&name, def, fargs), Vec::new(), pts)
            }
            HK::Closure { def, .. } => {
                let p = self.expr_place(callee, false)?;
                let (env, _, name) = self.env_operand(callee.span, p, ct)?;
                let Some(job_params) = self.closure_param_tys(def) else {
                    return self.unsupported(e.span, "a call to this closure");
                };
                (
                    self.fn_operand(&name, def, self.args.clone()),
                    vec![env],
                    job_params,
                )
            }
            // An erased function value: called through a `ref` (`Fn`), a
            // `mut ref` (`MutFn`) or by value (`OnceFn`).
            HK::Fn {
                params,
                once,
                mutable,
                ..
            } => {
                let mut p = self.expr_place(callee, mutable && !once)?;
                if peeled != ct {
                    p = p.project(ProjElem::Deref);
                }
                let declared = self.callee_effects(callee);
                let func = if once && declared.is_some() && !p.projection.is_empty() {
                    // The clause is keyed by a local of the value's own.
                    let t = self.temp(peeled);
                    self.assign(t, Rvalue::Use(Operand::Move(p)));
                    Operand::Move(Place::local(t))
                } else if once {
                    Operand::Move(p)
                } else {
                    let rt = self.tys().tcx().reference(peeled, mutable);
                    let r = self.temp(rt);
                    let kind = if mutable {
                        BorrowKind::Mut
                    } else {
                        BorrowKind::Shared
                    };
                    self.assign(r, Rvalue::Ref(kind, p));
                    Operand::Copy(Place::local(r))
                };
                if let (Some(l), Some(declared)) = (func.place(), declared) {
                    if l.projection.is_empty() {
                        self.b.fn_value_effects.push((l.local, declared));
                    }
                }
                let pts = self.tys().tcx().list(params).to_vec();
                (func, Vec::new(), pts)
            }
            _ => return self.unsupported(e.span, "a call through a function value"),
        };
        if param_tys.len() != args.len() {
            return self.unsupported(e.span, "a call through a value with the wrong arity");
        }
        let mut pending = Vec::with_capacity(args.len());
        for (a, pt) in args.iter().zip(param_tys) {
            pending.push(self.arg_pending(&a.value, pt)?);
        }
        ops.extend(self.finish_args(pending)?);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: ops,
                destination: dest,
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(())
    }

    /// The parameter types of the function type a closure job was checked
    /// against, in its instance; empty when the checker recorded none.
    fn closure_fn_param_tys(&mut self, job: &ClosureJob<'a>) -> Vec<Ty> {
        let Some(&t) = self.lcx.node_types.get(&job.expr.id) else {
            return Vec::new();
        };
        let HK::Fn { params, .. } = self.tys().tcx().kind(t) else {
            return Vec::new();
        };
        let params = self.tys().tcx().list(params).to_vec();
        params
            .into_iter()
            .filter_map(|p| self.lcx.mir_ty(p, &job.args).ok())
            .collect()
    }

    /// A closure's parameter types, from its checked function type.
    fn closure_param_tys(&mut self, def: DefId) -> Option<Vec<Ty>> {
        let expr = *self.lcx.closure_exprs.get(&def)?;
        let t = *self.lcx.node_types.get(&expr.id)?;
        let HK::Fn { params, .. } = self.tys().tcx().kind(t) else {
            return None;
        };
        let params = self.tys().tcx().list(params).to_vec();
        let args = self.args.clone();
        params
            .into_iter()
            .map(|p| self.lcx.mir_ty(p, &args).ok())
            .collect()
    }

    /// An argument for a function-typed parameter: the closure borrowed
    /// the way its body takes its environment (moved when called once), the
    /// function item as a constant, or an erased value lent when `lend`
    /// (the parameter is not `own`). The parameter then has the type
    /// returned here in that instance of the callee.
    fn fn_arg(&mut self, a: &'a Expr, want: Option<Ty>, lend: bool) -> R<(Operand, Ty)> {
        let (op, t) = match &a.kind {
            ExprKind::Closure { .. } => {
                let (op, t) = self.closure_value(a)?;
                let Operand::Move(p) = op else { unreachable!() };
                (p, t)
            }
            ExprKind::Identifier(_) | ExprKind::Path { .. }
                if matches!(self.lcx.res.get(&a.id), Some(Res::Def(_))) =>
            {
                let Some(Res::Def(d)) = self.lcx.res.get(&a.id) else {
                    unreachable!()
                };
                return self.fn_item_value(a, *d, want);
            }
            _ => {
                let p = self.expr_place(a, false)?;
                let t = self.place_type(&p);
                (p, t)
            }
        };
        let tcx = self.tys().tcx();
        let inner = match tcx.kind(t) {
            HK::Ref(i) | HK::MutRef(i) => i,
            _ => t,
        };
        match tcx.kind(inner) {
            // An erased `Fn` or `MutFn` value is lent to a parameter that
            // borrows it (core semantics §9.3), so a value in a collection
            // element or a local passed twice stays where it is
            // (B-2026-10-27-12). A `OnceFn` is consumed.
            HK::Fn { once, mutable, .. } if lend && t == inner && !once => {
                let rt = tcx.reference(inner, mutable);
                let r = self.temp(rt);
                let kind = if mutable {
                    BorrowKind::Mut
                } else {
                    BorrowKind::Shared
                };
                self.assign(r, Rvalue::Ref(kind, op));
                Ok((Operand::Move(Place::local(r)), rt))
            }
            // A function item, or an erased `Fn` value: passed as it is.
            HK::FnDef { .. } | HK::Fn { .. } => Ok((self.use_place(op, t), t)),
            HK::Closure { def, .. } => {
                let env = self.lcx.closures.get(&def).map(|c| c.1);
                match (env, tcx.kind(t)) {
                    // Already a reference of the right kind: pass it on, a
                    // `mut ref` reborrowed (B-2026-10-19-68).
                    (Some(EnvMode::Ref), HK::Ref(_)) => Ok((Operand::Copy(op), t)),
                    (Some(EnvMode::Mut), HK::MutRef(_)) => {
                        let r = self.temp(t);
                        self.assign(r, Rvalue::Ref(BorrowKind::Mut, op.project(ProjElem::Deref)));
                        Ok((Operand::Move(Place::local(r)), t))
                    }
                    (Some(EnvMode::Value), _) => Ok((self.use_place(op, t), t)),
                    (Some(mode), _) => {
                        let mutable = mode == EnvMode::Mut;
                        let target = if t == inner {
                            op
                        } else {
                            op.project(ProjElem::Deref)
                        };
                        let rt = self.tys().tcx().reference(inner, mutable);
                        let r = self.temp(rt);
                        let kind = if mutable {
                            BorrowKind::Mut
                        } else {
                            BorrowKind::Shared
                        };
                        self.assign(r, Rvalue::Ref(kind, target));
                        Ok((Operand::Move(Place::local(r)), rt))
                    }
                    (None, _) => self.unsupported(a.span, "passing an unknown closure"),
                }
            }
            _ => self.unsupported(a.span, "this function argument"),
        }
    }

    /// An argument to a library method: by value, except that a borrowing
    /// parameter (`push_str`'s) takes a string literal as a constant and any
    /// other value by reference.
    fn lib_arg(&mut self, a: &'a Expr, borrows: bool) -> R<Operand> {
        if !borrows {
            return self.expr_operand(a);
        }
        if let ExprKind::StringLit(s) = &a.kind {
            return Ok(self.static_str(s));
        }
        let at = self.expr_ty(a)?;
        match self.tys().tcx().kind(at) {
            // A `mut ref` place lends a shared reborrow, `&(*r)`, so the
            // caller keeps its reference.
            HK::MutRef(inner) if self.is_place(a) => {
                let p = self.expr_place(a, false)?.project(ProjElem::Deref);
                let rt = self.tys().tcx().reference(inner, false);
                let r = self.temp(rt);
                self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
                return Ok(Operand::Move(Place::local(r)));
            }
            HK::Ref(_) | HK::MutRef(_) => return self.expr_operand(a),
            _ => {}
        }
        let p = self.expr_place(a, false)?;
        let rt = self.tys().tcx().reference(at, false);
        let r = self.temp(rt);
        self.assign(r, Rvalue::Ref(BorrowKind::Shared, p));
        Ok(Operand::Move(Place::local(r)))
    }

    /// The `Option`/`Result` helpers the stdlib will define in Kāra, lowered
    /// in place until it does: `is_some`/`is_none`/`is_ok`/`is_err` read the
    /// discriminant; `unwrap`/`expect`/`unwrap_or` take the receiver by value
    /// and move the payload out. `false` when `method` is not one of them.
    fn option_method(
        &mut self,
        object: &'a Expr,
        method: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<bool> {
        let ot = self.expr_ty(object)?;
        let (base, through_ref) = match self.tys().tcx().kind(ot) {
            HK::Ref(t) | HK::MutRef(t) => (t, true),
            _ => (ot, false),
        };
        let Some((adt, _)) = self.tys().tcx().adt_of(base) else {
            return Ok(false);
        };
        let (ok_name, err_name) = match adt.name.as_str() {
            "Option" => ("Some", "None"),
            "Result" => ("Ok", "Err"),
            _ => return Ok(false),
        };
        let idx = |n: &str| {
            adt.variants
                .iter()
                .position(|v| v.name == n)
                .map(|i| i as u32)
        };
        let (Some(ok), Some(err)) = (idx(ok_name), idx(err_name)) else {
            return Ok(false);
        };
        let by_value = matches!(method, "unwrap" | "expect" | "unwrap_or");
        if !by_value && !matches!(method, "is_some" | "is_ok" | "is_none" | "is_err") {
            return Ok(false);
        }
        if by_value && through_ref {
            return Ok(false);
        }
        let p = if by_value {
            if self.is_place(object) && self.is_local_rooted(object) {
                self.expr_place(object, false)?
            } else {
                let l = self.temp_of(object, base)?;
                Place::local(l)
            }
        } else {
            self.deref_place(object, false)?.0
        };
        // `unwrap_or`'s argument is evaluated before the test, and dropped
        // at the statement's end when the payload is taken instead.
        let default = match (method, args) {
            ("unwrap_or", [a]) => {
                let l = self.temp_of(&a.value, base_payload_or(self, base, ok))?;
                Some(l)
            }
            _ => None,
        };
        let i64_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let d = self.temp(i64_t);
        self.assign(d, Rvalue::Discriminant(p.clone()));
        if !by_value {
            let want = if matches!(method, "is_some" | "is_ok") {
                ok
            } else {
                err
            };
            self.assign(
                dest,
                Rvalue::BinaryOp(
                    BinOp::Eq,
                    Operand::Copy(Place::local(d)),
                    Operand::Const(Const {
                        ty: i64_t,
                        kind: ConstKind::Scalar(want as u128),
                    }),
                ),
            );
            return Ok(true);
        }
        let ok_bb = self.b.new_block();
        let other = self.b.new_block();
        let join = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(d)),
                targets: SwitchTargets {
                    values: vec![(ok as u128, ok_bb)],
                    otherwise: other,
                },
            },
            ok_bb,
        );
        match self.tys().tcx().field_ty(base, Some(ok), 0) {
            Some(pt) => {
                let fp = p.project(ProjElem::Downcast(VariantIdx(ok))).field(0, pt);
                let op = self.use_place(fp, pt);
                self.assign(dest.clone(), Rvalue::Use(op));
            }
            None => self.assign(dest.clone(), Rvalue::Use(unit_const(self.unit()))),
        }
        self.goto(join);
        self.cur = other;
        match default {
            Some(l) => {
                let t = self.b.local_ty(l);
                let op = self.use_place(Place::local(l), t);
                self.assign(dest, Rvalue::Use(op));
                self.goto(join);
            }
            None => self.diverge(TerminatorKind::Abort {
                reason: AbortReason::Panic,
            }),
        }
        self.cur = join;
        Ok(true)
    }

    /// `left ?? right`: `left`'s `Some`/`Ok` payload, else `right`, which is
    /// evaluated only then (design.md § Optional chaining). `left` is taken
    /// by value, as `unwrap_or` takes its receiver.
    fn nil_coalesce(&mut self, left: &'a Expr, right: &'a Expr, dest: Place) -> R<()> {
        let mut lt = self.expr_ty(left)?;
        let unsupported = |s: &mut Self| s.unsupported(left.span, "`??` on this type");
        // A `ref` of a `Copy` `Option` / `Result` reads the wrapper through
        // the reference (design.md § `*` and `ref` in expressions,
        // B-2026-10-14-40).
        let through_ref = match self.tys().tcx().kind(lt) {
            HK::Ref(inner) | HK::MutRef(inner) => {
                lt = inner;
                true
            }
            _ => false,
        };
        let Some((adt, _)) = self.tys().tcx().adt_of(lt) else {
            return unsupported(self);
        };
        let ok_name = match adt.name.as_str() {
            "Option" => "Some",
            "Result" => "Ok",
            _ => return unsupported(self),
        };
        let Some(ok) = adt.variants.iter().position(|v| v.name == ok_name) else {
            return unsupported(self);
        };
        let ok = ok as u32;
        let p = if self.is_place(left) && self.is_local_rooted(left) {
            self.expr_place(left, false)?
        } else {
            let left_ty = self.expr_ty(left)?;
            let l = self.temp_of(left, left_ty)?;
            Place::local(l)
        };
        let p = if through_ref {
            p.project(ProjElem::Deref)
        } else {
            p
        };
        let i64_t = self.tys().tcx().intern(HK::Int(IntSize::I64));
        let d = self.temp(i64_t);
        self.assign(d, Rvalue::Discriminant(p.clone()));
        let ok_bb = self.b.new_block();
        let other = self.b.new_block();
        let join = self.b.new_block();
        self.goto_with(
            TerminatorKind::SwitchInt {
                discr: Operand::Copy(Place::local(d)),
                targets: SwitchTargets {
                    values: vec![(ok as u128, ok_bb)],
                    otherwise: other,
                },
            },
            ok_bb,
        );
        match self.tys().tcx().field_ty(lt, Some(ok), 0) {
            Some(pt) => {
                let mut fp = p.project(ProjElem::Downcast(VariantIdx(ok))).field(0, pt);
                let mut pt = pt;
                // `Option[ref V] ?? v` with a `Copy` `V` reads the value
                // (design.md, `?` and `??`).
                let dt = self.place_type(&dest);
                if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(pt) {
                    if !matches!(self.tys().tcx().kind(dt), HK::Ref(_) | HK::MutRef(_)) {
                        fp = fp.project(ProjElem::Deref);
                        pt = inner;
                    }
                }
                let op = self.use_place(fp, pt);
                self.assign(dest.clone(), Rvalue::Use(op));
            }
            None => self.assign(dest.clone(), Rvalue::Use(unit_const(self.unit()))),
        }
        self.goto(join);
        self.cur = other;
        // B-2026-10-18-53 — `opt ?? ""` with `opt: Option[ref String]` is a
        // `ref String`, so a fallback that is a value is held in a temporary
        // the result borrows. It lives as long as a `let` binding of the
        // result, else to the end of the statement.
        let dt = self.place_type(&dest);
        let fallback_value = match self.tys().tcx().kind(dt) {
            HK::Ref(inner) | HK::MutRef(inner) => {
                let rt = self.expr_ty(right)?;
                let literal = matches!(
                    right.kind,
                    ExprKind::StringLit(_) | ExprKind::InterpolatedStringLit(_)
                );
                (literal || !self.is_reference(rt)).then_some(inner)
            }
            _ => None,
        };
        let kind = if matches!(self.tys().tcx().kind(dt), HK::MutRef(_)) {
            BorrowKind::Mut
        } else {
            BorrowKind::Shared
        };
        match fallback_value {
            // A named place is borrowed where it is, never moved into the
            // temporary (B-2026-10-23-2): `m.get(k) ?? empty` leaves `empty`.
            Some(_) if is_place_expr(right) && self.is_place(right) => {
                self.push_scope();
                let p = self.expr_place(right, kind == BorrowKind::Mut)?;
                self.assign(dest, Rvalue::Ref(kind, p));
                self.pop_scope()?;
            }
            Some(inner) => {
                let l = self.temp(inner);
                self.push_scope();
                self.expr_into(right, Place::local(l))?;
                self.pop_scope()?;
                if self.needs_drop(inner) {
                    let at = self.let_scope.unwrap_or(self.scopes.len() - 1);
                    self.scopes[at].push(ScopeEntry::Drop(Place::local(l)));
                }
                self.assign(dest, Rvalue::Ref(kind, Place::local(l)));
            }
            None => {
                self.push_scope();
                self.expr_into(right, dest)?;
                self.pop_scope()?;
            }
        }
        self.goto(join);
        self.cur = join;
        Ok(())
    }

    /// A library method the interpreter implements natively.
    /// `v.extend(items)` from a source that is not a `Vec`, slice or array
    /// (B-2026-10-13-19): a call of the library's `vec_extend_*` for that
    /// source, which moves each item onto the end. False when the native
    /// `extend` takes the source.
    fn extend_from_iterable(
        &mut self,
        object: &'a Expr,
        recv: Ty,
        src: &'a CallArg,
        dest: Place,
    ) -> R<bool> {
        let st = self.expr_ty(&src.value)?;
        let tcx = self.tys().tcx();
        let (deque, vargs) = match tcx.kind(recv) {
            HK::Intrinsic {
                kind: IntrinsicKind::Vec,
                args,
            } => (false, args),
            // A deque has no native `extend`: every source goes through a
            // library helper (B-2026-10-26-18).
            HK::Intrinsic {
                kind: IntrinsicKind::VecDeque,
                args,
            } => (true, args),
            _ => return Ok(false),
        };
        let elem = tcx.list(vargs)[0];
        let (helper, inst_args) = match tcx.kind(st) {
            HK::Ref(_) | HK::MutRef(_) | HK::Slice { .. } | HK::Array { .. } => return Ok(false),
            HK::Intrinsic { kind, args } => {
                let sargs = crate::mir::ty::table_args(kind, tcx.list(args));
                let helper = match (deque, kind) {
                    (false, IntrinsicKind::Vec) => return Ok(false),
                    (false, IntrinsicKind::Set) => "vec_extend_set",
                    (false, IntrinsicKind::SortedSet) => "vec_extend_sorted_set",
                    (false, IntrinsicKind::VecDeque) => "vec_extend_deque",
                    (false, IntrinsicKind::Map) => "vec_extend_map",
                    (false, IntrinsicKind::SortedMap) => "vec_extend_sorted_map",
                    (true, IntrinsicKind::Vec) => "deque_extend_vec",
                    (true, IntrinsicKind::Set) => "deque_extend_set",
                    (true, IntrinsicKind::SortedSet) => "deque_extend_sorted_set",
                    (true, IntrinsicKind::VecDeque) => "deque_extend_deque",
                    (true, IntrinsicKind::Map) => "deque_extend_map",
                    (true, IntrinsicKind::SortedMap) => "deque_extend_sorted_map",
                };
                (helper, sargs.to_vec())
            }
            // A type that is `IntoIterator` and no iterator (B-2026-10-20-32).
            HK::Adt { def, .. } if self.only_into_iterator(def) => {
                let helper = if deque {
                    "deque_extend_into"
                } else {
                    "vec_extend_into"
                };
                (helper, vec![elem, st])
            }
            _ if deque => ("deque_extend_iter", vec![elem, st]),
            _ => ("vec_extend_iter", vec![elem, st]),
        };
        let Some(d) = self.lcx.defs.lookup(0, helper) else {
            return Ok(false);
        };
        let f = self.lcx.fns[&d].f;
        let recv = self.recv_place(object, true)?;
        let pt = self.callee_param_ty(&f.params[1], &inst_args)?;
        let pending = self.arg_pending(&src.value, pt)?;
        let mut rest = self.finish_args(vec![pending])?;
        let mut ops = vec![self.recv_borrow_after(recv, &mut rest)?];
        ops.extend(rest);
        let name = self.lcx.instance(d, inst_args.clone());
        let func = self.fn_operand(&name, d, inst_args);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: ops,
                destination: dest,
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(true)
    }

    /// Whether the ADT `def` implements `IntoIterator` and not `Iterator`.
    fn only_into_iterator(&self, def: DefId) -> bool {
        let name = self.lcx.def_name(def);
        let has = |tr: &str| {
            self.lcx.tc.impl_trait_assoc_types.contains_key(&(
                name.clone(),
                tr.to_string(),
                "Item".to_string(),
            ))
        };
        has("IntoIterator") && !has("Iterator")
    }

    /// `T.parse(s)` as `docs/library/core-types.md` gives it, into `dest`
    /// of type `Result[T, ParseError]` (B-2026-10-12-6): the native's
    /// `Option[T]` and `s` go to the library's `parse_result_int` or
    /// `parse_result_float`, which names the error. `false` when `dest`
    /// is not a `Result` (the program's own `Option` reading) or the
    /// library has no helper for `owner`.
    fn parse_result_call(&mut self, owner: &str, s: &'a Expr, rt: Ty, dest: Place) -> R<bool> {
        let (helper, signed) = match owner {
            "i8" | "i16" | "i32" | "i64" | "i128" | "isize" => ("parse_result_int", Some(true)),
            "u8" | "u16" | "u32" | "u64" | "u128" | "usize" => ("parse_result_int", Some(false)),
            "f32" | "f64" => ("parse_result_float", None),
            _ => return Ok(false),
        };
        let tcx = self.tys().tcx();
        let Some(ok) = tcx
            .adt_of(rt)
            .filter(|(a, _)| a.variants.iter().any(|v| v.name == "Err"))
            .and_then(|(a, _)| a.variants.iter().position(|v| v.name == "Ok"))
        else {
            return Ok(false);
        };
        let Some(nt) = tcx.field_ty(rt, Some(ok as u32), 0) else {
            return Ok(false);
        };
        let Some(d) = self.lcx.defs.lookup(0, helper) else {
            return Ok(false);
        };
        let f = self.lcx.fns[&d].f;
        let inst_args = vec![nt];
        let opt_t = self.callee_param_ty(&f.params[0], &inst_args)?;
        let str_t = self.callee_param_ty(&f.params[1], &inst_args)?;
        // The input once, read by both calls.
        let op = self.arg_operand(s, str_t)?;
        let sl = self.temp(str_t);
        self.assign(Place::local(sl), Rvalue::Use(op));
        let o = self.temp(opt_t);
        self.call_native(
            &format!("{owner}.parse"),
            vec![Operand::Copy(Place::local(sl))],
            Place::local(o),
        );
        let mut ops = vec![
            Operand::Move(Place::local(o)),
            Operand::Copy(Place::local(sl)),
        ];
        if let Some(signed) = signed {
            ops.push(bool_const(self.tys().bool(), signed));
        }
        let name = self.lcx.instance(d, inst_args.clone());
        let func = self.fn_operand(&name, d, inst_args);
        let next = self.b.new_block();
        self.goto_with(
            TerminatorKind::Call {
                func,
                args: ops,
                destination: dest,
                target: Some(next),
                unwind: UnwindAction::Abort,
            },
            next,
        );
        Ok(true)
    }

    /// The library's `get_mut` on a `Map` or `SortedMap`, called with the
    /// key's view (a `Str` for a `String` key, a `Slice` for a `Vec` key):
    /// the native `get_mut_by_view`, which reads either form as `get` does,
    /// rather than the library instance, whose key parameter is `ref K`
    /// (B-2026-10-18-39).
    fn get_mut_by_key_view(
        &mut self,
        object: &'a Expr,
        method: &str,
        args: &'a [CallArg],
    ) -> R<bool> {
        let [k] = args else {
            return Ok(false);
        };
        // The receiver is the library's own type, so the method is the
        // library's.
        if method != "get_mut" {
            return Ok(false);
        }
        let ot = self.expr_ty(object)?;
        let (_, base) = self.strip_ty_full(ot);
        let key = match self.tys().tcx().kind(base) {
            HK::Intrinsic {
                kind: IntrinsicKind::Map | IntrinsicKind::SortedMap,
                args,
            } => self.tys().tcx().list(args)[0],
            _ => return Ok(false),
        };
        let at = self.expr_ty(&k.value)?;
        let (_, arg) = self.strip_ty_full(at);
        Ok(arg != key
            && matches!(
                self.tys().tcx().kind(arg),
                HK::Str | HK::StaticStr | HK::Slice { .. }
            ))
    }

    fn builtin_method(
        &mut self,
        e: &'a Expr,
        key: &str,
        object: &'a Expr,
        method: &str,
        args: &'a [CallArg],
        dest: Place,
    ) -> R<()> {
        let ot = self.expr_ty(object)?;
        let base = match self.tys().tcx().kind(ot) {
            HK::Ref(t) | HK::MutRef(t) => t,
            _ => ot,
        };
        if let ("extend", [src]) = (method, args) {
            if self.extend_from_iterable(object, base, src, dest.clone())? {
                return Ok(());
            }
        }
        if let ("spawn", [f]) = (method, args) {
            if self.tys().display(base) == "IsolatingGroup" {
                return self.isolating_spawn(object, f, dest);
            }
        }
        if let ("discriminant", []) = (method, args) {
            let p = self.expr_place(object, false)?;
            let (p, t) = self.strip_refs(p);
            if self.discriminant_into(e, p, t, dest.clone())? {
                return Ok(());
            }
        }
        if let ("cmp", [other]) = (method, args) {
            if matches!(
                self.tys().tcx().kind(base),
                HK::Adt { .. } | HK::Shared { .. } | HK::Tuple(_)
            ) {
                // A derived `Ord`: field by field.
                let lp = self.expr_place(object, false)?;
                let rp = self.expr_place(&other.value, false)?;
                let (lp, lt) = self.strip_refs(lp);
                let (rp, _) = self.strip_refs(rp);
                return self.cmp_places(e.span, lp, rp, lt, dest);
            }
        }
        // `a.lt(b)` on a scalar or a string: the operator, as `i64.lt(a, b)`
        // is.
        if let [other] = args {
            let op = match method {
                "eq" => Some(AstBinOp::Eq),
                "ne" => Some(AstBinOp::NotEq),
                "lt" => Some(AstBinOp::Lt),
                "le" => Some(AstBinOp::LtEq),
                "gt" => Some(AstBinOp::Gt),
                "ge" => Some(AstBinOp::GtEq),
                _ => None,
            };
            let scalar = matches!(
                self.tys().tcx().kind(base),
                HK::Int(_) | HK::UInt(_) | HK::Char | HK::Bool | HK::Str | HK::StaticStr
            ) || self.tys().display(base) == "String";
            if let (Some(op), true) = (op, scalar) {
                return self.binary(op, object, &other.value, dest);
            }
            // `a.add(b)`, `a.shl(2)` on a number: the operator, `a + b`
            // (B-2026-10-28-19).
            let number = matches!(
                self.tys().tcx().kind(base),
                HK::Int(_) | HK::UInt(_) | HK::Float(_)
            );
            if let (Some(op), true) = (operator_method(method), number) {
                return self.binary(op, object, &other.value, dest);
            }
        }
        if args.is_empty() && self.unary_operator_call(method, object, dest.clone())? {
            return Ok(());
        }
        match (key, method) {
            (_, "as_slice" | "as_mut_slice")
                if matches!(
                    self.tys().tcx().kind(base),
                    HK::Array { .. }
                        | HK::Intrinsic {
                            kind: IntrinsicKind::Vec,
                            ..
                        }
                ) =>
            {
                let t = self.expr_ty(e)?;
                let s = self.slice_view(object, None, t, method == "as_mut_slice")?;
                self.assign(dest, Rvalue::Use(Operand::Move(Place::local(s))));
                Ok(())
            }
            (_, "or_insert" | "or_insert_with" | "or_default") if matches!(&object.kind, ExprKind::MethodCall { method: m, .. } if m == "entry") =>
            {
                // `m.entry(k).or_insert(v)` is one call of the map's
                // `entry_or_insert(mut ref m, k, v)`, which returns a
                // `mut ref` to the value.
                let ExprKind::MethodCall {
                    object: map,
                    args: key,
                    ..
                } = &object.kind
                else {
                    unreachable!()
                };
                let mt = self.expr_ty(map)?;
                let (_, mbase) = self.strip_ty_full(mt);
                let recv = self.recv_place(map, true)?;
                let mut rest = Vec::new();
                for a in key.iter().chain(args) {
                    if self.is_fn_typed(a.value.id)
                        || matches!(a.value.kind, ExprKind::Closure { .. })
                    {
                        let (op, _) = self.fn_value(&a.value)?;
                        rest.push(op);
                    } else {
                        rest.push(self.expr_operand(&a.value)?);
                    }
                }
                let mut ops = vec![self.recv_borrow_after(recv, &mut rest)?];
                ops.extend(rest);
                let name = format!("{}.entry_{method}", self.tys().display(mbase));
                self.call_native(&name, ops, dest);
                Ok(())
            }
            (_, "to_string") if matches!(&object.kind, ExprKind::StringLit(_)) => {
                let ExprKind::StringLit(s) = &object.kind else {
                    unreachable!()
                };
                let op = self.static_str(s);
                self.call_native("String.from", vec![op], dest);
                Ok(())
            }
            (_, "to_string") if self.is_copy(base) => {
                let recv = self.expr_operand(object)?;
                let recv = match self.tys().tcx().kind(ot) {
                    HK::Ref(_) | HK::MutRef(_) => {
                        let p = self.expr_place(object, false)?.project(ProjElem::Deref);
                        Operand::Copy(p)
                    }
                    _ => recv,
                };
                let name = format!("{}.to_string", self.tys().display(base));
                self.call_native(&name, vec![recv], dest);
                Ok(())
            }
            (_, "to_string") if matches!(self.tys().tcx().kind(base), HK::Str | HK::StaticStr) => {
                let recv = self.recv_ref(object, false)?;
                self.call_native("String.clone", vec![recv], dest);
                Ok(())
            }
            _ => {
                // Any other library method is a call of the native
                // `<receiver type>.<method>`. A number takes its receiver by
                // value; a collection by `mut ref` when the method writes it,
                // else by `ref`.
                let recv = if self.is_number(base) {
                    let op = self.expr_operand(object)?;
                    PendingRecv::Ready(match self.tys().tcx().kind(ot) {
                        HK::Ref(_) | HK::MutRef(_) => {
                            Operand::Copy(self.expr_place(object, false)?.project(ProjElem::Deref))
                        }
                        _ => op,
                    })
                } else if self.tys().display(base).starts_with("Entry[")
                    && matches!(
                        method,
                        "and_modify" | "or_insert" | "or_insert_with" | "or_default"
                    )
                    || (self.tys().display(base).starts_with("TaskHandle[")
                        && matches!(method, "join" | "try_join"))
                    || {
                        let shown = self.tys().display(base);
                        let head = shown.split('[').next().unwrap_or("").to_string();
                        self.lcx
                            .builtin_own_self
                            .contains(&(head, method.to_string()))
                    }
                {
                    // An `Entry` is consumed by each step of its chain
                    // (docs/library/collections.md), and `join` consumes its
                    // handle.
                    PendingRecv::Ready(self.expr_operand(object)?)
                } else {
                    // `Atomic`, `Mutex` and the library cells write through
                    // a shared borrow (core semantics §6.3).
                    let interior = {
                        let shown = self.tys().display(base);
                        ["Atomic", "Mutex", "Arena", "OnceLock", "OnceCell"]
                            .iter()
                            .any(|c| shown.starts_with(c))
                    };
                    let declared_mut = {
                        let shown = self.tys().display(base);
                        let head = shown.split('[').next().unwrap_or("").to_string();
                        self.lcx
                            .builtin_mut_self
                            .contains(&(head, method.to_string()))
                    };
                    let mutates = !interior
                        && (declared_mut
                            || crate::ast::is_mutating_collection_method(method)
                            || matches!(
                                method,
                                "push_str"
                                    | "set"
                                    | "get_mut_by_view"
                                    | "sort_unstable"
                                    | "sort_unstable_by"
                                    | "entry"
                                    | "drain_entries"
                                    // Its halves hold a mutable loan of the
                                    // sequence (B-2026-10-21-29).
                                    | "split_at_mut"
                            ));
                    self.recv_place(object, mutates)?
                };
                if method == "to_string" {
                    self.queue_nested_displays(base);
                }
                self.queue_key_eq(base);
                let mut rest = Vec::with_capacity(args.len());
                self.hint_lib_args(base, method, args);
                // Stored values and closures move in; other non-Copy
                // arguments (keys, needles, slices, text) are borrowed.
                let stores = stores_argument(method)
                    || (method == "replace" && self.tys().display(base).starts_with("Option["));
                // A library method declared to take an argument `own` keeps it.
                let owns = {
                    let shown = self.tys().display(base);
                    let head = shown.split('[').next().unwrap_or("").to_string();
                    self.lcx
                        .builtin_owns
                        .get(&(head, method.to_string()))
                        .cloned()
                        .unwrap_or_default()
                };
                for (i, a) in args.iter().enumerate() {
                    // Only a library value (a pooled connection, a permit) for
                    // now: the natives that take `own` text still read it
                    // through a borrow and would leak it.
                    // A `Copy` value (an `ArenaRef`) is copied, as any
                    // owned `Copy` argument is.
                    let declared_own = owns.get(i).copied().unwrap_or(false) && {
                        let at = self.expr_ty(&a.value)?;
                        let (_, b) = self.strip_ty_full(at);
                        matches!(self.tys().tcx().kind(b), HK::Adt { .. }) && !self.is_copy(b)
                    };
                    let stores = stores || declared_own;
                    // A function value stored in a collection of `Fn(..)`
                    // (`v.push(w)`) is erased to the element type, as
                    // `vec![w]` erases it (B-2026-10-15-26).
                    let stored_fn = if stores {
                        self.lib_param_tys(base, method)
                            .and_then(|ps| ps.get(i).copied())
                            .filter(|&pt| matches!(self.tys().tcx().kind(pt), HK::Fn { .. }))
                    } else {
                        None
                    };
                    if let Some(pt) = stored_fn {
                        rest.push(self.arg_operand(&a.value, pt)?);
                        continue;
                    }
                    if self.is_fn_typed(a.value.id)
                        || matches!(a.value.kind, ExprKind::Closure { .. })
                    {
                        // A closure or function goes by value; the native
                        // calls it, lending each element by reference.
                        self.closure_ref_params = true;
                        self.closure_key = matches!(
                            method,
                            "sort_by_key"
                                | "sort_unstable_by_key"
                                | "sort_by_cached_key"
                                | "sorted_by_key"
                        );
                        self.closure_task = method == "spawn";
                        let v = self.fn_value(&a.value);
                        self.closure_ref_params = false;
                        self.closure_key = false;
                        self.closure_task = false;
                        let (op, _) = v?;
                        rest.push(op);
                        continue;
                    }
                    let at = self.expr_ty(&a.value)?;
                    if a.mut_marker && self.is_place(&a.value) {
                        // `f.read(mut buf)`: a `mut Slice[T]` / `mut ref T`
                        // parameter lends the place mutably, even a `Copy`
                        // array, so the native writes the caller's elements.
                        let p = self.expr_place(&a.value, true)?;
                        let rt = self.tys().tcx().reference(at, true);
                        let r = self.temp(rt);
                        self.assign(r, Rvalue::Ref(BorrowKind::Mut, p));
                        rest.push(Operand::Move(Place::local(r)));
                        continue;
                    }
                    let callable = matches!(self.tys().tcx().kind(at), HK::Closure { .. });
                    let by_ref = !stores && !callable && !self.is_copy(at);
                    // A number's method reads a `ref` to the same number as
                    // its value: `n.min(m)` with `m: ref i64` (§5.10).
                    if matches!(
                        self.tys().tcx().kind(base),
                        HK::Int(_) | HK::UInt(_) | HK::Float(_)
                    ) && matches!(self.tys().tcx().kind(at), HK::Ref(t) | HK::MutRef(t) if t == base)
                    {
                        rest.push(self.owned_operand(&a.value, base)?);
                        continue;
                    }
                    // Text's char argument (`push`, `find`, `split`) reads
                    // a `ref char` as its value (§5.10; B-2026-10-14-2).
                    if matches!(self.tys().tcx().kind(base), HK::Str | HK::StaticStr) {
                        if let HK::Ref(t) | HK::MutRef(t) = self.tys().tcx().kind(at) {
                            if matches!(self.tys().tcx().kind(t), HK::Char) {
                                rest.push(self.owned_operand(&a.value, t)?);
                                continue;
                            }
                        }
                    }
                    // A `ref` to a `Copy` value or handle that a call
                    // returns (`v.push(m.get(k).unwrap())`), stored into a
                    // container of owned elements, is read through: the
                    // element is the value, not its address (§5.10;
                    // B-2026-10-24-3).
                    if stores && !self.is_place(&a.value) {
                        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(at) {
                            let holds_refs = match self.tys().tcx().kind(base) {
                                HK::Intrinsic { args, .. } => {
                                    self.tys().tcx().list(args).into_iter().any(|t| {
                                        matches!(
                                            self.tys().tcx().kind(t),
                                            HK::Ref(_) | HK::MutRef(_)
                                        )
                                    })
                                }
                                _ => true,
                            };
                            let readable = self.is_copy(inner)
                                || self.is_handle(inner)
                                || self.is_handle_aggregate(inner);
                            if !holds_refs && readable {
                                rest.push(self.owned_operand(&a.value, inner)?);
                                continue;
                            }
                        }
                    }
                    // A borrowed value stored into a container of owned
                    // elements is a move out of the borrow, which the move
                    // check refuses (a container of references stores it).
                    if stores && self.is_place(&a.value) {
                        if let HK::Ref(inner) | HK::MutRef(inner) = self.tys().tcx().kind(at) {
                            let holds_refs = match self.tys().tcx().kind(base) {
                                HK::Intrinsic { args, .. } => {
                                    self.tys().tcx().list(args).into_iter().any(|t| {
                                        matches!(
                                            self.tys().tcx().kind(t),
                                            HK::Ref(_) | HK::MutRef(_)
                                        )
                                    })
                                }
                                _ => true,
                            };
                            if !holds_refs
                                && (self.is_handle(inner) || self.is_handle_aggregate(inner))
                            {
                                // A borrowed handle stored is a counted copy (§6.1).
                                let p = self.expr_place(&a.value, false)?;
                                let l = self.temp(inner);
                                self.count_copy(p.project(ProjElem::Deref), inner, Place::local(l));
                                rest.push(Operand::Move(Place::local(l)));
                                continue;
                            }
                            if !holds_refs {
                                // A `Copy` element is read through the
                                // borrow (`out.push(v)` with `v: ref i64`).
                                let p = self.expr_place(&a.value, false)?.project(ProjElem::Deref);
                                rest.push(match self.is_copy(inner) {
                                    true => Operand::Copy(p),
                                    false => Operand::Move(p),
                                });
                                continue;
                            }
                        }
                    }
                    // An owned place stored into a `ref` slot (`v.push(t)`
                    // on a `Vec[ref Node]`) is lent, not moved (§5.3;
                    // B-2026-10-14-13).
                    if stores
                        && self.is_place(&a.value)
                        && !matches!(self.tys().tcx().kind(at), HK::Ref(_) | HK::MutRef(_))
                    {
                        let slot = self
                            .lib_param_tys(base, method)
                            .and_then(|s| s.get(rest.len()).copied())
                            .filter(|&t| matches!(self.tys().tcx().kind(t), HK::Ref(_)));
                        if let Some(slot) = slot {
                            rest.push(self.operand_at(&a.value, slot)?);
                            continue;
                        }
                    }
                    // A tuple literal stored is built at the slot's types,
                    // reading any `ref` element (§5.10).
                    if let (true, ExprKind::Tuple(_)) = (stores, &a.value.kind) {
                        let slot = self
                            .lib_param_tys(base, method)
                            .and_then(|s| s.get(rest.len()).copied());
                        if let Some(slot) = slot {
                            rest.push(self.operand_at(&a.value, slot)?);
                            continue;
                        }
                    }
                    rest.push(self.lib_arg(&a.value, by_ref)?);
                }
                // A strong handle stored into a `weak` slot is downgraded,
                // and a narrower number widened.
                if let Some(slots) = self.lib_param_tys(base, method).filter(|_| stores) {
                    for (op, t) in rest.iter_mut().zip(slots) {
                        let o = std::mem::replace(op, unit_const(self.unit()));
                        *op = if self.downgrades(&o, t) {
                            self.downgrade(o, t)
                        } else {
                            self.widen(o, t)
                        };
                    }
                }
                let mut ops = vec![self.recv_borrow_after(recv, &mut rest)?];
                ops.extend(rest);
                let name = format!("{}.{method}", self.tys().display(base));
                self.call_native(&name, ops, dest);
                Ok(())
            }
        }
    }
}

/// An operand of a failed `assert_eq` or `assert_ne`: a place the
/// comparison built, or the operand as written (evaluated already).
enum AssertSide<'a> {
    Place(Place, Ty),
    Expr(&'a Expr),
}

/// A method receiver whose borrow is not taken yet: an operand already in
/// hand, or the place to borrow, its type and whether mutably.
enum PendingRecv<'a> {
    Ready(Operand),
    Borrow(Place, Ty, bool),
    /// A receiver reached through a subscript (`nodes[i].kids`): its
    /// subscripts are evaluated, and its place is formed after the
    /// arguments, so the container's borrow starts after them too.
    Deferred(&'a Expr, bool),
}

enum PendingPlace<'a> {
    Plain(&'a Expr),
}

/// Empty every block control cannot reach: the code a builder emits after
/// a `return` or `break` is dead, and need not be well typed (`{ return x; }`
/// as a body still assigns its unit value to the return place).
/// `i64.MAX`, `u8.MIN`, …: the bits of an integer type's limit.
fn int_limit(kind: HK, path: &str) -> Option<u128> {
    let limit = path.rsplit('.').next()?;
    let (bits, signed) = match kind {
        HK::Int(s) => (
            match s {
                IntSize::I8 => 8,
                IntSize::I16 => 16,
                IntSize::I32 => 32,
                IntSize::I128 => 128,
                _ => 64,
            },
            true,
        ),
        HK::UInt(s) => (
            match s {
                UIntSize::U8 => 8,
                UIntSize::U16 => 16,
                UIntSize::U32 => 32,
                UIntSize::U128 => 128,
                _ => 64,
            },
            false,
        ),
        _ => return None,
    };
    let v: i128 = match (limit, signed) {
        ("MAX", true) => (1i128 << (bits - 1)).wrapping_sub(1),
        ("MIN", true) => (-1i128).wrapping_shl(bits - 1),
        ("MAX", false) if bits == 128 => return Some(u128::MAX),
        ("MAX", false) => (1i128 << bits) - 1,
        ("MIN", false) => 0,
        _ => return None,
    };
    Some(v as u128)
}

fn bool_const(t: Ty, b: bool) -> Operand {
    Operand::Const(Const {
        ty: t,
        kind: ConstKind::Scalar(b as u128),
    })
}

fn clear_unreachable_blocks(body: &mut Body) {
    let mut seen = vec![false; body.blocks.len()];
    let mut work = vec![0usize];
    while let Some(b) = work.pop() {
        if std::mem::replace(&mut seen[b], true) {
            continue;
        }
        for s in body.blocks[b].terminator.kind.successors() {
            work.push(s.index());
        }
    }
    for (b, data) in body.blocks.iter_mut().enumerate() {
        if !seen[b] {
            data.statements.clear();
            data.terminator.kind = TerminatorKind::Unreachable;
        }
    }
}

/// The type of `base`'s payload in variant `ok`, or unit.
fn base_payload_or(bx: &Bx<'_, '_>, base: Ty, ok: u32) -> Ty {
    bx.tys()
        .tcx()
        .field_ty(base, Some(ok), 0)
        .unwrap_or_else(|| bx.unit())
}

/// Whether `e` names an existing place rather than producing a value.
/// The `old(e)` calls in a contract condition, outermost first.
fn old_calls<'a>(e: &'a Expr, out: &mut Vec<&'a Expr>) {
    let block = |b: &'a Block, out: &mut Vec<&'a Expr>| {
        for s in &b.stmts {
            if let StmtKind::Expr(x) | StmtKind::Let { value: x, .. } = &s.kind {
                old_calls(x, out);
            }
        }
        if let Some(x) = &b.final_expr {
            old_calls(x, out);
        }
    };
    match &e.kind {
        ExprKind::Call { callee, args } => {
            if matches!(&callee.kind, ExprKind::Identifier(n) if n == "old") {
                out.push(e);
                return;
            }
            old_calls(callee, out);
            for a in args {
                old_calls(&a.value, out);
            }
        }
        ExprKind::MethodCall { object, args, .. } => {
            old_calls(object, out);
            for a in args {
                old_calls(&a.value, out);
            }
        }
        ExprKind::Binary { left, right, .. } | ExprKind::NilCoalesce { left, right } => {
            old_calls(left, out);
            old_calls(right, out);
        }
        ExprKind::Index { object, index } => {
            old_calls(object, out);
            old_calls(index, out);
        }
        ExprKind::Unary { operand: x, .. }
        | ExprKind::FieldAccess { object: x, .. }
        | ExprKind::TupleIndex { object: x, .. } => old_calls(x, out),
        ExprKind::Block(b) => block(b, out),
        ExprKind::If {
            condition,
            then_block,
            else_branch,
        } => {
            old_calls(condition, out);
            block(then_block, out);
            if let Some(x) = else_branch {
                old_calls(x, out);
            }
        }
        _ => {}
    }
}

/// Whether the place `e` names is reached through a subscript.
fn through_index(e: &Expr) -> bool {
    match &e.kind {
        ExprKind::Index { index, .. } => !matches!(index.kind, ExprKind::Range { .. }),
        ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
            through_index(object)
        }
        _ => false,
    }
}

/// `process.exit(code)`, which the checker leaves untyped in statement
/// position.
fn is_process_exit(e: &Expr) -> bool {
    process_exit_args(e).is_some()
}

/// The arguments of `process.exit(..)`, spelled as a path call or as a
/// method call on the module name.
fn process_exit_args(e: &Expr) -> Option<&[CallArg]> {
    match &e.kind {
        ExprKind::Call { callee, args, .. } => {
            matches!(&callee.kind, ExprKind::Path { segments, .. }
            if segments.len() == 2 && segments[0] == "process" && segments[1] == "exit")
            .then_some(args.as_slice())
        }
        ExprKind::MethodCall {
            object,
            method,
            args,
            ..
        } => (method == "exit"
            && matches!(&object.kind, ExprKind::Identifier(n) if n == "process"))
        .then_some(args.as_slice()),
        _ => None,
    }
}

/// Whether a loop body `b` can leave its iteration other than by its end:
/// a `return`, `?`, `break` or `continue` anywhere in it (an auto-par task
/// runs a whole run of iterations, so it takes none).
fn leaves_loop(b: &Block) -> bool {
    let mut leaves = false;
    crate::span_visitor::for_each_expr_in_block(b, &mut |x| {
        leaves |= matches!(
            x.kind,
            ExprKind::Return(_)
                | ExprKind::Question(_)
                | ExprKind::Break { .. }
                | ExprKind::Continue { .. }
        );
    });
    leaves
}

/// Whether `e` holds a `return`, which leaves the enclosing function: a
/// `par` branch with one leaves its task with the function's value
/// (`Bx::par_tasks`). A `return` inside a closure in it is counted too,
/// which only costs that `par` the wrapping.
fn returns_from_fn(e: &Expr) -> bool {
    let mut found = false;
    crate::span_visitor::for_each_expr(e, &mut |x| {
        found |= matches!(x.kind, ExprKind::Return(_));
    });
    found
}

/// Whether a release build asked for this debug-only machinery to go:
/// `KARAC_STRIP_DBG` (`dbg()`), `KARAC_STRIP_CONTRACTS` (contracts) or
/// `KARAC_STRIP_ERROR_TRACE` (the error return trace), each `1` or `true`.
/// `karac build --release` sets all three.
fn release_strips(var: &str) -> bool {
    matches!(std::env::var(var).as_deref(), Ok("1" | "true"))
}

fn is_place_expr(e: &Expr) -> bool {
    match &e.kind {
        ExprKind::Identifier(_) | ExprKind::SelfValue => true,
        ExprKind::FieldAccess { object, .. } | ExprKind::TupleIndex { object, .. } => {
            is_place_expr(object)
        }
        ExprKind::Unary {
            op: UnaryOp::Deref, ..
        } => true,
        _ => false,
    }
}

fn unit_const(unit: Ty) -> Operand {
    Operand::Const(Const {
        ty: unit,
        kind: ConstKind::Unit,
    })
}

/// Check one source file, build its MIR, elaborate drops and run `main`
/// on the MIR interpreter; or the first stage that refused it.
pub fn run_source(src: &str) -> Result<interp::RunResult, String> {
    let lowered = build_source(src)?.for_this_pool();
    par_check(&lowered)?;
    Ok(interp::run_untraced(
        &lowered.program,
        &lowered.tys,
        "main",
        vec![],
    ))
}

/// Every body of `program` passes the MIR validator, or the problems it
/// names, in the interpreter's `invalid MIR:` form. The interpreter
/// validates before it runs; the compiled entry points call this through
/// [`compiled_check`] so a lowering bug reads the same on every MIR backend
/// instead of reaching LLVM (B-2026-10-14-21).
pub fn validate_program(program: &interp::Program, tys: &TyInterner) -> Result<(), String> {
    let mut problems = Vec::new();
    for (name, body) in &program.bodies {
        for e in crate::mir::validate::validate(body, tys) {
            problems.push(format!("{name}: {e}"));
        }
    }
    if problems.is_empty() {
        Ok(())
    } else {
        Err(format!("invalid MIR:\n{}", problems.join("\n")))
    }
}

/// What a compiled entry point (`__mir-llvm-run`, `__mir-llvm-asan`,
/// `karac build --mir`) checks before codegen: [`par_check`], then
/// [`validate_program`].
pub fn compiled_check(lowered: &Lowered) -> Result<(), String> {
    par_check(lowered)?;
    validate_program(&lowered.program, &lowered.tys)
}

/// Core §11.2: conflicting `par` branches are a compile error.
/// `KARAC_MIR_EFFECTS=0` skips the check.
pub fn par_check(lowered: &Lowered) -> Result<(), String> {
    let has_par = lowered
        .program
        .bodies
        .values()
        .any(|b| !b.par_regions.is_empty());
    // A program with a resource to bind is checked for a call with no
    // provider (core semantics §14.6, B-2026-10-20-7).
    let has_resources = !lowered.program.resources.is_empty();
    if (has_par || has_resources) && std::env::var("KARAC_MIR_EFFECTS").as_deref() != Ok("0") {
        let fresh;
        let report = match &lowered.effects {
            Some(r) => r,
            None => {
                fresh = crate::mir::effects::analyze(&lowered.program, &lowered.tys);
                &fresh
            }
        };
        if let Some((name, c)) = par_conflict(report) {
            return Err(format!(
                "effects: in `{name}` at line {}, {}",
                c.line,
                par_conflict_text(c)
            ));
        }
        if let Some(n) = report.no_provider.first() {
            return Err(format!(
                "effects: in `{}` at line {}, {}",
                n.instance,
                n.span.line,
                no_provider_text(&n.resource)
            ));
        }
        if let Some((n, callee)) = report.stateful_default.first() {
            return Err(format!(
                "effects: in `{}` at line {}, {}",
                n.instance,
                n.span.line,
                stateful_default_text(&n.resource, callee)
            ));
        }
    }
    Ok(())
}

/// The first conflicting `par` region `report` found, with its body.
fn par_conflict(
    report: &crate::mir::effects::EffectReport,
) -> Option<(&String, &crate::mir::effects::ParConflict)> {
    report
        .par_conflicts
        .iter()
        .find_map(|(n, v)| v.first().map(|c| (n, c)))
}

/// The message for a call of `callee` that writes `resource`, whose default
/// has state, outside every override (core semantics §14.14).
pub fn stateful_default_text(resource: &str, callee: &str) -> String {
    let what = match callee.strip_prefix(&format!("{resource}.")) {
        Some(m) => format!("`{resource}.{m}` takes `mut ref self`"),
        None => format!("`{callee}` calls a `mut ref self` method of `{resource}`"),
    };
    format!(
        "{what}, but `{resource}`'s default has fields, so outside an override the call \
         would write a global every task shares (E_STATEFUL_DEFAULT, core semantics \
         §14.14): make the method take `self`, or run the call inside \
         `with_provider[{resource}](provider, || ...)`"
    )
}

/// The message for a call that needs `resource`'s provider where nothing
/// supplies it (core semantics §14.6).
pub fn no_provider_text(resource: &str) -> String {
    format!(
        "no provider for `{resource}`: this needs one and nothing supplies it, since `main` \
         takes no hidden provider parameter (core semantics §14.6); run it inside \
         `with_provider[{resource}](provider, || ...)`"
    )
}

/// What conflicts in `c`, for a message: "branches 1 and 2 of the `par`
/// conflict: `x` and `y`".
fn par_conflict_text(c: &crate::mir::effects::ParConflict) -> String {
    let which = if c.branches.0 == c.branches.1 {
        "two iterations of the `par for`".to_string()
    } else {
        format!(
            "branches {} and {} of the `par`",
            c.branches.0 + 1,
            c.branches.1 + 1
        )
    };
    format!("{which} conflict: `{}` and `{}`", c.first.1, c.second.1)
}

/// Which rule a [`source_effect_errors`] finding breaks.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum SourceEffectError {
    /// Two branches of a `par` conflict (core semantics §11.2).
    Par,
    /// A call needs a provider nothing supplies (§14.6).
    NoProvider,
    /// A call writes a resource whose default has state (§14.14).
    StatefulDefault,
}

/// `karac check`'s run of [`par_check`] (B-2026-10-19-39, B-2026-10-20-7):
/// the conflicting `par` regions and the calls with no provider in the
/// program's own text, as the build finds them, each with its line and
/// column, its kind and the message. A program with neither `par` nor
/// `effect resource` in its text, or one the builder stops on, gives none.
/// `KARAC_MIR_EFFECTS=0` skips it, as it does for a run.
pub fn source_effect_errors(src: &str) -> Vec<((usize, usize), SourceEffectError, String)> {
    if std::env::var("KARAC_MIR_EFFECTS").as_deref() == Ok("0")
        || !(mentions_par(src) || src.contains("effect resource"))
    {
        return Vec::new();
    }
    let Ok(lowered) = build_source(src) else {
        return Vec::new();
    };
    let user_lines = src.lines().count();
    let report = match lowered.effects {
        Some(r) => r,
        None => crate::mir::effects::analyze(&lowered.program, &lowered.tys),
    };
    let mut out: Vec<((usize, usize), SourceEffectError, String)> = Vec::new();
    let mut add = |span: crate::token::Span, kind, text: String| {
        let at = (span.line, span.column);
        if span.line == 0
            || span.line > user_lines
            || out.iter().any(|(a, k, _)| *a == at && *k == kind)
        {
            return;
        }
        out.push((at, kind, text));
    };
    for (name, found) in &report.par_conflicts {
        let body = &lowered.program.bodies[name];
        for c in found {
            add(
                body.par_regions[c.region].span,
                SourceEffectError::Par,
                par_conflict_text(c),
            );
        }
    }
    for n in &report.no_provider {
        add(
            n.span,
            SourceEffectError::NoProvider,
            no_provider_text(&n.resource),
        );
    }
    for (n, callee) in &report.stateful_default {
        add(
            n.span,
            SourceEffectError::StatefulDefault,
            stateful_default_text(&n.resource, callee),
        );
    }
    out.sort();
    out
}

/// Does `src` have the word `par` followed by `{` or `for`? A cheap test
/// that keeps a program with no `par` from being built twice by check.
fn mentions_par(src: &str) -> bool {
    let b = src.as_bytes();
    let ident = |c: u8| c.is_ascii_alphanumeric() || c == b'_';
    src.match_indices("par").any(|(i, _)| {
        if i > 0 && ident(b[i - 1]) {
            return false;
        }
        let rest = src[i + 3..].trim_start();
        rest.starts_with('{')
            || (rest.starts_with("for")
                && !rest[3..].starts_with(|c: char| c.is_alphanumeric() || c == '_'))
    })
}

/// [`run_source`], writing the program's output to the process's stdout
/// and stderr as it runs (`karac __mir-run`).
pub fn run_source_streaming(src: &str) -> Result<interp::RunResult, String> {
    let lowered = build_source(src)?.for_this_pool();
    par_check(&lowered)?;
    Ok(interp::run_streaming(
        &lowered.program,
        &lowered.tys,
        "main",
        vec![],
    ))
}

/// Baked library modules appended to a program that names one of their
/// words, with the names that make a program's own declaration of one
